static thread_local std::string* g_gpu_init_log_sink = nullptr;

static int init_log_vappend(FILE* stream, const char* format, va_list args) {
    if (g_gpu_init_log_sink == nullptr) {
        return std::vfprintf(stream, format, args);
    }

    va_list size_args;
    va_copy(size_args, args);
    const int count = std::vsnprintf(nullptr, 0, format, size_args);
    va_end(size_args);
    if (count <= 0) {
        return count;
    }

    std::vector<char> buffer(static_cast<size_t>(count) + 1u);
    std::vsnprintf(buffer.data(), buffer.size(), format, args);
    g_gpu_init_log_sink->append(buffer.data(), static_cast<size_t>(count));
    return count;
}

static int init_log_printf(const char* format, ...) {
    va_list args;
    va_start(args, format);
    const int count = init_log_vappend(stdout, format, args);
    va_end(args);
    return count;
}

static int init_log_fprintf(FILE* stream, const char* format, ...) {
    va_list args;
    va_start(args, format);
    const int count = init_log_vappend(stream, format, args);
    va_end(args);
    return count;
}

