static uint64_t xp_randstorm_mileage_count_host()
{
    return (xp_randstorm_mileage_end >= xp_randstorm_mileage_start)
        ? (static_cast<uint64_t>(xp_randstorm_mileage_end) - static_cast<uint64_t>(xp_randstorm_mileage_start) + 1ull)
        : 0ull;
}

static bool xp_randstorm_mileage_active()
{
    return xp_randstorm_mileage_start != 0u || xp_randstorm_mileage_end != 0u;
}

static bool xp_randstorm_mileage_arg_seen()
{
    return xp_randstorm_mileage_start_seen || xp_randstorm_mileage_end_seen;
}

static uint32_t xp_randstorm_seed_event_count_host()
{
    return xp_randstorm_seed_events & XP_RANDSTORM_SEED_EVENTS_COUNT_MASK;
}

static bool xp_randstorm_seed_events_repeat_host()
{
    return (xp_randstorm_seed_events & XP_RANDSTORM_SEED_EVENTS_REPEAT_FLAG) != 0u;
}

