void scanDir(const std::string& directoryPath, std::vector<std::string>& mnemonicFiles) {
    std::vector<MacDirectoryEntry> entries;
    if (!mac_list_directory(directoryPath, entries)) {
        return;
    }

    for (const MacDirectoryEntry& entry : entries) {
        if (entry.kind == MacPathKind::Directory) {
            scanDir(entry.path, mnemonicFiles);
        }
        else if (all_file || (entry.name.size() > 4 && entry.name.substr(entry.name.size() - 4) == ".txt")) {
            mnemonicFiles.push_back(entry.path);
            std::cout << "File '" << entry.path << "' added to list." << std::endl;
        }
    }
}
static const unsigned char unhex_tab_host[80] = {
  0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0xaa, 0xbb, 0xcc, 0xdd, 0xee,
  0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static inline unsigned char*
unhex_host(unsigned char* str, size_t str_sz,
    unsigned char* unhexed, size_t unhexed_sz) {
    int i, j;
    for (i = j = 0; i < str_sz && j < unhexed_sz; i += 2, ++j) {
        unhexed[j] = (unhex_tab_host[str[i + 0] & 0x4f] & 0xf0) |
            (unhex_tab_host[str[i + 1] & 0x4f] & 0x0f);
    }
    return unhexed;
}

unsigned char*
hex(unsigned char* buf, size_t buf_sz,
    unsigned char* hexed, size_t hexed_sz) {
    int i, j;
    --hexed_sz;
    for (i = j = 0; i < buf_sz && j < hexed_sz; ++i, j += 2) {
        snprintf((char*)hexed + j, 3, "%02x", buf[i]);
    }
    hexed[j] = 0; // null terminate
    return hexed;
}

// hex_nibble_value: converts nibble value.
static inline int hex_nibble_value(const char c) {
    if (c >= '0' && c <= '9') return (int)(c - '0');
    const char cl = (char)(c | 0x20);
    if (cl >= 'a' && cl <= 'f') return (int)(cl - 'a' + 10);
    return -1;
}

static inline bool parse_hash_target_argument(
    const char* arg,
    uint32_t out_words[8],
    uint32_t out_masks[8],
    uint32_t& out_len_bytes,
    std::string& out_hex,
    std::string& err) {

    if (arg == nullptr) {
        err = "value is missing";
        return false;
    }

    std::string s(arg);
    if (s.size() >= 2 && s[0] == '0' && ((s[1] | 0x20) == 'x')) {
        s.erase(0, 2);
    }

    if (s.empty()) {
        err = "value is empty";
        return false;
    }
    if ((s.size() & 1u) != 0u) {
        err = "hex length must be even";
        return false;
    }
    if (s.size() < 4u || s.size() > 64u) {
        err = "expects 2..32 bytes (4..64 hex chars)";
        return false;
    }
    for (const char ch : s) {
        if (!std::isxdigit(static_cast<unsigned char>(ch))) {
            err = "contains non-hex characters";
            return false;
        }
    }

    uint8_t bytes[32] = { 0 };
    const size_t len_bytes = s.size() / 2u;
    for (size_t i = 0; i < len_bytes; ++i) {
        const int hi = hex_nibble_value(s[i * 2]);
        const int lo = hex_nibble_value(s[i * 2 + 1]);
        if (hi < 0 || lo < 0) {
            err = "contains non-hex characters";
            return false;
        }
        bytes[i] = static_cast<uint8_t>((hi << 4) | lo);
    }

    memset(out_words, 0, sizeof(uint32_t) * 8);
    memcpy(out_words, bytes, len_bytes);

    for (size_t w = 0; w < 8; ++w) {
        const size_t word_start = w * 4u;
        if (word_start >= len_bytes) {
            out_masks[w] = 0u;
            continue;
        }
        const size_t remain = len_bytes - word_start;
        if (remain >= 4u) {
            out_masks[w] = 0xFFFFFFFFu;
        }
        else {
            out_masks[w] = (1u << (remain * 8u)) - 1u;
        }
    }

    out_len_bytes = static_cast<uint32_t>(len_bytes);
    out_hex = s;
    std::transform(out_hex.begin(), out_hex.end(), out_hex.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    return true;
}

// normalize_priv_start_from_zero: secp256k1 private key cannot be zero, normalize start to 1.
static inline bool normalize_priv_start_from_zero(uint8_t* key32) {
    if (key32 == nullptr) {
        return false;
    }
    bool is_zero = true;
    for (int i = 0; i < 32; ++i) {
        if (key32[i] != 0u) {
            is_zero = false;
            break;
        }
    }
    if (!is_zero) {
        return false;
    }
    memset(key32, 0, 32);
    key32[31] = 1u;
    return true;
}

// ensure_password_device_capacity: ensures password device capacity.
static inline metalError_t ensure_password_device_capacity(size_t bytes) {
    if (bytes == 0) {
        bytes = 1;
    }
    if (passwords_dev == nullptr || passwords_dev_capacity < bytes) {
        char* new_buffer = nullptr;
        metalError_t st = metalMalloc((void**)&new_buffer, bytes);
        if (st != metalSuccess) {
            return st;
        }
        if (passwords_dev != nullptr) {
            metalFree(passwords_dev);
        }
        passwords_dev = new_buffer;
        passwords_dev_capacity = bytes;
    }
    return metalSuccess;
}

// copy_password_to_device: copies password to device.
static inline metalError_t copy_password_to_device(const void* src, size_t bytes) {
    metalError_t st = ensure_password_device_capacity(bytes);
    if (st != metalSuccess) {
        return st;
    }
    if (bytes == 0) {
        return metalSuccess;
    }
    return metalMemcpyAsync(passwords_dev, src, bytes, metalMemcpyHostToDevice);
}

thread_local static std::unordered_map<void**, size_t> g_device_buffer_capacities;

// ensure_device_buffer_capacity: ensures device buffer capacity.
static inline metalError_t ensure_device_buffer_capacity(void** device_ptr, size_t bytes) {
    if (bytes == 0) {
        bytes = 1;
    }

    size_t& capacity = g_device_buffer_capacities[device_ptr];
    if (*device_ptr == nullptr || capacity < bytes) {
        void* new_buffer = nullptr;
        metalError_t st = metalMalloc(&new_buffer, bytes);
        if (st != metalSuccess) {
            return st;
        }
        if (*device_ptr != nullptr) {
            metalFree(*device_ptr);
        }
        *device_ptr = new_buffer;
        capacity = bytes;
    }
    return metalSuccess;
}

// copy_to_device_grow: copies to device grow.
static inline metalError_t copy_to_device_grow(void** device_ptr, const void* src, size_t bytes) {
    metalError_t st = ensure_device_buffer_capacity(device_ptr, bytes);
    if (st != metalSuccess) {
        return st;
    }
    if (bytes == 0) {
        return metalSuccess;
    }
    return metalMemcpyAsync(*device_ptr, src, bytes, metalMemcpyHostToDevice);
}

// trim_crlf_inplace: trims crlf inplace.
static inline void trim_crlf_inplace(std::string& line) {
    if (!line.empty() && line.back() == '\r') {
        line.pop_back();
    }
}

// truncate_inplace: truncates inplace.
static inline void truncate_inplace(std::string& line, const size_t max_len) {
    if (line.size() > max_len) {
        line.resize(max_len);
    }
}

static constexpr char kCryptedLinePrefix[] = "CRYPTED:";
static constexpr std::array<uint8_t, 32> kCryptedPhraseKey = {
    0x1f, 0x4d, 0x8b, 0xe2, 0xc7, 0x39, 0x5a, 0x10,
    0x6e, 0xa4, 0xd1, 0x9c, 0x02, 0xb7, 0xf0, 0x68,
