static inline bool has_generic_derivation_targets() {
    return has_secp_output_targets() || has_ed_output_targets();
}

static uint8_t infer_derivation_type_mask() {
    uint8_t mask = derivation_type_mask_host;
    if (derivation_type_explicit) {
        return mask;
    }
    if (has_secp_derivation_targets()) {
        mask |= DERIVATION_TYPE_MASK_BIP32;
    }
    if (has_slip0010_derivation_targets()) {
        mask |= DERIVATION_TYPE_MASK_SLIP0010;
    }
    if (Ada) {
        mask |= DERIVATION_TYPE_MASK_BIP32_ED25519;
    }
    return mask;
}

static inline bool derivation_type_enabled(uint8_t bit) {
    return (derivation_type_mask_host & bit) != 0;
}

