// acquire_shared_result_buffers: acquires shared result buffers.
static inline metalError_t acquire_shared_result_buffers(const uint64_t output_entries, bool** out_is_result, bool** out_device_result) {
    if (out_is_result == nullptr || out_device_result == nullptr) {
        return metalErrorInvalidValue;
    }
    if (shared_result_flag == nullptr || shared_result_buffer == nullptr) {
        return metalErrorInvalidDevicePointer;
    }
    if (output_entries > shared_result_buffer_capacity) {
        return metalErrorInvalidValue;
    }

    *out_is_result = shared_result_flag;
    *out_device_result = shared_result_buffer;

    metalError_t st = metalMemset(shared_result_flag, 0, sizeof(bool));
    if (st != metalSuccess) {
        return st;
    }
    if (output_entries > 0) {
        st = metalMemset(shared_result_buffer, 0, static_cast<size_t>(output_entries) * sizeof(bool));
        if (st != metalSuccess) {
            return st;
        }
    }
    return metalSuccess;
}

static std::mutex g_result_flag_host_access_mutex;

// read_result_flag_host: reads result flag host.
static inline bool read_result_flag_host(bool* flag_ptr) {
    if (flag_ptr == nullptr) {
        return false;
    }
    std::lock_guard<std::mutex> lock(g_result_flag_host_access_mutex);
    bool host_value = false;
    const metalError_t st = metalMemcpy(&host_value, flag_ptr, sizeof(bool), metalMemcpyDeviceToHost);
    if (st != metalSuccess) {
        return false;
    }
    return host_value;
}

// clear_result_flag_host: clears result flag host.
static inline void clear_result_flag_host(bool* flag_ptr) {
    if (flag_ptr == nullptr) {
        return;
    }
    std::lock_guard<std::mutex> lock(g_result_flag_host_access_mutex);
    metalMemset(flag_ptr, 0, sizeof(bool));
}

// allocate_result_buffers_device: allocates result buffers device.
static inline metalError_t allocate_result_buffers_device(const uint64_t output_entries, bool** out_is_result, bool** out_device_result) {
    if (out_is_result == nullptr || out_device_result == nullptr) {
        return metalErrorInvalidValue;
    }
    *out_is_result = nullptr;
    *out_device_result = nullptr;

    metalError_t st = metalMalloc(reinterpret_cast<void**>(out_is_result), sizeof(bool));
    if (st != metalSuccess || *out_is_result == nullptr) {
        return (st != metalSuccess) ? st : metalErrorMemoryAllocation;
    }
    st = metalMemset(*out_is_result, 0, sizeof(bool));
    if (st != metalSuccess) {
        metalFree(*out_is_result);
        *out_is_result = nullptr;
        return st;
    }

    if (output_entries == 0) {
        return metalSuccess;
    }
    if (output_entries > (std::numeric_limits<size_t>::max() / sizeof(bool))) {
        metalFree(*out_is_result);
        *out_is_result = nullptr;
        return metalErrorInvalidValue;
    }

    const size_t bytes = static_cast<size_t>(output_entries) * sizeof(bool);
    st = metalMalloc(reinterpret_cast<void**>(out_device_result), bytes);
    if (st != metalSuccess || *out_device_result == nullptr) {
        metalFree(*out_is_result);
        *out_is_result = nullptr;
        return (st != metalSuccess) ? st : metalErrorMemoryAllocation;
    }
    st = metalMemset(*out_device_result, 0, bytes);
    if (st != metalSuccess) {
        metalFree(*out_device_result);
        metalFree(*out_is_result);
        *out_device_result = nullptr;
        *out_is_result = nullptr;
        return st;
    }
    return metalSuccess;
}

// fetch_and_clear_result_flag: fetches and clear result flag.
static inline metalError_t fetch_and_clear_result_flag(bool* device_flag, bool& out_has_result) {
    out_has_result = false;
    if (device_flag == nullptr) {
        return metalErrorInvalidDevicePointer;
    }
    metalError_t st = metalMemcpy(&out_has_result, device_flag, sizeof(bool), metalMemcpyDeviceToHost);
    if (st != metalSuccess) {
        return st;
    }
    if (out_has_result) {
        const bool zero = false;
        st = metalMemcpy(device_flag, &zero, sizeof(bool), metalMemcpyHostToDevice);
        if (st != metalSuccess) {
            return st;
        }
    }
    return metalSuccess;
}

class BufferedIfstream final {
public:
    explicit BufferedIfstream(const size_t buffer_bytes = (4u << 20))
// BufferedIfstream: constructs file reader with a reusable custom buffer.
        : buffer_(buffer_bytes) {
        stream_.rdbuf()->pubsetbuf(buffer_.data(), static_cast<std::streamsize>(buffer_.size()));
    }

// open: opens a file in binary mode and resets stream state before reuse.
    bool open(const std::string& path) {
        if (stream_.is_open()) {
            stream_.clear();
            stream_.close();
        }
        stream_.open(path.c_str(), std::ios::binary);
        return stream_.is_open();
    }

    std::ifstream& stream() { return stream_; }

private:
    std::ifstream stream_;
    std::vector<char> buffer_;
};

thread_local static std::unordered_map<std::string, std::unique_ptr<BufferedIfstream>> g_password_stream_cache;
thread_local static std::unordered_set<std::string> g_password_stream_open_failed;

// reset_password_stream_cache: resets password stream cache.
static inline void reset_password_stream_cache() {
    g_password_stream_cache.clear();
    g_password_stream_open_failed.clear();
}

// acquire_password_stream_for_rewind: acquires password stream for rewind.
static inline std::ifstream* acquire_password_stream_for_rewind(const std::string& path) {
    if (g_password_stream_open_failed.find(path) != g_password_stream_open_failed.end()) {
        return nullptr;
    }

    auto it = g_password_stream_cache.find(path);
    if (it == g_password_stream_cache.end()) {
        auto stream_holder = std::make_unique<BufferedIfstream>(1u << 20);
        if (!stream_holder->open(path)) {
            std::cout << "Error: Failed to open password file '" << path << "'\n";
            g_password_stream_open_failed.insert(path);
            return nullptr;
        }
        it = g_password_stream_cache.emplace(path, std::move(stream_holder)).first;
    }

    std::ifstream& stream = it->second->stream();
    stream.clear();
    stream.seekg(0, std::ios::beg);
    if (!stream.good()) {
        if (!it->second->open(path)) {
            std::cout << "Error: Failed to open password file '" << path << "'\n";
            g_password_stream_open_failed.insert(path);
            g_password_stream_cache.erase(it);
            return nullptr;
        }
    }

    return &stream;
}

// parse_int32_token: parses int 32 token.
static inline bool parse_int32_token(const std::string& src, size_t begin, size_t end, int32_t& out) {
    while (begin < end && std::isspace(static_cast<unsigned char>(src[begin]))) {
        ++begin;
    }
    while (end > begin && std::isspace(static_cast<unsigned char>(src[end - 1]))) {
        --end;
    }
    if (begin >= end) {
        return false;
    }
    const std::string token = src.substr(begin, end - begin);
    char* end_ptr = nullptr;
    const long parsed = std::strtol(token.c_str(), &end_ptr, 10);
    if (end_ptr == token.c_str() || *end_ptr != '\0') {
        return false;
    }
    if (parsed < std::numeric_limits<int32_t>::min() || parsed > std::numeric_limits<int32_t>::max()) {
        return false;
    }
    out = static_cast<int32_t>(parsed);
    return true;
}

template <typename T>
// parse_list_or_ranges: parses list or ranges.
static inline bool parse_list_or_ranges(const std::string& input, std::vector<T>& out, const bool clear_out = false) {
    if (clear_out) {
        out.clear();
    }
    size_t token_begin = 0;
    while (token_begin <= input.size()) {
        const size_t comma = input.find(',', token_begin);
        const size_t token_end = (comma == std::string::npos) ? input.size() : comma;
        if (token_end > token_begin) {
            size_t dash = std::string::npos;
            for (size_t i = token_begin; i < token_end; ++i) {
                if (input[i] == '-') {
                    dash = i;
                    break;
                }
            }
            if (dash != std::string::npos) {
                int32_t start = 0;
                int32_t end = 0;
                if (!parse_int32_token(input, token_begin, dash, start) || !parse_int32_token(input, dash + 1, token_end, end)) {
                    std::cerr << "Invalid range token: " << input.substr(token_begin, token_end - token_begin) << std::endl;
                }
                else if (start > end) {
                    std::cerr << "Invalid range: " << input.substr(token_begin, token_end - token_begin) << std::endl;
                }
                else {
                    for (int32_t v = start; v <= end; ++v) {
                        out.emplace_back(static_cast<T>(v));
                    }
                }
            }
            else {
                int32_t value = 0;
                if (!parse_int32_token(input, token_begin, token_end, value)) {
                    std::cerr << "Invalid value token: " << input.substr(token_begin, token_end - token_begin) << std::endl;
                }
                else {
                    out.emplace_back(static_cast<T>(value));
                }
            }
        }
        if (comma == std::string::npos) {
            break;
        }
        token_begin = comma + 1;
    }
    return true;
}

static inline bool parse_type_mask_list(const char* raw, const uint32_t min_value, const uint32_t max_value, uint32_t& out_mask, const char* flag_name) {
    if (raw == nullptr || *raw == '\0' || min_value == 0u || max_value < min_value || max_value - min_value >= 31u) {
        std::cerr << "[!] Invalid value for " << flag_name << ". [!]" << std::endl;
        return false;
    }

    uint32_t mask = 0;
    const std::string input(raw);
    size_t token_begin = 0;
    while (token_begin <= input.size()) {
        const size_t comma = input.find(',', token_begin);
        const size_t token_end = (comma == std::string::npos) ? input.size() : comma;
        if (token_end == token_begin) {
            std::cerr << "[!] Empty token in " << flag_name << ". [!]" << std::endl;
            return false;
        }

        size_t dash = std::string::npos;
        for (size_t i = token_begin; i < token_end; ++i) {
            if (input[i] == '-') {
                dash = i;
                break;
            }
        }

        int32_t start = 0;
        int32_t end = 0;
        if (dash == std::string::npos) {
            if (!parse_int32_token(input, token_begin, token_end, start)) {
                std::cerr << "[!] Invalid token '" << input.substr(token_begin, token_end - token_begin) << "' for " << flag_name << ". [!]" << std::endl;
                return false;
            }
            end = start;
        }
        else {
            if (!parse_int32_token(input, token_begin, dash, start) || !parse_int32_token(input, dash + 1, token_end, end) || start > end) {
                std::cerr << "[!] Invalid range '" << input.substr(token_begin, token_end - token_begin) << "' for " << flag_name << ". [!]" << std::endl;
                return false;
            }
        }

        if (start < static_cast<int32_t>(min_value) || end > static_cast<int32_t>(max_value)) {
            std::cerr << "[!] " << flag_name << " supports values " << min_value << ".." << max_value << ". [!]" << std::endl;
            return false;
        }
        for (int32_t v = start; v <= end; ++v) {
            mask |= (1u << (static_cast<uint32_t>(v) - min_value));
        }

        if (comma == std::string::npos) {
            break;
        }
        token_begin = comma + 1;
    }

    if (mask == 0u) {
        std::cerr << "[!] Empty type mask for " << flag_name << ". [!]" << std::endl;
        return false;
    }
    out_mask = mask;
    return true;
}

static inline uint32_t count_bits_u32(uint32_t v) {
    uint32_t count = 0;
    while (v != 0u) {
        count += v & 1u;
        v >>= 1u;
    }
    return count;
}

static inline int active_target_count_for_stats() {
    int count = 0;
    count += Compressed ? 1 : 0;
    count += Uncompressed ? 1 : 0;
    count += Segwit ? 1 : 0;
    count += P2wsh ? 1 : 0;
    count += Taproot ? 1 : 0;
    count += Ethereum ? 1 : 0;
    count += Xpoint ? 1 : 0;
    count += Solana ? 1 : 0;
    count += Dot ? static_cast<int>(count_bits_u32(g_dot_type_mask)) : 0;
    count += (Ton || Ton_all) ? static_cast<int>(count_bits_u32(g_ton_type_mask)) : 0;
    count += Xrp ? static_cast<int>(count_bits_u32(g_xrp_type_mask)) : 0;
    count += Aptos ? static_cast<int>(count_bits_u32(g_aptos_type_mask)) : 0;
    count += Sui ? static_cast<int>(count_bits_u32(g_sui_type_mask)) : 0;
    count += Iota ? static_cast<int>(count_bits_u32(g_iota_type_mask)) : 0;
    count += Ada ? static_cast<int>(count_bits_u32(g_ada_type_mask)) : 0;
    count += Icp ? static_cast<int>(count_bits_u32(g_icp_type_mask)) : 0;
    count += Xtz ? static_cast<int>(count_bits_u32(g_xtz_type_mask)) : 0;
    count += Fil ? static_cast<int>(count_bits_u32(g_fil_type_mask)) : 0;
    return count;
}

// parse_priv_pattern_lengths: parses -pb list/ranges for -priv 6 mode.
static inline bool parse_priv_pattern_lengths(const std::string& input, std::vector<int>& out_lengths) {
    out_lengths.clear();

    auto push_unique_checked = [&](int32_t v) -> bool {
        if (v < 1 || v > 64) {
            return false;
        }
        const int vv = static_cast<int>(v);
        if (std::find(out_lengths.begin(), out_lengths.end(), vv) == out_lengths.end()) {
            out_lengths.push_back(vv);
        }
        return true;
    };

    size_t token_begin = 0;
    while (token_begin <= input.size()) {
        const size_t comma = input.find(',', token_begin);
        const size_t token_end = (comma == std::string::npos) ? input.size() : comma;
        if (token_end == token_begin) {
            return false;
        }

        size_t dash = std::string::npos;
        for (size_t i = token_begin; i < token_end; ++i) {
            if (input[i] == '-') {
                if (dash != std::string::npos) {
                    return false;
                }
                dash = i;
            }
        }

        if (dash != std::string::npos) {
            int32_t start = 0;
            int32_t end = 0;
            if (!parse_int32_token(input, token_begin, dash, start) ||
                !parse_int32_token(input, dash + 1, token_end, end)) {
                return false;
            }
            if (start > end) {
                return false;
            }
            for (int32_t v = start; v <= end; ++v) {
                if (!push_unique_checked(v)) {
                    return false;
                }
            }
        }
        else {
            int32_t value = 0;
            if (!parse_int32_token(input, token_begin, token_end, value)) {
                return false;
            }
            if (!push_unique_checked(value)) {
                return false;
            }
        }

        if (comma == std::string::npos) {
            break;
        }
        token_begin = comma + 1;
    }

    return !out_lengths.empty();
}

// try_get_file_size: tries to get file size.
static inline bool try_get_file_size(const std::string& path, uint64_t& out_bytes) {
    std::ifstream probe(path.c_str(), std::ios::binary | std::ios::ate);
    if (!probe.is_open()) {
        return false;
    }
    const std::streamoff pos = probe.tellg();
    if (pos < 0) {
        return false;
    }
    out_bytes = static_cast<uint64_t>(pos);
    return true;
}

static inline uint64_t sum_existing_file_sizes(const std::vector<std::string>& files) {
    uint64_t total = 0;
    for (const std::string& path : files) {
        uint64_t bytes = 0;
        if (try_get_file_size(path, bytes)) {
            total += bytes;
        }
    }
    return total;
}

// preload_password_files_once: preloads password files once.
static inline void preload_password_files_once() {
    static bool initialized = false;
    if (initialized || !pass_set) {
        return;
    }
    initialized = true;
    reset_password_stream_cache();

    if (passwords_files.empty()) {
        for (std::string& p : passwords_list) {
            trim_crlf_inplace(p);
            truncate_inplace(p, 128);
        }
        passwords_lenght.clear();
        passwords_lenght.reserve(passwords_list.size());
        for (const std::string& p : passwords_list) {
            passwords_lenght.emplace_back(static_cast<uint32_t>(p.size()));
        }
        return;
    }

    constexpr uint64_t kCachePerFileLimitBytes = 256ull * 1024ull * 1024ull;
    constexpr uint64_t kCacheTotalLimitBytes = 768ull * 1024ull * 1024ull;

    uint64_t cached_bytes = 0;
    size_t cached_lines = 0;
    size_t cached_files = 0;

    std::vector<std::string> inline_passwords = std::move(passwords_list);
    passwords_list.clear();
    passwords_list.reserve(inline_passwords.size() + (1u << 16));

    std::vector<std::string> remaining_files;
    remaining_files.reserve(passwords_files.size());

    for (const std::string& fname : passwords_files) {
        uint64_t fsize = 0;
        if (!try_get_file_size(fname, fsize) || fsize > kCachePerFileLimitBytes || (cached_bytes + fsize) > kCacheTotalLimitBytes) {
            remaining_files.emplace_back(fname);
            continue;
        }

        BufferedIfstream fin(1u << 20);
        if (!fin.open(fname)) {
            std::cout << "Error: Failed to open password file '" << fname << "'\n";
            continue;
        }

        std::string line;
        while (read_trimmed_line(fin.stream(), line, 128)) {
            passwords_list.emplace_back(line);
            ++cached_lines;
        }
        cached_bytes += fsize;
        ++cached_files;
    }

    for (std::string& p : inline_passwords) {
        trim_crlf_inplace(p);
        truncate_inplace(p, 128);
        passwords_list.emplace_back(std::move(p));
    }

    passwords_files.swap(remaining_files);
    reset_password_stream_cache();
    passwords_lenght.clear();
    passwords_lenght.reserve(passwords_list.size());
    for (const std::string& p : passwords_list) {
        passwords_lenght.emplace_back(static_cast<uint32_t>(p.size()));
    }

    if (cached_files > 0) {
        fprintf(stderr, "[!] Password cache enabled: %zu file(s), %llu bytes, %zu line(s)\n",
            cached_files,
            static_cast<unsigned long long>(cached_bytes),
            cached_lines);
    }
    if (!passwords_files.empty()) {
        fprintf(stderr, "[!] Password streaming fallback: %zu large file(s) left uncached\n", passwords_files.size());
    }
}

static inline bool priv_span_all_char(const char* data, const size_t len, const char value) {
    for (size_t i = 0; i < len; ++i) {
        if (data[i] != value) return false;
    }
    return true;
}

static inline bool append_normalized_priv_line(
    std::string& buffer,
    std::string& combined,
    std::vector<uint32_t>& indexes,
    uint32_t& nr,
    bool input_is_hex) {
    if (input_is_hex) {
        if (buffer.length() > 64) {
            if (!priv_span_all_char(buffer.data(), 64u, '0')) {
                combined.append(buffer.data(), 64u);
                indexes.emplace_back((uint32_t)combined.size());
                nr++;
            }
            buffer.erase(0, 64);
        }
        if (buffer.length() > 64) {
            buffer.resize(64);
        }
        if (buffer.length() < 64) {
            buffer.insert(0, 64 - buffer.length(), '0');
        }
        if (priv_span_all_char(buffer.data(), buffer.length(), '0')) {
            return false;
        }
    }
    else {
        if (buffer.length() > 32) {
            if (!priv_span_all_char(buffer.data(), 32u, 0x00) &&
                !priv_span_all_char(buffer.data(), 32u, '0')) {
                combined.append(buffer.data(), 32u);
                indexes.emplace_back((uint32_t)combined.size());
                nr++;
            }
            buffer.erase(0, 32);
        }
        if (buffer.length() > 32) {
            buffer.resize(32);
        }
        if (buffer.length() < 32) {
            buffer.insert(0, 32 - buffer.length(), 0x00);
        }
        if (priv_span_all_char(buffer.data(), buffer.length(), 0x00) ||
            priv_span_all_char(buffer.data(), buffer.length(), '0')) {
            return false;
        }
    }

    combined.append(buffer.data(), buffer.size());
    indexes.emplace_back((uint32_t)combined.size());
    nr++;
    return true;
}

static inline void append_brain_line_to_batch(
    const std::string& buffer,
    std::string& combined,
    std::vector<uint32_t>& indexes,
    std::string& last,
    const bool input_is_hex) {
    if (input_is_hex) {
        const size_t out_len = buffer.length() / 2u;
        const size_t offset = combined.size();
        combined.resize(offset + out_len);
        if (out_len > 0u) {
            unhex_host(
                reinterpret_cast<unsigned char*>(const_cast<char*>(buffer.data())),
                buffer.length(),
                reinterpret_cast<unsigned char*>(&combined[offset]),
                out_len);
        }
        last.assign(combined.data() + offset, out_len);
    }
    else {
        combined.append(buffer);
        last = buffer;
    }
    indexes.emplace_back(static_cast<uint32_t>(combined.size()));
}

