static const int PRNG32_GEN_MAX = 489;
static const int PRNG64_GEN_MAX = 223;
static const int PRNG32_MODE_MAX = 762;
static const int PRNG64_MODE_MAX = 218;

static_assert(PRNG32_GEN_MAX == kPrng32GeneratedGenMax, "PRNG32 generated allowlist gen max mismatch");
static_assert(PRNG32_MODE_MAX == kPrng32GeneratedModeMax, "PRNG32 generated allowlist mode max mismatch");
static_assert(PRNG64_GEN_MAX == kPrng64GeneratedGenMax, "PRNG64 generated allowlist gen max mismatch");
static_assert(PRNG64_MODE_MAX == kPrng64GeneratedModeMax, "PRNG64 generated allowlist mode max mismatch");

static bool prng32_mode_in_generated_ranges(int gen, int mode) {
    if (gen < 1 || gen > PRNG32_GEN_MAX || mode < 1 || mode > PRNG32_MODE_MAX) {
        return false;
    }
    // Appended Ill Bloom profiles expose the complete PRNG32 extraction
    // catalog, including the exhaustive output-sign masks.
    if (gen >= 332 && gen <= 489) {
        return mode >= 1 && mode <= 762;
    }
    const int offset = kPrng32AllowedRangeOffset[gen];
    const int count = kPrng32AllowedRangeCount[gen];
    for (int i = 0; i < count; ++i) {
        const Prng32ModeRange& range = kPrng32AllowedRanges[offset + i];
        if (mode >= range.first && mode <= range.last) {
            return true;
        }
    }
    return false;
}

static bool prng64_mode_in_generated_ranges(int gen, int mode) {
    if (gen < 1 || gen > PRNG64_GEN_MAX || mode < 1 || mode > PRNG64_MODE_MAX) {
        return false;
    }
    if (gen >= 221 && gen <= 223) {
        return mode >= 1 && mode <= 218;
    }
    if (gen > 220) {
        return false;
    }
    const int offset = kPrng64AllowedRangeOffset[gen];
    const int count = kPrng64AllowedRangeCount[gen];
    for (int i = 0; i < count; ++i) {
        const Prng64ModeRange& range = kPrng64AllowedRanges[offset + i];
        if (mode >= range.first && mode <= range.last) {
            return true;
        }
    }
    return false;
}

static bool is_prng_combo_allowed(bool is64, int gen, int mode) {
    return is64
        ? prng64_mode_in_generated_ranges(gen, mode)
        : prng32_mode_in_generated_ranges(gen, mode);
}

static bool g_prng_combo_single_explicit = false;

static bool should_run_prng_combo(bool is64, int gen, int mode) {
    if (g_prng_combo_single_explicit) {
        return true;
    }
    return is_prng_combo_allowed(is64, gen, mode);
}

static bool initialize_prng_combo_filter_state() {
    if (!prng_gen && !prng64_gen) {
        return true;
    }

    const bool is64 = prng64_gen;
    const uint64_t total_pairs = (uint64_t)Gens.size() * (uint64_t)PrngModes.size();
    g_prng_combo_single_explicit = gen_set && mode_set && Gens.size() == 1 && PrngModes.size() == 1;

    uint64_t blocked_pairs = 0;
    for (size_t gi = 0; gi < Gens.size(); ++gi) {
        for (size_t mi = 0; mi < PrngModes.size(); ++mi) {
            if (!is_prng_combo_allowed(is64, Gens[gi], PrngModes[mi])) {
                ++blocked_pairs;
            }
        }
    }

    if (g_prng_combo_single_explicit && blocked_pairs == 1) {
        fprintf(stderr, "[!] Warning: selected PRNG gen/mode is marked low-value; running because it was explicitly requested [!]\n");
        return true;
    }

    if (total_pairs > 0 && blocked_pairs == total_pairs) {
        fprintf(stderr, "[!] Error: PRNG combo filter skipped all selected gen/mode pairs [!]\n");
        return false;
    }

    if (total_pairs > 1) {
        printf("[!] PRNG combo filter: active, skipped %llu blocked gen/mode pairs [!]\n",
            (unsigned long long)blocked_pairs);
    }

    return true;
}

static bool validate_prng_values_in_range(const std::vector<int>& values, int min_value, int max_value, const char* flag_name, const char* backend_name) {
    for (int value : values) {
        if (value < min_value || value > max_value) {
            std::cerr << "[!] Error: " << flag_name << " value " << value
                      << " is out of range for " << backend_name
                      << " (expected " << min_value << "-" << max_value << ")." << std::endl;
            return false;
        }
    }
    return true;
}

static bool validate_prng_selection_ranges() {
    if (!prng_gen && !prng64_gen) {
        return true;
    }

    const bool is_prng32 = prng_gen;
    const int gen_max = is_prng32 ? PRNG32_GEN_MAX : PRNG64_GEN_MAX;
    const int mode_max = is_prng32 ? PRNG32_MODE_MAX : PRNG64_MODE_MAX;
    const char* backend_name = is_prng32 ? "-prng" : "-prng64";

    return validate_prng_values_in_range(Gens, 1, gen_max, "-gen", backend_name) &&
           validate_prng_values_in_range(PrngModes, 1, mode_max, "-mode", backend_name);
}

static bool validate_or_clamp_illbloom_packed64_seed_range() {
    if (!prng64_gen || Gens.empty() || PrngModes.empty()) {
        return true;
    }

    for (int gen : Gens) {
        if (gen < 221 || gen > 223) {
            return true;
        }
    }

    uint64_t maximum_index = 0ull;
    bool have_supported_profile = false;
    for (int gen : Gens) {
        if (gen == 221) {
            for (int entropy_len : PrngBytes) {
                if (entropy_len <= 0) {
                    continue;
                }
                maximum_index = (std::max)(maximum_index, (1ull << 48) - 1ull);
                have_supported_profile = true;
            }
        }
        else if (gen == 222) {
            maximum_index = (std::max)(maximum_index, (120ull << 32) - 1ull);
            have_supported_profile = true;
        }
        else {
            maximum_index = (std::max)(maximum_index, (1ull << 40) - 1ull);
            have_supported_profile = true;
        }
    }

    if (!have_supported_profile) {
        std::cerr << "[!] Error: packed Ill Bloom PRNG64 requires a positive -byte value [!]" << std::endl;
        return false;
    }
    if (start_seed64 > maximum_index) {
        fprintf(stderr,
            "[!] Error: packed Ill Bloom PRNG64 start index %016llx exceeds maximum %016llx [!]\n",
            static_cast<unsigned long long>(start_seed64),
            static_cast<unsigned long long>(maximum_index));
        return false;
    }
    if (end_seed64 > maximum_index) {
        fprintf(stderr,
            "[!] Packed Ill Bloom PRNG64: clamping end index %016llx -> %016llx [!]\n",
            static_cast<unsigned long long>(end_seed64),
            static_cast<unsigned long long>(maximum_index));
        end_seed64 = maximum_index;
        end_seed_arg64 = maximum_index;
    }
    return true;
}

class AtomicCounter64 {
public:
    // Creates the counter with an explicit initial value.
    AtomicCounter64(const uint64_t initial = 0) : value_(initial) {}
    // Copies the current value from another counter.
    AtomicCounter64(const AtomicCounter64& other) : value_(other.value_.load(std::memory_order_relaxed)) {}
    // Assigns the value from another AtomicCounter64 instance.
    AtomicCounter64& operator=(const AtomicCounter64& other) {
        if (this != &other) {
            value_.store(other.value_.load(std::memory_order_relaxed), std::memory_order_relaxed);
        }
        return *this;
    }

    // Assigns a raw uint64_t value to the counter.
    AtomicCounter64& operator=(const uint64_t v) {
        value_.store(v, std::memory_order_relaxed);
        return *this;
    }
    // Adds delta to the counter and returns the same object.
    AtomicCounter64& operator+=(const uint64_t delta) {
        value_.fetch_add(delta, std::memory_order_release);
        return *this;
    }
    // Prefix increment: increments first, then returns this object.
    AtomicCounter64& operator++() {
        value_.fetch_add(1, std::memory_order_release);
        return *this;
    }
    // Postfix increment: returns old value, then increments the counter.
    uint64_t operator++(int) {
        return value_.fetch_add(1, std::memory_order_release);
    }
    // Implicit conversion to the current counter value.
    operator uint64_t() const {
        return value_.load(std::memory_order_acquire);
    }
    // Reads the current value with acquire ordering.
    uint64_t load() const {
        return value_.load(std::memory_order_acquire);
    }

private:
    std::atomic<uint64_t> value_;
};

