static inline const char* hexset_mode_label() {
    if (IS_PRIV && !IS_PRIV_RECOVERY && !IS_PRIV_SWAP && !IS_PRIV_BYTE && !IS_PRIV_HASH && !IS_PRIV_PLUS && !IS_PRIV_PLUS_256 && !IS_PRIV_PATTERN) {
        return "-priv";
    }
    if (OLD && (SEED || IS_ENTROPY)) {
        return "-old -seed";
    }
    if (SEED && !OLD) {
        return "-seed";
    }
    if (HMAC) {
        return "-hmac";
    }
    if (BRAIN) {
        return "-brain";
    }
    if (BIP32) {
        return "-bip32";
    }
    if (IS_ENTROPY) {
        return "-entropy";
    }
    if (OLD) {
        return "-old";
    }
    if (ARMORY_ROOT) {
        return "-root";
    }
    if (ARMORY) {
        return "-armory";
    }
    if (!IS_PRIV && !IS_MINIKEYS && !SEED && !HMAC && !BIP32 && !OLD && !ARMORY && !ARMORY_ROOT && !RECOVERY_MODE) {
        return "-mnemonic";
    }
    return nullptr;
}

static inline bool hexset_size_config_for_current_mode(int& out_min_size, int& out_max_size) {
    out_min_size = 1;
    if (IS_PRIV && !IS_PRIV_RECOVERY && !IS_PRIV_SWAP && !IS_PRIV_BYTE && !IS_PRIV_HASH && !IS_PRIV_PLUS && !IS_PRIV_PLUS_256 && !IS_PRIV_PATTERN) {
        out_max_size = 32;
        return true;
    }
    if (OLD && (SEED || IS_ENTROPY)) {
        out_max_size = 512;
        return true;
    }
    if (SEED && !OLD) {
        out_max_size = 64;
        return true;
    }
    if (HMAC) {
        out_max_size = 64;
        return true;
    }
    if (BRAIN) {
        out_max_size = 256;
        return true;
    }
    if (BIP32 || IS_ENTROPY || OLD || (!IS_PRIV && !IS_MINIKEYS && !SEED && !HMAC && !ARMORY && !ARMORY_ROOT && !RECOVERY_MODE)) {
        out_max_size = 512;
        return true;
    }
    return false;
}

// parse_hexset_digits: validates and parses -hexset nibble alphabet in user order.
static inline bool parse_hexset_digits(const std::string& input, std::vector<uint8_t>& out_digits, std::string& out_norm, std::string& err) {
    out_digits.clear();
    out_norm.clear();
    if (input.empty()) {
        err = "-hexset value is empty";
        return false;
    }
    if (input.size() > 16u) {
        err = "-hexset accepts 1..16 unique hex nibbles";
        return false;
    }

    bool seen[16] = { false };
    out_digits.reserve(input.size());
    out_norm.reserve(input.size());
    for (const char ch : input) {
        const int nib = hex_nibble_value(ch);
        if (nib < 0) {
            err = "-hexset contains non-hex characters";
            return false;
        }
        if (seen[nib]) {
            err = "-hexset contains duplicate nibbles";
            return false;
        }
        seen[nib] = true;
        out_digits.push_back(static_cast<uint8_t>(nib));
        out_norm.push_back("0123456789abcdef"[nib]);
    }
    return !out_digits.empty();
}

// parse_hexset_bound_hex: validates even-length hex range bound for -hexset.
static inline bool parse_hexset_bound_hex(
    const std::string& input,
    const size_t max_bytes,
    std::string& out_norm,
    std::vector<uint8_t>& out_nibbles,
    std::string& err) {

    out_norm.clear();
    out_nibbles.clear();
    if (input.empty()) {
        err = "hex bound is empty";
        return false;
    }
    if ((input.size() & 1u) != 0u) {
        err = "hex bound length must be even";
        return false;
    }
    if ((input.size() / 2u) > max_bytes) {
        std::ostringstream oss;
        oss << "hex bound exceeds max size for " << (hexset_mode_label() ? hexset_mode_label() : "this mode")
            << " (" << max_bytes << " bytes)";
        err = oss.str();
        return false;
    }

    out_norm.reserve(input.size());
    out_nibbles.reserve(input.size());
    for (const char ch : input) {
        const int nib = hex_nibble_value(ch);
        if (nib < 0) {
            err = "hex bound contains non-hex characters";
            return false;
        }
        out_norm.push_back("0123456789abcdef"[nib]);
        out_nibbles.push_back(static_cast<uint8_t>(nib));
    }
    return true;
}

// mode_scoped_recovery_supported_after_parse: final routing decision after all flags were parsed.
static inline bool mode_scoped_recovery_supported_after_parse() {
    if (IS_PRIV || IS_MINIKEYS || IS_PRIV_RECOVERY ||
        IS_PRIV_SWAP || IS_PRIV_BYTE || IS_PRIV_HASH || IS_PRIV_PLUS || IS_PRIV_PLUS_256 || IS_PRIV_PATTERN) {
        return false;
    }
    if (OLD || SEED || HMAC || BIP32 || BRAIN || IS_ENTROPY || ARMORY || ARMORY_ROOT || mnemonic_mode_explicit) {
        return true;
    }
    return false;
}

// recovery_hexset_max_bytes_for_current_mode: byte cap for mode-scoped recovery templates.
static inline bool recovery_hexset_max_bytes_for_current_mode(size_t& out_max_bytes) {
    if (OLD && (SEED || IS_ENTROPY)) {
        out_max_bytes = 512u;
        return true;
    }
    if (SEED && !OLD) {
        out_max_bytes = 64u;
        return true;
    }
    if (HMAC) {
        out_max_bytes = 64u;
        return true;
    }
    if (BRAIN) {
        out_max_bytes = 256u;
        return true;
    }
    if (ARMORY && !ARMORY_ROOT) {
        out_max_bytes = 256u;
        return true;
    }
    if (BIP32 || IS_ENTROPY || OLD || ARMORY_ROOT ||
        (!IS_PRIV && !IS_MINIKEYS && !SEED && !HMAC && !BIP32 && !OLD && !RECOVERY_MODE)) {
        out_max_bytes = 512u;
        return true;
    }
    return false;
}

// parse_recovery_hex_template_to: validates mode-scoped recovery template, where '*' is one hex nibble.
static inline bool parse_recovery_hex_template_to(
    const std::string& input,
    std::string& out_raw,
    std::vector<uint8_t>& out_nibbles,
    uint32_t& out_wildcards,
    std::string& err) {
    out_raw.clear();
    out_nibbles.clear();
    out_wildcards = 0u;
    if (input.empty()) {
        err = "-recovery template is empty";
        return false;
    }
    if ((input.size() & 1u) != 0u) {
        err = "-recovery hex template length must be even";
        return false;
    }

    size_t max_bytes = 0u;
    if (!recovery_hexset_max_bytes_for_current_mode(max_bytes)) {
        err = "-recovery TEMPLATE is not supported in this mode";
        return false;
    }
    if ((input.size() / 2u) > max_bytes) {
        std::ostringstream oss;
        oss << "-recovery template exceeds max size for "
            << (hexset_mode_label() ? hexset_mode_label() : "this mode")
            << " (" << max_bytes << " bytes)";
        err = oss.str();
        return false;
    }

    out_nibbles.reserve(input.size());
    out_raw.reserve(input.size());
    for (const char ch : input) {
        if (ch == '*') {
            out_nibbles.push_back(RECOVERY_HEXSET_WILDCARD_HOST);
            out_raw.push_back('*');
            ++out_wildcards;
            continue;
        }
        const int nib = hex_nibble_value(ch);
        if (nib < 0) {
            err = "-recovery hex template accepts only hex chars and '*'";
            return false;
        }
        out_nibbles.push_back(static_cast<uint8_t>(nib));
        out_raw.push_back("0123456789abcdef"[nib]);
    }
    return true;
}

// parse_recovery_hex_template: validates and applies current mode-scoped recovery template.
static inline bool parse_recovery_hex_template(const std::string& input, std::string& err) {
    return parse_recovery_hex_template_to(
        input,
        recovery_hex_template_raw,
        recovery_hex_template_nibbles,
        recovery_hex_wildcards,
        err);
}

// prepare_mode_scoped_recovery_templates: loads inline/file hex templates after final mode is known.
static inline bool prepare_mode_scoped_recovery_templates(std::string& err) {
    mode_scoped_recovery_templates.clear();
    std::vector<RecoveryTemplateInput> raw_templates;
    if (!recovery_expand_templates(raw_templates, err)) {
        return false;
    }

    mode_scoped_recovery_templates.reserve(raw_templates.size());
    for (RecoveryTemplateInput& t : raw_templates) {
        std::string norm;
        std::vector<uint8_t> nibbles;
        uint32_t wildcards = 0u;
        std::string parse_err;
        if (!parse_recovery_hex_template_to(t.phrase, norm, nibbles, wildcards, parse_err)) {
            std::ostringstream oss;
            oss << "invalid mode-scoped -recovery template";
            if (!t.source.empty()) {
                oss << " in " << t.source;
                if (t.line_no != 0u) {
                    oss << ":" << t.line_no;
                }
            }
            oss << ": " << parse_err;
            err = oss.str();
            return false;
        }
        if (wildcards == 0u) {
            std::ostringstream oss;
            oss << "invalid mode-scoped -recovery template";
            if (!t.source.empty()) {
                oss << " in " << t.source;
                if (t.line_no != 0u) {
                    oss << ":" << t.line_no;
                }
            }
            oss << ": template must contain at least one '*'";
            err = oss.str();
            return false;
        }
        t.phrase = norm;
        mode_scoped_recovery_templates.emplace_back(std::move(t));
    }
    if (mode_scoped_recovery_templates.empty()) {
        err = "mode-scoped recovery template queue is empty";
        return false;
    }
    return true;
}

static inline bool apply_mode_scoped_recovery_template(const RecoveryTemplateInput& t, std::string& err) {
    if (!parse_recovery_hex_template(t.phrase, err)) {
        return false;
    }
    const int template_bytes = static_cast<int>(recovery_hex_template_nibbles.size() / 2u);
    entropy_len = template_bytes;
    min_len = template_bytes;
    return true;
}

// add_baseN_counter_inplace: adds delta to mixed-radix digit counter in-place.
static inline bool add_baseN_counter_inplace(std::vector<uint8_t>& digits, const uint32_t base, uint64_t delta) {
    if (base == 0u || digits.empty()) {
        return false;
    }
    if (base == 1u) {
        return delta == 0ull;
    }
    for (size_t pos = digits.size(); pos-- > 0;) {
        const uint64_t add = delta % static_cast<uint64_t>(base);
        delta /= static_cast<uint64_t>(base);
        uint64_t sum = static_cast<uint64_t>(digits[pos]) + add;
        if (sum >= static_cast<uint64_t>(base)) {
            sum -= static_cast<uint64_t>(base);
            ++delta;
        }
        digits[pos] = static_cast<uint8_t>(sum);
    }
    return delta == 0ull;
}

// materialize_hexset_counter_to_hex: renders current mixed-radix counter as exact hex string.
static inline std::string materialize_hexset_counter_to_hex(const std::vector<uint8_t>& digits, const std::vector<uint8_t>& alphabet) {
    static const char* kHex = "0123456789abcdef";
    std::string out;
    out.resize(digits.size());
    for (size_t i = 0; i < digits.size(); ++i) {
        out[i] = kHex[alphabet[digits[i]] & 0x0Fu];
    }
    return out;
}

// add_recovery_hexset_counter_inplace: adds delta over wildcard positions only.
static inline bool add_recovery_hexset_counter_inplace(
    std::vector<uint8_t>& counter_digits,
    const std::vector<uint8_t>& templ,
    const uint32_t base,
    uint64_t delta) {

    if (base == 0u || counter_digits.size() != templ.size()) {
        return false;
    }
    if (base == 1u) {
        return delta == 0ull;
    }
    for (size_t pos = templ.size(); pos-- > 0;) {
        if (templ[pos] != RECOVERY_HEXSET_WILDCARD_HOST) {
            continue;
        }
        const uint64_t add = delta % static_cast<uint64_t>(base);
        delta /= static_cast<uint64_t>(base);
        uint64_t sum = static_cast<uint64_t>(counter_digits[pos]) + add;
        if (sum >= static_cast<uint64_t>(base)) {
            sum -= static_cast<uint64_t>(base);
            ++delta;
        }
        counter_digits[pos] = static_cast<uint8_t>(sum);
    }
    return delta == 0ull;
}

// materialize_recovery_hexset_counter_to_hex: renders current recovery template point.
static inline std::string materialize_recovery_hexset_counter_to_hex(
    const std::vector<uint8_t>& templ,
    const std::vector<uint8_t>& counter_digits,
    const std::vector<uint8_t>& alphabet) {

    static const char* kHex = "0123456789abcdef";
    std::string out;
    out.resize(templ.size());
    for (size_t i = 0; i < templ.size(); ++i) {
        if (templ[i] == RECOVERY_HEXSET_WILDCARD_HOST) {
            out[i] = kHex[alphabet[counter_digits[i]] & 0x0Fu];
        }
        else {
            out[i] = kHex[templ[i] & 0x0Fu];
        }
    }
    return out;
}

// compare_hexset_counter_digits: compares mixed-radix digit vectors lexicographically.
static inline int compare_hexset_counter_digits(const std::vector<uint8_t>& lhs, const std::vector<uint8_t>& rhs) {
    if (lhs.size() != rhs.size()) {
        return (lhs.size() < rhs.size()) ? -1 : 1;
    }
    for (size_t i = 0; i < lhs.size(); ++i) {
        if (lhs[i] != rhs[i]) {
            return (lhs[i] < rhs[i]) ? -1 : 1;
        }
    }
    return 0;
}

// nibble_vector_to_bytes: packs nibble vector into exact-size bytes.
static inline void nibble_vector_to_bytes(const std::vector<uint8_t>& nibbles, std::vector<uint8_t>& out_bytes) {
    out_bytes.assign(nibbles.size() / 2u, 0u);
    for (size_t i = 0; i < out_bytes.size(); ++i) {
        out_bytes[i] = static_cast<uint8_t>((nibbles[i * 2u] << 4) | nibbles[i * 2u + 1u]);
    }
}

// build_hexset_numeric_bounds_for_length: builds lower/upper numeric hex window for one exact byte length.
static inline void build_hexset_numeric_bounds_for_length(
    const int current_size,
    const int start_len_bytes,
    const int end_len_bytes,
    std::vector<uint8_t>& out_lower,
    std::vector<uint8_t>& out_upper) {

    out_lower.assign(static_cast<size_t>(current_size) * 2u, 0u);
    out_upper.assign(static_cast<size_t>(current_size) * 2u, 0x0Fu);

    if (current_size == start_len_bytes) {
        out_lower = hexset_start_bound_nibbles;
    }

    if (!hexset_end_bound_nibbles.empty()) {
        if (current_size == end_len_bytes) {
            out_upper = hexset_end_bound_nibbles;
        }
    }
}

// hexset_can_complete_ge_equal: checks whether suffix can stay within >= lower bound.
static inline bool hexset_can_complete_ge_equal(
    const std::vector<uint8_t>& lower_nibbles,
    const std::vector<uint8_t>& alphabet,
    std::vector<uint8_t>& memo,
    const size_t pos) {

    if (pos >= lower_nibbles.size()) {
        return true;
    }
    if (memo[pos] != 0xFFu) {
        return memo[pos] != 0u;
    }
    const uint8_t target = lower_nibbles[pos];
    bool ok = false;
    for (size_t idx = 0; idx < alphabet.size(); ++idx) {
        const uint8_t nib = alphabet[idx];
        if (nib > target) {
            ok = true;
            break;
        }
        if (nib == target && hexset_can_complete_ge_equal(lower_nibbles, alphabet, memo, pos + 1u)) {
            ok = true;
            break;
        }
    }
    memo[pos] = ok ? 1u : 0u;
    return ok;
}

// hexset_can_complete_le_equal: checks whether suffix can stay within <= upper bound.
static inline bool hexset_can_complete_le_equal(
    const std::vector<uint8_t>& upper_nibbles,
    const std::vector<uint8_t>& alphabet,
    std::vector<uint8_t>& memo,
    const size_t pos) {

    if (pos >= upper_nibbles.size()) {
        return true;
    }
    if (memo[pos] != 0xFFu) {
        return memo[pos] != 0u;
    }
    const uint8_t target = upper_nibbles[pos];
    bool ok = false;
    for (size_t idx = 0; idx < alphabet.size(); ++idx) {
        const uint8_t nib = alphabet[idx];
        if (nib < target) {
            ok = true;
            break;
        }
        if (nib == target && hexset_can_complete_le_equal(upper_nibbles, alphabet, memo, pos + 1u)) {
            ok = true;
            break;
        }
    }
    memo[pos] = ok ? 1u : 0u;
    return ok;
}

// find_first_hexset_counter_ge_bound: finds earliest user-order counter within numeric lower bound.
static inline bool find_first_hexset_counter_ge_bound(
    const std::vector<uint8_t>& lower_nibbles,
    const std::vector<uint8_t>& alphabet,
    std::vector<uint8_t>& out_counter) {

    out_counter.clear();
    if (lower_nibbles.empty() || alphabet.empty()) {
        return false;
    }

    std::vector<uint8_t> memo(lower_nibbles.size() + 1u, 0xFFu);
    memo[lower_nibbles.size()] = 1u;
    if (!hexset_can_complete_ge_equal(lower_nibbles, alphabet, memo, 0u)) {
        return false;
    }

    out_counter.resize(lower_nibbles.size(), 0u);
    bool greater = false;
    for (size_t pos = 0; pos < lower_nibbles.size(); ++pos) {
        const uint8_t target = lower_nibbles[pos];
        bool assigned = false;
        for (size_t idx = 0; idx < alphabet.size(); ++idx) {
            const uint8_t nib = alphabet[idx];
            bool feasible = false;
            if (greater) {
                feasible = true;
            }
            else if (nib > target) {
                feasible = true;
            }
            else if (nib == target && hexset_can_complete_ge_equal(lower_nibbles, alphabet, memo, pos + 1u)) {
                feasible = true;
            }

            if (feasible) {
                out_counter[pos] = static_cast<uint8_t>(idx);
                if (!greater && nib > target) {
                    greater = true;
                }
                assigned = true;
                break;
            }
        }
        if (!assigned) {
            out_counter.clear();
            return false;
        }
    }
    return true;
}

// find_last_hexset_counter_le_bound: finds latest user-order counter within numeric upper bound.
static inline bool find_last_hexset_counter_le_bound(
    const std::vector<uint8_t>& upper_nibbles,
    const std::vector<uint8_t>& alphabet,
    std::vector<uint8_t>& out_counter) {

    out_counter.clear();
    if (upper_nibbles.empty() || alphabet.empty()) {
        return false;
    }

    std::vector<uint8_t> memo(upper_nibbles.size() + 1u, 0xFFu);
    memo[upper_nibbles.size()] = 1u;
    if (!hexset_can_complete_le_equal(upper_nibbles, alphabet, memo, 0u)) {
        return false;
    }

    out_counter.resize(upper_nibbles.size(), 0u);
    bool smaller = false;
    for (size_t pos = 0; pos < upper_nibbles.size(); ++pos) {
        const uint8_t target = upper_nibbles[pos];
        bool assigned = false;
        for (size_t rev = alphabet.size(); rev-- > 0u;) {
            const uint8_t nib = alphabet[rev];
            bool feasible = false;
            if (smaller) {
                feasible = true;
            }
            else if (nib < target) {
                feasible = true;
            }
            else if (nib == target && hexset_can_complete_le_equal(upper_nibbles, alphabet, memo, pos + 1u)) {
                feasible = true;
            }

            if (feasible) {
                out_counter[pos] = static_cast<uint8_t>(rev);
                if (!smaller && nib < target) {
                    smaller = true;
                }
                assigned = true;
                break;
            }
        }
        if (!assigned) {
            out_counter.clear();
            return false;
        }
    }
    return true;
}

static inline int hexset_effective_end_len_for_current_mode() {
    if (!hexset_end_bound_nibbles.empty()) {
        return static_cast<int>(hexset_end_bound_nibbles.size() / 2u);
    }
    int min_size = 0;
    int max_size = 0;
    if (!hexset_size_config_for_current_mode(min_size, max_size)) {
        return 0;
    }
    return max_size;
}

// print_hexset_startup_banner: prints normalized -hexset range banner.
static inline void print_hexset_startup_banner(const char* mode_label) {
    const int start_len_bytes = static_cast<int>(hexset_start_bound_nibbles.size() / 2u);
    const int end_len_bytes = hexset_effective_end_len_for_current_mode();
    printf("[!] starting %s [!]\n", mode_label);
    printf("[!] HEXSET alphabet: %s [!]\n", hexset_raw_arg.c_str());
    printf("[!] HEXSET start: %s [!]\n", hexset_start_bound_norm.c_str());
    if (!hexset_end_bound_norm.empty()) {
        printf("[!] HEXSET end: %s [!]\n", hexset_end_bound_norm.c_str());
    }
    else {
        printf("[!] HEXSET end: AUTO(MAX for mode) [!]\n");
    }
    printf("[!] HEXSET length span: %d..%d bytes [!]\n", start_len_bytes, end_len_bytes);
}

// print_recovery_hexset_startup_banner: prints mode-scoped recovery banner.
static inline void print_recovery_hexset_startup_banner(const char* mode_label) {
    printf("[!] starting %s [!]\n", mode_label);
    printf("[!] RECOVERY template: %s [!]\n", recovery_hex_template_raw.c_str());
    printf("[!] HEXSET alphabet: %s [!]\n", hexset_raw_arg.c_str());
    printf("[!] RECOVERY wildcards: %u nibble(s) [!]\n", recovery_hex_wildcards);
    printf("[!] RECOVERY fixed length: %zu byte(s) [!]\n", recovery_hex_template_nibbles.size() / 2u);
}

// run_mode_scoped_recovery_templates: runs all inline/file templates through one GPU worker path.
static metalError_t run_mode_scoped_recovery_templates(const char* mode_label, metalError_t (*process_fn)()) {
    if (mode_scoped_recovery_templates.empty()) {
        fprintf(stderr, "[!] Error: mode-scoped recovery template queue is empty [!]\n");
        return metalErrorInvalidValue;
    }

    for (const RecoveryTemplateInput& t : mode_scoped_recovery_templates) {
        std::string err;
        if (!apply_mode_scoped_recovery_template(t, err)) {
            fprintf(stderr, "[!] Error: invalid mode-scoped recovery template");
            if (!t.source.empty()) {
                fprintf(stderr, " in %s", t.source.c_str());
                if (t.line_no != 0u) {
                    fprintf(stderr, ":%zu", t.line_no);
                }
            }
            fprintf(stderr, ": %s [!]\n", err.c_str());
            return metalErrorInvalidValue;
        }

        if (mode_scoped_recovery_templates.size() > 1u) {
            printf("[!] RECOVERY source: %s", t.source.empty() ? "<cmd>" : t.source.c_str());
            if (t.line_no != 0u) {
                printf(":%zu", t.line_no);
            }
            printf(" [!]\n");
        }
        print_recovery_hexset_startup_banner(mode_label);
        const metalError_t st = process_fn();
        if (st != metalSuccess) {
            return st;
        }
    }
    return metalSuccess;
}

static inline const char* runtime_log_dir() {
    return "_perf/runtime_logs";
}

static inline bool path_has_directory_component(const std::string& path) {
    return path.find('/') != std::string::npos;
}

static inline void ensure_runtime_log_dir() {
    static std::once_flag once;
    std::call_once(once, []() {
        mac_create_directory("_perf");
        mac_create_directory(runtime_log_dir());
    });
}

static inline std::string runtime_log_path(const char* path) {
    if (path == nullptr || path[0] == '\0') {
        return std::string();
    }

    std::string out(path);
    if (path_has_directory_component(out)) {
        return out;
    }

    ensure_runtime_log_dir();
    return std::string(runtime_log_dir()) + "/" + out;
}

static inline std::string effective_progress_log_path() {
    if (log_file_user_set || path_has_directory_component(log_file)) {
        return log_file;
    }
    return runtime_log_path(log_file.c_str());
}

static inline FILE* open_runtime_log(const char* path, const char* mode) {
    const std::string out = runtime_log_path(path);
    if (out.empty()) {
        return nullptr;
    }
    return fopen(out.c_str(), mode);
}

// write_text_log_snapshot: writes a plain-text status snapshot into a log file.
static inline void write_text_log_snapshot(const char* path, const std::string& value) {
    const std::string out_path = runtime_log_path(path);
    if (out_path.empty()) {
        return;
    }
    FILE* fp = fopen(out_path.c_str(), "wb");
    if (fp == nullptr) {
        return;
    }
    if (!value.empty()) {
        fwrite(value.data(), 1, value.size(), fp);
    }
    fclose(fp);
}

