struct ThreadInputSnapshot {
    uint32_t start_seed = 0;
    uint32_t end_seed = UINT32_MAX;
    uint64_t start_seed64 = 0;
    uint64_t end_seed64 = UINT64_MAX;
    uint64_t step = 1;

    uint8_t start_pvk_point[32] = { 0 };
    uint8_t end_pvk_point[32] = { 0 };
    uint8_t start_seed_point[64] = { 0 };
    uint8_t end_seed_point[64] = { 0 };
    uint8_t start_entropy_point[512] = { 0 };
    uint8_t end_entropy_point[512] = { 0 };
    uint8_t start_mnemonic_point[512] = { 0 };
    uint8_t end_mnemonic_point[512] = { 0 };
    uint8_t start_brain_point[256] = { 0 };
    uint8_t end_brain_point[256] = { 0 };
};

static std::vector<GpuRuntimeContext> g_gpu_contexts;
static std::mutex g_activate_gpu_context_mutex;
thread_local static bool g_disable_multi_gpu_dispatch = false;
thread_local static uint64_t g_seq_kernel_step_override = 0;
thread_local static uint64_t g_seq_both_chunk_delta_override = 0;

static inline uint64_t effective_seq_kernel_step() {
    return g_seq_kernel_step_override != 0ull ? g_seq_kernel_step_override : step;
}

static inline bool mul_u64_checked(const uint64_t a, const uint64_t b, uint64_t& out) {
    if (b != 0ull && a > (std::numeric_limits<uint64_t>::max() / b)) {
        return false;
    }
    out = a * b;
    return true;
}

static inline uint64_t generated_seq_round_size_for_mode(const char* mode_name) {
    uint64_t per_thread = static_cast<uint64_t>(THREAD_STEPS);
    if (mode_name != nullptr && std::strstr(mode_name, "BrainSeq") != nullptr) {
        per_thread = static_cast<uint64_t>(THREAD_STEPS_BRAIN);
    }
    else if (mode_name != nullptr &&
        std::strstr(mode_name, "PRIVSeq") != nullptr &&
        std::strstr(mode_name, "_old") == nullptr) {
        uint64_t pub_steps = static_cast<uint64_t>(chunks) * static_cast<uint64_t>(keys_per_chunk);
        if ((pub_steps % 1024ull) != 0ull) {
            pub_steps = ((pub_steps + 1023ull) / 1024ull) * 1024ull;
        }
        per_thread = pub_steps;
    }

    uint64_t round = 0;
    uint64_t blocks_threads = 0;
    if (!mul_u64_checked(static_cast<uint64_t>(BLOCK_NUMBER), static_cast<uint64_t>(BLOCK_THREADS), blocks_threads) ||
        !mul_u64_checked(blocks_threads, per_thread, round)) {
        return 0ull;
    }
    return round;
}

// is_multi_gpu_active: checks whether multi GPU active is valid.
static inline bool is_multi_gpu_active() {
    return g_gpu_contexts.size() > 1;
}

static inline bool should_write_seq_checkpoint_log() {
    return isLog && (!is_multi_gpu_active() || (!g_gpu_contexts.empty() && DEVICE_NR == g_gpu_contexts.front().device_id));
}

static std::string bytes_to_hex_upper_full(const uint8_t* data, const size_t len) {
    static const char hex[] = "0123456789ABCDEF";
    std::string out;
    out.resize(len * 2u);
    for (size_t i = 0; i < len; ++i) {
        out[i * 2u] = hex[(data[i] >> 4) & 0x0f];
        out[i * 2u + 1u] = hex[data[i] & 0x0f];
    }
    return out;
}

static std::string seq_step_hex(const uint64_t value) {
    std::ostringstream ss;
    ss << "0x" << std::hex << std::uppercase << value;
    return ss.str();
}

static void write_seq_checkpoint_log(const char sign, const uint8_t* point, const size_t len, const uint64_t seq_step) {
    if (!should_write_seq_checkpoint_log()) {
        return;
    }
    const std::string out_log = effective_progress_log_path();
    std::ofstream ofs(out_log, std::ios::trunc);
    if (!ofs.is_open()) {
        std::cerr << "Failed to open log file: " << out_log << "\n";
        return;
    }
    ofs << sign << bytes_to_hex_upper_full(point, len) << " step " << seq_step_hex(seq_step) << "\n";
}

static void write_seq_checkpoint_log_both(const uint8_t* plus, const uint8_t* minus, const size_t len, const uint64_t seq_step) {
    if (!should_write_seq_checkpoint_log()) {
        return;
    }
    const std::string out_log = effective_progress_log_path();
    std::ofstream ofs(out_log, std::ios::trunc);
    if (!ofs.is_open()) {
        std::cerr << "Failed to open log file: " << out_log << "\n";
        return;
    }
    ofs << "+" << bytes_to_hex_upper_full(plus, len) << " step " << seq_step_hex(seq_step) << "\n";
    ofs << "-" << bytes_to_hex_upper_full(minus, len) << " step " << seq_step_hex(seq_step) << "\n";
}

// add_scalar_to_be: adds scalar to be.
static inline void add_scalar_to_be(uint8_t* data, const size_t len, uint64_t delta) {
    if (delta == 0) {
        return;
    }
    for (size_t i = 0; i < len && delta != 0; ++i) {
        const size_t pos = len - 1 - i;
        const uint64_t acc = static_cast<uint64_t>(data[pos]) + (delta & 0xFFu);
        data[pos] = static_cast<uint8_t>(acc & 0xFFu);
        delta = (delta >> 8) + (acc >> 8);
    }
}

// sub_scalar_from_be: subtracts scalar from be.
static inline void sub_scalar_from_be(uint8_t* data, const size_t len, uint64_t delta) {
    if (delta == 0) {
        return;
    }
    for (size_t i = 0; i < len && delta != 0; ++i) {
        const size_t pos = len - 1 - i;
        const uint64_t rhs = (delta & 0xFFu);
        if (data[pos] >= rhs) {
            data[pos] = static_cast<uint8_t>(data[pos] - rhs);
            delta >>= 8;
        }
        else {
            data[pos] = static_cast<uint8_t>(0x100u + data[pos] - rhs);
            delta = (delta >> 8) + 1u;
        }
    }
}

static inline void init_seq_both_points(uint8_t* plus, uint8_t* minus, const uint8_t* start, const uint8_t* end, const size_t len) {
    memcpy(plus, start, len);
    memcpy(minus, end_point_set ? end : start, len);
    if (g_seq_both_chunk_delta_override != 0ull) {
        add_scalar_to_be(plus, len, g_seq_both_chunk_delta_override);
        sub_scalar_from_be(minus, len, g_seq_both_chunk_delta_override);
    }
}

static inline bool seq_both_round_active(const uint8_t* plus, const uint8_t* minus, const uint8_t* start, const uint8_t* end, const size_t len) {
    if (!end_point_set) {
        return true;
    }
    return cmp_host(plus, end, static_cast<int>(len)) <= 0 &&
        cmp_host(minus, start, static_cast<int>(len)) >= 0;
}

static inline void print_end_point_text_if_set(const char* label) {
    if (!end_point_set) {
        return;
    }
    printf("%s%s\n", label, end_point.c_str());
}

static inline void print_end_point_hex_if_set(const char* label, const uint8_t* point, const size_t len) {
    if (!end_point_set) {
        return;
    }
    printf("%s", label);
    for (size_t i = 0; i < len; ++i) {
        printf("%02X", point[i]);
    }
    printf("\n");
}

// capture_thread_input_snapshot: captures thread input snapshot.
static inline ThreadInputSnapshot capture_thread_input_snapshot() {
    ThreadInputSnapshot snap;
    snap.start_seed = start_seed;
    snap.end_seed = end_seed;
    snap.start_seed64 = start_seed64;
    snap.end_seed64 = end_seed64;
    snap.step = step;
    memcpy(snap.start_pvk_point, start_pvk_point, sizeof(start_pvk_point));
    memcpy(snap.end_pvk_point, end_pvk_point, sizeof(end_pvk_point));
    memcpy(snap.start_seed_point, start_seed_point, sizeof(start_seed_point));
    memcpy(snap.end_seed_point, end_seed_point, sizeof(end_seed_point));
    memcpy(snap.start_entropy_point, start_entropy_point, sizeof(start_entropy_point));
    memcpy(snap.end_entropy_point, end_entropy_point, sizeof(end_entropy_point));
    memcpy(snap.start_mnemonic_point, start_mnemonic_point, sizeof(start_mnemonic_point));
    memcpy(snap.end_mnemonic_point, end_mnemonic_point, sizeof(end_mnemonic_point));
    memcpy(snap.start_brain_point, start_brain_point, sizeof(start_brain_point));
    memcpy(snap.end_brain_point, end_brain_point, sizeof(end_brain_point));
    return snap;
}

// restore_thread_input_snapshot: restores thread input snapshot.
static inline void restore_thread_input_snapshot(const ThreadInputSnapshot& snap) {
    start_seed = snap.start_seed;
    end_seed = snap.end_seed;
    start_seed64 = snap.start_seed64;
    end_seed64 = snap.end_seed64;
    step = snap.step;
    memcpy(start_pvk_point, snap.start_pvk_point, sizeof(start_pvk_point));
    memcpy(end_pvk_point, snap.end_pvk_point, sizeof(end_pvk_point));
    memcpy(start_seed_point, snap.start_seed_point, sizeof(start_seed_point));
    memcpy(end_seed_point, snap.end_seed_point, sizeof(end_seed_point));
    memcpy(start_entropy_point, snap.start_entropy_point, sizeof(start_entropy_point));
    memcpy(end_entropy_point, snap.end_entropy_point, sizeof(end_entropy_point));
    memcpy(start_mnemonic_point, snap.start_mnemonic_point, sizeof(start_mnemonic_point));
    memcpy(end_mnemonic_point, snap.end_mnemonic_point, sizeof(end_mnemonic_point));
    memcpy(start_brain_point, snap.start_brain_point, sizeof(start_brain_point));
    memcpy(end_brain_point, snap.end_brain_point, sizeof(end_brain_point));
}

