// activate_gpu_context: activates GPU context.
static inline bool activate_gpu_context(const GpuRuntimeContext& ctx) {
    metalError_t st = metalSetDevice(ctx.device_id);
    if (st != metalSuccess) {
        fprintf(stderr, "[!] Failed to activate device %d: %s [!]\n", ctx.device_id, metalGetErrorString(st));
        return false;
    }
    st = metalFree(0);
    if (st != metalSuccess) {
        fprintf(stderr, "[!] Failed to initialize Metal runtime on device %d thread: %s [!]\n", ctx.device_id, metalGetErrorString(st));
        return false;
    }
    apply_gpu_context(ctx);
    return true;
}

// detect_partition_kind_for_generated_mode: detects partition kind for generated mode.
static inline MultiGpuPartitionKind detect_partition_kind_for_generated_mode() {
    if (isRandom && (prng_gen || prng64_gen)) {
        return MultiGpuPartitionKind::random_mode;
    }
    if (prng_gen) {
        return MultiGpuPartitionKind::prng32;
    }
    if (prng64_gen) {
        return MultiGpuPartitionKind::prng64;
    }
    if (seqMode) {
        if (both) {
            return MultiGpuPartitionKind::seq_both;
        }
        return backward ? MultiGpuPartitionKind::seq_backward : MultiGpuPartitionKind::seq_forward;
    }
    if (isRandom) {
        return MultiGpuPartitionKind::random_mode;
    }
    return MultiGpuPartitionKind::none;
}

static inline bool split_u32_range(const uint32_t range_start,
    const uint32_t range_end,
    const size_t part_index,
    const size_t part_count,
    uint32_t& out_start,
    uint32_t& out_end) {
    if (range_start > range_end || part_count == 0) {
        return false;
    }
    const uint64_t total = static_cast<uint64_t>(range_end) - static_cast<uint64_t>(range_start) + 1ull;
    const uint64_t base = total / part_count;
    const uint64_t rem = total % part_count;
    const uint64_t my = base + (part_index < rem ? 1ull : 0ull);
    if (my == 0) {
        return false;
    }
    const uint64_t offset = static_cast<uint64_t>(part_index) * base + std::min<uint64_t>(part_index, rem);
    out_start = static_cast<uint32_t>(static_cast<uint64_t>(range_start) + offset);
    out_end = static_cast<uint32_t>(static_cast<uint64_t>(out_start) + my - 1ull);
    return true;
}

static inline bool split_u64_range(const uint64_t range_start,
    const uint64_t range_end,
    const size_t part_index,
    const size_t part_count,
    uint64_t& out_start,
    uint64_t& out_end) {
    if (range_start > range_end || part_count == 0) {
        return false;
    }
    uint64_t base = 0ull;
    uint64_t rem = 0ull;
    if (range_start == 0ull && range_end == std::numeric_limits<uint64_t>::max()) {
        // Split full [0..2^64-1] domain without 128-bit arithmetic.
        const uint64_t k = static_cast<uint64_t>(part_count);
        uint64_t q = std::numeric_limits<uint64_t>::max() / k;
        uint64_t r = std::numeric_limits<uint64_t>::max() % k;
        base = q;
        rem = r + 1ull; // because 2^64 = (2^64-1) + 1
        if (rem == k) {
            ++base;
            rem = 0ull;
        }
    }
    else {
        const uint64_t total = range_end - range_start + 1ull;
        base = total / part_count;
        rem = total % part_count;
    }

    const uint64_t my = base + (part_index < rem ? 1ull : 0ull);
    if (my == 0) {
        return false;
    }
    const uint64_t offset = static_cast<uint64_t>(part_index) * base + std::min<uint64_t>(part_index, rem);
    out_start = range_start + offset;
    out_end = out_start + my - 1ull;
    return true;
}

static constexpr size_t MULTI_GPU_MAX_BE_RANGE_BYTES = 512;

static inline bool mgpu_be_is_zero(const uint8_t* value, const size_t len) {
    for (size_t i = 0; i < len; ++i) {
        if (value[i] != 0u) {
            return false;
        }
    }
    return true;
}

static inline void mgpu_be_inc(uint8_t* value, const size_t len) {
    for (size_t i = len; i-- > 0;) {
        ++value[i];
        if (value[i] != 0u) {
            break;
        }
    }
}

static inline void mgpu_be_add_small(uint8_t* value, const size_t len, uint64_t delta) {
    for (size_t i = 0; i < len && delta != 0ull; ++i) {
        const size_t pos = len - 1 - i;
        const uint64_t acc = static_cast<uint64_t>(value[pos]) + (delta & 0xFFull);
        value[pos] = static_cast<uint8_t>(acc & 0xFFull);
        delta = (delta >> 8) + (acc >> 8);
    }
}

static inline void mgpu_be_sub_small(uint8_t* value, const size_t len, uint64_t delta) {
    for (size_t i = 0; i < len && delta != 0ull; ++i) {
        const size_t pos = len - 1 - i;
        const uint64_t rhs = (delta & 0xFFull);
        if (value[pos] >= rhs) {
            value[pos] = static_cast<uint8_t>(value[pos] - rhs);
            delta >>= 8;
        }
        else {
            value[pos] = static_cast<uint8_t>(0x100ull + static_cast<uint64_t>(value[pos]) - rhs);
            delta = (delta >> 8) + 1ull;
        }
    }
}

static inline uint64_t mgpu_be_divmod_small(uint8_t* value, const size_t len, const uint64_t divisor) {
    if (divisor == 0ull) {
        return 0ull;
    }
    uint64_t rem = 0ull;
    for (size_t i = 0; i < len; ++i) {
        const uint64_t cur = (rem << 8) | static_cast<uint64_t>(value[i]);
        value[i] = static_cast<uint8_t>(cur / divisor);
        rem = cur % divisor;
    }
    return rem;
}

static inline bool split_be_range(const uint8_t* range_start,
    const uint8_t* range_end,
    const size_t len,
    const size_t part_index,
    const size_t part_count,
    uint8_t* out_start,
    uint8_t* out_end) {
    if (range_start == nullptr || range_end == nullptr || out_start == nullptr || out_end == nullptr) {
        return false;
    }
    if (len == 0 || len > MULTI_GPU_MAX_BE_RANGE_BYTES || part_count == 0 || part_index >= part_count) {
        return false;
    }
    if (cmp_be(range_start, range_end, len) > 0) {
        return false;
    }

    uint8_t total[MULTI_GPU_MAX_BE_RANGE_BYTES] = { 0 };
    uint8_t base[MULTI_GPU_MAX_BE_RANGE_BYTES] = { 0 };
    uint8_t my_size[MULTI_GPU_MAX_BE_RANGE_BYTES] = { 0 };
    uint8_t offset[MULTI_GPU_MAX_BE_RANGE_BYTES] = { 0 };
    uint8_t tmp[MULTI_GPU_MAX_BE_RANGE_BYTES] = { 0 };
    uint8_t span_minus_one[MULTI_GPU_MAX_BE_RANGE_BYTES] = { 0 };

    sub_be(range_end, range_start, total, len);
    mgpu_be_inc(total, len); // inclusive range length

    std::memcpy(base, total, len);
    const uint64_t rem = mgpu_be_divmod_small(base, len, static_cast<uint64_t>(part_count));

    std::memcpy(my_size, base, len);
    if (part_index < rem) {
        mgpu_be_inc(my_size, len);
    }
    if (mgpu_be_is_zero(my_size, len)) {
        return false;
    }

    for (size_t i = 0; i < part_index; ++i) {
        add_be(offset, base, tmp, len);
        std::memcpy(offset, tmp, len);
    }
    mgpu_be_add_small(offset, len, std::min<uint64_t>(static_cast<uint64_t>(part_index), rem));

    std::memcpy(span_minus_one, my_size, len);
    mgpu_be_sub_small(span_minus_one, len, 1ull);

    add_be(range_start, offset, out_start, len);
    add_be(out_start, span_minus_one, out_end, len);

    if (cmp_be(out_start, out_end, len) > 0) {
        return false;
    }
    if (cmp_be(out_start, range_start, len) < 0) {
        return false;
    }
    if (cmp_be(out_end, range_end, len) > 0) {
        return false;
    }
    return true;
}

static inline uint32_t random_u32_raw() {
    uint32_t value = 0u;
    random_bytes(reinterpret_cast<uint8_t*>(&value), sizeof(value), static_cast<int>(sizeof(value)));
    return value;
}

static inline uint64_t random_u64_raw() {
    uint64_t value = 0ull;
    random_bytes(reinterpret_cast<uint8_t*>(&value), sizeof(value), static_cast<int>(sizeof(value)));
    return value;
}

static inline uint32_t random_seed32_inclusive(uint32_t start_inclusive, uint32_t end_inclusive) {
    if (start_inclusive > end_inclusive) {
        std::swap(start_inclusive, end_inclusive);
    }
    const uint64_t span = static_cast<uint64_t>(end_inclusive) - static_cast<uint64_t>(start_inclusive) + 1ull;
    if (span == (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) + 1ull)) {
        return random_u32_raw();
    }
    const uint64_t limit = (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) + 1ull) / span * span;
    uint32_t rnd = 0u;
    do {
        rnd = random_u32_raw();
    } while (static_cast<uint64_t>(rnd) >= limit);
    return start_inclusive + static_cast<uint32_t>(static_cast<uint64_t>(rnd) % span);
}

struct ProfanityRandomSeedBlock {
    uint32_t next_seed = 0u;
    uint64_t remaining = 0ull;
};

static inline bool profanity_pick_random_seed_block(
    uint32_t start_inclusive,
    uint32_t end_inclusive,
    uint64_t requested_count,
    ProfanityRandomSeedBlock& block)
{
    if (requested_count == 0ull) {
        return false;
    }
    if (start_inclusive > end_inclusive) {
        std::swap(start_inclusive, end_inclusive);
    }

    const uint64_t range = static_cast<uint64_t>(end_inclusive) - static_cast<uint64_t>(start_inclusive) + 1ull;
    const uint64_t effective_count = std::min<uint64_t>(requested_count, range);
    const uint32_t max_start = static_cast<uint32_t>(
        static_cast<uint64_t>(end_inclusive) - (effective_count - 1ull));

    block.next_seed = random_seed32_inclusive(start_inclusive, max_start);
    block.remaining = effective_count;
    return true;
}

static inline bool profanity_next_random_seed(
    uint32_t start_inclusive,
    uint32_t end_inclusive,
    ProfanityRandomSeedBlock& block,
    uint32_t& seed)
{
    if (block.remaining == 0ull &&
        !profanity_pick_random_seed_block(start_inclusive, end_inclusive, profanity_random_seeds_per_pick, block)) {
        return false;
    }

    seed = block.next_seed;
    --block.remaining;
    if (block.remaining > 0ull) {
        ++block.next_seed;
    }
    return true;
}

static inline uint64_t random_seed64_inclusive(uint64_t start_inclusive, uint64_t end_inclusive) {
    if (start_inclusive > end_inclusive) {
        std::swap(start_inclusive, end_inclusive);
    }
    if (start_inclusive == 0ull && end_inclusive == std::numeric_limits<uint64_t>::max()) {
        return random_u64_raw();
    }
    const uint64_t span = end_inclusive - start_inclusive + 1ull;
    const uint64_t threshold = static_cast<uint64_t>(-span) % span;
    uint64_t rnd = 0ull;
    do {
        rnd = random_u64_raw();
    } while (rnd < threshold);
    return start_inclusive + (rnd % span);
}

static inline bool apply_partition_for_thread(ThreadInputSnapshot& state,
    const MultiGpuPartitionKind kind,
    const char* mode_name,
    const size_t gpu_index,
    const size_t gpu_count) {
    switch (kind) {
    case MultiGpuPartitionKind::prng32: {
        uint32_t s = 0;
        uint32_t e = 0;
        if (!split_u32_range(state.start_seed, state.end_seed, gpu_index, gpu_count, s, e)) {
            return false;
        }
        state.start_seed = s;
        state.end_seed = e;
        return true;
    }
    case MultiGpuPartitionKind::prng64: {
        uint64_t s = 0;
        uint64_t e = 0;
        if (!split_u64_range(state.start_seed64, state.end_seed64, gpu_index, gpu_count, s, e)) {
            return false;
        }
        state.start_seed64 = s;
        state.end_seed64 = e;
        return true;
    }
    case MultiGpuPartitionKind::seq_forward:
    case MultiGpuPartitionKind::seq_backward:
    case MultiGpuPartitionKind::seq_both: {
        const uint64_t base_step = (state.step == 0ull) ? 1ull : state.step;
        uint64_t stepped = 0;
        if (!mul_u64_checked(base_step, static_cast<uint64_t>(gpu_count), stepped)) {
            return false;
        }
        state.step = stepped;

        const uint64_t round_size = generated_seq_round_size_for_mode(mode_name);
        if (round_size == 0ull) {
            return false;
        }
        uint64_t chunk_delta = 0;
        uint64_t delta = 0;
        if (!mul_u64_checked(base_step, round_size, chunk_delta) ||
            !mul_u64_checked(chunk_delta, static_cast<uint64_t>(gpu_index), delta)) {
            return false;
        }
        g_seq_kernel_step_override = base_step;

        if (kind == MultiGpuPartitionKind::seq_both) {
            g_seq_both_chunk_delta_override = delta;
            return true;
        }

        if (delta == 0ull) {
            return true;
        }

        const bool is_backward = (kind == MultiGpuPartitionKind::seq_backward);
        if (is_backward) {
            sub_scalar_from_be(state.start_pvk_point, sizeof(state.start_pvk_point), delta);
            sub_scalar_from_be(state.start_seed_point, sizeof(state.start_seed_point), delta);
            sub_scalar_from_be(state.start_entropy_point, sizeof(state.start_entropy_point), delta);
            sub_scalar_from_be(state.start_mnemonic_point, sizeof(state.start_mnemonic_point), delta);
            sub_scalar_from_be(state.start_brain_point, sizeof(state.start_brain_point), delta);
        }
        else {
            add_scalar_to_be(state.start_pvk_point, sizeof(state.start_pvk_point), delta);
            add_scalar_to_be(state.start_seed_point, sizeof(state.start_seed_point), delta);
            add_scalar_to_be(state.start_entropy_point, sizeof(state.start_entropy_point), delta);
            add_scalar_to_be(state.start_mnemonic_point, sizeof(state.start_mnemonic_point), delta);
            add_scalar_to_be(state.start_brain_point, sizeof(state.start_brain_point), delta);
        }
        return true;
    }
    case MultiGpuPartitionKind::random_mode: {
        if (prng_gen || prng64_gen) {
            if (prng_gen) {
                uint32_t s = 0u;
                uint32_t e = 0u;
                if (!split_u32_range(state.start_seed, state.end_seed, gpu_index, gpu_count, s, e)) {
                    return false;
                }
                state.start_seed = s;
                state.end_seed = e;
            }
            if (prng64_gen) {
                uint64_t s64 = 0ull;
                uint64_t e64 = 0ull;
                if (!split_u64_range(state.start_seed64, state.end_seed64, gpu_index, gpu_count, s64, e64)) {
                    return false;
                }
                state.start_seed64 = s64;
                state.end_seed64 = e64;
            }
            return true;
        }

        if (!split_be_range(state.start_pvk_point, state.end_pvk_point, sizeof(state.start_pvk_point), gpu_index, gpu_count, state.start_pvk_point, state.end_pvk_point)) {
            return false;
        }
        if (!split_be_range(state.start_seed_point, state.end_seed_point, sizeof(state.start_seed_point), gpu_index, gpu_count, state.start_seed_point, state.end_seed_point)) {
            return false;
        }
        if (!split_be_range(state.start_entropy_point, state.end_entropy_point, sizeof(state.start_entropy_point), gpu_index, gpu_count, state.start_entropy_point, state.end_entropy_point)) {
            return false;
        }
        if (!split_be_range(state.start_mnemonic_point, state.end_mnemonic_point, sizeof(state.start_mnemonic_point), gpu_index, gpu_count, state.start_mnemonic_point, state.end_mnemonic_point)) {
            return false;
        }
        if (!split_be_range(state.start_brain_point, state.end_brain_point, sizeof(state.start_brain_point), gpu_index, gpu_count, state.start_brain_point, state.end_brain_point)) {
            return false;
        }
        return true;
    }
    case MultiGpuPartitionKind::none:
    default:
        return true;
    }
}

template <typename Fn>
// dispatch_generated_mode_multi_gpu: dispatches generated mode multi GPU.
static metalError_t dispatch_generated_mode_multi_gpu(const char* mode_name, Fn&& worker_fn) {
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return worker_fn();
    }

    const MultiGpuPartitionKind kind = detect_partition_kind_for_generated_mode();
    if (kind == MultiGpuPartitionKind::none) {
        return worker_fn();
    }

    const auto mode_has = [mode_name](const char* needle) -> bool {
        return mode_name != nullptr && needle != nullptr && std::strstr(mode_name, needle) != nullptr;
    };
    const bool ada_direct_adjacent_mode =
        Ada && mode_name != nullptr &&
        ((mode_has("processMetalPRIV") &&
            (mode_has("Seq") || mode_has("Random") || mode_has("Gen") || mode_has("Hexset"))) ||
            (mode_has("processMetalBrain") &&
                (mode_has("Seq") || mode_has("Random") || mode_has("Gen") || mode_has("Hexset"))) ||
            (mode_has("processMetalOld") &&
                (mode_has("Seq") || mode_has("Random") || mode_has("Gen") || mode_has("Hexset"))) ||
            (mode_has("processMetalMINIKEYSSeed") &&
                (mode_has("Seq") || mode_has("Random") || mode_has("Gen"))));
    if (ada_direct_adjacent_mode) {
        const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
        metalError_t status = metalErrorInvalidDevice;
        if (!g_gpu_contexts.empty()) {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts.front())) {
                    return metalErrorInvalidDevice;
                }
            }

            g_disable_multi_gpu_dispatch = true;
            status = worker_fn();
            g_disable_multi_gpu_dispatch = false;

            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (metalSetDevice(g_gpu_contexts.front().device_id) == metalSuccess) {
                    g_gpu_contexts.front() = capture_current_gpu_context();
                }
                activate_gpu_context(g_gpu_contexts.front());
            }
            restore_thread_input_snapshot(base_snapshot);
        }
        return status;
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    workers.reserve(gpu_count);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            ThreadInputSnapshot local_snapshot = base_snapshot;
            if (!apply_partition_for_thread(local_snapshot, kind, mode_name, gpu_idx, gpu_count)) {
                statuses[gpu_idx] = metalSuccess;
                return;
            }
            restore_thread_input_snapshot(local_snapshot);
            /* MultiGPU: each GPU runs at full BLOCK_NUMBER; partition is by key space (prng/seq/random subranges). */
            if (seqMode) {
                metal_launch("SetSeqStep", 1, 1, effective_seq_kernel_step());
                const metalError_t seq_step_status = metalDeviceSynchronize();
                if (seq_step_status != metalSuccess) {
                    statuses[gpu_idx] = seq_step_status;
                    g_seq_kernel_step_override = 0ull;
                    g_seq_both_chunk_delta_override = 0ull;
                    return;
                }
            }

            g_disable_multi_gpu_dispatch = true;
            statuses[gpu_idx] = worker_fn();
            g_disable_multi_gpu_dispatch = false;
            g_seq_kernel_step_override = 0ull;
            g_seq_both_chunk_delta_override = 0ull;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) {
            th.join();
        }
    }

    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    metalError_t first_error = metalSuccess;
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            first_error = statuses[gpu_idx];
            fprintf(stderr, "[!] mode %s failed on GPU %d: %s [!]\n",
                mode_name,
                g_gpu_contexts[gpu_idx].device_id,
                metalGetErrorString(statuses[gpu_idx]));
            break;
        }
    }
    return first_error;
}

template <typename Fn>
// dispatch_recovery_mode_multi_gpu: dispatches recovery mode multi GPU.
static metalError_t dispatch_recovery_mode_multi_gpu(const char* mode_name, Fn&& worker_fn) {
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return worker_fn();
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    std::vector<uint64_t> tested_totals(gpu_count, 0ull);
    std::vector<uint64_t> emitted_totals(gpu_count, 0ull);
    workers.reserve(gpu_count);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            restore_thread_input_snapshot(base_snapshot);
            const RecoveryMultiGpuPartition previous_partition = g_recovery_multi_gpu_partition;
            g_recovery_multi_gpu_partition.enabled = true;
            g_recovery_multi_gpu_partition.index = gpu_idx;
            g_recovery_multi_gpu_partition.count = gpu_count;

            g_disable_multi_gpu_dispatch = true;
            statuses[gpu_idx] = worker_fn();
            g_disable_multi_gpu_dispatch = false;
            tested_totals[gpu_idx] = g_recovery_run_stats.tested_total;
            emitted_totals[gpu_idx] = g_recovery_run_stats.emitted_total;

            g_recovery_multi_gpu_partition = previous_partition;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) {
            th.join();
        }
    }

    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    metalError_t first_error = metalSuccess;
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            first_error = statuses[gpu_idx];
            fprintf(stderr, "[!] mode %s failed on GPU %d: %s [!]\n",
                mode_name,
                g_gpu_contexts[gpu_idx].device_id,
                metalGetErrorString(statuses[gpu_idx]));
            break;
        }
    }

    if (first_error == metalSuccess) {
        uint64_t tested_sum = 0ull;
        uint64_t emitted_sum = 0ull;
        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            tested_sum += tested_totals[gpu_idx];
            emitted_sum += emitted_totals[gpu_idx];
        }
        printf("[!] Recovery summary: tested=%llu checksum-valid=%llu [!]\n",
            static_cast<unsigned long long>(tested_sum),
            static_cast<unsigned long long>(emitted_sum));
        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            printf("[!] Recovery slot %llu/%llu (GPU %d): tested=%llu checksum-valid=%llu [!]\n",
                static_cast<unsigned long long>(gpu_idx + 1u),
                static_cast<unsigned long long>(gpu_count),
                g_gpu_contexts[gpu_idx].device_id,
                static_cast<unsigned long long>(tested_totals[gpu_idx]),
                static_cast<unsigned long long>(emitted_totals[gpu_idx]));
        }
    }

    return first_error;
}

template <typename Fn>
// dispatch_stream_mode_multi_gpu: dispatches stream mode multi GPU.
static metalError_t dispatch_stream_mode_multi_gpu(const char* mode_name, std::istream& shared_stream, Fn&& worker_fn) {
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return worker_fn(shared_stream);
    }

    if (Ada && mode_name != nullptr &&
        (std::strcmp(mode_name, "processMetalPRIV") == 0 ||
            std::strcmp(mode_name, "processMetalPRIVSWAP") == 0 ||
            std::strcmp(mode_name, "processMetalPRIVBYTE") == 0 ||
            std::strcmp(mode_name, "processMetalPRIVHASH") == 0 ||
            std::strcmp(mode_name, "processMetalPRIVPLUS256") == 0 ||
            std::strcmp(mode_name, "processMetalBrain") == 0 ||
            std::strcmp(mode_name, "processMetalMINIKEYSStream") == 0 ||
            std::strcmp(mode_name, "processMetalMINIKEYSSeed") == 0)) {
        const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
        metalError_t status = metalErrorInvalidDevice;
        if (!g_gpu_contexts.empty()) {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts.front())) {
                    return metalErrorInvalidDevice;
                }
            }

            g_disable_multi_gpu_dispatch = true;
            status = worker_fn(shared_stream);
            g_disable_multi_gpu_dispatch = false;

            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (metalSetDevice(g_gpu_contexts.front().device_id) == metalSuccess) {
                    g_gpu_contexts.front() = capture_current_gpu_context();
                }
                activate_gpu_context(g_gpu_contexts.front());
            }
            restore_thread_input_snapshot(base_snapshot);
        }
        return status;
    }

    {
        std::lock_guard<std::mutex> guard(g_shared_stream_registry_mutex);
        g_shared_input_streams.insert(&shared_stream);
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    workers.reserve(gpu_count);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            restore_thread_input_snapshot(base_snapshot);
            g_disable_multi_gpu_dispatch = true;
            statuses[gpu_idx] = worker_fn(shared_stream);
            g_disable_multi_gpu_dispatch = false;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) {
            th.join();
        }
    }
    {
        std::lock_guard<std::mutex> guard(g_shared_stream_registry_mutex);
        g_shared_input_streams.erase(&shared_stream);
    }
    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    metalError_t first_error = metalSuccess;
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            first_error = statuses[gpu_idx];
            fprintf(stderr, "[!] mode %s failed on GPU %d: %s [!]\n",
                mode_name,
                g_gpu_contexts[gpu_idx].device_id,
                metalGetErrorString(statuses[gpu_idx]));
            break;
        }
    }
    return first_error;
}

// delFile: deletes file.
bool delFile(const char* filePath) {
    if (std::remove(filePath) == 0) {
        std::cout << "\nFile successfully deleted. - " << filePath << std::endl;
        return true;
    }
    else {
        std::cerr << "\nError deleting file." << std::endl;
        return false;
    }
}

//combos

class BlockingPipeBuf final : public std::streambuf
{
public:
    explicit BlockingPipeBuf(size_t capacityBytes = (1u << 20))
        : cap_(std::max<size_t>(capacityBytes, 1)),
        q_(cap_)
    {
        setg(nullptr, nullptr, nullptr);
        setp(nullptr, nullptr);
    }

// close: marks the pipe as closed and wakes all waiting producers/consumers.
    void close()
    {
        {
            std::lock_guard<std::mutex> lk(m_);
            closed_ = true;
        }
        cv_not_empty_.notify_all();
        cv_not_full_.notify_all();
    }

// reset: clears queue state so the same pipe buffer can be reused.
    void reset()
    {
        std::lock_guard<std::mutex> lk(m_);
        read_pos_ = 0;
        write_pos_ = 0;
        size_ = 0;
        closed_ = false;
        setg(nullptr, nullptr, nullptr);
        setp(nullptr, nullptr);
        cv_not_empty_.notify_all();
        cv_not_full_.notify_all();
    }

protected:
    // overflow: pushes one character through the pipe write path.
    int_type overflow(int_type ch) override
    {
        if (traits_type::eq_int_type(ch, traits_type::eof()))
            return traits_type::not_eof(ch);

        const char c = traits_type::to_char_type(ch);
        return (xsputn(&c, 1) == 1) ? ch : traits_type::eof();
    }

    // xsputn: writes a block of data into the bounded ring buffer.
    std::streamsize xsputn(const char* s, std::streamsize n) override
    {
        if (n <= 0) return 0;

        std::streamsize written = 0;
        while (written < n)
        {
            std::unique_lock<std::mutex> lk(m_);
            cv_not_full_.wait(lk, [&] { return closed_ || size_ < cap_; });
            if (closed_) break;

            const size_t freeSpace = cap_ - size_;
            const std::streamsize canWrite =
                (std::streamsize)std::min<size_t>(freeSpace, (size_t)(n - written));

            const size_t canWriteU = static_cast<size_t>(canWrite);
            const size_t first = std::min(canWriteU, cap_ - write_pos_);
            memcpy(q_.data() + write_pos_, s + written, first);
            const size_t second = canWriteU - first;
            if (second) {
                memcpy(q_.data(), s + written + first, second);
            }
            write_pos_ = (write_pos_ + canWriteU) % cap_;
            size_ += canWriteU;
            written += canWrite;

            lk.unlock();
            cv_not_empty_.notify_one();
        }
        return written;
    }

    // sync: streambuf sync hook (nothing to flush for in-memory pipe).
    int sync() override
    {
        return 0;
    }

    // underflow: waits for data and exposes the next readable byte.
    int_type underflow() override
    {
        std::unique_lock<std::mutex> lk(m_);
        cv_not_empty_.wait(lk, [&] { return closed_ || size_ > 0; });

        if (size_ == 0 && closed_)
            return traits_type::eof();

        const size_t take = std::min<size_t>(READ_CHUNK_BYTES, size_);
        const size_t first = std::min(take, cap_ - read_pos_);
        memcpy(read_chunk_, q_.data() + read_pos_, first);
        const size_t second = take - first;
        if (second) {
            memcpy(read_chunk_ + first, q_.data(), second);
        }
        read_pos_ = (read_pos_ + take) % cap_;
        size_ -= take;
        setg(read_chunk_, read_chunk_, read_chunk_ + take);

        lk.unlock();
        cv_not_full_.notify_one();
        return traits_type::to_int_type(*gptr());
    }



private:
    static constexpr size_t READ_CHUNK_BYTES = 8192;

    size_t cap_;
    std::vector<char> q_;
    size_t read_pos_ = 0;
    size_t write_pos_ = 0;
    size_t size_ = 0;
    std::mutex m_;
    std::condition_variable cv_not_empty_;
    std::condition_variable cv_not_full_;
    bool closed_ = false;
    char read_chunk_[READ_CHUNK_BYTES];
};

BlockingPipeBuf g_pipe(1u << 24);
std::istream    g_pipe_in(&g_pipe);
std::ostream    g_pipe_out(&g_pipe);

// add_hex_counter_inplace: adds delta (base16) to nibble-array counter. Returns false on overflow.
static inline bool add_hex_counter_inplace(std::vector<uint8_t>& nibbles, uint64_t delta) {
    if (nibbles.empty()) {
        return false;
    }
    for (int pos = static_cast<int>(nibbles.size()) - 1; pos >= 0; --pos) {
        const uint32_t sum = static_cast<uint32_t>(nibbles[static_cast<size_t>(pos)]) + static_cast<uint32_t>(delta & 0x0Fu);
        nibbles[static_cast<size_t>(pos)] = static_cast<uint8_t>(sum & 0x0Fu);
        delta = (delta >> 4) + static_cast<uint64_t>(sum >> 4);
    }
    return delta == 0;
}

// hex_string_from_nibbles: formats nibble-array counter into lower-case hex string.
static inline std::string hex_string_from_nibbles(const std::vector<uint8_t>& nibbles) {
    std::string out;
    out.resize(nibbles.size());
    for (size_t i = 0; i < nibbles.size(); ++i) {
        const uint8_t v = static_cast<uint8_t>(nibbles[i] & 0x0Fu);
        out[i] = (v < 10u) ? static_cast<char>('0' + v) : static_cast<char>('a' + (v - 10u));
    }
    return out;
}

static constexpr char MINIKEY_BASE58_ALPHABET[] = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

// minikey_char_to_value: maps base58 character to value for mini keys.
static inline int minikey_char_to_value(const char c) {
    for (int i = 0; i < 58; ++i) {
        if (MINIKEY_BASE58_ALPHABET[i] == c) {
            return i;
        }
    }
    return -1;
}

// cmp_base58_counter: lexicographic compare for same-size big-endian base58 counters.
static inline int cmp_base58_counter(const std::vector<uint8_t>& a, const std::vector<uint8_t>& b) {
    if (a.size() != b.size()) {
        return (a.size() < b.size()) ? -1 : 1;
    }
    for (size_t i = 0; i < a.size(); ++i) {
        if (a[i] < b[i]) return -1;
        if (a[i] > b[i]) return 1;
    }
    return 0;
}

// add_base58_counter_inplace: adds delta (base58) to counter, returns false on overflow.
static inline bool add_base58_counter_inplace(std::vector<uint8_t>& digits, uint64_t delta) {
    if (digits.empty()) {
        return false;
    }
    for (int pos = static_cast<int>(digits.size()) - 1; pos >= 0; --pos) {
        const uint32_t sum = static_cast<uint32_t>(digits[static_cast<size_t>(pos)]) + static_cast<uint32_t>(delta % 58ull);
        digits[static_cast<size_t>(pos)] = static_cast<uint8_t>(sum % 58u);
        delta = (delta / 58ull) + static_cast<uint64_t>(sum / 58u);
    }
    return delta == 0ull;
}

// minikey_string_from_suffix: formats mini key as S + base58 suffix digits.
static inline std::string minikey_string_from_suffix(const std::vector<uint8_t>& suffix) {
    std::string out;
    out.reserve(suffix.size() + 1u);
    out.push_back('S');
    for (size_t i = 0; i < suffix.size(); ++i) {
        const uint8_t v = suffix[i];
        if (v < 58u) out.push_back(MINIKEY_BASE58_ALPHABET[v]);
        else out.push_back('?');
    }
    return out;
}

// parse_minikey_argument: parses full mini key (S...) or suffix-only value.
static inline bool parse_minikey_argument(const std::string& raw, int& total_len, std::vector<uint8_t>& suffix, std::string* err = nullptr) {
    std::string s = raw;
    size_t begin = 0;
    size_t end = s.size();
    while (begin < end && std::isspace(static_cast<unsigned char>(s[begin]))) ++begin;
    while (end > begin && std::isspace(static_cast<unsigned char>(s[end - 1]))) --end;
    s = s.substr(begin, end - begin);

    if (s.empty()) {
        if (err) *err = "empty mini key";
        return false;
    }

    bool has_prefix = false;
    if (!s.empty() && (s[0] == 'S' || s[0] == 's')) {
        has_prefix = true;
        s[0] = 'S';
    }

    total_len = has_prefix ? static_cast<int>(s.size()) : static_cast<int>(s.size() + 1u);
    if (!(total_len == 22 || total_len == 26 || total_len == 30)) {
        if (err) *err = "length must be 22/26/30 (with S) or 21/25/29 (suffix)";
        return false;
    }

    const size_t suffix_begin = has_prefix ? 1u : 0u;
    const size_t suffix_len = static_cast<size_t>(total_len - 1);
    if ((s.size() - suffix_begin) != suffix_len) {
        if (err) *err = "invalid suffix length";
        return false;
    }

    suffix.assign(suffix_len, 0u);
    for (size_t i = 0; i < suffix_len; ++i) {
        const int value = minikey_char_to_value(s[suffix_begin + i]);
        if (value < 0) {
            if (err) *err = "contains non-base58 character";
            return false;
        }
        suffix[i] = static_cast<uint8_t>(value);
    }
    return true;
}

// minikey_casascius_check: validates SHA256(minikey + "?")[0] == 0.
static inline bool minikey_casascius_check(const std::string& minikey) {
    if (!(minikey.size() == 22u || minikey.size() == 26u || minikey.size() == 30u)) {
        return false;
    }
    uint8_t msg[31] = { 0 };
    for (size_t i = 0; i < minikey.size(); ++i) {
        msg[i] = static_cast<uint8_t>(minikey[i]);
    }
    msg[minikey.size()] = static_cast<uint8_t>('?');
    uint8_t digest[32] = { 0 };
    sha256(msg, minikey.size() + 1u, digest);
    return digest[0] == 0u;
}

// normalize_minikey_candidate: parses full/suffix mini key and applies Casascius check.
static inline bool normalize_minikey_candidate(const std::string& raw, std::string& out_minikey) {
    int total_len = 0;
    std::vector<uint8_t> suffix;
    if (!parse_minikey_argument(raw, total_len, suffix, nullptr)) {
        return false;
    }
    out_minikey = minikey_string_from_suffix(suffix);
    if (out_minikey.size() != static_cast<size_t>(total_len)) {
        return false;
    }
    return minikey_casascius_check(out_minikey);
}

// random_base58_counter_inclusive: random value in [start, end] for equal-size base58 counters.
static inline bool random_base58_counter_inclusive(const std::vector<uint8_t>& start, const std::vector<uint8_t>& end, std::vector<uint8_t>& out) {
    if (start.size() != end.size() || start.empty()) {
        return false;
    }
    if (cmp_base58_counter(start, end) > 0) {
        return false;
    }

    out.resize(start.size());
    bool tight_low = true;
    bool tight_high = true;
    for (size_t i = 0; i < start.size(); ++i) {
        const uint8_t low = tight_low ? start[i] : 0u;
        const uint8_t high = tight_high ? end[i] : 57u;
        const uint8_t pick = static_cast<uint8_t>(random_seed32_inclusive(low, high));
        out[i] = pick;
        tight_low = tight_low && (pick == low);
        tight_high = tight_high && (pick == high);
    }
    return true;
}

// build_minikey_ranges_from_args: prepares mini key ranges based on -start/-end.
static inline bool build_minikey_ranges_from_args(std::vector<MiniKeyRange>& out_ranges, std::string& err) {
    out_ranges.clear();
    err.clear();

    const bool has_start = seqMode;
    const bool has_end = end_point_set;

    int start_len = MINIKEY_TOTAL_LENGTHS[0];
    int end_len = MINIKEY_TOTAL_LENGTHS[2];
    std::vector<uint8_t> start_suffix;
    std::vector<uint8_t> end_suffix;

    if (has_start) {
        if (!parse_minikey_argument(start_point, start_len, start_suffix, &err)) {
            err = "invalid -start for -minikeys: " + err;
            return false;
        }
    }
    if (has_end) {
        if (!parse_minikey_argument(end_point, end_len, end_suffix, &err)) {
            err = "invalid -end for -minikeys: " + err;
            return false;
        }
    }

    if (has_start && !has_end) {
        end_len = start_len;
        end_suffix.assign(static_cast<size_t>(end_len - 1), 57u);
    }
    else if (!has_start && has_end) {
        start_len = end_len;
        start_suffix.assign(static_cast<size_t>(start_len - 1), 0u);
    }
    else if (!has_start && !has_end) {
        start_suffix.clear();
        end_suffix.clear();
    }

    if (start_len > end_len) {
        err = "start mini key type must not be greater than end type";
        return false;
    }
    if (has_start && has_end && start_len == end_len && cmp_base58_counter(start_suffix, end_suffix) > 0) {
        err = "start mini key must be <= end mini key for the same type";
        return false;
    }

    for (const int len : MINIKEY_TOTAL_LENGTHS) {
        if (len < start_len || len > end_len) {
            continue;
        }

        MiniKeyRange range;
        range.total_len = len;
        range.suffix_len = static_cast<uint8_t>(len - 1);
        range.start.assign(static_cast<size_t>(range.suffix_len), 0u);
        range.end.assign(static_cast<size_t>(range.suffix_len), 57u);

        if (has_start && len == start_len) {
            range.start = start_suffix;
        }
        if (has_end && len == end_len) {
            range.end = end_suffix;
        }
        if (cmp_base58_counter(range.start, range.end) > 0) {
            err = "invalid mini key range for length " + std::to_string(len);
            return false;
        }
        out_ranges.emplace_back(std::move(range));
    }

    if (out_ranges.empty()) {
        err = "empty mini key range set";
        return false;
    }
    return true;
}

// minikey_seed_collect_sizes: validates and normalizes -size/-sizes for -minikeys -seed.
static inline bool minikey_seed_collect_sizes(std::vector<uint8_t>& out_sizes, std::string& err) {
    out_sizes.clear();
    err.clear();

    if (Sizes.empty()) {
        out_sizes.push_back(22u);
        out_sizes.push_back(26u);
        out_sizes.push_back(30u);
        return true;
    }

    bool use22 = false;
    bool use26 = false;
    bool use30 = false;
    for (const int raw_size : Sizes) {
        if (raw_size == 22) {
            use22 = true;
        }
        else if (raw_size == 26) {
            use26 = true;
        }
        else if (raw_size == 30) {
            use30 = true;
        }
        else {
            err = "invalid -size/-sizes value for -minikeys -seed: " + std::to_string(raw_size) + " (allowed: 22,26,30)";
            return false;
        }
    }

    if (use22) out_sizes.push_back(22u);
    if (use26) out_sizes.push_back(26u);
    if (use30) out_sizes.push_back(30u);

    if (out_sizes.empty()) {
        err = "empty -size/-sizes set for -minikeys -seed";
        return false;
    }
    return true;
}

// parse_seed_hex_point64: parses hex point (up to 64 bytes) into fixed 64-byte big-endian buffer.
static inline bool parse_seed_hex_point64(const std::string& raw_input, uint8_t out64[64], int* out_effective_len, std::string& err) {
    if (out64 == nullptr) {
        err = "internal error: null output buffer";
        return false;
    }

    std::string s = raw_input;
    size_t begin = 0;
    size_t end = s.size();
    while (begin < end && std::isspace(static_cast<unsigned char>(s[begin]))) ++begin;
    while (end > begin && std::isspace(static_cast<unsigned char>(s[end - 1]))) --end;
    s = s.substr(begin, end - begin);

    if (s.size() >= 2u && s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
        s.erase(0, 2);
    }
    if (s.empty()) {
        err = "empty hex seed point";
        return false;
    }

    for (const char c : s) {
        if (!std::isxdigit(static_cast<unsigned char>(c))) {
            err = "seed point must be HEX";
            return false;
        }
    }

    size_t effective_hex_len = s.size();
    if (effective_hex_len > 128u) {
        s = s.substr(effective_hex_len - 128u);
        effective_hex_len = 128u;
    }

    if ((s.size() & 1u) != 0u) {
        s.insert(s.begin(), '0');
    }

    char padded[129] = { 0 };
    memset(padded, '0', 128);
    const size_t copy_len = s.size();
    memcpy(padded + (128u - copy_len), s.data(), copy_len);
    unhex_host(reinterpret_cast<unsigned char*>(padded), 128u, out64, 64u);

    if (out_effective_len != nullptr) {
        int bytes_len = static_cast<int>((effective_hex_len + 1u) / 2u);
        if (bytes_len < 1) bytes_len = 1;
        if (bytes_len > 64) bytes_len = 64;
        *out_effective_len = bytes_len;
    }
    return true;
}

// minikey_seed_point_to_hex: formats 64-byte point into hex string.
static inline std::string minikey_seed_point_to_hex(const uint8_t point[64]) {
    unsigned char hexed[129] = { 0 };
    unsigned char tmp[64];
    memcpy(tmp, point, sizeof(tmp));
    hex(tmp, 64u, hexed, sizeof(hexed));
    return std::string(reinterpret_cast<const char*>(hexed));
}

// configure_minikey_seed_seq_points_from_args: parses -start/-end into seed points for -minikeys -seed.
static inline bool configure_minikey_seed_seq_points_from_args(std::string& err) {
    err.clear();

    if (!seqMode && !end_point_set) {
        return true;
    }

    int start_len = min_len;
    if (seqMode) {
        if (!parse_seed_hex_point64(start_point, start_seed_point, &start_len, err)) {
            err = "invalid -start for -minikeys -seed: " + err;
            return false;
        }
        min_len = start_len;
    }
    else {
        memset(start_seed_point, 0, 64);
    }

    if (end_point_set) {
        if (!parse_seed_hex_point64(end_point, end_seed_point, nullptr, err)) {
            err = "invalid -end for -minikeys -seed: " + err;
            return false;
        }
    }
    else {
        memset(end_seed_point, 0xFF, 64);
    }

    if (cmp_host(start_seed_point, end_seed_point, 64) > 0) {
        err = "start seed point must be <= end seed point";
        return false;
    }
    return true;
}

// ReadWords: reads words.
static std::vector<std::string> ReadWords(std::istream& in, size_t maxWords = 9999999)
{
    std::vector<std::string> words;
    words.reserve(std::min<size_t>(maxWords, 1u << 16));

    std::string w;
    while (words.size() < maxWords && (in >> w))
        words.push_back(std::move(w));

    return words;
}

static inline void WriteCombo(const std::vector<std::string>& words,
    const std::vector<int>& idx,
    bool space)
{
    static thread_local std::string line;
    line.clear();

    size_t total = 1;
    if (!idx.empty()) {
        if (space && idx.size() > 1) {
            total += idx.size() - 1;
        }
        for (size_t i = 0; i < idx.size(); ++i) {
            total += words[(size_t)idx[i]].size();
        }
    }
    if (line.capacity() < total) {
        line.reserve(total);
    }

    for (size_t i = 0; i < idx.size(); ++i)
    {
        if (i && space) {
            line.push_back(' ');
        }
        line.append(words[(size_t)idx[i]]);
    }
    line.push_back('\n');
    g_pipe_out.write(line.data(), (std::streamsize)line.size());

    if (!g_pipe_out.good()) return;
}

static void GenRep(const std::vector<std::string>& words,
    std::vector<int>& idx,
    int pos,
    bool space)
{
    if (!g_pipe_out.good()) return;

    const int k = (int)idx.size();
    if (pos == k) { WriteCombo(words, idx, space); return; }

    const int n = (int)words.size();
    for (int i = 0; i < n; ++i)
    {
        idx[pos] = i;
        GenRep(words, idx, pos + 1, space);
        if (!g_pipe_out.good()) return;
    }
}

static void GenNoRep(const std::vector<std::string>& words,
    std::vector<int>& idx,
    std::vector<unsigned char>& used,
    int pos,
    bool space)
{
    if (!g_pipe_out.good()) return;

    const int k = (int)idx.size();
    if (pos == k) { WriteCombo(words, idx, space); return; }

    const int n = (int)words.size();
    for (int i = 0; i < n; ++i)
    {
        if (used[(size_t)i]) continue;
        used[(size_t)i] = 1;
        idx[pos] = i;

        GenNoRep(words, idx, used, pos + 1, space);

        used[(size_t)i] = 0;
        if (!g_pipe_out.good()) return;
    }
}

void EmitCombinations(std::istream& in,
    const std::vector<int>& comb,
    bool space,
    bool rep)
{
    std::vector<std::string> words = ReadWords(in, 9999999);
    if (words.empty()) return;

    for (int k : comb)
    {
        if (k <= 0) continue;
        if (!rep && k > (int)words.size()) continue;

        std::vector<int> idx((size_t)k, 0);

        if (rep)
        {
            GenRep(words, idx, 0, space);
        }
        else
        {
            std::vector<unsigned char> used(words.size(), 0);
            GenNoRep(words, idx, used, 0, space);
        }

        if (!g_pipe_out.good()) return;
    }
}

// recovery_trim_spaces_copy: recovery mode helper that trims spaces copy.
static std::string recovery_trim_spaces_copy(const std::string& in) {
    size_t b = 0;
    size_t e = in.size();
    while (b < e && std::isspace(static_cast<unsigned char>(in[b])) != 0) {
        ++b;
    }
    while (e > b && std::isspace(static_cast<unsigned char>(in[e - 1])) != 0) {
        --e;
    }
    return in.substr(b, e - b);
}

// recovery_is_ascii: recovery mode helper that checks whether ascii is valid.
static bool recovery_is_ascii(const std::string& s) {
    for (const unsigned char c : s) {
        if (c >= 128u) return false;
    }
    return true;
}

// recovery_norm_token: recovery mode helper that normalizes token.
static std::string recovery_norm_token(const std::string& in) {
    if (!recovery_is_ascii(in)) {
        return in;
    }
    std::string out = in;
    for (char& c : out) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return out;
}

// recovery_split_tokens: recovery mode helper that splits tokens.
static std::vector<std::string> recovery_split_tokens(const std::string& phrase) {
    std::vector<std::string> out;
    std::istringstream iss(phrase);
    std::string token;
    while (iss >> token) {
        out.emplace_back(std::move(token));
    }
    return out;
}

static size_t recovery_levenshtein(const std::string& a, const std::string& b) {
    const size_t n = a.size();
    const size_t m = b.size();
    if (n == 0) return m;
    if (m == 0) return n;

    std::vector<size_t> prev(m + 1);
    std::vector<size_t> curr(m + 1);
    for (size_t j = 0; j <= m; ++j) prev[j] = j;

    for (size_t i = 1; i <= n; ++i) {
        curr[0] = i;
        for (size_t j = 1; j <= m; ++j) {
            const size_t cost = (a[i - 1] == b[j - 1]) ? 0u : 1u;
            const size_t delv = prev[j] + 1u;
            const size_t insv = curr[j - 1] + 1u;
            const size_t sub = prev[j - 1] + cost;
            curr[j] = std::min(std::min(delv, insv), sub);
        }
        prev.swap(curr);
    }
    return prev[m];
}

// recovery_path_filename: extracts a filename from path string with slash normalization.
static std::string recovery_path_filename(const std::string& path) {
    const size_t p1 = path.find_last_of('/');
    if (p1 == std::string::npos) return path;
    return path.substr(p1 + 1);
}

// recovery_norm_file_id: recovery mode helper that normalizes file id.
static std::string recovery_norm_file_id(const std::string& raw) {
    std::string name = recovery_path_filename(raw);
    name = recovery_norm_token(name);
    const size_t dot = name.find_last_of('.');
    if (dot != std::string::npos) {
        name = name.substr(0, dot);
    }
    return name;
}

// recovery_detect_device_lang: recovery mode helper that detects device lang.
static int recovery_detect_device_lang(const std::string& id_norm, const std::string& file_norm) {
    const std::string key = id_norm + "|" + file_norm;

    auto has_token = [&](const char* token) -> bool {
        return (id_norm.find(token) != std::string::npos) ||
            (file_norm.find(token) != std::string::npos) ||
            (key.find(token) != std::string::npos);
        };

    if (has_token("bip39_en") || has_token("_en") || has_token("english")) return 0;
    if (has_token("bip39_es") || has_token("bip39_sp") || has_token("_es") || has_token("spanish")) return 1;
    if (has_token("bip39_ja") || has_token("_ja") || has_token("japanese")) return 2;
    if (has_token("bip39_it") || has_token("_it") || has_token("italian")) return 3;
    if (has_token("bip39_fr") || has_token("_fr") || has_token("french")) return 4;
    if (has_token("bip39_cs") || has_token("_cs") || has_token("czech")) return 5;
    if (has_token("bip39_pt") || has_token("_pt") || has_token("portuguese")) return 6;
    if (has_token("bip39_ko") || has_token("_ko") || has_token("korean")) return 7;
    if (has_token("bip39_zh_hans") || has_token("zh_hans") || has_token("chinese_simplified")) return 8;
    if (has_token("bip39_zh_hant") || has_token("zh_hant") || has_token("chinese_traditional")) return 9;
    return -1;
}

// recovery_add_embedded_wordlist: recovery mode helper that adds embedded wordlist.
static bool recovery_add_embedded_wordlist(const RecoveryEmbeddedWordlistView& view, RecoveryWordlist& out, std::string& err) {
    out = RecoveryWordlist{};
    out.id = view.id;
    out.file_name = view.file_name;
    out.path = view.file_name;
    out.name = view.file_name;
    out.external = false;
    out.device_lang = recovery_detect_device_lang(recovery_norm_token(out.id), recovery_norm_token(out.file_name));
    out.words.reserve(view.count);
    out.words_norm.reserve(view.count);
    out.id_by_norm.reserve(view.count * 2u);

    for (std::size_t i = 0; i < view.count; ++i) {
        const char* w = view.words[i];
        if (w == nullptr || *w == '\0') continue;

        const int idx = static_cast<int>(out.words.size());
        out.words.emplace_back(w);
        const std::string norm = recovery_norm_token(out.words.back());
        out.words_norm.emplace_back(norm);
        if (out.id_by_norm.find(norm) == out.id_by_norm.end()) {
            out.id_by_norm.emplace(norm, idx);
        }
    }

    if (out.words.empty()) {
        err = "embedded wordlist is empty: " + out.file_name;
        return false;
    }
    return true;
}

// recovery_add_file_wordlist: recovery mode helper that adds file wordlist.
static bool recovery_add_file_wordlist(const std::string& path, RecoveryWordlist& out, std::string& err) {
    out = RecoveryWordlist{};

    std::ifstream fin(path.c_str(), std::ios::binary);
    tune_ifstream_buffer(fin);
    if (!fin) {
        err = "failed to open external wordlist: " + path;
        return false;
    }

    out.path = path;
    out.file_name = recovery_path_filename(path);
    out.id = recovery_norm_file_id(path);
    out.name = out.file_name;
    out.external = true;
    out.device_lang = -1;
    out.words.reserve(2048u);
    out.words_norm.reserve(2048u);
    out.id_by_norm.reserve(4096u);

    std::string line;
    size_t line_no = 0;
    bool first_line = true;
    while (read_trimmed_line(fin, line, 4096u)) {
        ++line_no;
        line = recovery_trim_spaces_copy(line);
        if (line.empty()) {
            continue;
        }

        if (first_line && line.size() >= 3u &&
            static_cast<unsigned char>(line[0]) == 0xEFu &&
            static_cast<unsigned char>(line[1]) == 0xBBu &&
            static_cast<unsigned char>(line[2]) == 0xBFu) {
            line.erase(0u, 3u);
            line = recovery_trim_spaces_copy(line);
            if (line.empty()) {
                first_line = false;
                continue;
            }
        }
        first_line = false;

        if (!line.empty() && line[0] == '#') {
            continue;
        }

        bool has_space = false;
        for (const unsigned char c : line) {
            if (std::isspace(c) != 0) {
                has_space = true;
                break;
            }
        }
        if (has_space) {
            err = "invalid external wordlist line (contains spaces) at line " + std::to_string(line_no);
            return false;
        }

        const int idx = static_cast<int>(out.words.size());
        out.words.emplace_back(line);
        const std::string norm = recovery_norm_token(out.words.back());
        if (out.id_by_norm.find(norm) != out.id_by_norm.end()) {
            err = "duplicate word in external wordlist at line " + std::to_string(line_no);
            return false;
        }
        out.words_norm.emplace_back(norm);
        out.id_by_norm.emplace(norm, idx);
    }

    if (out.words.empty()) {
        err = "external wordlist is empty: " + path;
        return false;
    }

    if (out.words.size() != 2048u) {
        err = "external wordlist must contain exactly 2048 words for BIP39 checksum mode";
        return false;
    }

    return true;
}

// recovery_find_best_word_id: recovery mode helper that finds best word id.
static int recovery_find_best_word_id(const RecoveryWordlist& wl, const std::string& token_norm, size_t* out_dist) {
    auto it = wl.id_by_norm.find(token_norm);
    if (it != wl.id_by_norm.end()) {
        if (out_dist) *out_dist = 0;
        return it->second;
    }

    size_t best_dist = std::numeric_limits<size_t>::max();
    int best_id = -1;
    for (size_t i = 0; i < wl.words_norm.size(); ++i) {
        const std::string& cand = wl.words_norm[i];
        const size_t d = recovery_levenshtein(token_norm, cand);
        if (d < best_dist) {
            best_dist = d;
            best_id = static_cast<int>(i);
            if (best_dist == 1u) {
                break;
            }
        }
    }
    if (out_dist) *out_dist = best_dist;
    return best_id;
}

// recovery_pick_wordlist: recovery mode helper that selects wordlist.
static const RecoveryWordlist* recovery_pick_wordlist(const std::vector<RecoveryWordlist>& lists,
    const std::vector<std::string>& tokens) {
    if (lists.empty()) return nullptr;
    if (lists.size() == 1u) return &lists[0];

    int best_exact = -1;
    size_t best_penalty = std::numeric_limits<size_t>::max();
    size_t best_words = std::numeric_limits<size_t>::max();
    const RecoveryWordlist* best = &lists[0];

    for (const RecoveryWordlist& wl : lists) {
        int exact = 0;
        size_t penalty = 0;

        for (const std::string& token : tokens) {
            if (token == "*") continue;
            const std::string norm = recovery_norm_token(token);
            auto it = wl.id_by_norm.find(norm);
            if (it != wl.id_by_norm.end()) {
                ++exact;
                continue;
            }

            size_t dist = 0;
            (void)recovery_find_best_word_id(wl, norm, &dist);
            penalty += dist;
        }

        if (exact > best_exact ||
            (exact == best_exact && penalty < best_penalty) ||
            (exact == best_exact && penalty == best_penalty && wl.words.size() < best_words)) {
            best_exact = exact;
            best_penalty = penalty;
            best_words = wl.words.size();
            best = &wl;
        }
    }

    return best;
}

// recovery_format_scientific: recovery mode helper that formats scientific.
static std::string recovery_format_scientific(const long double v) {
    std::ostringstream oss;
    oss << std::scientific << std::setprecision(6) << static_cast<double>(v);
    return oss.str();
}

// recovery_join_tokens: recovery mode helper that joins tokens.
static std::string recovery_join_tokens(const std::vector<std::string>& tokens) {
    std::string out;
    size_t total = 0;
    for (const std::string& t : tokens) total += t.size();
    if (!tokens.empty()) total += tokens.size() - 1u;
    out.reserve(total);
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i) out.push_back(' ');
        out.append(tokens[i]);
    }
    return out;
}

// recovery_prepare_task: recovery mode helper that prepares task.
static bool recovery_prepare_task(
    const RecoveryTemplateInput& in,
    const std::vector<RecoveryWordlist>& lists,
    RecoveryPreparedTask& out,
    std::string& err) {

    std::vector<std::string> tokens = recovery_split_tokens(in.phrase);
    if (tokens.empty()) {
        err = "empty phrase";
        return false;
    }

    size_t added_stars = 0;
    while (tokens.size() < 3u || (tokens.size() % 3u) != 0u) {
        tokens.emplace_back("*");
        ++added_stars;
    }
    if (tokens.size() > 48u) {
        err = "word count is greater than 48 after normalization";
        return false;
    }

    const RecoveryWordlist* wl = recovery_pick_wordlist(lists, tokens);
    if (wl == nullptr) {
        err = "no wordlists available";
        return false;
    }

    out = RecoveryPreparedTask{};
    out.source = in.source;
    out.line_no = in.line_no;
    out.wordlist = wl;
    out.added_stars = added_stars;
    out.ids.assign(tokens.size(), -1);

    for (size_t i = 0; i < tokens.size(); ++i) {
        if (tokens[i] == "*") {
            out.missing_positions.emplace_back(static_cast<int>(i));
            continue;
        }

        const std::string norm = recovery_norm_token(tokens[i]);
        size_t dist = 0;
        const int best_id = recovery_find_best_word_id(*wl, norm, &dist);
        if (best_id < 0 || static_cast<size_t>(best_id) >= wl->words.size()) {
            err = "failed to find replacement for token: " + tokens[i];
            return false;
        }

        out.ids[i] = best_id;
        if (dist != 0 || wl->words_norm[best_id] != norm) {
            out.replacements.emplace_back(tokens[i], wl->words[best_id]);
            tokens[i] = wl->words[best_id];
        }
    }

    out.normalized_phrase = recovery_join_tokens(tokens);
    return true;
}

// recovery_bip39_checksum_valid: recovery mode helper that checks whether BIP39 checksum is valid.
static bool recovery_bip39_checksum_valid(const std::vector<int>& ids) {
    const int n = static_cast<int>(ids.size());
    if (n <= 0 || (n % 3) != 0) return false;
    for (int i = 0; i < n; ++i) {
        if (ids[i] < 0 || ids[i] > 2047) return false;
    }

    const int total_bits = n * 11;
    const int ent_bits = (total_bits * 32) / 33;
    const int cs_bits = total_bits - ent_bits;
    if (cs_bits <= 0) return false;

    const int bits_bytes = (total_bits + 7) >> 3;
    std::vector<uint8_t> bits(static_cast<size_t>(bits_bytes), 0u);

    int bitpos = 0;
    for (int i = 0; i < n; ++i) {
        const int v = ids[i] & 0x7FF;
        for (int b = 10; b >= 0; --b) {
            const int bit = (v >> b) & 1;
            bits[static_cast<size_t>(bitpos >> 3)] |= static_cast<uint8_t>(bit << (7 - (bitpos & 7)));
            ++bitpos;
        }
    }

    const int ent_bytes = (ent_bits + 7) >> 3;
    std::vector<uint8_t> entropy(static_cast<size_t>(ent_bytes), 0u);
    for (int i = 0; i < ent_bytes; ++i) {
        entropy[static_cast<size_t>(i)] = bits[static_cast<size_t>(i)];
    }
    if ((ent_bits & 7) != 0 && !entropy.empty()) {
        entropy.back() &= static_cast<uint8_t>(0xFFu << (8 - (ent_bits & 7)));
    }

    uint8_t digest[32] = { 0 };
    sha256(entropy.data(), entropy.size(), digest);

    for (int i = 0; i < cs_bits; ++i) {
        const int phrase_bit_pos = ent_bits + i;
        const uint8_t phrase_bit = (bits[static_cast<size_t>(phrase_bit_pos >> 3)] >> (7 - (phrase_bit_pos & 7))) & 1u;
        const uint8_t digest_bit = (digest[static_cast<size_t>(i >> 3)] >> (7 - (i & 7))) & 1u;
        if (phrase_bit != digest_bit) {
            return false;
        }
    }

    return true;
}

// recovery_direct_release: recovery mode helper that releases the related data for direct.
static void recovery_direct_release(RecoveryGpuDirectContext& ctx) {
    if (ctx.devIndexes) {
        metalFree(ctx.devIndexes);
        ctx.devIndexes = nullptr;
    }
    if (ctx.devLines) {
        metalFree(ctx.devLines);
        ctx.devLines = nullptr;
    }
    if (ctx.devDerivationList) {
        metalFree(ctx.devDerivationList);
        ctx.devDerivationList = nullptr;
    }
    if (ctx.devDerIndex) {
        metalFree(ctx.devDerIndex);
        ctx.devDerIndex = nullptr;
    }
    if (ctx.devIter) {
        metalFree(ctx.devIter);
        ctx.devIter = nullptr;
    }
    if (ctx.devRecoveryDict) {
        metalFree(ctx.devRecoveryDict);
        ctx.devRecoveryDict = nullptr;
    }
    ctx.kernel_inflight = false;
    ctx.combined.clear();
    ctx.indexes.clear();
    ctx.devRecoveryDictWords = 0;
    ctx.activeWordlist = nullptr;
}

// recovery_direct_sync_previous: recovery mode helper that synchronizes previous for direct.
static metalError_t recovery_direct_sync_previous(RecoveryGpuDirectContext& ctx) {
    if (!ctx.kernel_inflight) {
        return metalSuccess;
    }
    metalError_t st = metalDeviceSynchronize();
    if (st != metalSuccess) {
        return st;
    }
    if (read_result_flag_host(ctx.buffIsResult)) {
        clear_result_flag_host(ctx.buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
    ctx.kernel_inflight = false;
    return metalSuccess;
}

// recovery_direct_launch_current_batch: recovery mode helper that launches current batch for direct.
static metalError_t recovery_direct_launch_current_batch(RecoveryGpuDirectContext& ctx, const uint32_t nr) {
    if (nr == 0u) {
        return metalSuccess;
    }

    metalError_t st = recovery_direct_sync_previous(ctx);
    if (st != metalSuccess) {
        return st;
    }

    st = copy_to_device_grow(reinterpret_cast<void**>(&ctx.devLines), ctx.combined.data(), ctx.combined.size());
    if (st != metalSuccess) {
        return st;
    }
    st = copy_to_device_grow(reinterpret_cast<void**>(&ctx.devIndexes), ctx.indexes.data(), ctx.indexes.size() * sizeof(uint32_t));
    if (st != metalSuccess) {
        return st;
    }

    auto launch_kernel = [&](const uint32_t pass_len, const uint32_t pass_count) -> metalError_t {
        metal_launch("worker", BLOCK_NUMBER, BLOCK_THREADS, ctx.buffIsResult, ctx.buffDeviceResult, _dev_precomp, pitch, ctx.devLines, ctx.devIndexes, nr, ctx.devDerivationList, ctx.devDerIndex, derIndex_size, 0, passwords_dev, pass_len, pass_count, Rounds, MNEMONIC_MODE, ctx.devIter, ctx.iteration_size, IS_STRING, dub_mnem);

        metalError_t launch_st = metalGetLastError();
        if (launch_st == metalSuccess) {
            if (!MNEMONIC_SCRAMBLE_MODE) {
                counterTotal += static_cast<uint64_t>(nr) *
                    static_cast<uint64_t>(Iterations.size());
            }
            ctx.kernel_inflight = true;
        }
        return launch_st;
    };

    if (pass_set) {
        bool launched_any = false;

        for (size_t i = 0; i < passwords_files.size(); ++i) {
            const std::string& fname = passwords_files[i];
            std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
            if (pass_stream == nullptr) {
                continue;
            }
            std::string password_line;
            while (read_trimmed_line(*pass_stream, password_line, 128)) {
                st = recovery_direct_sync_previous(ctx);
                if (st != metalSuccess) {
                    return st;
                }
                st = copy_password_to_device(password_line.data(), password_line.size());
                if (st != metalSuccess) {
                    return st;
                }
                st = launch_kernel(static_cast<uint32_t>(password_line.size()), 0u);
                if (st != metalSuccess) {
                    return st;
                }
                launched_any = true;
            }
        }

        for (size_t i = 0; i < passwords_list.size(); ++i) {
            const std::string password_line = passwords_list[i];
            st = recovery_direct_sync_previous(ctx);
            if (st != metalSuccess) {
                return st;
            }
            st = copy_password_to_device(password_line.data(), password_line.size());
            if (st != metalSuccess) {
                return st;
            }
            st = launch_kernel(static_cast<uint32_t>(password_line.size()), 0u);
            if (st != metalSuccess) {
                return st;
            }
            launched_any = true;
        }

        if (pass_brute) {
            uint8_t start_pass_point_local[128];
            memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
            uint64_t start_pass[16];
            uint64_t start_pass_plus[16];
            int pass_len = 0;

            array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
            pass_len = sizeBE_64(start_pass, 16);
            if (pass_len < min_pass_len) {
                pass_len = min_pass_len;
            }

            while (true) {
                int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                if (result > 0) {
                    break;
                }

                st = recovery_direct_sync_previous(ctx);
                if (st != metalSuccess) {
                    return st;
                }
                st = copy_password_to_device(&start_pass_point_local[128 - pass_len], static_cast<size_t>(pass_len));
                if (st != metalSuccess) {
                    return st;
                }
                st = launch_kernel(static_cast<uint32_t>(pass_len), 0u);
                if (st != metalSuccess) {
                    return st;
                }
                launched_any = true;

                array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                add64to1024_host(start_pass, 1, start_pass_plus);
                array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                pass_len = sizeBE_64(start_pass_plus, 16);
                if (pass_len < min_pass_len) {
                    pass_len = min_pass_len;
                }
            }
        }

        if (!launched_any) {
            st = launch_kernel(passwords_lenght_dev, static_cast<uint32_t>(passwords_lenght.size()));
            if (st != metalSuccess) {
                return st;
            }
        }
    }
    else {
        st = launch_kernel(passwords_lenght_dev, static_cast<uint32_t>(passwords_lenght.size()));
        if (st != metalSuccess) {
            return st;
        }
    }

    return metalSuccess;
}

// recovery_direct_flush: recovery mode helper that flushes the related data for direct.
static bool recovery_direct_flush(RecoveryGpuDirectContext& ctx, std::string& err) {
    err.clear();
    if (ctx.indexes.empty()) {
        return true;
    }
    const uint32_t nr = static_cast<uint32_t>(ctx.indexes.size());
    const metalError_t st = recovery_direct_launch_current_batch(ctx, nr);
    if (st != metalSuccess) {
        err = std::string("recovery launch failed: ") + metalGetErrorString(st);
        return false;
    }
    ctx.combined.clear();
    ctx.indexes.clear();
    return true;
}

// recovery_direct_append_candidate_u16: recovery mode helper that appends candidate u16 for direct.
static bool recovery_direct_append_candidate_u16(
    RecoveryGpuDirectContext& ctx,
    const RecoveryPreparedTask& task,
    const uint16_t* ids,
    const size_t ids_size,
    std::string& err) {
    err.clear();
    if (ids == nullptr || ids_size != task.ids.size()) {
        err = "invalid recovery candidate payload";
        return false;
    }
    if (ctx.indexes.size() >= ctx.batch_capacity) {
        if (!recovery_direct_flush(ctx, err)) {
            return false;
        }
    }
    for (size_t i = 0; i < ids_size; ++i) {
        if (i) {
            ctx.combined.push_back(' ');
        }
        const uint16_t id = ids[i];
        if (static_cast<size_t>(id) >= task.wordlist->words.size()) {
            err = "recovery candidate has invalid word id";
            return false;
        }
        ctx.combined.append(task.wordlist->words[static_cast<size_t>(id)]);
    }
    if (ctx.combined.size() > static_cast<size_t>(std::numeric_limits<uint32_t>::max())) {
        err = "recovery candidate batch exceeds indexable size";
        return false;
    }
    ctx.indexes.emplace_back(static_cast<uint32_t>(ctx.combined.size()));
    return true;
}

// recovery_direct_append_candidate_i32: recovery mode helper that appends candidate i32 for direct.
static bool recovery_direct_append_candidate_i32(
    RecoveryGpuDirectContext& ctx,
    const RecoveryPreparedTask& task,
    const std::vector<int>& ids,
    std::string& err) {
    std::vector<uint16_t> ids_u16(ids.size(), 0u);
    for (size_t i = 0; i < ids.size(); ++i) {
        const int id = ids[i];
        if (id < 0 || id >= 2048) {
            err = "recovery candidate has invalid CPU word id";
            return false;
        }
        ids_u16[i] = static_cast<uint16_t>(id);
    }
    return recovery_direct_append_candidate_u16(ctx, task, ids_u16.data(), ids_u16.size(), err);
}

// recovery_direct_append_batch_u16: recovery mode helper that appends batch u16 for direct.
static bool recovery_direct_append_batch_u16(
    RecoveryGpuDirectContext& ctx,
    const RecoveryPreparedTask& task,
    const uint16_t* ids,
    const size_t words_count,
    const uint32_t candidate_count,
    std::string& err) {
    err.clear();
    if (ids == nullptr || words_count != task.ids.size()) {
        err = "invalid recovery GPU batch payload";
        return false;
    }
    for (uint32_t i = 0; i < candidate_count; ++i) {
        const uint16_t* ptr = ids + static_cast<size_t>(i) * words_count;
        if (!recovery_direct_append_candidate_u16(ctx, task, ptr, words_count, err)) {
            return false;
        }
    }
    return true;
}

// recovery_direct_init: recovery mode helper that initializes the related data for direct.
static bool recovery_direct_init(RecoveryGpuDirectContext& ctx, std::string& err) {
    err.clear();
    recovery_direct_release(ctx);

    if (derIndex.empty() || Iterations.empty()) {
        err = "recovery requires loaded derivations and iterations";
        return false;
    }
    if (Derivations.empty()) {
        const bool root_only = std::all_of(derIndex.begin(), derIndex.end(), [](const uint32_t n) { return n == 0u; });
        if (!root_only) {
            err = "recovery derivation list is empty for non-root derivations";
            return false;
        }
    }

    const uint64_t output_size = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    ctx.batch_capacity = (output_size == 0ull) ? 1ull : output_size;
    ctx.iteration_size = static_cast<uint32_t>(Iterations.size());
    reserve_batch_buffers(ctx.combined, ctx.indexes, ctx.batch_capacity, 512);

    metalError_t st = acquire_shared_result_buffers(ctx.batch_capacity, &ctx.buffIsResult, &ctx.buffDeviceResult);
    if (st != metalSuccess) {
        err = std::string("acquire_shared_result_buffers failed: ") + metalGetErrorString(st);
        return false;
    }

    st = metalMalloc(reinterpret_cast<void**>(&ctx.devDerIndex), derIndex.size() * sizeof(uint32_t));
    if (st != metalSuccess) {
        err = "metalMalloc recovery devDerIndex failed";
        recovery_direct_release(ctx);
        return false;
    }
    const size_t recovery_deriv_words = Derivations.empty() ? 1u : Derivations.size();
    st = metalMalloc(reinterpret_cast<void**>(&ctx.devDerivationList), recovery_deriv_words * sizeof(uint32_t));
    if (st != metalSuccess) {
        err = "metalMalloc recovery devDerivationList failed";
        recovery_direct_release(ctx);
        return false;
    }
    st = metalMalloc(reinterpret_cast<void**>(&ctx.devIter), Iterations.size() * sizeof(uint32_t));
    if (st != metalSuccess) {
        err = "metalMalloc recovery devIter failed";
        recovery_direct_release(ctx);
        return false;
    }

    st = metalMemcpy(ctx.devDerIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (st != metalSuccess) {
        err = "metalMemcpy recovery devDerIndex failed";
        recovery_direct_release(ctx);
        return false;
    }
    if (!Derivations.empty()) {
        st = metalMemcpy(ctx.devDerivationList, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
        if (st != metalSuccess) {
            err = "metalMemcpy recovery devDerivationList failed";
            recovery_direct_release(ctx);
            return false;
        }
    }
    else {
        uint32_t zero = 0u;
        st = metalMemcpy(ctx.devDerivationList, &zero, sizeof(zero), metalMemcpyHostToDevice);
        if (st != metalSuccess) {
            err = "metalMemcpy recovery devDerivationList root failed";
            recovery_direct_release(ctx);
            return false;
        }
    }
    st = metalMemcpy(ctx.devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (st != metalSuccess) {
        err = "metalMemcpy recovery devIter failed";
        recovery_direct_release(ctx);
        return false;
    }

    return true;
}

// recovery_direct_select_wordlist: recovery mode helper that selects wordlist for direct.
static bool recovery_direct_select_wordlist(RecoveryGpuDirectContext& ctx, const RecoveryPreparedTask& task, std::string& err) {
    err.clear();
    if (task.wordlist == nullptr) {
        err = "recovery task has no wordlist";
        return false;
    }

    if (ctx.activeWordlist == task.wordlist) {
        return true;
    }

    metalError_t st = metalSuccess;
    if (!task.wordlist->external && task.wordlist->device_lang >= 0) {
        metal_launch("setDict", 1, 1, task.wordlist->device_lang);
        st = metalGetLastError();
        if (st != metalSuccess) {
            err = "setDict launch failed";
            return false;
        }
        st = metalDeviceSynchronize();
        if (st != metalSuccess) {
            err = std::string("setDict sync failed: ") + metalGetErrorString(st);
            return false;
        }
        ctx.activeWordlist = task.wordlist;
        return true;
    }

    if (task.wordlist->words.empty()) {
        err = "external wordlist is empty";
        return false;
    }

    const size_t dict_words = task.wordlist->words.size();
    const size_t dict_bytes = dict_words * 34u;

    std::vector<char> host_dict(dict_bytes, 0);
    for (size_t i = 0; i < dict_words; ++i) {
        const std::string& w = task.wordlist->words[i];
        const size_t copy_len = (w.size() > 33u) ? 33u : w.size();
        memcpy(host_dict.data() + i * 34u, w.data(), copy_len);
    }

    if (ctx.devRecoveryDictWords != dict_words) {
        if (ctx.devRecoveryDict) {
            metalFree(ctx.devRecoveryDict);
            ctx.devRecoveryDict = nullptr;
            ctx.devRecoveryDictWords = 0;
        }
        st = metalMalloc(reinterpret_cast<void**>(&ctx.devRecoveryDict), dict_bytes);
        if (st != metalSuccess) {
            err = "metalMalloc recovery external dictionary failed";
            return false;
        }
        ctx.devRecoveryDictWords = dict_words;
    }

    st = metalMemcpy(ctx.devRecoveryDict, host_dict.data(), dict_bytes, metalMemcpyHostToDevice);
    if (st != metalSuccess) {
        err = "metalMemcpy recovery external dictionary failed";
        return false;
    }

    metal_launch("setDictPointer", 1, 1, ctx.devRecoveryDict);
    st = metalGetLastError();
    if (st != metalSuccess) {
        err = "setDictPointer launch failed";
        return false;
    }
    st = metalDeviceSynchronize();
    if (st != metalSuccess) {
        err = std::string("setDictPointer sync failed: ") + metalGetErrorString(st);
        return false;
    }

    ctx.activeWordlist = task.wordlist;
    return true;
}

// recovery_direct_finalize: recovery mode helper that finalizes the related data for direct.
static bool recovery_direct_finalize(RecoveryGpuDirectContext& ctx, std::string& err) {
    err.clear();
    if (!recovery_direct_flush(ctx, err)) {
        return false;
    }
    const metalError_t st = recovery_direct_sync_previous(ctx);
    if (st != metalSuccess) {
        err = std::string("recovery final sync failed: ") + metalGetErrorString(st);
        return false;
    }
    return true;
}

// recovery_pow_2048_u64: recovery mode helper that computes 2048 u64.
static bool recovery_pow_2048_u64(int missing_count, uint64_t& out) {
    out = 0ull;
    if (missing_count < 0 || missing_count > 5) {
        return false;
    }
    out = 1ull << (11 * missing_count);
    return true;
}

// recovery_u64_add_saturating: recovery mode helper that adds saturating for u64.
static inline void recovery_u64_add_saturating(uint64_t& acc, const uint64_t delta) {
    const uint64_t max_v = std::numeric_limits<uint64_t>::max();
    if (acc > max_v - delta) {
        acc = max_v;
        return;
    }
    acc += delta;
}

static inline bool recovery_partition_active() {
    return g_recovery_multi_gpu_partition.enabled && g_recovery_multi_gpu_partition.count > 1u;
}

// recovery_partition_is_log_owner: recovery mode helper that checks whether partition log owner is valid.
static inline bool recovery_partition_is_log_owner() {
    return !recovery_partition_active() || g_recovery_multi_gpu_partition.index == 0u;
}

// recovery_partition_take_span: recovery mode helper that takes span for partition.
static inline bool recovery_partition_take_span(const uint64_t total, uint64_t& out_start, uint64_t& out_count) {
    out_start = 0ull;
    out_count = total;
    if (total == 0ull || !recovery_partition_active()) {
        return true;
    }
    uint64_t end = 0ull;
    const bool ok = split_u64_range(
        0ull,
        total - 1ull,
        g_recovery_multi_gpu_partition.index,
        g_recovery_multi_gpu_partition.count,
        out_start,
        end);
    if (!ok) {
        out_start = 0ull;
        out_count = 0ull;
        return true;
    }
    out_count = (end - out_start) + 1ull;
    return true;
}

// recovery_partition_skip_high_combo: recovery mode helper that skips high combo for partition.
static inline bool recovery_partition_skip_high_combo(const uint64_t high_combo_index) {
    if (!recovery_partition_active()) {
        return false;
    }
    const uint64_t part_count = static_cast<uint64_t>(g_recovery_multi_gpu_partition.count);
    const uint64_t part_index = static_cast<uint64_t>(g_recovery_multi_gpu_partition.index);
    return (high_combo_index % part_count) != part_index;
}

#include "main_priv_recovery_runtime.h"

// recovery_can_use_fused_path: recovery mode helper that checks whether use fused path is valid.
static bool recovery_can_use_fused_path() {
    if (MNEMONIC_MODE != 0) return false;
    if (IS_STRING || UTF8) return false;
    if (Electrum || Electrum_128 || Electrum_seg || Ton_mnemonic || Ton_only || Old_electrum) return false;
    if (pass_set) return false;
    if (!secp256_host || ed25519_host) return false;
    if (Iterations.size() != 1u || Iterations[0] != 1u) return false;

    // Fused recovery kernel currently targets secp256 hash types used in vanity-style modes.
    if (Solana || Ton || Ton_all || Dot || Aptos || Sui || Xrp || Exodus || Iota || Ada || Icp || Fil || Xtz) return false;

    if (!Compressed && !Uncompressed && !Segwit && !P2wsh && !Taproot && !Ethereum && !Xpoint) return false;
    return true;
}

// recovery_emit_task_candidates_cpu: recovery mode helper that emits task candidates CPU.
static bool recovery_emit_task_candidates_cpu(RecoveryGpuDirectContext& ctx, const RecoveryPreparedTask& task, uint64_t& tested, uint64_t& emitted, std::string& err) {
    err.clear();
    tested = 0;
    emitted = 0;

    std::vector<int> ids = task.ids;
    uint64_t linear_index = 0ull;

    if (task.missing_positions.empty()) {
        const bool take_candidate = !recovery_partition_active() || g_recovery_multi_gpu_partition.index == 0u;
        if (!take_candidate) {
            return true;
        }
        tested = 1;
        if (recovery_bip39_checksum_valid(ids)) {
            emitted = 1;
            if (!recovery_direct_append_candidate_i32(ctx, task, ids, err)) {
                return false;
            }
        }
        return true;
    }

    std::function<bool(size_t)> dfs;
    dfs = [&](const size_t depth) -> bool {
        if (depth >= task.missing_positions.size()) {
            bool take_candidate = true;
            if (recovery_partition_active()) {
                const uint64_t part_count = static_cast<uint64_t>(g_recovery_multi_gpu_partition.count);
                const uint64_t part_index = static_cast<uint64_t>(g_recovery_multi_gpu_partition.index);
                take_candidate = ((linear_index % part_count) == part_index);
                ++linear_index;
            }
            if (!take_candidate) {
                return true;
            }

            ++tested;
            if (recovery_bip39_checksum_valid(ids)) {
                ++emitted;
                if (!recovery_direct_append_candidate_i32(ctx, task, ids, err)) {
                    return false;
                }
            }
            return true;
        }

        const int pos = task.missing_positions[depth];
        for (int w = 0; w < 2048; ++w) {
            ids[static_cast<size_t>(pos)] = w;
            if (!dfs(depth + 1u)) {
                return false;
            }
        }
        return true;
    };

    const bool ok = dfs(0u);
    if (recovery_partition_is_log_owner() && (tested & ((1ull << 20) - 1ull)) == 0ull) {
        printf("                                                                        \r");
        fflush(stdout);
    }
    if (!ok && err.empty()) {
        err = "recovery CPU candidate submit failed";
    }
    return ok;
}

// recovery_emit_task_candidates_gpu: recovery mode helper that emits task candidates GPU.
static bool recovery_emit_task_candidates_gpu(RecoveryGpuDirectContext& ctx, const RecoveryPreparedTask& task, uint64_t& tested, uint64_t& emitted, std::string& err) {
    tested = 0;
    emitted = 0;
    err.clear();

    const int words_count_local = static_cast<int>(task.ids.size());
    const int missing_count = static_cast<int>(task.missing_positions.size());

    if (words_count_local <= 0 || words_count_local > 48 || (words_count_local % 3) != 0) {
        err = "unsupported word count for GPU recovery";
        return false;
    }

    if (missing_count == 0) {
        std::vector<int> ids = task.ids;
        const bool take_candidate = !recovery_partition_active() || g_recovery_multi_gpu_partition.index == 0u;
        if (!take_candidate) {
            return true;
        }
        tested = 1;
        if (recovery_bip39_checksum_valid(ids)) {
            if (!recovery_direct_append_candidate_i32(ctx, task, ids, err)) {
                return false;
            }
            emitted = 1;
        }
        return true;
    }

    const int low_missing_count = (missing_count > 5) ? 5 : missing_count;
    const int high_missing_count = missing_count - low_missing_count;

    uint64_t low_space_candidates = 0ull;
    if (!recovery_pow_2048_u64(low_missing_count, low_space_candidates)) {
        err = "internal error: invalid GPU wildcard split";
        return false;
    }

    uint64_t partition_low_start = 0ull;
    uint64_t partition_low_count = low_space_candidates;
    if (high_missing_count == 0) {
        recovery_partition_take_span(low_space_candidates, partition_low_start, partition_low_count);
    }

    std::vector<uint16_t> base_ids(static_cast<size_t>(words_count_local), 0u);
    for (int i = 0; i < words_count_local; ++i) {
        const int id = task.ids[static_cast<size_t>(i)];
        base_ids[static_cast<size_t>(i)] = static_cast<uint16_t>(id < 0 ? 0 : id);
    }

    std::vector<int> high_missing_positions;
    std::vector<int> low_missing_positions;
    high_missing_positions.reserve(static_cast<size_t>(high_missing_count));
    low_missing_positions.reserve(static_cast<size_t>(low_missing_count));

    for (int i = 0; i < missing_count; ++i) {
        const int pos = task.missing_positions[static_cast<size_t>(i)];
        if (i < high_missing_count) {
            high_missing_positions.emplace_back(pos);
        }
        else {
            low_missing_positions.emplace_back(pos);
        }
    }

    const uint32_t out_capacity = 262144u;
    const size_t out_ids_count = static_cast<size_t>(out_capacity) * static_cast<size_t>(words_count_local);

    uint16_t* d_base_ids = nullptr;
    int* d_missing_positions = nullptr;
    uint16_t* d_out_ids = nullptr;
    uint32_t* d_out_count = nullptr;
    std::vector<uint16_t> host_out_ids;
    struct RecoveryRange {
        uint64_t start = 0ull;
        uint64_t count = 0ull;
    };
    std::vector<RecoveryRange> pending;
    std::vector<uint16_t> active_base_ids = base_ids;
    std::vector<uint16_t> high_digits(static_cast<size_t>(high_missing_count), 0u);

    metalError_t st = metalSetDevice(DEVICE_NR);
    if (st != metalSuccess) {
        err = "metalSetDevice failed";
        return false;
    }

    const unsigned int launch_threads = (BLOCK_THREADS == 0u) ? 256u : BLOCK_THREADS;
    const unsigned int launch_blocks = (BLOCK_NUMBER == 0u) ? 1024u : BLOCK_NUMBER;
    const uint64_t hard_batch = 1ull << 22; // 4M candidates per launch before adaptive splitting.
    pending.reserve(128u);

    auto run_low_space = [&](const uint64_t range_start, const uint64_t range_count) -> bool {
        st = metalMemcpy(d_base_ids, active_base_ids.data(), active_base_ids.size() * sizeof(uint16_t), metalMemcpyHostToDevice);
        if (st != metalSuccess) {
            err = "metalMemcpy d_base_ids failed";
            return false;
        }

        pending.clear();
        pending.push_back({ range_start, range_count });

        while (!pending.empty()) {
            RecoveryRange range = pending.back();
            pending.pop_back();
            if (range.count == 0ull) {
                continue;
            }

            if (range.count > hard_batch) {
                pending.push_back({ range.start + hard_batch, range.count - hard_batch });
                range.count = hard_batch;
            }

            const unsigned int checksum_blocks = static_cast<unsigned int>(
                std::min<uint64_t>(
                    static_cast<uint64_t>(launch_blocks),
                    std::max<uint64_t>(1ull, (range.count + static_cast<uint64_t>(launch_threads) - 1ull) / static_cast<uint64_t>(launch_threads))));

            st = metalMemset(d_out_count, 0, sizeof(uint32_t));
            if (st != metalSuccess) {
                err = "metalMemset d_out_count failed";
                return false;
            }

            st = launchWorkerRecoveryChecksum(
                d_base_ids,
                words_count_local,
                d_missing_positions,
                low_missing_count,
                range.start,
                range.count,
                d_out_ids,
                d_out_count,
                out_capacity,
                checksum_blocks,
                launch_threads);
            if (st != metalSuccess) {
                err = "launchWorkerRecoveryChecksum failed";
                return false;
            }

            st = metalDeviceSynchronize();
            if (st != metalSuccess) {
                err = "metalDeviceSynchronize failed";
                return false;
            }

            uint32_t found_total = 0u;
            st = metalMemcpy(&found_total, d_out_count, sizeof(uint32_t), metalMemcpyDeviceToHost);
            if (st != metalSuccess) {
                err = "metalMemcpy d_out_count failed";
                return false;
            }

            if (found_total > out_capacity && range.count > 1ull) {
                const uint64_t left = range.count >> 1;
                const uint64_t right = range.count - left;
                pending.push_back({ range.start + left, right });
                pending.push_back({ range.start, left });
                continue;
            }

            recovery_u64_add_saturating(tested, range.count);

            const uint32_t copy_count = (found_total > out_capacity) ? out_capacity : found_total;
            if (copy_count > 0u) {
                const size_t copy_words = static_cast<size_t>(copy_count) * static_cast<size_t>(words_count_local);
                st = metalMemcpy(host_out_ids.data(), d_out_ids, copy_words * sizeof(uint16_t), metalMemcpyDeviceToHost);
                if (st != metalSuccess) {
                    err = "metalMemcpy d_out_ids failed";
                    return false;
                }

                if (!recovery_direct_append_batch_u16(
                    ctx,
                    task,
                    host_out_ids.data(),
                    static_cast<size_t>(words_count_local),
                    copy_count,
                    err)) {
                    return false;
                }
            }

            recovery_u64_add_saturating(emitted, static_cast<uint64_t>(found_total));
      /*      if ((tested & ((1ull << 20) - 1ull)) == 0ull) {
                printf("[!] Recovery tested: %llu | checksum-valid: %llu\r",
                    static_cast<unsigned long long>(tested),
                    static_cast<unsigned long long>(emitted));
                fflush(stdout);
            }*/
        }

        return true;
    };

    st = metalMalloc(reinterpret_cast<void**>(&d_base_ids), base_ids.size() * sizeof(uint16_t));
    if (st != metalSuccess) { err = "metalMalloc d_base_ids failed"; goto cleanup; }
    st = metalMalloc(reinterpret_cast<void**>(&d_missing_positions), low_missing_positions.size() * sizeof(int));
    if (st != metalSuccess) { err = "metalMalloc d_missing_positions failed"; goto cleanup; }
    st = metalMalloc(reinterpret_cast<void**>(&d_out_ids), out_ids_count * sizeof(uint16_t));
    if (st != metalSuccess) { err = "metalMalloc d_out_ids failed"; goto cleanup; }
    st = metalMalloc(reinterpret_cast<void**>(&d_out_count), sizeof(uint32_t));
    if (st != metalSuccess) { err = "metalMalloc d_out_count failed"; goto cleanup; }

    st = metalMemcpy(d_missing_positions, low_missing_positions.data(), low_missing_positions.size() * sizeof(int), metalMemcpyHostToDevice);
    if (st != metalSuccess) { err = "metalMemcpy d_missing_positions failed"; goto cleanup; }
    host_out_ids.resize(out_ids_count);

    if (high_missing_count == 0) {
        if (!run_low_space(partition_low_start, partition_low_count)) {
            goto cleanup;
        }
    }
    else {
        uint64_t high_combo_index = 0ull;
        for (;;) {
            for (int i = 0; i < high_missing_count; ++i) {
                const int pos = high_missing_positions[static_cast<size_t>(i)];
                active_base_ids[static_cast<size_t>(pos)] = high_digits[static_cast<size_t>(i)];
            }

            if (!recovery_partition_skip_high_combo(high_combo_index)) {
                if (!run_low_space(0ull, low_space_candidates)) {
                    goto cleanup;
                }
            }
            ++high_combo_index;

            int carry_idx = 0;
            for (; carry_idx < high_missing_count; ++carry_idx) {
                const uint16_t next = static_cast<uint16_t>(high_digits[static_cast<size_t>(carry_idx)] + 1u);
                if (next < 2048u) {
                    high_digits[static_cast<size_t>(carry_idx)] = next;
                    break;
                }
                high_digits[static_cast<size_t>(carry_idx)] = 0u;
            }

            if (carry_idx == high_missing_count) {
                break;
            }
        }
    }

cleanup:
    if (d_base_ids) metalFree(d_base_ids);
    if (d_missing_positions) metalFree(d_missing_positions);
    if (d_out_ids) metalFree(d_out_ids);
    if (d_out_count) metalFree(d_out_count);

    if (!err.empty()) {
        return false;
    }

    if (recovery_partition_is_log_owner() && (tested & ((1ull << 20) - 1ull)) == 0ull) {
        printf("                                                                        \r");
        fflush(stdout);
    }
    return true;
}

// recovery_emit_task_candidates_fused_gpu: recovery mode helper that emits task candidates fused GPU.
static bool recovery_emit_task_candidates_fused_gpu(RecoveryGpuDirectContext& ctx, const RecoveryPreparedTask& task, uint64_t& tested, uint64_t& emitted, std::string& err) {
    tested = 0;
    emitted = 0;
    err.clear();

    const int words_count_local = static_cast<int>(task.ids.size());
    const int missing_count = static_cast<int>(task.missing_positions.size());

    if (words_count_local <= 0 || words_count_local > 48 || (words_count_local % 3) != 0) {
        err = "unsupported word count for fused recovery";
        return false;
    }

    const int low_missing_count = (missing_count > 5) ? 5 : missing_count;
    const int high_missing_count = missing_count - low_missing_count;

    uint64_t low_space_candidates = 0ull;
    if (!recovery_pow_2048_u64(low_missing_count, low_space_candidates)) {
        err = "internal error: invalid fused wildcard split";
        return false;
    }

    uint64_t partition_low_start = 0ull;
    uint64_t partition_low_count = low_space_candidates;
    if (high_missing_count == 0) {
        recovery_partition_take_span(low_space_candidates, partition_low_start, partition_low_count);
    }

    std::vector<uint16_t> base_ids(static_cast<size_t>(words_count_local), 0u);
    for (int i = 0; i < words_count_local; ++i) {
        const int id = task.ids[static_cast<size_t>(i)];
        if (id >= 2048) {
            err = "invalid recovery base word id (>=2048)";
            return false;
        }
        base_ids[static_cast<size_t>(i)] = static_cast<uint16_t>(id < 0 ? 0 : id);
    }

    std::vector<int> high_missing_positions;
    std::vector<int> low_missing_positions;
    high_missing_positions.reserve(static_cast<size_t>(high_missing_count));
    low_missing_positions.reserve(static_cast<size_t>(low_missing_count));

    for (int i = 0; i < missing_count; ++i) {
        const int pos = task.missing_positions[static_cast<size_t>(i)];
        if (i < high_missing_count) {
            high_missing_positions.emplace_back(pos);
        }
        else {
            low_missing_positions.emplace_back(pos);
        }
    }

    const uint32_t out_capacity = 262144u;
    const size_t out_ids_count = static_cast<size_t>(out_capacity) * static_cast<size_t>(words_count_local);
    const size_t master_words_count = static_cast<size_t>(out_capacity) * 16u;

    uint16_t* d_base_ids = nullptr;
    int* d_missing_positions = nullptr;
    uint16_t* d_out_ids = nullptr;
    uint32_t* d_out_count = nullptr;
    uint32_t* d_master_words = nullptr;

    struct RecoveryRange {
        uint64_t start = 0ull;
        uint64_t count = 0ull;
    };
    std::vector<RecoveryRange> pending;
    std::vector<uint16_t> active_base_ids = base_ids;
    std::vector<uint16_t> high_digits(static_cast<size_t>(high_missing_count), 0u);

    metalError_t st = metalSetDevice(DEVICE_NR);
    if (st != metalSuccess) {
        err = "metalSetDevice failed";
        return false;
    }

    const unsigned int launch_threads = (BLOCK_THREADS == 0u) ? 256u : BLOCK_THREADS;
    const unsigned int launch_blocks = (BLOCK_NUMBER == 0u) ? 1024u : BLOCK_NUMBER;
    const uint64_t hard_batch = 1ull << 22;
    pending.reserve(128u);

    auto run_low_space = [&](const uint64_t range_start, const uint64_t range_count) -> bool {
        st = metalMemcpy(d_base_ids, active_base_ids.data(), active_base_ids.size() * sizeof(uint16_t), metalMemcpyHostToDevice);
        if (st != metalSuccess) {
            err = "metalMemcpy fused d_base_ids failed";
            return false;
        }

        pending.clear();
        pending.push_back({ range_start, range_count });

        while (!pending.empty()) {
            RecoveryRange range = pending.back();
            pending.pop_back();
            if (range.count == 0ull) {
                continue;
            }

            if (range.count > hard_batch) {
                pending.push_back({ range.start + hard_batch, range.count - hard_batch });
                range.count = hard_batch;
            }

            const unsigned int checksum_blocks = static_cast<unsigned int>(
                std::min<uint64_t>(
                    static_cast<uint64_t>(launch_blocks),
                    std::max<uint64_t>(1ull, (range.count + static_cast<uint64_t>(launch_threads) - 1ull) / static_cast<uint64_t>(launch_threads))));

            st = metalMemset(d_out_count, 0, sizeof(uint32_t));
            if (st != metalSuccess) {
                err = "metalMemset fused d_out_count failed";
                return false;
            }

            st = launchWorkerRecoveryChecksum(
                d_base_ids,
                words_count_local,
                d_missing_positions,
                low_missing_count,
                range.start,
                range.count,
                d_out_ids,
                d_out_count,
                out_capacity,
                checksum_blocks,
                launch_threads);
            if (st != metalSuccess) {
                err = "launchWorkerRecoveryChecksum (staged) failed";
                return false;
            }

            uint32_t found_total = 0u;
            st = metalMemcpy(&found_total, d_out_count, sizeof(uint32_t), metalMemcpyDeviceToHost);
            if (st != metalSuccess) {
                err = "metalMemcpy fused d_out_count failed";
                return false;
            }

            if (found_total > out_capacity && range.count > 1ull) {
                const uint64_t left = range.count >> 1;
                const uint64_t right = range.count - left;
                pending.push_back({ range.start + left, right });
                pending.push_back({ range.start, left });
                continue;
            }

            const uint32_t eval_count = (found_total > out_capacity) ? out_capacity : found_total;
            if (eval_count > 0u) {
                const unsigned int eval_blocks = static_cast<unsigned int>(
                    std::min<uint64_t>(
                        static_cast<uint64_t>(launch_blocks),
                        std::max<uint64_t>(1ull, (static_cast<uint64_t>(eval_count) + static_cast<uint64_t>(launch_threads) - 1ull) / static_cast<uint64_t>(launch_threads))));

                st = launchWorkerRecoverySeedBatch(
                    d_out_ids,
                    words_count_local,
                    eval_count,
                    passwords_dev,
                    passwords_lenght_dev,
                    ctx.devIter,
                    ctx.iteration_size,
                    d_master_words,
                    eval_blocks,
                    launch_threads);
                if (st != metalSuccess) {
                    err = "launchWorkerRecoverySeedBatch failed";
                    return false;
                }

                st = launchWorkerRecoveryEvalMasterBatch(
                    ctx.buffIsResult,
                    ctx.buffDeviceResult,
                    _dev_precomp,
                    pitch,
                    d_out_ids,
                    d_master_words,
                    words_count_local,
                    eval_count,
                    ctx.devDerivationList,
                    ctx.devDerIndex,
                    derIndex_size,
                    0u,
                    passwords_dev,
                    passwords_lenght_dev,
                    0u,
                    Rounds,
                    MNEMONIC_MODE,
                    IS_STRING,
                    dub_mnem,
                    eval_blocks,
                    launch_threads);
                if (st != metalSuccess) {
                    err = "launchWorkerRecoveryEvalMasterBatch failed";
                    return false;
                }

                st = metalDeviceSynchronize();
                if (st != metalSuccess) {
                    err = "metalDeviceSynchronize after staged eval failed";
                    return false;
                }
            }

            if (read_result_flag_host(ctx.buffIsResult)) {
                clear_result_flag_host(ctx.buffIsResult);
                SaveResult(OUT_FILE, Founds, save, Derivations_list);
            }

            recovery_u64_add_saturating(tested, range.count);
            recovery_u64_add_saturating(emitted, static_cast<uint64_t>(found_total));
            counterTotal += (range.count * static_cast<uint64_t>(Iterations.size()));

   /*         if ((tested & ((1ull << 20) - 1ull)) == 0ull) {
                printf("[!] Recovery tested: %llu | checksum-valid: %llu\r",
                    static_cast<unsigned long long>(tested),
                    static_cast<unsigned long long>(emitted));
                fflush(stdout);
            }*/
        }

        return true;
    };

    st = metalMalloc(reinterpret_cast<void**>(&d_base_ids), base_ids.size() * sizeof(uint16_t));
    if (st != metalSuccess) { err = "metalMalloc fused d_base_ids failed"; goto cleanup_fused; }
    if (low_missing_count > 0) {
        st = metalMalloc(reinterpret_cast<void**>(&d_missing_positions), low_missing_positions.size() * sizeof(int));
        if (st != metalSuccess) { err = "metalMalloc fused d_missing_positions failed"; goto cleanup_fused; }
        st = metalMemcpy(d_missing_positions, low_missing_positions.data(), low_missing_positions.size() * sizeof(int), metalMemcpyHostToDevice);
        if (st != metalSuccess) { err = "metalMemcpy fused d_missing_positions failed"; goto cleanup_fused; }
    }
    st = metalMalloc(reinterpret_cast<void**>(&d_out_ids), out_ids_count * sizeof(uint16_t));
    if (st != metalSuccess) { err = "metalMalloc fused d_out_ids failed"; goto cleanup_fused; }
    st = metalMalloc(reinterpret_cast<void**>(&d_out_count), sizeof(uint32_t));
    if (st != metalSuccess) { err = "metalMalloc fused d_out_count failed"; goto cleanup_fused; }
    st = metalMalloc(reinterpret_cast<void**>(&d_master_words), master_words_count * sizeof(uint32_t));
    if (st != metalSuccess) { err = "metalMalloc fused d_master_words failed"; goto cleanup_fused; }

    if (high_missing_count == 0) {
        if (!run_low_space(partition_low_start, partition_low_count)) {
            goto cleanup_fused;
        }
    }
    else {
        uint64_t high_combo_index = 0ull;
        for (;;) {
            for (int i = 0; i < high_missing_count; ++i) {
                const int pos = high_missing_positions[static_cast<size_t>(i)];
                active_base_ids[static_cast<size_t>(pos)] = high_digits[static_cast<size_t>(i)];
            }

            if (!recovery_partition_skip_high_combo(high_combo_index)) {
                if (!run_low_space(0ull, low_space_candidates)) {
                    goto cleanup_fused;
                }
            }
            ++high_combo_index;

            int carry_idx = 0;
            for (; carry_idx < high_missing_count; ++carry_idx) {
                const uint16_t next = static_cast<uint16_t>(high_digits[static_cast<size_t>(carry_idx)] + 1u);
                if (next < 2048u) {
                    high_digits[static_cast<size_t>(carry_idx)] = next;
                    break;
                }
                high_digits[static_cast<size_t>(carry_idx)] = 0u;
            }
            if (carry_idx == high_missing_count) {
                break;
            }
        }
    }

cleanup_fused:
    if (d_base_ids) metalFree(d_base_ids);
    if (d_missing_positions) metalFree(d_missing_positions);
    if (d_out_ids) metalFree(d_out_ids);
    if (d_out_count) metalFree(d_out_count);
    if (d_master_words) metalFree(d_master_words);

    if (!err.empty()) {
        return false;
    }

    if (recovery_partition_is_log_owner() && (tested & ((1ull << 20) - 1ull)) == 0ull) {
        printf("                                                                        \r");
        fflush(stdout);
    }
    return true;
}

// recovery_emit_task_candidates: recovery mode helper that emits task candidates.
static bool recovery_emit_task_candidates(RecoveryGpuDirectContext& ctx, const RecoveryPreparedTask& task, bool use_fused_path, uint64_t& tested, uint64_t& emitted, std::string& err) {
    if (use_fused_path) {
        return recovery_emit_task_candidates_fused_gpu(ctx, task, tested, emitted, err);
    }

    std::string gpu_err;
    if (recovery_emit_task_candidates_gpu(ctx, task, tested, emitted, gpu_err)) {
        err.clear();
        return true;
    }

    if (!gpu_err.empty()) {
        fprintf(stderr, "[!] Recovery GPU checksum path disabled for this task: %s [!]\n", gpu_err.c_str());
    }

    if (task.missing_positions.size() > 5u) {
        err = gpu_err.empty() ? "recovery GPU path failed for wildcard count > 5" : gpu_err;
        return false;
    }

    err.clear();
    if (!recovery_emit_task_candidates_cpu(ctx, task, tested, emitted, err)) {
        if (err.empty()) {
            err = gpu_err.empty() ? "recovery CPU fallback failed" : gpu_err;
        }
        return false;
    }
    return true;
}

// recovery_expand_templates: recovery mode helper that expands templates.
static bool recovery_expand_templates(std::vector<RecoveryTemplateInput>& out, std::string& err) {
    out.clear();
    for (const RecoveryQueueEntry& entry : recoveryQueue) {
        if (entry.type == RecoveryQueueEntryType::Phrase) {
            const std::string phrase = recovery_trim_spaces_copy(entry.value);
            if (!phrase.empty()) {
                RecoveryTemplateInput t;
                t.source = "<cmd>";
                t.line_no = 0;
                t.phrase = phrase;
                out.emplace_back(std::move(t));
            }
            continue;
        }

        std::ifstream fin(entry.value.c_str(), std::ios::binary);
        tune_ifstream_buffer(fin);
        if (!fin) {
            err = "failed to open recovery file: " + entry.value;
            return false;
        }
        print_opened_input_file(entry.value);
        std::string line;
        size_t line_no = 0;
        while (read_trimmed_line(fin, line, 4096)) {
            ++line_no;
            line = recovery_trim_spaces_copy(line);
            if (line.empty()) continue;
            RecoveryTemplateInput t;
            t.source = entry.value;
            t.line_no = line_no;
            t.phrase = line;
            out.emplace_back(std::move(t));
        }
    }
    if (out.empty()) {
        err = "recovery queue is empty";
        return false;
    }
    return true;
}

// recovery_load_wordlists: recovery mode helper that loads wordlists.
static bool recovery_load_wordlists(std::vector<RecoveryWordlist>& out, std::string& err) {
    out.clear();

    if (!recoveryForcedWordlist.empty()) {
        RecoveryWordlist external_wl;
        if (!recovery_add_file_wordlist(recoveryForcedWordlist, external_wl, err)) {
            return false;
        }
        out.emplace_back(std::move(external_wl));
        return true;
    }

    std::vector<RecoveryWordlist> all_lists;
    all_lists.reserve(kRecoveryEmbeddedWordlistsCount);

    for (std::size_t i = 0; i < kRecoveryEmbeddedWordlistsCount; ++i) {
        RecoveryWordlist wl;
        std::string load_err;
        if (!recovery_add_embedded_wordlist(kRecoveryEmbeddedWordlists[i], wl, load_err)) {
            continue;
        }
        all_lists.emplace_back(std::move(wl));
    }

    if (all_lists.empty()) {
        err = "no embedded wordlists available";
        return false;
    }

    std::vector<RecoveryWordlist> bip39_lists;
    for (const RecoveryWordlist& wl : all_lists) {
        const std::string id_norm = recovery_norm_token(wl.id);
        const std::string file_norm = recovery_norm_token(wl.file_name);
        if (id_norm.find("bip39-") != std::string::npos || file_norm.find("bip39-") != std::string::npos) {
            bip39_lists.emplace_back(wl);
        }
    }

    if (!bip39_lists.empty()) {
        out.swap(bip39_lists);
    }
    else {
        out.swap(all_lists);
    }

    return !out.empty();
}

// processMetalRecovery: runs the Metal workflow for recovery.
metalError_t processMetalRecovery() {
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_recovery_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalRecovery();
            });
    }

    g_recovery_run_stats = RecoveryRunStats{};

    const bool recovery_log_master = recovery_partition_is_log_owner();
    if (recovery_partition_active()) {
        printf("[!] Recovery multiGPU: device=%d slot=%llu/%llu [!]\n",
            DEVICE_NR,
            static_cast<unsigned long long>(g_recovery_multi_gpu_partition.index + 1u),
            static_cast<unsigned long long>(g_recovery_multi_gpu_partition.count));
    }

    std::vector<RecoveryWordlist> wordlists;
    std::string err;
    if (!recovery_load_wordlists(wordlists, err)) {
        fprintf(stderr, "[!] Recovery error: %s [!]\n", err.c_str());
        return metalErrorInvalidValue;
    }

    std::vector<RecoveryTemplateInput> templates;
    if (!recovery_expand_templates(templates, err)) {
        fprintf(stderr, "[!] Recovery error: %s [!]\n", err.c_str());
        return metalErrorInvalidValue;
    }

    std::vector<RecoveryPreparedTask> tasks;
    tasks.reserve(templates.size());
    const bool use_fused_path = recovery_can_use_fused_path();

    if (recovery_log_master) {
        printf("[!] Recovery templates loaded: %llu [!]\n", static_cast<unsigned long long>(templates.size()));
    }
    for (const RecoveryTemplateInput& t : templates) {
        RecoveryPreparedTask task;
        std::string prep_err;
        if (!recovery_prepare_task(t, wordlists, task, prep_err)) {
            if (t.line_no > 0) {
                fprintf(stderr, "[!] Recovery skip: %s:%llu -> %s [!]\n",
                    t.source.c_str(),
                    static_cast<unsigned long long>(t.line_no),
                    prep_err.c_str());
            }
            else {
                fprintf(stderr, "[!] Recovery skip: %s -> %s [!]\n",
                    t.source.c_str(),
                    prep_err.c_str());
            }
            continue;
        }

        if (recovery_log_master && task.added_stars > 0) {
            printf("[!] Recovery normalized word count by appending %llu wildcard(s). [!]\n",
                static_cast<unsigned long long>(task.added_stars));
        }
        for (const auto& repl : task.replacements) {
            if (!recovery_log_master) {
                break;
            }
            printf("[!] Recovery replace: '%s' -> '%s' [!]\n", repl.first.c_str(), repl.second.c_str());
        }

        const size_t n_words = task.ids.size();
        const size_t missing = task.missing_positions.size();
        const long double combos = std::pow(2048.0L, static_cast<long double>(missing));
        const long double expected_valid = combos / std::pow(2.0L, static_cast<long double>(n_words / 3u));

        if (recovery_log_master) {
            printf("[!] Recovery task: words=%llu missing=%llu dict=%s [!]\n",
                static_cast<unsigned long long>(n_words),
                static_cast<unsigned long long>(missing),
                task.wordlist->name.c_str());
            printf("[!] Phrase: %s\n", task.normalized_phrase.c_str());
            printf("[!] Candidates to test: ~%s | expected checksum-valid: ~%s\n",
                recovery_format_scientific(combos).c_str(),
                recovery_format_scientific(expected_valid).c_str());
            if (use_fused_path) {
                printf("[!] Recovery engine: staged GPU pipeline (checksum + seed + derivation/hash)\n");
            }
            else if (missing == 0u) {
                printf("[!] Recovery checksum engine: direct (no wildcard expansion)\n");
            }
            else if (missing <= 5u) {
                printf("[!] Recovery checksum engine: GPU kernel (WorkerRecovery)\n");
            }
            else {
                printf("[!] Recovery checksum engine: GPU chunked kernel (WorkerRecovery, wildcards > 5)\n");
            }
        }

        tasks.emplace_back(std::move(task));
    }

    if (tasks.empty()) {
        fprintf(stderr, "[!] Recovery error: no valid tasks to process [!]\n");
        return metalErrorInvalidValue;
    }

    RecoveryGpuDirectContext recovery_ctx;
    if (!recovery_direct_init(recovery_ctx, err)) {
        fprintf(stderr, "[!] Recovery error: %s [!]\n", err.c_str());
        return metalErrorUnknown;
    }
    if (recovery_log_master && !use_fused_path) {
        printf("[!] Recovery fused path: disabled (using compatibility pipeline) [!]\n");
    }

    metalError_t st = metalSuccess;
    uint64_t tested_total = 0;
    uint64_t emitted_total = 0;

    for (size_t i = 0; i < tasks.size(); ++i) {
        const RecoveryPreparedTask& task = tasks[i];
        uint64_t tested = 0;
        uint64_t emitted = 0;
        std::string task_err;
        if (!recovery_direct_select_wordlist(recovery_ctx, task, task_err)) {
            fprintf(stderr, "[!] Recovery dictionary error: %s [!]\n", task_err.c_str());
            st = metalErrorUnknown;
            break;
        }
        if (!recovery_emit_task_candidates(recovery_ctx, task, use_fused_path, tested, emitted, task_err)) {
            if (task_err.empty()) {
                task_err = "recovery task generation failed";
            }
            fprintf(stderr, "[!] Recovery generator error: %s [!]\n", task_err.c_str());
            st = metalErrorUnknown;
            break;
        }
        if (!use_fused_path) {
            if (!recovery_direct_flush(recovery_ctx, task_err)) {
                if (task_err.empty()) {
                    task_err = "recovery flush failed";
                }
                fprintf(stderr, "[!] Recovery generator error: %s [!]\n", task_err.c_str());
                st = metalErrorUnknown;
                break;
            }
        }

        tested_total += tested;
        emitted_total += emitted;
        if (recovery_log_master) {
            if (recovery_partition_active()) {
                printf("[!] Recovery task done (%llu/%llu) [slot-local]: tested=%llu checksum-valid=%llu [!]\n",
                    static_cast<unsigned long long>(i + 1u),
                    static_cast<unsigned long long>(tasks.size()),
                    static_cast<unsigned long long>(tested),
                    static_cast<unsigned long long>(emitted));
            }
            else {
                printf("[!] Recovery task done (%llu/%llu): tested=%llu checksum-valid=%llu [!]\n",
                    static_cast<unsigned long long>(i + 1u),
                    static_cast<unsigned long long>(tasks.size()),
                    static_cast<unsigned long long>(tested),
                    static_cast<unsigned long long>(emitted));
            }
        }
    }

    if (st == metalSuccess && !use_fused_path) {
        if (!recovery_direct_finalize(recovery_ctx, err)) {
            fprintf(stderr, "[!] Recovery generator error: %s [!]\n", err.c_str());
            st = metalErrorUnknown;
        }
    }

    recovery_direct_release(recovery_ctx);

    if (recovery_log_master && !recovery_partition_active()) {
        printf("[!] Recovery summary: tested=%llu checksum-valid=%llu [!]\n",
            static_cast<unsigned long long>(tested_total),
            static_cast<unsigned long long>(emitted_total));
    }

    g_recovery_run_stats.tested_total = tested_total;
    g_recovery_run_stats.emitted_total = emitted_total;

    return st;
}

static bool scramble_u256_factorial(
    uint32_t value,
    modeinfra::U256& result,
    std::string& err) {
    result = modeinfra::U256::from_u64(1u);
    for (uint32_t factor = 2u; factor <= value; ++factor) {
        modeinfra::U256 next{};
        if (!modeinfra::multiply_checked(result, factor, next)) {
            err = "scramble permutation domain exceeds U256";
            return false;
        }
        result = next;
    }
    return true;
}

static bool scramble_multiset_size(
    const std::vector<uint16_t>& counts,
    modeinfra::U256& result,
    std::string& err) {
    uint32_t total = 0u;
    for (uint16_t count : counts) total += count;
    if (!scramble_u256_factorial(total, result, err)) return false;
    for (uint16_t count : counts) {
        for (uint32_t divisor = 2u; divisor <= count; ++divisor) {
            modeinfra::U256 quotient{};
            uint64_t remainder = 0u;
            if (!modeinfra::divide(
                    result, divisor, quotient, remainder) ||
                remainder != 0u) {
                err = "internal multiset factorial division failed";
                return false;
            }
            result = quotient;
        }
    }
    return true;
}

static bool scramble_load_pattern(std::string& pattern, std::string& err) {
    pattern = mnemonic_scramble_pattern;
    if (mnemonic_scramble_pattern_file.empty()) return true;
    std::ifstream input(mnemonic_scramble_pattern_file);
    if (!input) {
        err = "failed to open -pattern-file '" +
            mnemonic_scramble_pattern_file + "'";
        return false;
    }
    std::string line;
    while (std::getline(input, line)) {
        trim_crlf_inplace(line);
        const size_t comment = line.find('#');
        if (comment != std::string::npos) line.erase(comment);
        line = recovery_trim_spaces_copy(line);
        if (line.empty()) continue;
        if (!pattern.empty()) {
            err = "-pattern-file must contain exactly one non-comment pattern";
            return false;
        }
        pattern = line;
    }
    if (pattern.empty()) {
        err = "-pattern-file contains no pattern";
        return false;
    }
    return true;
}

static bool scramble_load_inputs(
    std::vector<RecoveryTemplateInput>& inputs,
    std::string& err) {
    inputs.clear();
    if (!mnemonic_scramble_inline.empty()) {
        inputs.push_back({
            "command line -scramble", 0u,
            mnemonic_scramble_inline
        });
    }
    for (const std::string& path : mnemonicFiles) {
        std::ifstream input(path);
        if (!input) {
            err = "failed to open scramble input '" + path + "'";
            return false;
        }
        std::string line;
        size_t line_no = 0u;
        while (std::getline(input, line)) {
            ++line_no;
            trim_crlf_inplace(line);
            const size_t comment = line.find('#');
            if (comment != std::string::npos) line.erase(comment);
            line = recovery_trim_spaces_copy(line);
            if (line.empty()) continue;
            inputs.push_back({path, line_no, line});
        }
    }
    if (inputs.empty()) {
        err = "scramble input contains no mnemonic phrases";
        return false;
    }
    return true;
}

static bool scramble_parse_restriction(
    const std::string& token,
    const RecoveryWordlist& wordlist,
    std::vector<uint16_t>& ids,
    std::string& err) {
    ids.clear();
    if (token.size() < 3u || token.front() != '{' ||
        token.back() != '}') {
        err = "restricted position must use {word|word}";
        return false;
    }
    std::stringstream values(
        token.substr(1u, token.size() - 2u));
    std::string word;
    std::set<uint16_t> unique;
    while (std::getline(values, word, '|')) {
        word = recovery_norm_token(word);
        const auto found = wordlist.id_by_norm.find(word);
        if (found == wordlist.id_by_norm.end() ||
            found->second < 0 || found->second >= 2048) {
            err = "pattern restriction contains a word outside the selected wordlist";
            return false;
        }
        unique.insert(static_cast<uint16_t>(found->second));
    }
    ids.assign(unique.begin(), unique.end());
    if (ids.empty()) {
        err = "pattern restriction is empty";
        return false;
    }
    return true;
}

static bool scramble_prepare_task(
    const RecoveryTemplateInput& input,
    const std::string& pattern,
    const std::vector<RecoveryWordlist>& wordlists,
    MnemonicScramblePreparedTask& output,
    std::string& err) {
    const std::vector<std::string> words =
        recovery_split_tokens(input.phrase);
    if (words.size() != 12u && words.size() != 15u &&
        words.size() != 18u && words.size() != 21u &&
        words.size() != 24u) {
        err = "BIP39 scramble requires 12, 15, 18, 21, or 24 words";
        return false;
    }
    const RecoveryWordlist* wordlist =
        recovery_pick_wordlist(wordlists, words);
    if (wordlist == nullptr) {
        err = "no BIP39 wordlist is available";
        return false;
    }
    std::vector<uint16_t> input_ids;
    input_ids.reserve(words.size());
    for (const std::string& word : words) {
        const auto found =
            wordlist->id_by_norm.find(recovery_norm_token(word));
        if (found == wordlist->id_by_norm.end() ||
            found->second < 0 || found->second >= 2048) {
            err = "input contains a word outside the selected BIP39 wordlist: " +
                word;
            return false;
        }
        input_ids.push_back(static_cast<uint16_t>(found->second));
    }

    std::vector<std::string> pattern_tokens;
    if (pattern.empty()) {
        pattern_tokens.assign(words.size(), "*");
    } else {
        pattern_tokens = recovery_split_tokens(pattern);
        if (pattern_tokens.size() != words.size()) {
            err = "pattern word count must match the scramble phrase";
            return false;
        }
    }

    std::map<uint16_t, uint16_t> remaining;
    for (uint16_t id : input_ids) ++remaining[id];
    output = MnemonicScramblePreparedTask{};
    output.recovery.source = input.source;
    output.recovery.line_no = input.line_no;
    output.recovery.wordlist = wordlist;
    output.recovery.ids.assign(words.size(), 0);
    output.recovery.normalized_phrase =
        recovery_join_tokens(words);
    output.output_template.assign(words.size(), 0u);
    std::vector<std::vector<uint16_t>> restrictions(words.size());

    for (size_t position = 0u;
         position < pattern_tokens.size(); ++position) {
        const std::string& token = pattern_tokens[position];
        if (token == "*") {
            output.movable_positions.push_back(
                static_cast<uint16_t>(position));
            continue;
        }
        if (!token.empty() && token.front() == '{') {
            if (!scramble_parse_restriction(
                    token, *wordlist, restrictions[position], err)) {
                return false;
            }
            output.movable_positions.push_back(
                static_cast<uint16_t>(position));
            continue;
        }
        const auto found =
            wordlist->id_by_norm.find(recovery_norm_token(token));
        if (found == wordlist->id_by_norm.end() ||
            found->second < 0 || found->second >= 2048) {
            err = "fixed pattern word is outside the selected wordlist: " +
                token;
            return false;
        }
        const uint16_t id = static_cast<uint16_t>(found->second);
        auto available = remaining.find(id);
        if (available == remaining.end() || available->second == 0u) {
            err = "fixed pattern consumes a word not present in the phrase: " +
                token;
            return false;
        }
        output.output_template[position] = id;
        --available->second;
    }

    std::map<uint16_t, uint32_t> unique_index;
    for (const auto& entry : remaining) {
        if (entry.second == 0u) continue;
        unique_index.emplace(
            entry.first,
            static_cast<uint32_t>(output.unique_ids.size()));
        output.unique_ids.push_back(entry.first);
        output.counts.push_back(entry.second);
    }
    if (output.unique_ids.size() > 24u) {
        err = "scramble unique word count exceeds 24";
        return false;
    }
    if (output.movable_positions.empty()) {
        output.unique_ids.assign(1u, 0u);
        output.counts.assign(1u, 0u);
    }
    const uint32_t all_mask =
        unique_index.empty()
        ? 0u
        : ((1u << static_cast<uint32_t>(unique_index.size())) - 1u);
    for (uint16_t position : output.movable_positions) {
        uint32_t mask = all_mask;
        if (!restrictions[position].empty()) {
            mask = 0u;
            for (uint16_t id : restrictions[position]) {
                const auto found = unique_index.find(id);
                if (found != unique_index.end()) {
                    mask |= 1u << found->second;
                }
            }
            if (mask == 0u) {
                err = "restricted pattern position has no remaining phrase word";
                return false;
            }
        }
        output.allowed_masks.push_back(mask);
    }
    if (output.allowed_masks.empty()) {
        output.allowed_masks.push_back(0u);
    }
    if (!scramble_multiset_size(
            output.counts, output.domain_size, err)) {
        return false;
    }
    return true;
}

static bool scramble_partition_interval(
    const modeinfra::U256& begin,
    const modeinfra::U256& end,
    uint64_t index,
    uint64_t count,
    modeinfra::U256& local_begin,
    modeinfra::U256& local_end,
    std::string& err) {
    modeinfra::U256 length{};
    if (count == 0u ||
        !modeinfra::subtract_checked(end, begin, length)) {
        err = "invalid scramble partition interval";
        return false;
    }
    auto offset_for = [&](uint64_t shard,
                          modeinfra::U256& offset) -> bool {
        modeinfra::U256 product{};
        if (!modeinfra::multiply_checked(length, shard, product)) {
            err = "scramble partition multiplication overflow";
            return false;
        }
        uint64_t remainder = 0u;
        return modeinfra::divide(product, count, offset, remainder);
    };
    modeinfra::U256 first_offset{};
    modeinfra::U256 last_offset{};
    if (!offset_for(index, first_offset) ||
        !offset_for(index + 1u, last_offset) ||
        !modeinfra::add_checked(begin, first_offset, local_begin) ||
        !modeinfra::add_checked(begin, last_offset, local_end)) {
        if (err.empty()) err = "scramble partition arithmetic failed";
        return false;
    }
    return true;
}

static uint64_t scramble_bounded_window(
    const modeinfra::U256& remaining,
    uint64_t maximum) {
    if (remaining.limbs[1] != 0u ||
        remaining.limbs[2] != 0u ||
        remaining.limbs[3] != 0u) {
        return maximum;
    }
    return std::min(remaining.limbs[0], maximum);
}

metalError_t processMetalMnemonicScramble() {
    modeinfra::ModeProgress& progress =
        modeinfra::global_mode_progress();
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        progress.begin(
            "MNEMONIC-SCRAMBLE",
            modeinfra::ProgressUnit::Candidate,
            modeinfra::ProgressPhase::Search);
        const metalError_t result =
            dispatch_recovery_mode_multi_gpu(
                __func__, []() -> metalError_t {
                    return processMetalMnemonicScramble();
                });
        progress.end();
        return result;
    }
    const bool progress_owner = !recovery_partition_active();
    if (progress_owner) {
        progress.begin(
            "MNEMONIC-SCRAMBLE",
            modeinfra::ProgressUnit::Candidate,
            modeinfra::ProgressPhase::Search);
    }

    std::string err;
    std::string pattern;
    std::vector<RecoveryTemplateInput> inputs;
    std::vector<RecoveryWordlist> wordlists;
    std::vector<MnemonicScramblePreparedTask> tasks;
    if (!scramble_load_pattern(pattern, err) ||
        !scramble_load_inputs(inputs, err) ||
        !recovery_load_wordlists(wordlists, err)) {
        fprintf(stderr, "[!] Scramble error: %s [!]\n", err.c_str());
        if (progress_owner) progress.end();
        return metalErrorInvalidValue;
    }
    for (const RecoveryTemplateInput& input : inputs) {
        MnemonicScramblePreparedTask task;
        if (!scramble_prepare_task(
                input, pattern, wordlists, task, err)) {
            fprintf(stderr, "[!] Scramble error at %s:%llu: %s [!]\n",
                input.source.c_str(),
                static_cast<unsigned long long>(input.line_no),
                err.c_str());
            if (progress_owner) progress.end();
            return metalErrorInvalidValue;
        }
        tasks.push_back(std::move(task));
    }

    modeinfra::U256 requested_start{};
    modeinfra::U256 requested_end{};
    bool explicit_end = end_point_set;
    if (seqMode &&
        !modeinfra::parse_u256(start_point, requested_start, err)) {
        fprintf(stderr, "[!] Scramble ordinal error: %s [!]\n", err.c_str());
        if (progress_owner) progress.end();
        return metalErrorInvalidValue;
    }
    if (explicit_end &&
        !modeinfra::parse_u256(end_point, requested_end, err)) {
        fprintf(stderr, "[!] Scramble ordinal error: %s [!]\n", err.c_str());
        if (progress_owner) progress.end();
        return metalErrorInvalidValue;
    }

    RecoveryGpuDirectContext recovery_ctx;
    if (!recovery_direct_init(recovery_ctx, err)) {
        fprintf(stderr, "[!] Scramble runtime error: %s [!]\n", err.c_str());
        if (progress_owner) progress.end();
        return metalErrorUnknown;
    }
    const bool use_fused_path = recovery_can_use_fused_path();
    const uint64_t requested_batch =
        (use_n_count && n_number != 0u)
        ? n_number
        : (1ull << 20u);
    const uint64_t dispatch_threads =
        BLOCK_THREADS == 0u ? 256u : BLOCK_THREADS;
    const uint64_t dispatch_blocks =
        BLOCK_NUMBER == 0u ? 1024u : BLOCK_NUMBER;
    const uint64_t dispatch_capacity =
        dispatch_blocks >
                std::numeric_limits<uint64_t>::max() /
                    dispatch_threads
        ? std::numeric_limits<uint64_t>::max()
        : dispatch_blocks * dispatch_threads;
    const uint64_t hard_batch = std::min<uint64_t>(
        std::min<uint64_t>(
            requested_batch,
            static_cast<uint64_t>(
                std::numeric_limits<uint32_t>::max())),
        dispatch_capacity);

    metalDeviceProp properties{};
    metalError_t st = metalGetDeviceProperties(&properties, DEVICE_NR);
    if (st != metalSuccess) {
        recovery_direct_release(recovery_ctx);
        if (progress_owner) progress.end();
        return st;
    }
    modeinfra::MemoryDeviceInfo memory_info{
        properties.recommendedMaxWorkingSetSize,
        properties.currentAllocatedSize,
        properties.maxBufferLength,
        properties.hasUnifiedMemory != 0,
    };
    modeinfra::MemoryBudget memory_budget;
    const uint64_t fixed_working_set =
        32ull * 1024ull * 1024ull;
    const uint64_t max_words = 24u;
    const uint64_t bytes_per_hit =
        max_words * sizeof(uint16_t) +
        16u * sizeof(uint32_t);
    if (!modeinfra::resolve_memory_budget(
            wallet_memory_spec, {memory_info},
            fixed_working_set + 1024u * bytes_per_hit,
            0u, memory_budget, err)) {
        fprintf(stderr, "[!] Scramble memory error: %s [!]\n", err.c_str());
        recovery_direct_release(recovery_ctx);
        if (progress_owner) progress.end();
        return metalErrorInvalidValue;
    }
    const uint64_t spare =
        memory_budget.per_device_budget > fixed_working_set
        ? memory_budget.per_device_budget - fixed_working_set
        : 0u;
    const uint32_t out_capacity = static_cast<uint32_t>(
        std::max<uint64_t>(
            1024u,
            std::min<uint64_t>(
                262144u,
                std::min<uint64_t>(
                    spare / std::max<uint64_t>(bytes_per_hit, 1u),
                    properties.maxBufferLength /
                        (max_words * sizeof(uint16_t))))));

    uint16_t* d_unique_ids = nullptr;
    uint16_t* d_counts = nullptr;
    uint16_t* d_template = nullptr;
    uint16_t* d_positions = nullptr;
    uint32_t* d_allowed = nullptr;
    uint64_t* d_base = nullptr;
    uint64_t* d_domain = nullptr;
    uint16_t* d_out_ids = nullptr;
    uint32_t* d_out_count = nullptr;
    uint32_t* d_master_words = nullptr;
    auto allocate = [&](void** pointer, size_t bytes,
                        const char* label) -> bool {
        st = metalMalloc(pointer, std::max<size_t>(bytes, 1u));
        if (st != metalSuccess) {
            err = std::string("metalMalloc ") + label + " failed";
            return false;
        }
        return true;
    };
    if (!allocate(reinterpret_cast<void**>(&d_unique_ids), 24u * sizeof(uint16_t), "unique ids") ||
        !allocate(reinterpret_cast<void**>(&d_counts), 24u * sizeof(uint16_t), "counts") ||
        !allocate(reinterpret_cast<void**>(&d_template), 24u * sizeof(uint16_t), "template") ||
        !allocate(reinterpret_cast<void**>(&d_positions), 24u * sizeof(uint16_t), "positions") ||
        !allocate(reinterpret_cast<void**>(&d_allowed), 24u * sizeof(uint32_t), "allowed masks") ||
        !allocate(reinterpret_cast<void**>(&d_base), 4u * sizeof(uint64_t), "base ordinal") ||
        !allocate(reinterpret_cast<void**>(&d_domain), 4u * sizeof(uint64_t), "domain") ||
        !allocate(reinterpret_cast<void**>(&d_out_ids),
            static_cast<size_t>(out_capacity) * max_words * sizeof(uint16_t), "output ids") ||
        !allocate(reinterpret_cast<void**>(&d_out_count), sizeof(uint32_t), "output count") ||
        (use_fused_path &&
         !allocate(reinterpret_cast<void**>(&d_master_words),
            static_cast<size_t>(out_capacity) * 16u * sizeof(uint32_t), "master words"))) {
        fprintf(stderr, "[!] Scramble runtime error: %s [!]\n", err.c_str());
        st = metalErrorMemoryAllocation;
        goto scramble_cleanup;
    }

    progress.set_allocated_working_set(
        static_cast<uint64_t>(out_capacity) * bytes_per_hit +
        fixed_working_set);
    progress.set_targets(1u, 1u, 0u);
    if (recovery_partition_is_log_owner()) {
        printf("[!] Mnemonic scramble: tasks=%llu pattern=%s batch=%llu output-capacity=%u engine=%s [!]\n",
            static_cast<unsigned long long>(tasks.size()),
            pattern.empty() ? "<all positions>" : pattern.c_str(),
            static_cast<unsigned long long>(hard_batch),
            out_capacity,
            use_fused_path ? "staged GPU" : "compatibility");
    }

    for (size_t task_index = 0u;
         task_index < tasks.size(); ++task_index) {
        MnemonicScramblePreparedTask& task = tasks[task_index];
        if (!recovery_direct_select_wordlist(
                recovery_ctx, task.recovery, err)) {
            st = metalErrorUnknown;
            goto scramble_cleanup;
        }
        modeinfra::U256 begin = requested_start;
        modeinfra::U256 end =
            explicit_end ? requested_end : task.domain_size;
        if (modeinfra::compare(begin, end) >= 0 ||
            modeinfra::compare(end, task.domain_size) > 0) {
            err = "require 0 <= -start < -end <= permutation domain";
            st = metalErrorInvalidValue;
            goto scramble_cleanup;
        }
        if (recovery_partition_active()) {
            modeinfra::U256 local_begin{};
            modeinfra::U256 local_end{};
            if (!scramble_partition_interval(
                    begin, end,
                    g_recovery_multi_gpu_partition.index,
                    g_recovery_multi_gpu_partition.count,
                    local_begin, local_end, err)) {
                st = metalErrorInvalidValue;
                goto scramble_cleanup;
            }
            begin = local_begin;
            end = local_end;
        }
        if (modeinfra::compare(begin, end) >= 0) continue;

        st = metalMemcpy(
            d_unique_ids, task.unique_ids.data(),
            task.unique_ids.size() * sizeof(uint16_t),
            metalMemcpyHostToDevice);
        if (st == metalSuccess) {
            st = metalMemcpy(
                d_counts, task.counts.data(),
                task.counts.size() * sizeof(uint16_t),
                metalMemcpyHostToDevice);
        }
        if (st == metalSuccess) {
            st = metalMemcpy(
                d_template, task.output_template.data(),
                task.output_template.size() * sizeof(uint16_t),
                metalMemcpyHostToDevice);
        }
        if (st == metalSuccess && !task.movable_positions.empty()) {
            st = metalMemcpy(
                d_positions, task.movable_positions.data(),
                task.movable_positions.size() * sizeof(uint16_t),
                metalMemcpyHostToDevice);
        }
        if (st == metalSuccess) {
            st = metalMemcpy(
                d_allowed, task.allowed_masks.data(),
                task.allowed_masks.size() * sizeof(uint32_t),
                metalMemcpyHostToDevice);
        }
        if (st == metalSuccess) {
            st = metalMemcpy(
                d_domain, task.domain_size.limbs.data(),
                4u * sizeof(uint64_t), metalMemcpyHostToDevice);
        }
        if (st != metalSuccess) {
            err = "failed to upload scramble task";
            goto scramble_cleanup;
        }
        if (recovery_partition_is_log_owner()) {
            printf("[!] Scramble task %llu/%llu: words=%llu movable=%llu domain=0x%s range=[0x%s,0x%s) [!]\n",
                static_cast<unsigned long long>(task_index + 1u),
                static_cast<unsigned long long>(tasks.size()),
                static_cast<unsigned long long>(task.recovery.ids.size()),
                static_cast<unsigned long long>(task.movable_positions.size()),
                modeinfra::u256_hex(task.domain_size).c_str(),
                modeinfra::u256_hex(begin).c_str(),
                modeinfra::u256_hex(end).c_str());
        }

        struct PendingWindow {
            modeinfra::U256 begin{};
            uint64_t count = 0u;
        };
        std::vector<PendingWindow> pending;
        modeinfra::U256 cursor = begin;
        while (modeinfra::compare(cursor, end) < 0) {
            modeinfra::U256 remaining{};
            if (!modeinfra::subtract_checked(end, cursor, remaining)) {
                err = "scramble scheduler underflow";
                st = metalErrorUnknown;
                goto scramble_cleanup;
            }
            const uint64_t count =
                scramble_bounded_window(remaining, hard_batch);
            if (count == 0u) {
                err = "scramble scheduler produced an empty window";
                st = metalErrorUnknown;
                goto scramble_cleanup;
            }
            pending.push_back({cursor, count});
            modeinfra::U256 next{};
            if (!modeinfra::add_checked(
                    cursor, modeinfra::U256::from_u64(count), next)) {
                err = "scramble scheduler overflow";
                st = metalErrorUnknown;
                goto scramble_cleanup;
            }
            cursor = next;

            while (!pending.empty()) {
                PendingWindow window = pending.back();
                pending.pop_back();
                st = metalMemcpy(
                    d_base, window.begin.limbs.data(),
                    4u * sizeof(uint64_t), metalMemcpyHostToDevice);
                if (st == metalSuccess) {
                    st = metalMemset(
                        d_out_count, 0, sizeof(uint32_t));
                }
                if (st != metalSuccess) {
                    err = "failed to prepare scramble window";
                    goto scramble_cleanup;
                }
                const uint32_t threads =
                    static_cast<uint32_t>(dispatch_threads);
                const uint32_t blocks = static_cast<uint32_t>(
                    std::min<uint64_t>(
                        dispatch_blocks,
                        std::max<uint64_t>(
                            1u,
                            (window.count + threads - 1u) /
                                threads)));
                const auto readback_started =
                    std::chrono::steady_clock::now();
                st = launchWorkerMnemonicScramble(
                    d_unique_ids, d_counts,
                    static_cast<uint32_t>(task.unique_ids.size()),
                    d_template,
                    static_cast<uint32_t>(task.recovery.ids.size()),
                    d_positions,
                    static_cast<uint32_t>(
                        task.movable_positions.size()),
                    d_allowed, d_base, d_domain,
                    window.count, d_out_ids, d_out_count,
                    out_capacity, blocks, threads);
                if (st == metalSuccess) st = metalDeviceSynchronize();
                uint32_t found_total = 0u;
                if (st == metalSuccess) {
                    st = metalMemcpy(
                        &found_total, d_out_count,
                        sizeof(uint32_t), metalMemcpyDeviceToHost);
                }
                if (st != metalSuccess) {
                    err = "scramble kernel/readback failed";
                    goto scramble_cleanup;
                }
                const uint64_t readback_ns =
                    static_cast<uint64_t>(
                        std::chrono::duration_cast<
                            std::chrono::nanoseconds>(
                            std::chrono::steady_clock::now() -
                            readback_started).count());
                if (found_total > out_capacity &&
                    window.count > 1u) {
                    const uint64_t left = window.count >> 1u;
                    modeinfra::U256 right_begin{};
                    if (!modeinfra::add_checked(
                            window.begin,
                            modeinfra::U256::from_u64(left),
                            right_begin)) {
                        err = "scramble overflow retry arithmetic failed";
                        st = metalErrorUnknown;
                        goto scramble_cleanup;
                    }
                    pending.push_back({
                        right_begin, window.count - left
                    });
                    pending.push_back({window.begin, left});
                    continue;
                }
                const uint32_t eval_count =
                    std::min(found_total, out_capacity);
                if (eval_count != 0u) {
                    if (use_fused_path) {
                        const uint32_t eval_blocks =
                            static_cast<uint32_t>(
                                std::min<uint64_t>(
                                    BLOCK_NUMBER == 0u
                                        ? 1024u : BLOCK_NUMBER,
                                    std::max<uint64_t>(
                                        1u,
                                        (static_cast<uint64_t>(
                                             eval_count) +
                                         threads - 1u) /
                                            threads)));
                        st = launchWorkerRecoverySeedBatch(
                            d_out_ids,
                            static_cast<int>(
                                task.recovery.ids.size()),
                            eval_count,
                            passwords_dev,
                            passwords_lenght_dev,
                            recovery_ctx.devIter,
                            recovery_ctx.iteration_size,
                            d_master_words,
                            eval_blocks, threads);
                        if (st == metalSuccess) {
                            st =
                                launchWorkerRecoveryEvalMasterBatch(
                                    recovery_ctx.buffIsResult,
                                    recovery_ctx.buffDeviceResult,
                                    _dev_precomp,
                                    pitch,
                                    d_out_ids,
                                    d_master_words,
                                    static_cast<int>(
                                        task.recovery.ids.size()),
                                    eval_count,
                                    recovery_ctx.devDerivationList,
                                    recovery_ctx.devDerIndex,
                                    derIndex_size,
                                    0u,
                                    passwords_dev,
                                    passwords_lenght_dev,
                                    0u,
                                    Rounds,
                                    MNEMONIC_MODE,
                                    IS_STRING,
                                    dub_mnem,
                                    eval_blocks, threads);
                        }
                        if (st == metalSuccess) {
                            st = metalDeviceSynchronize();
                        }
                    } else {
                        std::vector<uint16_t> host_ids(
                            static_cast<size_t>(eval_count) *
                            task.recovery.ids.size());
                        st = metalMemcpy(
                            host_ids.data(), d_out_ids,
                            host_ids.size() * sizeof(uint16_t),
                            metalMemcpyDeviceToHost);
                        if (st == metalSuccess &&
                            !recovery_direct_append_batch_u16(
                                recovery_ctx, task.recovery,
                                host_ids.data(),
                                task.recovery.ids.size(),
                                eval_count, err)) {
                            st = metalErrorUnknown;
                        }
                    }
                    if (st != metalSuccess) {
                        if (err.empty()) {
                            err = "scramble candidate evaluation failed";
                        }
                        goto scramble_cleanup;
                    }
                }
                if (read_result_flag_host(
                        recovery_ctx.buffIsResult)) {
                    clear_result_flag_host(
                        recovery_ctx.buffIsResult);
                    SaveResult(
                        OUT_FILE, Founds, save,
                        Derivations_list);
                }
                counterTotal += window.count;
                progress.credit_completed(
                    window.count, window.count,
                    eval_count, readback_ns);
                progress.set_founds(Founds);
            }
        }
    }

    if (!use_fused_path &&
        !recovery_direct_finalize(recovery_ctx, err)) {
        st = metalErrorUnknown;
    }

scramble_cleanup:
    if (d_unique_ids) metalFree(d_unique_ids);
    if (d_counts) metalFree(d_counts);
    if (d_template) metalFree(d_template);
    if (d_positions) metalFree(d_positions);
    if (d_allowed) metalFree(d_allowed);
    if (d_base) metalFree(d_base);
    if (d_domain) metalFree(d_domain);
    if (d_out_ids) metalFree(d_out_ids);
    if (d_out_count) metalFree(d_out_count);
    if (d_master_words) metalFree(d_master_words);
    recovery_direct_release(recovery_ctx);
    if (st != metalSuccess && !err.empty()) {
        fprintf(stderr, "[!] Scramble runtime error: %s [!]\n", err.c_str());
    }
    if (progress_owner) progress.end();
    return st;
}








#define rotl32_h(n,d) (((n) << (d)) | ((n) >> (32 - (d))))
// SWAP256_host: swaps 256 host.
inline uint32_t SWAP256_host(uint32_t val) {
    return (rotl32_h(((val) & (uint32_t)0x00FF00FF), (uint32_t)24U) | rotl32_h(((val) & (uint32_t)0xFF00FF00), (uint32_t)8U));
}

