#define METAL_HELP_FULL_TARGET_TYPES_FOR_C \
"[!] HASH TYPES FOR -c [!]\n" \
"[!] c - BTC compressed hash160\n" \
"[!] u - BTC uncompressed hash160\n" \
"[!] s - BTC segwit base58 hash160\n" \
"[!] p - BTC segwit p2wsh hash160\n" \
"[!] r - BTC taproot hash\n" \
"[!] e - Ethereum address\n" \
"[!] x - secp256k1 pubkey X coordinate\n" \
"[!] T - TON\n" \
"[!]        -ton-type LIST              TON address variants:\n" \
"[!]                                    1=v1r1, 2=v1r2, 3=v1r3, 4=v2r1, 5=v2r2,\n" \
"[!]                                    6=v3r1, 7=v3r2, 8=v4r1, 9=v4r2, 10=v5r1,\n" \
"[!]                                    11=hv1, 12=hv2, 13=hv3. Ranges allowed: 1,2,4-10.\n" \
"[!] S - Solana\n" \
