static void printHelpRange(const char* start_marker, const char* end_marker = nullptr) {
    const char* start = std::strstr(kLegacyDetailedHelp, start_marker);
    if (start == nullptr) {
        std::printf("[!] Help section not found: %s [!]\n", start_marker);
        return;
    }
    const char* end = nullptr;
    if (end_marker != nullptr) {
        end = std::strstr(start, end_marker);
    }
    if (end == nullptr) {
        end = kLegacyDetailedHelp + std::strlen(kLegacyDetailedHelp);
    }
    if (end <= start) {
        std::printf("[!] Help section is empty: %s [!]\n", start_marker);
        return;
    }
    std::fwrite(start, 1, static_cast<size_t>(end - start), stdout);
    if (*(end - 1) != '\n') std::putchar('\n');
}

