static void printHelpInputFileFlowSection(HelpTopic topic) {
    if (!helpTopicUsesDirectoryInputFlow(topic)) return;
    puts(R"HELP(
[!] ======================================================================
[!] FILE INPUT MODIFIERS
[!] ======================================================================
[!] -f DIR                          Recursively scan directory as input source.
[!]                                 Normal scan adds .txt files; use -all for every file.
[!] -all                            With -f, include all files instead of only .txt.
)HELP");
    if (helpTopicSupportsCryptedInput(topic)) {
        puts(R"HELP([!] -crypted                       Decode CRYPTED:<*************> input before normal processing;
[!]                                 saved sensitive input/private fields are protected.
)HELP");
    }
    if (helpTopicUsesFileDeleteFlow(topic)) {
        puts(R"HELP([!] -delete                         Delete each processed input file after its file wrapper finishes.
)HELP");
    }
    if (helpTopicUsesCombinationFileFlow(topic)) {
        puts(R"HELP([!] -comb N1,N2-N3,...              File-input combo generator from words in each input file.
[!] -space                          With -comb, join selected words using spaces.
[!] -rep                            With -comb, allow repeated word positions.
[!]                                 These apply to file-input wrappers, not STDIN/PRNG/seq/random.
)HELP");
    }
}

