static void printHelpTopic(HelpTopic topic) {
    if (topic == HelpTopic::Short) {
        printHelpShort();
        return;
    }
    std::printf("\n[!] ================== METAL_CRYPTO_TOOLKIT DETAILED HELP: %s ==================\n", help_topic_command(topic));
    std::printf("[!] Use -help for the short main mode list. [!]\n");
    printHelpModeSection(topic);
    if (topic == HelpTopic::Recovery) {
        printHelpRecoveryStandaloneExtraSection();
    }
    if (topic == HelpTopic::ProfanityRecovery) {
        printHelpProfanityRecoveryArgsSection();
    }
    printHelpInputFileFlowSection(topic);
    if (helpTopicUsesCommonBruteSections(topic)) {
        printHelpCommonBruteSections();
    }
    if (helpTopicUsesWalletPasswordCommonSection(topic)) {
        printHelpWalletPasswordCommonSection();
    }
    if (helpTopicUsesWalletScryptMemSection(topic)) {
        printHelpWalletScryptMemSection();
    }
    if (helpTopicUsesFullTargetFilterCommonSection(topic)) {
        printHelpFullTargetFilterCommonSection(topic);
    }
    if (helpTopicUsesSecpTargetFilterCommonSection(topic)) {
        printHelpSecpTargetFilterCommonSection();
    }
    if (topic == HelpTopic::WalletScan) {
        printHelpWalletScanCommonSection();
    }
    if (helpTopicUsesPrngSection(topic)) {
        printHelpPrngSection();
    }
    std::printf("[!] ======================================================================\n");
    std::printf("[!] End of detailed help for %s [!]\n", help_topic_command(topic));
}

static void printUnknownParameterHint(const char* arg, HelpTopic topic) {
    std::cerr << "[!] Unknown parameter: " << (arg != nullptr ? arg : "") << " [!]" << std::endl;
    std::cerr << "[!] Use -help for short mode list, or <mode> -help for detailed help [!]" << std::endl;
    if (topic == HelpTopic::Short) {
        std::cerr << "[!] Example: METAL_CRYPTO_TOOLKIT -help [!]" << std::endl;
    }
    else {
        std::cerr << "[!] Example: METAL_CRYPTO_TOOLKIT " << help_topic_command(topic) << " -help [!]" << std::endl;
    }
}

static bool walletjs_is_supported_cli_profile(const char* raw, std::string& err)
{
    if (raw == nullptr || raw[0] == '\0') {
        err = "-walletjs requires PROFILE";
        return false;
    }
    std::string p(raw);
    std::transform(p.begin(), p.end(), p.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
    });
    static const char* const profiles[] = {
        "cryptojs-sha256",
        "bitaddress-sha256",
        "brain-sha256",
        "jsbn-arc4-v8-2011",
        "jsbn-arc4-v8-2015",
        "jsbn-arc4-spidermonkey-lcg48",
        "jsbn-arc4-jsc-weakrandom",
        "jsbn-arc4-v8-2011-exact",
        "jsbn-arc4-v8-2015-exact",
        "jsbn-arc4-spidermonkey-lcg48-exact",
        "jsbn-arc4-jsc-weakrandom-exact",
    };
    for (const char* profile : profiles) {
        if (p == profile) return true;
    }
    err = "unsupported walletjs profile '" + std::string(raw) + "'";
    return false;
}

