        g_bsgs_active_targets.store(0, std::memory_order_relaxed);
        g_bsgs_founds.store(0, std::memory_order_relaxed);
        g_bsgs_total_targets.store(0, std::memory_order_relaxed);

        const std::time_t started =
            std::chrono::system_clock::to_time_t(
                std::chrono::system_clock::now());
        std::cout << "[!] Program started at: " << std::ctime(&started);

        std::thread speed_thread(SpeedThreadFunc);
        const bsgs::RuntimeHooks hooks{
            [](std::uint64_t operations) {
                counterTotal += operations;
            },
            [](bsgs::SpeedPhase phase,
               std::uint64_t phase_total,
               double covered_scalars_per_operation,
               std::uint32_t active_targets) {
                g_bsgs_phase_start_operations.store(
                    counterTotal.load(), std::memory_order_release);
                g_bsgs_speed_phase.store(
                    static_cast<uint32_t>(phase),
                    std::memory_order_release);
                g_bsgs_phase_total.store(
                    phase_total, std::memory_order_release);
                g_bsgs_covered_scalars_per_operation.store(
                    covered_scalars_per_operation,
                    std::memory_order_release);
                g_bsgs_active_targets.store(
                    active_targets, std::memory_order_release);
                if (phase == bsgs::SpeedPhase::Search) {
                    const std::uint64_t target_total =
                        static_cast<std::uint64_t>(active_targets) +
                        g_bsgs_founds.load(std::memory_order_acquire);
                    const std::uint32_t bounded_total =
                        static_cast<std::uint32_t>(
                            std::min<std::uint64_t>(
                                target_total,
                                std::numeric_limits<std::uint32_t>::max()));
                    std::uint32_t observed =
                        g_bsgs_total_targets.load(std::memory_order_relaxed);
                    while (observed < bounded_total &&
                           !g_bsgs_total_targets.compare_exchange_weak(
                               observed,
                               bounded_total,
                               std::memory_order_release,
                               std::memory_order_relaxed)) {
                    }
                }
                g_bsgs_speed_epoch.fetch_add(
                    1, std::memory_order_acq_rel);
            },
            []() {
                g_bsgs_founds.fetch_add(1, std::memory_order_release);
                ++Founds;
            }
        };
        const int result = bsgs::run(argc, argv, hooks);
        isRun = false;
        if (speed_thread.joinable()) {
            speed_thread.join();
        }

        const std::time_t finished =
            std::chrono::system_clock::to_time_t(
                std::chrono::system_clock::now());
        std::cout << "\n[!] Processed " << counterTotal
                  << " BSGS point operations. Found: " << Founds
                  << ". Program finished at " << std::ctime(&finished);
        return result;
    }
    if (kangaroo::requested(argc, argv)) {
        KANGAROO_MODE = true;
        counterTotal = 0;
        Founds = 0;
        isRun = true;
        g_kangaroo_equivalent_keys_per_jump.store(0.0, std::memory_order_relaxed);
        g_kangaroo_speed_epoch.store(0, std::memory_order_relaxed);
        g_kangaroo_founds.store(0, std::memory_order_relaxed);

        const std::time_t started =
            std::chrono::system_clock::to_time_t(
                std::chrono::system_clock::now());
        std::cout << "[!] Program started at: " << std::ctime(&started);

        std::thread speed_thread(SpeedThreadFunc);
        const kangaroo::RuntimeHooks hooks{
            [](std::uint64_t operations) {
                counterTotal += operations;
            },
            [](double equivalent_keys_per_jump) {
                g_kangaroo_equivalent_keys_per_jump.store(
                    equivalent_keys_per_jump,
                    std::memory_order_release);
                g_kangaroo_speed_epoch.fetch_add(1, std::memory_order_acq_rel);
            },
            []() {
                g_kangaroo_founds.fetch_add(1, std::memory_order_release);
                ++Founds;
            }
        };
        const int result = kangaroo::run(argc, argv, hooks);
        isRun = false;
        if (speed_thread.joinable()) {
            speed_thread.join();
        }

        const std::time_t finished =
            std::chrono::system_clock::to_time_t(
                std::chrono::system_clock::now());
        std::cout << "\n[!] Processed " << counterTotal
                  << " kangaroo operations. Found: " << Founds
                  << ". Program finished at " << std::ctime(&finished);
        return result;
    }
    if (!readArgs(argc, argv)) {
        return 2;
    }
    const bool brain_extended_requested =
        !brain_profile_arg.empty() ||
        !brain_rules_path.empty() ||
        !brain_combine_path.empty() ||
        brain_combine_mode != "lr";
    if (brain_extended_requested && !BRAIN) {
        std::cerr << "[!] Error: -brain-profile/-brain-rules/-brain-combine options require -brain [!]"
                  << std::endl;
        return 2;
    }
    if (BRAIN) {
        std::string brain_error;
        if (!brain_profile_arg.empty()) {
            brain_input::ProfileSelection profile;
            if (!brain_input::resolve_profile(brain_profile_arg, profile, brain_error)) {
                std::cerr << "[!] Error: " << brain_error << " [!]" << std::endl;
                return 2;
            }
            brainMode = profile.mode;
            Iterations = profile.iterations;
            IS_UTF8 = profile.hexadecimal_iterations;
            std::cout << "[!] Brain profile: " << profile.canonical_name
                      << " | mode=" << static_cast<unsigned>(brainMode)
                      << " | iterations=" << Iterations.front()
                      << (IS_UTF8 ? " | hex-between-rounds" : "")
                      << " [!]" << std::endl;
        }
        if (!brain_input::prepare_configuration(
                brain_rules_path,
                brain_combine_path,
                brain_combine_mode,
                combo_space,
                g_brain_input_configuration,
                brain_error)) {
            std::cerr << "[!] Error: " << brain_error << " [!]" << std::endl;
            return 2;
        }
        if (g_brain_input_configuration.expands_candidates()) {
            if (IS_HEX) {
                std::cerr << "[!] Error: -brain-rules/-brain-combine operate on text candidates and cannot be combined with -hex [!]"
                          << std::endl;
                return 2;
            }
            if (seqMode || isRandom || prng_gen || prng64_gen || hexset_mode ||
                mode_scoped_recovery) {
                std::cerr << "[!] Error: -brain-rules/-brain-combine require external file/stdin input, not seq/random/PRNG/hexset/recovery [!]"
                          << std::endl;
                return 2;
            }
            std::cout << "[!] Brain streaming expander: "
                      << g_brain_input_configuration.rules.size() << " rule(s)";
            if (!brain_combine_path.empty()) {
                std::cout << " | combine=" << brain_combine_mode
                          << " | right="
                          << (g_brain_input_configuration.right_dictionary_resident
                                  ? "resident<=64MiB"
                                  : "streamed");
            }
            std::cout << " [!]" << std::endl;
        }
        brain_input::reset_skipped_candidates();
    }
    if (POETRY_MODE) {
        std::string poetry_error;
        if (use_n_count && !isRandom) {
            std::cerr << "[!] Error: -poetry -n requires -random [!]" << std::endl;
            return 2;
        }
        if (use_n_count && n_number == 0U) {
            std::cerr << "[!] Error: -poetry -n requires N > 0 [!]" << std::endl;
            return 2;
        }
        if (!poetry_validate_cli_surface(argc, argv, poetry_error) ||
            !poetry_prepare_templates(isRandom, use_n_count, g_poetry_templates, g_poetry_dictionary, poetry_error)) {
            std::cerr << "[!] Error: " << poetry_error << " [!]" << std::endl;
            return 2;
        }
        if (!mnemonicFiles.empty() || useDirectory) {
            std::cerr << "[!] Error: Poetry input must be attached to -poetry; use -poetry -i FILE [!]" << std::endl;
            return 2;
        }
    }

    if (is_pending_exact_wallet_seed_mode()) {
        std::cerr << "[!] Error: selected mode is reserved, but its exact GPU worker is not enabled in this build [!]" << std::endl;
        std::cerr << "[!] Use <mode> -help for the expected input format and implementation status [!]" << std::endl;
        return 1;
    }

    metalError_t metalStatus = metalSuccess;

    if (useDirectory && !XP_MODE) {
        for (size_t i = 0; i < FolderList.size(); ++i) {
            scanDir(FolderList[i], mnemonicFiles);
        }
    }

    if (!PROFANITY_MODE && !KEYSTORE_MODE && !WALLETDAT_MODE && !WALLETJS_MODE &&
        !is_browserlike_wallet_mode() && !ELECTRUMWALLET_MODE && !EXODUSSECO_MODE && !BITCOINJWALLET_MODE && !ANDROIDWALLET_MODE && !ARMORYWALLET_MODE && !WALLETSCAN_MODE && !XP_MODE &&
        !IS_PRIV && !IS_MINIKEYS && !POETRY_MODE && !BRAIN && !OLD && !ARMORY)
    {
        bool derivations_loaded = false;
        if (!Derivations_list.empty() && !derIndex.empty()) {
            derivations_loaded = true;
            g_bip_derivations_loaded = true;
        }
        else if (!derivationFiles.empty()) {
            derivations_loaded = parseDerivations(derivationFiles);
            g_bip_derivations_loaded = derivations_loaded;
        }
        else if (!g_substrate_paths_host.empty()) {
