            Derivations_list.push_back("m/");
            if (Iterations.empty()) {
                Iterations.push_back(1);
            }
            derivations_loaded = true;
            g_bip_derivations_loaded = false;
        }
        if (!derivations_loaded) {
            printf("[!] Error: Loading derivations failed! [!]\n");
            return -1;
        }
    }

    finalize_substrate_path_labels();

    derivation_type_mask_host = infer_derivation_type_mask();
    c_counter = active_target_count_for_stats();
    if ((derivation_type_mask_host & ~(DERIVATION_TYPE_MASK_BIP32 | DERIVATION_TYPE_MASK_SLIP0010 | DERIVATION_TYPE_MASK_BIP32_ED25519)) != 0) {
        fprintf(stderr, "[!] Error: invalid derivation type mask [!]\n");
        return 1;
    }
    if (derivation_type_mask_host != 0) {
        printf("[!] Derivation types: %s%s\n",
