            fprintf(stderr, "[!] Error: failed to open output file '%s': %s\n", fileResult.c_str(), std::strerror(errno));
            return 1;
        }
        std::time_t s_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::cout << "[!] Program started at: " << std::ctime(&s_time);
        metalStatus = processWalletScan();
        if (OUT_FILE != nullptr) {
            fclose(OUT_FILE);
            OUT_FILE = nullptr;
        }
        std::time_t e_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::cout << "\n[!] Processed " << counterTotal << " lines. Found: " << Founds << ". Program finished at " << std::ctime(&e_time);
        return metalStatus == metalSuccess ? 0 : 1;
    }

    if (WALLET_LOAD_ONLY) {
        if (save && OUT_FILE == nullptr) {
            OUT_FILE = fopen(fileResult.c_str(), "a");
            if (OUT_FILE == nullptr) {
                fprintf(stderr, "[!] Error: failed to open output file '%s': %s\n", fileResult.c_str(), std::strerror(errno));
                return 1;
            }
        }
        std::time_t s_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::cout << "[!] Program started at: " << std::ctime(&s_time);
        if (KEYSTORE_MODE) {
            metalStatus = processMetalKeystore();
        }
        else if (WALLETDAT_MODE) {
            metalStatus = processMetalWalletDat();
        }
        else if (is_browserlike_wallet_mode()) {
            metalStatus = processMetalBrowserVault();
        }
        else if (ELECTRUMWALLET_MODE) {
            metalStatus = processMetalElectrumWallet();
        }
        else if (EXODUSSECO_MODE) {
            metalStatus = processMetalExodusSeco();
        }
        else if (BITCOINJWALLET_MODE || ANDROIDWALLET_MODE) {
            metalStatus = processMetalBitcoinJWallet();
        }
        else if (ARMORYWALLET_MODE) {
            metalStatus = processMetalArmoryWallet();
        }
        else {
            fprintf(stderr, "[!] Error: -wallet-load-only requires a wallet artifact mode [!]\n");
            metalStatus = metalErrorInvalidValue;
        }
        std::time_t e_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        flush_all_async_save_queues();
        if (OUT_FILE != nullptr) {
            fclose(OUT_FILE);
            OUT_FILE = nullptr;
        }
        std::cout << "\n[!] Processed " << counterTotal << " lines. Found: " << Founds << ". Program finished at " << std::ctime(&e_time);
        return metalStatus == metalSuccess ? 0 : 1;
    }

    if (KEYSTORE_MODE || WALLETDAT_MODE || WALLETJS_MODE || is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE || XP_MODE) { secp256_host = true; Ton_only = false; }
    if (has_secp_output_targets()) { secp256_host = true; }
    if (has_ed_output_targets()) { ed25519_host = true; }
    if (has_generic_derivation_targets() && derivation_type_enabled(DERIVATION_TYPE_MASK_BIP32)) { secp256_host = true; }
    if (has_generic_derivation_targets() && (derivation_type_enabled(DERIVATION_TYPE_MASK_SLIP0010) || derivation_type_enabled(DERIVATION_TYPE_MASK_BIP32_ED25519))) { ed25519_host = true; }
    if (Dot && !g_substrate_paths_host.empty()) { ed25519_host = true; }
    if (Ada && (IS_PRIV || IS_MINIKEYS || POETRY_MODE || BRAIN)) { ed25519_host = true; }
    if (Ethereum || Compressed || Uncompressed || Segwit || P2wsh || Xpoint || Solana || Taproot || Dot || Aptos || Sui || Xrp || Iota || Ada || Icp || Fil || Xtz) { Ton_only = false; }

    if (!set_bit)
    {
        if (PROFANITY_MODE || XP_MODE)
        {
            PARAM_ECMULT_WINDOW_SIZE = 16;
        }
        else if (RECOVERY_MODE)
