            // BIP39-like recovery runs are usually short and startup-bound, so use a lighter secp table.
            PARAM_ECMULT_WINDOW_SIZE = 10;
        }
        else if (IS_PRIV || IS_MINIKEYS || POETRY_MODE)
        {
            PARAM_ECMULT_WINDOW_SIZE = 18;
