        {
            for (int i = 1; i <= PRNG32_MODE_MAX; i++)
            {
                PrngModes.push_back(i);
            }

        }
    }
    else if (prng64_gen)
    {
        if (!gen_set)
        {

            for (int i = 1; i <= PRNG64_GEN_MAX; i++)
            {
                Gens.push_back(i);
            }
        }
        if (!mode_set)
        {
            for (int i = 1; i <= PRNG64_MODE_MAX; i++)
            {
                PrngModes.push_back(i);
            }

