            fprintf(stderr, "Metal error on device %d: %s\n", ctx.device_id, metalGetErrorString(err));
        }
    }
    activate_gpu_context(g_gpu_contexts.front());
    if (!IS_PRIV && !IS_MINIKEYS && !POETRY_MODE && !BRAIN && !KEYSTORE_MODE && !WALLETDAT_MODE && !WALLETJS_MODE &&
        !is_browserlike_wallet_mode() && !ELECTRUMWALLET_MODE && !EXODUSSECO_MODE && !BITCOINJWALLET_MODE && !ANDROIDWALLET_MODE && !ARMORYWALLET_MODE && !WALLETSCAN_MODE && !XP_MODE) {
        if (OLD)
        {
            if (!set_deep) { deep = 20; }
            for (auto& ctx : g_gpu_contexts) {
                if (!activate_gpu_context(ctx)) {
                    continue;
                }
                metal_launch("SetDeep", 1, 1, deep);
                metalDeviceSynchronize();
            }
            activate_gpu_context(g_gpu_contexts.front());

            cerr << "[!] Getting " << deep << " receiving and " << deep << " change child addresses from old Electrum [!]\n";
        }
        else if (ARMORY)
        {
            cerr << "[!] Getting " << deep + 1 << " child addresses from Armory Easy16 paper backup [!]\n";
        }
        else
        {
            cerr << "[!] Loaded " << derIndex_size << " derivations from the file: ";
            for (size_t i = 0; i < derivationFiles.size(); ++i) {
                std::cout << derivationFiles[i] << " ";
            }
            cerr << endl;
        }

    }
    if (mnemonicFiles.size() > 0)
    {
        cout << "[!] Phrases file: ";
        for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
            std::cout << mnemonicFiles[i] << " ";
        }
        cout << endl;
    }
    std::time_t s_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    std::cout << "[!] Program started at: " << std::ctime(&s_time);

    if (pass_thread_mode)
        printf("[!] pass_thread mode active: one mnemonic per round, passwords split across threads/GPUs [!]\n");
    if (der_thread_mode)
        printf("[!] der_thread mode active: derivations distributed across GPU threads [!]\n");

    std::thread speedThread;
    auto stopSpeedThread = [&]() {
        isRun = false;
        if (speedThread.joinable())
            speedThread.join();

        };
    speedThread = std::thread(SpeedThreadFunc);

    if (POETRY_MODE)
    {
        metalStatus = processMetalPoetry();
    }
    else if (KEYSTORE_MODE)
    {
        metalStatus = processMetalKeystore();
    }
    else if (WALLETDAT_MODE)
    {
        metalStatus = processMetalWalletDat();
    }
    else if (WALLETJS_MODE)
    {
        metalStatus = processMetalWalletJS();
    }
    else if (is_browserlike_wallet_mode())
    {
        metalStatus = processMetalBrowserVault();
    }
    else if (ELECTRUMWALLET_MODE)
    {
        metalStatus = processMetalElectrumWallet();
    }
    else if (EXODUSSECO_MODE)
    {
        metalStatus = processMetalExodusSeco();
    }
    else if (BITCOINJWALLET_MODE || ANDROIDWALLET_MODE)
    {
        metalStatus = processMetalBitcoinJWallet();
    }
    else if (ARMORYWALLET_MODE)
    {
        metalStatus = processMetalArmoryWallet();
    }
    else if (WALLETSCAN_MODE)
    {
        metalStatus = processWalletScan();
    }
    else if (XP_MODE)
    {
        printf("[!] starting XP historical replay mode [!]\n");
        if (xp_profile_kind == XP_PROFILE_OPENSSL) {
            printf("[!] XP profile: openssl, PID range: %08x..%08x, keys/PID: %llu, paths: %u [!]\n",
                start_seed, end_seed, static_cast<unsigned long long>(n_number), xp_path_count);
            printf("[!] XP warning: openssl:* is a legacy experimental candidate scan, not an article-exact XP/OpenSSL reconstruction [!]\n");
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN) {
            printf("[!] XP profile: randstorm ARC4, state range: %016llx..%016llx, profiles: %u, keys/state: %llu [!]\n",
                static_cast<unsigned long long>(start_seed64),
                static_cast<unsigned long long>(end_seed64),
                xp_path_count,
                static_cast<unsigned long long>(n_number));
            if (walletjs_time_start_seen && walletjs_time_end_seen) {
                if (xp_randstorm_time_mode == 2u) {
                    printf("[!] XP randstorm time offset range: %u..%u ms delta=0..%u ms [!]\n",
                        walletjs_time_start, walletjs_time_end, walletjs_time_delta_max);
                }
                else {
                    printf("[!] XP randstorm time low32 range: %08x..%08x delta=0..%u ms [!]\n",
