            }
            if (xp_randstorm_time_mode == 1u) {
                printf("[!] XP randstorm time mode: seed-sec-ms (source*1000 + offset) [!]\n");
            }
            else if (xp_randstorm_time_mode == 2u) {
                printf("[!] XP randstorm time mode: seed-ms-offset (source + offset) [!]\n");
            }
            if (xp_randstorm_seed_event_count_host() != 0u) {
