                    fprintf(stderr, "[!] Error: -profanity -recovery -i requires file path [!]\n");
                    metalStatus = metalErrorInvalidValue;
                }
                else if (isRandom) {
                    fprintf(stderr, "[!] Error: -profanity -recovery does not use -random [!]\n");
                    metalStatus = metalErrorInvalidValue;
                }
                else {
                    printf("[!] starting PROFANITY recovery batch mode [!]\n");
                    printf("[!] recovery file: %s [!]\n", profanity_recovery_file_path.c_str());
                    printf("[!] rounds per pubkey pass: %llu [!]\n", static_cast<unsigned long long>(n_number));
                    metalStatus = processMetalProfanityRecoveryFile();
                }
            }
            else if (profanity_target_hex.empty()) {
                fprintf(stderr, "[!] Error: -profanity -recovery requires -target HEX/-hash HEX or -i FILE [!]\n");
                metalStatus = metalErrorInvalidValue;
            }
            else if (use_n_count) {
                fprintf(stderr, "[!] Error: -profanity -recovery does not use -n; use -offset HEX for restart [!]\n");
                metalStatus = metalErrorInvalidValue;
            }
            else if (isRandom) {
                fprintf(stderr, "[!] Error: -profanity -recovery does not use -random [!]\n");
                metalStatus = metalErrorInvalidValue;
            }
            else {
                const uint64_t recovery_round_start = profanity_offset_explicit ? profanity_offset : 0ull;
                printf("[!] starting PROFANITY recovery mode [!]\n");
                printf("[!] target pubkey: %s [!]\n", profanity_target_hex.c_str());
                printf("[!] reverse round start: %016llx [!]\n", static_cast<unsigned long long>(recovery_round_start));
                g_profanity_recovery_found_any.store(false, std::memory_order_relaxed);
                g_profanity_recovery_found_round.store(recovery_round_start, std::memory_order_relaxed);
                g_profanity_recovery_window_override_active.store(false, std::memory_order_relaxed);
                g_profanity_recovery_window_end.store(std::numeric_limits<uint64_t>::max(), std::memory_order_relaxed);
                metalStatus = processMetalProfanityRecovery();
            }
        }
        else {
            printf("[!] starting PROFANITY search mode [!]\n");
            printf("[!] seed32 range: %08x..%08x [!]\n", start_seed, end_seed);
            if (isRandom) {
                printf("[!] random seed32 mode: pick random start, then scan sequential seed block [!]\n");
                printf("[!] random sequential seeds per pick: %llu [!]\n",
                    static_cast<unsigned long long>(profanity_random_seeds_per_pick));
            }
            printf("[!] rounds per Metal lane: %llu [!]\n", static_cast<unsigned long long>(use_n_count ? n_number : (1ull << 32)));
            printf("[!] round offset start: %016llx [!]\n", static_cast<unsigned long long>(profanity_offset_explicit ? profanity_offset : 1ull));
            metalStatus = processMetalProfanity();
        }
    }
    else if (MNEMONIC_SCRAMBLE_MODE)
    {
        printf("[!] starting mnemonic scramble mode [!]\n");
