            fprintf(stderr, "[!] Error: recovery mode enabled but no templates were provided [!]\n");
            metalStatus = metalErrorInvalidValue;
        }
        else {
            printf("[!] starting mnemonic recovery mode [!]\n");
            metalStatus = processMetalRecovery();
        }
