            }
            else if (prng_gen)
            {
                printf("[!] using old seed-bytes mode from internal PRNG32 generator.\n");
                if(isRandom)
                {
                    printf("[!] Using random 32 bit PRNG seed [!]\n");
				}
                metalStatus = processMetalOldSeedGen();
            }
            else if (prng64_gen)
            {
                printf("[!] using old seed-bytes mode from internal PRNG64 generator.\n");
                if (isRandom)
                {
                    printf("[!] Using random 64 bit PRNG seed [!]\n");
                }
                metalStatus = processMetalOldSeedGen64();
            }
            else if (hexset_mode)
            {
                print_hexset_startup_banner("old seed hexset forward mode");
                metalStatus = processMetalOldSeedHexsetSeq();
            }
            else if (seqMode)
            {
                size_t len = start_point.size();
                if (len > 1024) {
                    len = 1024;
                }
                char padded_start[1025] = { 0 };
                memset(padded_start, '0', 1024 - len);
                memcpy(padded_start + (1024 - len), start_point.c_str(), len);
                unhex_host((unsigned char*)padded_start, 1024, start_mnemonic_point, 512);
                if (end_point_set)
                {
                    len = end_point.size();
                    if (len > 1024) {
                        len = 1024;
                    }
                    char padded_end[1025] = { 0 };
                    memset(padded_end, '0', 1024 - len);
                    memcpy(padded_end + (1024 - len), end_point.c_str(), len);
                    unhex_host((unsigned char*)padded_end, 1024, end_mnemonic_point, 512);
                }

                if (!isRandom)
                {
                    if (!backward && !both)
                    {
                        if (!end_point_set)
                        {
                            memset(end_mnemonic_point, 0xFF, 512);
                        }
                        printf("[!] starting old seed (bytes) sequential mode + step=0x%llx [!]\n", step);
                        printf("START OLD SEED BYTES POINT: ");
                        printf("%s\n", start_point.c_str());
                        printf("END OLD SEED BYTES POINT: ");
                        if (end_point_set)
                        {
                            printf("%s\n", end_point.c_str());
                        }
                        else
                        {
                            printf("ffffffffffffffffffffffffffffffffff...  (512 bytes)\n");
                        }
                        metalStatus = processMetalOldSeedSeq();
                    }
                    else if (both)
                    {
                        printf("[!] starting old seed (bytes) sequential mode +- step=0x%llx [!]\n", step);
                        printf("START OLD SEED BYTES POINT: ");
                        printf("%s\n", start_point.c_str());
                        print_end_point_text_if_set("END OLD SEED BYTES POINT: ");

                        metalStatus = processMetalOldSeedSeqBoth();
                    }
                    else
                    {
                        if (!end_point_set)
                        {
                            memset(end_mnemonic_point, 0, 512);
                            end_entropy_point[511] = 0x01;
                        }

                        printf("[!] starting old seed (bytes) sequential backward mode - step=0x%llx [!]\n", step);
                        printf("START OLD SEED BYTES POINT: ");
                        printf("%s\n", start_point.c_str());

                        printf("END OLD SEED BYTES POINT: ");
                        if (end_point_set)
                        {
                            printf("%s\n", end_point.c_str());
                        }
                        else
                        {
                            printf("000000000000000000000000000000...01  (512 bytes)\n");
                        }
                        metalStatus = processMetalOldSeedSeqBack();
                    }
                }
                else
                {
                    if (!end_point_set)
                    {
                        printf("[!] Error! need to set -end! [!]\n");
                        exit(0);
                    }
                    uint64_t final_n = BLOCK_NUMBER * BLOCK_THREADS;
                    if (n_number >= final_n)
                    {
                        final_n = n_number;
                    }
                    printf("[!] starting old seed (bytes) sequential random mode +- n=%llu step=0x%llx [!]\n", final_n, step);
                    printf("START OLD SEED POINT: ");
                    printf("%s\n", start_point.c_str());
                    printf("END OLD SEED POINT: ");
                    printf("%s\n", end_point.c_str());

                    metalStatus = processMetalOldSeedRandom();

                }
            }
            else
            {
                if (!isRandom)
                {
                    if (PHRASE_IN) {
                        printf("[!] Using old electrum seeds from external input [!]\n");
                        metalStatus = processMetalOldSeed(cin);
                    }
                    else {
                        printf("[!] Using old electrum seeds from file [!]\n");
                        metalStatus = processMetalOldSeedFile(mnemonicFiles);
                    }
                }
                else
                {
                    printf("[!] using old seeds from internal random generator\n");
                    if (!use_custom_size)
                    {
                        entropy_len = 16;
                    }
                    metalStatus = processMetalOldSeedRandom();
                }
            }
        }
        else
        {
            if (mode_scoped_recovery)
            {
                metalStatus = run_mode_scoped_recovery_templates("old mnemonic recovery hexset mode", processMetalOldRecoveryHexset);
            }
            else if (prng_gen)
            {
                printf("[!] using old mnemonic mode from internal PRNG32 generator.\n");
                metalStatus = processMetalOldGen();
            }
            else if (prng64_gen)
            {
                printf("[!] using old mnemonic mode from internal PRNG64 generator.\n");
                metalStatus = processMetalOldGen64();
            }
            else if (hexset_mode)
            {
                print_hexset_startup_banner("old mnemonic hexset forward mode");
                metalStatus = processMetalOldHexsetSeq();
            }
            else if (seqMode)
            {
                size_t len = start_point.size();
                if (len > 1024) {
                    len = 1024;
                }
                char padded_start[1025] = { 0 };
                memset(padded_start, '0', 1024 - len);
