                unhex_host((unsigned char*)padded_end, 1024, end_mnemonic_point, 512);
            }

            if (!isRandom)
            {
                if (!backward && !both)
                {
                    if (!end_point_set)
                    {
                        memset(end_mnemonic_point, 0xFF, 512);
                    }
                    printf("[!] starting mnemonic (bytes) sequential mode + step=0x%llx [!]\n", step);
                    printf("START MNEMONIC BYTES POINT: ");
                    printf("%s\n", start_point.c_str());
                    printf("END MNEMONIC BYTES POINT: ");
                    if (end_point_set)
                    {
                        printf("%s\n", end_point.c_str());
                    }
                    else
                    {
                        printf("ffffffffffffffffffffffffffffffffff...  (512 bytes)\n");
                    }
                    metalStatus = processMetalSeq();
                }
                else if (both)
                {
                    printf("[!] starting mnemonic (bytes) sequential mode +- step=0x%llx [!]\n", step);
                    printf("START MNEMONIC BYTES POINT: ");
                    printf("%s\n", start_point.c_str());
                    print_end_point_text_if_set("END MNEMONIC BYTES POINT: ");

                    metalStatus = processMetalSeqBoth();
                }
                else
                {
                    if (!end_point_set)
                    {
                        memset(end_mnemonic_point, 0, 512);
                        end_entropy_point[511] = 0x01;
                    }

                    printf("[!] starting mnemonic (bytes) sequential backward mode - step=0x%llx [!]\n", step);
                    printf("START MNEMONIC BYTES POINT: ");
                    printf("%s\n", start_point.c_str());

                    printf("END MNEMONIC BYTES POINT: ");
                    if (end_point_set)
                    {
                        printf("%s\n", end_point.c_str());
                    }
                    else
                    {
                        printf("000000000000000000000000000000...01  (512 bytes)\n");
                    }
                    metalStatus = processMetalSeqBack();
                }
            }
            else
            {
                if (!end_point_set)
                {
                    printf("[!] Error! need to set -end! [!]\n");
                    exit(0);
                }
                uint64_t final_n = BLOCK_NUMBER * BLOCK_THREADS;
                if (n_number >= final_n)
                {
                    final_n = n_number;
                }
                printf("[!] starting MNEMONIC (bytes) sequential random mode +- n=%llu step=0x%llx [!]\n", final_n, step);
                printf("START MNEMONIC POINT: ");
                printf("%s\n", start_point.c_str());
                printf("END MNEMONIC POINT: ");
                printf("%s\n", end_point.c_str());

                metalStatus = processMetal2Random();

            }
        }
        else
        {
            if (!isRandom)
            {
                if (PHRASE_IN) {
                    printf("[!] Using mnemonic from external input\n");
                    metalStatus = processMetal2(cin);
                }
                else {
                    metalStatus = processMetal2File(mnemonicFiles);
                }
            }
            else
            {
                printf("[!] Generate %i words mnemonic from internal random gen.\n", words_count);
                if (!use_custom_size)
                {
                    entropy_len = 16;
                }
                metalStatus = processMetalEntropyRandom();
            }
        }
    }

    stopSpeedThread();

    cout << "\n";
    shutdown_async_save_queues();
    if (BRAIN) {
        const std::uint64_t skipped = brain_input::skipped_candidates();
        if (skipped != 0u) {
            std::cout << "[!] Brain expander skipped " << skipped
                      << " candidate(s) that violated a rule position or the 512-byte limit [!]\n";
        }
    }

    s_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    if (!PROFANITY_MODE && !XP_MODE && !IS_PRIV && !IS_MINIKEYS && !POETRY_MODE)
    {
        std::cout << "\n[!] Processed " << counterTotal << " lines." << " Found: " << Founds << ". Program finished at " << std::ctime(&s_time);
    }
    else
    {
        std::cout << "\n[!] Processed " << counterTotal << " Keys." << " Found: " << Founds << ". Program finished at " << std::ctime(&s_time);
    }
    fclose(OUT_FILE);
    release_all_gpu_contexts();

    if (MNEMONIC_SCRAMBLE_MODE && metalStatus != metalSuccess) {
        return metalStatus == metalErrorInvalidValue ? 2 : 1;
    }
    if (BRAIN && metalStatus != metalSuccess) {
        return 1;
    }
    return ((BIP38_MODE || COPAYWALLET_MODE || TERRAWALLET_MODE ||
             BITSHARESWALLET_MODE || YOROIWALLET_MODE) &&
            metalStatus != metalSuccess) ? 1 : 0;
}

static inline bool crypted_base_priv_mode_selected() {
    return IS_PRIV &&
        !IS_PRIV_RECOVERY &&
        !IS_PRIV_SWAP &&
        !IS_PRIV_BYTE &&
        !IS_PRIV_HASH &&
        !IS_PRIV_PLUS &&
        !IS_PRIV_PLUS_256 &&
        !IS_PRIV_PATTERN &&
        true_priv_mode == 0;
}

static inline bool crypted_default_mnemonic_mode_selected() {
    return !PROFANITY_MODE &&
        !XP_MODE &&
        !KEYSTORE_MODE &&
        !WALLETDAT_MODE &&
        !WALLETJS_MODE &&
        !is_browserlike_wallet_mode() &&
        !ELECTRUMWALLET_MODE &&
        !EXODUSSECO_MODE &&
        !BITCOINJWALLET_MODE &&
        !ANDROIDWALLET_MODE &&
        !ARMORYWALLET_MODE &&
        !WALLETSCAN_MODE &&
        !RECOVERY_MODE &&
        !POETRY_MODE &&
        !IS_PRIV &&
        !IS_MINIKEYS &&
        !SEED &&
        !HMAC &&
        !BIP32 &&
        !BRAIN &&
        !OLD &&
        !ARMORY &&
        !ARMORY_ROOT &&
        !IS_ENTROPY;
}

static inline bool crypted_supported_mode_selected() {
    if (crypted_base_priv_mode_selected()) return true;
    if (OLD && SEED) return true;
    if (OLD && !SEED && !IS_ENTROPY) return true;
    if (SEED && !OLD) return true;
    if (HMAC) return true;
    if (IS_ENTROPY && !OLD) return true;
    if (BIP32) return true;
    if (BRAIN) return true;
    if (ARMORY) return true;
    if (mnemonic_mode_explicit || crypted_default_mnemonic_mode_selected()) return true;
    return false;
}

static inline bool validate_crypted_cli_selection() {
    if (!g_crypted_input_active) {
        return true;
    }
    if (!crypted_supported_mode_selected()) {
        std::cerr << "[!] Error: -crypted is supported only with -mnemonic, -seed, -hmac, -entropy, "
                     "-bip32, base -priv, -old, -old -seed, -armory, and -brain [!]" << std::endl;
        return false;
    }
    if (use_combos) {
        std::cerr << "[!] Error: -crypted cannot be combined with -comb [!]" << std::endl;
        return false;
    }
    if (prng_gen || prng64_gen || hexset_mode || mode_scoped_recovery || seqMode || isRandom ||
        RECOVERY_MODE || pass_thread_mode || der_thread_mode || IS_PRIV_RECOVERY ||
        IS_PRIV_SWAP || IS_PRIV_BYTE || IS_PRIV_HASH || IS_PRIV_PLUS || IS_PRIV_PLUS_256 || IS_PRIV_PATTERN) {
        std::cerr << "[!] Error: -crypted is valid only for external file/folder/stdin input, not internal "
                     "generator, seq, hexset, recovery, thread-inverted, or -priv submode paths [!]" << std::endl;
        return false;
    }
    return true;
}

// readArgs: reads args.
bool readArgs(int argc, char** argv) {
    int a = 1;
    bool target_arg_seen = false;
    std::string target_arg_name;
    std::string target_arg_value;
    while (a < argc) {
        if (strcmp(argv[a], "-device") == 0) {
            a++;
            if (a >= argc) {
                fprintf(stderr, "[!] Error: -device requires value (example: 0 or 0,1,3 or 0-3) [!]\n");
                return false;
            }
            DEVICE_LIST.clear();
            parse_list_or_ranges<int>(argv[a], DEVICE_LIST, true);
            if (DEVICE_LIST.empty()) {
                fprintf(stderr, "[!] Error: invalid -device list '%s' [!]\n", argv[a]);
                return false;
            }
            DEVICE_NR = DEVICE_LIST.front();
            a++;
            continue;
        }
        if (strcmp(argv[a], "-brain-profile") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -brain-profile requires NAME [!]\n");
                return false;
            }
            brain_profile_arg = argv[a + 1];
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-brain-rules") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -brain-rules requires FILE [!]\n");
                return false;
            }
            brain_rules_path = argv[a + 1];
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-brain-combine") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -brain-combine requires FILE [!]\n");
                return false;
            }
            brain_combine_path = argv[a + 1];
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-brain-combine-mode") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -brain-combine-mode requires lr, rl, or both [!]\n");
                return false;
            }
            brain_combine_mode = argv[a + 1];
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-poetry") == 0) {
            std::string poetry_error;
            if (!poetry_cli_consume(argc, argv, a, poetry_error)) {
                fprintf(stderr, "[!] Error: %s [!]\n", poetry_error.c_str());
                return false;
            }
            POETRY_MODE = true;
            continue;
        }
        if (strcmp(argv[a], "-profanity") == 0) {
            PROFANITY_MODE = true;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-xp") == 0) {
            XP_MODE = true;
            a++;
            if (a < argc && !wallet_is_flag_token(argv[a])) {
                xp_profile_arg = argv[a];
                a++;
