                fprintf(stderr, "[!] Error: -mask requires value [!]\n");
                return false;
            }
            wallet_mask_mode = true;
            wallet_masks.push_back(argv[a + 1]);
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-mask-file") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -mask-file requires path [!]\n");
                return false;
            }
            std::ifstream mf(argv[a + 1]);
            if (!mf) {
                fprintf(stderr, "[!] Error: failed to open mask file '%s' [!]\n", argv[a + 1]);
                return false;
            }
            std::string line;
            while (std::getline(mf, line)) {
                trim_crlf_inplace(line);
                line = wallet_trim_copy(line);
                if (!line.empty() && line[0] != '#') {
                    wallet_masks.push_back(line);
                }
            }
            wallet_mask_mode = !wallet_masks.empty();
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-cs1") == 0 || strcmp(argv[a], "-cs2") == 0 ||
            strcmp(argv[a], "-cs3") == 0 || strcmp(argv[a], "-cs4") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: %s requires charset value [!]\n", argv[a]);
                return false;
            }
            const int idx = argv[a][3] - '1';
            wallet_custom_charset[idx] = argv[a + 1];
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-gpu-split") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -gpu-split requires mode: round, seed, or foundid [!]\n");
                return false;
            }
            ProfanityGpuSplitMode parsed = ProfanityGpuSplitMode::Round;
            if (!parse_profanity_gpu_split_mode(argv[a + 1], parsed)) {
                fprintf(stderr, "[!] Error: invalid -gpu-split '%s'; expected round, seed, or foundid [!]\n", argv[a + 1]);
                return false;
            }
            profanity_gpu_split_mode = parsed;
            profanity_gpu_split_explicit = true;
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-random-seeds") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -random-seeds requires positive decimal value [!]\n");
                return false;
            }
            char* end_ptr = nullptr;
            const unsigned long long parsed = strtoull(argv[a + 1], &end_ptr, 10);
            if (end_ptr == argv[a + 1] || *end_ptr != '\0' || parsed == 0ull) {
                fprintf(stderr, "[!] Error: -random-seeds requires N >= 1 [!]\n");
                return false;
            }
            profanity_random_seeds_per_pick = static_cast<uint64_t>(parsed);
            profanity_random_seeds_explicit = true;
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-scramble") == 0) {
            MNEMONIC_SCRAMBLE_MODE = true;
            mnemonic_mode_explicit = true;
            a++;
            if (a < argc && argv[a] != nullptr && argv[a][0] != '-') {
                if (!mnemonic_scramble_inline.empty()) {
                    fprintf(stderr, "[!] Error: -scramble accepts only one inline phrase; use -i FILE for more [!]\n");
                    return false;
                }
                mnemonic_scramble_inline = argv[a];
                a++;
            }
            continue;
        }
        if (strcmp(argv[a], "-pattern") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -pattern requires a positional mnemonic pattern [!]\n");
                return false;
            }
            if (!mnemonic_scramble_pattern.empty() ||
                !mnemonic_scramble_pattern_file.empty()) {
                fprintf(stderr, "[!] Error: use exactly one -pattern or -pattern-file [!]\n");
                return false;
            }
            mnemonic_scramble_pattern = argv[a + 1];
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-pattern-file") == 0) {
            if (a + 1 >= argc) {
                fprintf(stderr, "[!] Error: -pattern-file requires a file path [!]\n");
                return false;
            }
            if (!mnemonic_scramble_pattern.empty() ||
