                a++;
                continue;
            }

            if (strcmp(argv[a + 1], "-i") == 0) {
                if (a + 2 >= argc) {
                    fprintf(stderr, "[!] Error: -recovery -i requires file path [!]\n");
                    return false;
                }
                RecoveryQueueEntry entry;
                entry.type = RecoveryQueueEntryType::File;
                entry.value = argv[a + 2];
                recoveryQueue.emplace_back(std::move(entry));
                a += 3;
                continue;
            }

            RecoveryQueueEntry entry;
            entry.type = RecoveryQueueEntryType::Phrase;
            entry.value = argv[a + 1];
            recoveryQueue.emplace_back(std::move(entry));
            a += 2;
            continue;
        }
