            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '" << argv[a] << "'." << std::endl;
                return false;
            }
            try {
                size_t pos = 0;
                const unsigned long parsed = std::stoul(argv[a + 1], &pos, 10);
                if (pos < std::strlen(argv[a + 1])) {
                    std::cerr << "[!] Error: Invalid value for '" << argv[a] << "'. Expected decimal count." << std::endl;
                    return false;
                }
                if (parsed > 16ul) {
                    std::cerr << "[!] Error: '" << argv[a] << "' is capped at 16 extra rng_seed_time calls." << std::endl;
                    return false;
                }
                const uint32_t preserved_flags = xp_randstorm_seed_events & XP_RANDSTORM_SEED_EVENTS_SCREEN_ZERO_FLAG;
                xp_randstorm_seed_events = preserved_flags | static_cast<uint32_t>(parsed);
                if (repeat_seed_time && parsed != 0ul) {
                    xp_randstorm_seed_events |= XP_RANDSTORM_SEED_EVENTS_REPEAT_FLAG;
                }
            }
            catch (const std::exception& e) {
                std::cerr << "[!] Error: Invalid value for '" << argv[a] << "'. " << e.what() << std::endl;
                return false;
            }
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-screen-seed-zero") == 0) {
            xp_randstorm_seed_events |= XP_RANDSTORM_SEED_EVENTS_SCREEN_ZERO_FLAG;
            xp_randstorm_screen_seed_x = 0u;
            xp_randstorm_screen_seed_y = 0u;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-screen-seed") == 0) {
            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '-screen-seed'." << std::endl;
                return false;
            }
            const std::string screen_seed = argv[a + 1];
            const size_t colon = screen_seed.find(':');
            if (colon == std::string::npos || screen_seed.find(':', colon + 1u) != std::string::npos) {
                std::cerr << "[!] Error: Invalid value for '-screen-seed'. Expected X:Y signed int32 values." << std::endl;
                return false;
            }
            int32_t sx = 0;
            int32_t sy = 0;
            if (!parse_int32_token(screen_seed, 0u, colon, sx) ||
                !parse_int32_token(screen_seed, colon + 1u, screen_seed.size(), sy)) {
                std::cerr << "[!] Error: Invalid value for '-screen-seed'. Expected X:Y signed int32 values." << std::endl;
                return false;
            }
            xp_randstorm_seed_events |= XP_RANDSTORM_SEED_EVENTS_SCREEN_ZERO_FLAG;
            xp_randstorm_screen_seed_x = static_cast<uint32_t>(sx);
            xp_randstorm_screen_seed_y = static_cast<uint32_t>(sy);
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-time-mode") == 0) {
            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '-time-mode'." << std::endl;
                return false;
            }
            std::string mode = argv[a + 1];
            std::transform(mode.begin(), mode.end(), mode.begin(), [](unsigned char ch) {
                return static_cast<char>(std::tolower(ch));
            });
            if (mode == "state" || mode == "source" || mode == "source-low32" || mode == "low32") {
                xp_randstorm_time_mode = 0u;
            }
            else if (mode == "seed-sec-ms" || mode == "sec-ms" || mode == "seconds-ms") {
                xp_randstorm_time_mode = 1u;
            }
            else if (mode == "seed-ms-offset" || mode == "ms-offset" || mode == "seed-ms") {
                xp_randstorm_time_mode = 2u;
            }
            else {
                std::cerr << "[!] Error: Invalid value for '-time-mode'. Expected state, seed-sec-ms, or seed-ms-offset." << std::endl;
                return false;
            }
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-mileage") == 0) {
            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '-mileage'." << std::endl;
                return false;
            }
            try {
                size_t pos = 0;
                const unsigned long parsed = std::stoul(argv[a + 1], &pos, 10);
                if (pos < std::strlen(argv[a + 1]) || parsed > static_cast<unsigned long>(UINT32_MAX)) {
                    std::cerr << "[!] Error: Invalid value for '-mileage'. Expected decimal count 0.." << UINT32_MAX << "." << std::endl;
                    return false;
                }
                xp_randstorm_mileage_start = 0u;
                xp_randstorm_mileage_end = static_cast<uint32_t>(parsed);
                xp_randstorm_mileage_start_seen = true;
                xp_randstorm_mileage_end_seen = true;
            }
            catch (const std::exception& e) {
                std::cerr << "[!] Error: Invalid value for '-mileage'. " << e.what() << std::endl;
                return false;
            }
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-mileage-s") == 0 || strcmp(argv[a], "-mileage-e") == 0) {
            const bool is_start = (strcmp(argv[a], "-mileage-s") == 0);
            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '" << argv[a] << "'." << std::endl;
                return false;
            }
            try {
                size_t pos = 0;
                const unsigned long parsed = std::stoul(argv[a + 1], &pos, 10);
                if (pos < std::strlen(argv[a + 1]) || parsed > static_cast<unsigned long>(UINT32_MAX)) {
                    std::cerr << "[!] Error: Invalid value for '" << argv[a] << "'. Expected decimal count 0.." << UINT32_MAX << "." << std::endl;
                    return false;
                }
                if (is_start) {
                    xp_randstorm_mileage_start = static_cast<uint32_t>(parsed);
                    xp_randstorm_mileage_start_seen = true;
                }
                else {
                    xp_randstorm_mileage_end = static_cast<uint32_t>(parsed);
                    xp_randstorm_mileage_end_seen = true;
                }
            }
            catch (const std::exception& e) {
                std::cerr << "[!] Error: Invalid value for '" << argv[a] << "'. " << e.what() << std::endl;
                return false;
            }
            a += 2;
            continue;
        }
        if (strcmp(argv[a], "-byte") == 0)
        {
            parse_list_or_ranges<int>(argv[a + 1], PrngBytes, false);


            a++;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-pb") == 0)
        {
            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '-pb'." << std::endl;
                return false;
            }

            priv_pattern_raw_arg = argv[a + 1];
            priv_pattern_arg_seen = true;
            parse_list_or_ranges<int>(argv[a + 1], PvkBytes, false);


            a++;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-minikeys") == 0) {
            IS_MINIKEYS = true;
            IS_PRIV = false;
            IS_PRIV_SWAP = false;
            IS_PRIV_BYTE = false;
            IS_PRIV_HASH = false;
            IS_PRIV_PLUS = false;
            IS_PRIV_PLUS_256 = false;
            IS_PRIV_PATTERN = false;
            true_priv_mode = 0;
            std::cerr << "[!] Set mode to mini keys (Casascius-style) [!]" << std::endl;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-last") == 0)
        {
            priv_pattern_last_cycle = true;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-mode") == 0)
        {
            parse_list_or_ranges<int>(argv[a + 1], PrngModes, true);

            mode_set = true;
            a++;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-gen") == 0)
        {
            parse_list_or_ranges<int>(argv[a + 1], Gens, true);
            gen_set = true;

            a++;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-w") == 0) {
            if (a + 1 >= argc) {
                std::cerr << "[!] Missing value after '-w'." << std::endl;
                return false;
            }

            try {
                words_count = std::stoi(argv[a + 1]);
                while (words_count % 3 != 0 || words_count < 3) {
                    words_count++;
                }
                entropy_len = (words_count / words_count_min) * entropy_count_min;

            }
            catch (const std::exception& e) {
                std::cerr << "[!] Error: Invalid value after '-w'. Setting to default value of 12." << std::endl;
                words_count = 1;
            }
            use_custom_size = true;
            Sizes.push_back(entropy_len);
            a++;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-lang") == 0) {
            string lang = argv[a + 1];
            if (lang == "EN") {
                language = 0;
            }
            else if (lang == "SA") {
                language = 1;
            }
            else if (lang == "JA") {
                language = 2;
            }
            else if (lang == "IT") {
                language = 3;
            }
            else if (lang == "FR") {
                language = 4;
            }
            else if (lang == "CZ") {
                language = 5;
            }
            else if (lang == "PT") {
                language = 6;
            }
            else if (lang == "KO") {
                language = 7;
            }
            else if (lang == "CS") {
                language = 8;
            }
            else if (lang == "CT") {
                language = 9;
            }
            else
            {
                language = 0;
            }



            a++;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-em") == 0) {
            Endomorphism = true;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-save") == 0) {
            save = true;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-silent") == 0) {
            setSilentMode();
            host_silent_mode = true;
            printf("[!] Silent mode activated! Do not print founds on the console, only in file! [!]\n");
            a++;
            continue;
        }
        if (strcmp(argv[a], "-delete") == 0) {
            deleteFile = true;
            a++;
            continue;
        }
        if (strcmp(argv[a], "-h") == 0 || strcmp(argv[a], "-help") == 0) {
            return false;
        }

        printUnknownParameterHint(argv[a], detect_help_topic(argc, argv));
        exit(1);
        a++;
    }
    IS_MINIKEYS_SEED = (IS_MINIKEYS && SEED);

    if (recovery_arg_seen) {
        if (mode_scoped_recovery_supported_after_parse()) {
            mode_scoped_recovery = true;
            RECOVERY_MODE = false;
            std::string recovery_err;
            if (!prepare_mode_scoped_recovery_templates(recovery_err)) {
                std::cerr << "[!] Error: " << recovery_err << " [!]" << std::endl;
                return false;
            }
            if (!apply_mode_scoped_recovery_template(mode_scoped_recovery_templates.front(), recovery_err)) {
                std::cerr << "[!] Error: " << recovery_err << " [!]" << std::endl;
                return false;
            }
        }
        else if (!IS_PRIV_RECOVERY) {
            RECOVERY_MODE = true;
            IS_ENTROPY = false;
            IS_PRIV = false;
            IS_MINIKEYS = false;
            SEED = false;
            HMAC = false;
            BIP32 = false;
            BRAIN = false;
            OLD = false;
            ARMORY = false;
            ARMORY_ROOT = false;
        }
    }

    const int wallet_mode_count =
        (KEYSTORE_MODE ? 1 : 0) +
        (WALLETDAT_MODE ? 1 : 0) +
        (WALLETJS_MODE ? 1 : 0) +
        (BROWSERVAULT_MODE ? 1 : 0) +
        (COPAYWALLET_MODE ? 1 : 0) +
        (TERRAWALLET_MODE ? 1 : 0) +
        (BITSHARESWALLET_MODE ? 1 : 0) +
        (YOROIWALLET_MODE ? 1 : 0) +
        (SUBSTRATEWALLET_MODE ? 1 : 0) +
        (BLOCKCHAINWALLET_MODE ? 1 : 0) +
        (MULTIBITWALLET_MODE ? 1 : 0) +
        (BIP38_MODE ? 1 : 0) +
        (ETHPRESALE_MODE ? 1 : 0) +
        (ANDROIDWALLET_MODE ? 1 : 0) +
        (SLIP39_MODE ? 1 : 0) +
        (AEZEED_MODE ? 1 : 0) +
        (ETH2VALIDATOR_MODE ? 1 : 0) +
        (BISQWALLET_MODE ? 1 : 0) +
        (DOGECHAINWALLET_MODE ? 1 : 0) +
        (STELLARWALLET_MODE ? 1 : 0) +
        (ELECTRUMWALLET_MODE ? 1 : 0) +
        (EXODUSSECO_MODE ? 1 : 0) +
        (BITCOINJWALLET_MODE ? 1 : 0) +
        (ARMORYWALLET_MODE ? 1 : 0) +
        (WALLETSCAN_MODE ? 1 : 0);
    if (wallet_mode_count > 1) {
        std::cerr << "[!] Error: choose only one wallet mode [!]" << std::endl;
        return false;
    }
    if (!prng64_gen && !WALLETJS_MODE && !XP_MODE) {
        if (start_seed_arg_seen && start_seed_arg64 > static_cast<uint64_t>(UINT32_MAX)) {
            std::cerr << "[!] Error: -s exceeds 32-bit seed range for this mode [!]" << std::endl;
            return false;
        }
        if (end_seed_arg_seen && end_seed_arg64 > static_cast<uint64_t>(UINT32_MAX)) {
            std::cerr << "[!] Error: -e exceeds 32-bit seed range for this mode [!]" << std::endl;
            return false;
        }
    }
    if (wallet_mode_count > 0) {
        if (PROFANITY_MODE || RECOVERY_MODE || IS_PRIV || IS_MINIKEYS || BRAIN || OLD || ARMORY || ARMORY_ROOT ||
            IS_ENTROPY || SEED || HMAC || BIP32 || prng_gen || prng64_gen || hexset_mode || mode_scoped_recovery) {
            std::cerr << "[!] Error: wallet modes are standalone main modes and cannot be mixed with existing brute modes [!]" << std::endl;
            return false;
        }
        if (target_arg_seen && !WALLETJS_MODE) {
            std::cerr << "[!] Error: -target/-hash is not used by password wallet artifact modes [!]" << std::endl;
            return false;
        }
        if ((is_wallet_artifact_password_mode() || WALLETSCAN_MODE || BIP38_MODE || ANDROIDWALLET_MODE) &&
            wallet_artifact_files.empty() && wallet_artifact_dirs.empty()) {
            std::cerr << "[!] Error: wallet mode requires artifact FILE or -f DIR [!]" << std::endl;
            return false;
        }
        if ((is_wallet_artifact_password_mode() || BIP38_MODE || ANDROIDWALLET_MODE) && !WALLET_LOAD_ONLY &&
            mnemonicFiles.empty() && wallet_masks.empty() && !seqMode) {
            std::cerr << "[!] Error: wallet mode requires candidates via -i FILE, -mask MASK, or -start/-end [!]" << std::endl;
            return false;
        }
        if (WALLETSCAN_MODE && (mnemonicFiles.size() != 0 || !wallet_masks.empty() || seqMode)) {
            std::cerr << "[!] Error: -walletscan is inventory-only and does not use password candidate flags [!]" << std::endl;
            return false;
        }
        if (!wallet_masks.empty() && seqMode) {
            std::cerr << "[!] Error: wallet modes use either -mask or -start/-end, not both [!]" << std::endl;
            return false;
        }
    }
    else if (wallet_mask_mode || !wallet_masks.empty()) {
        std::cerr << "[!] Error: -mask/-mask-file are currently valid only with wallet modes [!]" << std::endl;
        return false;
    }
    if (walletdat_max_raw_ckey_explicit && !WALLETDAT_MODE) {
        std::cerr << "[!] Error: -walletdat-max-ckey is valid only with -walletdat [!]" << std::endl;
        return false;
    }
    if (walletdat_kdf_work_explicit && !WALLETDAT_MODE) {
        std::cerr << "[!] Error: -walletdat-kdf-work is valid only with -walletdat [!]" << std::endl;
        return false;
    }
    if (walletdat_max_iterations_explicit && !WALLETDAT_MODE) {
        std::cerr << "[!] Error: -walletdat-max-iter is valid only with -walletdat [!]" << std::endl;
        return false;
    }
    if (walletdat_min_jobs_explicit && !WALLETDAT_MODE) {
        std::cerr << "[!] Error: -walletdat-min-jobs is valid only with -walletdat [!]" << std::endl;
        return false;
    }
    if (walletdat_staged_kdf_loop_explicit && !WALLETDAT_MODE) {
        std::cerr << "[!] Error: -walletdat-kdf-loop is valid only with -walletdat [!]" << std::endl;
        return false;
    }
    if (walletdat_scan_all && !WALLETDAT_MODE) {
        std::cerr << "[!] Error: -scan-all is valid only with -walletdat [!]" << std::endl;
        return false;
    }
    if (wallet_scrypt_scratch_budget_explicit &&
        !(is_browserlike_wallet_mode() || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE)) {
        std::cerr << "[!] Error: -wallet-scrypt-mem is valid only with scrypt wallet modes [!]" << std::endl;
        return false;
    }
    if (wallet_memory_explicit && !BIP38_MODE && !SUBSTRATEWALLET_MODE &&
        !COPAYWALLET_MODE && !TERRAWALLET_MODE &&
        !BITSHARESWALLET_MODE && !YOROIWALLET_MODE &&
        !MNEMONIC_SCRAMBLE_MODE) {
        std::cerr << "[!] Error: -wallet-mem is not enabled for this wallet mode yet; it is supported by -bip38, -copaywallet, -terrawallet, -bitshareswallet, -yoroiwallet, -substratewallet and -mnemonic -scramble [!]" << std::endl;
        return false;
    }
    if ((!mnemonic_scramble_pattern.empty() ||
         !mnemonic_scramble_pattern_file.empty()) &&
        !MNEMONIC_SCRAMBLE_MODE) {
        std::cerr << "[!] Error: -pattern/-pattern-file currently require -mnemonic -scramble [!]" << std::endl;
        return false;
    }
    if (MNEMONIC_SCRAMBLE_MODE) {
        if (RECOVERY_MODE || recovery_arg_seen || mode_scoped_recovery ||
            IS_PRIV || IS_MINIKEYS || BRAIN || OLD || ARMORY ||
            ARMORY_ROOT || IS_ENTROPY || SEED || HMAC || BIP32 ||
            POETRY_MODE || XP_MODE || prng_gen || prng64_gen ||
            hexset_mode || isRandom || backward || both ||
            pass_thread_mode || der_thread_mode) {
            std::cerr << "[!] Error: -mnemonic -scramble is a standalone mnemonic source and cannot be mixed with recovery, other source modes, PRNG/random, hexset, direction, pass_thread, or der_thread [!]" << std::endl;
            return false;
        }
        if (mnemonic_scramble_inline.empty() && mnemonicFiles.empty()) {
            std::cerr << "[!] Error: -mnemonic -scramble requires inline WORDS or -i FILE [!]" << std::endl;
            return false;
        }
    }
    if (WALLET_LOAD_ONLY && !(is_wallet_artifact_password_mode() || BIP38_MODE || ANDROIDWALLET_MODE)) {
        std::cerr << "[!] Error: -wallet-load-only is valid only with wallet artifact modes [!]" << std::endl;
        return false;
    }

    if (XP_MODE) {
        const int xp_milksad_bytes = xp_milksad_profile_bytes_from_arg(xp_profile_arg);
        if (xp_milksad_bytes > 0) {
            const bool xp_milksad_seq_offsets = xp_milksad_bx256_seq_offsets_from_arg(xp_profile_arg);
            if (PROFANITY_MODE || RECOVERY_MODE || KEYSTORE_MODE || WALLETDAT_MODE || WALLETJS_MODE ||
                is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE || WALLETSCAN_MODE ||
                IS_PRIV || IS_MINIKEYS || BRAIN || OLD || ARMORY || ARMORY_ROOT ||
                IS_ENTROPY || SEED || HMAC || BIP32 || prng_gen || prng64_gen || hexset_mode || mode_scoped_recovery ||
                wallet_mask_mode || !wallet_masks.empty()) {
                std::cerr << "[!] Error: -xp milksad is a standalone historical entropy profile and cannot be mixed with other brute modes [!]" << std::endl;
                return false;
            }
            XP_MODE = false;
            IS_ENTROPY = true;
            prng_gen = true;
            prng64_gen = false;
            Gens.assign(1, 89);
            PrngModes.assign(1, 11);
            PrngBytes.assign(1, xp_milksad_bytes);
            if (xp_milksad_seq_offsets && !prng_shift_arg_seen) {
                PrngSkip = { 0, 8, 16, 24, 32, 40, 48, 56, 64, 72, 80, 88, 96, 104, 112, 120, 128, 136, 144 };
            }
            gen_set = true;
            mode_set = true;
            if (!start_seed_arg_seen) {
                start_seed = 0u;
                start_seed64 = 0ull;
            }
            if (!end_seed_arg_seen) {
                end_seed = UINT32_MAX;
                end_seed64 = static_cast<uint64_t>(UINT32_MAX);
            }
            std::cerr << "[!] -xp " << xp_profile_arg
                << " -> Milk Sad bx seed profile: -entropy -prng -gen 89 -mode 11 -byte "
                << xp_milksad_bytes;
            if (xp_milksad_seq_offsets) {
                std::cerr << " -shift " << xp_join_ints(PrngSkip)
                    << (prng_shift_arg_seen ? " (user supplied)" : " (source offsets 0,32,...,576 PRNG rounds)");
            }
            std::cerr << " [!]" << std::endl;
        }
    }

    if (XP_MODE) {
        std::vector<int> xp_bip3x_mingw_bytes;
        if (xp_bip3x_mingw_profile_bytes_from_arg(xp_profile_arg, xp_bip3x_mingw_bytes)) {
            if (PROFANITY_MODE || RECOVERY_MODE || KEYSTORE_MODE || WALLETDAT_MODE || WALLETJS_MODE ||
                is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE || WALLETSCAN_MODE ||
                IS_PRIV || IS_MINIKEYS || BRAIN || OLD || ARMORY || ARMORY_ROOT ||
                IS_ENTROPY || SEED || HMAC || BIP32 || prng_gen || prng64_gen || hexset_mode || mode_scoped_recovery ||
                wallet_mask_mode || !wallet_masks.empty()) {
                std::cerr << "[!] Error: -xp bip3x-mingw is a standalone historical entropy profile and cannot be mixed with other brute modes [!]" << std::endl;
                return false;
            }
            XP_MODE = false;
            IS_ENTROPY = true;
            prng_gen = true;
            prng64_gen = false;
            Gens.assign(1, 89);
            PrngModes.assign(1, 11);
            PrngBytes = xp_bip3x_mingw_bytes;
            gen_set = true;
            mode_set = true;
            if (!start_seed_arg_seen) {
                start_seed = 0u;
                start_seed64 = 0ull;
            }
            if (!end_seed_arg_seen) {
                end_seed = UINT32_MAX;
                end_seed64 = static_cast<uint64_t>(UINT32_MAX);
            }
            std::cerr << "[!] -xp " << xp_profile_arg
                << " -> bip3x MinGW std::mt19937 profile: -entropy -prng -gen 89 -mode 11 -byte "
                << xp_join_ints(xp_bip3x_mingw_bytes) << " [!]" << std::endl;
        }
    }

    if (XP_MODE) {
        std::vector<int> xp_bx_ecnew_bytes;
        if (xp_milksad_bx_ecnew_profile_bytes_from_arg(xp_profile_arg, xp_bx_ecnew_bytes)) {
            if (PROFANITY_MODE || RECOVERY_MODE || KEYSTORE_MODE || WALLETDAT_MODE || WALLETJS_MODE ||
                is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE || WALLETSCAN_MODE ||
                IS_PRIV || IS_MINIKEYS || BRAIN || OLD || ARMORY || ARMORY_ROOT ||
                IS_ENTROPY || SEED || HMAC || BIP32 || prng_gen || prng64_gen || hexset_mode || mode_scoped_recovery ||
                wallet_mask_mode || !wallet_masks.empty()) {
                std::cerr << "[!] Error: -xp milksad-bx-ecnew is a standalone historical BIP32 profile and cannot be mixed with other brute modes [!]" << std::endl;
