                std::cerr << "[!] Error: -xp randstorm-v8init requires bounded -s HEX and -e HEX seed range [!]" << std::endl;
                return false;
            }
            if (end_seed64 < start_seed64) {
                std::cerr << "[!] Error: -xp randstorm-v8init requires -e >= -s [!]" << std::endl;
                return false;
            }
            const bool explicit_time_range = walletjs_time_start_seen || walletjs_time_end_seen;
            if (explicit_time_range && (!walletjs_time_start_seen || !walletjs_time_end_seen)) {
                std::cerr << "[!] Error: -xp randstorm-v8init requires both -time-s HEX and -time-e HEX when either is specified [!]" << std::endl;
                return false;
            }
            if (explicit_time_range && walletjs_time_end < walletjs_time_start) {
                std::cerr << "[!] Error: -xp randstorm-v8init requires -time-e >= -time-s [!]" << std::endl;
                return false;
            }
            if (xp_randstorm_time_mode == 1u && explicit_time_range && walletjs_time_end > 999u) {
                std::cerr << "[!] Error: -xp randstorm-v8init -time-mode seed-sec-ms treats -time-s/-time-e as millisecond offsets 0..0x3e7 [!]" << std::endl;
                return false;
            }
            const uint64_t state_count = end_seed64 - start_seed64 + 1ull;
            const uint64_t time_count = explicit_time_range
                ? (static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull)
                : 1ull;
            const uint64_t delta_count = static_cast<uint64_t>(walletjs_time_delta_max) + 1ull;
            const uint64_t mileage_count = xp_randstorm_mileage_count_host();
            if (explicit_time_range && time_count > static_cast<uint64_t>(UINT32_MAX)) {
                std::cerr << "[!] Error: -xp randstorm-v8init time range is too large for one pass; split -time-s/-time-e into smaller windows [!]" << std::endl;
                return false;
            }
            uint64_t state_time = 0ull;
            uint64_t state_time_delta = 0ull;
            uint64_t state_time_delta_keys = 0ull;
            uint64_t state_time_delta_keys_mileage = 0ull;
            uint64_t total = 0ull;
            if (!mul_u64_checked(state_count, time_count, state_time) ||
                !mul_u64_checked(state_time, delta_count, state_time_delta) ||
                !mul_u64_checked(state_time_delta, static_cast<uint64_t>(n_number), state_time_delta_keys) ||
                !mul_u64_checked(state_time_delta_keys, mileage_count, state_time_delta_keys_mileage) ||
                !mul_u64_checked(state_time_delta_keys_mileage, static_cast<uint64_t>(xp_path_count), total)) {
                std::cerr << "[!] Error: -xp randstorm-v8init scan range overflows uint64 [!]" << std::endl;
                return false;
            }
            if (total == 0ull) {
                std::cerr << "[!] Error: -xp randstorm-v8init empty scan range [!]" << std::endl;
                return false;
            }
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32) {
            if (xp_path_count == 0u || xp_path_mask == 0u) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 selected no engines/profiles [!]" << std::endl;
                return false;
            }
            if (n_number > (static_cast<uint64_t>(UINT32_MAX) / 33ull)) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 -n is too large for sequential JSBN stream offsets [!]" << std::endl;
                return false;
            }
            if (!start_seed_arg_seen || !end_seed_arg_seen) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 requires bounded -s HEX and -e HEX state0 range [!]" << std::endl;
                return false;
            }
            if (end_seed64 < start_seed64) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 requires -e >= -s [!]" << std::endl;
                return false;
            }
            if (end_seed64 > 0xffffffffull) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 -e must fit 32-bit state0 [!]" << std::endl;
                return false;
            }
            const bool explicit_time_range = walletjs_time_start_seen || walletjs_time_end_seen;
            if (explicit_time_range && (!walletjs_time_start_seen || !walletjs_time_end_seen)) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 requires both -time-s HEX and -time-e HEX when either is specified [!]" << std::endl;
                return false;
            }
            if (explicit_time_range && walletjs_time_end < walletjs_time_start) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 requires -time-e >= -time-s [!]" << std::endl;
                return false;
            }
            if (xp_randstorm_time_mode == 1u && explicit_time_range && walletjs_time_end > 999u) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 -time-mode seed-sec-ms treats -time-s/-time-e as millisecond offsets 0..0x3e7 [!]" << std::endl;
                return false;
            }
            const uint64_t state_count = end_seed64 - start_seed64 + 1ull;
            const uint64_t time_count = explicit_time_range
                ? (static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull)
                : 1ull;
            const uint64_t delta_count = static_cast<uint64_t>(walletjs_time_delta_max) + 1ull;
            const uint64_t mileage_count = xp_randstorm_mileage_count_host();
            if (explicit_time_range && time_count > static_cast<uint64_t>(UINT32_MAX)) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 time range is too large for one pass; split -time-s/-time-e into smaller windows [!]" << std::endl;
                return false;
            }
            uint64_t state_time = 0ull;
            uint64_t state_time_delta = 0ull;
            uint64_t state_time_delta_keys = 0ull;
            uint64_t state_time_delta_keys_mileage = 0ull;
            uint64_t total = 0ull;
            if (!mul_u64_checked(state_count, time_count, state_time) ||
                !mul_u64_checked(state_time, delta_count, state_time_delta) ||
                !mul_u64_checked(state_time_delta, static_cast<uint64_t>(n_number), state_time_delta_keys) ||
                !mul_u64_checked(state_time_delta_keys, mileage_count, state_time_delta_keys_mileage) ||
                !mul_u64_checked(state_time_delta_keys_mileage, static_cast<uint64_t>(xp_path_count), total)) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 scan range overflows uint64 [!]" << std::endl;
                return false;
            }
            if (total == 0ull) {
                std::cerr << "[!] Error: -xp randstorm-mwc32 empty scan range [!]" << std::endl;
                return false;
            }
        }
        else if (xp_profile_kind == XP_PROFILE_CGR_STATE || xp_profile_kind == XP_PROFILE_CGR_BRIDGE ||
            xp_profile_kind == XP_PROFILE_CGR_XOR || xp_profile_kind == XP_PROFILE_CGR_CHAIN ||
            xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE || xp_profile_kind == XP_PROFILE_RAW32 ||
            xp_profile_kind == XP_PROFILE_SSLEAY_STIR) {
            if (xp_randstorm_seed_events != 0u) {
                std::cerr << "[!] Error: -time-events/-time-events-repeat/-screen-seed/-screen-seed-zero is only valid with -xp randstorm JSBN profiles [!]" << std::endl;
                return false;
            }
            if (xp_randstorm_time_mode != 0u) {
                std::cerr << "[!] Error: -time-mode is only valid with -xp randstorm JSBN profiles [!]" << std::endl;
                return false;
            }
            if (mnemonicFiles.empty() && xp_artifact_dirs.empty()) {
                std::cerr << "[!] Error: -xp cgr-state/cgr-bridge/cgr-xor/cgr-chain/cgr-chain-bridge/ssleay-stir/raw32 requires -i FILE"
                    << " or -f DIR [!]" << std::endl;
                return false;
            }
        }
        if (isRandom) {
            std::cerr << "[!] Error: -xp does not use -random in v1 [!]" << std::endl;
            return false;
        }
    }
    else {
        if (xp_once) {
            std::cerr << "[!] Error: -once is only valid with -xp [!]" << std::endl;
            return false;
        }
        if (xp_path_override_explicit) {
            std::cerr << "[!] Error: -v is only valid with -xp OpenSSL profiles [!]" << std::endl;
            return false;
        }
        if (xp_randstorm_seed_events != 0u) {
            std::cerr << "[!] Error: -time-events/-time-events-repeat/-screen-seed/-screen-seed-zero is only valid with -xp randstorm JSBN profiles [!]" << std::endl;
            return false;
        }
        if (xp_randstorm_time_mode != 0u) {
            std::cerr << "[!] Error: -time-mode is only valid with -xp randstorm JSBN profiles [!]" << std::endl;
            return false;
        }
        if (xp_randstorm_mileage_arg_seen()) {
            std::cerr << "[!] Error: -mileage is only valid with -xp randstorm profiles [!]" << std::endl;
            return false;
        }
    }

    if (PROFANITY_MODE && RECOVERY_MODE) {
        profanity_recovery_file_mode = false;
        profanity_recovery_file_path.clear();
        for (const auto& entry : recoveryQueue) {
            if (entry.type == RecoveryQueueEntryType::File) {
                if (!profanity_recovery_file_path.empty()) {
                    std::cerr << "[!] Error: -profanity -recovery accepts only one -i FILE [!]" << std::endl;
                    return false;
                }
                profanity_recovery_file_path = entry.value;
            }
        }
        if (profanity_recovery_file_path.empty() && !mnemonicFiles.empty()) {
            if (mnemonicFiles.size() > 1u) {
                std::cerr << "[!] Error: -profanity -recovery accepts only one -i FILE [!]" << std::endl;
                return false;
            }
            profanity_recovery_file_path = mnemonicFiles.front();
        }
        if (!profanity_recovery_file_path.empty()) {
            profanity_recovery_file_mode = true;
            recoveryQueue.clear();
            mnemonicFiles.clear();
        }
    }

    if (target_arg_seen) {
        if (PROFANITY_MODE && RECOVERY_MODE) {
            if (profanity_recovery_file_mode) {
                std::cerr << "[!] Error: -profanity -recovery uses either -target/-hash or -i FILE, not both [!]" << std::endl;
                return false;
            }
            profanity_target_hex = target_arg_value;
        }
        else {
            uint32_t words[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };
            uint32_t masks[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };
            uint32_t len_bytes = 0;
            std::string normalized;
            std::string err;
            if (!parse_hash_target_argument(target_arg_value.c_str(), words, masks, len_bytes, normalized, err)) {
                std::cerr << "[!] Error: invalid " << target_arg_name << " value: " << err << " [!]" << std::endl;
                return false;
            }

            memcpy(hashTargetWordsHost, words, sizeof(hashTargetWordsHost));
            memcpy(hashTargetMasksHost, masks, sizeof(hashTargetMasksHost));
            hashTargetLenBytes = len_bytes;
            hashTargetHex = normalized;
            useHashTarget = true;

            std::cerr << "[!] Hash prefix matching enabled: " << hashTargetLenBytes
                << " byte(s), hex=" << hashTargetHex << " [!]" << std::endl;
        }
    }

    if (PROFANITY_MODE && RECOVERY_MODE && use_n_count && !profanity_recovery_file_mode) {
        std::cerr << "[!] Error: -profanity -recovery does not use -n; use -offset HEX for restart [!]" << std::endl;
        return false;
    }
    if (profanity_gpu_split_explicit && !PROFANITY_MODE) {
        std::cerr << "[!] Error: -gpu-split is only valid with direct -profanity [!]" << std::endl;
        return false;
    }
    if (PROFANITY_MODE && RECOVERY_MODE && profanity_gpu_split_explicit) {
        std::cerr << "[!] Error: -gpu-split is only valid with direct -profanity; recovery has its own partition logic [!]" << std::endl;
        return false;
    }
    if (profanity_random_seeds_explicit && (!PROFANITY_MODE || RECOVERY_MODE)) {
        std::cerr << "[!] Error: -random-seeds is only valid with direct -profanity -random [!]" << std::endl;
        return false;
    }
    if (profanity_random_seeds_explicit && !isRandom) {
        std::cerr << "[!] Error: -random-seeds requires -random [!]" << std::endl;
        return false;
    }
    if (PROFANITY_MODE && RECOVERY_MODE && isRandom) {
        std::cerr << "[!] Error: -profanity -recovery does not use -random [!]" << std::endl;
        return false;
    }
    if (PROFANITY_MODE && RECOVERY_MODE && profanity_recovery_file_mode) {
        if (!use_n_count) {
            n_number = 1ull << 14;
            use_n_count = true;
        }
        if (n_number == 0ull) {
            std::cerr << "[!] Error: -profanity -recovery -i FILE requires -n > 0 [!]" << std::endl;
            return false;
        }
    }

    if (mode_scoped_recovery) {
        if (!hexset_mode) {
            std::cerr << "[!] Error: mode-scoped -recovery TEMPLATE requires -hexset HEXDIGITS [!]" << std::endl;
            return false;
        }
        if (mode_scoped_recovery_templates.empty() || recovery_hex_template_nibbles.empty()) {
            std::cerr << "[!] Error: mode-scoped -recovery template queue is empty [!]" << std::endl;
            return false;
        }
        if (IS_PRIV || IS_MINIKEYS || IS_PRIV_RECOVERY ||
            IS_PRIV_SWAP || IS_PRIV_BYTE || IS_PRIV_HASH || IS_PRIV_PLUS || IS_PRIV_PLUS_256 || IS_PRIV_PATTERN) {
            std::cerr << "[!] Error: mode-scoped -recovery is not supported in -priv/-minikeys/submode paths [!]" << std::endl;
            return false;
        }
        if (backward || both || isRandom || use_n_count ||
            step != 1ull ||
            prng_gen || prng64_gen || seq_priv_use_step_schedule || seq_priv_has_end_step ||
            seq_priv_has_add_plus_step || pass_thread_mode || der_thread_mode || seqMode || end_point_set) {
            std::cerr << "[!] Error: mode-scoped -recovery + -hexset is forward-only and cannot be combined with "
                << "-start/-end/-step/-endstep/-plusstep/-addplusstep/-back/-both/-random/-n/"
                << "-prng/-prng64/-pass_thread/-der_thread [!]" << std::endl;
            return false;
        }
        if (use_custom_size) {
            std::cerr << "[!] Error: mode-scoped -recovery fixes candidate length from TEMPLATE; do not use -size/-sizes [!]" << std::endl;
            return false;
        }
    }

    if (hexset_mode) {
        int min_size = 0;
        int max_size = 0;
        if (!mode_scoped_recovery && !hexset_size_config_for_current_mode(min_size, max_size)) {
            const char* mode_label = hexset_mode_label();
            std::cerr << "[!] Error: -hexset is not supported in this mode";
            if (mode_label != nullptr) {
                std::cerr << " (" << mode_label << ")";
            }
            std::cerr << " [!]" << std::endl;
            return false;
        }
        if (!mode_scoped_recovery && (IS_MINIKEYS || RECOVERY_MODE || ARMORY || ARMORY_ROOT || IS_PRIV_RECOVERY ||
            IS_PRIV_SWAP || IS_PRIV_BYTE || IS_PRIV_HASH || IS_PRIV_PLUS || IS_PRIV_PLUS_256 || IS_PRIV_PATTERN)) {
            const char* mode_label = hexset_mode_label();
            std::cerr << "[!] Error: -hexset is not supported in this mode";
            if (mode_label != nullptr) {
                std::cerr << " (" << mode_label << ")";
            }
            std::cerr << " [!]" << std::endl;
            return false;
        }
        if (!mode_scoped_recovery && (backward || both || isRandom || use_n_count ||
            step != 1ull ||
            prng_gen || prng64_gen || seq_priv_use_step_schedule || seq_priv_has_end_step ||
            seq_priv_has_add_plus_step || pass_thread_mode || der_thread_mode)) {
            std::cerr << "[!] Error: -hexset is forward-only and cannot be combined with "
                << "-step/-endstep/-plusstep/-addplusstep/-back/-both/-random/-n/"
                << "-prng/-prng64/-pass_thread/-der_thread [!]" << std::endl;
            return false;
        }
        if (!mode_scoped_recovery && use_custom_size) {
            std::cerr << "[!] Error: -hexset no longer supports -size/-sizes. Use -start HEX [-end HEX] [!]" << std::endl;
            return false;
        }
        if (!mode_scoped_recovery && !seqMode) {
            std::cerr << "[!] Error: -hexset requires -start HEX [!]" << std::endl;
            return false;
        }
        if (!mode_scoped_recovery && end_point_set && start_point.empty()) {
            std::cerr << "[!] Error: -hexset does not support -end without -start [!]" << std::endl;
            return false;
        }

        if (mode_scoped_recovery) {
            size_t recovery_max = 0u;
            if (!recovery_hexset_max_bytes_for_current_mode(recovery_max)) {
                std::cerr << "[!] Error: mode-scoped -recovery is not supported in this mode [!]" << std::endl;
                return false;
            }
            if ((recovery_hex_template_nibbles.size() / 2u) > recovery_max) {
                std::cerr << "[!] Error: mode-scoped -recovery template exceeds mode max size [!]" << std::endl;
                return false;
            }
            goto hexset_validation_done;
        }

        std::string hexset_bound_err;
        if (!parse_hexset_bound_hex(start_point, static_cast<size_t>(max_size), hexset_start_bound_norm, hexset_start_bound_nibbles, hexset_bound_err)) {
            std::cerr << "[!] Error: invalid -hexset -start: " << hexset_bound_err << " [!]" << std::endl;
            return false;
        }
        start_point = hexset_start_bound_norm;

        if (end_point_set) {
            if (!parse_hexset_bound_hex(end_point, static_cast<size_t>(max_size), hexset_end_bound_norm, hexset_end_bound_nibbles, hexset_bound_err)) {
                std::cerr << "[!] Error: invalid -hexset -end: " << hexset_bound_err << " [!]" << std::endl;
                return false;
            }
            end_point = hexset_end_bound_norm;
            const size_t start_len = hexset_start_bound_nibbles.size();
            const size_t end_len = hexset_end_bound_nibbles.size();
            if (end_len < start_len) {
                std::cerr << "[!] Error: -hexset -end length cannot be smaller than -start length [!]" << std::endl;
                return false;
            }
            if (end_len == start_len && hexset_start_bound_norm > hexset_end_bound_norm) {
                std::cerr << "[!] Error: -hexset start must be <= end when both bounds have the same length [!]" << std::endl;
                return false;
            }
        }
        else {
            hexset_end_bound_norm.clear();
            hexset_end_bound_nibbles.clear();
        }
    }
hexset_validation_done:

    if (IS_PRIV && IS_PRIV_PATTERN) {
        if (prng_gen || prng64_gen || seqMode || isRandom) {
            std::cerr << "[!] Error: -priv 6 cannot be combined with -prng/-prng64/-start/-end/-step/-random [!]" << std::endl;
            return false;
        }
        if (!priv_pattern_arg_seen) {
            std::cerr << "[!] Error: -priv 6 requires -pb list/range (example: -pb 1,2,3-6) [!]" << std::endl;
            return false;
        }
        if (!parse_priv_pattern_lengths(priv_pattern_raw_arg, priv_pattern_lengths)) {
            std::cerr << "[!] Error: invalid -pb for -priv 6. Use list/ranges, e.g. 1,2,3-6 (1..64) [!]" << std::endl;
            return false;
        }
        priv_pattern_range_set = true;
        std::cerr << "[!] -priv 6 pattern lengths spec: " << priv_pattern_raw_arg << " [!]" << std::endl;
        if (priv_pattern_last_cycle) {
            std::cerr << "[!] -priv 6: -last enabled (cycle last hex symbol for each key) [!]" << std::endl;
        }
    }
    else {
        priv_pattern_range_set = false;
        priv_pattern_lengths.clear();
        if (priv_pattern_last_cycle) {
            std::cerr << "[!] Warning: -last works only with -priv 6 and will be ignored [!]" << std::endl;
            priv_pattern_last_cycle = false;
        }
    }

    {
        std::string priv_recovery_err;
        if (!priv_recovery_validate_cli(priv_recovery_err)) {
            std::cerr << "[!] Error: " << priv_recovery_err << " [!]" << std::endl;
            return false;
        }
    }

    // -priv -random enables endomorphism (-em) by default
    if (IS_PRIV && isRandom) {
        Endomorphism = true;
    }
    if (IS_MINIKEYS && !IS_MINIKEYS_SEED && (prng_gen || prng64_gen)) {
        std::cerr << "[!] Error: -minikeys cannot be combined with -prng/-prng64 [!]" << std::endl;
        return false;
    }
    if (IS_MINIKEYS && !IS_MINIKEYS_SEED && IS_HEX) {
        std::cerr << "[!] Warning: -hex is ignored in -minikeys mode [!]" << std::endl;
        IS_HEX = false;
    }
    if (!validate_crypted_cli_selection()) {
        return false;
    }
    return true;
}

// parse_derivation_components_fast: parses derivation components fast.
static inline bool parse_derivation_components_fast(const std::string& path, uint32_t& parsed_count) {
    parsed_count = 0;
    size_t start = 0;
    while (start < path.size()) {
        const size_t slash = path.find('/', start);
        size_t end = (slash == std::string::npos) ? path.size() : slash;

        if (end > start) {
            bool hardened = false;
            if (path[end - 1] == '\'') {
                hardened = true;
                --end;
            }
            if (end <= start) {
                return false;
            }

            uint64_t value = 0;
            for (size_t i = start; i < end; ++i) {
                const char c = path[i];
                if (c < '0' || c > '9') {
                    return false;
                }
                value = (value * 10ull) + (uint64_t)(c - '0');
                if (value > UINT32_MAX) {
                    return false;
                }
            }

            uint32_t v32 = (uint32_t)value;
            if (hardened) {
                v32 |= 0x80000000u;
            }
            Derivations.emplace_back(v32);
            ++parsed_count;
        }

        if (slash == std::string::npos) {
            break;
        }
        start = slash + 1;
    }
    return parsed_count > 0;
}

static void sort_derivations_by_path();

// parseDerivations: parses derivations.
bool parseDerivations(const vector<string>& file) {
    for (size_t i = 0; i < file.size(); ++i) {
        std::ifstream stream(file[i].c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cerr << "[!] Failed to open derivations file: " << file[i] << " [!]" << std::endl;
            continue;
        }

        std::string buffer;
        while (read_trimmed_line(stream, buffer, 512)) {
            try {
                if (buffer.empty()) {
                    continue;
                }

                if ((buffer == "m") || (buffer == "m/")) {
                    derIndex.emplace_back(0);
                    derIndex_size++;
                    Derivations_list.push_back("m/");
                    continue;
                }

                if (buffer.size() >= 2 && buffer[0] == 'm' && buffer[1] == '/') {
                    buffer.erase(0, 2);
                }
                if (buffer.empty()) {
                    derIndex.emplace_back(0);
                    derIndex_size++;
                    Derivations_list.push_back("m/");
                    continue;
                }

                uint64_t last_value = 0;
                bool last_hardened = false;
                bool can_increment_last = false;
                std::string prefix;
                {
                    const size_t pos = buffer.find_last_of('/');
                    const size_t start = (pos == std::string::npos) ? 0 : pos + 1;
                    std::string last = buffer.substr(start);
                    if (!last.empty() && last.back() == '\'') {
                        last_hardened = true;
                        last.pop_back();
                    }
                    if (!last.empty()) {
                        can_increment_last = true;
                        for (char c : last) {
                            if (c < '0' || c > '9') {
                                can_increment_last = false;
                                break;
                            }
                            last_value = (last_value * 10ull) + (uint64_t)(c - '0');
                            if (last_value > UINT32_MAX) {
                                can_increment_last = false;
                                break;
                            }
                        }
                    }
                    prefix = (pos == std::string::npos) ? "" : buffer.substr(0, pos + 1);
                }

                for (uint32_t step = 0; step <= deep; ++step) {
                    std::string buf2 = buffer;
                    if (step && can_increment_last) {
                        const uint64_t next = last_value + (uint64_t)step;
                        if (next > UINT32_MAX) {
                            break;
                        }
                        buf2 = prefix + std::to_string(next) + (last_hardened ? "'" : "");
                    }

                    uint32_t parsed_count = 0;
                    if (!parse_derivation_components_fast(buf2, parsed_count)) {
                        throw std::runtime_error("invalid derivation");
                    }

                    derIndex.emplace_back(parsed_count);
                    derIndex_size++;
                    Derivations_list.push_back("m/" + buf2);
                }
            }
            catch (const std::exception&) {
                std::cerr << "[!] Wrong derivation: " << buffer << " skipped [!]" << std::endl;
                continue;
            }
        }
    }

    if (Derivations_list.empty()) return false;
    /* Keep ADA paths in user/file order because Shelley Base pair generation uses
     * ordered adjacent paths. Legacy/non-ADA modes keep sorted paths for cache hits. */
    if (!Ada) {
        sort_derivations_by_path();
    }
    return true;
}

/* Reorder Derivations, derIndex, Derivations_list so paths are sorted lexicographically.
 * Improves derivation cache hit rate when many paths share prefixes (e.g. m/44'/0'/0'/0/0..N). */
static void sort_derivations_by_path() {
    const size_t n = derIndex.size();
    if (n <= 1u) return;

    std::vector<size_t> offsets(n + 1, 0);
    for (size_t i = 0; i < n; i++)
        offsets[i + 1] = offsets[i] + derIndex[i];

    std::vector<size_t> perm(n);
    for (size_t i = 0; i < n; i++) perm[i] = i;

    auto path_less = [&](size_t a, size_t b) {
        const uint32_t* pa = Derivations.data() + offsets[a];
        const uint32_t* pb = Derivations.data() + offsets[b];
        const size_t la = derIndex[a], lb = derIndex[b];
        const size_t l = (la < lb) ? la : lb;
        for (size_t i = 0; i < l; i++) {
            if (pa[i] != pb[i]) return pa[i] < pb[i];
        }
        return la < lb;
    };
    std::sort(perm.begin(), perm.end(), path_less);

    std::vector<uint32_t> newDerivations;
    std::vector<uint32_t> newDerIndex;
    std::vector<std::string> newDerivations_list;
    newDerivations.reserve(Derivations.size());
    newDerIndex.reserve(n);
    newDerivations_list.reserve(n);

    for (size_t i = 0; i < n; i++) {
        const size_t idx = perm[i];
        const size_t off = offsets[idx], len = derIndex[idx];
        newDerIndex.push_back(static_cast<uint32_t>(len));
        newDerivations_list.push_back(Derivations_list[idx]);
        for (size_t j = 0; j < len; j++)
            newDerivations.push_back(Derivations[off + j]);
    }
    Derivations = std::move(newDerivations);
    derIndex = std::move(newDerIndex);
    Derivations_list = std::move(newDerivations_list);
}

// readHex: reads hex.
void readHex(char* buf, const char* txt) {
    char b[3] = "00";
    for (unsigned int i = 0; i < strlen(txt); i += 2) {
        b[0] = *(txt + i);
        b[1] = *(txt + i + 1);
        *(buf + (i >> 1)) = strtoul(b, NULL, 16);
    }
}

char* __strlwr(char* str)
{
    unsigned char* p = (unsigned char*)str;

    while (*p) {
        *p = tolower((unsigned char)*p);
        p++;
    }

    return str;
}

// checkDevice: checks whether device is valid.
bool checkDevice() {
    metalError_t metalStatus = metalSetDevice(DEVICE_NR);
    if (metalStatus != metalSuccess) {
        init_log_fprintf(stderr, "[!] device %d failed! [!]", DEVICE_NR);
        return false;
    }
    else {
        metalDeviceProp props;
        metalStatus = metalGetDeviceProperties(&props, DEVICE_NR);
        init_log_fprintf(stderr, "[!] Using device: %d\n", DEVICE_NR);

        if (BLOCK_THREADS == 0) {
            BLOCK_THREADS = props.maxThreadsPerBlock / 8 * 2;
        }
        if ((EXODUSSECO_MODE || BITCOINJWALLET_MODE) && !set_thread) {
            BLOCK_THREADS = 4u;
        }
        if (ARMORYWALLET_MODE && !set_thread) {
            BLOCK_THREADS = 8u;
        }
        if (SEED && !set_thread && (!mnemonicFiles.empty() || useDirectory) &&
            has_secp_output_targets() && !has_ed_output_targets()) {
            BLOCK_THREADS = 64u;
        }
        if (PROFANITY_MODE && BLOCK_THREADS != 256u) {
            BLOCK_THREADS = 256u;
        }
        if (BLOCK_NUMBER == 0) {
            unsigned int blocksPerSm = 8;
            const size_t derivCount = Derivations_list.empty() ? 1u : Derivations_list.size();
            const char* tuneProfile = "default";
            const bool isFileInputMode = !mnemonicFiles.empty() || useDirectory;
            const bool isPrngInputMode = prng_gen || prng64_gen;
            const bool isSeqInputMode = seqMode;
            const bool isRandomInputMode = isRandom;
            const bool isGeneratedInputMode = isPrngInputMode || isSeqInputMode || isRandomInputMode;
            if (XP_MODE) {
                const bool c = Compressed;
                const bool u = Uncompressed;
                const bool s = Segwit;
                const bool p = P2wsh;
                const bool r = Taproot;
                const bool x = Xpoint;
                const bool e = Ethereum;
                if (c && !u && !s && !p && !r && !x && !e) {
                    blocksPerSm = 128;
                    tuneProfile = "xp_c";
                }
                else if (!c && u && !s && !p && !r && !x && !e) {
                    blocksPerSm = 128;
                    tuneProfile = "xp_u";
                }
                else if (!c && !u && s && !p && !r && !x && !e) {
                    blocksPerSm = 32;
                    tuneProfile = "xp_s";
                }
                else if (!c && !u && !s && !p && r && !x && !e) {
                    blocksPerSm = 32;
                    tuneProfile = "xp_r";
                }
                else if (!c && !u && !s && !p && !r && x && !e) {
                    blocksPerSm = 128;
                    tuneProfile = "xp_x";
                }
                else if (!c && !u && !s && !p && !r && !x && e) {
                    blocksPerSm = 128;
                    tuneProfile = "xp_e";
                }
                else if (c && u && s && !p && r && x && e) {
                    blocksPerSm = 32;
                    tuneProfile = "xp_cusrxe";
                }
                else {
                    blocksPerSm = 32;
                    tuneProfile = "xp_common";
                }
            }
            else if (PROFANITY_MODE) {
                if (RECOVERY_MODE) {
                    const unsigned int profanityRecoveryBlocksPerSm = 128u;
                    const bool onlyXc = useXor && !useXorUn && !useXorUc && !useXorHc;
                    const bool onlyXu = useXorUn && !useXor && !useXorUc && !useXorHc;
                    const bool onlyXuc = useXorUc && !useXor && !useXorUn && !useXorHc;
                    const bool onlyXh = useXorHc && !useXor && !useXorUn && !useXorUc;
                    if (onlyXc) {
                        blocksPerSm = profanityRecoveryBlocksPerSm;
                        tuneProfile = "profanity_recovery_xc";
                    }
                    else if (onlyXuc) {
                        blocksPerSm = profanityRecoveryBlocksPerSm;
                        tuneProfile = "profanity_recovery_xuc";
                    }
                    else if (onlyXh) {
                        blocksPerSm = profanityRecoveryBlocksPerSm;
                        tuneProfile = "profanity_recovery_xh";
                    }
                    else if (onlyXu) {
                        blocksPerSm = profanityRecoveryBlocksPerSm;
                        tuneProfile = "profanity_recovery_xu";
                    }
                    else {
                        blocksPerSm = profanityRecoveryBlocksPerSm;
                        tuneProfile = "profanity_recovery_mixed";
                    }
                }
                else {
                    const bool c = Compressed;
                    const bool u = Uncompressed;
                    const bool s = Segwit;
                    const bool p = P2wsh;
                    const bool r = Taproot;
                    const bool x = Xpoint;
                    const bool e = Ethereum;
                    if (c && !u && !s && !p && !r && !x && !e) {
                        blocksPerSm = 16;
                        tuneProfile = "profanity_search_c";
                    }
                    else if (!c && u && !s && !p && !r && !x && !e) {
                        blocksPerSm = 16;
                        tuneProfile = "profanity_search_u";
                    }
                    else if (!c && !u && s && !p && !r && !x && !e) {
                        blocksPerSm = 16;
                        tuneProfile = "profanity_search_s";
                    }
                    else if (!c && !u && !s && !p && r && !x && !e) {
                        blocksPerSm = 16;
                        tuneProfile = "profanity_search_r";
                    }
                    else if (!c && !u && !s && !p && !r && x && !e) {
                        blocksPerSm = 16;
                        tuneProfile = "profanity_search_x";
                    }
                    else if (!c && !u && !s && !p && !r && !x && e) {
                        blocksPerSm = 16;
                        tuneProfile = "profanity_search_e";
                    }
                    else if (c && u && !s && !p && !r && !x && !e) {
                        blocksPerSm = 32;
                        tuneProfile = "profanity_search_cu";
                    }
                    else if (c && u && s && !p && r && !x && !e) {
                        blocksPerSm = 32;
                        tuneProfile = "profanity_search_cusr";
                    }
                    else if (c && u && s && !p && r && x && e) {
                        blocksPerSm = 32;
                        tuneProfile = "profanity_search_cusrxe";
                    }
                    else {
                        blocksPerSm = 32;
                        tuneProfile = "profanity_search_mixed";
                    }
                }
            }
            else if (POETRY_MODE) {
                // The shorter lazy kernel benefits from larger batches on M4 Max; M3 Max regresses above 8.
                blocksPerSm = std::strstr(props.name, "Apple M4 Max") != nullptr ? 16u : 8u;
                tuneProfile = isRandomInputMode ? "poetry_random" : "poetry_finite";
            }
            else if (IS_PRIV || (IS_MINIKEYS && !IS_MINIKEYS_SEED)) {
                if ((isSeqInputMode || (IS_MINIKEYS && !IS_MINIKEYS_SEED)) && !isRandomInputMode && !isPrngInputMode && !isFileInputMode) {
                    const bool onlyBloom = useBloom && !useXor && !useXorUn && !useXorUc && !useXorHc;
                    const bool onlyXorUn = useXorUn && !useBloom && !useXor && !useXorUc && !useXorHc;
                    if (onlyXorUn) {
                        const uint64_t xuBytes = sum_existing_file_sizes(xorFilesUn);
                        if (xuBytes >= (8ull << 30)) {
                            // Large XOR_UN sets are DRAM-limited; fewer resident blocks reduce L2/TLB thrash.
                            blocksPerSm = 16;
                        }
                        else if (xuBytes >= (2ull << 30)) {
                            blocksPerSm = 24;
                        }
                        else if (xuBytes >= (512ull << 20)) {
                            blocksPerSm = 48;
                        }
                        else if (xuBytes >= (128ull << 20)) {
                            blocksPerSm = 96;
                        }
                        else {
                            // Tiny XOR_UN sets fit cache well; high occupancy hides filter latency better.
                            blocksPerSm = 256;
                        }
                        tuneProfile = "priv_seq_xu";
                    }
                    else if (onlyBloom) {
                        // Bloom-only (single large bitset) scales with occupancy in vanity seq kernels.
                        blocksPerSm = 256;
                        tuneProfile = "priv_seq_bf";
                    }
                    else if (useBloom && useXorUn) {
                        blocksPerSm = 64;
                        tuneProfile = "priv_seq_bf_xu";
                    }
                    else {
                        blocksPerSm = 72;
                        tuneProfile = "priv_seq";
                    }
                }
                else if (isRandomInputMode) {
                    blocksPerSm = 40;
                    tuneProfile = "priv_random";
                }
                else if (isPrngInputMode) {
                    blocksPerSm = 24;
                    tuneProfile = "priv_prng";
                }
                else if (isFileInputMode) {
                    const bool compressedOnly = Compressed && !Endomorphism &&
                        active_target_count_for_stats() == 1;
                    blocksPerSm = compressedOnly ? 2u : 4u;
                    tuneProfile = compressedOnly ? "priv_file_c" : "priv_file";
                }
                else {
                    blocksPerSm = 4;
                    tuneProfile = "priv_stream";
                }
            }
            else if (IS_MINIKEYS_SEED) {
                if (isPrngInputMode) {
                    blocksPerSm = 16;
                    tuneProfile = "minikey_seed_prng";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 16;
                    tuneProfile = "minikey_seed_generated";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = "minikey_seed_file";
                }
                else {
                    blocksPerSm = 8;
                    tuneProfile = "minikey_seed_stream";
                }
            }
            else if (BRAIN) {
                if (isPrngInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "brain_prng";
                }
                else if (isSeqInputMode || isRandomInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "brain_seq_random";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "brain_file";
                }
                else {
                    blocksPerSm = 4;
                    tuneProfile = "brain_stream";
                }
            }
            else if (KEYSTORE_MODE) {
                blocksPerSm = 4;
                tuneProfile = wallet_masks.empty() && !seqMode ? "keystore_pbkdf2_file" :
                    (!wallet_masks.empty() ? "keystore_pbkdf2_mask" : "keystore_pbkdf2_range");
            }
            else if (WALLETDAT_MODE) {
                // Staged wallet.dat KDF keeps per-launch state in global memory; a wider
                // grid improves occupancy and reduces relaunch overhead without duplicating targets.
                blocksPerSm = 128;
                tuneProfile = "walletdat";
            }
            else if (WALLETJS_MODE) {
                std::string walletjs_profile_lc = walletjs_profile;
                std::transform(walletjs_profile_lc.begin(), walletjs_profile_lc.end(), walletjs_profile_lc.begin(),
                    [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
                const bool walletjsSeedProfile =
                    walletjs_profile_lc == "jsbn-arc4-v8-2011" ||
                    walletjs_profile_lc == "jsbn-arc4-v8-2015" ||
                    walletjs_profile_lc == "jsbn-arc4-spidermonkey-lcg48" ||
                    walletjs_profile_lc == "jsbn-arc4-jsc-weakrandom" ||
                    walletjs_profile_lc == "jsbn-arc4-v8-2011-exact" ||
                    walletjs_profile_lc == "jsbn-arc4-v8-2015-exact" ||
                    walletjs_profile_lc == "jsbn-arc4-spidermonkey-lcg48-exact" ||
                    walletjs_profile_lc == "jsbn-arc4-jsc-weakrandom-exact";
                if (walletjsSeedProfile && !isFileInputMode && wallet_masks.empty()) {
                    blocksPerSm = 64;
                    tuneProfile = "walletjs_seed";
                }
                else {
                    blocksPerSm = 16;
                    tuneProfile = "walletjs";
                }
            }
            else if (is_browserlike_wallet_mode()) {
                blocksPerSm = 8;
                if (STELLARWALLET_MODE) tuneProfile = "stellarwallet";
                else if (BLOCKCHAINWALLET_MODE) tuneProfile = "blockchainwallet";
                else if (MULTIBITWALLET_MODE) tuneProfile = "multibitwallet";
                else if (BIP38_MODE) tuneProfile = "bip38";
                else if (ETHPRESALE_MODE) tuneProfile = "ethpresale";
                else if (BISQWALLET_MODE) tuneProfile = "bisqwallet";
                else if (DOGECHAINWALLET_MODE) tuneProfile = "dogechainwallet";
                else if (ANDROIDWALLET_MODE) tuneProfile = "androidwallet";
                else if (COPAYWALLET_MODE) tuneProfile = "copaywallet";
                else if (TERRAWALLET_MODE) tuneProfile = "terrawallet";
                else if (BITSHARESWALLET_MODE) tuneProfile = "bitshareswallet";
                else if (YOROIWALLET_MODE) tuneProfile = "yoroiwallet";
                else tuneProfile = "browservault";
            }
            else if (ELECTRUMWALLET_MODE) {
                blocksPerSm = 32;
                tuneProfile = "electrumwallet";
            }
            else if (EXODUSSECO_MODE) {
                blocksPerSm = 4;
                tuneProfile = "exodusseco";
            }
            else if (BITCOINJWALLET_MODE || ANDROIDWALLET_MODE) {
                blocksPerSm = 4;
                tuneProfile = ANDROIDWALLET_MODE ? "androidwallet" : "bitcoinjwallet";
            }
            else if (ARMORYWALLET_MODE) {
                blocksPerSm = 4;
                tuneProfile = "armorywallet";
            }
            else if (OLD) {
                if (isPrngInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "old_prng";
                }
                else if (isSeqInputMode || isRandomInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "old_seq_random";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "old_file";
                }
                else {
                    blocksPerSm = 4;
                    tuneProfile = "old_stream";
                }
            }
            else if (ARMORY_ROOT) {
                if (isPrngInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "armory_root_prng";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "armory_root_generated";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "armory_root_file";
                }
                else {
                    blocksPerSm = 4;
                    tuneProfile = "armory_root_stream";
                }
            }
            else if (ARMORY) {
                if (isPrngInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "armory_prng";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "armory_generated";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = "armory_file";
                }
                else {
                    blocksPerSm = 4;
                    tuneProfile = "armory_stream";
                }
            }
            else if (SEED) {
                if (isPrngInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "seed_prng_multi" : "seed_prng_single";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "seed_generated_multi" : "seed_generated_single";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "seed_file_multi" : "seed_file_single";
                }
                else {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "seed_stream_multi" : "seed_stream_single";
                }
            }
            else if (HMAC) {
                if (isPrngInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "hmac_prng_multi" : "hmac_prng_single";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "hmac_generated_multi" : "hmac_generated_single";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "hmac_file_multi" : "hmac_file_single";
                }
                else {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "hmac_stream_multi" : "hmac_stream_single";
                }
            }
            else if (BIP32) {
                if (isPrngInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "bip32_prng_multi" : "bip32_prng_single";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "bip32_generated_multi" : "bip32_generated_single";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "bip32_file_multi" : "bip32_file_single";
                }
                else {
                    blocksPerSm = 8;
                    tuneProfile = (derivCount > 1u) ? "bip32_stream_multi" : "bip32_stream_single";
                }
            }
            else if (RECOVERY_MODE) {
                blocksPerSm = (derivCount > 2u) ? 2u : 1u;
                tuneProfile = (derivCount > 1u) ? "recovery_stream_multi_lowlat" : "recovery_stream_single_lowlat";
            }
            else {
                if (isPrngInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = (derivCount > 1u) ? "mnemonic_entropy_prng_multi" : "mnemonic_entropy_prng_single";
                }
                else if (isGeneratedInputMode) {
                    blocksPerSm = 4;
                    tuneProfile = (derivCount > 1u) ? "mnemonic_entropy_generated_multi" : "mnemonic_entropy_generated_single";
                }
                else if (isFileInputMode) {
                    blocksPerSm = 32;
                    tuneProfile = (derivCount > 1u) ? "mnemonic_entropy_file_multi" : "mnemonic_entropy_file_single";
                }
                else {
                    blocksPerSm = 4;
                    tuneProfile = (derivCount > 1u) ? "mnemonic_entropy_stream_multi" : "mnemonic_entropy_stream_single";
                }
            }

            if (PROFANITY_MODE) {
                const unsigned int minProfanityBlocks = 16384u;
                const unsigned int smCount = std::max(1, props.multiProcessorCount);
                const unsigned int minProfanityBlocksPerSm =
                    (minProfanityBlocks + static_cast<unsigned int>(smCount) - 1u) /
                    static_cast<unsigned int>(smCount);
                if (blocksPerSm < minProfanityBlocksPerSm) {
                    blocksPerSm = minProfanityBlocksPerSm;
                }
            }
            const uint64_t gpuFilterBytes = gpu_filter_input_bytes_total();
            if ((XP_MODE || KEYSTORE_MODE || WALLETDAT_MODE || WALLETJS_MODE || is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE) &&
                gpuFilterBytes >= (8ull << 30) && blocksPerSm > 4u) {
                blocksPerSm = 4u;
                init_log_fprintf(stderr,
                    "[!] Large GPU filter set detected (%.2f GiB); limiting '%s' to 4 blocks/SM for VRAM/cache headroom\n",
                    static_cast<double>(gpuFilterBytes) / 1073741824.0,
                    tuneProfile);
            }

            // Global safety cap by output-buffer thread budget.
            const unsigned int threadsPerBlock = (BLOCK_THREADS == 0u) ? 256u : BLOCK_THREADS;
            const unsigned int maxOutputThreads = 16u * 1024u * 1024u;
            unsigned int maxBlocks = maxOutputThreads / max(1u, threadsPerBlock);
            if (maxBlocks == 0u) {
                maxBlocks = 1u;
            }
            unsigned int maxBlocksPerSm = maxBlocks / std::max(1u, static_cast<unsigned int>(props.multiProcessorCount));
            if (maxBlocksPerSm == 0u) {
                maxBlocksPerSm = 1u;
            }
            if (blocksPerSm > maxBlocksPerSm) {
                blocksPerSm = maxBlocksPerSm;
            }
            BLOCK_NUMBER = props.multiProcessorCount * blocksPerSm;
            init_log_fprintf(stderr, "[!] Auto-tuned threadgroups profile '%s': %u per GPU core (derivations: %zu)\n", tuneProfile, blocksPerSm, derivCount);
        }


        workSize = (uint64_t)BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS;
        init_log_fprintf(stderr, "[!] %s (%d GPU cores | Threadgroups: %d | Threads: %d)\n", props.name, props.multiProcessorCount, BLOCK_NUMBER, BLOCK_THREADS);
    }
    return true;
}

// mallocFounds: allocates founds.
bool mallocFounds(uint32_t N) {

    metalError_t metalStatus;
    size_t free0, total0, free1, total1;
    metalGetLastError();
    metalStatus = metalMemGetInfo(&free0, &total0);
    if (metalStatus != metalSuccess) {
        init_log_fprintf(stderr, "[!] Metal MemGetInfo before founds allocation failed on GPU %d: %s [!]\n",
            DEVICE_NR, metalGetErrorString(metalStatus));
        return false;
    }

    if (XP_MODE) {
        metalStatus = metalMalloc((void**)&p_xp_results, static_cast<size_t>(N) * sizeof(XpReplayResult));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "[!] Metal Malloc XP result array failed [!]");
            return false;
        }
        metalStatus = metalMalloc((void**)&p_xp_count, sizeof(unsigned long long));
        if (metalStatus != metalSuccess) {
