        const bool direct_walk_state_needed =
            !RECOVERY_MODE &&
            direct_round_span > profanity_direct_rounds_per_launch();
        const bool recovery_file_walk_state_needed =
            RECOVERY_MODE &&
            profanity_recovery_file_mode &&
