        const bool allocate_profanity_walk_state = direct_walk_state_needed || recovery_file_walk_state_needed;
        if (allocate_profanity_walk_state) {
            const uint64_t state_capacity = RECOVERY_MODE
                ? (255ull * 16384ull)
                : (set_block ? (static_cast<uint64_t>(BLOCK_NUMBER) * 256ull) : (255ull * 16384ull));
            if (state_capacity == 0ull ||
                state_capacity > (std::numeric_limits<size_t>::max() / sizeof(ProfanityWalkState))) {
