                        p_profanity_walk_state_capacity = 0;
                    }
                    else {
                        fprintf(stderr, "[!] Metal Malloc Profanity walk-state failed: %s [!]\n", metalGetErrorString(metalStatus));
                        return false;
                    }
                }
                else {
                    p_profanity_walk_state_capacity = state_capacity;
