        return false;
    }

    char           (*p_str2)[512] = (char (*)[512])p_str;
    unsigned char  (*p_prv2)[64] = (unsigned char (*)[64])p_prv;
    char  (*p_pas2)[128] = (char (*)[128])p_pas;
    uint32_t(*p_h160_2)[20] = (uint32_t(*)[20])p_h160;
    uint32_t(*p_len2)[1] = (uint32_t(*)[1])p_len1;
    uint32_t(*p_iter2)[1] = (uint32_t(*)[1])p_iter1;

    if (!IS_PRIV)
    {
