                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "[!] Metal Memcpy found passwords sizes array failed [!]");
                    return false;
                }
            }
        }
    }
    if (prng64_gen || prng_gen)
    {

        metalStatus = metalWriteStateValue(d_seed, &p_seed, sizeof(p_seed));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "[!] Metal Memcpy found prng seeds array failed [!]");
            return false;
        }
    }

    metalStatus = metalWriteStateValue(d_foundPrvKeys, &p_prv2, sizeof(p_prv2));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memcpy found private keys array failed [!]");
        return false;
    }
    metalStatus = metalWriteStateValue(d_foundHash160, &p_h160_2, sizeof(p_h160_2));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memcpy found address hashes array failed [!]");
        return false;
    }
    metalStatus = metalWriteStateValue(d_type, &p_typ, sizeof(p_typ));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memcpy found hash types array failed [!]");
        return false;
    }
    metalStatus = metalWriteStateValue(d_round, &p_round, sizeof(p_round));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memcpy found rounds array failed [!]");
        return false;
    }


    if (!IS_PRIV)
    {

        metalStatus = metalMemset(p_str, 0, (size_t)N * 512);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "[!] Metal Memset found strings array failed [!]");
            return false;
        }
        metalStatus = metalMemset(p_len1, 0, (size_t)N * sizeof(uint32_t));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "[!] Metal Memset found lenght's array failed [!]");
            return false;
        }
        metalStatus = metalMemset(p_iter1, 0, (size_t)N * sizeof(uint32_t));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "[!] Metal Memset found iteration's array failed [!]");
            return false;
        }
        if (!IS_MINIKEYS) {
            metalStatus = metalMemset(p_der, 0, (size_t)N * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "[!] Metal Memset found derivations array failed [!]");
                return false;
            }
            if (p_der2 != nullptr) {
                metalStatus = metalMemset(p_der2, 0, (size_t)N * sizeof(uint32_t));
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "[!] Metal Memset found second derivations array failed [!]");
                    return false;
                }
            }
            if (pass_set) {
                metalStatus = metalMemset(p_pas, 0, (size_t)N * 128);
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "[!] Metal Memset found passwords array failed [!]");
                    return false;
                }
                metalStatus = metalMemset(p_pas_size, 0, (size_t)N * sizeof(uint16_t));
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "[!] Metal Memset found passwords sizes array failed [!]");
                    return false;
                }
            }
        }

    }
    if (prng64_gen || prng_gen)
    {

        metalStatus = metalMemset(p_seed, 0, (size_t)N * sizeof(uint64_t));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "[!] Metal Memset found prng seeds array failed [!]");
            return false;
        }
    }

    metalStatus = metalMemset(p_prv, 0, (size_t)N * 64);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memset found private keys array failed [!]");
        return false;
    }
    metalStatus = metalMemset(p_h160, 0, (size_t)N * 20 * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memset found address hashes array failed [!]");
        return false;
    }
    metalStatus = metalMemset(p_typ, 0, (size_t)N * sizeof(uint8_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memset found hash types array failed [!]");
        return false;
    }
    metalStatus = metalMemset(p_round, 0, (size_t)N * sizeof(int64_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "[!] Metal Memset found rounds array failed [!]");
        return false;
    }

    metalDeviceSynchronize();
    metalMemGetInfo(&free1, &total1);   // Snapshot after allocations.
    init_log_printf("[!] GPU %d founds memory allocated: %.2f MiB [!]\n", DEVICE_NR, (free0 - free1) / 1024.0 / 1024.0);
    return true;
}

static std::mutex g_cpu_filter_load_mutex;
static bool g_cpu_filters_loaded = false;

static bool ensure_cpu_post_filters_loaded() {
    if (!(useBloomCPU || useXorCPU)) {
        return true;
    }

    bool need_cpu_load = false;
    {
        std::lock_guard<std::mutex> lock(g_cpu_filter_load_mutex);
        if (!g_cpu_filters_loaded) {
            g_cpu_filters_loaded = true;
            need_cpu_load = true;
        }
    }

    if (!need_cpu_load) {
        return true;
    }

    if (useBloomCPU)
    {
        init_log_printf("[!] loading [%lld] bloom filter(s) in CPU RAM:\n", bloomFilesCPU.size());
        if (!loadBloomFiltersIntoSharedMemory(bloomFilesCPU))
        {
            init_log_fprintf(stderr, "\n[!] Bloom filter(s) CPU loading failed [!]\n");
            {
                std::lock_guard<std::mutex> lock(g_cpu_filter_load_mutex);
                g_cpu_filters_loaded = false;
            }
            return false;
        }

    }
    if (useXorCPU)
    {
        init_log_printf("[!] loading [%lld] uncompressed xor filter(s) in CPU RAM:\n", xorFilesCPU.size());
        if (!loadXorFilters(xorFilesCPU))
        {
            init_log_fprintf(stderr, "\n[!] XOR's CPU loading failed [!]\n");
            {
                std::lock_guard<std::mutex> lock(g_cpu_filter_load_mutex);
                g_cpu_filters_loaded = false;
            }
            return false;
        }

    }

    return true;
}

static metalError_t upload_special_coin_config() {
    metalError_t st = metalSuccess;
    uint32_t bip_derivations_enabled = g_bip_derivations_loaded ? 1u : 0u;
    st = metalWriteStateValue(BIP_DERIVATIONS_ENABLED_D, &bip_derivations_enabled, sizeof(bip_derivations_enabled));
    if (st != metalSuccess) {
        return st;
    }
    uint32_t substrate_count = static_cast<uint32_t>(g_substrate_paths_host.size());
    st = metalWriteStateValue(SUBSTRATE_PATH_COUNT_D, &substrate_count, sizeof(substrate_count));
    if (st != metalSuccess) {
        return st;
    }
    if (p_substrate_paths_dev != nullptr) {
        metalFree(p_substrate_paths_dev);
        p_substrate_paths_dev = nullptr;
    }
    if (substrate_count > 0) {
        st = metalMalloc(&p_substrate_paths_dev, substrate_count * sizeof(SubstratePathDevice));
        if (st != metalSuccess) {
            return st;
        }
        st = metalMemcpy(p_substrate_paths_dev, g_substrate_paths_host.data(), substrate_count * sizeof(SubstratePathDevice), metalMemcpyHostToDevice);
        if (st != metalSuccess) {
            return st;
        }
    }
    st = metalWriteStateValue(SUBSTRATE_PATHS_D, &p_substrate_paths_dev, sizeof(p_substrate_paths_dev));
    if (st != metalSuccess) {
        return st;
    }

    uint32_t ada_pointer_enabled = g_ada_pointer_set ? 1u : 0u;
    st = metalWriteStateValue(ADA_POINTER_ENABLED_D, &ada_pointer_enabled, sizeof(ada_pointer_enabled));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(ADA_POINTER_SLOT_D, &g_ada_pointer_slot, sizeof(g_ada_pointer_slot));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(ADA_POINTER_TX_D, &g_ada_pointer_tx, sizeof(g_ada_pointer_tx));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(ADA_POINTER_CERT_D, &g_ada_pointer_cert, sizeof(g_ada_pointer_cert));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(ADA_TYPE_MASK_D, &g_ada_type_mask, sizeof(g_ada_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(TON_TYPE_MASK_D, &g_ton_type_mask, sizeof(g_ton_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(DOT_TYPE_MASK_D, &g_dot_type_mask, sizeof(g_dot_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(APTOS_TYPE_MASK_D, &g_aptos_type_mask, sizeof(g_aptos_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(SUI_TYPE_MASK_D, &g_sui_type_mask, sizeof(g_sui_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(XRP_TYPE_MASK_D, &g_xrp_type_mask, sizeof(g_xrp_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(IOTA_TYPE_MASK_D, &g_iota_type_mask, sizeof(g_iota_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(ICP_TYPE_MASK_D, &g_icp_type_mask, sizeof(g_icp_type_mask));
    if (st != metalSuccess) return st;
    st = metalWriteStateValue(FIL_TYPE_MASK_D, &g_fil_type_mask, sizeof(g_fil_type_mask));
    if (st != metalSuccess) return st;
    return metalWriteStateValue(XTZ_TYPE_MASK_D, &g_xtz_type_mask, sizeof(g_xtz_type_mask));
}

// prepareMetal: prepares metal.
metalError_t prepareMetal() {
    unsigned int windows;
    unsigned int bits;
    size_t window_size;
    std::time_t s_time;
    metalError_t metalStatus;
    gpu_bloom_loaded = false;
    gpu_xor_loaded = false;
    gpu_xor_un_loaded = false;
    gpu_xor_uc_loaded = false;
    gpu_xor_hc_loaded = false;


#ifdef ECMULT_BIG_TABLE
    bits = PARAM_ECMULT_WINDOW_SIZE;
    s_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    windows = (256 / bits) + 1;
    window_size = (1 << (bits - 1));
    init_log_printf("[!] GPU %d: preparing Metal device... Please wait... \n", DEVICE_NR);
    if (secp256_host) {
        metalStatus = metalMallocPitch(&_dev_precomp, &pitch, sizeof(secp256k1_ge_storage) * window_size, windows);
        if (metalStatus != metalSuccess) {
            init_log_fprintf(stderr, "[!] Metal prepare failed: kernel launch failed: %s [!]\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = loadWindow(bits, windows);
        if (metalStatus != metalSuccess) {
            init_log_fprintf(stderr, "[!] Metal prepare failed: loadWindow(bits) %d! [!]\n", metalStatus);
            goto Error;
        }

        {
            std::vector<secp256k1_ge_storage> host_precomp;
            size_t host_pitch = 0u;
            unsigned int host_windows = 0u;
            std::string precompute_error;
            if (!build_secp256k1_precompute_table_host(
                    bits, host_precomp, host_pitch, host_windows, precompute_error) ||
                host_windows != windows || host_pitch != pitch) {
                init_log_fprintf(stderr, "[!] Metal prepare failed: secp256k1 host precompute: %s [!]\n",
                    precompute_error.empty() ? "layout mismatch" : precompute_error.c_str());
                metalStatus = metalErrorInvalidValue;
                goto Error;
            }
            metalStatus = metalMemcpy(_dev_precomp,
                                    host_precomp.data(),
                                    host_precomp.size() * sizeof(secp256k1_ge_storage),
                                    metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                init_log_fprintf(stderr, "[!] Metal prepare failed: secp256k1 host precompute upload: %s [!]\n",
                    metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        init_log_printf("[!] GPU %d: preparing finished \n", DEVICE_NR);
    Error:
        ;
    }
#else
    bits = ECMULT_GEN_PREC_BITS;
    if (bits != 8 && bits != 4 && bits != 2) {
        int g = ECMULT_GEN_PREC_G;
        int n = ECMULT_GEN_PREC_N;
        init_log_printf("[!] prec gen %d bit, please wait [!]\n", bits);
        secp256k1_ge_storage* _dev_prec_table = new secp256k1_ge_storage[g * n];
        secp256k1_ge* _dev_prec = new secp256k1_ge[g * n];
        secp256k1_gej* _dev_precj = new secp256k1_gej[g * n];

        metalStatus = metalMalloc((void**)&_dev_precj, g * n * sizeof(secp256k1_gej));
        metalStatus = metalMalloc((void**)&_dev_prec, g * n * sizeof(secp256k1_ge));
        metalStatus = metalMalloc((void**)&_dev_prec_table, g * n * sizeof(secp256k1_ge_storage));

        metal_launch("computeTable", 1, 1, _dev_prec_table, _dev_prec, _dev_precj);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            init_log_fprintf(stderr, "[!] Metal prepare failed: kernel launch failed: %s [!]\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            init_log_fprintf(stderr, "[!] Metal prepare failed: metalDeviceSynchronize returned error code %d after launching kernel 'computeTable'! [!]\n", metalStatus);
            goto Error;
        }
        init_log_printf("[!] GPU %d: prec gen %d bit finished [!]\n", DEVICE_NR, bits);
    Error:
        metalFree(_dev_precj);
        metalFree(_dev_prec);
        metalFree(_dev_prec_table);

    }
#endif
    if (IS_HEX)
    {
        metal_launch("setHEX", 1, 1);
        init_log_printf("[!] using -hex --- input strings are interpreted as hex-encoded bytes [!]\n");
    }
    if (IS_UTF8)
    {
        metal_launch("setUTF8", 1, 1);
        init_log_printf("[!] Using -utf8 --- all hash output will be represented as UTF-8 strings!\n");
    }
    if (seqMode)
    {
        metal_launch("SetSeqStep", 1, 1, step);
    }
    if (FULL)
    {
        metal_launch("setFULL", 1, 1);
        init_log_printf("[!] using -full --- ALL hashes will be saved as founds!!!\n");
    }
    else
    {
        if (useBloom) {
            init_log_printf("[!] loading [%lld] bloom filter(s):\n", bloomFiles.size());
            metalStatus = _targetLookup.setTargets(bloomFiles);
            if (metalStatus != metalSuccess) {
                init_log_fprintf(stderr, "\n[!] Bloom filter(s) loading failed on GPU %d, skipping bloom on this GPU: %s [!]\n", DEVICE_NR, metalGetErrorString(metalStatus));
            }
            else {
                gpu_bloom_loaded = true;
            }
        }
        if (useXor)
        {
            init_log_printf("[!] loading [%lld] compressed xor filter(s):\n", xorFiles.size());
            metalStatus = setTargetXorFilter(xorFiles);
            if (metalStatus != metalSuccess) {
                init_log_fprintf(stderr, "\n[!] Compressed xor filters loading failed on GPU %d, skipping on this GPU: %s [!]\n", DEVICE_NR, metalGetErrorString(metalStatus));
            }
            else {
                gpu_xor_loaded = true;
            }
        }
        if (useXorUn)
        {
            init_log_printf("[!] loading [%lld] uncompressed xor filter(s):\n", xorFilesUn.size());
            metalStatus = setTargetXorUnFilter(xorFilesUn);
            if (metalStatus != metalSuccess) {
                init_log_fprintf(stderr, "\n[!] Uncompressed xor filters loading failed on GPU %d, skipping on this GPU: %s [!]\n", DEVICE_NR, metalGetErrorString(metalStatus));
            }
            else {
                gpu_xor_un_loaded = true;
            }
        }
        if (useXorUc)
        {
            init_log_printf("[!] loading [%lld] ultra compressed xor filter(s):\n", xorFilesUc.size());
            metalStatus = setTargetXorUcFilter(xorFilesUc);
            if (metalStatus != metalSuccess) {
                init_log_fprintf(stderr, "\n[!] Ultra compressed xor filters loading failed on GPU %d, skipping on this GPU: %s [!]\n", DEVICE_NR, metalGetErrorString(metalStatus));
            }
            else {
                gpu_xor_uc_loaded = true;
            }
        }
        if (useXorHc)
        {
            init_log_printf("[!] loading [%lld] hyper compressed xor filter(s):\n", xorFilesHc.size());
            metalStatus = setTargetXorHcFilter(xorFilesHc);
            if (metalStatus != metalSuccess) {
                init_log_fprintf(stderr, "\n[!] Hyper compressed xor filters loading failed on GPU %d, skipping on this GPU: %s [!]\n", DEVICE_NR, metalGetErrorString(metalStatus));
            }
            else {
                gpu_xor_hc_loaded = true;
            }
        }

        if (useBloomCPU || useXorCPU)
        {
            if (!ensure_cpu_post_filters_loaded()) {
                goto Error;
            }
        }
    }
    metalStatus = loadHashTarget(hashTargetWordsHost, hashTargetMasksHost, hashTargetLenBytes, useHashTarget);
    if (metalSuccess != metalStatus) {
        init_log_fprintf(stderr, "\n[!] Metal prepare failed: 'loadHashTarget' %s [!]\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    if (useHashTarget) {
        init_log_printf("[!] GPU %d: loaded hash prefix matcher (%u byte(s), hex=%s)\n",
            DEVICE_NR, hashTargetLenBytes, hashTargetHex.c_str());
    }
    metalStatus = loadIteration(HASH_ITERATION);
    if (metalSuccess != metalStatus) {
        init_log_fprintf(stderr, "\n[!] Metal prepare failed: 'loadIteration' %s [!]\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = upload_special_coin_config();
    if (metalSuccess != metalStatus) {
        init_log_fprintf(stderr, "\n[!] Metal prepare failed: 'upload_special_coin_config' %s [!]\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    init_log_printf("[!] GPU %d: all preparation finished.\n", DEVICE_NR);
    metalMemGetInfo(&free_gpu_end, &total_gpu_end);
    init_log_printf("[!] GPU %d total memory used: %.2f MiB [!]\n", DEVICE_NR, (free_gpu_start - free_gpu_end) / 1024.0 / 1024.0);
    init_log_printf("-----------------------------------------------------------------\n");
    init_log_printf("[!] Loaded bloom filters on GPU %d: %lld\n", DEVICE_NR, gpu_bloom_loaded ? (long long)bloomFiles.size() : 0ll);
    init_log_printf("[!] Loaded uncompressed xor filters on GPU %d: %lld\n", DEVICE_NR, gpu_xor_un_loaded ? (long long)xorFilesUn.size() : 0ll);
    init_log_printf("[!] Loaded compressed xor filters on GPU %d: %lld\n", DEVICE_NR, gpu_xor_loaded ? (long long)xorFiles.size() : 0ll);
    init_log_printf("[!] Loaded ultra compressed xor filters on GPU %d: %lld\n", DEVICE_NR, gpu_xor_uc_loaded ? (long long)xorFilesUc.size() : 0ll);
    init_log_printf("[!] Loaded hyper compressed xor filters on GPU %d: %lld\n", DEVICE_NR, gpu_xor_hc_loaded ? (long long)xorFilesHc.size() : 0ll);
    init_log_printf("[!] Loaded hash prefix matcher on GPU %d: %s\n", DEVICE_NR, useHashTarget ? "yes" : "no");
#ifdef ECMULT_BIG_TABLE
    /*Error:
        metalFree(_dev_gej_temp);
        metalFree(_dev_z_ratio);*/
#else
    /*Error:
        metalFree(_dev_precj);
        metalFree(_dev_prec);
        metalFree(_dev_prec_table);*/
#endif

    return metalStatus;
}

// release_gpu_context: releases GPU context.
static void release_gpu_context(GpuRuntimeContext& ctx) {
    if (metalSetDevice(ctx.device_id) != metalSuccess) {
        return;
    }
    if (ctx.p_str) metalFree(ctx.p_str);
    if (ctx.p_prv) metalFree(ctx.p_prv);
    if (ctx.p_h160) metalFree(ctx.p_h160);
    if (ctx.p_typ) metalFree(ctx.p_typ);
    if (ctx.p_len1) metalFree(ctx.p_len1);
    if (ctx.p_iter1) metalFree(ctx.p_iter1);
    if (ctx.p_der) metalFree(ctx.p_der);
    if (ctx.p_der2) metalFree(ctx.p_der2);
    if (ctx.p_pas) metalFree(ctx.p_pas);
    if (ctx.p_pas_size) metalFree(ctx.p_pas_size);
    if (ctx.p_round) metalFree(ctx.p_round);
    if (ctx.p_seed) metalFree(ctx.p_seed);
    if (ctx.p_substrate_paths_dev) metalFree(ctx.p_substrate_paths_dev);
    if (ctx.p_profanity_results) metalFree(ctx.p_profanity_results);
    if (ctx.p_profanity_count) metalFree(ctx.p_profanity_count);
    if (ctx.p_wallet_results) metalFree(ctx.p_wallet_results);
    if (ctx.p_wallet_count) metalFree(ctx.p_wallet_count);
    if (ctx.p_xp_results) metalFree(ctx.p_xp_results);
    if (ctx.p_xp_count) metalFree(ctx.p_xp_count);
    if (ctx.p_profanity_walk_state) metalFree(ctx.p_profanity_walk_state);
    if (ctx.p_profanity_recovery_target_pubkey) metalFree(ctx.p_profanity_recovery_target_pubkey);
    if (ctx.p_profanity_recovery_target_ge) metalFree(ctx.p_profanity_recovery_target_ge);
    if (ctx.p_profanity_recovery_target_ge_ok) metalFree(ctx.p_profanity_recovery_target_ge_ok);
    if (ctx.p_profanity_recovery_hits) metalFree(ctx.p_profanity_recovery_hits);
    if (ctx.p_profanity_recovery_hit_count) metalFree(ctx.p_profanity_recovery_hit_count);
    if (ctx.passwords_dev) metalFree(ctx.passwords_dev);
    if (ctx.shared_result_flag) metalFree(ctx.shared_result_flag);
    if (ctx.shared_result_buffer) metalFree(ctx.shared_result_buffer);
    if (ctx.dev_precomp) metalFree(ctx.dev_precomp);

    ctx.p_str = nullptr;
    ctx.p_prv = nullptr;
    ctx.p_h160 = nullptr;
    ctx.p_typ = nullptr;
    ctx.p_len1 = nullptr;
    ctx.p_iter1 = nullptr;
    ctx.p_der = nullptr;
    ctx.p_der2 = nullptr;
    ctx.p_pas = nullptr;
    ctx.p_pas_size = nullptr;
    ctx.p_round = nullptr;
    ctx.p_seed = nullptr;
    ctx.p_substrate_paths_dev = nullptr;
    ctx.p_profanity_results = nullptr;
    ctx.p_profanity_count = nullptr;
    ctx.p_wallet_results = nullptr;
    ctx.p_wallet_count = nullptr;
    ctx.p_xp_results = nullptr;
    ctx.p_xp_count = nullptr;
    ctx.p_profanity_walk_state = nullptr;
    ctx.p_profanity_walk_state_capacity = 0;
    ctx.p_profanity_recovery_target_pubkey = nullptr;
    ctx.p_profanity_recovery_target_ge = nullptr;
    ctx.p_profanity_recovery_target_ge_ok = nullptr;
    ctx.p_profanity_recovery_hits = nullptr;
    ctx.p_profanity_recovery_hit_count = nullptr;
    ctx.profanity_recovery_target_cache_hex.clear();
    ctx.profanity_recovery_target_cache_len = 0;
    ctx.profanity_recovery_walk_state_valid = false;
    ctx.profanity_recovery_walk_state_target_hex.clear();
    ctx.profanity_recovery_walk_state_lane_start = 0;
    ctx.profanity_recovery_walk_state_lane_count = 0;
    ctx.profanity_recovery_walk_state_next_round = 0;
    ctx.passwords_dev = nullptr;
    ctx.passwords_dev_capacity = 0;
    ctx.passwords_lenght_dev = 0;
    ctx.shared_result_flag = nullptr;
    ctx.shared_result_buffer = nullptr;
    ctx.shared_result_buffer_capacity = 0;
    ctx.dev_precomp = nullptr;
    ctx.pitch = 0;
    ctx.bloom_loaded = false;
    ctx.xor_loaded = false;
    ctx.xor_un_loaded = false;
    ctx.xor_uc_loaded = false;
    ctx.xor_hc_loaded = false;
}

// release_all_gpu_contexts: releases all GPU contexts.
static void release_all_gpu_contexts() {
    for (auto& ctx : g_gpu_contexts) {
        release_gpu_context(ctx);
    }
    g_gpu_contexts.clear();
    g_save_output_with_gpu_prefix = false;
}

// build_valid_device_list: builds valid device list.
static bool build_valid_device_list(std::vector<int>& out_devices) {
    out_devices.clear();
    int device_count = 0;
    metalError_t st = metalGetDeviceCount(&device_count);
    if (st != metalSuccess || device_count <= 0) {
        fprintf(stderr, "[!] Metal device enumeration failed: %s [!]\n", metalGetErrorString(st));
        return false;
    }

    if (DEVICE_LIST.empty()) {
        DEVICE_LIST.push_back(DEVICE_NR);
    }

    std::unordered_set<int> seen;
    for (const int dev : DEVICE_LIST) {
        if (dev < 0 || dev >= device_count) {
            fprintf(stderr, "[!] Warning: device %d is out of range [0..%d], skipped [!]\n", dev, device_count - 1);
            continue;
        }
        if (seen.insert(dev).second) {
            out_devices.push_back(dev);
        }
    }
    return !out_devices.empty();
}

// initialize_gpu_contexts: initializes GPU contexts.
static bool initialize_gpu_contexts(const unsigned int requested_threads, const unsigned int requested_blocks) {
    g_save_output_with_gpu_prefix = false;
    std::vector<int> valid_devices;
    if (!build_valid_device_list(valid_devices)) {
        fprintf(stderr, "[!] No valid Metal devices selected [!]\n");
        return false;
    }

    g_gpu_contexts.clear();
    if (!ensure_cpu_post_filters_loaded()) {
        return false;
    }

    struct GpuInitResult {
        int device_id = 0;
        bool ok = false;
        std::string log;
        std::unique_ptr<GpuRuntimeContext> context;
    };

    std::vector<GpuInitResult> init_results(valid_devices.size());
    std::vector<std::thread> init_threads;
    init_threads.reserve(valid_devices.size());

    for (size_t index = 0; index < valid_devices.size(); ++index) {
        init_results[index].device_id = valid_devices[index];
        init_threads.emplace_back([&, index]() {
            GpuInitResult& result = init_results[index];
            const int dev = result.device_id;
            g_gpu_init_log_sink = &result.log;

        reset_thread_local_gpu_runtime_aliases_for_init();
        _dev_precomp = nullptr;
        pitch = 0;
        gpu_bloom_loaded = false;
        gpu_xor_loaded = false;
        gpu_xor_un_loaded = false;
        gpu_xor_uc_loaded = false;
        gpu_xor_hc_loaded = false;

        DEVICE_NR = dev;
        BLOCK_THREADS = requested_threads;
        BLOCK_NUMBER = requested_blocks;

        init_log_fprintf(stderr, "[!] Initializing GPU %d...\n", dev);
        if (!checkDevice()) {
            init_log_fprintf(stderr, "[!] Device %d init skipped [!]\n", dev);
            g_gpu_init_log_sink = nullptr;
            return;
        }

        metalMemGetInfo(&free_gpu_start, &total_gpu_start);
        metal_launch("setFoundSize", 1, 1, MAX_FOUNDS);
        metalError_t st = metalDeviceSynchronize();
        if (st != metalSuccess) {
            init_log_fprintf(stderr, "[!] setFoundSize failed on GPU %d: %s [!]\n", dev, metalGetErrorString(st));
            g_gpu_init_log_sink = nullptr;
            return;
        }

        if (!mallocFounds(MAX_FOUNDS)) {
            init_log_fprintf(stderr, "[!] mallocFounds failed on GPU %d [!]\n", dev);
            GpuRuntimeContext tmp = capture_current_gpu_context();
            release_gpu_context(tmp);
            g_gpu_init_log_sink = nullptr;
            return;
        }

        st = prepareMetal();
        if (st != metalSuccess) {
            init_log_fprintf(stderr, "[!] prepareMetal failed on GPU %d: %s [!]\n", dev, metalGetErrorString(st));
            GpuRuntimeContext tmp = capture_current_gpu_context();
            release_gpu_context(tmp);
            g_gpu_init_log_sink = nullptr;
            return;
        }

        uint64_t shared_result_capacity = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
        if (PROFANITY_MODE || KEYSTORE_MODE || WALLETDAT_MODE || WALLETJS_MODE || is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE || XP_MODE) {
            // These modes use dedicated compact result buffers. The generic
            // per-thread result buffers waste memory and scale badly with -b/-t.
            shared_result_capacity = 1ull;
        }
        else {
            uint64_t max_output_multiplier = 1ull;
            if (static_cast<uint64_t>(THREAD_STEPS) > max_output_multiplier) {
                max_output_multiplier = static_cast<uint64_t>(THREAD_STEPS);
            }
            if (static_cast<uint64_t>(THREAD_STEPS_PUB_H) > max_output_multiplier) {
                max_output_multiplier = static_cast<uint64_t>(THREAD_STEPS_PUB_H);
            }
            if (static_cast<uint64_t>(THREAD_STEPS_BRAIN) > max_output_multiplier) {
                max_output_multiplier = static_cast<uint64_t>(THREAD_STEPS_BRAIN);
            }
            if (max_output_multiplier > 1ull) {
                if (shared_result_capacity > (std::numeric_limits<uint64_t>::max() / max_output_multiplier)) {
                    shared_result_capacity = std::numeric_limits<uint64_t>::max();
                }
                else {
                    shared_result_capacity *= max_output_multiplier;
                }
            }
        }
        st = init_shared_result_buffers_for_current_gpu(shared_result_capacity);
        if (st != metalSuccess) {
            init_log_fprintf(stderr, "[!] shared result buffers init failed on GPU %d: %s [!]\n", dev, metalGetErrorString(st));
            GpuRuntimeContext tmp = capture_current_gpu_context();
            release_gpu_context(tmp);
            g_gpu_init_log_sink = nullptr;
            return;
        }

        if (!pass_set) {
            st = copy_password_to_device("", 0);
            if (st != metalSuccess) {
                init_log_fprintf(stderr, "[!] default password upload failed on GPU %d: %s [!]\n", dev, metalGetErrorString(st));
                GpuRuntimeContext tmp = capture_current_gpu_context();
                release_gpu_context(tmp);
                g_gpu_init_log_sink = nullptr;
                return;
            }
            passwords_lenght_dev = 0;
        }
        else {
            metal_launch("setPASS", 1, 1);
        }

        metal_launch("rand_state", 1, 1);
        metal_launch("SetCurve", 1, 1, secp256_host, ed25519_host, Electrum, Ton_mnemonic, Ton_only, Old_electrum, Compressed, Uncompressed, Segwit, P2wsh, Taproot, Ethereum, Xpoint, Solana, Ton, Ton_all, Dot, Aptos, Sui, Xrp, Exodus, Iota, Ada, Icp, Fil, Xtz, Endomorphism);
        metal_launch("SetDerivationTypeMask", 1, 1, derivation_type_mask_host);
        if (is_ed25519_scalar) {
            metal_launch("setEd25519_scalar", 1, 1);
            if (is_ed25519_le) {
                metal_launch("setLE", 1, 1);
            }
        }
        else if (is_ed25519_hash) {
            metal_launch("setEd25519_hash", 1, 1);
        }
        metal_launch("setFilterType", 1, 1, gpu_bloom_loaded, gpu_xor_loaded, gpu_xor_un_loaded, gpu_xor_uc_loaded, gpu_xor_hc_loaded);
        metal_launch("setDict", 1, 1, language);
        metal_launch("set_electrum", 1, 1, Electrum_seg, Electrum_128, Electrum_cake_wallet);
        metal_launch("set_iter", 1, 1, pbkdf_iter);

        st = metalDeviceSynchronize();
        if (st != metalSuccess) {
            init_log_fprintf(stderr, "[!] Runtime constant setup failed on GPU %d: %s [!]\n", dev, metalGetErrorString(st));
            GpuRuntimeContext tmp = capture_current_gpu_context();
            release_gpu_context(tmp);
            g_gpu_init_log_sink = nullptr;
            return;
        }

            result.context.reset(new GpuRuntimeContext(capture_current_gpu_context()));
            result.ok = true;
            g_gpu_init_log_sink = nullptr;
        });
    }

    for (std::thread& t : init_threads) {
        if (t.joinable()) {
            t.join();
        }
    }

    for (GpuInitResult& result : init_results) {
        if (!result.log.empty()) {
            std::fwrite(result.log.data(), 1, result.log.size(), stderr);
        }
        if (result.ok && result.context) {
            g_gpu_contexts.emplace_back(std::move(*result.context));
        }
    }
    std::fflush(stderr);

    if (g_gpu_contexts.empty()) {
        return false;
    }
    g_save_output_with_gpu_prefix = (g_gpu_contexts.size() > 1);
    activate_gpu_context(g_gpu_contexts.front());
    return true;
}

// write_hex_last: writes hex last.
static inline void write_hex_last(FILE* f, const uint8_t* buf, uint64_t total, uint64_t n, bool isMinus = false) {
    if (n > total) n = total;
    uint64_t start = total - n;
    static const char* hexd = "0123456789abcdef";
    char type[2] = { 0 };
    if (isMinus)
    {
        type[0] = '-';
        type[1] = ' ';
    }
    else
    {
        type[0] = '+';
        type[1] = ' ';
    }
    fwrite(type, 1, 2, f);
    for (uint64_t i = start; i < total; ++i) {
        unsigned b = buf[i];
        char out[2] = { hexd[b >> 4], hexd[b & 0xF] };
        fwrite(out, 1, 2, f);
    }
    fputc('\n', f);
}

// ??? pass_thread support ????????????????????????????????????????????????????
// PtPassBuf: packed password buffer for pass_thread kernels.
// Password i is stored at data[i * PASS_THREAD_STRIDE] with length lens[i].
struct PtPassBuf {
    std::vector<uint8_t> data;
    std::vector<uint8_t> lens;
    uint32_t count = 0;
    void reset() { data.clear(); lens.clear(); count = 0; }
    void push(const char* p, size_t L) {
        if (L > 127) L = 127;
        data.resize((size_t)(count + 1) * PASS_THREAD_STRIDE, 0);
        if (L > 0) memcpy(data.data() + (size_t)count * PASS_THREAD_STRIDE, p, L);
        lens.push_back((uint8_t)L);
        ++count;
    }
    void push(const std::string& s) { push(s.data(), s.size()); }
};

static inline void pt_reset_batches(std::vector<PtPassBuf>& batches) {
    for (PtPassBuf& batch : batches) batch.reset();
}

// Streaming reader: opens password files once and reads them in batches.
// rewind() seeks all files back to the beginning (called per-mnemonic).
struct PtPassReader {
    std::vector<std::ifstream> files;
    size_t file_idx = 0;
    size_t list_pos = 0;

    void open(const std::vector<std::string>& fnames) {
        files.clear();
        files.reserve(fnames.size());
        for (const auto& fname : fnames) {
            files.emplace_back();
            tune_ifstream_buffer(files.back());
            files.back().open(fname, std::ios::in);
        }
        rewind();
    }

    void rewind() {
        for (auto& f : files) { f.clear(); f.seekg(0); }
        file_idx = 0;
        list_pos = 0;
    }

    // Fill buf with up to max_count passwords. Returns true if any were read.
    bool read_batch(PtPassBuf& buf, uint32_t max_count) {
        buf.reset();
        buf.data.reserve((size_t)max_count * PASS_THREAD_STRIDE);
        buf.lens.reserve(max_count);
        std::string line;
        while (buf.count < max_count) {
            if (file_idx < files.size()) {
                if (std::getline(files[file_idx], line)) {
                    if (!line.empty() && line.back() == '\r') line.pop_back();
                    buf.push(line);
                    continue;
                }
                ++file_idx;
                continue;
            }
            if (list_pos < passwords_list.size()) {
                buf.push(passwords_list[list_pos++]);
                continue;
            }
            break;
        }
        return buf.count > 0;
    }
};

static PtPassReader g_pt_pass_reader;
static bool         g_pt_pass_reader_opened = false;

static void ensure_pt_pass_reader() {
    if (!g_pt_pass_reader_opened) {
        g_pt_pass_reader.open(passwords_files);
        g_pt_pass_reader_opened = true;
    }
}

static inline bool wallet_is_flag_token(const char* s) {
    return s != nullptr && s[0] == '-';
}

static inline std::string wallet_trim_copy(std::string s) {
    size_t b = 0;
    while (b < s.size() && std::isspace(static_cast<unsigned char>(s[b]))) ++b;
    size_t e = s.size();
    while (e > b && std::isspace(static_cast<unsigned char>(s[e - 1]))) --e;
    return s.substr(b, e - b);
}

static inline std::string wallet_lower_copy(std::string s) {
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

