static void xp_add_bip32_root_derivation_if_needed()
{
    if (!Derivations_list.empty() || !derIndex.empty() || !Derivations.empty()) {
        return;
    }
    derIndex.emplace_back(0);
    derIndex_size++;
    Derivations_list.push_back("m/");
}

static bool xp_add_default_derivation_if_needed(const std::string& path)
{
    if (!Derivations_list.empty() || !derIndex.empty() || !Derivations.empty() || !derivationFiles.empty()) {
        return false;
    }

    std::string p = path;
    if (p == "m" || p == "m/") {
        derIndex.emplace_back(0);
        derIndex_size++;
        Derivations_list.push_back("m/");
        return true;
    }
    if (p.rfind("m/", 0) == 0) {
        p.erase(0, 2);
    }

    const size_t old_size = Derivations.size();
    uint32_t parsed_count = 0;
    if (!parse_derivation_components_fast(p, parsed_count)) {
        Derivations.resize(old_size);
        return false;
    }
    derIndex.emplace_back(parsed_count);
    derIndex_size++;
    Derivations_list.push_back("m/" + p);
    return true;
}

