static bool xp_b4q_duplicate_or_unclosed_profile_error(const std::string& p, std::string& err)
{
    if (p == "time-lcg-glibc") {
        err = "B4Q time-lcg-glibc is covered by canonical -xp time-lcg-direct:glibc";
        return true;
    }
    if (p == "time-lcg-msvc") {
        err = "B4Q time-lcg-msvc is covered by canonical -xp time-lcg-direct:msvc";
        return true;
    }
    if (p == "time-lcg-pid") {
        err = "B4Q time-lcg-pid is covered by canonical -xp time-lcg-direct:glibc-xor-pid";
        return true;
    }
    if (p == "borland-lcg") {
        err = "B4Q borland-lcg is covered by canonical -xp time-lcg-direct:borland";
        return true;
    }
    if (p == "lcg-usec-seed") {
        err = "B4Q lcg-usec-seed is the glibc LCG direct lane over a full uint32 seed range; use -xp time-lcg-direct:glibc -s 0 -e ffffffff";
        return true;
    }
    if (p == "dual-lcg-xor") {
        err = "B4Q dual-lcg-xor is covered by canonical -xp time-lcg-direct:dual-xor";
        return true;
    }
    if (p == "sha256-time" || p == "sha256-ms-time" || p == "sha256-decimal") {
        err = "B4Q " + p + " is covered by canonical -xp sha256-direct:decimal with the matching numeric timestamp/range";
        return true;
    }
    if (p == "sha256-seq") {
        err = "B4Q sha256-seq is covered by canonical -xp sha256-direct:be64";
        return true;
    }
    if (p == "sha256d-seq") {
        err = "B4Q sha256d-seq is covered by canonical -xp sha256-direct:be64d";
        return true;
    }
    if (p == "sha256-hex-seq") {
        err = "B4Q sha256-hex-seq is covered by canonical -xp sha256-direct:hex";
        return true;
    }
    if (p == "phone-sha256") {
        err = "B4Q phone-sha256 is covered by canonical -xp sha256-direct:phone10";
        return true;
    }
    if (p == "sha256-short-ascii") {
        err = "B4Q sha256-short-ascii is covered by canonical -xp sha256-direct:short-ascii";
        return true;
    }
    if (p == "low-bits") {
        err = "B4Q low-bits is covered by canonical -xp lowbits-direct";
        return true;
    }
    if (p == "openssl-pid") {
        err = "B4Q openssl-pid is covered by canonical -xp pid-hash-direct";
        return true;
    }
    if (p == "java-lcg") {
        err = "B4Q java-lcg is covered by canonical -xp java-lcg-direct";
        return true;
    }
    if (p == "php-mt-seed") {
        err = "B4Q php-mt-seed is recognized but not implemented as a new -xp alias: time*PID seeding is known, but the exact private-key byte/range layout is not closed beyond existing phpcoinaddress";
        return true;
    }
    if (p == "v8-xorshift128") {
        err = "B4Q v8-xorshift128 is recognized but not implemented as a new -xp alias: current source evidence does not close an exact direct-private replay distinct from existing Randstorm profiles";
        return true;
    }
    if (p == "openssl-debian") {
        err = "B4Q openssl-debian is recognized but not implemented as a new -xp alias: use exact openssl:* paths or pid-hash-direct where applicable; no extra byte layout is closed here";
        return true;
    }
    return false;
}

static bool xp_path_mask_from_token(const std::string& token_raw, uint64_t& mask, uint32_t& count, std::string& err) {
    std::string token = wallet_lower_copy(wallet_trim_copy(token_raw));
    if (token.rfind("openssl:", 0) == 0) {
        token.erase(0, 8);
    }
    if (token == "openssl" || token == "all") {
        mask = XP_OPENSSL_ALL_PATH_MASK;
        count = XP_OPENSSL_PATH_COUNT;
        return true;
    }
    if (token.rfind("path", 0) == 0) {
        const std::string num = token.substr(4);
        if (num.empty()) {
            err = "missing path number";
            return false;
        }
        char* endp = nullptr;
        const long p = std::strtol(num.c_str(), &endp, 10);
        if (*endp != '\0' || p < 0 || p >= static_cast<long>(XP_OPENSSL_PATH_COUNT)) {
            err = "path must be path0..path53";
            return false;
        }
        mask = 1ull << static_cast<uint32_t>(p);
        count = 1u;
        return true;
    }
    struct NameMap { const char* name; uint32_t path; };
    static const NameMap names[] = {
        {"0.3.24",0},{"0.8.6d",1},{"0.8.6-d",1},{"0.8.6qt",2},{"0.8.6-qt",2},
        {"0.9.1d",3},{"0.9.1-d",3},{"0.9.4d",4},{"0.9.4-d",4},
        {"unknowna",5},{"unka",5},{"unknownb",6},{"unkb",6},{"unknownc",7},{"unkc",7},{"unknownd",8},{"unkd",8},
        {"unknowne",9},{"unke",9},{"unknownf",10},{"unkf",10},{"unknowng",11},{"unkg",11},{"unknownh",12},{"unkh",12},
        {"unknowni",13},{"unki",13},{"unknownj",14},{"unkj",14},{"unknownk",15},{"unkk",15},
        {"unknowna0",16},{"unka0",16},{"unknowna1",17},{"unka1",17},{"unknowna2",18},{"unka2",18},{"unknowna3",19},{"unka3",19},{"unknowna4",20},{"unka4",20},
        {"unknownb0",21},{"unkb0",21},{"unknownb1",22},{"unkb1",22},{"unknownb2",23},{"unkb2",23},{"unknownb3",24},{"unkb3",24},
        {"unknownc0",25},{"unkc0",25},{"unknownc1",26},{"unkc1",26},{"unknownc2",27},{"unkc2",27},
        {"unknownd0",28},{"unkd0",28},{"unknownd1",29},{"unkd1",29},{"unknownd2",30},{"unkd2",30},{"unknownd3",31},{"unkd3",31},{"unknownd4",32},{"unkd4",32},{"unknownd5",33},{"unkd5",33},
        {"unknowne0",34},{"unke0",34},
        {"unknowna0x",35},{"unka0x",35},{"unknowna1x",36},{"unka1x",36},{"unknowna2x",37},{"unka2x",37},{"unknowna3x",38},{"unka3x",38},{"unknowna4x",39},{"unka4x",39},
        {"unknownb0x",40},{"unkb0x",40},{"unknownb1x",41},{"unkb1x",41},{"unknownb2x",42},{"unkb2x",42},{"unknownb3x",43},{"unkb3x",43},
        {"unknownc0x",44},{"unkc0x",44},{"unknownc1x",45},{"unkc1x",45},{"unknownc2x",46},{"unkc2x",46},
        {"unknownd0x",47},{"unkd0x",47},{"unknownd1x",48},{"unkd1x",48},{"unknownd2x",49},{"unkd2x",49},{"unknownd3x",50},{"unkd3x",50},{"unknownd4x",51},{"unkd4x",51},{"unknownd5x",52},{"unkd5x",52},
        {"unknowne0x",53},{"unke0x",53}
    };
    for (const auto& n : names) {
        if (token == n.name) {
            mask = 1ull << n.path;
            count = 1u;
            return true;
        }
    }
    err = "unknown OpenSSL XP profile/path";
    return false;
}

static uint32_t xp_count_mask_bits(uint64_t mask, uint32_t max_bits)
{
    uint32_t count = 0u;
    for (uint32_t i = 0u; i < max_bits; ++i) {
        if ((mask & (1ull << i)) != 0ull) ++count;
    }
    return count;
}

static constexpr uint32_t XP_RANDSTORM_XP_ENGINE_COUNT = 8u;
static constexpr uint32_t XP_RANDSTORM_XP_GROUP_COUNT = 8u;
static constexpr uint32_t XP_RANDSTORM_XP_PROFILE_COUNT = XP_RANDSTORM_XP_ENGINE_COUNT * XP_RANDSTORM_XP_GROUP_COUNT;
static constexpr uint64_t XP_RANDSTORM_XP_ENGINE_MASK = (1ull << XP_RANDSTORM_XP_ENGINE_COUNT) - 1ull;
static constexpr uint64_t XP_RANDSTORM_XP_JSBN_HILO_PROFILE_MASK = XP_RANDSTORM_XP_ENGINE_MASK;
