static bool xp_phpcoinaddress_mask_from_token(const std::string& token_raw, uint64_t& mask, uint32_t& count, std::string& err)
{
    std::string token = wallet_lower_copy(wallet_trim_copy(token_raw));
    const char* prefix = "phpcoinaddress:";
    const size_t prefix_len = std::strlen(prefix);
    if (token.rfind(prefix, 0) == 0) {
        token.erase(0, prefix_len);
    }
    if (token == "phpcoinaddress" || token.empty() || token == "all") {
        mask = XP_PHPCOINADDRESS_ALL_VARIANT_MASK;
        count = xp_count_mask_bits(mask, XP_PHPCOINADDRESS_VARIANT_COUNT);
        return true;
    }
    if (token == "php521") {
        mask = 1ull << 0u;
        count = 1u;
        return true;
    }
    if (token == "php710") {
        mask = 1ull << 1u;
        count = 1u;
        return true;
    }
    if (token == "phplegacy") {
        mask = 1ull << 2u;
        count = 1u;
        return true;
    }
    err = "unknown PHPCoinAddress variant; use phpcoinaddress[:all|php521|php710|phplegacy]";
    return false;
}

