static bool xp_bluewallet_isaac_mask_from_token(const std::string& token_raw, uint64_t& mask, uint32_t& count, std::string& err)
{
    std::string token = wallet_lower_copy(wallet_trim_copy(token_raw));
    const char* prefix = "bluewallet-isaac:";
    const size_t prefix_len = std::strlen(prefix);
    if (token.rfind(prefix, 0) == 0) {
        token.erase(0, prefix_len);
    }
    if (token == "bluewallet-isaac" || token.empty() || token == "all") {
        mask = XP_BLUEWALLET_ISAAC_ALL_VARIANT_MASK;
        count = xp_count_mask_bits(mask, XP_BLUEWALLET_ISAAC_VARIANT_COUNT);
        return true;
    }
    if (token == "v0" || token == "v0-cap255" || token == "cap255" || token == "255") {
        mask = 1ull << 0u;
        count = 1u;
        return true;
    }
    if (token == "v2" || token == "v2-cap256" || token == "v3" || token == "cap256" || token == "256") {
        mask = 1ull << 1u;
        count = 1u;
        return true;
    }
    if (token == "hd-v3") {
        err = "bluewallet-isaac:hd-v3 is a BIP39 entropy subprofile; use it as -xp bluewallet-isaac:hd-v3, not -v hd-v3";
        return false;
    }
    err = "unknown BlueWallet ISAAC variant; use bluewallet-isaac[:all|v0-cap255|v2-cap256|hd-v3]";
    return false;
}

