static bool xp_randstorm_mwc32_mask_from_token(const std::string& token_raw, uint64_t& mask, uint32_t& count, std::string& err)
{
    std::string token = wallet_lower_copy(wallet_trim_copy(token_raw));
    if (token.rfind("xp-", 0) == 0) token.erase(0, 3);
    const char* prefixes[] = {
        "randstorm-mwc32:", "randstorm-mwc32-", "randstorm-state0:", "randstorm-state0-",
        "randstorm-mwc-state0:", "randstorm-mwc-state0-", "mwc1616-state0:", "mwc1616-state0-"
    };
    for (const char* prefix : prefixes) {
        const size_t len = std::strlen(prefix);
        if (token.rfind(prefix, 0) == 0) {
            token.erase(0, len);
            break;
        }
    }
