    };
    for (const auto& n : exact_names) {
        if (token == n.name) {
            mask = 1ull << n.profile;
            count = 1u;
            return true;
        }
        const std::string exact_name(n.name);
        if (token == exact_name + "-byte8" || token == exact_name + "-high8" ||
            token == exact_name + "-high-byte" || token == "byte8-" + exact_name ||
            token == "high8-" + exact_name || token == "high-byte-" + exact_name) {
            mask = 1ull << n.profile;
            count = 1u;
