        }
        if (token == exact_name + "-low8" || token == exact_name + "-low-byte" ||
            token == exact_name + "-low8-byte8" || token == exact_name + "-low-byte-byte8" ||
            token == exact_name + "-byte8-low8" || token == exact_name + "-byte8-low-byte" ||
            token == "low8-" + exact_name || token == "low-byte-" + exact_name ||
