static bool xp_randstorm_v8init_pool32_mask_from_token(const std::string& token_raw, uint64_t& mask, uint32_t& count, std::string& err)
{
    std::string token = wallet_lower_copy(wallet_trim_copy(token_raw));
    if (token.rfind("xp-", 0) == 0) token.erase(0, 3);
    const char* prefixes[] = {
        "randstorm-v8init-pool32:", "randstorm-v8init-pool32-",
        "randstorm:v8init-pool32:", "randstorm:v8init-pool32-",
        "v8init-pool32:", "v8init-pool32-",
        "pool32-v8init:", "pool32-v8init-"
    };
    bool stripped = false;
    for (const char* prefix : prefixes) {
        const size_t len = std::strlen(prefix);
        if (token.rfind(prefix, 0) == 0) {
            token.erase(0, len);
            stripped = true;
            break;
        }
    }
    if (!stripped) {
        if (token == "randstorm-v8init-pool32" || token == "randstorm:v8init-pool32" ||
            token == "v8init-pool32" || token == "pool32-v8init") {
            token = "all";
        }
    }
    if (token.empty()) token = "all";
    if (!xp_randstorm_v8init_mask_from_token(std::string("randstorm-v8init:") + token, mask, count, err)) {
        err = "unknown Randstorm V8-init pool32 profile; use randstorm-v8init-pool32[:all|hilo|lohi|msvc|ansi|lrand48|glibc|v8-2011|v8-2015|v8-alt-mwc|v8-mwc1616]";
        return false;
    }
    return true;
}

