            const uint64_t jsbn_mask = n.engine_mask | (n.engine_mask << (XP_RANDSTORM_XP_ENGINE_COUNT * 2u));
            const uint64_t raw32_mask = (n.engine_mask << XP_RANDSTORM_XP_ENGINE_COUNT) |
                (n.engine_mask << (XP_RANDSTORM_XP_ENGINE_COUNT * 3u)) |
                (n.engine_mask << (XP_RANDSTORM_XP_ENGINE_COUNT * 4u)) |
                (n.engine_mask << (XP_RANDSTORM_XP_ENGINE_COUNT * 5u)) |
                (n.engine_mask << (XP_RANDSTORM_XP_ENGINE_COUNT * 6u)) |
                (n.engine_mask << (XP_RANDSTORM_XP_ENGINE_COUNT * 7u));
            mask = force_jsbn ? jsbn_mask : (force_raw32 ? raw32_mask : (jsbn_mask | raw32_mask));
            count = xp_count_mask_bits(mask, XP_RANDSTORM_XP_PROFILE_COUNT);
            return true;
        }
    }
    struct CanonicalRandstormProfile { const char* engine; uint32_t engine_id; };
    static const CanonicalRandstormProfile canonical_profiles[] = {
        {"v8-2011", 0u}, {"v8-2015", 1u}, {"spidermonkey-lcg48", 2u}, {"jsc-weakrandom", 3u},
        {"v8-classic-mwc", 4u}, {"v8-alt-mwc", 5u}, {"v8-mwc1616", 6u}, {"lcg32", 7u}
    };
    struct CanonicalRandstormGroup { const char* suffix; uint32_t group_id; };
    static const CanonicalRandstormGroup canonical_groups[] = {
        {"-jsbn", 0u}, {"-raw32", 1u}, {"-jsbn-lohi", 2u}, {"-raw32-lohi", 3u},
        {"-pool32", 4u}, {"-pool32-lohi", 5u}, {"-raw32-drop1", 6u}, {"-raw32-drop1-lohi", 7u}
    };
    for (const auto& e : canonical_profiles) {
        const std::string prefix(e.engine);
        if (token.rfind(prefix, 0) != 0) continue;
        const std::string suffix = token.substr(prefix.size());
        for (const auto& g : canonical_groups) {
            if (suffix == g.suffix) {
                const uint32_t profile = g.group_id * XP_RANDSTORM_XP_ENGINE_COUNT + e.engine_id;
                mask = 1ull << profile;
                count = 1u;
                return true;
            }
        }
    }
    if (token.rfind("pool32-", 0) == 0) {
        const std::string rest = token.substr(7);
        for (const auto& e : canonical_profiles) {
            const std::string engine(e.engine);
            uint32_t group_id = UINT32_MAX;
            if (rest == engine) {
                group_id = 4u;
            }
            else if (rest == engine + "-lohi") {
                group_id = 5u;
            }
            if (group_id != UINT32_MAX) {
                const uint32_t profile = group_id * XP_RANDSTORM_XP_ENGINE_COUNT + e.engine_id;
                mask = 1ull << profile;
                count = 1u;
                return true;
            }
        }
    }
    struct ExactNameMap { const char* name; uint32_t profile; };
    static const ExactNameMap exact_names[] = {
        {"v8-2011-jsbn", 0u}, {"v8-2015-jsbn", 1u}, {"spidermonkey-lcg48-jsbn", 2u}, {"jsc-weakrandom-jsbn", 3u},
        {"v8-classic-mwc-jsbn", 4u}, {"v8-alt-mwc-jsbn", 5u}, {"v8-mwc1616-jsbn", 6u},
        {"v8-2011-raw32", 8u}, {"v8-2015-raw32", 9u}, {"spidermonkey-lcg48-raw32", 10u}, {"jsc-weakrandom-raw32", 11u},
        {"v8-classic-mwc-raw32", 12u}, {"v8-alt-mwc-raw32", 13u}, {"v8-mwc1616-raw32", 14u}, {"lcg32-raw32", 15u},
        {"v8-2011-jsbn-lohi", 16u}, {"v8-2015-jsbn-lohi", 17u}, {"spidermonkey-lcg48-jsbn-lohi", 18u}, {"jsc-weakrandom-jsbn-lohi", 19u},
        {"v8-classic-mwc-jsbn-lohi", 20u}, {"v8-alt-mwc-jsbn-lohi", 21u}, {"v8-mwc1616-jsbn-lohi", 22u}, {"lcg32-jsbn-lohi", 23u},
        {"v8-2011-raw32-lohi", 24u}, {"v8-2015-raw32-lohi", 25u}, {"spidermonkey-lcg48-raw32-lohi", 26u}, {"jsc-weakrandom-raw32-lohi", 27u},
        {"v8-classic-mwc-raw32-lohi", 28u}, {"v8-alt-mwc-raw32-lohi", 29u}, {"v8-mwc1616-raw32-lohi", 30u}, {"lcg32-raw32-lohi", 31u},
        {"pool32-v8-2011", 32u}, {"pool32-v8-2015", 33u}, {"pool32-spidermonkey-lcg48", 34u}, {"pool32-jsc-weakrandom", 35u},
        {"pool32-v8-classic-mwc", 36u}, {"pool32-v8-alt-mwc", 37u}, {"pool32-v8-mwc1616", 38u}, {"pool32-lcg32", 39u},
        {"pool32-v8-2011-lohi", 40u}, {"pool32-v8-2015-lohi", 41u}, {"pool32-spidermonkey-lcg48-lohi", 42u}, {"pool32-jsc-weakrandom-lohi", 43u},
        {"pool32-v8-classic-mwc-lohi", 44u}, {"pool32-v8-alt-mwc-lohi", 45u}, {"pool32-v8-mwc1616-lohi", 46u}, {"pool32-lcg32-lohi", 47u}
    };
    for (const auto& n : exact_names) {
        if (token == n.name) {
            mask = 1ull << n.profile;
            count = 1u;
            return true;
        }
    }
    err = "unknown Randstorm profile; use randstorm[:all|jsbn|raw32|pool32|v8-2011|v8-2015|spidermonkey-lcg48|jsc-weakrandom|v8-classic-mwc|v8-alt-mwc|v8-mwc1616]";
    return false;
}

static bool xp_configure_profile_from_cli(std::string& err) {
    std::string p = wallet_lower_copy(wallet_trim_copy(xp_profile_arg));
    if (p.empty() || p == "xp") {
        err = "-xp requires an explicit profile: cgr-state/cgr-bridge/cgr-chain/cgr-chain-bridge/ssleay-stir/raw32; use openssl:all only for legacy experimental scan";
        return false;
    }
    if (p == "cgr-full" || p == "xp-cgr-full") {
        err = "cgr-full is recognized but not implemented: upstream seedbase_after -> state20 mapping is not closed";
        return false;
    }
    if (xp_b4q_duplicate_or_unclosed_profile_error(p, err)) {
        return false;
    }
    if (p == "cgr-state" || p == "xp-cgr-state") {
        xp_profile_kind = XP_PROFILE_CGR_STATE;
        xp_path_mask = 0u;
        xp_path_count = 0u;
        if (xp_path_override_explicit) {
            err = "-v/OpenSSL path restriction is not valid with cgr-state";
            return false;
        }
        return true;
    }
    if (p == "cgr-bridge" || p == "xp-cgr-bridge") {
        xp_profile_kind = XP_PROFILE_CGR_BRIDGE;
        xp_path_mask = 0u;
        xp_path_count = 0u;
        if (xp_path_override_explicit) {
            err = "-v/OpenSSL path restriction is not valid with cgr-bridge";
            return false;
        }
        return true;
    }
    if (p == "cgr-xor" || p == "provider-xor" || p == "xp-cgr-xor") {
        xp_profile_kind = XP_PROFILE_CGR_XOR;
        xp_path_mask = 0u;
        xp_path_count = 0u;
        if (xp_path_override_explicit) {
            err = "-v/OpenSSL path restriction is not valid with cgr-xor";
            return false;
        }
        return true;
    }
    if (p == "cgr-chain" || p == "provider-chain" || p == "xp-cgr-chain") {
