            return false;
        }
        return true;
    }
    if (p == "cgr-chain-bridge" || p == "provider-chain-bridge" || p == "xp-cgr-chain-bridge" || p == "v29") {
        xp_profile_kind = XP_PROFILE_CGR_CHAIN_BRIDGE;
        xp_path_mask = 0u;
        xp_path_count = 0u;
        if (xp_path_override_explicit) {
            err = "-v/OpenSSL path restriction is not valid with cgr-chain-bridge";
            return false;
        }
        return true;
    }
    if (p == "ssleay" || p == "ssleay-stir" || p == "openssl-ssleay" || p == "xp-ssleay") {
