        if (xp_path_override_explicit) {
            err = "-v/OpenSSL path restriction is not valid with raw32";
            return false;
        }
        return true;
    }
    if (p == "randstorm-prng64" || p == "randstorm64" || p == "xp-randstorm-prng64") {
        err = "randstorm-prng64 is disabled in -xp: external gen/mode/bytes rows are not a source-grounded historical replay";
