        if (xp_path_override_explicit) {
            uint64_t override_mask = 0u;
            uint32_t override_count = 0u;
            if (!xp_bluewallet_isaac_mask_from_token(xp_path_override_value, override_mask, override_count, err)) {
                err = std::string("invalid -v value: ") + err;
