            }
            xp_path_mask &= override_mask;
            xp_path_count = xp_count_mask_bits(xp_path_mask, XP_BLUEWALLET_ISAAC_VARIANT_COUNT);
            if (xp_path_mask == 0u || xp_path_count == 0u) {
