            xp_path_mask &= override_mask;
            xp_path_count = xp_count_mask_bits(xp_path_mask, XP_LOWBITS_DIRECT_VARIANT_COUNT);
            if (xp_path_mask == 0u || xp_path_count == 0u) {
                err = "-v lowbits-direct restriction does not intersect selected variants";
                return false;
            }
        }
        return true;
    }
    if (p == "pybtc-mt" || p.rfind("pybtc-mt:", 0) == 0) {
        xp_profile_kind = XP_PROFILE_PYBTC_MT;
        // Detect time-sweep sub-alias (:ts / :nots) and variant sub-alias.
        // Supported formats: pybtc-mt[:ts|:nots][:random-key|:electrum-seed]
        std::string pv = wallet_lower_copy(p);
        const std::string ts_tag = ":ts";
        const std::string nots_tag = ":nots";
        const std::string rkey_tag = ":random-key";
        const std::string rkey2_tag = ":random_key";
        const std::string eseed_tag = ":electrum-seed";
        const std::string eseed2_tag = ":electrum_seed";
        bool ts_seen = false;
        // Save variant token BEFORE stripping it from pv.
        bool variant_stripped = false;
        std::string variant_token;
        if (pv.length() >= rkey_tag.length() && pv.compare(pv.length() - rkey_tag.length(), rkey_tag.length(), rkey_tag) == 0) {
            variant_stripped = true;
            variant_token = "pybtc-mt:random-key";
            pv.erase(pv.length() - rkey_tag.length(), rkey_tag.length());
        }
        else if (pv.length() >= rkey2_tag.length() && pv.compare(pv.length() - rkey2_tag.length(), rkey2_tag.length(), rkey2_tag) == 0) {
            variant_stripped = true;
            variant_token = "pybtc-mt:random-key";
            pv.erase(pv.length() - rkey2_tag.length(), rkey2_tag.length());
        }
        else if (pv.length() >= eseed_tag.length() && pv.compare(pv.length() - eseed_tag.length(), eseed_tag.length(), eseed_tag) == 0) {
            variant_stripped = true;
            variant_token = "pybtc-mt:electrum-seed";
            pv.erase(pv.length() - eseed_tag.length(), eseed_tag.length());
        }
        else if (pv.length() >= eseed2_tag.length() && pv.compare(pv.length() - eseed2_tag.length(), eseed2_tag.length(), eseed2_tag) == 0) {
            variant_stripped = true;
            variant_token = "pybtc-mt:electrum-seed";
            pv.erase(pv.length() - eseed2_tag.length(), eseed2_tag.length());
        }
        // Now strip time tag (if present at end).
        if (pv.length() >= ts_tag.length() && pv.compare(pv.length() - ts_tag.length(), ts_tag.length(), ts_tag) == 0) {
            ts_seen = true;
            pv.erase(pv.length() - ts_tag.length(), ts_tag.length());
        }
        else if (pv.length() >= nots_tag.length() && pv.compare(pv.length() - nots_tag.length(), nots_tag.length(), nots_tag) == 0) {
            pv.erase(pv.length() - nots_tag.length(), nots_tag.length());
        }
        xp_pybtc_mt_time_mode = ts_seen;
        // pv is now "pybtc-mt"; use variant_token if one was stripped, else use pv.
        std::string token_for_mask = variant_stripped ? variant_token : pv;
        if (!xp_pybtc_mt_mask_from_token(token_for_mask, xp_path_mask, xp_path_count, err)) {
            return false;
        }
        if (xp_path_override_explicit) {
            uint64_t override_mask = 0u;
            uint32_t override_count = 0u;
            if (!xp_pybtc_mt_mask_from_token(xp_path_override_value, override_mask, override_count, err)) {
                err = std::string("invalid -v value: ") + err;
                return false;
            }
            xp_path_mask &= override_mask;
            xp_path_count = xp_count_mask_bits(xp_path_mask, XP_PYBTC_MT_VARIANT_COUNT);
            if (xp_path_mask == 0u || xp_path_count == 0u) {
                err = "-v pybtc-mt restriction does not intersect selected variants";
                return false;
            }
        }
        return true;
    }
