    if (p == "elliptic-php-rand-hmacdrbg" || p.rfind("elliptic-php-rand-hmacdrbg:", 0) == 0) {
        xp_profile_kind = XP_PROFILE_ELLIPTIC_PHP_RAND_HMACDRBG;
