    if (p == "randstorm-pymt" || p == "xp-randstorm-pymt" || p == "randstorm-python" ||
        p == "randstormbtc" || p == "randstorm-btc" || p == "python-mt-randint8" ||
        p == "python-mt-randrange8" || p == "python-mt-randrange256" ||
