static bool wallet_parse_keystore_v3_text(const std::string& json,
    const std::string& source,
    WalletKeystoreHostTarget& out,
    std::string& err)
{
    std::string cipher, kdf, prf, salt_hex, iv_hex, ciphertext_hex, mac_hex, address_hex;
    if (!wallet_json_get_string(json, "cipher", cipher) ||
        !wallet_json_get_string(json, "kdf", kdf) ||
        !wallet_json_get_string(json, "salt", salt_hex) ||
        !wallet_json_get_string(json, "iv", iv_hex) ||
        !wallet_json_get_string(json, "ciphertext", ciphertext_hex) ||
        !wallet_json_get_string(json, "mac", mac_hex)) {
        err = "missing required Ethereum JSON V3 fields";
        return false;
    }
    const bool has_address = wallet_json_get_string(json, "address", address_hex);

    cipher = wallet_lower_copy(cipher);
    kdf = wallet_lower_copy(kdf);
    if (cipher != "aes-128-ctr") {
        err = "unsupported cipher '" + cipher + "'";
        return false;
    }

    WalletKeystoreTarget t{};
    if (kdf == "pbkdf2") {
        if (wallet_json_get_string(json, "prf", prf)) {
            prf = wallet_lower_copy(prf);
            if (prf != "hmac-sha256") {
                err = "unsupported pbkdf2 prf '" + prf + "'";
                return false;
            }
        }
        uint32_t c = 0, dklen = 0;
        if (!wallet_json_get_u32(json, "c", c) || !wallet_json_get_u32(json, "dklen", dklen)) {
            err = "missing pbkdf2 c/dklen";
            return false;
        }
        if (c == 0 || dklen < 32) {
            err = "invalid pbkdf2 c/dklen";
            return false;
        }
        t.kdf_type = WALLET_KDF_PBKDF2_SHA256;
        t.iterations = c;
        t.dklen = dklen;
    }
    else if (kdf == "scrypt") {
        uint32_t n = 0, r = 0, p = 0, dklen = 0;
        if (!wallet_json_get_u32(json, "n", n) ||
            !wallet_json_get_u32(json, "r", r) ||
            !wallet_json_get_u32(json, "p", p) ||
            !wallet_json_get_u32(json, "dklen", dklen)) {
            err = "missing scrypt n/r/p/dklen";
            return false;
        }
        if (n < 2 || (n & (n - 1u)) != 0u || r == 0 || p == 0 || dklen < 32) {
            err = "invalid scrypt n/r/p/dklen";
            return false;
        }
        if (r > 8) {
            err = "scrypt worker currently supports r<=8";
            return false;
        }
        const uint64_t scrypt_block_bytes = 128ull * static_cast<uint64_t>(r) * static_cast<uint64_t>(p);
        if (scrypt_block_bytes == 0ull || scrypt_block_bytes > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max() - 4u)) {
            err = "scrypt p*r memory span is too large";
            return false;
        }
        t.kdf_type = WALLET_KDF_SCRYPT;
        t.dklen = dklen;
        t.scrypt_n = n;
        t.scrypt_r = r;
        t.scrypt_p = p;
    }
    else {
        err = "unsupported kdf '" + kdf + "'";
        return false;
    }

    std::vector<uint8_t> salt_vec, cipher_vec;
    if (!wallet_hex_to_bytes(salt_hex, salt_vec, err)) return false;
    if (salt_vec.empty() || salt_vec.size() > WALLET_MAX_SALT_LEN) {
        err = "salt length is unsupported";
        return false;
    }
    if (!wallet_hex_to_bytes(ciphertext_hex, cipher_vec, err)) return false;
    if (cipher_vec.empty() || cipher_vec.size() > WALLET_MAX_CIPHERTEXT_LEN) {
        err = "ciphertext length is unsupported";
        return false;
    }
    if (!wallet_hex_to_fixed(iv_hex, t.iv, 16, err)) return false;
    if (!wallet_hex_to_fixed(mac_hex, t.mac, 32, err)) return false;
    if (has_address) {
        if (!wallet_hex_to_fixed(address_hex, t.address, 20, err)) return false;
        t.has_address = 1u;
    }
    else {
        memset(t.address, 0, sizeof(t.address));
        t.has_address = 0u;
    }
    t.salt_len = static_cast<uint32_t>(salt_vec.size());
    t.ciphertext_len = static_cast<uint32_t>(cipher_vec.size());
    memcpy(t.salt, salt_vec.data(), salt_vec.size());
    memcpy(t.ciphertext, cipher_vec.data(), cipher_vec.size());
    {
        std::vector<uint8_t> hash_input;
        hash_input.reserve(cipher_vec.size() + salt_vec.size() + 64u);
        hash_input.insert(hash_input.end(), cipher_vec.begin(), cipher_vec.end());
        hash_input.push_back('|');
        hash_input.insert(hash_input.end(), t.iv, t.iv + 16);
        hash_input.push_back('|');
        hash_input.insert(hash_input.end(), salt_vec.begin(), salt_vec.end());
        hash_input.push_back('|');
        hash_input.push_back(static_cast<uint8_t>(t.kdf_type));
        hash_input.push_back(static_cast<uint8_t>(t.iterations & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.iterations >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.iterations >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.iterations >> 24) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>(t.scrypt_n & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_n >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_n >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_n >> 24) & 0xffu));
        sha256(hash_input.data(), hash_input.size(), t.vault_hash);
    }

    out.dev = t;
    out.file = source;
    return true;
}

static bool wallet_json_object_end_from(const std::string& text, const size_t begin, size_t& end)
{
    if (begin >= text.size() || text[begin] != '{') {
        return false;
    }
    bool in_string = false;
    bool escape = false;
    uint32_t depth = 0u;
    for (size_t i = begin; i < text.size(); ++i) {
        const char c = text[i];
        if (in_string) {
            if (escape) {
                escape = false;
            }
            else if (c == '\\') {
                escape = true;
            }
            else if (c == '"') {
                in_string = false;
            }
            continue;
        }
        if (c == '"') {
            in_string = true;
        }
        else if (c == '{') {
            ++depth;
        }
        else if (c == '}') {
            if (depth == 0u) {
                return false;
            }
            --depth;
            if (depth == 0u) {
                end = i + 1u;
                return true;
            }
        }
    }
    return false;
}

static void wallet_collect_keystore_json_fragments(
    const std::string& text,
    std::vector<std::string>& fragments)
{
    const char* needles[] = { "\"crypto\"", "\"Crypto\"", "\"ciphertext\"" };
    std::unordered_set<std::string> seen;
    auto add_fragment = [&](const size_t begin, const size_t len) {
        if (begin >= text.size() || len == 0u) {
            return;
        }
        const size_t safe_len = std::min<size_t>(len, text.size() - begin);
        if (safe_len == 0u || safe_len > 65536u) {
            return;
        }
        std::string fragment = text.substr(begin, safe_len);
        if (seen.insert(fragment).second) {
            fragments.emplace_back(std::move(fragment));
        }
    };

    for (const char* needle : needles) {
        size_t p = 0u;
        while ((p = text.find(needle, p)) != std::string::npos) {
            size_t scan = p;
            uint32_t attempts = 0u;
            while (attempts < 96u) {
                const size_t brace = text.rfind('{', scan);
                if (brace == std::string::npos || p - brace > 4096u) {
                    break;
                }
                size_t end = 0u;
                if (wallet_json_object_end_from(text, brace, end) && end > p) {
                    add_fragment(brace, end - brace);
                }
                if (brace == 0u) {
                    break;
                }
                scan = brace - 1u;
                ++attempts;
            }

            const size_t begin = (p > 256u) ? (p - 256u) : 0u;
            add_fragment(begin, std::min<size_t>(text.size() - begin, 32768u));
            p += strlen(needle);
        }
    }
}

static size_t wallet_parse_keystore_v3_file_targets(const std::string& path,
    std::vector<WalletKeystoreHostTarget>& out,
    std::string& err)
{
    std::string json;
    if (!mac_read_text_file(path, json, err)) {
        return 0u;
    }

    std::unordered_set<std::string> seen;
    auto add_target = [&](WalletKeystoreHostTarget&& target) {
        const WalletKeystoreTarget& t = target.dev;
        std::string key;
        key.reserve(1u + WALLET_MAX_SALT_LEN + WALLET_MAX_CIPHERTEXT_LEN + 64u);
        key.push_back(static_cast<char>(t.kdf_type));
        const uint32_t params[] = {
            t.iterations,
            t.dklen,
            t.scrypt_n,
            t.scrypt_r,
            t.scrypt_p,
            t.salt_len,
            t.ciphertext_len
        };
        key.append(reinterpret_cast<const char*>(params), reinterpret_cast<const char*>(params) + sizeof(params));
        key.append(reinterpret_cast<const char*>(t.salt), reinterpret_cast<const char*>(t.salt) + std::min<uint32_t>(t.salt_len, WALLET_MAX_SALT_LEN));
        key.append(reinterpret_cast<const char*>(t.iv), reinterpret_cast<const char*>(t.iv) + sizeof(t.iv));
        key.append(reinterpret_cast<const char*>(t.ciphertext), reinterpret_cast<const char*>(t.ciphertext) + std::min<uint32_t>(t.ciphertext_len, WALLET_MAX_CIPHERTEXT_LEN));
        key.append(reinterpret_cast<const char*>(t.mac), reinterpret_cast<const char*>(t.mac) + sizeof(t.mac));
        if (seen.insert(std::move(key)).second) {
            out.emplace_back(std::move(target));
        }
    };

    std::vector<WalletKeystoreHostTarget> ethereum_hash_targets;
    std::string ethereum_hash_err;
    wallet_parse_ethereum_hash_lines_text(json, path, ethereum_hash_targets, ethereum_hash_err);
    for (WalletKeystoreHostTarget& target : ethereum_hash_targets) {
        add_target(std::move(target));
    }

    WalletKeystoreHostTarget full_target;
    std::string full_err;
    if (wallet_parse_keystore_v3_text(json, path, full_target, full_err)) {
        add_target(std::move(full_target));
    }

    std::vector<std::string> fragments;
    wallet_collect_keystore_json_fragments(json, fragments);
    std::string last_err = full_err;
    for (const std::string& fragment : fragments) {
        WalletKeystoreHostTarget target;
        std::string fragment_err;
        if (wallet_parse_keystore_v3_text(fragment, path, target, fragment_err)) {
            add_target(std::move(target));
        }
        else if (!fragment_err.empty()) {
            last_err = fragment_err;
        }
    }

    std::vector<std::string> leveldb_values;
    std::string leveldb_err;
    if (wallet_extract_leveldb_table_values(path, leveldb_values, leveldb_err)) {
        for (const std::string& value : leveldb_values) {
            WalletKeystoreHostTarget target;
            std::string value_err;
            if (wallet_parse_keystore_v3_text(value, path, target, value_err)) {
                add_target(std::move(target));
                continue;
            }
            std::vector<std::string> value_fragments;
            wallet_collect_keystore_json_fragments(value, value_fragments);
            for (const std::string& fragment : value_fragments) {
                WalletKeystoreHostTarget fragment_target;
                std::string fragment_err;
                if (wallet_parse_keystore_v3_text(fragment, path, fragment_target, fragment_err)) {
                    add_target(std::move(fragment_target));
                }
                else if (!fragment_err.empty()) {
                    last_err = fragment_err;
                }
            }
        }
    }
    else if (!leveldb_err.empty() && leveldb_err != "not a LevelDB table") {
        last_err = leveldb_err;
    }

    std::vector<std::string> leveldb_log_values;
    std::string leveldb_log_err;
    if (wallet_extract_leveldb_log_values(path, leveldb_log_values, leveldb_log_err)) {
        for (const std::string& value : leveldb_log_values) {
            WalletKeystoreHostTarget target;
            std::string value_err;
            if (wallet_parse_keystore_v3_text(value, path, target, value_err)) {
                add_target(std::move(target));
                continue;
            }
            std::vector<std::string> value_fragments;
            wallet_collect_keystore_json_fragments(value, value_fragments);
            for (const std::string& fragment : value_fragments) {
                WalletKeystoreHostTarget fragment_target;
                std::string fragment_err;
                if (wallet_parse_keystore_v3_text(fragment, path, fragment_target, fragment_err)) {
                    add_target(std::move(fragment_target));
                }
                else if (!fragment_err.empty()) {
                    last_err = fragment_err;
                }
            }
        }
    }
    else if (!leveldb_log_err.empty() &&
        leveldb_log_err != "not a LevelDB WAL" &&
        leveldb_log_err != "no useful LevelDB WAL values") {
        last_err = leveldb_log_err;
    }

    if (out.empty()) {
        if (!ethereum_hash_err.empty()) {
            err = ethereum_hash_err;
        }
        else {
            err = last_err.empty() ? "missing required Ethereum JSON V3 fields" : last_err;
        }
    }
    return out.size();
}

static std::string wallet_unescape_embedded_json_copy(std::string s) {
    std::string out;
    out.reserve(s.size());
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1u < s.size()) {
            const char n = s[i + 1u];
            if (n == '"' || n == '\\' || n == '/') {
                out.push_back(n);
                ++i;
                continue;
            }
        }
        out.push_back(s[i]);
    }
    return out;
}

static std::string wallet_browser_vault_key(const std::vector<uint8_t>& data,
    const std::vector<uint8_t>& iv,
    const std::vector<uint8_t>& salt,
    uint32_t iterations,
    uint32_t profile)
{
    std::string key;
    key.reserve(data.size() + iv.size() + salt.size() + 16u);
    key.push_back(static_cast<char>(profile & 0xffu));
    key.push_back(static_cast<char>((profile >> 8) & 0xffu));
    key.push_back(static_cast<char>((profile >> 16) & 0xffu));
    key.push_back(static_cast<char>((profile >> 24) & 0xffu));
    key.push_back('|');
    key.append(reinterpret_cast<const char*>(data.data()), data.size());
    key.push_back('|');
    key.append(reinterpret_cast<const char*>(iv.data()), iv.size());
    key.push_back('|');
    key.append(reinterpret_cast<const char*>(salt.data()), salt.size());
    key.push_back('|');
    key.push_back(static_cast<char>(iterations & 0xffu));
    key.push_back(static_cast<char>((iterations >> 8) & 0xffu));
    key.push_back(static_cast<char>((iterations >> 16) & 0xffu));
    key.push_back(static_cast<char>((iterations >> 24) & 0xffu));
    return key;
}

static void wallet_browser_vault_hash(const std::vector<uint8_t>& data,
    const std::vector<uint8_t>& iv,
    const std::vector<uint8_t>& salt,
    uint32_t iterations,
    uint32_t profile,
    uint8_t out32[32])
{
    std::vector<uint8_t> buf;
    buf.reserve(data.size() + iv.size() + salt.size() + 16u);
    buf.push_back(static_cast<uint8_t>(profile & 0xffu));
    buf.push_back(static_cast<uint8_t>((profile >> 8) & 0xffu));
    buf.push_back(static_cast<uint8_t>((profile >> 16) & 0xffu));
    buf.push_back(static_cast<uint8_t>((profile >> 24) & 0xffu));
    buf.push_back('|');
    buf.insert(buf.end(), data.begin(), data.end());
    buf.push_back('|');
    buf.insert(buf.end(), iv.begin(), iv.end());
    buf.push_back('|');
    buf.insert(buf.end(), salt.begin(), salt.end());
    buf.push_back('|');
    buf.push_back(static_cast<uint8_t>(iterations & 0xffu));
    buf.push_back(static_cast<uint8_t>((iterations >> 8) & 0xffu));
    buf.push_back(static_cast<uint8_t>((iterations >> 16) & 0xffu));
    buf.push_back(static_cast<uint8_t>((iterations >> 24) & 0xffu));
    sha256(buf.data(), buf.size(), out32);
}

static bool wallet_add_browser_vault_target(
    const std::string& path,
    uint32_t profile,
    const std::vector<uint8_t>& data,
    const std::vector<uint8_t>& iv,
    const std::vector<uint8_t>& salt,
    uint32_t iterations,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen)
{
    const bool aes_gcm_profile =
        profile == BROWSERVAULT_PROFILE_METAMASK_AES_GCM ||
        profile == BROWSERVAULT_PROFILE_STELLAR_AES_GCM;
    const bool blockchain_profile =
        profile == BROWSERVAULT_PROFILE_BLOCKCHAIN_V2_PBKDF2_AES_CBC;
    const bool dogechain_profile =
        profile == BROWSERVAULT_PROFILE_DOGECHAIN_PBKDF2_AES_CBC;
    const bool android_backup_profile =
        profile == BROWSERVAULT_PROFILE_ANDROID_BACKUP_PBKDF2_SHA1_AES_CBC;
    if (profile == BROWSERVAULT_PROFILE_ATOMIC_CRYPTOJS_AES) {
        if (data.size() <= 32u ||
            memcmp(data.data(), "Salted__", 8u) != 0 ||
            ((data.size() - 16u) & 15u) != 0u ||
            data.size() - 16u > BROWSERVAULT_MAX_BLOB_LEN) {
            return false;
        }
    }
    else if (aes_gcm_profile) {
        if (data.size() <= 16u || data.size() - 16u > BROWSERVAULT_MAX_BLOB_LEN ||
            iv.empty() || iv.size() > 32u ||
            salt.empty() || salt.size() > WALLET_MAX_SALT_LEN ||
            iterations == 0u) {
            return false;
        }
    }
    else if (blockchain_profile) {
        if (data.size() < 48u || data.size() > BROWSERVAULT_MAX_BLOB_LEN ||
            iv.size() != 16u || salt.size() != 16u ||
            iterations == 0u) {
            return false;
        }
    }
    else if (dogechain_profile) {
        if (data.size() < 48u || data.size() > BROWSERVAULT_MAX_BLOB_LEN ||
            (data.size() & 15u) != 0u ||
            salt.empty() || salt.size() > WALLET_MAX_SALT_LEN ||
            iterations == 0u) {
            return false;
        }
    }
    else if (android_backup_profile) {
        if (data.size() != 16u || iv.size() != 16u ||
            salt.size() != 64u || iterations == 0u) {
            return false;
        }
    }
    else {
        if (data.size() <= 16u || data.size() - 16u > BROWSERVAULT_MAX_BLOB_LEN ||
            iv.size() != 24u ||
            salt.empty() || salt.size() > WALLET_MAX_SALT_LEN) {
            return false;
        }
        if (profile == BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_PBKDF2 && iterations == 0u) {
            return false;
        }
    }

    std::string key = wallet_browser_vault_key(data, iv, salt, iterations, profile);
    if (!seen.insert(std::move(key)).second) {
        return false;
    }

    BrowserVaultHostTarget target;
    target.file = path;
    target.dev.profile = profile;
    target.dev.iterations = iterations;
    if (profile == BROWSERVAULT_PROFILE_ATOMIC_CRYPTOJS_AES) {
        target.dev.iterations = 1u;
        target.dev.salt_len = 8u;
        target.dev.iv_len = 0u;
        memcpy(target.dev.salt, data.data() + 8u, 8u);
        target.dev.ciphertext_len = static_cast<uint32_t>(data.size() - 16u);
        target.ciphertext.assign(data.begin() + 16, data.end());
    }
    else if (aes_gcm_profile) {
        target.dev.salt_len = static_cast<uint32_t>(salt.size());
        target.dev.iv_len = static_cast<uint32_t>(iv.size());
        memcpy(target.dev.salt, salt.data(), salt.size());
        memcpy(target.dev.iv, iv.data(), iv.size());
        target.dev.ciphertext_len = static_cast<uint32_t>(data.size() - 16u);
        target.ciphertext.assign(data.begin(), data.end() - 16);
        memcpy(target.dev.tag, data.data() + data.size() - 16u, 16u);
    }
    else if (blockchain_profile) {
        target.dev.salt_len = 16u;
        target.dev.iv_len = 16u;
        memcpy(target.dev.salt, salt.data(), 16u);
        memcpy(target.dev.iv, iv.data(), 16u);
        target.dev.ciphertext_len = static_cast<uint32_t>(data.size());
        target.ciphertext.assign(data.begin(), data.end());
    }
    else if (dogechain_profile) {
        target.dev.salt_len = static_cast<uint32_t>(salt.size());
        target.dev.iv_len = 16u;
        memcpy(target.dev.salt, salt.data(), salt.size());
        memcpy(target.dev.iv, data.data(), 16u);
        target.dev.ciphertext_len = static_cast<uint32_t>(data.size() - 16u);
        target.ciphertext.assign(data.begin() + 16, data.end());
    }
    else if (android_backup_profile) {
        target.dev.salt_len = 64u;
        target.dev.iv_len = 16u;
        memcpy(target.dev.salt, salt.data(), 64u);
        memcpy(target.dev.iv, iv.data(), 16u);
        target.dev.ciphertext_len = 16u;
        target.ciphertext.assign(data.begin(), data.end());
    }
    else {
        target.dev.salt_len = static_cast<uint32_t>(salt.size());
        target.dev.iv_len = static_cast<uint32_t>(iv.size());
        memcpy(target.dev.salt, salt.data(), salt.size());
        memcpy(target.dev.iv, iv.data(), iv.size());
        target.dev.ciphertext_len = static_cast<uint32_t>(data.size() - 16u);
        memcpy(target.dev.tag, data.data(), 16u);
        target.ciphertext.assign(data.begin() + 16, data.end());
        if (profile == BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_SCRYPT) {
            target.dev.scrypt_n = 4096u;
            target.dev.scrypt_r = 8u;
            target.dev.scrypt_p = 1u;
        }
    }
    wallet_browser_vault_hash(data, iv, salt, iterations, profile, target.dev.vault_hash);
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_is_base64_token_char(const char c)
{
    return std::isalnum(static_cast<unsigned char>(c)) || c == '+' || c == '/' || c == '-' || c == '_' || c == '=';
}

static size_t wallet_collect_atomic_cryptojs_targets(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen)
{
    size_t added = 0u;
    size_t p = 0u;
    while ((p = text.find("U2FsdGVkX1", p)) != std::string::npos) {
        size_t begin = p;
        while (begin > 0u && wallet_is_base64_token_char(text[begin - 1u])) {
            --begin;
        }
        size_t end = p;
        while (end < text.size() && wallet_is_base64_token_char(text[end])) {
            ++end;
        }
        std::string token = text.substr(begin, end - begin);
        while (!token.empty() && token.back() == '=') {
            // keep valid padding, but trim LevelDB-adjacent repeated separators after it.
            break;
        }
        std::vector<uint8_t> raw;
        std::string dec_err;
        if (wallet_base64_to_bytes(token, raw, dec_err) &&
            raw.size() > 32u &&
            memcmp(raw.data(), "Salted__", 8u) == 0 &&
            ((raw.size() - 16u) & 15u) == 0u) {
            const std::vector<uint8_t> empty;
            if (wallet_add_browser_vault_target(path, BROWSERVAULT_PROFILE_ATOMIC_CRYPTOJS_AES,
                raw, empty, empty, 1u, targets, seen)) {
                ++added;
            }
        }
        p = (end > p) ? end : (p + 10u);
    }
    return added;
}

static bool wallet_parse_browservault_text(const std::string& path,
    std::string text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    const bool may_have_metamask = text.find("\"data\"") != std::string::npos || text.find("\\\"data\\\"") != std::string::npos;
    const bool may_have_phantom = text.find("encryptedMnemonic") != std::string::npos || text.find("encryptedKey") != std::string::npos;
    const bool may_have_atomic = text.find("U2FsdGVkX1") != std::string::npos;
    if (!may_have_metamask && !may_have_phantom && !may_have_atomic) {
        err = "no browser vault data field";
        return false;
    }
    text = wallet_unescape_embedded_json_copy(text);
    size_t p = 0u;
    size_t added = 0u;
    added += wallet_collect_atomic_cryptojs_targets(path, text, targets, seen);
    while ((p = text.find("\"data\"", p)) != std::string::npos) {
        std::string data_s, iv_s, salt_s;
        size_t after_data = p;
        if (!wallet_json_get_string_from(text, "data", p, data_s, &after_data)) {
            p += 6u;
            continue;
        }
        const size_t window_begin = p > 2048u ? p - 2048u : 0u;
        if (!wallet_json_get_string_from(text, "iv", window_begin, iv_s) ||
            !wallet_json_get_string_from(text, "salt", window_begin, salt_s)) {
            p = after_data;
            continue;
        }
        uint32_t iterations = 10000u;
        (void)wallet_json_get_u32_from(text, "iterations", window_begin, 8192u, iterations);

        std::vector<uint8_t> data, iv, salt;
        std::string dec_err;
        if (!wallet_base64_or_hex_to_bytes(data_s, data, dec_err) ||
            !wallet_base64_or_hex_to_bytes(iv_s, iv, dec_err) ||
            !wallet_base64_or_hex_to_bytes(salt_s, salt, dec_err)) {
            p = after_data;
            continue;
        }
        if (wallet_add_browser_vault_target(path, BROWSERVAULT_PROFILE_METAMASK_AES_GCM,
            data, iv, salt, iterations, targets, seen)) {
            ++added;
        }
        p = after_data;
    }
    p = 0u;
    while ((p = text.find("\"encrypted\"", p)) != std::string::npos) {
        std::string encrypted_s, nonce_s, salt_s, kdf_s, digest_s;
        size_t after_encrypted = p;
        if (!wallet_json_get_string_from(text, "encrypted", p, encrypted_s, &after_encrypted)) {
            p += 11u;
            continue;
        }
        const size_t window_begin = p > 2048u ? p - 2048u : 0u;
        if (!wallet_json_get_string_from(text, "nonce", window_begin, nonce_s) ||
            !wallet_json_get_string_from(text, "salt", window_begin, salt_s) ||
            !wallet_json_get_string_from(text, "kdf", window_begin, kdf_s)) {
            p = after_encrypted;
            continue;
        }
        uint32_t iterations = 0u;
        (void)wallet_json_get_u32_from(text, "iterations", window_begin, 8192u, iterations);
        if (wallet_json_get_string_from(text, "digest", window_begin, digest_s)) {
            digest_s = wallet_lower_copy(digest_s);
            if (!digest_s.empty() && digest_s != "sha256") {
                p = after_encrypted;
                continue;
            }
        }
        kdf_s = wallet_lower_copy(kdf_s);
        uint32_t profile = 0u;
        if (kdf_s == "pbkdf2") {
            profile = BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_PBKDF2;
            if (iterations == 0u) iterations = 10000u;
        }
        else if (kdf_s == "scrypt") {
            profile = BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_SCRYPT;
        }
        else {
            p = after_encrypted;
            continue;
        }
        std::vector<uint8_t> encrypted, nonce, salt;
        std::string dec_err;
        if (!wallet_base58_to_bytes(encrypted_s, encrypted, dec_err) ||
            !wallet_base58_to_bytes(nonce_s, nonce, dec_err) ||
            !wallet_base58_to_bytes(salt_s, salt, dec_err)) {
            p = after_encrypted;
            continue;
        }
        if (wallet_add_browser_vault_target(path, profile, encrypted, nonce, salt, iterations, targets, seen)) {
            ++added;
        }
        p = after_encrypted;
    }
    if (added == 0u) {
        err = "no usable MetaMask/Phantom browser vault";
        return false;
    }
    return true;
}

static bool wallet_parse_browservault_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }

    const size_t before = targets.size();
    std::string direct_err;
    (void)wallet_parse_browservault_text(path, text, targets, seen, direct_err);

    std::vector<std::string> leveldb_values;
    std::string leveldb_err;
    if (wallet_extract_leveldb_table_values(path, leveldb_values, leveldb_err)) {
        for (std::string& value : leveldb_values) {
            std::string value_err;
            (void)wallet_parse_browservault_text(path, std::move(value), targets, seen, value_err);
        }
    }

    std::vector<std::string> leveldb_log_values;
    std::string leveldb_log_err;
    if (wallet_extract_leveldb_log_values(path, leveldb_log_values, leveldb_log_err)) {
        for (std::string& value : leveldb_log_values) {
            std::string value_err;
            (void)wallet_parse_browservault_text(path, std::move(value), targets, seen, value_err);
        }
    }

    if (targets.size() != before) {
        return true;
    }
    err = !direct_err.empty() ? direct_err :
        (!leveldb_err.empty() && leveldb_err != "not a LevelDB table" ? leveldb_err :
            (!leveldb_log_err.empty() &&
                leveldb_log_err != "not a LevelDB WAL" &&
                leveldb_log_err != "no useful LevelDB WAL values" ? leveldb_log_err :
                "no usable MetaMask/Phantom browser vault"));
    return false;
}

static bool wallet_parse_copaywallet_text(
    const std::string& source,
    const std::string& json,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string iv_b64;
    std::string salt_b64;
    std::string ciphertext_b64;
    std::string mode;
    std::string cipher;
    std::string adata;
    uint32_t version = 0u;
    uint32_t iterations = 0u;
    uint32_t key_size = 0u;
    uint32_t tag_size = 0u;
    if (!wallet_json_get_string(json, "iv", iv_b64) ||
        !wallet_json_get_string(json, "salt", salt_b64) ||
        !wallet_json_get_string(json, "ct", ciphertext_b64) ||
        !wallet_json_get_string(json, "mode", mode) ||
        !wallet_json_get_string(json, "cipher", cipher) ||
        !wallet_json_get_string(json, "adata", adata) ||
        !wallet_json_get_u32(json, "v", version) ||
        !wallet_json_get_u32(json, "iter", iterations) ||
        !wallet_json_get_u32(json, "ks", key_size) ||
        !wallet_json_get_u32(json, "ts", tag_size)) {
        err = "missing required SJCL v1 iv/salt/ct/KDF/cipher fields";
        return false;
    }
    mode = wallet_lower_copy(mode);
    cipher = wallet_lower_copy(cipher);
    if (version != 1u || iterations == 0u || key_size != 128u ||
        tag_size != 64u || mode != "ccm" || cipher != "aes" ||
        !adata.empty()) {
        err = "unsupported SJCL profile (requires v1, AES-128-CCM, 64-bit tag, empty adata)";
        return false;
    }

    std::vector<uint8_t> iv;
    std::vector<uint8_t> salt;
    std::vector<uint8_t> encrypted_and_tag;
    std::string decode_error;
    if (!wallet_base64_to_bytes(iv_b64, iv, decode_error) ||
        !wallet_base64_to_bytes(salt_b64, salt, decode_error) ||
        !wallet_base64_to_bytes(ciphertext_b64, encrypted_and_tag, decode_error)) {
        err = "invalid SJCL base64 field: " + decode_error;
        return false;
    }
    if (iv.size() < 13u || salt.empty() ||
        salt.size() > WALLET_MAX_SALT_LEN ||
        encrypted_and_tag.size() <= 8u ||
        encrypted_and_tag.size() - 8u > 65535u) {
        err = "unsupported SJCL nonce/salt/ciphertext length";
        return false;
    }

    const std::string key = wallet_browser_vault_key(
        encrypted_and_tag, iv, salt, iterations,
        BROWSERVAULT_PROFILE_COPAY_SJCL_AES_CCM);
    if (!seen.insert(key).second) {
        return true;
    }

    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = BROWSERVAULT_PROFILE_COPAY_SJCL_AES_CCM;
    target.dev.iterations = iterations;
    target.dev.salt_len = static_cast<uint32_t>(salt.size());
    target.dev.iv_len = 13u;
    target.dev.ciphertext_len =
        static_cast<uint32_t>(encrypted_and_tag.size() - 8u);
    memcpy(target.dev.salt, salt.data(), salt.size());
    memcpy(target.dev.iv, iv.data(), 13u);
    memcpy(target.dev.tag,
        encrypted_and_tag.data() + target.dev.ciphertext_len, 8u);
    target.ciphertext.assign(
        encrypted_and_tag.begin(),
        encrypted_and_tag.begin() + target.dev.ciphertext_len);
    wallet_browser_vault_hash(
        encrypted_and_tag, iv, salt, iterations,
        BROWSERVAULT_PROFILE_COPAY_SJCL_AES_CCM,
        target.dev.vault_hash);
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_copaywallet_file(
    const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    const size_t before = targets.size();
    if (!wallet_parse_copaywallet_text(path, text, targets, seen, err)) {
        return false;
    }
    if (targets.size() == before) {
        err = "duplicate Copay/BitPay SJCL backup";
        return false;
    }
    return true;
}

static uint32_t wallet_terra_bech32_polymod_step(const uint32_t pre)
{
    const uint32_t top = pre >> 25u;
    uint32_t value = (pre & 0x01ffffffu) << 5u;
    if ((top & 1u) != 0u) value ^= 0x3b6a57b2u;
    if ((top & 2u) != 0u) value ^= 0x26508e6du;
    if ((top & 4u) != 0u) value ^= 0x1ea119fau;
    if ((top & 8u) != 0u) value ^= 0x3d4233ddu;
    if ((top & 16u) != 0u) value ^= 0x2a1462b3u;
    return value;
}

static int wallet_terra_bech32_value(const unsigned char c)
{
    static constexpr char charset[] =
        "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
    const unsigned char lower =
        (c >= 'A' && c <= 'Z') ? static_cast<unsigned char>(c + 32u) : c;
    const char* p = std::strchr(charset, static_cast<int>(lower));
    return p == nullptr ? -1 : static_cast<int>(p - charset);
}

static bool wallet_terra_decode_address(
    const std::string& input,
    uint8_t payload20[20],
    std::string& err)
{
    const std::string address = wallet_trim_copy(input);
    if (address.size() < 8u || address.size() > 90u) {
        err = "terra address length is invalid";
        return false;
    }
    bool lower = false;
    bool upper = false;
    for (const unsigned char c : address) {
        if (c < 33u || c > 126u) {
            err = "terra address contains an invalid character";
            return false;
        }
        lower = lower || (c >= 'a' && c <= 'z');
        upper = upper || (c >= 'A' && c <= 'Z');
    }
    if (lower && upper) {
        err = "terra address mixes upper and lower case";
        return false;
    }
    const size_t separator = address.rfind('1');
    if (separator == std::string::npos || separator == 0u ||
        separator + 7u > address.size()) {
        err = "terra address has no valid Bech32 separator/checksum";
        return false;
    }
    std::string hrp = address.substr(0u, separator);
    std::transform(hrp.begin(), hrp.end(), hrp.begin(),
        [](const unsigned char c) {
            return static_cast<char>(std::tolower(c));
        });
    if (hrp != "terra") {
        err = "address HRP must be terra";
        return false;
    }

    uint32_t checksum = 1u;
    for (const unsigned char c : hrp) {
        checksum =
            wallet_terra_bech32_polymod_step(checksum) ^ (c >> 5u);
    }
    checksum = wallet_terra_bech32_polymod_step(checksum);
    for (const unsigned char c : hrp) {
        checksum =
            wallet_terra_bech32_polymod_step(checksum) ^ (c & 31u);
    }
    std::vector<uint8_t> values;
    values.reserve(address.size() - separator - 7u);
    for (size_t i = separator + 1u; i < address.size(); ++i) {
        const int value =
            wallet_terra_bech32_value(static_cast<unsigned char>(address[i]));
        if (value < 0) {
            err = "terra address contains an invalid Bech32 character";
            return false;
        }
        checksum =
            wallet_terra_bech32_polymod_step(checksum) ^
            static_cast<uint32_t>(value);
        if (i + 6u < address.size()) {
            values.push_back(static_cast<uint8_t>(value));
        }
    }
    if (checksum != 1u) {
        err = "terra address Bech32 checksum mismatch";
        return false;
    }

    uint32_t accumulator = 0u;
    uint32_t bits = 0u;
    size_t output = 0u;
    for (const uint8_t value : values) {
        accumulator = ((accumulator << 5u) | value) & 0x0fffffffu;
        bits += 5u;
        while (bits >= 8u) {
            bits -= 8u;
            if (output >= 20u) {
                err = "terra address payload is longer than 20 bytes";
                return false;
            }
            payload20[output++] =
                static_cast<uint8_t>((accumulator >> bits) & 0xffu);
        }
    }
    if (output != 20u || bits >= 5u ||
        ((accumulator << (8u - bits)) & 0xffu) != 0u) {
        err = "terra address payload must be exactly 20 bytes";
        return false;
    }
    return true;
}

static bool wallet_parse_terrawallet_text(
    const std::string& source,
    const std::string& input,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string json = wallet_trim_copy(input);
    if (json.empty()) {
        err = "empty Terra Station export";
        return false;
    }
    if (json.front() != '{') {
        std::vector<uint8_t> decoded;
        if (!wallet_base64_to_bytes(json, decoded, err) || decoded.empty()) {
            err = "invalid outer-base64 Terra Station export: " + err;
            return false;
        }
        json.assign(
            reinterpret_cast<const char*>(decoded.data()), decoded.size());
        json = wallet_trim_copy(json);
    }
    if (json.empty() || json.front() != '{' || json.back() != '}') {
        err = "Terra Station export must be a JSON object";
        return false;
    }

    std::string name;
    std::string address;
    std::string encrypted_key;
    if (!wallet_json_get_string(json, "name", name) ||
        !wallet_json_get_string(json, "address", address) ||
        !wallet_json_get_string(json, "encrypted_key", encrypted_key)) {
        err = "missing required name/address/encrypted_key fields";
        return false;
    }
    if (encrypted_key.size() <= 64u) {
        err = "encrypted_key is too short";
        return false;
    }

    std::vector<uint8_t> salt;
    std::vector<uint8_t> iv;
    std::vector<uint8_t> ciphertext;
    if (!wallet_hex_to_bytes(encrypted_key.substr(0u, 32u), salt, err) ||
        salt.size() != 16u ||
        !wallet_hex_to_bytes(encrypted_key.substr(32u, 32u), iv, err) ||
        iv.size() != 16u ||
        !wallet_base64_to_bytes(encrypted_key.substr(64u), ciphertext, err)) {
        err = "invalid encrypted_key salt/iv/ciphertext: " + err;
        return false;
    }
    if (ciphertext.size() != 80u) {
        err = "Terra Station ciphertext must be exactly 80 bytes";
        return false;
    }

    uint8_t address_payload[20] = {};
    if (!wallet_terra_decode_address(address, address_payload, err)) {
        return false;
    }

    std::vector<uint8_t> identity = ciphertext;
    identity.insert(identity.end(), address_payload, address_payload + 20u);
    const std::string key = wallet_browser_vault_key(
        identity, iv, salt, 100u,
        BROWSERVAULT_PROFILE_TERRA_STATION_AES_CBC);
    if (!seen.insert(key).second) {
        return true;
    }

    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = BROWSERVAULT_PROFILE_TERRA_STATION_AES_CBC;
    target.dev.iterations = 100u;
    target.dev.salt_len = 16u;
    target.dev.iv_len = 16u;
    target.dev.ciphertext_len = 80u;
    target.dev.expected_public_len = 20u;
    memcpy(target.dev.salt, salt.data(), 16u);
    memcpy(target.dev.iv, iv.data(), 16u);
    memcpy(target.dev.expected_public, address_payload, 20u);
    target.ciphertext = ciphertext;
    wallet_browser_vault_hash(
        identity, iv, salt, 100u,
        BROWSERVAULT_PROFILE_TERRA_STATION_AES_CBC,
        target.dev.vault_hash);
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_terrawallet_file(
    const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    const size_t before = targets.size();
    if (!wallet_parse_terrawallet_text(
            path, text, targets, seen, err)) {
        return false;
    }
    if (targets.size() == before) {
        err = "duplicate Terra Station export";
        return false;
    }
    return true;
}

static bool wallet_bitshares_decode_public_key(
    const std::string& encoded,
    std::vector<uint8_t>& public_key,
    std::string& err)
{
    std::string payload;
    if (encoded.rfind("BTSX", 0u) == 0u) {
        payload = encoded.substr(4u);
    }
    else if (encoded.rfind("BTS", 0u) == 0u) {
        payload = encoded.substr(3u);
    }
    else {
        err = "BitShares public key must use BTS or BTSX prefix";
        return false;
    }
    std::vector<uint8_t> decoded;
    if (!wallet_base58_to_bytes(payload, decoded, err) ||
        decoded.size() != 37u ||
        (decoded[0] != 0x02u && decoded[0] != 0x03u)) {
        err = "invalid BitShares compressed public-key payload";
        return false;
    }
    uint8_t checksum[20] = {};
    ripemd160(decoded.data(), 33, checksum);
    if (std::memcmp(checksum, decoded.data() + 33u, 4u) != 0) {
        err = "BitShares public-key RIPEMD160 checksum mismatch";
        return false;
    }
    public_key.assign(decoded.begin(), decoded.begin() + 33u);
    return true;
}

static bool wallet_parse_bitshareswallet_text(
    const std::string& source,
    const std::string& input,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    const std::string json = wallet_trim_copy(input);
    if (json.empty() || json.front() != '{' || json.back() != '}') {
        err = "BitShares exported_keys input must be a JSON object";
        return false;
    }

    std::string checksum_hex;
    std::string account_keys_json;
    if (!wallet_json_get_string(
            json, "password_checksum", checksum_hex) ||
        !wallet_json_get_array(
            json, "account_keys", account_keys_json)) {
        err = "missing password_checksum/account_keys fields";
        return false;
    }
    std::vector<uint8_t> password_checksum;
    if (!wallet_hex_to_bytes(
            checksum_hex, password_checksum, err) ||
        password_checksum.size() != 64u) {
        err = "password_checksum must be exactly 64 SHA-512 bytes";
        return false;
    }

    std::vector<std::string> account_objects;
    if (!wallet_json_parse_object_array(
            account_keys_json, account_objects) ||
        account_objects.empty()) {
        err = "account_keys must be a non-empty array of objects";
        return false;
    }

    size_t parsed_records = 0u;
    for (size_t account_index = 0u;
         account_index < account_objects.size();
         ++account_index) {
        const std::string& account = account_objects[account_index];
        std::string account_name;
        std::string encrypted_json;
        std::string public_json;
        if (!wallet_json_get_string(
                account, "account_name", account_name) ||
            !wallet_json_get_array(
                account, "encrypted_private_keys", encrypted_json) ||
            !wallet_json_get_array(
                account, "public_keys", public_json)) {
            err = "account_keys entry is missing account_name/encrypted_private_keys/public_keys";
            return false;
        }
        std::vector<std::string> encrypted_keys;
        std::vector<std::string> public_keys;
        if (!wallet_json_parse_string_array(
                encrypted_json, encrypted_keys) ||
            !wallet_json_parse_string_array(
                public_json, public_keys) ||
            encrypted_keys.empty() ||
            encrypted_keys.size() != public_keys.size()) {
            err = "encrypted_private_keys/public_keys must be equal non-empty string arrays";
            return false;
        }

        for (size_t key_index = 0u;
             key_index < encrypted_keys.size();
             ++key_index) {
            std::vector<uint8_t> ciphertext;
            std::vector<uint8_t> public_key;
            if (!wallet_hex_to_bytes(
                    encrypted_keys[key_index], ciphertext, err) ||
                ciphertext.size() != 48u) {
                err = "encrypted private key must be exactly 48 AES-CBC bytes";
                return false;
            }
            if (!wallet_bitshares_decode_public_key(
                    public_keys[key_index], public_key, err)) {
                return false;
            }

            std::vector<uint8_t> identity = ciphertext;
            identity.insert(
                identity.end(), public_key.begin(), public_key.end());
            const std::string key = wallet_browser_vault_key(
                identity, {}, password_checksum, 2u,
                BROWSERVAULT_PROFILE_BITSHARES_0X_AES_CBC);
            if (!seen.insert(key).second) {
                continue;
            }

            BrowserVaultHostTarget target;
            target.file = source + "#account=" +
                std::to_string(account_index) + "/key=" +
                std::to_string(key_index);
            target.dev.profile =
                BROWSERVAULT_PROFILE_BITSHARES_0X_AES_CBC;
            target.dev.iterations = 2u;
            target.dev.salt_len = 64u;
            target.dev.iv_len = 0u;
            target.dev.ciphertext_len = 48u;
            target.dev.expected_public_len = 33u;
            std::memcpy(
                target.dev.salt, password_checksum.data(), 64u);
            std::memcpy(
                target.dev.expected_public, public_key.data(), 33u);
            target.ciphertext = ciphertext;
            wallet_browser_vault_hash(
                identity, {}, password_checksum, 2u,
                BROWSERVAULT_PROFILE_BITSHARES_0X_AES_CBC,
                target.dev.vault_hash);
            targets.push_back(std::move(target));
            ++parsed_records;
        }
    }
    if (parsed_records == 0u) {
        err = "exported_keys contains only duplicate key records";
        return false;
    }
    return true;
}

static bool wallet_parse_bitshareswallet_file(
    const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) return false;
    return wallet_parse_bitshareswallet_text(
        path, text, targets, seen, err);
}

struct YoroiIndexedDbKeyRecord {
    uint32_t key_id = 0u;
    uint32_t type = 0u;
    bool encrypted = false;
    std::vector<uint8_t> bytes;
};

struct YoroiIndexedDbDerivationRecord {
    uint32_t derivation_id = 0u;
    bool has_private_key = false;
    uint32_t private_key_id = 0u;
    bool has_public_key = false;
    uint32_t public_key_id = 0u;
    bool has_parent = false;
    uint32_t parent = 0u;
    bool has_index = false;
    uint32_t index = 0u;
};

static bool wallet_parse_yoroiwallet_text(
    const std::string& source,
    const std::string& input,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    const std::string json = wallet_trim_copy(input);
    if (json.empty() || json.front() != '{' || json.back() != '}') {
        err = "Yoroi IndexedDB input must be a JSON object";
        return false;
    }

    std::string keys_json;
    std::string derivations_json;
    if (!wallet_json_get_array(json, "Key", keys_json) ||
        !wallet_json_get_array(
            json, "KeyDerivation", derivations_json)) {
        err = "missing Key/KeyDerivation IndexedDB tables";
        return false;
    }

    std::vector<std::string> key_objects;
    std::vector<std::string> derivation_objects;
    if (!wallet_json_parse_object_array(keys_json, key_objects) ||
        !wallet_json_parse_object_array(
            derivations_json, derivation_objects) ||
        key_objects.empty() || derivation_objects.empty()) {
        err = "Key/KeyDerivation must be non-empty object arrays";
        return false;
    }

    std::unordered_map<uint32_t, YoroiIndexedDbKeyRecord> keys;
    for (const std::string& object : key_objects) {
        std::string value;
        if (!wallet_json_get_object(object, "value", value)) {
            err = "Key entry is missing its value object";
            return false;
        }
        uint32_t key_id = 0u;
        uint32_t type = 0u;
        if (!wallet_json_get_u32(value, "KeyId", key_id) ||
            !wallet_json_get_u32(value, "Type", type)) {
            err = "Key value is missing KeyId/Type";
            return false;
        }
        if (type != 0u) {
            continue;
        }
        std::string hash_hex;
        bool encrypted = false;
        if (!wallet_json_get_string(value, "Hash", hash_hex) ||
            !wallet_json_get_bool(
                value, "IsEncrypted", encrypted)) {
            err = "BIP32-Ed25519 Key is missing Hash/IsEncrypted";
            return false;
        }
        std::vector<uint8_t> bytes;
        if (!wallet_hex_to_bytes(hash_hex, bytes, err)) {
            err = "invalid Yoroi Key.Hash: " + err;
            return false;
        }
        const size_t expected_size = encrypted ? 156u : 64u;
        if (bytes.size() != expected_size) {
            err = encrypted
                ? "encrypted Yoroi root must be 156 EMIP-3 bytes"
                : "Yoroi account xpub must be 64 bytes";
            return false;
        }
        YoroiIndexedDbKeyRecord record;
        record.key_id = key_id;
        record.type = type;
        record.encrypted = encrypted;
        record.bytes = std::move(bytes);
        if (!keys.emplace(key_id, std::move(record)).second) {
            err = "duplicate Yoroi KeyId";
            return false;
        }
    }
    if (keys.empty()) {
        err = "no BIP32-Ed25519 Key records";
        return false;
    }

    std::unordered_map<uint32_t, YoroiIndexedDbDerivationRecord>
        derivations;
    for (const std::string& object : derivation_objects) {
        std::string value;
        if (!wallet_json_get_object(object, "value", value)) {
            err = "KeyDerivation entry is missing its value object";
            return false;
        }
        YoroiIndexedDbDerivationRecord record;
        if (!wallet_json_get_u32(
                value, "KeyDerivationId", record.derivation_id) ||
            !wallet_json_get_optional_u32(
                value, "PrivateKeyId",
                record.has_private_key, record.private_key_id) ||
            !wallet_json_get_optional_u32(
                value, "PublicKeyId",
                record.has_public_key, record.public_key_id) ||
            !wallet_json_get_optional_u32(
                value, "Parent",
                record.has_parent, record.parent) ||
            !wallet_json_get_optional_u32(
                value, "Index",
                record.has_index, record.index)) {
            err = "malformed Yoroi KeyDerivation value";
            return false;
        }
        if (!derivations.emplace(
                record.derivation_id, record).second) {
            err = "duplicate Yoroi KeyDerivationId";
            return false;
        }
    }

    size_t added = 0u;
    for (const auto& root_pair : derivations) {
        const YoroiIndexedDbDerivationRecord& root =
            root_pair.second;
        if (!root.has_private_key ||
            root.has_parent || root.has_index) {
            continue;
        }
        const auto root_key_it = keys.find(root.private_key_id);
        if (root_key_it == keys.end() ||
            !root_key_it->second.encrypted) {
            continue;
        }
        const std::vector<uint8_t>& emip3 =
            root_key_it->second.bytes;

        for (const auto& purpose_pair : derivations) {
            const YoroiIndexedDbDerivationRecord& purpose =
                purpose_pair.second;
            if (!purpose.has_parent ||
                purpose.parent != root.derivation_id ||
                !purpose.has_index ||
                purpose.index != 0x8000073cu) {
                continue;
            }
            for (const auto& coin_pair : derivations) {
                const YoroiIndexedDbDerivationRecord& coin =
                    coin_pair.second;
                if (!coin.has_parent ||
                    coin.parent != purpose.derivation_id ||
                    !coin.has_index ||
                    coin.index != 0x80000717u) {
                    continue;
                }
                for (const auto& account_pair : derivations) {
                    const YoroiIndexedDbDerivationRecord& account =
                        account_pair.second;
                    if (!account.has_parent ||
                        account.parent != coin.derivation_id ||
                        !account.has_index ||
                        (account.index & 0x80000000u) == 0u ||
                        !account.has_public_key) {
                        continue;
                    }
                    const auto account_key_it =
                        keys.find(account.public_key_id);
                    if (account_key_it == keys.end() ||
                        account_key_it->second.encrypted ||
                        account_key_it->second.bytes.size() != 64u) {
                        continue;
                    }
                    const std::vector<uint8_t>& account_xpub =
                        account_key_it->second.bytes;
                    std::vector<uint8_t> identity = emip3;
                    identity.insert(
                        identity.end(),
                        account_xpub.begin(), account_xpub.end());
                    identity.push_back(
                        static_cast<uint8_t>(account.index));
                    identity.push_back(
                        static_cast<uint8_t>(account.index >> 8u));
                    identity.push_back(
                        static_cast<uint8_t>(account.index >> 16u));
                    identity.push_back(
                        static_cast<uint8_t>(account.index >> 24u));
                    std::vector<uint8_t> nonce(
                        emip3.begin() + 32,
                        emip3.begin() + 44);
                    std::vector<uint8_t> salt(
                        emip3.begin(), emip3.begin() + 32);
                    const std::string key =
                        wallet_browser_vault_key(
                            identity, nonce, salt, 19162u,
                            BROWSERVAULT_PROFILE_YOROI_EMIP3);
                    if (!seen.insert(key).second) {
                        continue;
                    }

                    BrowserVaultHostTarget target;
                    target.file = source + "#root=" +
                        std::to_string(root.private_key_id) +
                        "/account=" +
                        std::to_string(
                            account.index & 0x7fffffffu);
                    target.dev.profile =
                        BROWSERVAULT_PROFILE_YOROI_EMIP3;
                    target.dev.iterations = 19162u;
                    target.dev.salt_len = 32u;
                    target.dev.iv_len = 12u;
                    target.dev.ciphertext_len = 96u;
                    target.dev.key_kind = account.index;
                    target.dev.expected_public_len = 32u;
                    std::memcpy(
                        target.dev.salt, emip3.data(), 32u);
                    std::memcpy(
                        target.dev.salt + 32u,
                        account_xpub.data() + 32u, 32u);
                    std::memcpy(
                        target.dev.iv, emip3.data() + 32u, 12u);
                    std::memcpy(
                        target.dev.tag, emip3.data() + 44u, 16u);
                    std::memcpy(
                        target.dev.expected_public,
                        account_xpub.data(), 32u);
                    target.ciphertext.assign(
                        emip3.begin() + 60u, emip3.end());
                    wallet_browser_vault_hash(
                        identity, nonce, salt, 19162u,
                        BROWSERVAULT_PROFILE_YOROI_EMIP3,
                        target.dev.vault_hash);
                    targets.push_back(std::move(target));
                    ++added;
                }
            }
        }
    }
    if (added == 0u) {
        err = "no encrypted root with exact 1852'/1815'/account' xpub chain";
        return false;
    }
    return true;
}

static bool wallet_parse_yoroiwallet_file(
    const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) return false;
    return wallet_parse_yoroiwallet_text(
        path, text, targets, seen, err);
}

static uint32_t wallet_substrate_load_le32(const uint8_t* bytes)
{
    return static_cast<uint32_t>(bytes[0]) |
        (static_cast<uint32_t>(bytes[1]) << 8u) |
        (static_cast<uint32_t>(bytes[2]) << 16u) |
        (static_cast<uint32_t>(bytes[3]) << 24u);
}

static bool wallet_substrate_decode_identity(
    const std::string& address,
    const uint32_t key_kind,
    std::vector<uint8_t>& public_key,
    std::string& err)
{
    public_key.clear();
    if (address.size() >= 2u && address[0] == '0' &&
        (address[1] == 'x' || address[1] == 'X')) {
        if (!wallet_hex_to_bytes(address, public_key, err)) {
            err = "invalid hex identity: " + err;
            return false;
        }
    }
    else {
        std::vector<uint8_t> decoded;
        if (!wallet_base58_to_bytes(address, decoded, err)) {
            err = "invalid SS58 identity: " + err;
            return false;
        }
        if (decoded.size() != 35u && decoded.size() != 36u) {
            err = "unsupported SS58 identity length";
            return false;
        }
        const size_t prefix_len = decoded.size() - 34u;
        const size_t body_len = prefix_len + 32u;
        std::vector<uint8_t> framed;
        static constexpr char kSs58Prefix[] = "SS58PRE";
        framed.reserve(sizeof(kSs58Prefix) - 1u + body_len);
        framed.insert(
            framed.end(),
            kSs58Prefix,
            kSs58Prefix + sizeof(kSs58Prefix) - 1u);
        framed.insert(
            framed.end(), decoded.begin(), decoded.begin() + body_len);
        uint8_t checksum[64] = {};
        blake2b(framed.data(), framed.size(), checksum, sizeof(checksum));
        if (decoded[body_len] != checksum[0] ||
            decoded[body_len + 1u] != checksum[1]) {
            err = "SS58 checksum mismatch";
            return false;
        }
        public_key.assign(
            decoded.begin() + static_cast<std::ptrdiff_t>(prefix_len),
            decoded.begin() + static_cast<std::ptrdiff_t>(body_len));
    }
    const size_t expected =
        key_kind == SUBSTRATEWALLET_KEY_ECDSA ? 33u : 32u;
    if (public_key.size() != expected) {
        std::ostringstream message;
        message << "identity has " << public_key.size()
                << " public-key bytes, expected " << expected;
        err = message.str();
        return false;
    }
    if (key_kind == SUBSTRATEWALLET_KEY_ECDSA &&
        public_key[0] != 0x02u && public_key[0] != 0x03u) {
        err = "ECDSA identity must be a compressed secp256k1 public key";
        return false;
    }
    return true;
}

static bool wallet_parse_substratewallet_file(
    const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string json;
    if (!mac_read_text_file(path, json, err)) {
        return false;
    }
    std::string encoded_text;
    std::string address;
    if (!wallet_json_get_string(json, "encoded", encoded_text) ||
        !wallet_json_get_string(json, "address", address)) {
        err = "missing Substrate JSON encoded/address field";
        return false;
    }
    std::string encoding;
    if (!wallet_json_get_object(json, "encoding", encoding) ||
        !wallet_json_has_exact_string_token(encoding, "pkcs8") ||
        !wallet_json_has_exact_string_token(
            encoding, "xsalsa20-poly1305")) {
        err = "unsupported Substrate JSON encoding";
        return false;
    }

    uint32_t key_kind = 0u;
    const bool has_sr25519 =
        wallet_json_has_exact_string_token(encoding, "sr25519");
    const bool has_ed25519 =
        wallet_json_has_exact_string_token(encoding, "ed25519");
    const bool has_ecdsa =
        wallet_json_has_exact_string_token(encoding, "ecdsa");
    if (static_cast<uint32_t>(has_sr25519) +
            static_cast<uint32_t>(has_ed25519) +
            static_cast<uint32_t>(has_ecdsa) != 1u) {
        err = "Substrate JSON encoding must name exactly one supported curve";
        return false;
    }
    if (has_sr25519) {
        key_kind = SUBSTRATEWALLET_KEY_SR25519;
    }
    else if (has_ed25519) {
        key_kind = SUBSTRATEWALLET_KEY_ED25519;
    }
    else if (has_ecdsa) {
        key_kind = SUBSTRATEWALLET_KEY_ECDSA;
    }

    std::string version_text;
    uint32_t version = 0u;
    if (wallet_json_get_string(encoding, "version", version_text)) {
        char* end = nullptr;
        const unsigned long value =
            std::strtoul(version_text.c_str(), &end, 10);
        if (end == version_text.c_str() || *end != '\0' ||
            value > static_cast<unsigned long>(UINT32_MAX)) {
            err = "invalid Substrate JSON version";
            return false;
        }
        version = static_cast<uint32_t>(value);
    }
    else if (!wallet_json_get_u32(encoding, "version", version)) {
        err = "missing Substrate JSON version";
        return false;
    }
    if (version != 2u && version != 3u) {
        err = "only Substrate JSON versions 2 and 3 are supported";
        return false;
    }

    std::vector<uint8_t> encoded;
    std::string decode_error;
    const bool encoded_is_hex =
        encoded_text.size() >= 2u && encoded_text[0] == '0' &&
        (encoded_text[1] == 'x' || encoded_text[1] == 'X');
    const bool decoded_ok = encoded_is_hex
        ? wallet_hex_to_bytes(encoded_text, encoded, decode_error)
        : wallet_base64_to_bytes(encoded_text, encoded, decode_error);
    if (!decoded_ok || encoded.empty()) {
        err = "invalid Substrate JSON encoded payload: " + decode_error;
        return false;
    }
    std::vector<uint8_t> expected_public;
    if (!wallet_substrate_decode_identity(
            address, key_kind, expected_public, err)) {
        return false;
    }

    BrowserVaultHostTarget target;
    target.file = path;
    target.dev.key_kind = key_kind;
    target.dev.expected_public_len =
        static_cast<uint32_t>(expected_public.size());
    memcpy(
        target.dev.expected_public,
        expected_public.data(),
        expected_public.size());
    target.dev.iterations = 1u;
    target.dev.iv_len = 24u;

    std::vector<uint8_t> salt;
    if (version == 3u) {
        if (!wallet_json_has_exact_string_token(encoding, "scrypt") ||
            encoded.size() < 44u + 24u + 16u + 85u) {
            err = "invalid Substrate v3 scrypt/secretbox payload length";
            return false;
        }
        salt.assign(encoded.begin(), encoded.begin() + 32);
        target.dev.profile =
            BROWSERVAULT_PROFILE_SUBSTRATE_SCRYPT_PKCS8;
        target.dev.scrypt_n =
            wallet_substrate_load_le32(encoded.data() + 32u);
        target.dev.scrypt_p =
            wallet_substrate_load_le32(encoded.data() + 36u);
        target.dev.scrypt_r =
            wallet_substrate_load_le32(encoded.data() + 40u);
        if (target.dev.scrypt_n < 2u ||
            (target.dev.scrypt_n & (target.dev.scrypt_n - 1u)) != 0u ||
            target.dev.scrypt_n > (1u << 20u) ||
            target.dev.scrypt_r == 0u || target.dev.scrypt_r > 32u ||
            target.dev.scrypt_p == 0u || target.dev.scrypt_p > 32u) {
            err = "unsupported Substrate v3 scrypt parameters";
            return false;
        }
        target.dev.salt_len = 32u;
        memcpy(target.dev.salt, salt.data(), salt.size());
        memcpy(target.dev.iv, encoded.data() + 44u, 24u);
        memcpy(target.dev.tag, encoded.data() + 68u, 16u);
        target.ciphertext.assign(encoded.begin() + 84, encoded.end());
    }
    else {
        if (wallet_json_has_exact_string_token(encoding, "scrypt") ||
            encoded.size() < 24u + 16u + 85u) {
            err = "invalid Substrate v2 legacy secretbox payload";
            return false;
        }
        target.dev.profile =
            BROWSERVAULT_PROFILE_SUBSTRATE_LEGACY_PKCS8;
        target.dev.salt_len = 0u;
        memcpy(target.dev.iv, encoded.data(), 24u);
        memcpy(target.dev.tag, encoded.data() + 24u, 16u);
        target.ciphertext.assign(encoded.begin() + 40, encoded.end());
    }
    if (target.ciphertext.size() < 85u ||
        target.ciphertext.size() > 117u) {
        err = "unsupported Substrate PKCS8 plaintext length";
        return false;
    }
    target.dev.ciphertext_len =
        static_cast<uint32_t>(target.ciphertext.size());
    wallet_browser_vault_hash(
        encoded,
        std::vector<uint8_t>(
            target.dev.iv, target.dev.iv + target.dev.iv_len),
        salt,
        version,
        target.dev.profile,
        target.dev.vault_hash);
    const std::string key(
        reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
    if (!seen.insert(key).second) {
        err = "duplicate Substrate wallet";
        return false;
    }
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_stellar_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$stellar$", token)) {
        err = "no $stellar$ hash token";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token, '$');
    if (parts.size() != 5u || parts[1] != "stellar") {
        err = "unsupported $stellar$ field count";
        return false;
    }

    std::vector<uint8_t> salt, iv, blob;
    std::string dec_err;
    if (!wallet_base64_to_bytes(parts[2], salt, dec_err)) {
        err = "invalid $stellar$ salt: " + dec_err;
        return false;
    }
    if (!wallet_base64_to_bytes(parts[3], iv, dec_err)) {
        err = "invalid $stellar$ iv: " + dec_err;
        return false;
    }
    if (!wallet_base64_to_bytes(parts[4], blob, dec_err)) {
        err = "invalid $stellar$ ciphertext/tag: " + dec_err;
        return false;
    }
    if (salt.size() != 16u) {
        err = "unsupported $stellar$ salt length";
        return false;
    }
    if (iv.size() != 12u) {
        err = "unsupported $stellar$ iv length";
        return false;
    }
    if (blob.size() <= 16u || blob.size() - 16u > BROWSERVAULT_MAX_BLOB_LEN) {
        err = "unsupported $stellar$ ciphertext length";
        return false;
    }
    if (!wallet_add_browser_vault_target(source, BROWSERVAULT_PROFILE_STELLAR_AES_GCM,
        blob, iv, salt, 4096u, targets, seen)) {
        err = "duplicate or unsupported $stellar$ target";
        return false;
    }
    return true;
}

static bool wallet_parse_stellarwallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$stellar$") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_stellar_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }
    if (added == 0u) {
        err = last_err.empty() ? "no usable $stellar$ hash target" : last_err;
        return false;
    }
    return true;
}

static bool wallet_parse_stellarwallet_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    return wallet_parse_stellarwallet_text(path, text, targets, seen, err);
}

static bool wallet_parse_blockchain_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$blockchain$", token)) {
        err = "no $blockchain$ hash token";
        return false;
    }

    const std::vector<std::string> parts = wallet_split_char(token, '$');
    uint64_t iterations64 = 10ull;
    uint64_t declared_len = 0ull;
    std::string hex_blob;
    if (parts.size() == 4u && parts[1] == "blockchain") {
        if (!wallet_parse_u64_decimal(parts[2], declared_len)) {
            err = "invalid $blockchain$ length";
            return false;
        }
        hex_blob = parts[3];
    }
    else if (parts.size() == 6u && parts[1] == "blockchain" && wallet_lower_copy(parts[2]) == "v2") {
        if (!wallet_parse_u64_decimal(parts[3], iterations64) ||
            !wallet_parse_u64_decimal(parts[4], declared_len)) {
            err = "invalid $blockchain$v2$ iterations/length";
            return false;
        }
        hex_blob = parts[5];
    }
    else {
        err = "unsupported $blockchain$ field count";
        return false;
    }
    if (iterations64 == 0ull || iterations64 > std::numeric_limits<uint32_t>::max()) {
        err = "unsupported $blockchain$ iteration count";
        return false;
    }
    if (hex_blob.size() < 128u || (hex_blob.size() & 1u) != 0u) {
        err = "unsupported $blockchain$ blob length";
        return false;
    }
    for (char c : hex_blob) {
        if (!std::isxdigit(static_cast<unsigned char>(c))) {
            err = "invalid $blockchain$ hex blob";
            return false;
        }
    }
    (void)declared_len; // hashcat-compatible verification uses the encrypted blob itself.

    std::vector<uint8_t> first64;
    std::string dec_err;
    if (!wallet_hex_to_bytes(hex_blob.substr(0u, 128u), first64, dec_err) || first64.size() != 64u) {
        err = "invalid $blockchain$ first encrypted blocks: " + dec_err;
        return false;
    }

    std::vector<uint8_t> iv(first64.begin(), first64.begin() + 16);
    std::vector<uint8_t> ciphertext(first64.begin() + 16, first64.end());
    if (!wallet_add_browser_vault_target(source, BROWSERVAULT_PROFILE_BLOCKCHAIN_V2_PBKDF2_AES_CBC,
        ciphertext, iv, iv, static_cast<uint32_t>(iterations64), targets, seen)) {
        err = "duplicate or unsupported $blockchain$ target";
        return false;
    }
    return true;
}

static bool wallet_parse_blockchainwallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$blockchain$") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_blockchain_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }
    if (added == 0u) {
        err = last_err.empty() ? "no usable $blockchain$ hash target" : last_err;
        return false;
    }
    return true;
}

static bool wallet_parse_blockchainwallet_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
