static bool wallet_parse_android_backup_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$ab$", token)) {
        err = "no $ab$ Android Backup hash token";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token, '*');
    if (parts.size() != 7u || parts[0].rfind("$ab$", 0u) != 0u || parts[0].size() <= 4u) {
        err = "unsupported $ab$ field count/signature";
        return false;
    }
    uint64_t version64 = 0ull;
    uint64_t cipher64 = 0ull;
    uint64_t iterations64 = 0ull;
    if (!wallet_parse_u64_decimal(parts[0].substr(4u), version64) ||
        !wallet_parse_u64_decimal(parts[1], cipher64) ||
        !wallet_parse_u64_decimal(parts[2], iterations64)) {
        err = "invalid $ab$ version/cipher/iteration field";
        return false;
    }
    if (version64 == 0ull || cipher64 != 0ull ||
        iterations64 == 0ull || iterations64 > std::numeric_limits<uint32_t>::max()) {
        err = "unsupported $ab$ version/cipher/iteration value";
        return false;
    }

    std::vector<uint8_t> user_salt, ck_salt, user_iv, masterkey_blob;
    std::string dec_err;
    if (!wallet_hex_to_bytes(parts[3], user_salt, dec_err) || user_salt.size() != 64u) {
        err = "invalid $ab$ user_salt: " + dec_err;
        return false;
    }
    if (!wallet_hex_to_bytes(parts[4], ck_salt, dec_err) || ck_salt.size() != 64u) {
        err = "invalid $ab$ ck_salt: " + dec_err;
        return false;
    }
    if (!wallet_hex_to_bytes(parts[5], user_iv, dec_err) || user_iv.size() != 16u) {
        err = "invalid $ab$ user_iv: " + dec_err;
        return false;
    }
    if (!wallet_hex_to_bytes(parts[6], masterkey_blob, dec_err) || masterkey_blob.size() != 96u) {
        err = "invalid $ab$ masterkey_blob: " + dec_err;
        return false;
    }

    // Hashcat m18900 verifies the last encrypted master-key block using IV stored
    // inside masterkey_blob[64..79], not the separate user_iv field.
    std::vector<uint8_t> iv(masterkey_blob.begin() + 64, masterkey_blob.begin() + 80);
    std::vector<uint8_t> ciphertext(masterkey_blob.begin() + 80, masterkey_blob.begin() + 96);
    if (!wallet_add_browser_vault_target(source, BROWSERVAULT_PROFILE_ANDROID_BACKUP_PBKDF2_SHA1_AES_CBC,
        ciphertext, iv, user_salt, static_cast<uint32_t>(iterations64), targets, seen)) {
        err = "duplicate or unsupported $ab$ target";
        return false;
    }
    return true;
}

static bool wallet_parse_androidwallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$ab$") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_android_backup_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }
    if (added == 0u) {
        err = last_err.empty() ? "no usable $ab$ Android Backup hash target" : last_err;
        return false;
    }
    return true;
}

