static bool wallet_parse_dogechain_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$dogechain$", token)) {
        err = "no $dogechain$ hash token";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token, '*');
    if (parts.size() != 4u || parts[0] != "$dogechain$0") {
        err = "unsupported $dogechain$ field count/signature";
        return false;
    }
    uint64_t iterations64 = 0ull;
    if (!wallet_parse_u64_decimal(parts[1], iterations64) ||
        iterations64 == 0ull || iterations64 > std::numeric_limits<uint32_t>::max()) {
        err = "invalid $dogechain$ iteration count";
        return false;
    }

    std::vector<uint8_t> payload, salt;
    std::string dec_err;
    if (!wallet_base64_to_bytes(parts[2], payload, dec_err)) {
        err = "invalid $dogechain$ payload: " + dec_err;
        return false;
    }
    if (!wallet_base64_to_bytes(parts[3], salt, dec_err)) {
        err = "invalid $dogechain$ salt: " + dec_err;
        return false;
    }
    if (payload.size() < 48u || (payload.size() & 15u) != 0u || payload.size() > BROWSERVAULT_MAX_BLOB_LEN) {
        err = "unsupported $dogechain$ payload length";
        return false;
    }
    if (salt.empty() || salt.size() > WALLET_MAX_SALT_LEN) {
        err = "unsupported $dogechain$ salt length";
        return false;
    }

    const std::vector<uint8_t> empty_iv;
    if (!wallet_add_browser_vault_target(source, BROWSERVAULT_PROFILE_DOGECHAIN_PBKDF2_AES_CBC,
        payload, empty_iv, salt, static_cast<uint32_t>(iterations64), targets, seen)) {
        err = "duplicate or unsupported $dogechain$ target";
        return false;
    }
    return true;
}

static bool wallet_parse_dogechainwallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$dogechain$") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_dogechain_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
