static bool wallet_add_multibit_target(
    const std::string& source,
    uint32_t profile,
    const std::vector<uint8_t>& data,
    const std::vector<uint8_t>& iv,
    const std::vector<uint8_t>& salt,
    uint32_t iterations,
    uint32_t scrypt_n,
    uint32_t scrypt_r,
    uint32_t scrypt_p,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    const bool classic_md5 = profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_MD5_AES;
    const bool hd_scrypt = profile == BROWSERVAULT_PROFILE_MULTIBIT_HD_SCRYPT_AES;
    const bool classic_scrypt = profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_SCRYPT_AES;
    if (!classic_md5 && !hd_scrypt && !classic_scrypt) {
        err = "unsupported MultiBit profile";
        return false;
    }
    if (salt.size() != 8u) {
        err = "unsupported MultiBit salt length";
        return false;
    }
    if (classic_md5) {
        if (data.size() != 32u || !iv.empty()) {
            err = "unsupported MultiBit classic MD5 blob length";
            return false;
        }
    }
    else if (hd_scrypt) {
        if (data.size() != 32u || iv.size() != 16u) {
            err = "unsupported MultiBit HD blob length";
            return false;
        }
        scrypt_n = 16384u;
        scrypt_r = 8u;
        scrypt_p = 1u;
    }
    else {
        if (data.size() != 16u || iv.size() != 16u ||
            scrypt_n < 2u || (scrypt_n & (scrypt_n - 1u)) != 0u ||
            scrypt_r == 0u || scrypt_r > 8u || scrypt_p == 0u) {
            err = "unsupported MultiBit classic scrypt parameters/blob";
            return false;
        }
    }

    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = profile;
    target.dev.iterations = iterations == 0u ? 1u : iterations;
    target.dev.salt_len = 8u;
    target.dev.iv_len = static_cast<uint32_t>(iv.size());
    target.dev.ciphertext_len = static_cast<uint32_t>(data.size());
    target.dev.scrypt_n = scrypt_n;
    target.dev.scrypt_r = scrypt_r;
    target.dev.scrypt_p = scrypt_p;
    memcpy(target.dev.salt, salt.data(), 8u);
    if (!iv.empty()) memcpy(target.dev.iv, iv.data(), iv.size());
    target.ciphertext.assign(data.begin(), data.end());

    std::vector<uint8_t> hash_input;
    hash_input.reserve(data.size() + iv.size() + salt.size() + 32u);
    auto append_u32 = [&](uint32_t v) {
        hash_input.push_back(static_cast<uint8_t>(v & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((v >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((v >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((v >> 24) & 0xffu));
        };
    append_u32(profile);
    append_u32(target.dev.iterations);
    append_u32(scrypt_n);
    append_u32(scrypt_r);
    append_u32(scrypt_p);
    hash_input.insert(hash_input.end(), salt.begin(), salt.end());
    hash_input.push_back('|');
    hash_input.insert(hash_input.end(), iv.begin(), iv.end());
    hash_input.push_back('|');
    hash_input.insert(hash_input.end(), data.begin(), data.end());
    sha256(hash_input.data(), hash_input.size(), target.dev.vault_hash);
    const std::string key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
    if (!seen.insert(key).second) {
        err = "duplicate MultiBit target";
        return false;
    }
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_multibit_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$multibit$", token)) {
        err = "no $multibit$ hash token";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token, '*');
    std::string dec_err;
    if (parts.size() == 3u && parts[0] == "$multibit$1") {
        std::vector<uint8_t> salt, data;
        if (!wallet_hex_to_bytes(parts[1], salt, dec_err) || salt.size() != 8u) {
            err = "invalid MultiBit classic MD5 salt";
            return false;
        }
        if (!wallet_hex_to_bytes(parts[2], data, dec_err) || data.size() != 32u) {
            err = "invalid MultiBit classic MD5 encrypted data";
            return false;
        }
        const std::vector<uint8_t> empty_iv;
        return wallet_add_multibit_target(source, BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_MD5_AES,
            data, empty_iv, salt, 1u, 0u, 0u, 0u, targets, seen, err);
    }
    if (parts.size() == 4u && parts[0] == "$multibit$2") {
        std::vector<uint8_t> iv, block1, block2, data;
        if (!wallet_hex_to_bytes(parts[1], iv, dec_err) || iv.size() != 16u) {
            err = "invalid MultiBit HD IV";
            return false;
        }
        if (!wallet_hex_to_bytes(parts[2], block1, dec_err) || block1.size() != 16u ||
            !wallet_hex_to_bytes(parts[3], block2, dec_err) || block2.size() != 16u) {
            err = "invalid MultiBit HD encrypted blocks";
            return false;
        }
        data.reserve(32u);
        data.insert(data.end(), block1.begin(), block1.end());
        data.insert(data.end(), block2.begin(), block2.end());
        const std::vector<uint8_t> fixed_salt = {
            0x35u, 0x51u, 0x03u, 0x80u, 0x75u, 0xa3u, 0xb0u, 0xc5u
        };
        return wallet_add_multibit_target(source, BROWSERVAULT_PROFILE_MULTIBIT_HD_SCRYPT_AES,
            data, iv, fixed_salt, 1u, 16384u, 8u, 1u, targets, seen, err);
    }
    if (parts.size() == 6u && parts[0] == "$multibit$3") {
        uint64_t n64 = 0ull, r64 = 0ull, p64 = 0ull;
        if (!wallet_parse_u64_decimal(parts[1], n64) ||
            !wallet_parse_u64_decimal(parts[2], r64) ||
            !wallet_parse_u64_decimal(parts[3], p64) ||
            n64 == 0ull || n64 > std::numeric_limits<uint32_t>::max() ||
            r64 == 0ull || r64 > 8ull ||
            p64 == 0ull || p64 > std::numeric_limits<uint32_t>::max()) {
            err = "invalid MultiBit classic scrypt parameters";
            return false;
        }
        const uint32_t n = static_cast<uint32_t>(n64);
        if ((n & (n - 1u)) != 0u) {
            err = "unsupported MultiBit classic scrypt N";
            return false;
        }
        std::vector<uint8_t> salt, blob;
        if (!wallet_hex_to_bytes(parts[4], salt, dec_err) || salt.size() != 8u) {
            err = "invalid MultiBit classic scrypt salt";
            return false;
        }
        if (!wallet_hex_to_bytes(parts[5], blob, dec_err) || blob.size() != 32u) {
            err = "invalid MultiBit classic scrypt encrypted blob";
            return false;
        }
        std::vector<uint8_t> iv(blob.begin(), blob.begin() + 16);
        std::vector<uint8_t> data(blob.begin() + 16, blob.end());
        return wallet_add_multibit_target(source, BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_SCRYPT_AES,
            data, iv, salt, 1u, n, static_cast<uint32_t>(r64), static_cast<uint32_t>(p64), targets, seen, err);
    }
    err = "unsupported $multibit$ hash field count/version";
    return false;
}

static bool wallet_parse_multibitwallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$multibit$") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_multibit_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }
    if (added == 0u) {
        err = last_err.empty() ? "no usable $multibit$ hash target" : last_err;
        return false;
    }
    return true;
}

static bool wallet_parse_multibitwallet_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    return wallet_parse_multibitwallet_text(path, text, targets, seen, err);
}

static bool wallet_add_bisq_target(
    const std::string& source,
    const std::vector<uint8_t>& data,
    const std::vector<uint8_t>& iv,
    const std::vector<uint8_t>& salt,
    uint32_t scrypt_n,
    uint32_t scrypt_r,
    uint32_t scrypt_p,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    if (salt.size() != 8u || iv.size() != 16u || data.size() != 16u ||
        scrypt_n < 2u || (scrypt_n & (scrypt_n - 1u)) != 0u ||
        scrypt_r == 0u || scrypt_r > 8u || scrypt_p == 0u || scrypt_p > 16u) {
        err = "unsupported Bisq scrypt parameters/blob";
        return false;
    }

    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = BROWSERVAULT_PROFILE_BISQ_SCRYPT_AES;
    target.dev.iterations = 1u;
    target.dev.salt_len = 8u;
    target.dev.iv_len = 16u;
    target.dev.ciphertext_len = 16u;
    target.dev.scrypt_n = scrypt_n;
    target.dev.scrypt_r = scrypt_r;
    target.dev.scrypt_p = scrypt_p;
    memcpy(target.dev.salt, salt.data(), 8u);
    memcpy(target.dev.iv, iv.data(), 16u);
    target.ciphertext.assign(data.begin(), data.end());

    std::vector<uint8_t> hash_input;
    hash_input.reserve(data.size() + iv.size() + salt.size() + 24u);
    auto append_u32 = [&](uint32_t v) {
        hash_input.push_back(static_cast<uint8_t>(v & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((v >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((v >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((v >> 24) & 0xffu));
        };
    append_u32(BROWSERVAULT_PROFILE_BISQ_SCRYPT_AES);
    append_u32(scrypt_n);
    append_u32(scrypt_r);
    append_u32(scrypt_p);
    hash_input.insert(hash_input.end(), salt.begin(), salt.end());
    hash_input.push_back('|');
    hash_input.insert(hash_input.end(), iv.begin(), iv.end());
    hash_input.push_back('|');
    hash_input.insert(hash_input.end(), data.begin(), data.end());
    sha256(hash_input.data(), hash_input.size(), target.dev.vault_hash);
    const std::string key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
    if (!seen.insert(key).second) {
        err = "duplicate Bisq target";
        return false;
    }
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_bisq_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$bisq$", token)) {
        err = "no $bisq$ hash token";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token, '*');
    if (parts.size() == 6u && parts[0] == "$bisq$3") {
        uint64_t n64 = 0ull, r64 = 0ull, p64 = 0ull;
        if (!wallet_parse_u64_decimal(parts[1], n64) ||
            !wallet_parse_u64_decimal(parts[2], r64) ||
            !wallet_parse_u64_decimal(parts[3], p64) ||
            n64 == 0ull || n64 > std::numeric_limits<uint32_t>::max() ||
            r64 == 0ull || r64 > 8ull ||
            p64 == 0ull || p64 > 16ull) {
            err = "invalid Bisq scrypt parameters";
            return false;
        }
        const uint32_t n = static_cast<uint32_t>(n64);
        if ((n & (n - 1u)) != 0u) {
            err = "unsupported Bisq scrypt N";
            return false;
        }
        std::string dec_err;
        std::vector<uint8_t> salt, blob;
        if (!wallet_hex_to_bytes(parts[4], salt, dec_err) || salt.size() != 8u) {
            err = "invalid Bisq salt";
            return false;
        }
        if (!wallet_hex_to_bytes(parts[5], blob, dec_err) || blob.size() != 32u) {
            err = "invalid Bisq encrypted blob";
            return false;
        }
        std::vector<uint8_t> iv(blob.begin(), blob.begin() + 16);
        std::vector<uint8_t> data(blob.begin() + 16, blob.end());
        return wallet_add_bisq_target(source, data, iv, salt, n,
            static_cast<uint32_t>(r64), static_cast<uint32_t>(p64), targets, seen, err);
    }
    if (!parts.empty() && (parts[0] == "$bisq$1" || parts[0] == "$bisq$2")) {
        err = "Bisq v1/v2 hash is recognized but not enabled yet";
        return false;
    }
    err = "unsupported $bisq$ hash field count/version";
    return false;
}

static bool wallet_parse_bisqwallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$bisq$") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_bisq_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }
    if (added == 0u) {
        err = last_err.empty() ? "no usable $bisq$3 hash target" : last_err;
        return false;
    }
    return true;
}

static bool wallet_parse_bisqwallet_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
