}

static bool wallet_add_ethpresale_target(
    const std::string& source,
    const std::vector<uint8_t>& encseed,
    const uint8_t eth20[20],
    const uint8_t bkp16[16],
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    if (encseed.size() < 32u || (encseed.size() & 15u) != 0u ||
        encseed.size() - 16u > ETHPRESALE_MAX_ENCSEED_LEN) {
        err = "unsupported Ethereum presale encseed length";
        return false;
    }

    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = BROWSERVAULT_PROFILE_ETHPRESALE_PBKDF2_AES_CBC;
    target.dev.iterations = 2000u;
    target.dev.salt_len = 0u; // KDF salt is candidate password itself; target address is stored in salt bytes.
    target.dev.iv_len = 16u;
    memcpy(target.dev.iv, encseed.data(), 16u);
    memcpy(target.dev.salt, eth20, 20u);
    memcpy(target.dev.tag, bkp16, 16u);
    target.dev.ciphertext_len = static_cast<uint32_t>(encseed.size() - 16u);
    target.ciphertext.assign(encseed.begin() + 16, encseed.end());

    std::vector<uint8_t> hash_input;
    hash_input.reserve(encseed.size() + 20u + 16u + 8u);
    hash_input.insert(hash_input.end(), encseed.begin(), encseed.end());
    hash_input.push_back('|');
    hash_input.insert(hash_input.end(), eth20, eth20 + 20);
    hash_input.push_back('|');
    hash_input.insert(hash_input.end(), bkp16, bkp16 + 16);
    sha256(hash_input.data(), hash_input.size(), target.dev.vault_hash);
    const std::string key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
    if (!seen.insert(key).second) {
        err = "duplicate Ethereum presale target";
        return false;
    }
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_ethpresale_hash_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$ethereum$w", token)) {
        err = "no $ethereum$w hash token";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token, '*');
    if (parts.size() != 4u || parts[0] != "$ethereum$w") {
        err = "unsupported Ethereum presale hash field count";
        return false;
    }

    std::vector<uint8_t> encseed;
    std::string dec_err;
    if (!wallet_hex_to_bytes(parts[1], encseed, dec_err)) {
        err = "invalid Ethereum presale encseed: " + dec_err;
        return false;
    }
    uint8_t eth20[20];
    uint8_t bkp16[16];
    if (!wallet_hex_to_fixed(parts[2], eth20, 20u, dec_err)) {
        err = "invalid Ethereum presale ethaddr: " + dec_err;
        return false;
    }
    if (!wallet_hex_to_fixed(parts[3], bkp16, 16u, dec_err)) {
        err = "invalid Ethereum presale bkp: " + dec_err;
        return false;
    }
    return wallet_add_ethpresale_target(source, encseed, eth20, bkp16, targets, seen, err);
}

static bool wallet_parse_ethpresalewallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        if (line.find("$ethereum$w") == std::string::npos) {
            continue;
        }
        std::string e;
        std::ostringstream source;
        source << path << "#" << line_no;
        if (wallet_parse_ethpresale_hash_token(line, source.str(), targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }

    std::string encseed_hex, ethaddr_hex, bkp_hex;
    if (wallet_json_get_string(text, "encseed", encseed_hex) &&
        wallet_json_get_string(text, "ethaddr", ethaddr_hex) &&
        wallet_json_get_string(text, "bkp", bkp_hex)) {
        std::vector<uint8_t> encseed;
        uint8_t eth20[20];
        uint8_t bkp16[16];
        std::string e;
        if (wallet_hex_to_bytes(encseed_hex, encseed, e) &&
            wallet_hex_to_fixed(ethaddr_hex, eth20, 20u, e) &&
            wallet_hex_to_fixed(bkp_hex, bkp16, 16u, e) &&
            wallet_add_ethpresale_target(path, encseed, eth20, bkp16, targets, seen, e)) {
            ++added;
        }
        else if (!e.empty()) {
            last_err = e;
        }
    }

    if (added == 0u) {
        err = last_err.empty() ? "no usable Ethereum presale target" : last_err;
        return false;
    }
    return true;
}

static bool wallet_parse_ethpresalewallet_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    return wallet_parse_ethpresalewallet_text(path, text, targets, seen, err);
}

static bool wallet_add_bip38_non_ec_target(
    const std::string& source,
    const uint8_t flag,
    const uint8_t address_hash4[4],
    const uint8_t encrypted32[32],
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    if (flag != 0xc0u && flag != 0xe0u) {
        err = "unsupported BIP38 non-EC flag byte";
        return false;
    }
    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = BROWSERVAULT_PROFILE_BIP38_NON_EC;
    target.dev.iterations = 1u;
    target.dev.salt_len = 4u;
    target.dev.iv_len = 1u;
    target.dev.ciphertext_len = 32u;
    target.dev.scrypt_n = 16384u;
    target.dev.scrypt_r = 8u;
    target.dev.scrypt_p = 8u;
    memcpy(target.dev.salt, address_hash4, 4u);
    target.dev.iv[0] = flag;
    target.ciphertext.assign(encrypted32, encrypted32 + 32u);

    std::vector<uint8_t> hash_input;
    hash_input.reserve(64u);
    hash_input.push_back(static_cast<uint8_t>(BROWSERVAULT_PROFILE_BIP38_NON_EC));
    hash_input.push_back(flag);
    hash_input.insert(hash_input.end(), address_hash4, address_hash4 + 4u);
    hash_input.insert(hash_input.end(), encrypted32, encrypted32 + 32u);
    sha256(hash_input.data(), hash_input.size(), target.dev.vault_hash);
    const std::string key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
    if (!seen.insert(key).second) {
        err = "duplicate BIP38 target";
        return false;
    }
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_add_bip38_ec_target(
    const std::string& source,
    const uint8_t flag,
    const uint8_t address_hash4[4],
    const uint8_t owner_entropy8[8],
    const uint8_t encrypted_part1_first8[8],
    const uint8_t encrypted_part2[16],
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    if ((flag & ~(0x20u | 0x04u)) != 0u) {
        err = "unsupported BIP38 EC flag byte";
        return false;
    }
    BrowserVaultHostTarget target;
    target.file = source;
    target.dev.profile = BROWSERVAULT_PROFILE_BIP38_EC;
    target.dev.iterations = 1u;
    target.dev.salt_len = 12u;
    target.dev.iv_len = 1u;
    target.dev.ciphertext_len = 24u;
    target.dev.scrypt_n = 16384u;
    target.dev.scrypt_r = 8u;
    target.dev.scrypt_p = 8u;
    memcpy(target.dev.salt, address_hash4, 4u);
    memcpy(target.dev.salt + 4u, owner_entropy8, 8u);
    target.dev.iv[0] = flag;
    target.ciphertext.reserve(24u);
    target.ciphertext.insert(target.ciphertext.end(), encrypted_part1_first8, encrypted_part1_first8 + 8u);
    target.ciphertext.insert(target.ciphertext.end(), encrypted_part2, encrypted_part2 + 16u);

    std::vector<uint8_t> hash_input;
    hash_input.reserve(64u);
    hash_input.push_back(static_cast<uint8_t>(BROWSERVAULT_PROFILE_BIP38_EC));
    hash_input.push_back(flag);
    hash_input.insert(hash_input.end(), address_hash4, address_hash4 + 4u);
    hash_input.insert(hash_input.end(), owner_entropy8, owner_entropy8 + 8u);
    hash_input.insert(hash_input.end(), encrypted_part1_first8, encrypted_part1_first8 + 8u);
    hash_input.insert(hash_input.end(), encrypted_part2, encrypted_part2 + 16u);
    sha256(hash_input.data(), hash_input.size(), target.dev.vault_hash);
    const std::string key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
    if (!seen.insert(key).second) {
        err = "duplicate BIP38 target";
        return false;
    }
    targets.push_back(std::move(target));
    return true;
}

static bool wallet_parse_bip38_token(
    const std::string& token_raw,
    const std::string& source,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string token = wallet_trim_copy(token_raw);
    while (!token.empty() && (token.back() == ',' || token.back() == ';' || token.back() == ':' ||
        token.back() == '"' || token.back() == '\'' || token.back() == ')' || token.back() == ']')) {
        token.pop_back();
    }
    while (!token.empty() && (token.front() == '"' || token.front() == '\'' || token.front() == '(' || token.front() == '[')) {
        token.erase(token.begin());
    }
    if (token.size() < 10u || token.rfind("6P", 0) != 0) {
        err = "no BIP38 6P token";
        return false;
    }
    uint8_t payload[124] = { 0 };
    size_t payload_len = 0u;
    if (!wallet_scan_b58check_decode_payload(token, payload, payload_len)) {
        err = "invalid BIP38 Base58Check payload";
        return false;
    }
    if (payload_len != 39u || payload[0] != 0x01u) {
        err = "unsupported BIP38 payload length/signature";
        return false;
    }
    if (payload[1] == 0x43u) {
        const uint8_t flag = payload[2];
        return wallet_add_bip38_ec_target(source, flag, payload + 3u, payload + 7u,
            payload + 15u, payload + 23u, targets, seen, err);
    }
    if (payload[1] != 0x42u) {
        err = "unsupported BIP38 type";
        return false;
    }
    const uint8_t flag = payload[2];
    if (flag != 0xc0u && flag != 0xe0u) {
        err = "unsupported BIP38 non-EC flag";
        return false;
    }
    return wallet_add_bip38_non_ec_target(source, flag, payload + 3u, payload + 7u, targets, seen, err);
}

static bool wallet_parse_bip38wallet_text(
    const std::string& path,
    const std::string& text,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    size_t added = 0u;
    std::istringstream iss(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(iss, line)) {
        ++line_no;
        const std::string trimmed = wallet_trim_copy(line);
        if (trimmed.empty() || trimmed[0] == '#') continue;
        size_t p = 0u;
        while ((p = trimmed.find("6P", p)) != std::string::npos) {
            size_t end = p;
            while (end < trimmed.size() && wallet_base58_value(static_cast<unsigned char>(trimmed[end])) >= 0) {
                ++end;
            }
            std::string token = trimmed.substr(p, end - p);
            std::string e;
            std::ostringstream source;
            source << path << "#" << line_no;
            if (wallet_parse_bip38_token(token, source.str(), targets, seen, e)) {
                ++added;
            }
            else if (!e.empty()) {
                last_err = e;
            }
            p = end > p ? end : p + 2u;
        }
    }
    if (added == 0u) {
        err = last_err.empty() ? "no usable BIP38 encrypted key" : last_err;
        return false;
    }
    return true;
}

static bool wallet_parse_bip38wallet_file(const std::string& path,
    std::vector<BrowserVaultHostTarget>& targets,
    std::unordered_set<std::string>& seen,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    return wallet_parse_bip38wallet_text(path, text, targets, seen, err);
}

static inline uint32_t wallet_load_be32_host(const uint8_t* p) {
    return (static_cast<uint32_t>(p[0]) << 24) |
        (static_cast<uint32_t>(p[1]) << 16) |
        (static_cast<uint32_t>(p[2]) << 8) |
        static_cast<uint32_t>(p[3]);
}

static bool wallet_parse_exodusseco_file(const std::string& path,
    ExodusSecoHostTarget& target,
    std::string& err)
{
    std::vector<uint8_t> data;
    if (!mac_read_binary_file(path, data, err)) {
        return false;
    }
    static constexpr size_t kHeaderSize = 224u;
    static constexpr size_t kChecksumSize = 32u;
    static constexpr size_t kMetadataSize = 256u;
    static constexpr size_t kChecksumOff = kHeaderSize;
    static constexpr size_t kMetadataOff = kHeaderSize + kChecksumSize;
    static constexpr size_t kBlobLenOff = kMetadataOff + kMetadataSize;
    static constexpr size_t kBlobOff = kBlobLenOff + 4u;
    if (data.size() < kBlobOff || memcmp(data.data(), "SECO", 4u) != 0) {
        err = "not Exodus SECO container";
        return false;
    }
    if (wallet_load_be32_host(data.data() + 4u) != 0u) {
        err = "unsupported SECO version";
        return false;
    }
    const uint8_t tag_len = data[12];
    if (13u + tag_len > kHeaderSize ||
        tag_len != 18u ||
        memcmp(data.data() + 13u, "seco-v0-scrypt-aes", 18u) != 0) {
        err = "unsupported SECO version tag";
        return false;
    }
    const uint32_t blob_len = wallet_load_be32_host(data.data() + kBlobLenOff);
    if (blob_len == 0u || kBlobOff + static_cast<size_t>(blob_len) != data.size()) {
        err = "invalid SECO blob length";
        return false;
    }

    std::vector<uint8_t> checksum_input;
    checksum_input.reserve(kMetadataSize + 4u + blob_len);
    checksum_input.insert(checksum_input.end(), data.begin() + kMetadataOff, data.begin() + kMetadataOff + kMetadataSize);
    checksum_input.insert(checksum_input.end(), data.begin() + kBlobLenOff, data.end());
    uint8_t checksum[32];
    sha256(checksum_input.data(), checksum_input.size(), checksum);
    if (memcmp(checksum, data.data() + kChecksumOff, 32u) != 0) {
        err = "SECO checksum mismatch";
        return false;
    }

    const uint8_t* meta = data.data() + kMetadataOff;
    const uint32_t n = wallet_load_be32_host(meta + 32u);
    const uint32_t r = wallet_load_be32_host(meta + 36u);
    const uint32_t p = wallet_load_be32_host(meta + 40u);
    if (n < 2u || (n & (n - 1u)) != 0u || r == 0u || r > 8u || p == 0u) {
        err = "unsupported SECO scrypt parameters";
        return false;
    }
    if (memcmp(meta + 44u, "aes-256-gcm", 11u) != 0) {
        err = "unsupported SECO cipher";
        return false;
    }

    target = ExodusSecoHostTarget{};
    target.file = path;
    target.dev.scrypt_n = n;
    target.dev.scrypt_r = r;
    target.dev.scrypt_p = p;
    target.dev.salt_len = 32u;
    memcpy(target.dev.salt, meta, 32u);
    memcpy(target.dev.key_iv, meta + 76u, 12u);
    memcpy(target.dev.key_tag, meta + 88u, 16u);
    memcpy(target.dev.encrypted_key, meta + 104u, 32u);
    sha256(data.data(), data.size(), target.dev.vault_hash);
    return true;
}

static bool wallet_proto_read_varint(const std::vector<uint8_t>& data, size_t pos, const size_t end, uint64_t& value, size_t& next)
{
    value = 0;
    uint32_t shift = 0;
    while (pos < end && shift <= 63u) {
        const uint8_t b = data[pos++];
        value |= (static_cast<uint64_t>(b & 0x7fu) << shift);
        if ((b & 0x80u) == 0u) {
            next = pos;
            return true;
        }
        shift += 7u;
    }
    return false;
}

static bool wallet_proto_skip_field(const std::vector<uint8_t>& data, size_t pos, const size_t end, const uint32_t wire, size_t& next)
{
    if (wire == 0u) {
        uint64_t v = 0;
        return wallet_proto_read_varint(data, pos, end, v, next);
    }
    if (wire == 1u) {
        if (pos + 8u > end) return false;
        next = pos + 8u;
        return true;
    }
    if (wire == 2u) {
        uint64_t len = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return false;
        next = p + static_cast<size_t>(len);
        return true;
    }
    if (wire == 5u) {
        if (pos + 4u > end) return false;
        next = pos + 4u;
        return true;
    }
    return false;
}

struct BitcoinJParsedScrypt {
    std::vector<uint8_t> salt;
    uint32_t n = 16384u;
    uint32_t r = 8u;
    uint32_t p = 1u;
};

struct BitcoinJParsedKey {
    std::vector<uint8_t> pubkey;
    std::vector<uint8_t> iv;
    std::vector<uint8_t> encrypted_key;
    bool encrypted = false;
};

static bool wallet_bitcoinj_parse_scrypt_params(
    const std::vector<uint8_t>& data,
    size_t pos,
    const size_t end,
    BitcoinJParsedScrypt& out)
{
    while (pos < end) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, end, tag, p)) return false;
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        pos = p;
        if (field == 1u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return false;
            out.salt.assign(data.begin() + static_cast<std::ptrdiff_t>(p),
                data.begin() + static_cast<std::ptrdiff_t>(p + static_cast<size_t>(len)));
            pos = p + static_cast<size_t>(len);
        }
        else if ((field == 2u || field == 3u || field == 4u) && wire == 0u) {
            uint64_t v = 0;
            if (!wallet_proto_read_varint(data, pos, end, v, p)) return false;
            if (v > std::numeric_limits<uint32_t>::max()) return false;
            if (field == 2u) out.n = static_cast<uint32_t>(v);
            if (field == 3u) out.r = static_cast<uint32_t>(v);
            if (field == 4u) out.p = static_cast<uint32_t>(v);
            pos = p;
        }
        else {
            if (!wallet_proto_skip_field(data, pos, end, wire, p)) return false;
            pos = p;
        }
    }
    return true;
}

static bool wallet_bitcoinj_parse_encrypted_data(
    const std::vector<uint8_t>& data,
    size_t pos,
    const size_t end,
    BitcoinJParsedKey& out)
{
    while (pos < end) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, end, tag, p)) return false;
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        pos = p;
        if ((field == 1u || field == 2u) && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return false;
            std::vector<uint8_t>& dst = (field == 1u) ? out.iv : out.encrypted_key;
            dst.assign(data.begin() + static_cast<std::ptrdiff_t>(p),
                data.begin() + static_cast<std::ptrdiff_t>(p + static_cast<size_t>(len)));
            pos = p + static_cast<size_t>(len);
        }
        else {
            if (!wallet_proto_skip_field(data, pos, end, wire, p)) return false;
            pos = p;
        }
    }
    return true;
}

static bool wallet_bitcoinj_parse_key_message(
    const std::vector<uint8_t>& data,
    size_t pos,
    const size_t end,
    BitcoinJParsedKey& out)
{
    uint64_t key_type = 0;
    bool have_type = false;
    while (pos < end) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, end, tag, p)) return false;
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        pos = p;
        if (field == 1u && wire == 0u) {
            if (!wallet_proto_read_varint(data, pos, end, key_type, p)) return false;
            have_type = true;
            pos = p;
        }
        else if (field == 3u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return false;
            BitcoinJParsedKey encrypted_probe;
            if (wallet_bitcoinj_parse_encrypted_data(data, p, p + static_cast<size_t>(len), encrypted_probe) &&
                encrypted_probe.iv.size() == 16u &&
                !encrypted_probe.encrypted_key.empty() &&
                (encrypted_probe.encrypted_key.size() & 15u) == 0u) {
                out.iv = std::move(encrypted_probe.iv);
                out.encrypted_key = std::move(encrypted_probe.encrypted_key);
            }
            else {
                out.pubkey.assign(data.begin() + static_cast<std::ptrdiff_t>(p),
                    data.begin() + static_cast<std::ptrdiff_t>(p + static_cast<size_t>(len)));
            }
            pos = p + static_cast<size_t>(len);
        }
        else if (field == 4u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return false;
            out.pubkey.assign(data.begin() + static_cast<std::ptrdiff_t>(p),
                data.begin() + static_cast<std::ptrdiff_t>(p + static_cast<size_t>(len)));
            pos = p + static_cast<size_t>(len);
        }
        else if (field == 6u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return false;
            BitcoinJParsedKey encrypted_probe;
            if (!wallet_bitcoinj_parse_encrypted_data(data, p, p + static_cast<size_t>(len), encrypted_probe)) return false;
            if (encrypted_probe.iv.size() == 16u &&
                !encrypted_probe.encrypted_key.empty() &&
                (encrypted_probe.encrypted_key.size() & 15u) == 0u) {
                out.iv = std::move(encrypted_probe.iv);
                out.encrypted_key = std::move(encrypted_probe.encrypted_key);
            }
            pos = p + static_cast<size_t>(len);
        }
        else {
            if (!wallet_proto_skip_field(data, pos, end, wire, p)) return false;
            pos = p;
        }
    }
    out.encrypted = (!have_type || key_type == 2u || key_type == 4u) && !out.iv.empty() && !out.encrypted_key.empty();
    return true;
}

static void wallet_bitcoinj_append_u32(std::string& key, const uint32_t v)
{
    key.push_back(static_cast<char>(v & 0xffu));
    key.push_back(static_cast<char>((v >> 8) & 0xffu));
    key.push_back(static_cast<char>((v >> 16) & 0xffu));
    key.push_back(static_cast<char>((v >> 24) & 0xffu));
}

static std::string wallet_bitcoinj_target_key(const BitcoinJWalletTarget& t)
{
    std::string key;
    key.reserve(32u + t.salt_len + t.encrypted_key_len + t.pubkey_len);
    wallet_bitcoinj_append_u32(key, t.scrypt_n);
    wallet_bitcoinj_append_u32(key, t.scrypt_r);
    wallet_bitcoinj_append_u32(key, t.scrypt_p);
    key.append(reinterpret_cast<const char*>(t.salt), reinterpret_cast<const char*>(t.salt) + t.salt_len);
    key.append(reinterpret_cast<const char*>(t.iv), reinterpret_cast<const char*>(t.iv) + 16u);
    key.append(reinterpret_cast<const char*>(t.encrypted_key), reinterpret_cast<const char*>(t.encrypted_key) + t.encrypted_key_len);
    key.append(reinterpret_cast<const char*>(t.pubkey), reinterpret_cast<const char*>(t.pubkey) + t.pubkey_len);
    return key;
}

static bool wallet_bitcoinj_scrypt_supported(const BitcoinJParsedScrypt& scrypt)
{
    return !scrypt.salt.empty() &&
        scrypt.salt.size() <= WALLET_MAX_SALT_LEN &&
        scrypt.n >= 2u &&
        (scrypt.n & (scrypt.n - 1u)) == 0u &&
        scrypt.r != 0u &&
        scrypt.r <= 8u &&
        scrypt.p != 0u;
}

static bool wallet_bitcoinj_try_parse_scrypt_params(
    const std::vector<uint8_t>& data,
    const size_t pos,
    const size_t end,
    BitcoinJParsedScrypt& out)
{
    BitcoinJParsedScrypt candidate;
    if (!wallet_bitcoinj_parse_scrypt_params(data, pos, end, candidate)) {
        return false;
    }
    if (!wallet_bitcoinj_scrypt_supported(candidate)) {
        return false;
    }
    out = std::move(candidate);
    return true;
}

static void wallet_bitcoinj_collect_coinomi_keys_from_record(
    const std::vector<uint8_t>& data,
    size_t pos,
    const size_t end,
    std::vector<BitcoinJParsedKey>& keys)
{
    while (pos < end) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, end, tag, p)) return;
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        pos = p;
        if (field == 2u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return;
            BitcoinJParsedKey key;
            if (wallet_bitcoinj_parse_key_message(data, p, p + static_cast<size_t>(len), key) && key.encrypted) {
                keys.push_back(std::move(key));
            }
            pos = p + static_cast<size_t>(len);
        }
        else {
            if (!wallet_proto_skip_field(data, pos, end, wire, p)) return;
            pos = p;
        }
    }
}

static void wallet_bitcoinj_collect_coinomi_keys(
    const std::vector<uint8_t>& data,
    size_t pos,
    const size_t end,
    std::vector<BitcoinJParsedKey>& keys)
{
    while (pos < end) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, end, tag, p)) return;
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        pos = p;
        if (field == 11u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, end, len, p) || len > static_cast<uint64_t>(end - p)) return;
            wallet_bitcoinj_collect_coinomi_keys_from_record(data, p, p + static_cast<size_t>(len), keys);
            pos = p + static_cast<size_t>(len);
        }
        else {
            if (!wallet_proto_skip_field(data, pos, end, wire, p)) return;
            pos = p;
        }
    }
}

static bool wallet_parse_bitcoinjwallet_file(const std::string& path,
    std::vector<BitcoinJWalletHostTarget>& out,
    std::string& err)
{
    std::vector<uint8_t> data;
    if (!mac_read_binary_file(path, data, err)) {
        return false;
    }
    if (data.size() < 16u || wallet_file_starts_with_armory_magic(path)) {
        err = "not a bitcoinj protobuf wallet";
        return false;
    }

    BitcoinJParsedScrypt scrypt;
    std::vector<BitcoinJParsedKey> keys;
    uint64_t encryption_type = 0;
    bool have_encryption_type = false;
    size_t pos = 0;
    while (pos < data.size()) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, data.size(), tag, p)) {
            err = "invalid protobuf varint";
            return false;
        }
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        pos = p;
        if (field == 3u && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, data.size(), len, p) || len > static_cast<uint64_t>(data.size() - p)) {
                err = "invalid bitcoinj key message length";
                return false;
            }
            BitcoinJParsedKey key;
            if (wallet_bitcoinj_parse_key_message(data, p, p + static_cast<size_t>(len), key) && key.encrypted) {
                keys.push_back(std::move(key));
            }
            pos = p + static_cast<size_t>(len);
        }
        else if ((field == 4u || field == 5u) && wire == 0u) {
            if (!wallet_proto_read_varint(data, pos, data.size(), encryption_type, p)) {
                err = "invalid bitcoinj encryption type";
                return false;
            }
            have_encryption_type = true;
            pos = p;
        }
        else if ((field == 5u || field == 6u) && wire == 2u) {
            uint64_t len = 0;
            if (!wallet_proto_read_varint(data, pos, data.size(), len, p) || len > static_cast<uint64_t>(data.size() - p)) {
                err = "invalid bitcoinj scrypt parameter length";
                return false;
            }
            const size_t msg_begin = p;
            const size_t msg_end = p + static_cast<size_t>(len);
            if (!wallet_bitcoinj_try_parse_scrypt_params(data, msg_begin, msg_end, scrypt)) {
                if (field == 6u) {
                    wallet_bitcoinj_collect_coinomi_keys(data, msg_begin, msg_end, keys);
                }
            }
            pos = msg_end;
        }
        else {
            if (!wallet_proto_skip_field(data, pos, data.size(), wire, p)) {
                err = "invalid protobuf field";
                return false;
            }
            pos = p;
        }
    }

    if (keys.empty()) {
        err = "no encrypted bitcoinj key targets";
        return false;
    }
    if (have_encryption_type && encryption_type != 2u) {
        err = "unsupported bitcoinj encryption type";
        return false;
    }
    if (!wallet_bitcoinj_scrypt_supported(scrypt)) {
        err = "unsupported bitcoinj scrypt parameters";
        return false;
    }

    uint8_t wallet_hash[32];
    sha256(data.data(), data.size(), wallet_hash);
    std::unordered_set<std::string> seen;
    for (const BitcoinJParsedKey& key : keys) {
        if (key.iv.size() != 16u ||
            key.encrypted_key.empty() || key.encrypted_key.size() > WALLETDAT_MAX_CRYPTED_KEY_LEN ||
            (key.encrypted_key.size() & 15u) != 0u ||
            (key.pubkey.size() != 33u && key.pubkey.size() != 65u)) {
            continue;
        }
        BitcoinJWalletHostTarget target;
        target.file = path;
        target.dev.scrypt_n = scrypt.n;
        target.dev.scrypt_r = scrypt.r;
        target.dev.scrypt_p = scrypt.p;
        target.dev.salt_len = static_cast<uint32_t>(scrypt.salt.size());
        target.dev.encrypted_key_len = static_cast<uint32_t>(key.encrypted_key.size());
        target.dev.pubkey_len = static_cast<uint32_t>(key.pubkey.size());
        memcpy(target.dev.salt, scrypt.salt.data(), scrypt.salt.size());
        memcpy(target.dev.iv, key.iv.data(), 16u);
        memcpy(target.dev.encrypted_key, key.encrypted_key.data(), key.encrypted_key.size());
        memcpy(target.dev.pubkey, key.pubkey.data(), key.pubkey.size());
        memcpy(target.dev.wallet_hash, wallet_hash, 32u);
        std::string dedup = wallet_bitcoinj_target_key(target.dev);
        if (!seen.insert(std::move(dedup)).second) {
            continue;
        }
        out.push_back(std::move(target));
    }
    if (out.empty()) {
        err = "bitcoinj wallet has no supported encrypted key targets";
        return false;
    }
    return true;
}

static std::string wallet_compact_ascii_copy(const std::string& text) {
    std::string out;
    out.reserve(text.size());
    for (unsigned char c : text) {
        if (!std::isspace(c)) {
            out.push_back(static_cast<char>(c));
        }
    }
    return out;
}

static bool wallet_parse_electrumwallet_file(const std::string& path,
    ElectrumWalletHostTarget& out,
    bool& unsupported_bie2,
    std::string& err)
{
    unsupported_bie2 = false;
    if (wallet_file_starts_with_armory_magic(path)) {
        err = "Armory wallet file, not Electrum";
        return false;
    }
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    std::string compact = wallet_compact_ascii_copy(text);
    if (!compact.empty() && compact.front() == '"' && compact.back() == '"' && compact.size() > 2u) {
        compact = compact.substr(1u, compact.size() - 2u);
    }
    const bool looks_like_electrum_json = text.find('{') != std::string::npos &&
        (text.find("\"wallet_type\"") != std::string::npos ||
            text.find("\"keystore\"") != std::string::npos ||
            text.find("\"seed\"") != std::string::npos);
    const bool electrum_json_encrypted =
        text.find("\"use_encryption\": true") != std::string::npos ||
        text.find("\"use_encryption\":true") != std::string::npos;
    if (looks_like_electrum_json && !electrum_json_encrypted) {
        ElectrumWalletHostTarget target;
        target.file = path;
        target.dev.kind = ELECTRUMWALLET_TARGET_PLAINTEXT;
        sha256(const_cast<uint8_t*>(reinterpret_cast<const uint8_t*>(text.data())), text.size(), target.dev.detail_hash);
        out = target;
        return true;
    }
    if (looks_like_electrum_json && electrum_json_encrypted) {
        uint32_t pw_hash_version = 1u;
        (void)wallet_json_get_u32(text, "pw_hash_version", pw_hash_version);
        if (pw_hash_version != 1u) {
            err = "Electrum JSON encrypted field uses unsupported pw_hash_version";
            return false;
        }

        std::string encrypted_field;
        uint8_t field_subtype = 0u; // 1=xprv, 2=seed
        if (wallet_json_get_string(text, "xprv", encrypted_field) && !encrypted_field.empty()) {
            field_subtype = 1u;
        }
        else if (wallet_json_get_string(text, "seed", encrypted_field) && !encrypted_field.empty()) {
            field_subtype = 2u;
        }
        else {
            err = "Electrum JSON encrypted fields found but no supported seed/xprv field";
            return false;
        }

        std::vector<uint8_t> raw_field;
        if (!wallet_base64_to_bytes(encrypted_field, raw_field, err)) {
            return false;
        }
        if (raw_field.size() < 32u || ((raw_field.size() - 16u) & 15u) != 0u) {
            err = "Electrum encrypted field has invalid AES-CBC length";
            return false;
        }
        if ((raw_field.size() - 16u) > WALLETDAT_MAX_CRYPTED_KEY_LEN) {
            err = "Electrum encrypted field exceeds supported inline decrypt length";
            return false;
        }

        ElectrumWalletHostTarget target;
        target.file = path;
        target.dev.kind = ELECTRUMWALLET_TARGET_FIELD_V1;
        target.dev.ciphertext_len = static_cast<uint32_t>(raw_field.size() - 16u);
        memcpy(target.dev.ephemeral_pubkey, raw_field.data(), 16u); // IV for FIELD_V1.
        target.dev.mac[0] = field_subtype;
        target.ciphertext.assign(raw_field.begin() + 16u, raw_field.end());
        sha256(raw_field.data(), raw_field.size(), target.dev.detail_hash);
        out = target;
        return true;
    }
    std::vector<uint8_t> raw;
    if (!wallet_base64_to_bytes(compact, raw, err)) {
        return false;
    }
    if (raw.size() < 4u) {
        err = "decoded Electrum payload is too short";
        return false;
    }
    if (raw.size() >= 4u && memcmp(raw.data(), "BIE2", 4u) == 0) {
        unsupported_bie2 = true;
        err = "BIE2 storage is detected but unsupported in this brute path";
        return false;
    }
    if (memcmp(raw.data(), "BIE1", 4u) != 0) {
        err = "not Electrum BIE1 storage";
        return false;
    }
    if (raw.size() < 4u + 33u + 32u + 1u) {
        err = "BIE1 payload is too short";
        return false;
    }
    const size_t ciphertext_len = raw.size() - 4u - 33u - 32u;
    if (ciphertext_len == 0u || ciphertext_len > ELECTRUMWALLET_MAX_BLOB_LEN) {
        err = "BIE1 ciphertext length exceeds supported cap";
        return false;
    }
    if ((ciphertext_len & 15u) != 0u) {
        err = "BIE1 ciphertext length is not AES-CBC block aligned";
        return false;
    }
    ElectrumWalletHostTarget target;
    target.file = path;
    target.dev.kind = ELECTRUMWALLET_TARGET_BIE1;
    target.dev.ciphertext_len = static_cast<uint32_t>(ciphertext_len);
    memcpy(target.dev.ephemeral_pubkey, raw.data() + 4u, 33u);
    target.ciphertext.assign(raw.begin() + 4u + 33u, raw.begin() + 4u + 33u + ciphertext_len);
    memcpy(target.dev.mac, raw.data() + 4u + 33u + ciphertext_len, 32u);
    sha256(raw.data(), raw.size(), target.dev.detail_hash);
    out = target;
    return true;
}

static bool wallet_parse_armorywallet_file(
    const std::string& path,
    ArmoryWalletHostTarget& out,
    bool& unencrypted,
    std::string& err)
{
    unencrypted = false;
    std::vector<uint8_t> raw;
    if (!mac_read_binary_file(path, raw, err)) {
        return false;
    }
    constexpr size_t ARMORY_HEADER_SIZE = 8u + 4u + 4u + 8u + 6u + 8u + 32u + 256u + 8u + 256u + 256u;
    constexpr size_t ARMORY_ADDR_RECORD_SIZE = 237u;
    constexpr size_t ARMORY_KDF_OFFSET = 8u + 4u + 4u + 8u + 6u + 8u + 32u + 256u + 8u;
    if (!wallet_scan_is_armory_wallet_raw(raw) || raw.size() < ARMORY_HEADER_SIZE + ARMORY_ADDR_RECORD_SIZE) {
        err = "not an Armory BA WALLET file";
        return false;
    }
    const uint64_t wallet_flags = wallet_scan_le64(raw.data() + 16u);
    if ((wallet_flags & 0x01ull) == 0ull) {
        unencrypted = true;
        err = "Armory wallet is plaintext; use -walletscan to extract keys";
        return false;
    }

    const uint8_t* kdf = raw.data() + ARMORY_KDF_OFFSET;
    const uint8_t* kdf_data = kdf;
    const uint8_t* kdf_chk = kdf + 44u;
    if (!wallet_scan_hash256_checksum4_ok(kdf_data, 44u, kdf_chk)) {
        err = "Armory KDF params checksum mismatch";
        return false;
    }
    const uint64_t kdf_mem64 = wallet_scan_le64(kdf_data);
    const uint32_t kdf_iterations = static_cast<uint32_t>(
        static_cast<uint32_t>(kdf_data[8]) |
        (static_cast<uint32_t>(kdf_data[9]) << 8) |
        (static_cast<uint32_t>(kdf_data[10]) << 16) |
        (static_cast<uint32_t>(kdf_data[11]) << 24));
    if (kdf_mem64 < 64ull || kdf_mem64 > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) ||
        (kdf_mem64 & 63ull) != 0ull) {
        err = "unsupported Armory KDF memory size";
        return false;
    }
    if (kdf_iterations == 0u) {
        err = "invalid Armory KDF iteration count";
        return false;
    }

    const uint8_t* rec = raw.data() + ARMORY_HEADER_SIZE;
    const uint8_t* addr20 = rec + 0u;
    const uint8_t* addr_chk = rec + 20u;
    const uint64_t addr_flags = wallet_scan_le64(rec + 28u);
    const uint8_t* chain32 = rec + 36u;
    const uint8_t* chain_chk = rec + 68u;
    const uint8_t* iv16 = rec + 88u;
    const uint8_t* iv_chk = rec + 104u;
    const uint8_t* enc_priv32 = rec + 108u;
    const uint8_t* enc_priv_chk = rec + 140u;
    const uint8_t* pub65 = rec + 144u;
    const uint8_t* pub_chk = rec + 209u;
    const bool has_priv = (addr_flags & 0x01ull) != 0ull;
    const bool has_pub = (addr_flags & 0x02ull) != 0ull;
    const bool encrypted_priv = (addr_flags & 0x04ull) != 0ull;
    if (!has_priv || !has_pub || !encrypted_priv) {
        err = "Armory root record is not an encrypted private-key record";
        return false;
    }
    if (!wallet_scan_hash256_checksum4_ok(addr20, 20u, addr_chk) ||
        !wallet_scan_hash256_checksum4_ok(chain32, 32u, chain_chk) ||
        !wallet_scan_hash256_checksum4_ok(iv16, 16u, iv_chk) ||
        !wallet_scan_hash256_checksum4_ok(enc_priv32, 32u, enc_priv_chk) ||
        !wallet_scan_hash256_checksum4_ok(pub65, 65u, pub_chk) ||
        !wallet_scan_armory_pubkey_matches_addr160(pub65, addr20)) {
        err = "Armory root record checksum/pubkey validation failed";
        return false;
    }

    ArmoryWalletHostTarget target;
    target.file = path;
    target.dev.kdf_mem = static_cast<uint32_t>(kdf_mem64);
    target.dev.kdf_iterations = kdf_iterations;
    memcpy(target.dev.salt, kdf_data + 12u, 32u);
    memcpy(target.dev.iv, iv16, 16u);
    memcpy(target.dev.encrypted_priv, enc_priv32, 32u);
    memcpy(target.dev.pubkey, pub65, 65u);
    memcpy(target.dev.addr160, addr20, 20u);
    sha256(raw.data(), raw.size(), target.dev.wallet_hash);
    out = std::move(target);
    return true;
}

static std::string wallet_armory_target_key(const ArmoryWalletTarget& t)
{
    std::string key;
    key.reserve(4u + 4u + 32u + 16u + 32u + 65u);
    auto append_u32 = [&](const uint32_t v) {
        key.push_back(static_cast<char>(v & 0xffu));
        key.push_back(static_cast<char>((v >> 8) & 0xffu));
        key.push_back(static_cast<char>((v >> 16) & 0xffu));
        key.push_back(static_cast<char>((v >> 24) & 0xffu));
        };
    append_u32(t.kdf_mem);
    append_u32(t.kdf_iterations);
    key.append(reinterpret_cast<const char*>(t.salt), reinterpret_cast<const char*>(t.salt) + 32u);
    key.append(reinterpret_cast<const char*>(t.iv), reinterpret_cast<const char*>(t.iv) + 16u);
    key.append(reinterpret_cast<const char*>(t.encrypted_priv), reinterpret_cast<const char*>(t.encrypted_priv) + 32u);
    key.append(reinterpret_cast<const char*>(t.pubkey), reinterpret_cast<const char*>(t.pubkey) + 65u);
    return key;
}

static BrowserVaultLoadFileResult wallet_load_one_browservault_file(const std::string& path)
{
    BrowserVaultLoadFileResult result;
    result.path = path;
    if (!mac_is_regular_file(path)) {
        result.skipped = true;
        result.err = "not a regular file";
        return result;
    }
    std::unordered_set<std::string> local_seen;
    if (!wallet_parse_browservault_file(path, result.targets, local_seen, result.err)) {
        result.skipped = true;
        return result;
    }
    for (BrowserVaultHostTarget& target : result.targets) {
        if (target.file.empty()) target.file = path;
    }
    result.loaded = !result.targets.empty();
    result.skipped = !result.loaded;
    if (result.skipped && result.err.empty()) {
        result.err = "no usable browser vault targets";
    }
    return result;
}

