static bool wallet_bitcoinj_is_obvious_noise_path(const std::string& path)
{
    const std::string l = wallet_lower_copy(path);
    const size_t slash = l.find_last_of('/');
    const std::string name = slash == std::string::npos ? l : l.substr(slash + 1u);

    if (name == "current" || name == "lock" || name == "log" || name == "journal") return true;
    if (name.rfind("manifest-", 0) == 0) return true;
    if (name.rfind("data_", 0) == 0 || name.rfind("f_", 0) == 0) return true;
    if (l.find("/cache/") != std::string::npos) return true;
    if (l.find("/local extension settings/") != std::string::npos) return true;
    return false;
}

static bool wallet_bitcoinj_quick_protobuf_candidate(const std::vector<uint8_t>& data)
{
    if (data.size() < 16u) return false;

    size_t pos = 0;
    uint32_t parsed_fields = 0;
    bool saw_wallet_shape = false;
    while (pos < data.size() && parsed_fields < 96u) {
        uint64_t tag = 0;
        size_t p = 0;
        if (!wallet_proto_read_varint(data, pos, data.size(), tag, p)) return false;
        const uint32_t field = static_cast<uint32_t>(tag >> 3);
        const uint32_t wire = static_cast<uint32_t>(tag & 7u);
        if (field == 0u || field > 1024u) return false;
        pos = p;

        if ((field == 3u && wire == 2u) ||
            (field == 5u && wire == 2u) ||
            (field == 6u && wire == 2u) ||
            ((field == 4u || field == 5u) && wire == 0u)) {
            saw_wallet_shape = true;
        }

        if (!wallet_proto_skip_field(data, pos, data.size(), wire, p)) return false;
        pos = p;
        ++parsed_fields;
    }
    return saw_wallet_shape;
}

static bool wallet_bitcoinj_should_try_dir_file(const std::string& path)
{
    if (wallet_bitcoinj_is_obvious_noise_path(path)) return false;

    const std::string l = wallet_lower_copy(path);
    const bool is_wallet_ext = l.size() >= 7u && l.compare(l.size() - 7u, 7u, ".wallet") == 0;
    if (is_wallet_ext) return true;

    std::vector<uint8_t> data;
    std::string err;
    if (!mac_read_binary_file(path, data, err)) return false;
    return wallet_bitcoinj_quick_protobuf_candidate(data);
}

static bool wallet_armory_should_try_dir_file(const std::string& path)
{
    return wallet_file_starts_with_armory_magic(path);
}

static void wallet_electrum_hash_detail(const std::string& token, const uint8_t subtype, uint8_t out32[32])
{
    std::vector<uint8_t> data;
    data.reserve(token.size() + 2u);
    data.insert(data.end(), token.begin(), token.end());
    data.push_back(0u);
    data.push_back(subtype);
    sha256(data.data(), data.size(), out32);
}

static bool wallet_parse_electrum_hash_token(const std::string& token_raw,
    const std::string& source,
    std::vector<ElectrumWalletHostTarget>& out,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$electrum$", token)) {
        err = "no $electrum$ hash token";
        return false;
    }
    const std::string prefix = "$electrum$";
    if (token.rfind(prefix, 0) != 0 || token.size() <= prefix.size()) {
        err = "invalid $electrum$ prefix";
        return false;
    }
    const std::vector<std::string> parts = wallet_split_char(token.substr(prefix.size()), '*');
    if (parts.empty()) {
        err = "empty $electrum$ target";
        return false;
    }

    if (parts[0] == "5") {
        if (parts.size() != 4u) {
            err = "unsupported $electrum$5 field count";
            return false;
        }
        std::vector<uint8_t> pubkey, ciphertext;
        if (!wallet_hex_to_bytes(parts[1], pubkey, err)) return false;
        if (pubkey.size() != 33u || (pubkey[0] != 0x02u && pubkey[0] != 0x03u)) {
            err = "$electrum$5 ephemeral pubkey is invalid";
            return false;
        }
        if (!wallet_hex_to_bytes(parts[2], ciphertext, err)) return false;
        if (ciphertext.empty() || ciphertext.size() > ELECTRUMWALLET_MAX_BLOB_LEN || (ciphertext.size() & 15u) != 0u) {
            err = "$electrum$5 ciphertext length is unsupported";
            return false;
        }

        ElectrumWalletHostTarget target;
        target.file = source;
        target.dev.kind = ELECTRUMWALLET_TARGET_BIE1;
        target.dev.ciphertext_len = static_cast<uint32_t>(ciphertext.size());
        memcpy(target.dev.ephemeral_pubkey, pubkey.data(), 33u);
        if (!wallet_hex_to_fixed(parts[3], target.dev.mac, 32u, err)) {
            err = "$electrum$5 mac: " + err;
            return false;
        }
        target.ciphertext = std::move(ciphertext);
        wallet_electrum_hash_detail(token, 0u, target.dev.detail_hash);
        out.emplace_back(std::move(target));
        return true;
    }

    if (parts[0] == "2") {
        if (parts.size() != 3u) {
            err = "unsupported $electrum$2 field count";
            return false;
        }
        std::vector<uint8_t> iv, ciphertext;
        if (!wallet_hex_to_bytes(parts[1], iv, err)) return false;
        if (iv.size() != 16u) {
            err = "$electrum$2 IV length is invalid";
            return false;
        }
        if (!wallet_hex_to_bytes(parts[2], ciphertext, err)) return false;
        if (ciphertext.empty() || ciphertext.size() > WALLETDAT_MAX_CRYPTED_KEY_LEN || (ciphertext.size() & 15u) != 0u) {
            err = "$electrum$2 ciphertext length is unsupported";
            return false;
        }

        for (uint8_t subtype = 1u; subtype <= 2u; ++subtype) {
            ElectrumWalletHostTarget target;
            target.file = source + (subtype == 1u ? "#xprv" : "#seed");
            target.dev.kind = ELECTRUMWALLET_TARGET_FIELD_V1;
            target.dev.ciphertext_len = static_cast<uint32_t>(ciphertext.size());
            memcpy(target.dev.ephemeral_pubkey, iv.data(), 16u); // IV for FIELD_V1.
            target.dev.mac[0] = subtype;
            target.ciphertext = ciphertext;
            wallet_electrum_hash_detail(token, subtype, target.dev.detail_hash);
            out.emplace_back(std::move(target));
        }
        return true;
    }

    err = "unsupported $electrum$ hash type";
    return false;
}

static size_t wallet_parse_electrum_hash_lines_file(const std::string& path,
    std::vector<ElectrumWalletHostTarget>& out,
    std::string& err)
{
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return 0u;
    }
    size_t loaded = 0u;
    size_t skipped = 0u;
    std::string last_err;
    std::istringstream in(text);
    std::string line;
    size_t line_no = 0u;
    while (std::getline(in, line)) {
        ++line_no;
        trim_crlf_inplace(line);
        if (line.find("$electrum$") == std::string::npos) {
            continue;
        }
        std::vector<ElectrumWalletHostTarget> parsed;
        std::string line_err;
        const std::string label = path + "#" + std::to_string(line_no);
        if (wallet_parse_electrum_hash_token(line, label, parsed, line_err)) {
            loaded += parsed.size();
            for (ElectrumWalletHostTarget& target : parsed) {
                out.emplace_back(std::move(target));
            }
        }
        else {
            ++skipped;
            if (!line_err.empty()) last_err = line_err;
        }
    }
    if (loaded == 0u && skipped != 0u) {
        err = last_err.empty() ? "no valid $electrum$ hash lines" : last_err;
    }
    return loaded;
}

static ElectrumWalletLoadFileResult wallet_load_one_electrumwallet_file(const std::string& path)
{
    ElectrumWalletLoadFileResult result;
    result.path = path;
    if (mac_is_regular_file(path)) {
        std::string hash_err;
        if (wallet_parse_electrum_hash_lines_file(path, result.targets, hash_err) != 0u) {
            result.loaded = true;
            return result;
        }
        if (!hash_err.empty()) {
            result.err = hash_err;
        }
    }
    if (!mac_is_regular_file(path) ||
        !wallet_parse_electrumwallet_file(path, result.target, result.unsupported_bie2, result.err)) {
        result.skipped = true;
        if (result.err.empty()) {
            result.err = "not a regular file";
        }
        return result;
    }
    result.targets.emplace_back(std::move(result.target));
    result.loaded = true;
    return result;
}

struct WalletDatMKeyRecord {
    std::vector<uint8_t> crypted_master;
    std::vector<uint8_t> salt;
    uint32_t iterations = 0;
    size_t pos = 0;
};

struct WalletDatCKeyRecord {
    std::vector<uint8_t> pubkey;
    std::vector<uint8_t> crypted_key;
    size_t pos = 0;
};

static std::vector<std::string> wallet_split_char(const std::string& s, const char delim) {
    std::vector<std::string> out;
    size_t start = 0;
    for (;;) {
        const size_t p = s.find(delim, start);
        if (p == std::string::npos) {
            out.push_back(s.substr(start));
            break;
        }
        out.push_back(s.substr(start, p - start));
        start = p + 1u;
    }
    return out;
}

static bool wallet_parse_u64_decimal(const std::string& s, uint64_t& out) {
    if (s.empty()) return false;
    char* end = nullptr;
    errno = 0;
    const unsigned long long v = std::strtoull(s.c_str(), &end, 10);
    if (errno != 0 || end == s.c_str() || *end != '\0') return false;
    out = static_cast<uint64_t>(v);
    return true;
}

static bool wallet_hex_length_matches(const uint64_t declared_len, const size_t bytes_len, const size_t hex_len) {
    return declared_len == bytes_len || declared_len == hex_len;
}

static bool wallet_extract_dollar_hash_token(const std::string& text, const char* marker, std::string& token) {
    token.clear();
    if (marker == nullptr || marker[0] == '\0') {
        return false;
    }
    std::string line = wallet_trim_copy(text);
    const size_t nl = line.find_first_of("\r\n");
    if (nl != std::string::npos) {
        line = wallet_trim_copy(line.substr(0, nl));
    }
    const size_t pos = line.find(marker);
    if (pos == std::string::npos) {
        return false;
    }
    size_t end = pos;
    while (end < line.size()) {
        const unsigned char ch = static_cast<unsigned char>(line[end]);
        if (std::isspace(ch) || ch == '"' || ch == '\'' || ch == '`') {
            break;
        }
        ++end;
    }
    token = line.substr(pos, end - pos);
    return !token.empty();
}

static bool wallet_parse_ethereum_hash_token(
    const std::string& token_raw,
    const std::string& source,
    WalletKeystoreHostTarget& out,
    std::string& err)
{
    std::string token;
    if (!wallet_extract_dollar_hash_token(token_raw, "$ethereum$", token)) {
        err = "no $ethereum$ hash token";
        return false;
    }
    const std::string prefix = "$ethereum$";
    if (token.rfind(prefix, 0) != 0 || token.size() <= prefix.size()) {
        err = "invalid $ethereum$ prefix";
        return false;
    }
    const std::string body = token.substr(prefix.size());
    const std::vector<std::string> parts = wallet_split_char(body, '*');
    if (parts.size() != 7u) {
        err = "unsupported $ethereum$ field count";
        return false;
    }

    WalletKeystoreTarget t{};
    if (parts[0] == "s" || parts[0] == "S") {
        uint64_t n64 = 0, r64 = 0, p64 = 0;
        if (!wallet_parse_u64_decimal(parts[1], n64) ||
            !wallet_parse_u64_decimal(parts[2], r64) ||
            !wallet_parse_u64_decimal(parts[3], p64) ||
            n64 == 0ull || n64 > std::numeric_limits<uint32_t>::max() ||
            r64 == 0ull || r64 > std::numeric_limits<uint32_t>::max() ||
            p64 == 0ull || p64 > std::numeric_limits<uint32_t>::max()) {
            err = "invalid $ethereum$ scrypt params";
            return false;
        }
        const uint32_t n = static_cast<uint32_t>(n64);
        const uint32_t r = static_cast<uint32_t>(r64);
        const uint32_t p = static_cast<uint32_t>(p64);
        if ((n & (n - 1u)) != 0u || r > 8u) {
            err = "unsupported $ethereum$ scrypt params";
            return false;
        }
        t.kdf_type = WALLET_KDF_SCRYPT;
        t.dklen = 32u;
        t.scrypt_n = n;
        t.scrypt_r = r;
        t.scrypt_p = p;
    }
    else {
        err = "unsupported $ethereum$ kdf";
        return false;
    }

    std::vector<uint8_t> salt_vec, cipher_vec;
    if (!wallet_hex_to_bytes(parts[4], salt_vec, err)) return false;
    if (salt_vec.empty() || salt_vec.size() > WALLET_MAX_SALT_LEN) {
        err = "$ethereum$ salt length is unsupported";
        return false;
    }
    if (!wallet_hex_to_bytes(parts[5], cipher_vec, err)) return false;
    if (cipher_vec.empty() || cipher_vec.size() > WALLET_MAX_CIPHERTEXT_LEN) {
        err = "$ethereum$ ciphertext length is unsupported";
        return false;
    }
    if (!wallet_hex_to_fixed(parts[6], t.mac, 32, err)) {
        err = "$ethereum$ mac: " + err;
        return false;
    }

    t.salt_len = static_cast<uint32_t>(salt_vec.size());
    t.ciphertext_len = static_cast<uint32_t>(cipher_vec.size());
    t.has_address = 0u;
    memcpy(t.salt, salt_vec.data(), salt_vec.size());
    memcpy(t.ciphertext, cipher_vec.data(), cipher_vec.size());
    {
        std::vector<uint8_t> hash_input;
        hash_input.reserve(cipher_vec.size() + salt_vec.size() + 64u);
        hash_input.insert(hash_input.end(), cipher_vec.begin(), cipher_vec.end());
        hash_input.push_back('|');
        hash_input.insert(hash_input.end(), salt_vec.begin(), salt_vec.end());
        hash_input.push_back('|');
        hash_input.insert(hash_input.end(), t.mac, t.mac + 32);
        hash_input.push_back('|');
        hash_input.push_back(static_cast<uint8_t>(t.kdf_type));
        hash_input.push_back(static_cast<uint8_t>(t.scrypt_n & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_n >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_n >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_n >> 24) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>(t.scrypt_r & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_r >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_r >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_r >> 24) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>(t.scrypt_p & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_p >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_p >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.scrypt_p >> 24) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>(t.dklen & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.dklen >> 8) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.dklen >> 16) & 0xffu));
        hash_input.push_back(static_cast<uint8_t>((t.dklen >> 24) & 0xffu));
        sha256(hash_input.data(), hash_input.size(), t.vault_hash);
    }

    out.dev = t;
    out.file = source;
    return true;
}

static size_t wallet_parse_ethereum_hash_lines_text(
    const std::string& text,
    const std::string& source,
    std::vector<WalletKeystoreHostTarget>& out,
    std::string& err)
{
    size_t loaded = 0u;
    size_t skipped = 0u;
    std::istringstream in(text);
    std::string line;
    size_t line_no = 0u;
    std::string last_err;
    while (std::getline(in, line)) {
        ++line_no;
        trim_crlf_inplace(line);
        if (line.find("$ethereum$") == std::string::npos) {
            continue;
        }
        WalletKeystoreHostTarget target;
        std::string line_err;
        const std::string label = source + "#" + std::to_string(line_no);
        if (wallet_parse_ethereum_hash_token(line, label, target, line_err)) {
            out.emplace_back(std::move(target));
            ++loaded;
        }
        else {
            ++skipped;
            if (!line_err.empty()) {
                last_err = line_err;
            }
        }
    }
    if (loaded == 0u && skipped != 0u) {
        err = last_err.empty() ? "no valid $ethereum$ hash lines" : last_err;
    }
    return loaded;
}

static bool walletdat_fill_target(
    const std::string& path,
    const uint32_t target_index,
    const std::vector<uint8_t>& crypted_master,
    const std::vector<uint8_t>& salt,
    const uint32_t iterations,
    const std::vector<uint8_t>& crypted_key,
    const std::vector<uint8_t>& pubkey,
    WalletDatHostTarget& out,
    std::string& err)
{
    if (crypted_master.empty() || crypted_master.size() > WALLETDAT_MAX_CRYPTED_KEY_LEN || (crypted_master.size() & 15u) != 0u) {
        err = "unsupported encrypted master key length";
        return false;
    }
    if (crypted_key.empty() || crypted_key.size() > WALLETDAT_MAX_CRYPTED_KEY_LEN || (crypted_key.size() & 15u) != 0u) {
        err = "unsupported encrypted ckey length";
        return false;
    }
    if (salt.empty() || salt.size() > WALLET_MAX_SALT_LEN) {
        err = "unsupported mkey salt length";
        return false;
    }
    if (iterations == 0u) {
        err = "invalid mkey iterations";
        return false;
    }
    if (pubkey.size() != 33u && pubkey.size() != 65u) {
        err = "unsupported public key length";
        return false;
    }
    WalletDatTarget t{};
    t.iterations = iterations;
    t.salt_len = static_cast<uint32_t>(salt.size());
    t.crypted_master_len = static_cast<uint32_t>(crypted_master.size());
    t.target_index = target_index;
    t.ckey_count = 1u;
    t.crypted_key_len[0] = static_cast<uint32_t>(crypted_key.size());
    t.pubkey_len[0] = static_cast<uint32_t>(pubkey.size());
    memcpy(t.salt, salt.data(), salt.size());
    memcpy(t.crypted_master, crypted_master.data(), crypted_master.size());
    memcpy(t.crypted_key[0], crypted_key.data(), crypted_key.size());
    memcpy(t.pubkey[0], pubkey.data(), pubkey.size());
    uint8_t h1[32], h2[32];
    sha256(const_cast<uint8_t*>(pubkey.data()), pubkey.size(), h1);
    sha256(h1, sizeof(h1), h2);
    memcpy(t.ckey_iv[0], h2, 16u);
    out.dev = t;
    out.file = path;
    return true;
}

static bool walletdat_fill_mkey_only_target(
    const std::string& path,
    const uint32_t target_index,
    const std::vector<uint8_t>& crypted_master,
    const std::vector<uint8_t>& salt,
    const uint32_t iterations,
    WalletDatHostTarget& out,
    std::string& err)
{
    if (crypted_master.empty() || crypted_master.size() > WALLETDAT_MAX_CRYPTED_KEY_LEN || (crypted_master.size() & 15u) != 0u) {
        err = "unsupported encrypted master key length";
        return false;
    }
    if (salt.empty() || salt.size() > WALLET_MAX_SALT_LEN) {
        err = "unsupported mkey salt length";
        return false;
    }
    if (iterations == 0u) {
        err = "invalid mkey iterations";
        return false;
    }
    WalletDatTarget t{};
    t.iterations = iterations;
    t.salt_len = static_cast<uint32_t>(salt.size());
    t.crypted_master_len = static_cast<uint32_t>(crypted_master.size());
    t.target_index = target_index;
    t.ckey_count = 0u;
    memcpy(t.salt, salt.data(), salt.size());
    memcpy(t.crypted_master, crypted_master.data(), crypted_master.size());
    out.dev = t;
    out.file = path;
    return true;
}

static void walletdat_append_u32_key(std::string& key, const uint32_t v) {
    key.push_back(static_cast<char>(v & 0xffu));
    key.push_back(static_cast<char>((v >> 8) & 0xffu));
    key.push_back(static_cast<char>((v >> 16) & 0xffu));
    key.push_back(static_cast<char>((v >> 24) & 0xffu));
}

static std::string walletdat_master_target_key(const WalletDatTarget& t) {
    std::string key;
    key.reserve(24u + static_cast<size_t>(t.salt_len) + static_cast<size_t>(t.crypted_master_len));
    walletdat_append_u32_key(key, t.iterations);
    walletdat_append_u32_key(key, t.salt_len);
    walletdat_append_u32_key(key, t.crypted_master_len);
    if (t.salt_len != 0u) {
        key.append(reinterpret_cast<const char*>(t.salt), reinterpret_cast<const char*>(t.salt) + t.salt_len);
    }
    if (t.crypted_master_len != 0u) {
        key.append(reinterpret_cast<const char*>(t.crypted_master), reinterpret_cast<const char*>(t.crypted_master) + t.crypted_master_len);
    }
    return key;
}

static bool walletdat_add_ckey_slot(WalletDatTarget& dst, const WalletDatTarget& src) {
    if (src.ckey_count == 0u) return false;
    for (uint32_t si = 0; si < src.ckey_count && si < WALLETDAT_MAX_CKEY_SLOTS; ++si) {
        const uint32_t src_ck_len = src.crypted_key_len[si];
        const uint32_t src_pk_len = src.pubkey_len[si];
        if (src_ck_len == 0u || src_ck_len > WALLETDAT_MAX_CRYPTED_KEY_LEN ||
            src_pk_len == 0u || src_pk_len > WALLETDAT_MAX_PUBKEY_LEN) {
            continue;
        }
        bool duplicate = false;
        for (uint32_t di = 0; di < dst.ckey_count && di < WALLETDAT_MAX_CKEY_SLOTS; ++di) {
            if (dst.crypted_key_len[di] == src_ck_len &&
                dst.pubkey_len[di] == src_pk_len &&
                memcmp(dst.crypted_key[di], src.crypted_key[si], src_ck_len) == 0 &&
                memcmp(dst.pubkey[di], src.pubkey[si], src_pk_len) == 0) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        if (dst.ckey_count >= WALLETDAT_MAX_CKEY_SLOTS) return false;
        const uint32_t out_idx = dst.ckey_count++;
        dst.crypted_key_len[out_idx] = src_ck_len;
        dst.pubkey_len[out_idx] = src_pk_len;
        memcpy(dst.crypted_key[out_idx], src.crypted_key[si], src_ck_len);
        memcpy(dst.pubkey[out_idx], src.pubkey[si], src_pk_len);
        memcpy(dst.ckey_iv[out_idx], src.ckey_iv[si], 16u);
    }
    return true;
}

static void walletdat_compact_master_targets(
    const std::vector<WalletDatHostTarget>& host_targets,
    std::vector<WalletDatTarget>& compact_targets,
    std::vector<std::string>& compact_target_files)
{
    compact_targets.clear();
    compact_target_files.clear();
    compact_targets.reserve(host_targets.size());
    compact_target_files.reserve(host_targets.size());
    std::unordered_map<std::string, size_t> seen;
    seen.reserve(host_targets.size() * 2u + 1u);
    for (const WalletDatHostTarget& host_target : host_targets) {
        const WalletDatTarget& candidate = host_target.dev;
        std::string key = walletdat_master_target_key(candidate);
        const auto it = seen.find(key);
        if (it == seen.end()) {
            WalletDatTarget compact = candidate;
            compact.target_index = static_cast<uint32_t>(compact_target_files.size());
            compact.ckey_count = std::min<uint32_t>(compact.ckey_count, WALLETDAT_MAX_CKEY_SLOTS);
            compact_targets.push_back(compact);
            compact_target_files.push_back(host_target.file);
            seen.emplace(std::move(key), compact_targets.size() - 1u);
        }
        else {
            walletdat_add_ckey_slot(compact_targets[it->second], candidate);
        }
    }

    if (compact_targets.size() <= 1u) {
        return;
    }

    std::vector<size_t> order(compact_targets.size());
    for (size_t i = 0; i < order.size(); ++i) {
        order[i] = i;
    }
    std::stable_sort(order.begin(), order.end(), [&](const size_t lhs, const size_t rhs) {
        const WalletDatTarget& a = compact_targets[lhs];
        const WalletDatTarget& b = compact_targets[rhs];
        if (a.iterations != b.iterations) return a.iterations < b.iterations;
        if (a.salt_len != b.salt_len) return a.salt_len < b.salt_len;
        const int salt_cmp = memcmp(a.salt, b.salt, std::min(a.salt_len, b.salt_len));
        if (salt_cmp != 0) return salt_cmp < 0;
        if (a.crypted_master_len != b.crypted_master_len) return a.crypted_master_len < b.crypted_master_len;
        const int master_cmp = memcmp(a.crypted_master, b.crypted_master, std::min(a.crypted_master_len, b.crypted_master_len));
        if (master_cmp != 0) return master_cmp < 0;
        return compact_target_files[lhs] < compact_target_files[rhs];
    });

    std::vector<WalletDatTarget> sorted_targets;
    std::vector<std::string> sorted_files;
    sorted_targets.reserve(compact_targets.size());
    sorted_files.reserve(compact_target_files.size());
    for (size_t new_idx = 0; new_idx < order.size(); ++new_idx) {
        WalletDatTarget target = compact_targets[order[new_idx]];
        target.target_index = static_cast<uint32_t>(new_idx);
        sorted_targets.push_back(target);
        sorted_files.push_back(compact_target_files[order[new_idx]]);
    }
    compact_targets.swap(sorted_targets);
    compact_target_files.swap(sorted_files);
}

static bool walletdat_parse_extended_bitcoin_line(
    const std::string& path,
    const std::string& text,
    const uint32_t target_index,
    std::vector<WalletDatHostTarget>& targets,
    std::string& err)
{
    std::string line;
    if (!wallet_extract_dollar_hash_token(text, "$bitcoin$", line)) {
        return false;
    }

    const std::vector<std::string> parts = wallet_split_char(line, '$');
    if (parts.size() < 11 || parts[1] != "bitcoin") {
        err = "extended $bitcoin$ walletdat target requires crypted key and pubkey fields";
        return false;
    }

    uint64_t cm_decl = 0, salt_decl = 0, iter_decl = 0, ck_decl = 0, pk_decl = 0;
    if (!wallet_parse_u64_decimal(parts[2], cm_decl) ||
        !wallet_parse_u64_decimal(parts[4], salt_decl) ||
        !wallet_parse_u64_decimal(parts[6], iter_decl) ||
        !wallet_parse_u64_decimal(parts[7], ck_decl) ||
        !wallet_parse_u64_decimal(parts[9], pk_decl)) {
        err = "invalid numeric field in extended $bitcoin$ target";
        return false;
    }
    if (iter_decl == 0 || iter_decl > std::numeric_limits<uint32_t>::max()) {
        err = "invalid iteration count in extended $bitcoin$ target";
        return false;
    }

    std::vector<uint8_t> crypted_master, salt, crypted_key, pubkey;
    if (!wallet_hex_to_bytes(parts[3], crypted_master, err)) return false;
    if (!wallet_hex_to_bytes(parts[5], salt, err)) return false;
    if (!wallet_hex_to_bytes(parts[8], crypted_key, err)) return false;
    if (!wallet_hex_to_bytes(parts[10], pubkey, err)) return false;
    if (!wallet_hex_length_matches(cm_decl, crypted_master.size(), parts[3].size()) ||
        !wallet_hex_length_matches(salt_decl, salt.size(), parts[5].size()) ||
        !wallet_hex_length_matches(ck_decl, crypted_key.size(), parts[8].size()) ||
        !wallet_hex_length_matches(pk_decl, pubkey.size(), parts[10].size())) {
        err = "declared extended $bitcoin$ field length does not match hex data";
        return false;
    }

    WalletDatHostTarget target;
    const bool empty_ckey = crypted_key.empty() || (crypted_key.size() == 1u && crypted_key[0] == 0u);
    const bool empty_pubkey = pubkey.empty() || (pubkey.size() == 1u && pubkey[0] == 0u);
    if (empty_ckey && empty_pubkey) {
        if (!walletdat_fill_mkey_only_target(path, target_index, crypted_master, salt, static_cast<uint32_t>(iter_decl), target, err)) {
            return false;
        }
    }
    else if (!walletdat_fill_target(path, target_index, crypted_master, salt, static_cast<uint32_t>(iter_decl), crypted_key, pubkey, target, err)) {
        return false;
    }
    targets.push_back(target);
    return true;
}

static bool walletdat_read_compact_size(const std::vector<uint8_t>& data, const size_t pos, uint64_t& value, size_t& next) {
    if (pos >= data.size()) return false;
    const uint8_t ch = data[pos];
    if (ch < 253u) {
        value = ch;
        next = pos + 1u;
        return true;
    }
    if (ch == 253u) {
        if (pos + 3u > data.size()) return false;
        value = static_cast<uint64_t>(data[pos + 1u]) | (static_cast<uint64_t>(data[pos + 2u]) << 8);
        next = pos + 3u;
        return true;
    }
    if (ch == 254u) {
        if (pos + 5u > data.size()) return false;
        value = 0;
        for (int i = 0; i < 4; ++i) value |= static_cast<uint64_t>(data[pos + 1u + static_cast<size_t>(i)]) << (8 * i);
        next = pos + 5u;
        return true;
    }
    if (pos + 9u > data.size()) return false;
    value = 0;
    for (int i = 0; i < 8; ++i) value |= static_cast<uint64_t>(data[pos + 1u + static_cast<size_t>(i)]) << (8 * i);
    next = pos + 9u;
    return true;
}

static bool walletdat_read_u32_le(const std::vector<uint8_t>& data, const size_t pos, uint32_t& value) {
    if (pos + 4u > data.size()) return false;
    value = static_cast<uint32_t>(data[pos]) |
        (static_cast<uint32_t>(data[pos + 1u]) << 8) |
        (static_cast<uint32_t>(data[pos + 2u]) << 16) |
        (static_cast<uint32_t>(data[pos + 3u]) << 24);
    return true;
}

static bool walletdat_parse_mkey_at(const std::vector<uint8_t>& data, const size_t pos, WalletDatMKeyRecord& out) {
    uint64_t cm_len = 0, salt_len = 0, other_len = 0;
    size_t p = 0;
    if (!walletdat_read_compact_size(data, pos, cm_len, p)) return false;
    if (cm_len != 48u || p + cm_len > data.size()) return false;
    const size_t cm_pos = p;
    p += static_cast<size_t>(cm_len);

    if (!walletdat_read_compact_size(data, p, salt_len, p)) return false;
    if (salt_len != 8u || p + salt_len > data.size()) return false;
    const size_t salt_pos = p;
    p += static_cast<size_t>(salt_len);

    uint32_t method = 0, iterations = 0;
    if (!walletdat_read_u32_le(data, p, method)) return false;
    p += 4u;
    if (!walletdat_read_u32_le(data, p, iterations)) return false;
    p += 4u;
    if (method != 0u || iterations == 0u || iterations > 100000000u) return false;

    if (!walletdat_read_compact_size(data, p, other_len, p)) return false;
    if (other_len != 0u || p + other_len > data.size()) return false;

    out.crypted_master.assign(data.begin() + static_cast<std::ptrdiff_t>(cm_pos),
        data.begin() + static_cast<std::ptrdiff_t>(cm_pos + cm_len));
    out.salt.assign(data.begin() + static_cast<std::ptrdiff_t>(salt_pos),
        data.begin() + static_cast<std::ptrdiff_t>(salt_pos + salt_len));
    out.iterations = iterations;
    out.pos = pos;
    return true;
}

static bool walletdat_parse_mkey_marker_at(const std::vector<uint8_t>& data, const size_t pos, WalletDatMKeyRecord& out) {
    static const uint8_t marker[] = { 0x04u, 'm', 'k', 'e', 'y' };
    if (pos + sizeof(marker) >= data.size()) return false;
    if (memcmp(data.data() + pos, marker, sizeof(marker)) != 0) return false;

    // Bitcoin Core serializes the key as string("mkey") + id.  In BerkeleyDB pages
    // the value record is usually close to that key, but not guaranteed to be exactly
    // adjacent, so scan a tight forward window for the CMasterKey value layout.
    const size_t begin = pos + sizeof(marker);
    const size_t end = std::min<size_t>(data.size(), begin + 4096u);
    for (size_t p = begin; p < end; ++p) {
        WalletDatMKeyRecord candidate;
        if (walletdat_parse_mkey_at(data, p, candidate)) {
            candidate.pos = p;
            out = std::move(candidate);
            return true;
        }
    }
    return false;
}

static bool walletdat_parse_pubkey_marker_at(const std::vector<uint8_t>& data, const size_t pos, std::vector<uint8_t>& pubkey, size_t& next) {
    static const uint8_t marker[] = { 0x04u, 'c', 'k', 'e', 'y' };
    if (pos + sizeof(marker) >= data.size()) return false;
    if (memcmp(data.data() + pos, marker, sizeof(marker)) != 0) return false;
    uint64_t pk_len = 0;
    size_t p = 0;
    if (!walletdat_read_compact_size(data, pos + sizeof(marker), pk_len, p)) return false;
    if ((pk_len != 33u && pk_len != 65u) || p + pk_len > data.size()) return false;
    const uint8_t first = data[p];
    if ((pk_len == 33u && first != 0x02u && first != 0x03u) || (pk_len == 65u && first != 0x04u)) return false;
    pubkey.assign(data.begin() + static_cast<std::ptrdiff_t>(p),
        data.begin() + static_cast<std::ptrdiff_t>(p + pk_len));
    next = p + static_cast<size_t>(pk_len);
    return true;
}

static bool walletdat_parse_crypted_key_vector_at(const std::vector<uint8_t>& data, const size_t pos, std::vector<uint8_t>& crypted_key, size_t& next) {
    uint64_t len = 0;
    size_t p = 0;
    if (!walletdat_read_compact_size(data, pos, len, p)) return false;
    if (len != 48u || p + len > data.size()) return false;
    crypted_key.assign(data.begin() + static_cast<std::ptrdiff_t>(p),
        data.begin() + static_cast<std::ptrdiff_t>(p + len));
    next = p + static_cast<size_t>(len);
    return true;
}

static bool walletdat_collect_raw_targets(
    const std::string& path,
    const uint32_t target_index,
    std::vector<WalletDatHostTarget>& targets,
    std::string& err,
    size_t* raw_cap_counter = nullptr)
{
    std::vector<uint8_t> data;
    if (!mac_read_binary_file(path, data, err)) {
        return false;
    }
    if (data.empty()) {
        err = "empty wallet.dat file";
        return false;
    }

    std::vector<WalletDatMKeyRecord> mkeys;
    std::vector<WalletDatCKeyRecord> ckeys;
    const size_t max_raw_records = walletdat_max_raw_ckey_records;
    auto raw_record_limit_reached = [&]() -> bool {
        return max_raw_records != 0u && ckeys.size() >= max_raw_records;
    };
    auto add_mkey = [&](WalletDatMKeyRecord&& mkey) {
        bool duplicate = false;
        for (const auto& prev : mkeys) {
            if (prev.crypted_master == mkey.crypted_master && prev.salt == mkey.salt && prev.iterations == mkey.iterations) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate && mkeys.size() < 64u) {
            mkeys.push_back(std::move(mkey));
        }
    };

    for (size_t pos = 0; pos < data.size() && mkeys.size() < 64u; ++pos) {
        WalletDatMKeyRecord mkey;
        if (walletdat_parse_mkey_marker_at(data, pos, mkey)) {
            add_mkey(std::move(mkey));
        }
    }

    // If keyed "mkey" records were found, avoid a full blind scan.  The blind
    // scan is intentionally kept as fallback for non-standard/damaged dumps.
    if (mkeys.empty()) {
        for (size_t pos = 0; pos < data.size() && mkeys.size() < 64u; ++pos) {
            WalletDatMKeyRecord mkey;
            if (walletdat_parse_mkey_at(data, pos, mkey)) {
                add_mkey(std::move(mkey));
            }
        }
    }

    // Keep several ckey candidates per file.  They are merged into compact
    // master targets later, so KDF work stays one-per-master while damaged or
    // non-standard files get more chances to resolve after a master hit.
    for (size_t pos = 0; pos < data.size() && !raw_record_limit_reached(); ++pos) {
        std::vector<uint8_t> pubkey;
        size_t after_pubkey = 0;
        if (!walletdat_parse_pubkey_marker_at(data, pos, pubkey, after_pubkey)) {
            continue;
        }

        std::vector<uint8_t> best_key;
        size_t best_dist = std::numeric_limits<size_t>::max();
        size_t exact_next = 0;
        if (walletdat_parse_crypted_key_vector_at(data, after_pubkey, best_key, exact_next) && best_key == pubkey) {
            best_key.clear();
        }
        if (best_key.empty()) {
            const size_t search_begin = (pos > 8192u) ? (pos - 8192u) : 0u;
            const size_t search_end = std::min<size_t>(data.size(), after_pubkey + 8192u);
            for (size_t kp = search_begin; kp < search_end; ++kp) {
                std::vector<uint8_t> candidate;
                size_t next = 0;
                if (!walletdat_parse_crypted_key_vector_at(data, kp, candidate, next)) {
                    continue;
                }
                if (candidate == pubkey) {
                    continue;
                }
                const size_t dist = (kp > pos) ? (kp - pos) : (pos - kp);
                if (dist < best_dist) {
                    best_dist = dist;
                    best_key = std::move(candidate);
                }
            }
        }
        if (best_key.empty()) {
            continue;
        }
        bool duplicate = false;
        for (const auto& prev : ckeys) {
            if (prev.pubkey == pubkey && prev.crypted_key == best_key) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            WalletDatCKeyRecord ckey;
            ckey.pubkey = std::move(pubkey);
            ckey.crypted_key = std::move(best_key);
            ckey.pos = pos;
            ckeys.push_back(std::move(ckey));
        }
    }

    if (mkeys.empty()) {
        err = "no encrypted mkey records found";
        return false;
    }
    if (ckeys.empty()) {
        err = "no encrypted ckey/pubkey records found";
        return false;
    }

    const size_t before = targets.size();
    for (const auto& mkey : mkeys) {
        for (const WalletDatCKeyRecord& ckey : ckeys) {
            WalletDatHostTarget target;
            std::string fill_err;
            if (walletdat_fill_target(path, target_index, mkey.crypted_master, mkey.salt, mkey.iterations,
                ckey.crypted_key, ckey.pubkey, target, fill_err)) {
                targets.push_back(target);
            }
        }
    }
    if (targets.size() == before) {
        err = "found mkey/ckey candidates but none fit supported limits";
        return false;
    }
    if (max_raw_records != 0u && ckeys.size() >= max_raw_records) {
        if (raw_cap_counter != nullptr) {
            ++(*raw_cap_counter);
        }
        else {
            ++walletdat_raw_ckey_cap_warning_count;
        }
        const size_t cap_count = raw_cap_counter != nullptr ? *raw_cap_counter : walletdat_raw_ckey_cap_warning_count;
        if (raw_cap_counter == nullptr && !walletdat_quiet_raw_ckey_cap_warnings && cap_count <= 64u) {
            fprintf(stderr, "[!] Warning: wallet.dat '%s' produced many ckey candidates; parser capped raw scan records [!]\n", path.c_str());
        }
    }
    return true;
}

static bool wallet_parse_walletdat_file(
    const std::string& path,
    const uint32_t target_index,
    std::vector<WalletDatHostTarget>& targets,
    std::string& err,
    size_t* raw_cap_counter = nullptr)
{
    if (wallet_file_starts_with_bitcoin_hash(path)) {
        std::string text;
        if (!mac_read_text_file(path, text, err)) {
            return false;
        }
        std::string trimmed;
        if (wallet_extract_dollar_hash_token(text, "$bitcoin$", trimmed)) {
            return walletdat_parse_extended_bitcoin_line(path, trimmed, target_index, targets, err);
        }
    }
    err.clear();
    return walletdat_collect_raw_targets(path, target_index, targets, err, raw_cap_counter);
}

static bool walletdat_parse_hash_lines_file(
    const std::string& path,
    std::vector<std::string>& target_files,
    std::vector<WalletDatHostTarget>& targets,
    size_t& valid_lines,
    size_t& skipped_lines,
    std::string& err)
{
    valid_lines = 0u;
    skipped_lines = 0u;
    std::string text;
    if (!mac_read_text_file(path, text, err)) {
        return false;
    }
    if (text.find("$bitcoin$") == std::string::npos) {
        err = "no $bitcoin$ hash lines";
        return false;
    }

    std::istringstream in(text);
    std::string line;
    size_t line_no = 0u;
    while (std::getline(in, line)) {
        ++line_no;
        trim_crlf_inplace(line);
        line = wallet_trim_copy(line);
        if (line.empty() || line[0] == '#') {
            continue;
        }
        std::string bitcoin_token;
        if (!wallet_extract_dollar_hash_token(line, "$bitcoin$", bitcoin_token)) {
            continue;
        }
        const uint32_t target_index = static_cast<uint32_t>(target_files.size());
        const size_t before = targets.size();
        std::string line_err;
        if (walletdat_parse_extended_bitcoin_line(path, bitcoin_token, target_index, targets, line_err)) {
            const std::string label = path + "#" + std::to_string(line_no);
            target_files.push_back(label);
            for (size_t i = before; i < targets.size(); ++i) {
                targets[i].dev.target_index = target_index;
                targets[i].file = label;
            }
            ++valid_lines;
        }
        else {
            ++skipped_lines;
        }
    }
    if (valid_lines == 0u) {
        err = "no valid extended $bitcoin$ hash lines";
        return false;
    }
    return true;
}

struct WalletDatLoadFileResult {
    std::string path;
    std::string err;
    std::vector<std::string> labels;
    std::vector<WalletDatHostTarget> targets;
    size_t valid_hash_lines = 0u;
    size_t invalid_hash_lines = 0u;
    size_t raw_ckey_cap_hits = 0u;
    bool loaded = false;
    bool skipped = false;
    bool not_regular = false;
};

static WalletDatLoadFileResult walletdat_load_one_file(const std::string& path, const bool scan_all)
{
    WalletDatLoadFileResult result;
    result.path = path;
    if (!mac_is_regular_file(path)) {
        result.skipped = true;
        result.not_regular = true;
        result.err = "not a regular file";
        return result;
    }

    if (scan_all) {
        std::string hash_err;
        if (walletdat_parse_hash_lines_file(path, result.labels, result.targets,
            result.valid_hash_lines, result.invalid_hash_lines, hash_err)) {
            result.loaded = true;
            return result;
        }
    }

    std::string err;
    size_t raw_cap_hits = 0u;
    if (!wallet_parse_walletdat_file(path, 0u, result.targets, err, &raw_cap_hits)) {
        result.skipped = true;
        result.err = err;
        return result;
    }
    result.raw_ckey_cap_hits = raw_cap_hits;
    result.labels.push_back(path);
    for (WalletDatHostTarget& target : result.targets) {
        target.dev.target_index = 0u;
        target.file = path;
    }
    result.loaded = true;
    return result;
}

static size_t walletdat_loader_thread_count(const size_t file_count)
{
    if (file_count <= 1u) {
        return 1u;
    }
    const unsigned int hw = std::thread::hardware_concurrency();
    const size_t by_hw = hw == 0u ? 4u : static_cast<size_t>(hw);
    // Parsing is I/O-heavy and allocates per file; keep parallelism bounded to
    // avoid fighting GPU memory/filter allocation and disk cache.
    return std::max<size_t>(1u, std::min<size_t>({ file_count, by_hw, 8u }));
}

template <typename Result, typename Loader>
static void wallet_parallel_load_files(
    const std::vector<std::string>& files,
    const char* label,
    std::vector<Result>& results,
    Loader loader)
{
    results.clear();
    results.resize(files.size());
    if (files.empty()) {
        return;
    }
    const size_t loader_threads = walletdat_loader_thread_count(files.size());
    if (files.size() == 1u) {
        results[0] = loader(files[0]);
        return;
    }
    if (loader_threads == 1u) {
        for (size_t idx = 0u; idx < files.size(); ++idx) {
            results[idx] = loader(files[idx]);
        }
        return;
    }
    if (loader_threads > 1u) {
        printf("[!] %s loader threads: %zu [!]\n", label, loader_threads);
        fflush(stdout);
    }
    std::atomic<size_t> next_file_idx{ 0u };
    std::atomic<size_t> done_files{ 0u };
    const auto load_begin = std::chrono::steady_clock::now();
    auto load_last_report = load_begin;

    auto worker = [&]() {
        for (;;) {
            const size_t idx = next_file_idx.fetch_add(1u, std::memory_order_relaxed);
            if (idx >= files.size()) {
                break;
            }
            results[idx] = loader(files[idx]);
            done_files.fetch_add(1u, std::memory_order_release);
        }
    };

    std::vector<std::thread> pool;
    pool.reserve(loader_threads);
    for (size_t t = 0u; t < loader_threads; ++t) {
        pool.emplace_back(worker);
    }
    while (done_files.load(std::memory_order_acquire) < files.size()) {
        const auto now = std::chrono::steady_clock::now();
        const double since_last = std::chrono::duration<double>(now - load_last_report).count();
        if (since_last >= 5.0) {
            load_last_report = now;
            const double elapsed = std::chrono::duration<double>(now - load_begin).count();
            printf("[!] %s load progress: %zu/%zu files | %.1fs [!]\n",
                label, done_files.load(std::memory_order_relaxed), files.size(), elapsed);
            fflush(stdout);
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(250));
    }
    for (std::thread& t : pool) {
        if (t.joinable()) {
            t.join();
        }
    }
}

static std::string wallet_skip_reason_or_default(const std::string& err)
{
    return err.empty() ? std::string("unsupported or invalid") : err;
}

static void wallet_add_skip_reason(std::unordered_map<std::string, size_t>& reasons, const std::string& err)
{
    ++reasons[wallet_skip_reason_or_default(err)];
}

static void wallet_print_skip_reason_summary(
    const char* label,
    const std::unordered_map<std::string, size_t>& reasons,
    const size_t total_skipped,
    const size_t max_reasons = 8u)
{
    if (total_skipped == 0u || reasons.empty()) {
        return;
    }
    std::vector<std::pair<std::string, size_t>> sorted;
    sorted.reserve(reasons.size());
    for (const auto& kv : reasons) {
        sorted.emplace_back(kv.first, kv.second);
    }
    std::sort(sorted.begin(), sorted.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
        });

    const size_t shown = std::min(max_reasons, sorted.size());
    printf("[!] %s skip reasons top %zu/%zu:", label, shown, sorted.size());
    for (size_t i = 0u; i < shown; ++i) {
        printf(" %s=%zu%s", sorted[i].first.c_str(), sorted[i].second, (i + 1u == shown) ? "" : ";");
    }
    if (sorted.size() > shown) {
        size_t other = 0u;
        for (size_t i = shown; i < sorted.size(); ++i) {
            other += sorted[i].second;
        }
        printf("; other=%zu", other);
    }
    printf(" [!]\n");
}

template <typename Result>
static void wallet_print_skip_reason_summary_from_results(
    const char* label,
    const std::vector<Result>& results,
    const size_t max_reasons = 8u)
{
    std::unordered_map<std::string, size_t> reasons;
    size_t total_skipped = 0u;
    for (const Result& result : results) {
        if (!result.loaded && result.skipped) {
            ++total_skipped;
            wallet_add_skip_reason(reasons, result.err);
        }
    }
    wallet_print_skip_reason_summary(label, reasons, total_skipped, max_reasons);
}

struct WalletPassBuf {
    std::vector<char> data;
    std::vector<uint8_t> lens;
    uint32_t count = 0;
    void reset() { data.clear(); lens.clear(); count = 0; }
    void push_bytes(const uint8_t* p, size_t L) {
        if (L > WALLET_MAX_PASSWORD_LEN) L = WALLET_MAX_PASSWORD_LEN;
        data.resize(static_cast<size_t>(count + 1) * WALLET_PASS_STRIDE, 0);
        if (L > 0) memcpy(data.data() + static_cast<size_t>(count) * WALLET_PASS_STRIDE, p, L);
        lens.push_back(static_cast<uint8_t>(L));
        ++count;
    }
    void push_text(const std::string& s) {
        push_bytes(reinterpret_cast<const uint8_t*>(s.data()), s.size());
    }
};

static bool wallet_normalize_nfc_utf8(const std::string& input,
                                      std::string& output,
                                      std::string& error)
{
    @autoreleasepool {
        NSString* source = [[NSString alloc]
            initWithBytes:input.data()
                   length:input.size()
                 encoding:NSUTF8StringEncoding];
        if (source == nil) {
            error = "candidate is not valid UTF-8";
            return false;
        }
        NSString* normalized = [source precomposedStringWithCanonicalMapping];
        NSData* data = [normalized dataUsingEncoding:NSUTF8StringEncoding
                                allowLossyConversion:NO];
        if (data == nil) {
            error = "candidate cannot be represented as normalized UTF-8";
            return false;
        }
        output.assign(static_cast<const char*>(data.bytes), data.length);
    }
    return true;
}

struct WalletPassReader {
    std::vector<std::ifstream> files;
    std::vector<std::string> file_names;
    size_t file_idx = 0;
    bool hex_lines = false;
    bool normalize_nfc_text = false;
    bool failed = false;
    std::string error;

    bool open(const std::vector<std::string>& fnames,
              const bool input_is_hex,
              const bool normalize_nfc = false) {
        files.clear();
        file_names = fnames;
        file_idx = 0;
        hex_lines = input_is_hex;
        normalize_nfc_text = normalize_nfc && !input_is_hex;
        failed = false;
        error.clear();
        files.reserve(fnames.size());
        for (const auto& fname : fnames) {
            files.emplace_back();
            tune_ifstream_buffer(files.back());
            files.back().open(fname, std::ios::in);
            if (!files.back()) {
                error = "cannot open candidate file: " + fname;
                failed = true;
                return false;
            }
        }
        return true;
    }

    bool read_batch(WalletPassBuf& buf, uint32_t max_count) {
        buf.reset();
        buf.data.reserve(static_cast<size_t>(max_count) * WALLET_PASS_STRIDE);
        buf.lens.reserve(max_count);
        std::string line;
        while (buf.count < max_count && file_idx < files.size()) {
            if (!std::getline(files[file_idx], line)) {
                ++file_idx;
                continue;
            }
            trim_crlf_inplace(line);
            if (hex_lines) {
                std::vector<uint8_t> bytes;
                std::string err;
                if (!wallet_hex_to_bytes(line, bytes, err)) {
                    error = "invalid hex candidate in " + file_names[file_idx] + ": " + err;
                    failed = true;
                    return buf.count > 0;
                }
                buf.push_bytes(bytes.data(), bytes.size());
            }
            else {
                if (normalize_nfc_text) {
                    std::string normalized;
                    std::string normalize_error;
                    if (!wallet_normalize_nfc_utf8(line, normalized, normalize_error)) {
                        error = "invalid BIP38 candidate in " + file_names[file_idx] +
                            ": " + normalize_error;
                        failed = true;
                        return buf.count > 0;
                    }
                    if (normalized.size() > WALLET_MAX_PASSWORD_LEN) {
                        error = "BIP38 candidate in " + file_names[file_idx] +
                            " exceeds the 127-byte normalized UTF-8 limit";
                        failed = true;
                        return buf.count > 0;
                    }
                    buf.push_text(normalized);
                }
                else {
                    buf.push_text(line);
                }
            }
        }
        return buf.count > 0;
    }
};

static void wallet_split_pass_batch_round_robin(
    const WalletPassBuf& src,
    const size_t parts,
    std::vector<WalletPassBuf>& dst)
{
    dst.clear();
    dst.resize(parts);
    if (parts == 0u || src.count == 0u) {
        return;
    }
    std::vector<uint32_t> counts(parts, 0u);
    for (uint32_t i = 0u; i < src.count; ++i) {
        ++counts[static_cast<size_t>(i) % parts];
    }
    for (size_t part_idx = 0u; part_idx < parts; ++part_idx) {
        WalletPassBuf& part = dst[part_idx];
        part.count = counts[part_idx];
        part.data.assign(static_cast<size_t>(part.count) * WALLET_PASS_STRIDE, 0);
        part.lens.assign(part.count, 0u);
    }
    std::vector<uint32_t> offsets(parts, 0u);
    for (uint32_t i = 0u; i < src.count; ++i) {
        const size_t part_idx = static_cast<size_t>(i) % parts;
        WalletPassBuf& part = dst[part_idx];
        const uint32_t slot = offsets[part_idx]++;
        const uint8_t len = src.lens[i];
        const char* ptr = src.data.data() + static_cast<size_t>(i) * WALLET_PASS_STRIDE;
        part.lens[slot] = len;
        if (len != 0u) {
            memcpy(part.data.data() + static_cast<size_t>(slot) * WALLET_PASS_STRIDE, ptr, len);
        }
    }
}

static bool wallet_read_split_pass_batch(
    WalletPassReader& reader,
    const uint32_t per_part_max_count,
    const size_t parts,
    std::vector<WalletPassBuf>& batches)
{
    const uint64_t part_count = std::max<uint64_t>(1ull, static_cast<uint64_t>(parts));
    const uint64_t per_part = std::max<uint64_t>(1ull, static_cast<uint64_t>(per_part_max_count));
    if (part_count == 1ull) {
        batches.clear();
        batches.resize(1u);
        if (!reader.read_batch(batches[0], static_cast<uint32_t>(per_part))) {
            batches.clear();
            return false;
        }
        return true;
    }
    const uint64_t combined = std::min<uint64_t>(
        static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()),
        per_part * part_count);
    WalletPassBuf combined_batch;
    if (!reader.read_batch(combined_batch, static_cast<uint32_t>(combined))) {
        batches.clear();
        return false;
    }
    wallet_split_pass_batch_round_robin(combined_batch, parts, batches);
    return true;
}

struct WalletKeystoreDeviceState {
    WalletKeystoreTarget* targets = nullptr;
    uint32_t target_count = 0;
    uint8_t* solved_flags = nullptr;
    uint32_t solved_count = 0;
    uint64_t solved_version_uploaded = UINT64_MAX;
    uint32_t active_target_count_cached = 0;
    WalletMaskSpec* mask_spec = nullptr;
    WalletRangeSpec* range_spec = nullptr;
    uint8_t* scrypt_scratch = nullptr;
    uint64_t scrypt_scratch_stride = 0;
    uint64_t scrypt_scratch_bytes = 0;
    uint64_t scrypt_concurrency = 0;
    char* pass_data = nullptr;
    uint8_t* pass_lens = nullptr;
    std::vector<uint32_t> target_file_indices;
};

static constexpr uint64_t WALLET_SCRYPT_DEFAULT_CONCURRENCY_CAP = 8192ull;
static constexpr uint64_t WALLET_SCRYPT_FILTERED_CONCURRENCY_CAP = 4096ull;
static constexpr uint64_t WALLET_KEYSTORE_SCRYPT_DEFAULT_CONCURRENCY_CAP = 512ull;
static constexpr uint64_t WALLET_KEYSTORE_SCRYPT_LARGE_DICTIONARY_CONCURRENCY_CAP = 1024ull;
static constexpr uint64_t WALLET_KEYSTORE_SCRYPT_SMALL_BATCH_CONCURRENCY_CAP = 256ull;
static constexpr uint64_t WALLET_SCRYPT_GPU_MEMORY_RESERVE = 1ull << 30;
static constexpr uint64_t WALLET_SCRYPT_GPU_MEMORY_RESERVE_FILTERED = 4ull << 30;
static constexpr uint64_t WALLET_SCRYPT_SCRATCH_BUDGET = 16ull << 30;
static constexpr uint64_t WALLET_SCRYPT_SCRATCH_BUDGET_FILTERED = 4ull << 30;
static constexpr uint64_t WALLET_BIP38_AUTO_SCRYPT_SCRATCH_BUDGET = 32ull << 30;
static constexpr uint64_t WALLET_BISQ_SCRYPT_LARGE_STRIDE_THRESHOLD = 128ull << 10;
static constexpr uint64_t WALLET_BISQ_SCRYPT_LARGE_STRIDE_BUDGET = 8ull << 30;

static inline uint64_t wallet_scrypt_memory_reserve_bytes()
{
    const uint64_t filter_bytes = gpu_filter_input_bytes_total();
    if (filter_bytes >= (8ull << 30)) {
        return WALLET_SCRYPT_GPU_MEMORY_RESERVE_FILTERED;
    }
    return WALLET_SCRYPT_GPU_MEMORY_RESERVE;
}

static inline uint64_t wallet_scrypt_default_concurrency_cap()
{
    const uint64_t filter_bytes = gpu_filter_input_bytes_total();
    if (filter_bytes >= (8ull << 30)) {
        return WALLET_SCRYPT_FILTERED_CONCURRENCY_CAP;
    }
    return WALLET_SCRYPT_DEFAULT_CONCURRENCY_CAP;
}

static inline uint64_t wallet_keystore_scrypt_default_concurrency_cap()
{
    return std::min<uint64_t>(
        wallet_scrypt_default_concurrency_cap(),
        WALLET_KEYSTORE_SCRYPT_DEFAULT_CONCURRENCY_CAP);
}

static inline uint64_t wallet_scrypt_align_stride(uint64_t bytes)
{
    return (bytes + 15ull) & ~15ull;
}

static inline uint64_t wallet_scrypt_next_backoff_concurrency(uint64_t concurrency)
{
    if (concurrency <= 1ull) {
        return 0ull;
    }
    const uint64_t next = (concurrency * 15ull) / 16ull;
    return next < concurrency ? next : (concurrency - 1ull);
}

static void wallet_release_keystore_device_state(WalletKeystoreDeviceState& state) {
    if (state.targets) metalFree(state.targets);
    if (state.solved_flags) metalFree(state.solved_flags);
    if (state.mask_spec) metalFree(state.mask_spec);
    if (state.range_spec) metalFree(state.range_spec);
    if (state.scrypt_scratch) metalFree(state.scrypt_scratch);
    if (state.pass_data) metalFree(state.pass_data);
    if (state.pass_lens) metalFree(state.pass_lens);
    state.targets = nullptr;
    state.solved_flags = nullptr;
    state.mask_spec = nullptr;
    state.range_spec = nullptr;
    state.scrypt_scratch = nullptr;
    state.pass_data = nullptr;
    state.pass_lens = nullptr;
    state.target_count = 0;
    state.solved_count = 0;
    state.solved_version_uploaded = UINT64_MAX;
    state.active_target_count_cached = 0;
    state.scrypt_scratch_stride = 0;
    state.scrypt_concurrency = 0;
    state.target_file_indices.clear();
}

static bool wallet_prepare_mask_spec(const std::string& mask, WalletMaskSpec& spec, std::string& err) {
    static const std::string lower = "abcdefghijklmnopqrstuvwxyz";
    static const std::string upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    static const std::string digits = "0123456789";
    static const std::string hexlow = "0123456789abcdef";
    static const std::string symbols = " !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
    memset(&spec, 0, sizeof(spec));
    uint32_t char_write = 0;
    auto add_charset = [&](const std::string& chars) -> bool {
        if (spec.len >= WALLET_MAX_MASK_LEN || chars.empty()) return false;
        if (char_write + chars.size() > WALLET_MAX_MASK_CHARS) return false;
        spec.charset_offset[spec.len] = static_cast<uint16_t>(char_write);
        spec.charset_len[spec.len] = static_cast<uint16_t>(chars.size());
        memcpy(spec.chars + char_write, chars.data(), chars.size());
        char_write += static_cast<uint32_t>(chars.size());
        ++spec.len;
        return true;
    };
    auto add_literal = [&](char c) -> bool {
        std::string s(1, c);
        return add_charset(s);
    };
    for (size_t i = 0; i < mask.size(); ++i) {
        if (mask[i] != '?') {
            if (!add_literal(mask[i])) { err = "mask is too long"; return false; }
            continue;
        }
        if (i + 1 >= mask.size()) { err = "dangling '?' in mask"; return false; }
        const char code = mask[++i];
        std::string chars;
        switch (code) {
        case '?': chars = "?"; break;
        case 'l': chars = lower; break;
        case 'u': chars = upper; break;
        case 'd': chars = digits; break;
        case 'h': chars = hexlow; break;
        case 'H': chars = "0123456789ABCDEF"; break;
        case 's': chars = symbols; break;
        case 'a': {
            for (int c = 0x20; c <= 0x7e; ++c) chars.push_back(static_cast<char>(c));
            break;
        }
        case '1': case '2': case '3': case '4': {
            chars = wallet_custom_charset[code - '1'];
            if (chars.empty()) { err = std::string("-cs") + code + " is empty"; return false; }
            break;
        }
        default:
            err = std::string("unknown mask token ?") + code;
            return false;
        }
        if (!add_charset(chars)) { err = "mask char storage overflow"; return false; }
    }
    if (spec.len == 0) { err = "empty mask"; return false; }
    uint64_t total = 1;
    for (uint32_t i = 0; i < spec.len; ++i) {
        const uint64_t clen = spec.charset_len[i];
        if (clen == 0 || total > std::numeric_limits<uint64_t>::max() / clen) {
            err = "mask candidate count overflows uint64";
            return false;
        }
        total *= clen;
    }
    spec.total_charsets = spec.len;
    spec.total_candidates = total;
    return true;
}

struct WalletRangeHostState {
    std::vector<uint8_t> start;
    std::vector<uint8_t> end;
    std::vector<uint8_t> current;
    size_t current_len = 0;
    size_t end_len = 0;
    bool valid = false;
};

static int wallet_cmp_bytes_same_len(const std::vector<uint8_t>& a, const std::vector<uint8_t>& b) {
    if (a.size() != b.size()) {
        return a.size() < b.size() ? -1 : 1;
    }
    for (size_t i = 0; i < a.size(); ++i) {
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return 0;
}

static void wallet_fill_max_bytes(std::vector<uint8_t>& out, const size_t len) {
    out.assign(len, 0xffu);
}

static uint64_t wallet_bytes_remaining_cap64(const std::vector<uint8_t>& cur, const std::vector<uint8_t>& end, const uint64_t cap) {
    std::vector<uint8_t> diff_bytes(cur.size(), 0u);
    int borrow = 0;
    for (int i = static_cast<int>(cur.size()) - 1; i >= 0; --i) {
        int v = static_cast<int>(end[static_cast<size_t>(i)]) - static_cast<int>(cur[static_cast<size_t>(i)]) - borrow;
        if (v < 0) {
            v += 256;
            borrow = 1;
        }
        else {
            borrow = 0;
        }
        diff_bytes[static_cast<size_t>(i)] = static_cast<uint8_t>(v);
    }
    uint64_t diff = 0;
    bool saturated = false;
    for (size_t i = 0; i < diff_bytes.size(); ++i) {
        if (!saturated) {
            if (diff > (std::numeric_limits<uint64_t>::max() >> 8)) {
                saturated = true;
                diff = std::numeric_limits<uint64_t>::max();
            }
            else {
                diff = (diff << 8) | static_cast<uint64_t>(diff_bytes[i]);
            }
        }
    }
    if (saturated || diff >= cap) {
        return cap;
    }
    return diff + 1ull;
}

static void wallet_add_u64_be_inplace(std::vector<uint8_t>& v, uint64_t add) {
    for (int pos = static_cast<int>(v.size()) - 1; pos >= 0 && add != 0ull; --pos) {
        const uint64_t acc = static_cast<uint64_t>(v[static_cast<size_t>(pos)]) + (add & 0xffull);
        v[static_cast<size_t>(pos)] = static_cast<uint8_t>(acc & 0xffu);
        add = (add >> 8) + (acc >> 8);
    }
}

static bool wallet_prepare_range_state(WalletRangeHostState& state, std::string& err) {
    if (!seqMode || start_point.empty()) {
        err = "-start is required for raw range";
        return false;
    }
    std::vector<uint8_t> start_bytes, end_bytes;
    if (!wallet_hex_to_bytes(start_point, start_bytes, err)) return false;
    if (start_bytes.empty() || start_bytes.size() > WALLET_MAX_PASSWORD_LEN) {
        err = "unsupported -start length";
        return false;
    }
    if (end_point_set) {
        if (!wallet_hex_to_bytes(end_point, end_bytes, err)) return false;
        if (end_bytes.empty() || end_bytes.size() > WALLET_MAX_PASSWORD_LEN) {
            err = "unsupported -end length";
            return false;
        }
    }
    else {
        end_bytes.assign(WALLET_MAX_PASSWORD_LEN, 0xffu);
    }
    if (end_bytes.size() < start_bytes.size()) {
        err = "-end length is smaller than -start length";
        return false;
    }
    if (end_bytes.size() == start_bytes.size() && wallet_cmp_bytes_same_len(start_bytes, end_bytes) > 0) {
        err = "-start is greater than -end";
        return false;
    }
    state.start = start_bytes;
    state.end = end_bytes;
    state.current = start_bytes;
    state.current_len = start_bytes.size();
    state.end_len = end_bytes.size();
    state.valid = true;
    return true;
}

static bool wallet_range_next_window(WalletRangeHostState& state, const uint64_t cap, WalletRangeSpec& spec, uint64_t& count) {
    count = 0;
    if (!state.valid || state.current_len == 0 || state.current_len > WALLET_MAX_PASSWORD_LEN) {
        return false;
    }
    if (state.current_len > state.end_len) {
        state.valid = false;
        return false;
    }

    std::vector<uint8_t> len_end;
    if (state.current_len == state.end_len) {
        len_end = state.end;
    }
    else {
        wallet_fill_max_bytes(len_end, state.current_len);
    }
    if (wallet_cmp_bytes_same_len(state.current, len_end) > 0) {
        ++state.current_len;
        if (state.current_len > state.end_len) {
            state.valid = false;
            return false;
        }
        state.current.assign(state.current_len, 0u);
        return wallet_range_next_window(state, cap, spec, count);
    }

    const uint64_t safe_cap = cap == 0ull ? 1ull : cap;
    const uint64_t remaining_to_len_end = wallet_bytes_remaining_cap64(
        state.current, len_end, std::numeric_limits<uint64_t>::max());
    count = std::min<uint64_t>(remaining_to_len_end, safe_cap);
    memset(&spec, 0, sizeof(spec));
    spec.len = static_cast<uint32_t>(state.current_len);
    memcpy(spec.start, state.current.data(), state.current.size());

    if (count == remaining_to_len_end) {
        ++state.current_len;
        if (state.current_len > state.end_len) {
            state.valid = false;
        }
        else {
            state.current.assign(state.current_len, 0u);
        }
    }
    else {
        wallet_add_u64_be_inplace(state.current, count);
    }
    return count > 0;
}

static std::mutex keystore_solved_mutex;
static uint64_t keystore_solved_version = 0ull;

static metalError_t walletkeystore_sync_solved_flags(
    WalletKeystoreDeviceState& state,
    const std::vector<uint8_t>& solved_files,
    uint32_t& active_target_count)
{
    std::vector<uint8_t> snapshot;
    uint64_t snapshot_version = 0ull;
    {
        std::lock_guard<std::mutex> solved_lock(keystore_solved_mutex);
        snapshot_version = keystore_solved_version;
        if (state.solved_flags != nullptr &&
            state.solved_count != 0u &&
            state.solved_version_uploaded == snapshot_version) {
            active_target_count = state.active_target_count_cached;
            return metalSuccess;
        }
        snapshot = solved_files;
    }

    active_target_count = 0u;
    const size_t logical_count = std::min<size_t>(snapshot.size(), state.solved_count);
    for (size_t i = 0; i < logical_count; ++i) {
        if (snapshot[i] == 0u) {
            ++active_target_count;
        }
    }
    if (state.solved_count > logical_count) {
        active_target_count += static_cast<uint32_t>(state.solved_count - logical_count);
    }

    if (state.solved_flags == nullptr || state.solved_count == 0u) {
        active_target_count = state.target_count;
        state.active_target_count_cached = active_target_count;
        state.solved_version_uploaded = snapshot_version;
        return metalSuccess;
    }
    if (snapshot.empty()) {
        metalError_t st = metalMemset(state.solved_flags, 0, state.solved_count);
        if (st == metalSuccess) {
            state.active_target_count_cached = active_target_count;
            state.solved_version_uploaded = snapshot_version;
        }
        return st;
    }
    const size_t copy_count = std::min<size_t>(snapshot.size(), state.solved_count);
    metalError_t st = metalMemcpy(state.solved_flags, snapshot.data(), copy_count, metalMemcpyHostToDevice);
    if (st != metalSuccess) {
        return st;
    }
    if (copy_count < state.solved_count) {
        st = metalMemset(state.solved_flags + copy_count, 0, state.solved_count - copy_count);
    }
    if (st == metalSuccess) {
        state.active_target_count_cached = active_target_count;
        state.solved_version_uploaded = snapshot_version;
    }
    return st;
}

static uint32_t walletkeystore_active_targets_in_range(
    const WalletKeystoreDeviceState& state,
    const std::vector<uint8_t>& solved_files,
    const uint32_t target_offset,
    const uint32_t target_count)
{
    if (target_count == 0u) return 0u;
    uint32_t active = 0u;
    const uint32_t end = std::min<uint32_t>(state.target_count, target_offset + target_count);
    for (uint32_t i = target_offset; i < end; ++i) {
        uint32_t file_index = i;
        if (i < state.target_file_indices.size()) {
            file_index = state.target_file_indices[i];
        }
        if (file_index >= solved_files.size() || solved_files[file_index] == 0u) {
            ++active;
        }
    }
    return active;
}

static metalError_t wallet_flush_keystore_results(
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved) {
    unsigned long long count = 0;
    metalError_t st = metalMemcpy(&count, p_wallet_count, sizeof(count), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (count == 0ull) return metalSuccess;
    const unsigned long long capped = std::min<unsigned long long>(count, MAX_FOUNDS);
    std::vector<WalletModeResult> results(static_cast<size_t>(capped));
    st = metalMemcpy(results.data(), p_wallet_results, static_cast<size_t>(capped) * sizeof(WalletModeResult), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (count > capped) {
        fprintf(stderr, "[!] Warning: wallet result buffer overflow; increase -fsize [!]\n");
    }
    std::vector<WalletModeResult> filtered;
    filtered.reserve(results.size());
    {
        std::lock_guard<std::mutex> solved_lock(keystore_solved_mutex);
        bool changed = false;
        for (const WalletModeResult& result : results) {
            if (result.target_index < solved_files.size()) {
                if (solved_files[result.target_index]) {
                    continue;
                }
                solved_files[result.target_index] = 1u;
                changed = true;
            }
            filtered.push_back(result);
        }
        if (changed) {
            ++keystore_solved_version;
        }
        all_solved = !solved_files.empty();
        for (uint8_t solved : solved_files) {
            if (!solved) {
                all_solved = false;
                break;
            }
        }
    }
    if (!filtered.empty()) {
        SaveResultKeystore(OUT_FILE, Founds, save, filtered.data(), static_cast<unsigned long long>(filtered.size()), target_files);
    }
    st = metalMemset(p_wallet_count, 0, sizeof(unsigned long long));
    return st;
}

static metalError_t wallet_launch_keystore_dict_batch(
    const WalletPassBuf& batch,
    WalletKeystoreDeviceState& state,
    const uint32_t target_offset,
    const uint32_t target_count,
    const bool use_scrypt_subchunks,
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved)
{
    if (target_count == 0u || batch.count == 0u) return metalSuccess;
    uint32_t active_target_count = 0u;
    metalError_t st = walletkeystore_sync_solved_flags(state, solved_files, active_target_count);
    if (st != metalSuccess) goto Done;
    if (active_target_count == 0u) {
        all_solved = true;
        goto Done;
    }
    active_target_count = walletkeystore_active_targets_in_range(state, solved_files, target_offset, target_count);
    if (active_target_count == 0u) goto Done;
    st = copy_to_device_grow(reinterpret_cast<void**>(&state.pass_data), batch.data.data(), batch.data.empty() ? 1u : batch.data.size());
    if (st != metalSuccess) goto Done;
    st = copy_to_device_grow(reinterpret_cast<void**>(&state.pass_lens), batch.lens.data(), batch.lens.empty() ? 1u : batch.lens.size());
    if (st != metalSuccess) goto Done;
    {
        uint64_t processed = 0ull;
        const uint64_t sublaunch_cap = use_scrypt_subchunks
            ? std::max<uint64_t>(1ull, state.scrypt_concurrency)
            : static_cast<uint64_t>(batch.count);
        while (processed < static_cast<uint64_t>(batch.count) && !all_solved) {
            const uint64_t sub_count = std::min<uint64_t>(sublaunch_cap, static_cast<uint64_t>(batch.count) - processed);
            metal_launch("workerKeystoreV3", BLOCK_NUMBER, BLOCK_THREADS, nullptr, nullptr, _dev_precomp, pitch, state.targets + target_offset, target_count, state.solved_flags, state.solved_count, WALLET_CANDIDATE_DICTIONARY, state.pass_data, state.pass_lens, batch.count, nullptr, nullptr, state.scrypt_scratch, state.scrypt_scratch_stride, processed, sub_count);
            st = metalGetLastError();
            if (st != metalSuccess) goto Done;
            st = metalDeviceSynchronize();
            if (st != metalSuccess) goto Done;
            counterTotal += sub_count * static_cast<uint64_t>(active_target_count);
            st = wallet_flush_keystore_results(target_files, solved_files, all_solved);
            if (st != metalSuccess) goto Done;
            processed += sub_count;
            if (use_scrypt_subchunks) {
                active_target_count = walletkeystore_active_targets_in_range(state, solved_files, target_offset, target_count);
                if (active_target_count == 0u) break;
            }
        }
    }
Done:
    return st;
}

static metalError_t wallet_launch_keystore_generated(
    WalletKeystoreDeviceState& state,
    uint8_t candidate_kind,
    const uint32_t target_offset,
    const uint32_t target_count,
    const bool use_scrypt_subchunks,
    uint64_t start,
    uint64_t count,
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved)
{
    if (target_count == 0u || count == 0ull) return metalSuccess;
    uint32_t active_target_count = 0u;
    metalError_t st = walletkeystore_sync_solved_flags(state, solved_files, active_target_count);
    if (st != metalSuccess) return st;
    if (active_target_count == 0u) {
        all_solved = true;
        return metalSuccess;
    }
    active_target_count = walletkeystore_active_targets_in_range(state, solved_files, target_offset, target_count);
    if (active_target_count == 0u) return metalSuccess;
    uint64_t processed = 0ull;
    const uint64_t sublaunch_cap = use_scrypt_subchunks
        ? std::max<uint64_t>(1ull, state.scrypt_concurrency)
        : count;
    while (processed < count && !all_solved) {
        const uint64_t sub_count = std::min<uint64_t>(sublaunch_cap, count - processed);
        metal_launch("workerKeystoreV3", BLOCK_NUMBER, BLOCK_THREADS, nullptr, nullptr, _dev_precomp, pitch, state.targets + target_offset, target_count, state.solved_flags, state.solved_count, candidate_kind, nullptr, nullptr, 0u, state.mask_spec, state.range_spec, state.scrypt_scratch, state.scrypt_scratch_stride, start + processed, sub_count);
        st = metalGetLastError();
        if (st != metalSuccess) return st;
        st = metalDeviceSynchronize();
        if (st != metalSuccess) return st;
        counterTotal += sub_count * static_cast<uint64_t>(active_target_count);
        st = wallet_flush_keystore_results(target_files, solved_files, all_solved);
        if (st != metalSuccess) return st;
        processed += sub_count;
        if (use_scrypt_subchunks) {
            active_target_count = walletkeystore_active_targets_in_range(state, solved_files, target_offset, target_count);
            if (active_target_count == 0u) break;
        }
    }
    return metalSuccess;
}

struct WalletDatDeviceState {
    WalletDatTarget* targets = nullptr;
    WalletDatGroup* groups = nullptr;
    uint32_t target_count = 0;
    uint32_t group_count = 0;
    WalletDatMasterHit* master_hits = nullptr;
    uint32_t* master_hit_count = nullptr;
    WalletDatKdfTmp* kdf_tmp = nullptr;
    uint64_t kdf_tmp_capacity = 0ull;
    uint8_t* solved_flags = nullptr;
    uint32_t solved_count = 0;
    uint64_t solved_version_uploaded = UINT64_MAX;
    uint32_t active_target_count_cached = 0;
    std::vector<uint32_t> target_file_indices;
    std::vector<WalletDatTargetChunk> target_chunks;
    WalletMaskSpec* mask_spec = nullptr;
    WalletRangeSpec* range_spec = nullptr;
    uint8_t* scrypt_scratch = nullptr;
    uint64_t scrypt_scratch_stride = 0;
    uint64_t scrypt_scratch_bytes = 0;
    uint64_t scrypt_concurrency = 0;
    char* pass_data = nullptr;
    uint8_t* pass_lens = nullptr;
};

static std::mutex walletdat_solved_mutex;
static uint64_t walletdat_solved_version = 0ull;

static void wallet_release_walletdat_device_state(WalletDatDeviceState& state) {
    if (state.targets) metalFree(state.targets);
    if (state.groups) metalFree(state.groups);
    if (state.master_hits) metalFree(state.master_hits);
    if (state.master_hit_count) metalFree(state.master_hit_count);
    if (state.kdf_tmp) metalFree(state.kdf_tmp);
    if (state.solved_flags) metalFree(state.solved_flags);
    if (state.mask_spec) metalFree(state.mask_spec);
    if (state.range_spec) metalFree(state.range_spec);
    if (state.scrypt_scratch) metalFree(state.scrypt_scratch);
    if (state.pass_data) metalFree(state.pass_data);
    if (state.pass_lens) metalFree(state.pass_lens);
    state.targets = nullptr;
    state.groups = nullptr;
    state.master_hits = nullptr;
    state.master_hit_count = nullptr;
    state.kdf_tmp = nullptr;
    state.kdf_tmp_capacity = 0ull;
    state.solved_flags = nullptr;
    state.mask_spec = nullptr;
    state.range_spec = nullptr;
    state.pass_data = nullptr;
    state.pass_lens = nullptr;
    state.target_count = 0;
    state.group_count = 0;
    state.solved_count = 0;
    state.solved_version_uploaded = UINT64_MAX;
    state.active_target_count_cached = 0;
    state.target_file_indices.clear();
    state.target_chunks.clear();
}

static metalError_t walletdat_sync_solved_flags(
    WalletDatDeviceState& state,
    const std::vector<uint8_t>& solved_files,
    uint32_t& active_target_count)
{
    std::vector<uint8_t> snapshot;
    uint64_t snapshot_version = 0ull;
    {
        std::lock_guard<std::mutex> solved_lock(walletdat_solved_mutex);
        snapshot_version = walletdat_solved_version;
        if (state.solved_flags != nullptr &&
            state.solved_count != 0u &&
            state.solved_version_uploaded == snapshot_version) {
            active_target_count = state.active_target_count_cached;
            return metalSuccess;
        }
        snapshot = solved_files;
    }
    active_target_count = 0u;
    for (uint32_t file_index : state.target_file_indices) {
        if (file_index >= snapshot.size() || snapshot[file_index] == 0u) {
            ++active_target_count;
        }
    }
    if (state.solved_flags == nullptr || state.solved_count == 0u) {
        state.active_target_count_cached = active_target_count;
        state.solved_version_uploaded = snapshot_version;
        return metalSuccess;
    }
    if (snapshot.empty()) {
        metalError_t st = metalMemset(state.solved_flags, 0, state.solved_count);
        if (st == metalSuccess) {
            state.active_target_count_cached = active_target_count;
            state.solved_version_uploaded = snapshot_version;
        }
        return st;
    }
    const size_t copy_count = std::min<size_t>(snapshot.size(), state.solved_count);
    metalError_t st = metalMemcpy(state.solved_flags, snapshot.data(), copy_count, metalMemcpyHostToDevice);
    if (st != metalSuccess) {
        return st;
    }
    if (copy_count < state.solved_count) {
        st = metalMemset(state.solved_flags + copy_count, 0, state.solved_count - copy_count);
    }
    if (st == metalSuccess) {
        state.active_target_count_cached = active_target_count;
        state.solved_version_uploaded = snapshot_version;
    }
    return st;
}

static metalError_t wallet_flush_walletdat_results(
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved)
{
    unsigned long long count = 0;
    metalError_t st = metalMemcpy(&count, p_wallet_count, sizeof(count), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (count == 0ull) return metalSuccess;
    const unsigned long long capped = std::min<unsigned long long>(count, MAX_FOUNDS);
    std::vector<WalletModeResult> results(static_cast<size_t>(capped));
    st = metalMemcpy(results.data(), p_wallet_results, static_cast<size_t>(capped) * sizeof(WalletModeResult), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (count > capped) {
        fprintf(stderr, "[!] Warning: wallet.dat result buffer overflow; increase -fsize [!]\n");
    }
    std::vector<WalletModeResult> filtered;
    filtered.reserve(results.size());
    {
        std::lock_guard<std::mutex> solved_lock(walletdat_solved_mutex);
        bool changed = false;
        for (const WalletModeResult& result : results) {
            if (result.target_index < solved_files.size()) {
                if (solved_files[result.target_index]) {
                    continue;
                }
                solved_files[result.target_index] = 1u;
                changed = true;
            }
            filtered.push_back(result);
        }
        if (changed) {
            ++walletdat_solved_version;
        }
        all_solved = !solved_files.empty();
        for (uint8_t solved : solved_files) {
            if (!solved) {
                all_solved = false;
                break;
            }
        }
    }
    if (!filtered.empty()) {
        SaveResultWalletDat(OUT_FILE, Founds, save, filtered.data(), static_cast<unsigned long long>(filtered.size()), target_files);
    }
    st = metalMemset(p_wallet_count, 0, sizeof(unsigned long long));
    return st;
}

static constexpr uint32_t WALLETDAT_MAX_TARGETS_PER_CHUNK = 4096u;
static constexpr uint32_t WALLETDAT_DICT_EARLY_PROBE_STEPS[] = { 4096u, 65536u, 262144u };

static uint64_t walletdat_launch_thread_count()
{
    uint64_t launch_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (launch_threads == 0ull) {
        launch_threads = 1ull;
    }
    return launch_threads;
}

static uint64_t walletdat_effective_min_jobs_per_launch()
{
    const uint64_t launch_threads = walletdat_launch_thread_count();
    if (walletdat_min_jobs_per_launch == 0ull) {
        return std::min<uint64_t>(launch_threads, WALLETDAT_AUTO_MIN_JOBS_CAP);
    }
    return std::min<uint64_t>(walletdat_min_jobs_per_launch, launch_threads);
}

static inline uint64_t wallet_saturating_mul_u64(const uint64_t a, const uint64_t b)
{
    if (a != 0ull && b > std::numeric_limits<uint64_t>::max() / a) {
        return std::numeric_limits<uint64_t>::max();
    }
    return a * b;
}

static uint32_t walletdat_kernel_blocks_for_jobs(uint64_t job_count)
{
    if (job_count == 0ull) {
        return 1u;
    }
    const uint64_t threads = std::max<uint64_t>(1ull, static_cast<uint64_t>(BLOCK_THREADS));
    const uint64_t requested = (job_count + threads - 1ull) / threads;
    return static_cast<uint32_t>(std::max<uint64_t>(1ull, std::min<uint64_t>(static_cast<uint64_t>(BLOCK_NUMBER), requested)));
}

static uint64_t walletdat_estimate_kdf_tmp_capacity(
    const std::vector<WalletDatTargetChunk>& chunks,
    uint64_t candidate_window)
{
    const uint64_t launch_threads = walletdat_launch_thread_count();
    candidate_window = std::max<uint64_t>(1ull, candidate_window);
    uint64_t max_chunk_count = 1ull;
    for (const WalletDatTargetChunk& chunk : chunks) {
        max_chunk_count = std::max<uint64_t>(max_chunk_count, static_cast<uint64_t>(std::max<uint32_t>(1u, chunk.count)));
    }
    if (candidate_window > std::numeric_limits<uint64_t>::max() / max_chunk_count) {
        return launch_threads;
    }
    return std::max<uint64_t>(1ull, std::min<uint64_t>(launch_threads, candidate_window * max_chunk_count));
}

static uint64_t wallet_effective_dict_batch_per_gpu(uint64_t requested)
{
    uint64_t batch = std::max<uint64_t>(1ull, requested);
    uint64_t floor = std::max<uint64_t>(WALLETDAT_DICT_BATCH_FLOOR, walletdat_effective_min_jobs_per_launch());
    if (!walletdat_min_jobs_explicit) {
        floor = std::min<uint64_t>(floor, WALLETDAT_AUTO_MIN_JOBS_CAP);
    }
    batch = std::max<uint64_t>(batch, floor);
    return std::min<uint64_t>(batch, static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()));
}

static uint32_t wallet_effective_dict_batch_u32(const char* mode_name, uint64_t requested)
{
    const uint64_t effective = wallet_effective_dict_batch_per_gpu(requested);
    if (effective != requested) {
        printf("[!] %s dictionary batch raised to %llu password(s)/GPU for occupancy (requested %llu) [!]\n",
            mode_name,
            static_cast<unsigned long long>(effective),
            static_cast<unsigned long long>(requested));
        fflush(stdout);
    }
    return static_cast<uint32_t>(std::min<uint64_t>(
        static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()), effective));
}

static bool walletdat_dict_use_early_probe(const std::vector<WalletDatTargetChunk>& chunks)
{
    // Small dictionary probes are useful for one/few wallet targets, but they
    // underfill late heavy chunks in large scan-all/multi-target runs.
    return chunks.size() <= 1u;
}

static uint32_t walletdat_dict_batch_for_round(const uint32_t steady_batch, const uint64_t round, const bool use_early_probe)
{
    if (steady_batch == 0u) {
        return 1u;
    }
    if (!use_early_probe) {
        return steady_batch;
    }
    const size_t probe_count = sizeof(WALLETDAT_DICT_EARLY_PROBE_STEPS) / sizeof(WALLETDAT_DICT_EARLY_PROBE_STEPS[0]);
    if (round < static_cast<uint64_t>(probe_count)) {
        return std::max<uint32_t>(1u, std::min<uint32_t>(
            steady_batch,
            WALLETDAT_DICT_EARLY_PROBE_STEPS[static_cast<size_t>(round)]));
    }
    return steady_batch;
}

static uint64_t walletdat_effective_generated_window(uint64_t requested)
{
    uint64_t effective = std::max<uint64_t>(1ull, requested);
    if (!walletdat_min_jobs_explicit && effective < WALLETDAT_GENERATED_WINDOW_FLOOR) {
        effective = WALLETDAT_GENERATED_WINDOW_FLOOR;
    }
    return effective;
}

static bool walletdat_same_kdf_group(const WalletDatTarget& a, const WalletDatTarget& b)
{
    if (a.iterations != b.iterations || a.salt_len != b.salt_len) {
        return false;
    }
    if (a.salt_len > WALLET_MAX_SALT_LEN) {
        return false;
    }
    return std::memcmp(a.salt, b.salt, a.salt_len) == 0;
}

static void walletdat_build_kdf_groups(
    const std::vector<WalletDatTarget>& targets,
    std::vector<WalletDatGroup>& groups,
    uint64_t& grouped_iteration_work)
{
    groups.clear();
    grouped_iteration_work = 0ull;
    if (targets.empty()) {
        return;
    }
    uint32_t begin = 0u;
    for (uint32_t i = 1u; i <= static_cast<uint32_t>(targets.size()); ++i) {
        if (i != static_cast<uint32_t>(targets.size()) && walletdat_same_kdf_group(targets[begin], targets[i])) {
            continue;
        }
        WalletDatGroup group{};
        group.iterations = targets[begin].iterations;
        group.salt_len = targets[begin].salt_len;
        group.target_offset = begin;
        group.target_count = i - begin;
        const uint32_t salt_copy = std::min<uint32_t>(group.salt_len, WALLET_MAX_SALT_LEN);
        for (uint32_t j = 0u; j < salt_copy; ++j) {
            group.salt[j] = targets[begin].salt[j];
        }
        groups.push_back(group);
        grouped_iteration_work += static_cast<uint64_t>(std::max<uint32_t>(1u, group.iterations));
        begin = i;
    }
}

static void walletdat_build_group_chunks(
    const std::vector<WalletDatGroup>& groups,
    std::vector<WalletDatTargetChunk>& chunks)
{
    chunks.clear();
    if (groups.empty()) {
        return;
    }
    uint32_t begin = 0u;
    uint64_t work = 0ull;
    uint32_t target_count = 0u;
    uint32_t min_iter = 0u;
    uint32_t max_iter = 0u;
    for (uint32_t i = 0u; i < static_cast<uint32_t>(groups.size()); ++i) {
        const uint64_t iter = std::max<uint64_t>(1ull, static_cast<uint64_t>(groups[i].iterations));
        const uint32_t count = i - begin;
        const bool count_full = count >= WALLETDAT_MAX_TARGETS_PER_CHUNK;
        const bool work_full = count != 0u && work + iter > walletdat_max_kdf_iter_work_per_launch;
        if (count_full || work_full) {
            chunks.push_back({ begin, count, target_count, work, min_iter, max_iter });
            begin = i;
            work = 0ull;
            target_count = 0u;
            min_iter = 0u;
            max_iter = 0u;
        }
        work += iter;
        target_count += groups[i].target_count;
        if (min_iter == 0u) {
            min_iter = groups[i].iterations;
        }
        else {
            min_iter = std::min<uint32_t>(min_iter, groups[i].iterations);
        }
        max_iter = std::max<uint32_t>(max_iter, groups[i].iterations);
    }
    if (begin < static_cast<uint32_t>(groups.size())) {
        chunks.push_back({ begin, static_cast<uint32_t>(groups.size()) - begin, target_count, work, min_iter, max_iter });
    }
}

static uint64_t walletdat_candidate_sublaunch_count(
    const uint64_t remaining,
    const uint64_t iteration_work,
    const uint32_t target_count,
    const uint64_t tmp_capacity)
{
    if (remaining == 0ull) {
        return 0ull;
    }
    if (tmp_capacity != 0ull) {
        const uint64_t targets = std::max<uint64_t>(1ull, static_cast<uint64_t>(target_count));
        const uint64_t by_tmp = std::max<uint64_t>(1ull, tmp_capacity / targets);
        return std::min<uint64_t>(remaining, by_tmp);
    }
    const uint64_t work = iteration_work == 0ull ? 1ull : iteration_work;
    uint64_t by_work = walletdat_max_kdf_iter_work_per_launch / work;
    if (by_work == 0ull) {
        by_work = 1ull;
    }
    const uint64_t targets = std::max<uint64_t>(1ull, static_cast<uint64_t>(target_count));
    const uint64_t min_jobs = walletdat_effective_min_jobs_per_launch();
    const uint64_t by_occupancy = (min_jobs + targets - 1ull) / targets;
    uint64_t occupancy_goal = by_occupancy;
    if (!walletdat_min_jobs_explicit) {
        const uint64_t launch_work_cap =
            walletdat_max_kdf_iter_work_per_launch > std::numeric_limits<uint64_t>::max() / WALLETDAT_AUTO_LAUNCH_WORK_MULTIPLIER
            ? std::numeric_limits<uint64_t>::max()
            : walletdat_max_kdf_iter_work_per_launch * WALLETDAT_AUTO_LAUNCH_WORK_MULTIPLIER;
        const uint64_t by_launch_work = std::max<uint64_t>(1ull, launch_work_cap / work);
        occupancy_goal = std::min<uint64_t>(occupancy_goal, by_launch_work);
    }
    return std::min<uint64_t>(remaining, std::max<uint64_t>(by_work, occupancy_goal));
}

static metalError_t walletdat_launch_staged_batch(
    WalletDatDeviceState& state,
    const WalletDatTargetChunk& chunk,
    uint8_t candidate_kind,
    uint32_t pass_count,
    uint64_t candidate_start,
    uint64_t candidate_count,
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved)
{
    if (candidate_count == 0ull || chunk.count == 0u) {
        return metalSuccess;
    }
    if (state.master_hits == nullptr || state.master_hit_count == nullptr || MAX_FOUNDS == 0u) {
        return metalErrorMemoryAllocation;
    }
    const uint64_t total_jobs = candidate_count * static_cast<uint64_t>(chunk.count);
    const uint64_t total_target_checks = candidate_count * static_cast<uint64_t>(std::max<uint32_t>(1u, chunk.target_count));
    const uint64_t total_kdf_iterations = wallet_saturating_mul_u64(
        candidate_count,
        static_cast<uint64_t>(std::max<uint64_t>(1ull, chunk.iteration_work)));
    if (state.groups == nullptr || state.kdf_tmp == nullptr || state.kdf_tmp_capacity == 0ull || total_jobs > state.kdf_tmp_capacity) {
        return metalErrorMemoryAllocation;
    }
    const uint64_t capped_jobs = std::min<uint64_t>(total_jobs, state.kdf_tmp_capacity);
    const uint32_t kdf_blocks = walletdat_kernel_blocks_for_jobs(capped_jobs);

    metalError_t st = metalMemset(state.master_hit_count, 0, sizeof(uint32_t));
    if (st != metalSuccess) return st;

    metal_launch("workerWalletDatGroupKdfInit", kdf_blocks, BLOCK_THREADS, state.groups + chunk.offset, chunk.count, candidate_kind, state.pass_data, state.pass_lens, pass_count, state.mask_spec, state.range_spec, candidate_start, candidate_count, state.kdf_tmp, state.kdf_tmp_capacity);
    st = metalGetLastError();
    if (st != metalSuccess) return st;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;

    uint64_t credited_checks = 0ull;
    uint64_t credited_kdf_iterations = 0ull;
    for (uint32_t loop_pos = 1u; loop_pos < chunk.max_iterations; ) {
        const uint32_t remaining = chunk.max_iterations - loop_pos;
        const uint32_t loop_count = std::min<uint32_t>(remaining, walletdat_staged_kdf_loop_iters);
        if (chunk.min_iterations == chunk.max_iterations) {
            metal_launch("workerWalletDatKdfLoopUniform", kdf_blocks, BLOCK_THREADS, total_jobs, loop_count, state.kdf_tmp, state.kdf_tmp_capacity);
        }
        else {
            metal_launch("workerWalletDatGroupKdfLoop", kdf_blocks, BLOCK_THREADS, state.groups + chunk.offset, chunk.count, candidate_count, loop_pos, loop_count, state.kdf_tmp, state.kdf_tmp_capacity);
        }
        st = metalGetLastError();
        if (st != metalSuccess) return st;
        st = metalDeviceSynchronize();
        if (st != metalSuccess) return st;
        loop_pos += loop_count;
        if (chunk.max_iterations > 1u && total_kdf_iterations != 0ull) {
            const long double scaled =
                (static_cast<long double>(total_kdf_iterations) * static_cast<long double>(loop_pos)) /
                static_cast<long double>(chunk.max_iterations);
            const uint64_t next_kdf_credit = scaled >= static_cast<long double>(std::numeric_limits<uint64_t>::max())
                ? std::numeric_limits<uint64_t>::max()
                : static_cast<uint64_t>(scaled);
            if (next_kdf_credit > credited_kdf_iterations) {
                counterWalletDatKdfIterations += next_kdf_credit - credited_kdf_iterations;
                credited_kdf_iterations = next_kdf_credit;
            }
        }
    }

    metal_launch("workerWalletDatGroupKdfCheck", kdf_blocks, BLOCK_THREADS, state.targets, state.groups + chunk.offset, chunk.count, state.solved_flags, state.solved_count, candidate_start, candidate_count, state.kdf_tmp, state.kdf_tmp_capacity, state.master_hits, state.master_hit_count, MAX_FOUNDS);
    st = metalGetLastError();
    if (st != metalSuccess) return st;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;

    if (total_target_checks > credited_checks) {
        counterTotal += total_target_checks - credited_checks;
    }
    if (total_kdf_iterations > credited_kdf_iterations) {
        counterWalletDatKdfIterations += total_kdf_iterations - credited_kdf_iterations;
    }

    uint32_t master_hits = 0u;
    st = metalMemcpy(&master_hits, state.master_hit_count, sizeof(master_hits), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (master_hits == 0u) {
        return metalSuccess;
    }
    if (master_hits > MAX_FOUNDS) {
        fprintf(stderr, "[!] Warning: wallet.dat master-hit buffer overflow; increase -fsize [!]\n");
        master_hits = MAX_FOUNDS;
    }

    const uint32_t resolve_blocks = std::max<uint32_t>(1u, std::min<uint32_t>(
        BLOCK_NUMBER,
        (master_hits + static_cast<uint32_t>(BLOCK_THREADS) - 1u) / static_cast<uint32_t>(BLOCK_THREADS)));
    metal_launch("workerWalletDatResolveHits", resolve_blocks, BLOCK_THREADS, nullptr, nullptr, _dev_precomp, pitch, state.targets, state.solved_flags, state.solved_count, candidate_kind, state.pass_data, state.pass_lens, pass_count, state.mask_spec, state.range_spec, state.master_hits, master_hits);
    st = metalGetLastError();
    if (st != metalSuccess) return st;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;

    return wallet_flush_walletdat_results(target_files, solved_files, all_solved);
}

static metalError_t wallet_launch_walletdat_dict_batch(
    const WalletPassBuf& batch,
    WalletDatDeviceState& state,
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved)
{
    uint32_t active_target_count = 0u;
    metalError_t st = metalSuccess;
    std::vector<uint64_t> chunk_processed;
    uint64_t credited_password_candidates = 0ull;
    st = walletdat_sync_solved_flags(state, solved_files, active_target_count);
    if (st != metalSuccess) goto Done;
    if (active_target_count == 0u) {
        all_solved = true;
        goto Done;
    }
    st = copy_to_device_grow(reinterpret_cast<void**>(&state.pass_data), batch.data.data(), batch.data.empty() ? 1u : batch.data.size());
    if (st != metalSuccess) goto Done;
    st = copy_to_device_grow(reinterpret_cast<void**>(&state.pass_lens), batch.lens.data(), batch.lens.empty() ? 1u : batch.lens.size());
    if (st != metalSuccess) goto Done;
    chunk_processed.assign(state.target_chunks.size(), 0ull);
    for (;;) {
        bool any_progress = false;
        bool all_chunks_done = true;
        for (size_t chunk_idx = 0; chunk_idx < state.target_chunks.size() && !all_solved; ++chunk_idx) {
            const WalletDatTargetChunk& chunk = state.target_chunks[chunk_idx];
            if (chunk.count == 0u) continue;
            const uint64_t processed = chunk_processed[chunk_idx];
            if (processed >= static_cast<uint64_t>(batch.count)) continue;
            all_chunks_done = false;
            const uint64_t sub_count = walletdat_candidate_sublaunch_count(
                static_cast<uint64_t>(batch.count) - processed, chunk.iteration_work, chunk.count, state.kdf_tmp_capacity);
            if (sub_count == 0ull) continue;
            const uint64_t next_credited_password_candidates = processed + sub_count;
            st = walletdat_launch_staged_batch(
                state, chunk, WALLET_CANDIDATE_DICTIONARY, batch.count,
                processed, sub_count, target_files, solved_files, all_solved);
            if (st != metalSuccess) goto Done;
            if (next_credited_password_candidates > credited_password_candidates) {
                counterWalletPasswordCandidates += next_credited_password_candidates - credited_password_candidates;
                credited_password_candidates = next_credited_password_candidates;
            }
            chunk_processed[chunk_idx] = processed + sub_count;
            any_progress = true;
        }
        if (all_chunks_done || !any_progress || all_solved) break;
    }
Done:
    return st;
}

static inline uint64_t wallet_scrypt_scratch_budget_bytes(uint64_t hard_cap, uint64_t max_stride)
{
    const uint64_t filter_bytes = gpu_filter_input_bytes_total();
    if (hard_cap < max_stride) {
        return 0ull;
    }
    if (wallet_scrypt_scratch_budget_explicit) {
        const uint64_t explicit_cap =
            wallet_scrypt_scratch_budget_override_mib << 20;
        if (explicit_cap < max_stride) {
            return 0ull;
        }
        return std::min<uint64_t>(hard_cap, explicit_cap);
    }
    const uint64_t preferred = filter_bytes >= (8ull << 30)
        ? WALLET_SCRYPT_SCRATCH_BUDGET_FILTERED
        : WALLET_SCRYPT_SCRATCH_BUDGET;
    return std::min<uint64_t>(hard_cap, std::max<uint64_t>(max_stride, preferred));
}

static metalError_t wallet_launch_walletdat_generated(
    WalletDatDeviceState& state,
    uint8_t candidate_kind,
    uint64_t start,
    uint64_t count,
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved)
{
    metalError_t st = metalSuccess;
    uint32_t active_target_count = 0u;
    st = walletdat_sync_solved_flags(state, solved_files, active_target_count);
    if (st != metalSuccess) return st;
    if (active_target_count == 0u) {
        all_solved = true;
        return metalSuccess;
    }
    std::vector<uint64_t> chunk_processed(state.target_chunks.size(), 0ull);
    uint64_t credited_password_candidates = 0ull;
    for (;;) {
        bool any_progress = false;
        bool all_chunks_done = true;
        for (size_t chunk_idx = 0; chunk_idx < state.target_chunks.size() && !all_solved; ++chunk_idx) {
            const WalletDatTargetChunk& chunk = state.target_chunks[chunk_idx];
            if (chunk.count == 0u) continue;
            const uint64_t processed = chunk_processed[chunk_idx];
            if (processed >= count) continue;
            all_chunks_done = false;
            const uint64_t sub_count = walletdat_candidate_sublaunch_count(count - processed, chunk.iteration_work, chunk.count, state.kdf_tmp_capacity);
            if (sub_count == 0ull) continue;
            const uint64_t next_credited_password_candidates = processed + sub_count;
            st = walletdat_launch_staged_batch(
                state, chunk, candidate_kind, 0u,
                start + processed, sub_count, target_files, solved_files, all_solved);
            if (st != metalSuccess) return st;
            if (next_credited_password_candidates > credited_password_candidates) {
                counterWalletPasswordCandidates += next_credited_password_candidates - credited_password_candidates;
                credited_password_candidates = next_credited_password_candidates;
            }
            chunk_processed[chunk_idx] = processed + sub_count;
            any_progress = true;
        }
        if (all_chunks_done || !any_progress || all_solved) break;
    }
    return metalSuccess;
}

