static uint32_t wallet_active_targets_from_indices(const std::vector<uint32_t>& indices, const std::vector<uint8_t>& solved_files) {
    uint32_t active = 0u;
    for (uint32_t file_index : indices) {
        if (file_index >= solved_files.size() || solved_files[file_index] == 0u) ++active;
    }
    return active;
}

static metalError_t wallet_sync_solved_flags_common(
    uint8_t* solved_flags,
    uint32_t solved_count,
    uint64_t& uploaded_version,
    uint32_t& active_cached,
    const std::vector<uint32_t>& target_file_indices,
    const std::vector<uint8_t>& solved_files,
    std::mutex& mtx,
    uint64_t global_version,
    uint32_t& active_target_count)
{
    std::vector<uint8_t> snapshot;
    {
        std::lock_guard<std::mutex> solved_lock(mtx);
        if (solved_flags != nullptr && solved_count != 0u && uploaded_version == global_version) {
            active_target_count = active_cached;
            return metalSuccess;
        }
        snapshot = solved_files;
    }
    active_target_count = wallet_active_targets_from_indices(target_file_indices, snapshot);
    if (solved_flags == nullptr || solved_count == 0u) {
        active_cached = active_target_count;
        uploaded_version = global_version;
        return metalSuccess;
    }
    metalError_t st = metalSuccess;
    if (snapshot.empty()) {
        st = metalMemset(solved_flags, 0, solved_count);
    }
    else {
        const size_t copy_count = std::min<size_t>(snapshot.size(), solved_count);
        st = metalMemcpy(solved_flags, snapshot.data(), copy_count, metalMemcpyHostToDevice);
        if (st == metalSuccess && copy_count < solved_count) {
            st = metalMemset(solved_flags + copy_count, 0, solved_count - copy_count);
        }
    }
    if (st == metalSuccess) {
        active_cached = active_target_count;
        uploaded_version = global_version;
    }
    return st;
}

static void wallet_build_generic_chunks_from_work(
    const std::vector<uint64_t>& work_by_target,
    std::vector<WalletGenericTargetChunk>& chunks,
    uint64_t max_work_per_chunk,
    const std::vector<uint64_t>* scratch_by_target = nullptr)
{
    chunks.clear();
    if (work_by_target.empty()) return;
    if (max_work_per_chunk == 0ull) max_work_per_chunk = 1ull;
    uint32_t begin = 0u;
    uint64_t work = 0ull;
    uint64_t scratch_stride = 0ull;
    for (uint32_t i = 0; i < static_cast<uint32_t>(work_by_target.size()); ++i) {
        const uint64_t w = std::max<uint64_t>(1ull, work_by_target[i]);
        const uint32_t count = i - begin;
        if (count != 0u && work + w > max_work_per_chunk) {
            chunks.push_back({ begin, count, work, scratch_stride });
            begin = i;
            work = 0ull;
            scratch_stride = 0ull;
        }
        work += w;
        if (scratch_by_target != nullptr && i < scratch_by_target->size()) {
            scratch_stride = std::max<uint64_t>(scratch_stride, (*scratch_by_target)[i]);
        }
    }
    if (begin < static_cast<uint32_t>(work_by_target.size())) {
        chunks.push_back({ begin, static_cast<uint32_t>(work_by_target.size()) - begin, work, scratch_stride });
    }
}

static uint64_t wallet_generic_candidate_sublaunch_count(
    const uint64_t remaining,
    const uint64_t work,
    const uint32_t target_count)
{
    if (remaining == 0ull) return 0ull;
    const uint64_t safe_work = work == 0ull ? 1ull : work;
    uint64_t by_work = walletdat_max_kdf_iter_work_per_launch / safe_work;
    if (by_work == 0ull) by_work = 1ull;
    const uint64_t targets = std::max<uint64_t>(1ull, static_cast<uint64_t>(target_count));
    const uint64_t min_jobs = walletdat_effective_min_jobs_per_launch();
    const uint64_t by_occupancy = (min_jobs + targets - 1ull) / targets;
    return std::min<uint64_t>(remaining, std::max<uint64_t>(by_work, by_occupancy));
}

static void wallet_build_browservault_groups(
    const std::vector<BrowserVaultDeviceTarget>& targets,
    std::vector<BrowserVaultGroup>& groups,
    std::vector<uint64_t>& work_by_group)
{
    groups.clear();
    work_by_group.clear();
    if (targets.empty()) return;

    uint32_t begin = 0u;
    while (begin < static_cast<uint32_t>(targets.size())) {
        const BrowserVaultDeviceTarget& first = targets[begin];
        uint32_t end = begin + 1u;
        while (end < static_cast<uint32_t>(targets.size())) {
            const BrowserVaultDeviceTarget& t = targets[end];
            if (t.profile != first.profile ||
                t.iterations != first.iterations || t.salt_len != first.salt_len ||
                t.scrypt_n != first.scrypt_n || t.scrypt_r != first.scrypt_r || t.scrypt_p != first.scrypt_p ||
                memcmp(t.salt, first.salt, std::min<uint32_t>(first.salt_len, WALLET_MAX_SALT_LEN)) != 0) {
                break;
            }
            ++end;
        }

        BrowserVaultGroup group{};
        group.iterations = first.iterations;
        group.salt_len = std::min<uint32_t>(first.salt_len, WALLET_MAX_SALT_LEN);
        group.target_offset = begin;
        group.target_count = end - begin;
        group.profile = first.profile;
        group.scrypt_n = first.scrypt_n;
        group.scrypt_r = first.scrypt_r;
        group.scrypt_p = first.scrypt_p;
        if (group.salt_len != 0u) {
            memcpy(group.salt, first.salt, group.salt_len);
        }
        groups.push_back(group);
        if (group.profile == BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_SCRYPT ||
            group.profile == BROWSERVAULT_PROFILE_SUBSTRATE_SCRYPT_PKCS8 ||
            group.profile == BROWSERVAULT_PROFILE_MULTIBIT_HD_SCRYPT_AES ||
            group.profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_SCRYPT_AES ||
            group.profile == BROWSERVAULT_PROFILE_BISQ_SCRYPT_AES ||
            group.profile == BROWSERVAULT_PROFILE_BIP38_NON_EC ||
            group.profile == BROWSERVAULT_PROFILE_BIP38_EC) {
            const uint64_t scrypt_work = std::max<uint32_t>(1u, group.scrypt_n) * 1024ull;
            work_by_group.push_back(scrypt_work);
        }
        else {
            work_by_group.push_back(std::max<uint32_t>(1u, group.iterations));
        }
        begin = end;
    }
}

static void wallet_count_chunk_targets_from_groups(
    const std::vector<BrowserVaultGroup>& groups,
    const std::vector<WalletGenericTargetChunk>& chunks,
    std::vector<uint32_t>& chunk_target_counts)
{
    chunk_target_counts.clear();
    chunk_target_counts.reserve(chunks.size());
    for (const WalletGenericTargetChunk& chunk : chunks) {
        uint32_t total = 0u;
        const uint32_t end = chunk.offset + chunk.count;
        for (uint32_t i = chunk.offset; i < end && i < groups.size(); ++i) {
            total += groups[i].target_count;
        }
        chunk_target_counts.push_back(total);
    }
}

static uint64_t wallet_scrypt_candidate_sublaunch_count(
    const uint64_t remaining,
    const uint64_t scrypt_concurrency,
    const uint32_t target_count)
{
    if (remaining == 0ull) return 0ull;
    const uint64_t targets = std::max<uint64_t>(1ull, static_cast<uint64_t>(target_count));
    const uint64_t lanes = std::max<uint64_t>(1ull, scrypt_concurrency);
    const uint64_t by_lanes = std::max<uint64_t>(1ull, lanes / targets);
    return std::min<uint64_t>(remaining, by_lanes);
}

static inline uint64_t wallet_chunk_scratch_stride(const WalletGenericTargetChunk& chunk, uint64_t fallback_stride)
{
    return chunk.scratch_stride != 0ull ? chunk.scratch_stride : fallback_stride;
}

static inline uint64_t wallet_chunk_concurrency(
    const uint64_t scratch_bytes,
    const uint64_t max_concurrency,
    const uint64_t scratch_stride)
{
    if (scratch_stride == 0ull) {
        return std::max<uint64_t>(1ull, max_concurrency);
    }
    if (scratch_bytes < scratch_stride) {
        return 0ull;
    }
    return std::max<uint64_t>(1ull, std::min<uint64_t>(max_concurrency, scratch_bytes / scratch_stride));
}

static uint32_t wallet_browservault_group_slice_target_count(
    const BrowserVaultDeviceState& state,
    const uint32_t group_offset,
    const uint32_t group_count)
{
    uint64_t total = 0ull;
    const uint64_t end = std::min<uint64_t>(
        static_cast<uint64_t>(state.group_target_counts.size()),
        static_cast<uint64_t>(group_offset) + static_cast<uint64_t>(group_count));
    for (uint64_t i = group_offset; i < end; ++i) {
        total += state.group_target_counts[static_cast<size_t>(i)];
    }
    return static_cast<uint32_t>(
        std::min<uint64_t>(total, static_cast<uint64_t>(UINT32_MAX)));
}

static metalError_t wallet_flush_browservault_results(
    const std::vector<std::string>& target_files,
    std::vector<uint8_t>& solved_files,
    bool& all_solved,
    bool* overflowed = nullptr)
{
    if (overflowed != nullptr) {
        *overflowed = false;
    }
    unsigned long long count = 0;
    metalError_t st = metalMemcpy(&count, p_wallet_count, sizeof(count), metalMemcpyDeviceToHost);
    if (st != metalSuccess || count == 0ull) return st;
    const unsigned long long capped = std::min<unsigned long long>(count, MAX_FOUNDS);
    if (count > capped) {
        fprintf(stderr,
            "[!] Warning: browser-wallet result buffer overflow (%llu > %llu); "
            "replaying the unfinished batch after solved-target upload [!]\n",
            count,
            capped);
        if (overflowed != nullptr) {
            *overflowed = true;
        }
    }
    std::vector<WalletModeResult> results(static_cast<size_t>(capped));
    st = metalMemcpy(results.data(), p_wallet_results, static_cast<size_t>(capped) * sizeof(WalletModeResult), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    std::vector<WalletModeResult> filtered;
    filtered.reserve(results.size());
    {
        std::lock_guard<std::mutex> lock(browservault_solved_mutex);
        bool changed = false;
        for (const WalletModeResult& result : results) {
            if (result.target_index < solved_files.size()) {
                if (solved_files[result.target_index]) continue;
                solved_files[result.target_index] = 1u;
                changed = true;
            }
            filtered.push_back(result);
        }
        if (changed) ++browservault_solved_version;
        all_solved = !solved_files.empty();
        for (uint8_t solved : solved_files) if (!solved) { all_solved = false; break; }
    }
    if (!filtered.empty()) SaveResultBrowserVault(OUT_FILE, Founds, save, filtered.data(), static_cast<unsigned long long>(filtered.size()), target_files);
    return metalMemset(p_wallet_count, 0, sizeof(unsigned long long));
}

static void wallet_update_browser_mode_progress(
    const std::vector<uint8_t>& solved_files,
    const uint64_t completed_kdfs,
    const uint64_t completed_verifications,
    const uint64_t readback_ns)
{
    if (!BIP38_MODE && !SUBSTRATEWALLET_MODE && !COPAYWALLET_MODE &&
        !TERRAWALLET_MODE && !BITSHARESWALLET_MODE &&
        !YOROIWALLET_MODE) {
        return;
    }
    uint64_t solved = 0ull;
    {
        std::lock_guard<std::mutex> lock(browservault_solved_mutex);
        for (const uint8_t value : solved_files) {
            solved += value != 0u ? 1ull : 0ull;
        }
    }
    modeinfra::ModeProgress& progress = modeinfra::global_mode_progress();
    progress.credit_completed(completed_kdfs,
                              completed_kdfs,
                              completed_verifications,
                              readback_ns);
    progress.set_targets(static_cast<uint64_t>(solved_files.size()),
                         static_cast<uint64_t>(solved_files.size()),
                         solved);
    progress.set_founds(solved);
}

