    for (;;) {
        bool any_progress = false, all_chunks_done = true;
        for (size_t chunk_idx = 0; chunk_idx < state.target_chunks.size() && !all_solved; ++chunk_idx) {
            const WalletGenericTargetChunk& chunk = state.target_chunks[chunk_idx];
