            const uint32_t launch_blocks = static_cast<uint32_t>(std::max<uint64_t>(1ull,
                std::min<uint64_t>((chunk_concurrency + BLOCK_THREADS - 1ull) / BLOCK_THREADS, static_cast<uint64_t>(BLOCK_NUMBER))));
