                const uint32_t target_sub_count = std::min<uint32_t>(target_sub_limit, chunk.count - target_offset);
                metal_launch("workerExodusSeco", launch_blocks, BLOCK_THREADS, nullptr, nullptr, state.targets + chunk.offset + target_offset, target_sub_count, state.solved_flags, state.solved_count, candidate_kind, nullptr, nullptr, 0u, state.mask_spec, state.range_spec, state.scrypt_scratch, chunk_stride, start + processed, sub_count);
                st = metalGetLastError(); if (st != metalSuccess) return st;
