                counterTotal += sub_count * static_cast<uint64_t>(target_sub_count);
                st = wallet_flush_exodusseco_results(target_files, solved_files, all_solved); if (st != metalSuccess) return st;
            }
            chunk_processed[chunk_idx] = processed + sub_count;
            any_progress = true;
        }
        if (all_chunks_done || !any_progress || all_solved) break;
    }
    return metalSuccess;
}

