struct WalletJsHostProfile {
    WalletJsSpec spec{};
    std::string name;
    bool seed_profile = false;
    bool exact_seed_profile = false;
};

static bool walletjs_parse_profile(const std::string& profile_in, WalletJsHostProfile& out, std::string& err) {
    const std::string p = wallet_lower_copy(profile_in);
    out = WalletJsHostProfile{};
    out.name = p;
    if (p == "cryptojs-sha256" || p == "bitaddress-sha256" || p == "brain-sha256") {
        out.spec.profile_kind = WALLETJS_PROFILE_SHA256_BRAIN;
        out.seed_profile = false;
        return true;
    }
    struct SeedProfileMap { const char* name; uint32_t gen; uint32_t mode; };
    static const SeedProfileMap profiles[] = {
        { "jsbn-arc4-v8-2011", 211u, 12u },
        { "jsbn-arc4-v8-2015", 212u, 12u },
        { "jsbn-arc4-spidermonkey-lcg48", 213u, 12u },
        { "jsbn-arc4-jsc-weakrandom", 214u, 12u },
    };
    for (const auto& profile : profiles) {
        if (p == profile.name) {
            out.spec.profile_kind = WALLETJS_PROFILE_PRNG64_SEED;
            out.spec.prng_gen = profile.gen;
            out.spec.prng_mode = profile.mode;
            out.seed_profile = true;
            return true;
        }
    }
    struct ExactProfileMap { const char* name; uint32_t gen; };
    static const ExactProfileMap exact_profiles[] = {
        { "jsbn-arc4-v8-2011-exact", 211u },
        { "jsbn-arc4-v8-2015-exact", 212u },
        { "jsbn-arc4-spidermonkey-lcg48-exact", 213u },
        { "jsbn-arc4-jsc-weakrandom-exact", 214u },
    };
    for (const auto& profile : exact_profiles) {
        if (p == profile.name) {
            out.spec.profile_kind = WALLETJS_PROFILE_RANDSTORM_JSBN_EXACT;
            out.spec.prng_gen = profile.gen;
            out.spec.prng_mode = 0u;
            out.seed_profile = true;
            out.exact_seed_profile = true;
            return true;
        }
    }
    err = "unsupported walletjs profile '" + profile_in + "'";
    return false;
}

struct WalletJsDeviceState {
    WalletMaskSpec* mask_spec = nullptr;
    WalletRangeSpec* range_spec = nullptr;
    char* pass_data = nullptr;
    uint8_t* pass_lens = nullptr;
};

static void wallet_release_walletjs_device_state(WalletJsDeviceState& state) {
    if (state.mask_spec) metalFree(state.mask_spec);
    if (state.range_spec) metalFree(state.range_spec);
    if (state.pass_data) metalFree(state.pass_data);
    if (state.pass_lens) metalFree(state.pass_lens);
    state.mask_spec = nullptr;
    state.range_spec = nullptr;
    state.pass_data = nullptr;
    state.pass_lens = nullptr;
}

static metalError_t wallet_flush_walletjs_results(const std::vector<std::string>& profile_names) {
    unsigned long long count = 0;
    metalError_t st = metalMemcpy(&count, p_wallet_count, sizeof(count), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (count == 0ull) return metalSuccess;
    const unsigned long long capped = std::min<unsigned long long>(count, MAX_FOUNDS);
    std::vector<WalletModeResult> results(static_cast<size_t>(capped));
    st = metalMemcpy(results.data(), p_wallet_results, static_cast<size_t>(capped) * sizeof(WalletModeResult), metalMemcpyDeviceToHost);
    if (st != metalSuccess) return st;
    if (count > capped) {
        fprintf(stderr, "[!] Warning: walletjs result buffer overflow; increase -fsize [!]\n");
    }
    SaveResultWalletJS(OUT_FILE, Founds, save, results.data(), capped, profile_names);
    st = metalMemset(p_wallet_count, 0, sizeof(unsigned long long));
    return st;
}

static metalError_t launch_workerWalletJS(
    uint64_t candidate_count,
    bool* bIs,
    bool* bDev,
    const WalletJsHostProfile& profile,
    uint8_t candidate_kind,
    const char* pass_data,
    const uint8_t* pass_lens,
    uint32_t pass_count,
    const WalletMaskSpec* mask_spec,
    const WalletRangeSpec* range_spec,
    uint64_t candidate_start)
{
    const uint32_t launch_blocks = static_cast<uint32_t>(
        std::max<uint64_t>(1ull, (candidate_count + static_cast<uint64_t>(BLOCK_THREADS) - 1ull) /
            static_cast<uint64_t>(BLOCK_THREADS)));
    const MetalGridSize grid(launch_blocks);
    const MetalGridSize block(BLOCK_THREADS);
    const bool p2wsh_only = P2wsh && !Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum;
    if (profile.seed_profile && candidate_kind == WALLET_CANDIDATE_RANGE) {
        if (p2wsh_only) {
            metal_launch("workerWalletJS_seed_p", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (P2wsh) {
            metal_launch("workerWalletJS_seed", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_c", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (!Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_u", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (!Compressed && !Uncompressed && Segwit && !Taproot && !Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_s", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (!Compressed && !Uncompressed && !Segwit && Taproot && !Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_r", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (!Compressed && !Uncompressed && !Segwit && !Taproot && Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_x", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (!Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && Ethereum) {
            metal_launch("workerWalletJS_seed_e", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_cu", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (Compressed && Uncompressed && Segwit && Taproot && !Xpoint && !Ethereum) {
            metal_launch("workerWalletJS_seed_cusr", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else if (Compressed && Uncompressed && Segwit && Taproot && Xpoint && Ethereum) {
            metal_launch("workerWalletJS_seed_cusrxe", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        else {
            metal_launch("workerWalletJS_seed", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_start, candidate_count);
        }
        return metalGetLastError();
    }
    if (p2wsh_only) {
        metal_launch("workerWalletJS_p", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (P2wsh) {
        metal_launch("workerWalletJS", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_c", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (!Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_u", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (!Compressed && !Uncompressed && Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_s", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (!Compressed && !Uncompressed && !Segwit && Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_r", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (!Compressed && !Uncompressed && !Segwit && !Taproot && Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_x", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (!Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && Ethereum) {
        metal_launch("workerWalletJS_e", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_cu", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (Compressed && Uncompressed && Segwit && Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerWalletJS_cusr", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else if (Compressed && Uncompressed && Segwit && Taproot && Xpoint && Ethereum) {
        metal_launch("workerWalletJS_cusrxe", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    else {
        metal_launch("workerWalletJS", grid, block, bIs, bDev, _dev_precomp, pitch, profile.spec, candidate_kind, pass_data, pass_lens, pass_count, mask_spec, range_spec, candidate_start, candidate_count);
    }
    return metalGetLastError();
}

static metalError_t wallet_launch_walletjs_dict_batch(
    const WalletPassBuf& batch,
    WalletJsDeviceState& state,
    const WalletJsHostProfile& profile,
    const std::vector<std::string>& profile_names)
{
    metalError_t st = metalSuccess;
    st = copy_to_device_grow(reinterpret_cast<void**>(&state.pass_data), batch.data.data(), batch.data.empty() ? 1u : batch.data.size());
    if (st != metalSuccess) goto Done;
    st = copy_to_device_grow(reinterpret_cast<void**>(&state.pass_lens), batch.lens.data(), batch.lens.empty() ? 1u : batch.lens.size());
    if (st != metalSuccess) goto Done;
    st = launch_workerWalletJS(batch.count, nullptr, nullptr, profile,
        WALLET_CANDIDATE_DICTIONARY, state.pass_data, state.pass_lens, batch.count,
        nullptr, nullptr, 0ull);
    if (st != metalSuccess) goto Done;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) goto Done;
    counterTotal += static_cast<uint64_t>(batch.count);
    st = wallet_flush_walletjs_results(profile_names);
Done:
    return st;
}

static metalError_t wallet_launch_walletjs_generated(
    WalletJsDeviceState& state,
    const WalletJsHostProfile& profile,
    uint8_t candidate_kind,
    uint64_t start,
    uint64_t count,
    const std::vector<std::string>& profile_names)
{
    metalError_t st = launch_workerWalletJS(count, nullptr, nullptr, profile,
        candidate_kind, nullptr, nullptr, 0u,
        state.mask_spec, state.range_spec, start);
    if (st != metalSuccess) return st;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;
    counterTotal += count;
    return wallet_flush_walletjs_results(profile_names);
}

struct PtGpuDeviceState {
    uint32_t* derivation_list = nullptr;
    uint32_t* der_index = nullptr;
    uint32_t* dev_iter = nullptr;
    int* dev_size = nullptr;
};

static void pt_release_device_state(PtGpuDeviceState& state) {
    if (state.derivation_list) metalFree(state.derivation_list);
    if (state.der_index) metalFree(state.der_index);
    if (state.dev_iter) metalFree(state.dev_iter);
    if (state.dev_size) metalFree(state.dev_size);
    state.derivation_list = nullptr;
    state.der_index = nullptr;
    state.dev_iter = nullptr;
    state.dev_size = nullptr;
}

static metalError_t pt_prepare_device_state(PtGpuDeviceState& state, const bool with_sizes) {
    metalError_t st = metalSuccess;

    st = metalMalloc((void**)&state.derivation_list, Derivations.size() * sizeof(uint32_t));
    if (st != metalSuccess) goto PTStateErr;
    st = metalMemcpy(state.derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (st != metalSuccess) goto PTStateErr;

    st = metalMalloc((void**)&state.der_index, derIndex.size() * sizeof(uint32_t));
    if (st != metalSuccess) goto PTStateErr;
    st = metalMemcpy(state.der_index, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (st != metalSuccess) goto PTStateErr;

    st = metalMalloc((void**)&state.dev_iter, Iterations.size() * sizeof(uint32_t));
    if (st != metalSuccess) goto PTStateErr;
    st = metalMemcpy(state.dev_iter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (st != metalSuccess) goto PTStateErr;

    if (with_sizes) {
        st = metalMalloc((void**)&state.dev_size, Sizes.size() * sizeof(int));
        if (st != metalSuccess) goto PTStateErr;
        st = metalMemcpy(state.dev_size, Sizes.data(), Sizes.size() * sizeof(int), metalMemcpyHostToDevice);
        if (st != metalSuccess) goto PTStateErr;
    }

    return metalSuccess;

PTStateErr:
    pt_release_device_state(state);
    return st;
}

// process one mnemonic with a password slice on the current GPU
static metalError_t processMetal2PassThread_single(
    bool* buffIsResult, bool* buffDeviceResult,
    const std::string& mnem,
    const PtPassBuf& slice,
    uint32_t* derivation_list, uint32_t* _derIndex, uint32_t derIndex_size,
    uint32_t* _devIter, uint32_t iteration_size)
{
    metalError_t st = metalSuccess;
    char* _devMnem = nullptr;
    char* _devPassData = nullptr;
    uint8_t* _devPassLens = nullptr;

    st = copy_to_device_grow((void**)&_devMnem, mnem.data(), mnem.size() ? mnem.size() : 1);
    if (st != metalSuccess) { fprintf(stderr, "pt: mnem copy failed: %s\n", metalGetErrorString(st)); goto PTSErr; }

    st = copy_to_device_grow((void**)&_devPassData, slice.data.data(), slice.data.size() ? slice.data.size() : 1);
    if (st != metalSuccess) { fprintf(stderr, "pt: pass_data copy failed: %s\n", metalGetErrorString(st)); goto PTSErr; }

    st = copy_to_device_grow((void**)&_devPassLens, slice.lens.data(), slice.lens.size() ? slice.lens.size() : 1);
    if (st != metalSuccess) { fprintf(stderr, "pt: pass_lens copy failed: %s\n", metalGetErrorString(st)); goto PTSErr; }

    st = metalDeviceSynchronize();
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
    st = metalDeviceSynchronize();

    metal_launch("workerPassThread", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, (const char*)_devMnem, (uint32_t)mnem.size(), derivation_list, _derIndex, derIndex_size, 0, (const char*)_devPassData, (const uint8_t*)_devPassLens, slice.count, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);

    st = metalGetLastError();
    if (st != metalSuccess) { fprintf(stderr, "workerPassThread launch failed: %s\n", metalGetErrorString(st)); goto PTSErr; }
    counterTotal += (uint64_t)slice.count * iteration_size;
    goto PTSDone;
PTSErr:
PTSDone:
    if (_devMnem) metalFree(_devMnem);
    if (_devPassData) metalFree(_devPassData);
    if (_devPassLens) metalFree(_devPassLens);
    return st;
}

static metalError_t pt_dispatch_multi_gpu_mnem(
    const std::string& mnem,
    const std::vector<PtPassBuf>& batches,
    const ThreadInputSnapshot& snap)
{
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<metalError_t> gst(gpu_count, metalSuccess);
    std::vector<std::thread> workers;
    const uint32_t batch_sz = BLOCK_NUMBER * BLOCK_THREADS;
    for (size_t gi = 0; gi < gpu_count && gi < batches.size(); ++gi) {
        if (batches[gi].count == 0) continue;
        workers.emplace_back([&, gi, mnem]() mutable {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
            }
            restore_thread_input_snapshot(snap);
            bool* bIs = nullptr; bool* bDev = nullptr;
            gst[gi] = acquire_shared_result_buffers(batch_sz, &bIs, &bDev);
            if (gst[gi] != metalSuccess) {
                return;
            }
            PtGpuDeviceState state;
            gst[gi] = pt_prepare_device_state(state, false);
            if (gst[gi] != metalSuccess) {
                pt_release_device_state(state);
                return;
            }
            gst[gi] = processMetal2PassThread_single(bIs, bDev, mnem, batches[gi],
                state.derivation_list, state.der_index, derIndex_size, state.dev_iter, (uint32_t)Iterations.size());
            pt_release_device_state(state);
        });
    }
    for (auto& t : workers) t.join();
    for (size_t gi = 0; gi < gpu_count && gi < batches.size(); ++gi)
        if (gst[gi] != metalSuccess) return gst[gi];
    return metalSuccess;
}

metalError_t processMetal2PassThread(std::istream& stream)
{
    ensure_pt_pass_reader();
    const uint32_t batch_sz = BLOCK_NUMBER * BLOCK_THREADS;
    const size_t gpu_count = g_gpu_contexts.size();
    const ThreadInputSnapshot snap = capture_thread_input_snapshot();
    const bool use_multi_gpu = is_multi_gpu_active() && !g_disable_multi_gpu_dispatch;

    PtGpuDeviceState state;
    uint32_t iteration_size = (uint32_t)Iterations.size();
    metalError_t st = metalSuccess;

    if (!use_multi_gpu) {
        st = pt_prepare_device_state(state, false);
        if (st != metalSuccess) goto PT2Err;
    }

    {
        bool* buffIsResult = nullptr;
        bool* buffDeviceResult = nullptr;
        if (!use_multi_gpu) {
            st = acquire_shared_result_buffers(batch_sz, &buffIsResult, &buffDeviceResult);
            if (st != metalSuccess) goto PT2Err;
        }

        std::string mnem;
        while (read_trimmed_line(stream, mnem, 512))
        {
            STATUS = mnem;
            bool any_dispatched = false;
            if (pass_brute)
            {
                uint8_t cur[128]; memcpy(cur, start_pass_point, 128);
                uint64_t tmp16[16]; array128_to_16x64_le(cur, tmp16);
                int plen = (int)sizeBE_64(tmp16, 16);
                if (plen < min_pass_len) plen = min_pass_len;
                std::vector<PtPassBuf> gpu_batches;
                if (use_multi_gpu) gpu_batches.resize(gpu_count);

                while (cmp_host(cur, end_pass_point, 128) <= 0)
                {
                    PtPassBuf batch;
                    batch.data.reserve((size_t)batch_sz * PASS_THREAD_STRIDE);
                    batch.lens.reserve(batch_sz);
                    uint8_t cur2[128]; memcpy(cur2, cur, 128);
                    int plen2 = plen;
                    for (uint32_t bi = 0; bi < batch_sz && cmp_host(cur2, end_pass_point, 128) <= 0; ++bi)
                    {
                        batch.push((const char*)&cur2[128 - plen2], (size_t)plen2);
                        uint64_t a[16], b[16];
                        array128_to_16x64_le(cur2, a);
                        add64to1024_host(a, 1, b);
                        array16x64_le_to128(b, cur2);
                        plen2 = (int)sizeBE_64(b, 16);
                        if (plen2 < min_pass_len) plen2 = min_pass_len;
                    }
                    if (batch.count == 0) break;

                    if (use_multi_gpu)
                    {
                        pt_reset_batches(gpu_batches);
                        for (size_t gi = 0; gi < gpu_count; ++gi) {
                            uint32_t s0 = (uint32_t)((batch.count * gi) / gpu_count);
                            uint32_t s1 = (uint32_t)((batch.count * (gi + 1)) / gpu_count);
                            if (s0 >= s1) continue;
                            gpu_batches[gi].count = s1 - s0;
                            gpu_batches[gi].data.assign(batch.data.begin() + (size_t)s0 * PASS_THREAD_STRIDE,
                                                        batch.data.begin() + (size_t)s1 * PASS_THREAD_STRIDE);
                            gpu_batches[gi].lens.assign(batch.lens.begin() + s0, batch.lens.begin() + s1);
                        }
                        st = pt_dispatch_multi_gpu_mnem(mnem, gpu_batches, snap);
                    }
                    else
                        st = processMetal2PassThread_single(buffIsResult, buffDeviceResult, mnem, batch, state.derivation_list, state.der_index, derIndex_size, state.dev_iter, iteration_size);
                    if (st != metalSuccess) goto PT2Err;
                    any_dispatched = true;

                    memcpy(cur, cur2, 128);
                    plen = plen2;
                }
            }
            else
            {
                g_pt_pass_reader.rewind();
                if (use_multi_gpu)
                {
                    std::vector<PtPassBuf> gpu_batches(gpu_count);
                    while (true) {
                        pt_reset_batches(gpu_batches);
                        bool any = false;
                        for (size_t gi = 0; gi < gpu_count; ++gi)
                            if (g_pt_pass_reader.read_batch(gpu_batches[gi], batch_sz)) any = true;
                        if (!any) break;
                        st = pt_dispatch_multi_gpu_mnem(mnem, gpu_batches, snap);
                        if (st != metalSuccess) goto PT2Err;
                        any_dispatched = true;
                    }
                }
                else
                {
                    PtPassBuf batch;
                    while (g_pt_pass_reader.read_batch(batch, batch_sz)) {
                        st = processMetal2PassThread_single(buffIsResult, buffDeviceResult, mnem, batch, state.derivation_list, state.der_index, derIndex_size, state.dev_iter, iteration_size);
                        if (st != metalSuccess) goto PT2Err;
                        any_dispatched = true;
                    }
                }
            }
            if (!any_dispatched) {
                PtPassBuf empty_batch;
                empty_batch.push("", 0);
                if (use_multi_gpu) {
                    std::vector<PtPassBuf> gpu_batches(1);
                    gpu_batches[0] = std::move(empty_batch);
                    st = pt_dispatch_multi_gpu_mnem(mnem, gpu_batches, snap);
                } else {
                    st = processMetal2PassThread_single(buffIsResult, buffDeviceResult, mnem, empty_batch, state.derivation_list, state.der_index, derIndex_size, state.dev_iter, iteration_size);
                }
                if (st != metalSuccess) goto PT2Err;
            }
        }

        if (!use_multi_gpu) {
            metalDeviceSynchronize();
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResult(OUT_FILE, Founds, save, Derivations_list);
            }
        }
    }
    goto PT2Done;
PT2Err:
    fprintf(stderr, "processMetal2PassThread error: %s\n", metalGetErrorString(st));
PT2Done:
    pt_release_device_state(state);
    return st;
}

// process one entropy with a password slice on the current GPU
static metalError_t processMetalEntropyPassThread_single(
    bool* buffIsResult, bool* buffDeviceResult,
    const std::string& ent,
    const PtPassBuf& slice,
    uint32_t* derivation_list, uint32_t* _derIndex, uint32_t derIndex_size,
    uint32_t* _devIter, uint32_t iteration_size,
    int* _devSize, uint32_t sizes_size)
{
    metalError_t st = metalSuccess;
    char* _devEnt = nullptr;
    char* _devPassData = nullptr;
    uint8_t* _devPassLens = nullptr;

    st = copy_to_device_grow((void**)&_devEnt, ent.data(), ent.size() ? ent.size() : 1);
    if (st != metalSuccess) { fprintf(stderr, "pt: ent copy failed: %s\n", metalGetErrorString(st)); goto EPTSErr; }

    st = copy_to_device_grow((void**)&_devPassData, slice.data.data(), slice.data.size() ? slice.data.size() : 1);
    if (st != metalSuccess) { fprintf(stderr, "pt: pass_data copy failed: %s\n", metalGetErrorString(st)); goto EPTSErr; }

    st = copy_to_device_grow((void**)&_devPassLens, slice.lens.data(), slice.lens.size() ? slice.lens.size() : 1);
    if (st != metalSuccess) { fprintf(stderr, "pt: pass_lens copy failed: %s\n", metalGetErrorString(st)); goto EPTSErr; }

    st = metalDeviceSynchronize();
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
    st = metalDeviceSynchronize();

    metal_launch("workerPassThreadEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, (const char*)_devEnt, (uint32_t)ent.size(), derivation_list, _derIndex, derIndex_size, 0, (const char*)_devPassData, (const uint8_t*)_devPassLens, slice.count, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);

    st = metalGetLastError();
    if (st != metalSuccess) { fprintf(stderr, "workerPassThreadEntropy launch failed: %s\n", metalGetErrorString(st)); goto EPTSErr; }
    counterTotal += (uint64_t)slice.count * iteration_size * sizes_size;
    goto EPTSDone;
EPTSErr:
EPTSDone:
    if (_devEnt) metalFree(_devEnt);
    if (_devPassData) metalFree(_devPassData);
    if (_devPassLens) metalFree(_devPassLens);
    return st;
}

static metalError_t pt_dispatch_multi_gpu_ent(
    const std::string& ent,
    const std::vector<PtPassBuf>& batches,
    const ThreadInputSnapshot& snap)
{
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<metalError_t> gst(gpu_count, metalSuccess);
    std::vector<std::thread> workers;
    const uint32_t batch_sz = BLOCK_NUMBER * BLOCK_THREADS;
    for (size_t gi = 0; gi < gpu_count && gi < batches.size(); ++gi) {
        if (batches[gi].count == 0) continue;
        workers.emplace_back([&, gi, ent]() mutable {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
            }
            restore_thread_input_snapshot(snap);
            bool* bIs = nullptr; bool* bDev = nullptr;
            gst[gi] = acquire_shared_result_buffers(batch_sz, &bIs, &bDev);
            if (gst[gi] != metalSuccess) {
                return;
            }
            PtGpuDeviceState state;
            gst[gi] = pt_prepare_device_state(state, true);
            if (gst[gi] != metalSuccess) {
                pt_release_device_state(state);
                return;
            }
            gst[gi] = processMetalEntropyPassThread_single(bIs, bDev, ent, batches[gi],
                state.derivation_list, state.der_index, derIndex_size, state.dev_iter, (uint32_t)Iterations.size(), state.dev_size, (uint32_t)Sizes.size());
            pt_release_device_state(state);
        });
    }
    for (auto& t : workers) t.join();
    for (size_t gi = 0; gi < gpu_count && gi < batches.size(); ++gi)
        if (gst[gi] != metalSuccess) return gst[gi];
    return metalSuccess;
}

metalError_t processMetalEntropyPassThread(std::istream& stream)
{
    ensure_pt_pass_reader();
    const uint32_t batch_sz = BLOCK_NUMBER * BLOCK_THREADS;
    const size_t gpu_count = g_gpu_contexts.size();
    const ThreadInputSnapshot snap = capture_thread_input_snapshot();
    const bool use_multi_gpu = is_multi_gpu_active() && !g_disable_multi_gpu_dispatch;

    PtGpuDeviceState state;
    uint32_t iteration_size = (uint32_t)Iterations.size();
    uint32_t sizes_size = (uint32_t)Sizes.size();
    metalError_t st = metalSuccess;

    if (!use_multi_gpu) {
        st = pt_prepare_device_state(state, true);
        if (st != metalSuccess) goto EPT2Err;
    }

    {
        bool* buffIsResult = nullptr;
        bool* buffDeviceResult = nullptr;
        if (!use_multi_gpu) {
            st = acquire_shared_result_buffers(batch_sz, &buffIsResult, &buffDeviceResult);
            if (st != metalSuccess) goto EPT2Err;
        }

        std::string ent;
        while (read_trimmed_line(stream, ent, 512))
        {
            STATUS = ent;
            bool any_dispatched = false;
            if (pass_brute)
            {
                uint8_t cur[128]; memcpy(cur, start_pass_point, 128);
                uint64_t tmp16[16]; array128_to_16x64_le(cur, tmp16);
                int plen = (int)sizeBE_64(tmp16, 16);
                if (plen < min_pass_len) plen = min_pass_len;
                std::vector<PtPassBuf> gpu_batches;
                if (use_multi_gpu) gpu_batches.resize(gpu_count);

                while (cmp_host(cur, end_pass_point, 128) <= 0)
                {
                    PtPassBuf batch;
                    batch.data.reserve((size_t)batch_sz * PASS_THREAD_STRIDE);
                    batch.lens.reserve(batch_sz);
                    uint8_t cur2[128]; memcpy(cur2, cur, 128);
                    int plen2 = plen;
                    for (uint32_t bi = 0; bi < batch_sz && cmp_host(cur2, end_pass_point, 128) <= 0; ++bi)
                    {
                        batch.push((const char*)&cur2[128 - plen2], (size_t)plen2);
                        uint64_t a[16], b[16];
                        array128_to_16x64_le(cur2, a);
                        add64to1024_host(a, 1, b);
                        array16x64_le_to128(b, cur2);
                        plen2 = (int)sizeBE_64(b, 16);
                        if (plen2 < min_pass_len) plen2 = min_pass_len;
                    }
                    if (batch.count == 0) break;

                    if (use_multi_gpu)
                    {
                        pt_reset_batches(gpu_batches);
                        for (size_t gi = 0; gi < gpu_count; ++gi) {
                            uint32_t s0 = (uint32_t)((batch.count * gi) / gpu_count);
                            uint32_t s1 = (uint32_t)((batch.count * (gi + 1)) / gpu_count);
                            if (s0 >= s1) continue;
                            gpu_batches[gi].count = s1 - s0;
                            gpu_batches[gi].data.assign(batch.data.begin() + (size_t)s0 * PASS_THREAD_STRIDE,
                                                        batch.data.begin() + (size_t)s1 * PASS_THREAD_STRIDE);
                            gpu_batches[gi].lens.assign(batch.lens.begin() + s0, batch.lens.begin() + s1);
                        }
                        st = pt_dispatch_multi_gpu_ent(ent, gpu_batches, snap);
                    }
                    else
                        st = processMetalEntropyPassThread_single(buffIsResult, buffDeviceResult, ent, batch, state.derivation_list, state.der_index, derIndex_size, state.dev_iter, iteration_size, state.dev_size, sizes_size);
                    if (st != metalSuccess) goto EPT2Err;
                    any_dispatched = true;

                    memcpy(cur, cur2, 128);
                    plen = plen2;
                }
            }
            else
            {
                g_pt_pass_reader.rewind();
                if (use_multi_gpu)
                {
                    std::vector<PtPassBuf> gpu_batches(gpu_count);
                    while (true) {
                        pt_reset_batches(gpu_batches);
                        bool any = false;
                        for (size_t gi = 0; gi < gpu_count; ++gi)
                            if (g_pt_pass_reader.read_batch(gpu_batches[gi], batch_sz)) any = true;
                        if (!any) break;
                        st = pt_dispatch_multi_gpu_ent(ent, gpu_batches, snap);
                        if (st != metalSuccess) goto EPT2Err;
                        any_dispatched = true;
                    }
                }
                else
                {
                    PtPassBuf batch;
                    while (g_pt_pass_reader.read_batch(batch, batch_sz)) {
                        st = processMetalEntropyPassThread_single(buffIsResult, buffDeviceResult, ent, batch, state.derivation_list, state.der_index, derIndex_size, state.dev_iter, iteration_size, state.dev_size, sizes_size);
                        if (st != metalSuccess) goto EPT2Err;
                        any_dispatched = true;
                    }
                }
            }
            if (!any_dispatched) {
                PtPassBuf empty_batch;
                empty_batch.push("", 0);
                if (use_multi_gpu) {
                    std::vector<PtPassBuf> gpu_batches(1);
                    gpu_batches[0] = std::move(empty_batch);
                    st = pt_dispatch_multi_gpu_ent(ent, gpu_batches, snap);
                } else {
                    st = processMetalEntropyPassThread_single(buffIsResult, buffDeviceResult, ent, empty_batch, state.derivation_list, state.der_index, derIndex_size, state.dev_iter, iteration_size, state.dev_size, sizes_size);
                }
                if (st != metalSuccess) goto EPT2Err;
            }
        }

        if (!use_multi_gpu) {
            metalDeviceSynchronize();
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResult(OUT_FILE, Founds, save, Derivations_list);
            }
        }
    }
    goto EPT2Done;
EPT2Err:
    fprintf(stderr, "processMetalEntropyPassThread error: %s\n", metalGetErrorString(st));
EPT2Done:
    pt_release_device_state(state);
    return st;
}

// Flatten the seekable entropy/passphrase Cartesian product used by the
// automatic route. Explicit pass_thread and multi-GPU dispatch keep their
// established per-entropy path and serve as regression controls.
static metalError_t processMetalEntropyPassThreadCartesian(std::istream& stream)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return processMetalEntropyPassThread(stream);
    }

    ensure_pt_pass_reader();
    const uint32_t batch_sz = BLOCK_NUMBER * BLOCK_THREADS;
    const std::istream::pos_type initial_position = stream.tellg();
    std::vector<char> packed_entropies;
    std::vector<uint32_t> entropy_lengths;
    std::string entropy;
    while (read_trimmed_line(stream, entropy, 512)) {
        STATUS = entropy;
        const size_t offset = packed_entropies.size();
        packed_entropies.resize(offset + 512u, 0);
        if (!entropy.empty()) {
            memcpy(packed_entropies.data() + offset, entropy.data(), entropy.size());
        }
        entropy_lengths.push_back((uint32_t)entropy.size());
    }
    if (entropy_lengths.empty()) {
        return metalSuccess;
    }
    if (entropy_lengths.size() > batch_sz) {
        stream.clear();
        stream.seekg(initial_position);
        return processMetalEntropyPassThread(stream);
    }

    const uint32_t entropy_count = (uint32_t)entropy_lengths.size();
    const uint32_t max_pass_batch = std::max<uint32_t>(1u, batch_sz / entropy_count);
    const uint32_t iteration_size = (uint32_t)Iterations.size();
    const uint32_t sizes_size = (uint32_t)Sizes.size();
    char* dev_entropies = nullptr;
    uint32_t* dev_entropy_lengths = nullptr;
    char* dev_pass_data = nullptr;
    uint8_t* dev_pass_lens = nullptr;
    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    PtGpuDeviceState state;

    metalError_t st = pt_prepare_device_state(state, true);
    if (st == metalSuccess) {
        st = acquire_shared_result_buffers(batch_sz, &buffIsResult, &buffDeviceResult);
    }
    if (st == metalSuccess) {
        st = copy_to_device_grow((void**)&dev_entropies, packed_entropies.data(),
                                 packed_entropies.size());
    }
    if (st == metalSuccess) {
        st = copy_to_device_grow((void**)&dev_entropy_lengths, entropy_lengths.data(),
                                 entropy_lengths.size() * sizeof(uint32_t));
    }

    if (st == metalSuccess) {
        g_pt_pass_reader.rewind();
        PtPassBuf pass_batch;
        bool any_dispatched = false;
        while (g_pt_pass_reader.read_batch(pass_batch, max_pass_batch)) {
            st = copy_to_device_grow((void**)&dev_pass_data, pass_batch.data.data(),
                                     pass_batch.data.empty() ? 1u : pass_batch.data.size());
            if (st != metalSuccess) break;
            st = copy_to_device_grow((void**)&dev_pass_lens, pass_batch.lens.data(),
                                     pass_batch.lens.empty() ? 1u : pass_batch.lens.size());
            if (st != metalSuccess) break;

            st = metalDeviceSynchronize();
            if (st != metalSuccess) break;
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResult(OUT_FILE, Founds, save, Derivations_list);
            }
            st = metalDeviceSynchronize();
            if (st != metalSuccess) break;

            const uint32_t pair_count = entropy_count * pass_batch.count;
            st = metal_launch("workerPassThreadEntropyBatch", BLOCK_NUMBER, BLOCK_THREADS,
                              buffIsResult, buffDeviceResult, _dev_precomp, pitch,
                              (const char*)dev_entropies, (const uint32_t*)dev_entropy_lengths,
                              entropy_count, state.derivation_list, state.der_index,
                              derIndex_size, 0, (const char*)dev_pass_data,
                              (const uint8_t*)dev_pass_lens, pass_batch.count,
                              use_custom_size, state.dev_size, sizes_size, ENTROPY_MODE,
                              state.dev_iter, iteration_size, Rounds, dub_mnem);
            if (st != metalSuccess) break;
            st = metalGetLastError();
            if (st != metalSuccess) break;
            counterTotal += (uint64_t)pair_count * iteration_size * sizes_size;
            any_dispatched = true;
        }
        if (st == metalSuccess && !any_dispatched) {
            st = metalErrorInvalidValue;
        }
    }

    if (st == metalSuccess) {
        st = metalDeviceSynchronize();
        if (st == metalSuccess && read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResult(OUT_FILE, Founds, save, Derivations_list);
        }
    }
    if (st != metalSuccess) {
        fprintf(stderr, "processMetalEntropyPassThreadCartesian error: %s\n",
                metalGetErrorString(st));
    }
    if (dev_entropies) metalFree(dev_entropies);
    if (dev_entropy_lengths) metalFree(dev_entropy_lengths);
    if (dev_pass_data) metalFree(dev_pass_data);
    if (dev_pass_lens) metalFree(dev_pass_lens);
    pt_release_device_state(state);
    return st;
}

// ??? der_thread support ??????????????????????????????????????????????????????
// One input per round: derive master key on 1 GPU thread (workerDerThread_mkd),
// then distribute ALL derivation paths across GPU threads (workerDerThread).
// Multi-GPU splits the derivation-path range, not the input stream.
// ?????????????????????????????????????????????????????????????????????????????

extern "C" METAL_KERNEL void workerDerThread_precompute_master_ed_hmac(const uint8_t* __restrict__ d_master_ed, hmac_sha512_precomp_t* __restrict__ d_master_ed_hmac_precomp);
extern "C" METAL_KERNEL void workerDerThread_slip0010_solana(bool* isResult, bool* buffResult, const uint8_t* __restrict__ d_master_ed, const hmac_sha512_precomp_t* __restrict__ d_master_ed_hmac_precomp, const char* __restrict__ d_save_str, const uint32_t d_save_len, const char* __restrict__ d_passphrase, uint32_t pass_len, uint64_t seed_value, bool store_seed, const uint32_t* __restrict__ d_derivations, const uint32_t* __restrict__ d_deriv_offsets, const uint32_t* __restrict__ derindex, const uint32_t der_indexes_size, const uint32_t der_offset, uint64_t round);
extern "C" METAL_KERNEL void workerDerThread_bip32_compressed(bool* isResult, bool* buffResult, const secp256k1_ge_storage* __restrict__ precPtr, const size_t precPitch, const uint8_t* __restrict__ d_master_secp, const char* __restrict__ d_save_str, const uint32_t d_save_len, const char* __restrict__ d_passphrase, uint32_t pass_len, uint64_t seed_value, bool store_seed, const uint32_t* __restrict__ d_derivations, const uint32_t* __restrict__ d_deriv_offsets, const uint32_t* __restrict__ derindex, const uint32_t der_indexes_size, const uint32_t der_offset, uint64_t round);

// CPU prefix-sum array: d_deriv_offsets[i] = sum(derIndex[0..i-1]).
// Allows O(1) path-start lookup inside workerDerThread.
static std::vector<uint32_t> g_dt_deriv_offsets;
static void ensure_dt_deriv_offsets() {
    if (g_dt_deriv_offsets.size() == derIndex.size()) return;
    g_dt_deriv_offsets.resize(derIndex.size(), 0);
    uint32_t sum = 0;
    for (size_t i = 0; i < derIndex.size(); ++i) {
        g_dt_deriv_offsets[i] = sum;
        sum += derIndex[i];
    }
}

// Helper: call appropriate SaveResult for the given mode.
static void dt_save_result(uint8_t mode) {
    switch (mode) {
    case 0: SaveResultHmac(OUT_FILE, Founds, save, Derivations_list); break;
    case 1: SaveResultSeed(OUT_FILE, Founds, save, Derivations_list); break;
    case 4: SaveResultBip32(OUT_FILE, Founds, save, Derivations_list); break;
    default: SaveResult(OUT_FILE, Founds, save, Derivations_list); break;
    }
}

static inline bool dt_use_slip0010_solana_fast_path() {
    return derivation_type_mask_host == DERIVATION_TYPE_MASK_SLIP0010 &&
        Solana &&
        !Ton && !Ton_all && !Dot && !Aptos && !Sui && !Xrp && !Exodus &&
        !Iota && !Ada && !Icp && !Fil && !Xtz &&
        !has_secp_output_targets();
}

static inline bool dt_use_bip32_compressed_fast_path() {
    return derivation_type_mask_host == DERIVATION_TYPE_MASK_BIP32 &&
        Compressed &&
        !Uncompressed && !Segwit && !Taproot && !Ethereum && !Xpoint &&
        !Solana && !Ton && !Ton_all && !Dot && !Aptos && !Sui && !Xrp &&
        !Exodus && !Iota && !Ada && !Icp && !Fil && !Xtz;
}

static inline bool dt_use_derthread_fast_scratch() {
    return dt_use_slip0010_solana_fast_path() || dt_use_bip32_compressed_fast_path();
}

// Inner kernel pair: check prev result, launch workerDerThread_mkd (1 thread),
// sync, copy save_len, then launch workerDerThread (one thread per path slice).
static metalError_t dt_launch_one(
    bool*    buffIsResult, bool* buffDeviceResult,
    char*    d_input_dev,  uint32_t input_len,
    const char* passphrase_dev, uint32_t pass_len,
    uint8_t* d_master_secp, uint8_t* d_master_ed,
    hmac_sha512_precomp_t* d_master_ed_hmac_precomp,
    uint8_t* d_master_cardano_icarus, uint8_t* d_master_cardano_daedalus,
    uint8_t* d_master_cardano_ledger,
    uint8_t* d_master_cardano_byron_legacy,
    uint8_t* d_entropy, uint32_t* d_entropy_len, uint8_t* d_entropy_valid,
    char*    d_save_str,    uint32_t* d_save_len_dev,
    uint32_t* d_devIter,    uint32_t  iteration_size,
    uint32_t* d_derivations_dev,
    uint32_t* d_deriv_offsets_dev,
    uint32_t* d_derIndex_dev,
    uint32_t  der_offset,
    uint32_t  der_count,
    uint8_t   mode)
{
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        dt_save_result(mode);
    }
    metalError_t st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;

    if (mode == 1 &&
        derIndex_size == 1u &&
        der_count == 1u &&
        der_offset == 0u &&
        !pass_set &&
        !is_multi_gpu_active() &&
        dt_use_slip0010_solana_fast_path()) {
        const uint32_t grid = (der_count + BLOCK_THREADS - 1) / BLOCK_THREADS;
        metal_launch("workerDerThread_seed_slip0010_solana", grid, BLOCK_THREADS,
                     buffIsResult, buffDeviceResult, d_input_dev, input_len,
                     d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev,
                     derIndex_size, der_offset, Rounds);
        st = metalGetLastError();
        if (st != metalSuccess) return st;
        counterTotal++;
        return metalSuccess;
    }

    metal_launch("workerDerThread_mkd", 1, 1, d_input_dev, input_len, passphrase_dev, pass_len, d_master_secp, d_master_ed, d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy, d_entropy, d_entropy_len, d_entropy_valid, d_save_str, d_save_len_dev, mode, MNEMONIC_MODE, ENTROPY_MODE, BIP32_MODE, d_devIter, iteration_size, 0);
    st = metalGetLastError();
    if (st != metalSuccess) return st;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;

    if (dt_use_slip0010_solana_fast_path() && d_master_ed_hmac_precomp != nullptr) {
        metal_launch("workerDerThread_precompute_master_ed_hmac", 1, 1, d_master_ed, d_master_ed_hmac_precomp);
        st = metalGetLastError();
        if (st != metalSuccess) return st;
    }

    uint32_t h_save_len = 0;
    metalMemcpy(&h_save_len, d_save_len_dev, sizeof(uint32_t), metalMemcpyDeviceToHost);

    const uint32_t grid = (der_count + BLOCK_THREADS - 1) / BLOCK_THREADS;
    if (dt_use_slip0010_solana_fast_path()) {
        metal_launch("workerDerThread_slip0010_solana", grid, BLOCK_THREADS, buffIsResult, buffDeviceResult, d_master_ed, d_master_ed_hmac_precomp, d_save_str, h_save_len, passphrase_dev, pass_len, 0, false, d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev, derIndex_size, der_offset, Rounds);
    } else if (dt_use_bip32_compressed_fast_path()) {
        metal_launch("workerDerThread_bip32_compressed", grid, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_master_secp, d_save_str, h_save_len, passphrase_dev, pass_len, 0, false, d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev, derIndex_size, der_offset, Rounds);
    } else {
        metal_launch("workerDerThread", grid, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_master_secp, d_master_ed, d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy, d_entropy, d_entropy_len, d_entropy_valid, d_save_str, h_save_len, passphrase_dev, pass_len, 0, false, d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev, derIndex_size, der_offset, Rounds);
    }
    st = metalGetLastError();
    if (st != metalSuccess) return st;

    counterTotal++;
    return metalSuccess;
}

// Per-GPU worker thread for multi-GPU dispatch.
static void dt_gpu_worker(
    size_t gi,
    const std::string& input_str,
    const std::string& pass_str,
    uint32_t der_offset, uint32_t der_count,
    uint8_t mode,
    const ThreadInputSnapshot& snap,
    metalError_t& out_st)
{
    {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        if (!activate_gpu_context(g_gpu_contexts[gi])) { out_st = metalErrorInvalidDevice; return; }
    }
    restore_thread_input_snapshot(snap);

    uint64_t batch_sz = BLOCK_NUMBER * BLOCK_THREADS;
    bool* bIs = nullptr; bool* bDev = nullptr;
    acquire_shared_result_buffers(batch_sz, &bIs, &bDev);

    ensure_dt_deriv_offsets();

    uint32_t* dev_der  = nullptr; uint32_t* dev_off  = nullptr;
    uint32_t* dev_idx  = nullptr; uint32_t* dev_iter = nullptr;
    uint8_t*  dev_ms   = nullptr; uint8_t*  dev_me   = nullptr;
    uint8_t*  dev_mci  = nullptr; uint8_t*  dev_mcd  = nullptr; uint8_t* dev_mcl = nullptr; uint8_t* dev_mbl = nullptr;
    uint8_t*  dev_entropy = nullptr; uint32_t* dev_entropy_len = nullptr; uint8_t* dev_entropy_valid = nullptr;
    uint8_t*  dev_fast_scratch = nullptr;
    hmac_sha512_precomp_t* dev_me_hmac = nullptr;
    char*     dev_ss   = nullptr; uint32_t* dev_sl   = nullptr;
    char*     dev_in   = nullptr;
    uint32_t  iter_sz  = (uint32_t)Iterations.size();

    metalMalloc(&dev_der,  Derivations.size() * sizeof(uint32_t));
    metalMemcpy(dev_der, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    metalMalloc(&dev_off,  g_dt_deriv_offsets.size() * sizeof(uint32_t));
    metalMemcpy(dev_off, g_dt_deriv_offsets.data(), g_dt_deriv_offsets.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    metalMalloc(&dev_idx,  derIndex.size() * sizeof(uint32_t));
    metalMemcpy(dev_idx, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    metalMalloc(&dev_iter, Iterations.size() * sizeof(uint32_t));
    metalMemcpy(dev_iter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    metalMalloc(&dev_me, 64);
    if (dt_use_slip0010_solana_fast_path()) {
        metalMalloc(&dev_me_hmac, sizeof(hmac_sha512_precomp_t));
    }
    if (dt_use_derthread_fast_scratch()) {
        metalMalloc(&dev_fast_scratch, 384);
        dev_ms = dev_fast_scratch;
        dev_mci = dev_fast_scratch + 64;
        dev_mcd = dev_fast_scratch + 160;
        dev_mcl = nullptr;
        dev_mbl = nullptr;
        dev_entropy = dev_fast_scratch + 256;
        dev_entropy_len = reinterpret_cast<uint32_t*>(dev_fast_scratch + 320);
        dev_entropy_valid = dev_fast_scratch + 324;
    }
    else {
        metalMalloc(&dev_ms, 64);
        metalMalloc(&dev_mci, sizeof(cardano_extended_private_key_t));
        metalMalloc(&dev_mcd, sizeof(cardano_extended_private_key_t));
        metalMalloc(&dev_mcl, sizeof(cardano_extended_private_key_t));
        metalMalloc(&dev_mbl, sizeof(cardano_extended_private_key_t));
        metalMalloc(&dev_entropy, 64);
        metalMalloc(&dev_entropy_len, sizeof(uint32_t));
        metalMalloc(&dev_entropy_valid, sizeof(uint8_t));
    }
    metalMalloc(&dev_ss, 512); metalMalloc(&dev_sl, sizeof(uint32_t));
    copy_to_device_grow((void**)&dev_in, input_str.data(), input_str.size() ? input_str.size() : 1);

    if (!pass_str.empty())
        copy_password_to_device(pass_str.data(), pass_str.size());
    const char* pdev = pass_str.empty() ? nullptr : passwords_dev;

    out_st = dt_launch_one(bIs, bDev,
        dev_in, (uint32_t)input_str.size(),
        pdev, (uint32_t)pass_str.size(),
        dev_ms, dev_me, dev_me_hmac, dev_mci, dev_mcd, dev_mcl, dev_mbl, dev_entropy, dev_entropy_len, dev_entropy_valid, dev_ss, dev_sl,
        dev_iter, iter_sz,
        dev_der, dev_off, dev_idx,
        der_offset, der_count, mode);

    metalDeviceSynchronize();
    if (read_result_flag_host(bIs)) {
        clear_result_flag_host(bIs);
        dt_save_result(mode);
    }

    if (dev_der)  metalFree(dev_der);
    if (dev_off)  metalFree(dev_off);
    if (dev_idx)  metalFree(dev_idx);
    if (dev_iter) metalFree(dev_iter);
    if (dev_fast_scratch) metalFree(dev_fast_scratch);
    else if (dev_ms) metalFree(dev_ms);
    if (dev_me)   metalFree(dev_me);
    if (dev_me_hmac) metalFree(dev_me_hmac);
    if (!dev_fast_scratch) {
        if (dev_mci)  metalFree(dev_mci);
        if (dev_mcd)  metalFree(dev_mcd);
        if (dev_mcl)  metalFree(dev_mcl);
        if (dev_mbl)  metalFree(dev_mbl);
        if (dev_entropy) metalFree(dev_entropy);
        if (dev_entropy_len) metalFree(dev_entropy_len);
        if (dev_entropy_valid) metalFree(dev_entropy_valid);
    }
    if (dev_ss)   metalFree(dev_ss);
    if (dev_sl)   metalFree(dev_sl);
    if (dev_in)   metalFree(dev_in);
}

// Dispatch one (input, passphrase) pair across all GPUs, each handling a path slice.
static metalError_t dt_dispatch_multi_gpu_one(
    const std::string& input_str,
    const std::string& pass_str,
    uint8_t mode,
    const ThreadInputSnapshot& snap)
{
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<metalError_t> gst(gpu_count, metalSuccess);
    std::vector<std::thread> workers;
    for (size_t gi = 0; gi < gpu_count; ++gi) {
        uint32_t d0 = (uint32_t)((derIndex_size * gi) / gpu_count);
        uint32_t d1 = (uint32_t)((derIndex_size * (gi + 1)) / gpu_count);
        if (d0 >= d1) continue;
        workers.emplace_back([gi, d0, d1, &input_str, &pass_str, mode, &snap, &gst]() mutable {
            dt_gpu_worker(gi, input_str, pass_str, d0, d1 - d0, mode, snap, gst[gi]);
        });
    }
    for (auto& t : workers) t.join();
    for (size_t gi = 0; gi < gpu_count; ++gi)
        if (gst[gi] != metalSuccess) return gst[gi];
    return metalSuccess;
}

// Process one input line with optional passphrase on the current GPU (or multi-GPU).
static metalError_t dt_process_line(
    bool* buffIsResult, bool* buffDeviceResult,
    const std::string& line,
    uint32_t* d_derivations_dev, uint32_t* d_deriv_offsets_dev, uint32_t* d_derIndex_dev,
    uint32_t* d_devIter, uint32_t iteration_size,
    uint8_t*  d_master_secp, uint8_t*  d_master_ed,
    hmac_sha512_precomp_t* d_master_ed_hmac_precomp,
    uint8_t*  d_master_cardano_icarus, uint8_t* d_master_cardano_daedalus,
    uint8_t*  d_master_cardano_ledger,
    uint8_t*  d_master_cardano_byron_legacy,
    uint8_t*  d_entropy, uint32_t* d_entropy_len, uint8_t* d_entropy_valid,
    char*     d_save_str,    uint32_t* d_save_len_dev,
    char**    d_input_dev_ptr,
    uint8_t mode,
    const ThreadInputSnapshot& snap)
{
    metalError_t st = copy_to_device_grow((void**)d_input_dev_ptr, line.data(), line.size() ? line.size() : 1);
    if (st != metalSuccess) return st;
    char* d_input_dev = *d_input_dev_ptr;

    auto run_single = [&](const char* pdev, uint32_t plen) -> metalError_t {
        return dt_launch_one(buffIsResult, buffDeviceResult,
            d_input_dev, (uint32_t)line.size(), pdev, plen,
            d_master_secp, d_master_ed, d_master_ed_hmac_precomp,
            d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy,
            d_entropy, d_entropy_len, d_entropy_valid,
            d_save_str, d_save_len_dev,
            d_devIter, iteration_size,
            d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev,
            0, derIndex_size, mode);
    };

    if (pass_set) {
        for (size_t i = 0; i < passwords_files.size(); ++i) {
            std::ifstream* ps = acquire_password_stream_for_rewind(passwords_files[i]);
            if (!ps) continue;
            std::string pline;
            while (read_trimmed_line(*ps, pline, 128)) {
                if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
                    st = dt_dispatch_multi_gpu_one(line, pline, mode, snap);
                } else {
                    st = copy_password_to_device(pline.data(), pline.size());
                    if (st != metalSuccess) return st;
                    st = run_single(passwords_dev, (uint32_t)pline.size());
                }
                if (st != metalSuccess) return st;
            }
        }
        for (size_t i = 0; i < passwords_list.size(); ++i) {
            const std::string& pline = passwords_list[i];
            if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
                st = dt_dispatch_multi_gpu_one(line, pline, mode, snap);
            } else {
                st = copy_password_to_device(pline.data(), pline.size());
                if (st != metalSuccess) return st;
                st = run_single(passwords_dev, (uint32_t)pline.size());
            }
            if (st != metalSuccess) return st;
        }
    } else {
        if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
            st = dt_dispatch_multi_gpu_one(line, "", mode, snap);
        } else {
            st = run_single(nullptr, 0);
        }
        if (st != metalSuccess) return st;
    }
    return metalSuccess;
}

// Main dispatch: reads lines from stream, processes each with all derivation paths.
metalError_t processMetalDerThread(uint8_t mode, std::istream& stream)
{
    ensure_dt_deriv_offsets();
    const ThreadInputSnapshot snap = capture_thread_input_snapshot();

    uint64_t  outputSizeB_T       = BLOCK_NUMBER * BLOCK_THREADS;
    bool*     buffIsResult        = nullptr;
    bool*     buffDeviceResult    = nullptr;
    uint32_t* d_derivations_dev   = nullptr;
    uint32_t* d_deriv_offsets_dev = nullptr;
    uint32_t* d_derIndex_dev      = nullptr;
    uint32_t* d_devIter           = nullptr;
    uint8_t*  d_master_secp       = nullptr;
    uint8_t*  d_master_ed         = nullptr;
    uint8_t*  d_master_cardano_icarus = nullptr;
    uint8_t*  d_master_cardano_daedalus = nullptr;
    uint8_t*  d_master_cardano_ledger = nullptr;
    uint8_t*  d_master_cardano_byron_legacy = nullptr;
    uint8_t*  d_entropy           = nullptr;
    uint32_t* d_entropy_len       = nullptr;
    uint8_t*  d_entropy_valid     = nullptr;
    uint8_t*  d_fast_scratch      = nullptr;
    hmac_sha512_precomp_t* d_master_ed_hmac_precomp = nullptr;
    char*     d_save_str          = nullptr;
    uint32_t* d_save_len_dev      = nullptr;
    char*     d_input_dev         = nullptr;
    uint32_t  iter_sz             = (uint32_t)Iterations.size();
    metalError_t st;

    st = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);
    if (st != metalSuccess) goto DTErr;

    st = metalMalloc(&d_derivations_dev, Derivations.size() * sizeof(uint32_t)); if (st) goto DTErr;
    metalMemcpy(d_derivations_dev, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_deriv_offsets_dev, g_dt_deriv_offsets.size() * sizeof(uint32_t)); if (st) goto DTErr;
    metalMemcpy(d_deriv_offsets_dev, g_dt_deriv_offsets.data(), g_dt_deriv_offsets.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_derIndex_dev, derIndex.size() * sizeof(uint32_t)); if (st) goto DTErr;
    metalMemcpy(d_derIndex_dev, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_devIter, Iterations.size() * sizeof(uint32_t)); if (st) goto DTErr;
    metalMemcpyAsync(d_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_master_ed,   64); if (st) goto DTErr;
    if (dt_use_slip0010_solana_fast_path()) {
        st = metalMalloc(&d_master_ed_hmac_precomp, sizeof(hmac_sha512_precomp_t)); if (st) goto DTErr;
    }
    if (dt_use_derthread_fast_scratch()) {
        st = metalMalloc(&d_fast_scratch, 384); if (st) goto DTErr;
        d_master_secp = d_fast_scratch;
        d_master_cardano_icarus = d_fast_scratch + 64;
        d_master_cardano_daedalus = d_fast_scratch + 160;
        d_master_cardano_ledger = nullptr;
        d_master_cardano_byron_legacy = nullptr;
        d_entropy = d_fast_scratch + 256;
        d_entropy_len = reinterpret_cast<uint32_t*>(d_fast_scratch + 320);
        d_entropy_valid = d_fast_scratch + 324;
    }
    else {
        st = metalMalloc(&d_master_secp, 64); if (st) goto DTErr;
        st = metalMalloc(&d_master_cardano_icarus, sizeof(cardano_extended_private_key_t)); if (st) goto DTErr;
        st = metalMalloc(&d_master_cardano_daedalus, sizeof(cardano_extended_private_key_t)); if (st) goto DTErr;
        st = metalMalloc(&d_master_cardano_ledger, sizeof(cardano_extended_private_key_t)); if (st) goto DTErr;
        st = metalMalloc(&d_master_cardano_byron_legacy, sizeof(cardano_extended_private_key_t)); if (st) goto DTErr;
        st = metalMalloc(&d_entropy, 64); if (st) goto DTErr;
        st = metalMalloc(&d_entropy_len, sizeof(uint32_t)); if (st) goto DTErr;
        st = metalMalloc(&d_entropy_valid, sizeof(uint8_t)); if (st) goto DTErr;
    }
    st = metalMalloc(&d_save_str,   512); if (st) goto DTErr;
    st = metalMalloc(&d_save_len_dev, sizeof(uint32_t)); if (st) goto DTErr;

    {
        std::string line;
        while (read_trimmed_line(stream, line, 512)) {
            STATUS = line;
            st = dt_process_line(
                buffIsResult, buffDeviceResult, line,
                d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev,
                d_devIter, iter_sz,
                d_master_secp, d_master_ed, d_master_ed_hmac_precomp,
                d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy,
                d_entropy, d_entropy_len, d_entropy_valid,
                d_save_str, d_save_len_dev,
                &d_input_dev, mode, snap);
            if (st != metalSuccess) goto DTErr;
        }
        metalDeviceSynchronize();
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            dt_save_result(mode);
        }
    }
    st = metalSuccess;
    goto DTDone;
DTErr:
    fprintf(stderr, "processMetalDerThread error: %s\n", metalGetErrorString(st));
DTDone:
    if (d_derivations_dev)   metalFree(d_derivations_dev);
    if (d_deriv_offsets_dev) metalFree(d_deriv_offsets_dev);
    if (d_derIndex_dev)      metalFree(d_derIndex_dev);
    if (d_devIter)           metalFree(d_devIter);
    if (d_fast_scratch)      metalFree(d_fast_scratch);
    else if (d_master_secp)  metalFree(d_master_secp);
    if (d_master_ed)         metalFree(d_master_ed);
    if (d_master_ed_hmac_precomp) metalFree(d_master_ed_hmac_precomp);
    if (!d_fast_scratch) {
        if (d_master_cardano_icarus) metalFree(d_master_cardano_icarus);
        if (d_master_cardano_daedalus) metalFree(d_master_cardano_daedalus);
        if (d_master_cardano_ledger) metalFree(d_master_cardano_ledger);
        if (d_master_cardano_byron_legacy) metalFree(d_master_cardano_byron_legacy);
        if (d_entropy)           metalFree(d_entropy);
        if (d_entropy_len)       metalFree(d_entropy_len);
        if (d_entropy_valid)     metalFree(d_entropy_valid);
    }
    if (d_save_str)          metalFree(d_save_str);
    if (d_save_len_dev)      metalFree(d_save_len_dev);
    if (d_input_dev)         metalFree(d_input_dev);
    return st;
}

// Inner kernel pair for prng gen mode.
static metalError_t dt_launch_gen_one(
    bool*    buffIsResult, bool* buffDeviceResult,
    uint64_t seed_local,
    int      entropy_bytes, int gen_h,
    const char* pass_dev, uint32_t pass_len,
    bool     is_64,
    uint8_t* d_master_secp, uint8_t* d_master_ed,
    hmac_sha512_precomp_t* d_master_ed_hmac_precomp,
    uint8_t* d_master_cardano_icarus, uint8_t* d_master_cardano_daedalus,
    uint8_t* d_master_cardano_ledger,
    uint8_t* d_master_cardano_byron_legacy,
    uint8_t* d_entropy, uint32_t* d_entropy_len, uint8_t* d_entropy_valid,
    char*    d_save_str, uint32_t* d_save_len_dev,
    uint32_t* d_derivations_dev,
    uint32_t* d_deriv_offsets_dev,
    uint32_t* d_derIndex_dev)
{
    metal_launch("workerDerThread_mkd_gen", 1, 1, seed_local, entropy_bytes, gen_h - 1, d_master_secp, d_master_ed, d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy, d_entropy, d_entropy_len, d_entropy_valid, d_save_str, d_save_len_dev, 3, // entropy/mnemonic mode
        ENTROPY_MODE, pass_dev, pass_len, is_64);
    metalError_t st = metalGetLastError();
    if (st != metalSuccess) return st;
    st = metalDeviceSynchronize();
    if (st != metalSuccess) return st;

    if (dt_use_slip0010_solana_fast_path() && d_master_ed_hmac_precomp != nullptr) {
        metal_launch("workerDerThread_precompute_master_ed_hmac", 1, 1, d_master_ed, d_master_ed_hmac_precomp);
        st = metalGetLastError();
        if (st != metalSuccess) return st;
    }

    uint32_t h_save_len = 0;
    metalMemcpy(&h_save_len, d_save_len_dev, sizeof(uint32_t), metalMemcpyDeviceToHost);

    const uint32_t grid = (derIndex_size + BLOCK_THREADS - 1) / BLOCK_THREADS;
    if (dt_use_slip0010_solana_fast_path()) {
        metal_launch("workerDerThread_slip0010_solana", grid, BLOCK_THREADS, buffIsResult, buffDeviceResult, d_master_ed, d_master_ed_hmac_precomp, d_save_str, h_save_len, pass_dev, pass_len, seed_local, true, d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev, derIndex_size, 0, Rounds);
    } else if (dt_use_bip32_compressed_fast_path()) {
        metal_launch("workerDerThread_bip32_compressed", grid, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_master_secp, d_save_str, h_save_len, pass_dev, pass_len, seed_local, true, d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev, derIndex_size, 0, Rounds);
    } else {
        metal_launch("workerDerThread", grid, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_master_secp, d_master_ed, d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy, d_entropy, d_entropy_len, d_entropy_valid, d_save_str, h_save_len, pass_dev, pass_len, seed_local, true, d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev, derIndex_size, 0, Rounds);
    }
    st = metalGetLastError();
    if (st != metalSuccess) return st;

    counterTotal++;
    return metalSuccess;
}

// Prng gen variant: for each seed, derive master key via workerDerThread_mkd_gen,
// then check all derivation paths via workerDerThread.
metalError_t processMetalDerThreadGen(bool is_64)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, [is_64]() -> metalError_t {
            return processMetalDerThreadGen(is_64);
        });
    }
    ensure_dt_deriv_offsets();

    uint64_t    outputSizeB_T       = BLOCK_NUMBER * BLOCK_THREADS;
    bool*       buffIsResult        = nullptr;
    bool*       buffDeviceResult    = nullptr;
    uint32_t*   d_derivations_dev   = nullptr;
    uint32_t*   d_deriv_offsets_dev = nullptr;
    uint32_t*   d_derIndex_dev      = nullptr;
    uint8_t*    d_master_secp       = nullptr;
    uint8_t*    d_master_ed         = nullptr;
    uint8_t*    d_master_cardano_icarus = nullptr;
    uint8_t*    d_master_cardano_daedalus = nullptr;
    uint8_t*    d_master_cardano_ledger = nullptr;
    uint8_t*    d_master_cardano_byron_legacy = nullptr;
    uint8_t*    d_entropy           = nullptr;
    uint32_t*   d_entropy_len       = nullptr;
    uint8_t*    d_entropy_valid     = nullptr;
    uint8_t*    d_fast_scratch      = nullptr;
    hmac_sha512_precomp_t* d_master_ed_hmac_precomp = nullptr;
    char*       d_save_str          = nullptr;
    uint32_t*   d_save_len_dev      = nullptr;
    metalError_t st;

    st = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);
    if (st != metalSuccess) goto DTGErr;
    st = metalMalloc(&d_derivations_dev, Derivations.size() * sizeof(uint32_t)); if (st) goto DTGErr;
    metalMemcpy(d_derivations_dev, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_deriv_offsets_dev, g_dt_deriv_offsets.size() * sizeof(uint32_t)); if (st) goto DTGErr;
    metalMemcpy(d_deriv_offsets_dev, g_dt_deriv_offsets.data(), g_dt_deriv_offsets.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_derIndex_dev, derIndex.size() * sizeof(uint32_t)); if (st) goto DTGErr;
    metalMemcpy(d_derIndex_dev, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    st = metalMalloc(&d_master_ed,   64); if (st) goto DTGErr;
    if (dt_use_slip0010_solana_fast_path()) {
        st = metalMalloc(&d_master_ed_hmac_precomp, sizeof(hmac_sha512_precomp_t)); if (st) goto DTGErr;
    }
    if (dt_use_derthread_fast_scratch()) {
        st = metalMalloc(&d_fast_scratch, 384); if (st) goto DTGErr;
        d_master_secp = d_fast_scratch;
        d_master_cardano_icarus = d_fast_scratch + 64;
        d_master_cardano_daedalus = d_fast_scratch + 160;
        d_master_cardano_ledger = nullptr;
        d_master_cardano_byron_legacy = nullptr;
        d_entropy = d_fast_scratch + 256;
        d_entropy_len = reinterpret_cast<uint32_t*>(d_fast_scratch + 320);
        d_entropy_valid = d_fast_scratch + 324;
    }
    else {
        st = metalMalloc(&d_master_secp, 64); if (st) goto DTGErr;
        st = metalMalloc(&d_master_cardano_icarus, sizeof(cardano_extended_private_key_t)); if (st) goto DTGErr;
        st = metalMalloc(&d_master_cardano_daedalus, sizeof(cardano_extended_private_key_t)); if (st) goto DTGErr;
        st = metalMalloc(&d_master_cardano_ledger, sizeof(cardano_extended_private_key_t)); if (st) goto DTGErr;
        st = metalMalloc(&d_master_cardano_byron_legacy, sizeof(cardano_extended_private_key_t)); if (st) goto DTGErr;
        st = metalMalloc(&d_entropy, 64); if (st) goto DTGErr;
        st = metalMalloc(&d_entropy_len, sizeof(uint32_t)); if (st) goto DTGErr;
        st = metalMalloc(&d_entropy_valid, sizeof(uint8_t)); if (st) goto DTGErr;
    }
    st = metalMalloc(&d_save_str,   512); if (st) goto DTGErr;
    st = metalMalloc(&d_save_len_dev, sizeof(uint32_t)); if (st) goto DTGErr;

    {
        uint64_t seed_start = is_64
            ? (isRandom ? random_seed64_inclusive(start_seed64, end_seed64) : start_seed64)
            : (isRandom ? random_seed32_inclusive(start_seed,   end_seed)   : start_seed);
        uint64_t seed_end = is_64 ? end_seed64 : end_seed;

        for (uint64_t seed_local = seed_start; seed_local <= seed_end; ) {
            current_seed = seed_local;
            for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len) {
                current_byte = PrngBytes[entr_len];
                for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                    if (is_64) metal_launch("SetSkipDev64", 1, 1, PrngSkip[skip]);
                    else       metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                    current_skip = PrngSkip[skip];
                    for (size_t n = 0; n < Gens.size(); ++n) {
                        int gen_h = Gens[n];
                        current_gen = gen_h;
                        for (size_t mi = 0; mi < PrngModes.size(); ++mi) {
                            int mode_h = PrngModes[mi];
                            if (!should_run_prng_combo(is_64, gen_h, mode_h)) continue;
                            current_mode = mode_h;
                            if (pass_set) {
                                for (size_t pi = 0; pi < passwords_files.size(); ++pi) {
                                    std::ifstream* ps = acquire_password_stream_for_rewind(passwords_files[pi]);
                                    if (!ps) continue;
                                    std::string pline;
                                    while (read_trimmed_line(*ps, pline, 128)) {
                                        if (read_result_flag_host(buffIsResult)) {
                                            clear_result_flag_host(buffIsResult);
                                            SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                        }
                                        st = copy_password_to_device(pline.data(), pline.size());
                                        if (st != metalSuccess) goto DTGErr;
                                        st = dt_launch_gen_one(buffIsResult, buffDeviceResult,
                                            seed_local, PrngBytes[entr_len], gen_h,
                                            passwords_dev, (uint32_t)pline.size(), is_64,
                                            d_master_secp, d_master_ed, d_master_ed_hmac_precomp,
                                            d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy,
                                            d_entropy, d_entropy_len, d_entropy_valid,
                                            d_save_str, d_save_len_dev,
                                            d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev);
                                        if (st != metalSuccess) goto DTGErr;
                                    }
                                }
                                for (size_t pi = 0; pi < passwords_list.size(); ++pi) {
                                    const std::string& pline = passwords_list[pi];
                                    if (read_result_flag_host(buffIsResult)) {
                                        clear_result_flag_host(buffIsResult);
                                        SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                    }
                                    st = copy_password_to_device(pline.data(), pline.size());
                                    if (st != metalSuccess) goto DTGErr;
                                    st = dt_launch_gen_one(buffIsResult, buffDeviceResult,
                                        seed_local, PrngBytes[entr_len], gen_h,
                                        passwords_dev, (uint32_t)pline.size(), is_64,
                                        d_master_secp, d_master_ed, d_master_ed_hmac_precomp,
                                        d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy,
                                        d_entropy, d_entropy_len, d_entropy_valid,
                                        d_save_str, d_save_len_dev,
                                        d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev);
                                    if (st != metalSuccess) goto DTGErr;
                                }
                            } else {
                                if (read_result_flag_host(buffIsResult)) {
                                    clear_result_flag_host(buffIsResult);
                                    SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                }
                                st = dt_launch_gen_one(buffIsResult, buffDeviceResult,
                                    seed_local, PrngBytes[entr_len], gen_h,
                                    nullptr, 0, is_64,
                                    d_master_secp, d_master_ed, d_master_ed_hmac_precomp,
                                    d_master_cardano_icarus, d_master_cardano_daedalus, d_master_cardano_ledger, d_master_cardano_byron_legacy,
                                    d_entropy, d_entropy_len, d_entropy_valid,
                                    d_save_str, d_save_len_dev,
                                    d_derivations_dev, d_deriv_offsets_dev, d_derIndex_dev);
                                if (st != metalSuccess) goto DTGErr;
                            }
                        }
                    }
                }
            }
            if (isRandom)
                seed_local = is_64 ? random_seed64_inclusive(start_seed64, end_seed64) : random_seed32_inclusive(start_seed, end_seed);
            else
                seed_local++;
        }

        metalDeviceSynchronize();
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultGen(OUT_FILE, Founds, save, Derivations_list,
                PrngBytes.empty() ? 0 : PrngBytes[0],
                PrngModes.empty() ? 0 : PrngModes[0],
                Gens.empty() ? 0 : Gens[0],
                PrngSkip.empty() ? 0 : PrngSkip[0]);
        }
    }
    st = metalSuccess;
    goto DTGDone;
DTGErr:
    fprintf(stderr, "processMetalDerThreadGen error: %s\n", metalGetErrorString(st));
DTGDone:
    if (d_derivations_dev)   metalFree(d_derivations_dev);
    if (d_deriv_offsets_dev) metalFree(d_deriv_offsets_dev);
    if (d_derIndex_dev)      metalFree(d_derIndex_dev);
    if (d_fast_scratch)      metalFree(d_fast_scratch);
    else if (d_master_secp)  metalFree(d_master_secp);
    if (d_master_ed)         metalFree(d_master_ed);
    if (d_master_ed_hmac_precomp) metalFree(d_master_ed_hmac_precomp);
    if (!d_fast_scratch) {
        if (d_master_cardano_icarus) metalFree(d_master_cardano_icarus);
        if (d_master_cardano_daedalus) metalFree(d_master_cardano_daedalus);
        if (d_master_cardano_ledger) metalFree(d_master_cardano_ledger);
        if (d_master_cardano_byron_legacy) metalFree(d_master_cardano_byron_legacy);
        if (d_entropy)           metalFree(d_entropy);
        if (d_entropy_len)       metalFree(d_entropy_len);
        if (d_entropy_valid)     metalFree(d_entropy_valid);
    }
    if (d_save_str)          metalFree(d_save_str);
    if (d_save_len_dev)      metalFree(d_save_len_dev);
    return st;
}

//Entropy modes

static bool entropy_should_auto_pass_thread(std::istream& stream);

metalError_t processMetalEntropy(std::istream& stream)
{
    if (pass_thread_mode) return processMetalEntropyPassThread(stream);
    if (der_thread_mode)  return processMetalDerThread(3, stream);
    if (!FULL && &stream != &std::cin && pass_set && !pass_brute &&
        !g_crypted_input_decode_enabled && entropy_should_auto_pass_thread(stream)) {
        return processMetalEntropyPassThreadCartesian(stream);
    }
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalEntropy(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 256);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 256);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";

    uint32_t* _devIndexes1 = nullptr;
    uint32_t* _devIndexes2 = nullptr;
    uint32_t* _derIndex = nullptr;
    char* _devLines1 = nullptr;
    char* _devLines2 = nullptr;
    uint32_t* _devIter = nullptr;
    int* _devSize = nullptr;
    uint32_t* derivation_list = nullptr;
    uint32_t sizes_size = Sizes.size();
    uint32_t iteration_size = Iterations.size();

    metalStatus = metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _derIndex failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc((void**)&_devIter, Iterations.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _devIter failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Iterations.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc((void**)&_devSize, Sizes.size() * sizeof(int));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _devSize failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(_devSize, Sizes.data(), Sizes.size() * sizeof(int), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Sizes.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc derivation_list failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Derivations.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy derIndex.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    if (!is_multi_gpu_active()) {
        std::ios_base::sync_with_stdio(false);
        std::cin.tie(nullptr);
    }
    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_trimmed_line_known_lock(stream, buffer, 256, input_requires_shared_lock))
        {
            combined1.append(buffer.data(), buffer.size());
            indexes1.emplace_back(combined1.size());
            nr1++;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        assign_last_raw_batch_line(nr1Last, combined1, indexes1);
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes1, indexes1.data(), indexes1.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //show status
 /*       long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
        }*/

        //sync kernel 2
        if (nr2 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResult(OUT_FILE, Founds, save, Derivations_list);
            }
        }

        //launch kernel 1
        if (nr1 > 0) {

            if (pass_set)
            {
                for (size_t i = 0; i < passwords_files.size(); ++i) {

                    const std::string& fname = passwords_files[i];

                    std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
                    if (pass_stream == nullptr) {
                        continue;
                    }
                    string password_line;
                    while (read_trimmed_line(*pass_stream, password_line, 128))
                    {                        metalStatus = metalDeviceSynchronize();

                        //copy passwords -> device
                        metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }



                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResult(OUT_FILE, Founds, save, Derivations_list);
                        }

                        metalStatus = metalDeviceSynchronize();

                        metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines1, _devIndexes1, nr1, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, password_line.size(), 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);



                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }


                        counterTotal += (nr1 * Iterations.size() * Sizes.size());

                    }




                }
                for (size_t i = 0; i < passwords_list.size(); ++i)
                {
                    string password_line = passwords_list[i];
                    metalStatus = metalDeviceSynchronize();
                    //copy passwords -> device
                    metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResult(OUT_FILE, Founds, save, Derivations_list);
                    }
                    metalStatus = metalDeviceSynchronize();
                    metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines1, _devIndexes1, nr1, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, password_line.size(), 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);

                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }


                    counterTotal += (nr1 * Iterations.size() * Sizes.size());
                }
                if (pass_brute)
                {
                    uint8_t start_pass_point_local[128];
                    memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                    uint64_t start_pass[16];
                    uint64_t start_pass_plus[16];
                    int pass_len = 0;
                    array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                    pass_len = sizeBE_64(start_pass, 16);
                    if (pass_len < min_pass_len)
                    {
                        pass_len = min_pass_len;
                    }

                    while (true)
                    {
                        int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                        if (result > 0)
                        {
                            break;
                        }
                        metalStatus = metalDeviceSynchronize();
                        //copy password -> device
                        metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResult(OUT_FILE, Founds, save, Derivations_list);
                        }
                        metalStatus = metalDeviceSynchronize();

                        metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines1, _devIndexes1, nr1, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, pass_len, 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);

                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }


                        counterTotal += (nr1 * Iterations.size() * Sizes.size());

                        array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                        add64to1024_host(start_pass, 1, start_pass_plus);
                        array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                        pass_len = sizeBE_64(start_pass_plus, 16);
                        if (pass_len < min_pass_len)
                        {
                            pass_len = min_pass_len;
                        }
                    }



                }
            }
            else
            {

                metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines1, _devIndexes1, nr1, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, passwords_lenght_dev, 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);
                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                counterTotal += (nr1 * Iterations.size() * Sizes.size());
            }
        }


        STATUS = nr2Last;
        //read file 1
        combined2.clear();
        indexes2.clear();
        nr2 = 0;
        data2ready = false;
        while (read_trimmed_line_known_lock(stream, buffer, 256, input_requires_shared_lock))
        {
            combined2.append(buffer.data(), buffer.size());
            indexes2.emplace_back(combined2.size());
            nr2++;
            if (nr2 < outputSizeB_T) {
                continue;
            }
            data2ready = true;
            break;
        }
        assign_last_raw_batch_line(nr2Last, combined2, indexes2);
        if (!data2ready) {
            isData = false;
        }
        if (nr2 > 0) {
            //copy data 2 -> device
            metalStatus = copy_to_device_grow((void**)&_devLines2, combined2.data(), combined2.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes2, indexes2.data(), indexes2.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //sync kernel 1
        if (nr1 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 1
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResult(OUT_FILE, Founds, save, Derivations_list);
            }
        }
        //launch kernel 2
        if (nr2 > 0) {

            if (pass_set)
            {
                for (size_t i = 0; i < passwords_files.size(); ++i) {

                    const std::string& fname = passwords_files[i];

                    std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
                    if (pass_stream == nullptr) {
                        continue;
                    }
                    string password_line;
                    while (read_trimmed_line(*pass_stream, password_line, 128))
                    {                        metalStatus = metalDeviceSynchronize();

                        //copy passwords -> device
                        metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }



                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResult(OUT_FILE, Founds, save, Derivations_list);
                        }

                        metalStatus = metalDeviceSynchronize();

                        metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines2, _devIndexes2, nr2, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, password_line.size(), 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);



                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }


                        counterTotal += (nr2 * Iterations.size() * Sizes.size());

                    }




                }
                for (size_t i = 0; i < passwords_list.size(); ++i)
                {
                    string password_line = passwords_list[i];
                    metalStatus = metalDeviceSynchronize();
                    //copy passwords -> device
                    metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResult(OUT_FILE, Founds, save, Derivations_list);
                    }
                    metalStatus = metalDeviceSynchronize();
                    metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines2, _devIndexes2, nr2, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, password_line.size(), 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);

                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }


                    counterTotal += (nr2 * Iterations.size() * Sizes.size());
                }
                if (pass_brute)
                {
                    uint8_t start_pass_point_local[128];
                    memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                    uint64_t start_pass[16];
                    uint64_t start_pass_plus[16];
                    int pass_len = 0;
                    array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                    pass_len = sizeBE_64(start_pass, 16);
                    if (pass_len < min_pass_len)
                    {
                        pass_len = min_pass_len;
                    }

                    while (true)
                    {
                        int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                        if (result > 0)
                        {
                            break;
                        }
                        metalStatus = metalDeviceSynchronize();
                        //copy password -> device
                        metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResult(OUT_FILE, Founds, save, Derivations_list);
                        }
                        metalStatus = metalDeviceSynchronize();

                        metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines2, _devIndexes2, nr2, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, pass_len, 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);

                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }


                        counterTotal += (nr2 * Iterations.size() * Sizes.size());

                        array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                        add64to1024_host(start_pass, 1, start_pass_plus);
                        array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                        pass_len = sizeBE_64(start_pass_plus, 16);
                        if (pass_len < min_pass_len)
                        {
                            pass_len = min_pass_len;
                        }
                    }



                }
            }
            else
            {

                metal_launch("workerEntropy", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines2, _devIndexes2, nr2, derivation_list, _derIndex, derIndex_size, 0, passwords_dev, passwords_lenght_dev, 0, use_custom_size, _devSize, sizes_size, ENTROPY_MODE, _devIter, iteration_size, Rounds, dub_mnem);
                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }

                counterTotal += (nr2 * Iterations.size() * Sizes.size());
            }




        }
        STATUS = nr1Last;
    }
    metalDeviceSynchronize();

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(_devIndexes1);
    metalFree(_devIndexes2);
    metalFree(_derIndex);
    metalFree(_devIter);
    metalFree(_devSize);
    metalFree(_devLines1);
    metalFree(_devLines2);
    metalFree(derivation_list);
    return metalStatus;
}

// processMetal2FileEntropy: runs the Metal workflow for 2 file entropy.
metalError_t processMetal2FileEntropy(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);
        metalError_t st;

        if (use_combos)
        {

            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });


            st = processMetalEntropy(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = processMetalEntropy(stream);
        }



        if (st != metalSuccess) {
            std::cerr << "processMetalEntropy failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalEntropySeq: runs the Metal workflow for entropy seq.
metalError_t processMetalEntropySeq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalEntropySeq();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;


    metalMalloc((void**)&start_pvk_dev, 512);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    uint64_t plus_size = 0;

    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp_host(start_entropy_point, end_entropy_point, 1024);
        if (result > 0)
        {
            break;
        }
        write_seq_checkpoint_log('+', start_brain_point, 256, effective_seq_kernel_step());
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_entropy_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        for (size_t suz = 0; suz < Sizes.size(); ++suz)
        {
            int custom_size = Sizes[suz];



            for (size_t num = 0; num < Iterations.size(); ++num)
            {

                uint32_t ITERATION_HOST = Iterations[num];

                if (pass_set)
                {
                    for (size_t i = 0; i < passwords_files.size(); ++i) {

                        const std::string& fname = passwords_files[i];

                        std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
                        if (pass_stream == nullptr) {
                            continue;
                        }
                        string password_line;
                        while (read_trimmed_line(*pass_stream, password_line, 128))
                        {                            metalStatus = metalDeviceSynchronize();
                            //copy passwords -> device
                            metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }

                            if (read_result_flag_host(buffIsResult)) {
                                clear_result_flag_host(buffIsResult);
                                SaveResult(OUT_FILE, Founds, save, Derivations_list);
                            }
                            metalStatus = metalDeviceSynchronize();

                            metal_launch("workerEntropy_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, password_line.size(), 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                            metalStatus = metalGetLastError();
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }
                            counterTotal += outputSizeB_T;



                        }
                        }
                    for (size_t i = 0; i < passwords_list.size(); ++i)
                    {
                        string password_line = passwords_list[i];
                        metalStatus = metalDeviceSynchronize();
                        //copy passwords -> device
                        metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResult(OUT_FILE, Founds, save, Derivations_list);
                        }
                        metalStatus = metalDeviceSynchronize();

                        metal_launch("workerEntropy_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, password_line.size(), 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        counterTotal += outputSizeB_T;

                    }
                    if (pass_brute)
                    {
                        uint8_t start_pass_point_local[128];
                        memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                        uint64_t start_pass[16];
                        uint64_t start_pass_plus[16];
                        int pass_len = 0;
                        array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                        pass_len = sizeBE_64(start_pass, 16);
                        if (pass_len < min_pass_len)
                        {
                            pass_len = min_pass_len;
                        }

                        while (true)
                        {
                            int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                            if (result > 0)
                            {
                                break;
                            }
                            metalStatus = metalDeviceSynchronize();
                            //copy password -> device
                            metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }
                            if (read_result_flag_host(buffIsResult)) {
                                clear_result_flag_host(buffIsResult);
                                SaveResult(OUT_FILE, Founds, save, Derivations_list);
                            }
                            metalStatus = metalDeviceSynchronize();

                            metal_launch("workerEntropy_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, pass_len, 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                            metalStatus = metalGetLastError();
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }


                            counterTotal += outputSizeB_T;

                            array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                            add64to1024_host(start_pass, 1, start_pass_plus);
                            array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                            pass_len = sizeBE_64(start_pass_plus, 16);
                            if (pass_len < min_pass_len)
                            {
                                pass_len = min_pass_len;
                            }
                        }



                    }
                    long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                    if (tHash > 2500) {
                        counter = 0;
                        beginCountHashrate = std::chrono::steady_clock::now();

                        {
                            FILE* fp = open_runtime_log("EntropySeq_log.txt", "wb");
                            if (fp)
                            {
                                write_hex_last(fp, start_entropy_point, 512, (size_t)plus_size);
                            }

                            if (fp) fclose(fp);
                        }

                    }
                }
                else
                {


                    metal_launch("workerEntropy_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);
                    metalStatus = metalGetLastError();

                    counterTotal += outputSizeB_T;

                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }



                    metalStatus = metalDeviceSynchronize();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                        goto Error;
                    }
                    //show status
                    long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                    if (tHash > 2500) {
                        counter = 0;
                        beginCountHashrate = std::chrono::steady_clock::now();

                        {
                            FILE* fp = open_runtime_log("EntropySeq_log.txt", "wb");
                            if (fp)
                            {
                                write_hex_last(fp, start_entropy_point, 512, (size_t)plus_size);
                            }

                            if (fp) fclose(fp);
                        }

                    }
                    //check result 2
                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResult(OUT_FILE, Founds, save, Derivations_list);

                    }
                }

            }

        }

        uint64_t valLE[64];
        uint64_t valBE[64];

        array512_to_64x64_le(start_entropy_point, valLE);

        add64to4096_host(valLE, outputSizeB_T * step, valBE);

        array64x64_le_to512(valBE, start_entropy_point);
        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

