                }
            }

        }

        uint64_t valLE[64];
        uint64_t valBE[64];

        array512_to_64x64_le(start_entropy_point, valLE);

        sub64from4096_host(valLE, outputSizeB_T * step, valBE);

        array64x64_le_to512(valBE, start_entropy_point);
        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

// processMetalEntropySeqBoth: runs the Metal workflow for entropy seq both.
