                                add64to1024_host(start_pass, 1, start_pass_plus);
                                array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                                pass_len = sizeBE_64(start_pass_plus, 16);
                                if (pass_len < min_pass_len)
                                {
                                    pass_len = min_pass_len;
                                }
                            }



                        }

                    }
                    else
                    {

                        metal_launch("workerEntropy_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                        metalStatus = metalGetLastError();

                        counterTotal += outputSizeB_T;

                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metal_launch("workerEntropy_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                        metalStatus = metalGetLastError();

                        counterTotal += outputSizeB_T;

                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        metalStatus = metalDeviceSynchronize();


                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                            goto Error;
                        }


                        //show status
                        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                        if (tHash > 2500) {
                            counter = 0;
                            beginCountHashrate = std::chrono::steady_clock::now();

                        }
                        // check result after both (+/-) launches in this chunk
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResult(OUT_FILE, Founds, save, Derivations_list);

                        }
                    }
                }
            }

            array512_to_64x64_le(plus_entropy_point, valLE);
            add64to4096_host(valLE, outputSizeB_T * step, valBE);
            array64x64_le_to512(valBE, plus_entropy_point);


            array512_to_64x64_le(minus_entropy_point, valLE);
            sub64from4096_host(valLE, outputSizeB_T * step, valBE);
            array64x64_le_to512(valBE, minus_entropy_point);
        }
        if (seqMode)
        {
            random_bytes_seq(start_entropy_point, end_entropy_point, start_pvk_point_local, 512);
        }
        else
        {
            random_bytes(start_pvk_point_local, 512, entropy_len);
        }
        memcpy(&plus_entropy_point[0], &start_pvk_point_local[0], 512);
        memcpy(&minus_entropy_point[0], &start_pvk_point_local[0], 512);


    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResult(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalGen: runs the Metal workflow for gen.
metalError_t processMetalGen()
{
    if (der_thread_mode) return processMetalDerThreadGen(false);
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalGen();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;



    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    // Allocate derivation list buffer on device.
    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t)); // Derivations-only buffer size.
    // Copy derivation list from host to device.
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    char* pass_dev;
    metalMalloc((void**)&pass_dev, 128);
    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed; seed_local <= end_seed;) {
        uint64_t remaining = end_seed - seed_local + 1;
        uint64_t seed_count = (remaining < outputSizeB_T) ? remaining : outputSizeB_T;

        current_seed = seed_local;
        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFULL);

                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        for (size_t suz = 0; suz < Sizes.size(); ++suz)
                        {
                            int custom_size = Sizes[suz];



                            for (size_t num = 0; num < Iterations.size(); ++num)
                            {

                                uint32_t ITERATION_HOST = Iterations[num];
                                std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                                if (pass_set)
                                {
                                    for (size_t i = 0; i < passwords_files.size(); ++i) {

                                        const std::string& fname = passwords_files[i];

                                        std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
                                        if (pass_stream == nullptr) {
                                            continue;
                                        }
                                        string password_line;
                                        while (read_trimmed_line(*pass_stream, password_line, 128))
                                        {                                            metalStatus = metalDeviceSynchronize();
                                            //copy passwords -> device
                                            metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                                            if (metalStatus != metalSuccess) {
                                                fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                                                goto Error;
                                            }

                                            if (read_result_flag_host(buffIsResult)) {
                                                clear_result_flag_host(buffIsResult);
                                                SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                            }
                                            metalStatus = metalDeviceSynchronize();

                                            metal_launch("worker_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, passwords_dev, password_line.size(), 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                                            metalStatus = metalGetLastError();
                                            if (metalStatus != metalSuccess) {
                                                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                                goto Error;
                                            }
                                            counterTotal += seed_count;



                                        }
                                                        }
                                    for (size_t i = 0; i < passwords_list.size(); ++i)
                                    {
                                        string password_line = passwords_list[i];
                                        metalStatus = metalDeviceSynchronize();
                                        //copy passwords -> device
                                        metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                                        if (metalStatus != metalSuccess) {
                                            fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                                            goto Error;
                                        }
                                        if (read_result_flag_host(buffIsResult)) {
                                            clear_result_flag_host(buffIsResult);
                                            SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                        }
                                        metalStatus = metalDeviceSynchronize();


                                        metal_launch("worker_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, passwords_dev, password_line.size(), 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                                        metalStatus = metalGetLastError();
                                        if (metalStatus != metalSuccess) {
                                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                            goto Error;
                                        }
                                        counterTotal += seed_count;

                                    }
                                    if (pass_brute)
                                    {
                                        uint8_t start_pass_point_local[128];
                                        memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                                        uint64_t start_pass[16];
                                        uint64_t start_pass_plus[16];
                                        int pass_len = 0;
                                        array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                                        pass_len = sizeBE_64(start_pass, 16);
                                        if (pass_len < min_pass_len)
                                        {
                                            pass_len = min_pass_len;
                                        }

                                        while (true)
                                        {
                                            int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                                            if (result > 0)
                                            {
                                                break;
                                            }
                                            metalStatus = metalDeviceSynchronize();
                                            //copy password -> device
                                            metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                                            if (metalStatus != metalSuccess) {
                                                fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                                                goto Error;
                                            }
                                            if (read_result_flag_host(buffIsResult)) {
                                                clear_result_flag_host(buffIsResult);
                                                SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                            }
                                            metalStatus = metalDeviceSynchronize();

                                            metal_launch("worker_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, passwords_dev, pass_len, 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);

                                            metalStatus = metalGetLastError();
                                            if (metalStatus != metalSuccess) {
                                                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                                goto Error;
                                            }


                                            counterTotal += seed_count;

                                            array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                                            add64to1024_host(start_pass, 1, start_pass_plus);
                                            array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                                            pass_len = sizeBE_64(start_pass_plus, 16);
                                            if (pass_len < min_pass_len)
                                            {
                                                pass_len = min_pass_len;
                                            }
                                        }



                                    }
                                }
                                else {

                                    metal_launch("worker_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, passwords_dev, passwords_lenght_dev, 0, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds, dub_mnem);
                                    metalStatus = metalGetLastError();
                                    if (metalStatus != metalSuccess) {
                                        fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                        goto Error;
                                    }


                                    counterTotal += seed_count;




                                    metalStatus = metalDeviceSynchronize();
                                    if (metalStatus != metalSuccess) {
                                        fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                                        goto Error;
                                    }
                                    //show status
                                    long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                    if (tHash > 2500) {
                                        counter = 0;
                                        beginCountHashrate = std::chrono::steady_clock::now();
                                    }
                                    //check result 2
                                    if (read_result_flag_host(buffIsResult)) {
                                        clear_result_flag_host(buffIsResult);
                                        SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                    }
                                }
                            }
                        }

                    }
                }

            }
        }

        if (isRandom)
        {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else
        {
            seed_local += seed_count;
        }
    }
Error:

    return metalStatus;
}

