                                    //show status
                                    long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                    if (tHash > 2500) {
                                        counter = 0;
                                        beginCountHashrate = std::chrono::steady_clock::now();
                                    }
                                    //check result 2
                                    if (read_result_flag_host(buffIsResult)) {
                                        clear_result_flag_host(buffIsResult);
                                        SaveResultGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                    }
                                }
                            }
                        }

                    }
                }

            }
        }


        if (isRandom)
        {
            seed_local = random_seed64_inclusive(start_seed64, end_seed64);
        }
        else
        {
            if (seed_local > (std::numeric_limits<uint64_t>::max() - seed_count)) {
                break;
            }
            seed_local += seed_count;
        }


    }
Error:

    return metalStatus;
}

//Mnemonic Modes

static bool entropy_should_auto_pass_thread(std::istream& stream)
{
    constexpr size_t minimum_cartesian_candidates = 64u;
    const size_t cached_password_count = passwords_files.empty() ? passwords_list.size() : 0u;
    if (cached_password_count < 2u) return false;

    const std::ios::iostate initial_state = stream.rdstate();
    if (initial_state != std::ios::goodbit) return false;

    const std::istream::pos_type initial_position = stream.tellg();
    if (initial_position == std::istream::pos_type(-1)) {
        stream.clear(initial_state);
        return false;
    }

    size_t input_line_count = 0u;
    std::string line;
    while (input_line_count < cached_password_count && std::getline(stream, line)) {
        ++input_line_count;
    }
    const bool reached_eof = stream.eof();

    stream.clear();
    stream.seekg(initial_position);
    const bool restored = static_cast<bool>(stream);
    stream.clear(initial_state);

    const size_t minimum_input_lines =
        (minimum_cartesian_candidates + cached_password_count - 1u) / cached_password_count;
    return restored && reached_eof && input_line_count < cached_password_count &&
        input_line_count >= minimum_input_lines;
}

static bool mnemonic_should_auto_pass_thread(std::istream& stream)
{
    const std::ios::iostate initial_state = stream.rdstate();
    if (initial_state != std::ios::goodbit) return false;

    const std::istream::pos_type initial_position = stream.tellg();
    if (initial_position == std::istream::pos_type(-1)) {
        stream.clear(initial_state);
        return false;
    }

    const size_t cached_password_count = passwords_files.empty() ? passwords_list.size() : 0u;
    const size_t scan_limit = cached_password_count > 2u ? cached_password_count : 2u;
    size_t input_line_count = 0u;
    std::string line;
    while (input_line_count < scan_limit && std::getline(stream, line)) {
        ++input_line_count;
    }
    const bool reached_eof = stream.eof();

    stream.clear();
    stream.seekg(initial_position);
    const bool restored = static_cast<bool>(stream);
    stream.clear(initial_state);
    return restored && reached_eof && input_line_count > 0u &&
        (input_line_count == 1u || input_line_count < cached_password_count);
}

metalError_t processMetal2(std::istream& stream)
{
    if (pass_thread_mode) return processMetal2PassThread(stream);
    if (der_thread_mode)  return processMetalDerThread(2, stream);
    if (!FULL && &stream != &std::cin && pass_set && !pass_brute &&
        !g_crypted_input_decode_enabled && mnemonic_should_auto_pass_thread(stream)) {
        return processMetal2PassThread(stream);
    }
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetal2(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 512);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 512);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";

    uint32_t* _devIndexes1 = nullptr;
    uint32_t* _devIndexes2 = nullptr;
    uint32_t* _derIndex = nullptr;
    char* _devLines1 = nullptr;
    char* _devLines2 = nullptr;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));

    uint32_t* derivation_list = nullptr;
    uint32_t iteration_size = Iterations.size();

    uint32_t* _devIter = nullptr;
    metalMalloc((void**)&_devIter, Iterations.size() * sizeof(uint32_t));
    metalStatus = metalMemcpyAsync(_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    // Allocate derivation list buffer on device.
    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t)); // Derivations-only buffer size.
    // Copy derivation list from host to device.
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (!is_multi_gpu_active()) {
        std::ios_base::sync_with_stdio(false);
        std::cin.tie(nullptr);
    }
    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            combined1.append(buffer.data(), buffer.size());
            indexes1.emplace_back(combined1.size());
            nr1++;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        assign_last_raw_batch_line(nr1Last, combined1, indexes1);
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
