                }
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
                }
                metalStatus = metalDeviceSynchronize();

                metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                counterTotal += outputSizeB_T * Iterations.size();

            }
            if (pass_brute)
            {
                uint8_t start_pass_point_local[128];
                memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                uint64_t start_pass[16];
                uint64_t start_pass_plus[16];
                int pass_len = 0;
                array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                pass_len = sizeBE_64(start_pass, 16);
                if (pass_len < min_pass_len)
                {
                    pass_len = min_pass_len;
                }

                while (true)
                {
                    int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                    if (result > 0)
                    {
                        break;
                    }
                    metalStatus = metalDeviceSynchronize();
                    //copy password -> device
                    metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
                    }
                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, pass_len, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);

                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }


                    counterTotal += outputSizeB_T * Iterations.size();

                    array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                    add64to1024_host(start_pass, 1, start_pass_plus);
                    array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                    pass_len = sizeBE_64(start_pass_plus, 16);
                    if (pass_len < min_pass_len)
                    {
                        pass_len = min_pass_len;
                    }
                }



            }
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("MnemonicSeq_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, start_mnemonic_point, 512, (size_t)plus_size);
                    }

                    if (fp) fclose(fp);
                }
                write_seq_checkpoint_log('+', start_mnemonic_point, 512, effective_seq_kernel_step());

            }
        }
        else
        {



            metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);
            metalStatus = metalGetLastError();

            counterTotal += outputSizeB_T * Iterations.size();

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }



            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("MnemonicSeq_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, start_mnemonic_point, 512, (size_t)plus_size);
                    }

                    if (fp) fclose(fp);
                }
                write_seq_checkpoint_log('-', start_mnemonic_point, 512, effective_seq_kernel_step());

            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultByte(OUT_FILE, Founds, save, Derivations_list);

            }

        }
        uint64_t valLE[64];
        uint64_t valBE[64];

        array512_to_64x64_le(start_mnemonic_point, valLE);

        add64to4096_host(valLE, outputSizeB_T * step, valBE);

        array64x64_le_to512(valBE, start_mnemonic_point);
        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

