// processMetalSeqBoth: runs the Metal workflow for seq both.
metalError_t processMetalSeqBoth()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalSeqBoth();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_mnemonic_point[512] = { 0 };
    uint8_t minus_mnemonic_point[512] = { 0 };

    init_seq_both_points(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    metalMalloc((void**)&plus_pvk_dev, 512);
    metalMalloc((void**)&minus_pvk_dev, 512);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    uint32_t iteration_size = Iterations.size();

    uint32_t* _devIter;
    metalMalloc((void**)&_devIter, Iterations.size() * sizeof(uint32_t));
    metalStatus = metalMemcpyAsync(_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t valLE[64];
    uint64_t valBE[64];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;
    bool range_active = seq_both_round_active(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();

        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_mnemonic_point, 512, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_mnemonic_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        if (pass_set)
        {
            for (size_t i = 0; i < passwords_files.size(); ++i) {

                const std::string& fname = passwords_files[i];

                std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
                if (pass_stream == nullptr) {
                    continue;
                }
                string password_line;
                while (read_trimmed_line(*pass_stream, password_line, 128))
                {                    metalStatus = metalDeviceSynchronize();
                    //copy passwords -> device
                    metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
                    }
                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    counterTotal += outputSizeB_T * Iterations.size();


                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, -1, minus_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    counterTotal += outputSizeB_T * Iterations.size();





                }
            }
            for (size_t i = 0; i < passwords_list.size(); ++i)
            {
                string password_line = passwords_list[i];
                metalStatus = metalDeviceSynchronize();
                //copy passwords -> device
                metalStatus = copy_password_to_device(password_line.data(), password_line.size());
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalMemcpy passwords.data() failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
                }
                metalStatus = metalDeviceSynchronize();

                metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                counterTotal += outputSizeB_T * Iterations.size();

                metalStatus = metalDeviceSynchronize();

                metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, -1, minus_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                counterTotal += outputSizeB_T * Iterations.size();


            }
            if (pass_brute)
            {
                uint8_t start_pass_point_local[128];
                memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                uint64_t start_pass[16];
                uint64_t start_pass_plus[16];
                int pass_len = 0;
                array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                pass_len = sizeBE_64(start_pass, 16);
                if (pass_len < min_pass_len)
                {
                    pass_len = min_pass_len;
                }

                while (true)
                {
                    int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                    if (result > 0)
                    {
                        break;
                    }
                    metalStatus = metalDeviceSynchronize();
                    //copy password -> device
                    metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
                    }
                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, pass_len, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);

                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    counterTotal += outputSizeB_T * Iterations.size();

                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, -1, minus_pvk_dev, min_len, passwords_dev, pass_len, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);

                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    counterTotal += outputSizeB_T * Iterations.size();

                    array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                    add64to1024_host(start_pass, 1, start_pass_plus);
                    array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                    pass_len = sizeBE_64(start_pass_plus, 16);
                    if (pass_len < min_pass_len)
                    {
                        pass_len = min_pass_len;
                    }
                }



            }
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("MnemonicSeqBoth_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, plus_mnemonic_point, 512, (size_t)plus_size);
                        write_hex_last(fp, minus_mnemonic_point, 512, (size_t)minus_size, true);
                    }

                    if (fp) fclose(fp);
                }

            }
        }
        else
        {

            //+
            metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);
            metalStatus = metalGetLastError();

            counterTotal += outputSizeB_T * Iterations.size();

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultByte(OUT_FILE, Founds, save, Derivations_list);

            }
            metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);
            metalStatus = metalGetLastError();

            counterTotal += outputSizeB_T * Iterations.size();

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }


            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("MnemonicSeqBoth_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, plus_mnemonic_point, 512, (size_t)plus_size);
                        write_hex_last(fp, minus_mnemonic_point, 512, (size_t)minus_size, true);
                    }

                    if (fp) fclose(fp);
                }
            }

            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultByte(OUT_FILE, Founds, save, Derivations_list);

            }
        }
        array512_to_64x64_le(plus_mnemonic_point, valLE);
        add64to4096_host(valLE, outputSizeB_T * step, valBE);
        array64x64_le_to512(valBE, plus_mnemonic_point);

        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array512_to_64x64_le(minus_mnemonic_point, valLE);
        sub64from4096_host(valLE, outputSizeB_T * step, valBE);
        array64x64_le_to512(valBE, minus_mnemonic_point);

        minus_size = sizeBE_64(valBE, 64);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }

        local_n += outputSizeB_T;
        range_active = seq_both_round_active(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetal2Random: runs the Metal workflow for 2 random.
metalError_t processMetal2Random()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetal2Random();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t start_pvk_point_local[512] = { 0 };

    if (seqMode)
    {
        random_bytes_seq(start_mnemonic_point, start_mnemonic_point, start_pvk_point_local, 512);
    }
    else
    {
        random_bytes(start_pvk_point_local, 512, entropy_len);
    }

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_mnemonic_point[512] = { 0 };
    uint8_t minus_mnemonic_point[512] = { 0 };

    memcpy(&plus_mnemonic_point[0], &start_pvk_point_local[0], 512);
    memcpy(&minus_mnemonic_point[0], &start_pvk_point_local[0], 512);

    metalMalloc((void**)&plus_pvk_dev, 512);
    metalMalloc((void**)&minus_pvk_dev, 512);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));

    uint32_t iteration_size = Iterations.size();

    uint32_t* _devIter;
    metalMalloc((void**)&_devIter, Iterations.size() * sizeof(uint32_t));
    metalStatus = metalMemcpyAsync(_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t valLE[64];
    uint64_t valBE[64];


    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


        for (uint64_t local_n = 0; local_n <= n_number; local_n += outputSizeB_T)
        {
            metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_mnemonic_point, 512, metalMemcpyHostToDevice);
            metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_mnemonic_point, 512, metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            if (pass_set)
            {
                for (size_t i = 0; i < passwords_files.size(); ++i) {

