                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    counterTotal += outputSizeB_T * Iterations.size();

                    metalStatus = metalDeviceSynchronize();

                    metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, -1, minus_pvk_dev, min_len, passwords_dev, password_line.size(), 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);


                    metalStatus = metalGetLastError();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    counterTotal += outputSizeB_T * Iterations.size();


                }
                if (pass_brute)
                {
                    uint8_t start_pass_point_local[128];
                    memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                    uint64_t start_pass[16];
                    uint64_t start_pass_plus[16];
                    int pass_len = 0;
                    array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                    pass_len = sizeBE_64(start_pass, 16);
                    if (pass_len < min_pass_len)
                    {
                        pass_len = min_pass_len;
                    }

                    while (true)
                    {
                        int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                        if (result > 0)
                        {
                            break;
                        }
                        metalStatus = metalDeviceSynchronize();
                        //copy password -> device
                        metalStatus = copy_password_to_device(&start_pass_point_local[128 - pass_len], pass_len);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy start_pass_point_localfailed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
                        }
                        metalStatus = metalDeviceSynchronize();

                        metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, pass_len, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);

                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        counterTotal += outputSizeB_T * Iterations.size();

                        metalStatus = metalDeviceSynchronize();

                        metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, -1, minus_pvk_dev, min_len, passwords_dev, pass_len, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);

                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        counterTotal += outputSizeB_T * Iterations.size();

                        array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                        add64to1024_host(start_pass, 1, start_pass_plus);
                        array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);

                        pass_len = sizeBE_64(start_pass_plus, 16);
                        if (pass_len < min_pass_len)
                        {
                            pass_len = min_pass_len;
                        }
                    }



                }

            }
            else
