                metal_launch("worker_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, passwords_dev, passwords_lenght_dev, 0, Rounds, MNEMONIC_MODE, _devIter, iteration_size, IS_STRING, dub_mnem);
                metalStatus = metalGetLastError();

                counterTotal += outputSizeB_T * Iterations.size();

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
