//Bip32 Passphrase modes

metalError_t processMetalBip32Seq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBip32Seq();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;


    metalMalloc((void**)&start_pvk_dev, 512);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t plus_size = 0;


    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp_host(start_mnemonic_point, end_mnemonic_point, 512);
        if (result > 0)
        {
            break;
        }
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_mnemonic_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        for (size_t num = 0; num < Iterations.size(); ++num)
        {

            uint32_t ITERATION_HOST = Iterations[num];
            metal_launch("workerBip32_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, BIP32_MODE, ITERATION_HOST, Rounds);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T;
            counterTotal += outputSizeB_T;

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }



            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("Bip32Seq_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, start_mnemonic_point, 512, (size_t)plus_size);
                    }

                    if (fp) fclose(fp);
                }


            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);

            }
        }

        uint64_t valLE[64];
        uint64_t valBE[64];

        array512_to_64x64_le(start_mnemonic_point, valLE);

        add64to4096_host(valLE, outputSizeB_T * step, valBE);

        array64x64_le_to512(valBE, start_mnemonic_point);

        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

// processMetalBip32SeqBack: runs the Metal workflow for BIP32 seq back.
metalError_t processMetalBip32SeqBack()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBip32SeqBack();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;


    metalMalloc((void**)&start_pvk_dev, 512);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    uint64_t plus_size = 0;

    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp_host(start_mnemonic_point, end_mnemonic_point, 512);
        if (result < 0)
        {
            break;
        }
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_mnemonic_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        for (size_t num = 0; num < Iterations.size(); ++num)
        {

            uint32_t ITERATION_HOST = Iterations[num];
            metal_launch("workerBip32_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, start_pvk_dev, min_len, BIP32_MODE, ITERATION_HOST, Rounds);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T;
            counterTotal += outputSizeB_T;

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }



            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("Bip32SeqBack_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, start_mnemonic_point, 512, (size_t)plus_size, true);
                    }

                    if (fp) fclose(fp);
                }

            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);

            }
        }

        uint64_t valLE[64];
        uint64_t valBE[64];

        array512_to_64x64_le(start_mnemonic_point, valLE);

        sub64from4096_host(valLE, outputSizeB_T * step, valBE);

        array64x64_le_to512(valBE, start_mnemonic_point);

        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

// processMetalBip32: runs the Metal workflow for BIP32.
metalError_t processMetalBip32(std::istream& stream)
{
    if (der_thread_mode) return processMetalDerThread(4, stream);
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalBip32(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 512);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 512);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";

    uint32_t* _devIndexes1 = nullptr;
    uint32_t* _devIndexes2 = nullptr;
    uint32_t* _derIndex = nullptr;
    char* _devLines1 = nullptr;
    char* _devLines2 = nullptr;
    uint32_t* _devIter = nullptr;
    uint32_t* derivation_list = nullptr;
    uint32_t iteration_size = Iterations.size();

    metalStatus = metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _derIndex failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc((void**)&_devIter, Iterations.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _devIter failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Iterations.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc derivation_list failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Derivations.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy derIndex.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            combined1.append(buffer.data(), buffer.size());
            indexes1.emplace_back(combined1.size());
            nr1++;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        assign_last_raw_batch_line(nr1Last, combined1, indexes1);
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes1, indexes1.data(), indexes1.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
        }

        //sync kernel 2
        if (nr2 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
            }
        }

        //launch kernel 1
        if (nr1 > 0) {
            metal_launch("workerBip32", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines1, _devIndexes1, nr1, derivation_list, _derIndex, derIndex_size, 0, BIP32_MODE, _devIter, iteration_size, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }

        STATUS = nr2Last;
        counter += nr1 * iteration_size;
        counterTotal += nr1 * iteration_size;
        //read file 1
        combined2.clear();
        indexes2.clear();
        nr2 = 0;
        data2ready = false;
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            combined2.append(buffer.data(), buffer.size());
            indexes2.emplace_back(combined2.size());
            nr2++;
            if (nr2 < outputSizeB_T) {
                continue;
            }
            data2ready = true;
            break;
        }
        assign_last_raw_batch_line(nr2Last, combined2, indexes2);
        if (!data2ready) {
            isData = false;
        }
        if (nr2 > 0) {
            //copy data 2 -> device
            metalStatus = copy_to_device_grow((void**)&_devLines2, combined2.data(), combined2.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes2, indexes2.data(), indexes2.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //sync kernel 1
        if (nr1 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 1
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
            }
        }
        //launch kernel 2
        if (nr2 > 0) {
            metal_launch("workerBip32", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines2, _devIndexes2, nr2, derivation_list, _derIndex, derIndex_size, 0, BIP32_MODE, _devIter, iteration_size, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        STATUS = nr1Last;
        counter += nr2 * iteration_size;
        counterTotal += nr2 * iteration_size;

    }
    metalDeviceSynchronize();

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(_devIndexes1);
    metalFree(_devIndexes2);
    metalFree(_derIndex);
    metalFree(_devIter);
    metalFree(_devLines1);
    metalFree(_devLines2);
    metalFree(derivation_list);
    return metalStatus;
}

// processMetalBip32File: runs the Metal workflow for BIP32 file.
metalError_t processMetalBip32File(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);



        metalError_t st;

        if (use_combos)
        {


            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });


            st = processMetalBip32(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = processMetalBip32(stream);
        }


        if (st != metalSuccess) {
            std::cerr << "processMetalBip32 failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalBip32SeqBoth: runs the Metal workflow for BIP32 seq both.
metalError_t processMetalBip32SeqBoth()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBip32SeqBoth();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_mnemonic_point[512] = { 0 };
    uint8_t minus_mnemonic_point[512] = { 0 };

    init_seq_both_points(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    metalMalloc((void**)&plus_pvk_dev, 512);
    metalMalloc((void**)&minus_pvk_dev, 512);


    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t valLE[64];
    uint64_t valBE[64];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;
    bool range_active = seq_both_round_active(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();

        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_mnemonic_point, 512, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_mnemonic_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        for (size_t num = 0; num < Iterations.size(); ++num)
        {

            uint32_t ITERATION_HOST = Iterations[num];
            //+
            metal_launch("workerBip32_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, BIP32_MODE, ITERATION_HOST, Rounds);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T;
            counterTotal += outputSizeB_T;

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);


            }
            metal_launch("workerBip32_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, min_len, BIP32_MODE, ITERATION_HOST, Rounds);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T;
            counterTotal += outputSizeB_T;

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }



            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("Bip32SeqBoth_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, plus_mnemonic_point, 512, (size_t)plus_size);
                        write_hex_last(fp, minus_mnemonic_point, 512, (size_t)minus_size, true);
                    }

                    if (fp) fclose(fp);
                }
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);


            }
        }
        array512_to_64x64_le(plus_mnemonic_point, valLE);
        add64to4096_host(valLE, outputSizeB_T * step, valBE);
        array64x64_le_to512(valBE, plus_mnemonic_point);

        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array512_to_64x64_le(minus_mnemonic_point, valLE);
        sub64from4096_host(valLE, outputSizeB_T * step, valBE);
        array64x64_le_to512(valBE, minus_mnemonic_point);

        minus_size = sizeBE_64(valBE, 64);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }
        local_n += outputSizeB_T;
        range_active = seq_both_round_active(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalBip32Random: runs the Metal workflow for BIP32 random.
metalError_t processMetalBip32Random()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBip32Random();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t start_pvk_point_local[512] = { 0 };

    if (seqMode)
    {
        random_bytes_seq(start_mnemonic_point, start_mnemonic_point, start_pvk_point_local, 512);
    }
    else
    {
        random_bytes(start_pvk_point_local, 512, entropy_len);
    }


    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_mnemonic_point[512] = { 0 };
    uint8_t minus_mnemonic_point[512] = { 0 };

    memcpy(&plus_mnemonic_point[0], &start_pvk_point_local[0], 512);
    memcpy(&minus_mnemonic_point[0], &start_pvk_point_local[0], 512);

    metalMalloc((void**)&plus_pvk_dev, 512);
    metalMalloc((void**)&minus_pvk_dev, 512);


    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t valLE[64];
    uint64_t valBE[64];


    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        for (uint64_t local_n = 0; local_n <= n_number; local_n += outputSizeB_T)
        {
            metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_mnemonic_point, 512, metalMemcpyHostToDevice);
            metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_mnemonic_point, 512, metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            for (size_t num = 0; num < Iterations.size(); ++num)
            {

                uint32_t ITERATION_HOST = Iterations[num];
                //+
                metal_launch("workerBip32_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, BIP32_MODE, ITERATION_HOST, Rounds);
                metalStatus = metalGetLastError();
                counter += outputSizeB_T;
                counterTotal += outputSizeB_T;

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }

                metalStatus = metalDeviceSynchronize();
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);


                }
                metal_launch("workerBip32_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, min_len, BIP32_MODE, ITERATION_HOST, Rounds);
                metalStatus = metalGetLastError();
                counter += outputSizeB_T;
                counterTotal += outputSizeB_T;

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }

                metalStatus = metalDeviceSynchronize();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                    goto Error;
                }



                //show status
                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                if (tHash > 2500) {
                    counter = 0;
                    beginCountHashrate = std::chrono::steady_clock::now();

                }
                //check result 2
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);


                }
            }
            array512_to_64x64_le(plus_mnemonic_point, valLE);
            add64to4096_host(valLE, outputSizeB_T * step, valBE);
            array64x64_le_to512(valBE, plus_mnemonic_point);


            array512_to_64x64_le(minus_mnemonic_point, valLE);
            sub64from4096_host(valLE, outputSizeB_T * step, valBE);
            array64x64_le_to512(valBE, minus_mnemonic_point);
        }
        if (seqMode)
        {
            random_bytes_seq(start_mnemonic_point, end_mnemonic_point, start_pvk_point_local, 512);
        }
        else
        {
            random_bytes(start_pvk_point_local, 512, entropy_len);
        }
        memcpy(&plus_mnemonic_point[0], &start_pvk_point_local[0], 512);
        memcpy(&minus_mnemonic_point[0], &start_pvk_point_local[0], 512);
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBip32(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalBip32Gen: runs the Metal workflow for BIP32 gen.
metalError_t processMetalBip32Gen()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBip32Gen();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;



    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t)); // Derivations-only buffer size.
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed; seed_local <= end_seed;) {

        uint64_t remaining = end_seed - seed_local + 1;
        uint64_t seed_count = (remaining < outputSizeB_T) ? remaining : outputSizeB_T;

        current_seed = seed_local;

        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFULL);

                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];

            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        for (size_t suz = 0; suz < Sizes.size(); ++suz)
                        {
                            int custom_size = Sizes[suz];



                            for (size_t num = 0; num < Iterations.size(); ++num)
                            {

                                uint32_t ITERATION_HOST = Iterations[num];
                                std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                                metal_launch("workerBip32_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, BIP32_MODE, ITERATION_HOST, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);

                                metalStatus = metalGetLastError();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }

                                counterTotal += seed_count;




                                metalStatus = metalDeviceSynchronize();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                                    goto Error;
                                }
                                //show status
                                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                if (tHash > 2500) {
                                    counter = 0;
                                    beginCountHashrate = std::chrono::steady_clock::now();
                                }
                                //check result 2
                                if (read_result_flag_host(buffIsResult)) {
                                    clear_result_flag_host(buffIsResult);
                                    SaveResultBip32Gen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                }
                            }
                        }

                    }
                }

            }
        }
        if (isRandom)
        {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else
        {
            seed_local += seed_count;
        }

    }
Error:

    return metalStatus;
}

// processMetalBip32Gen64: runs the Metal workflow for BIP32 gen 64.
metalError_t processMetalBip32Gen64()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBip32Gen64();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;



    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t)); // Derivations-only buffer size.
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    for (uint64_t seed_local = isRandom ? random_seed64_inclusive(start_seed64, end_seed64) : start_seed64; seed_local <= end_seed64;) {

        uint64_t remaining = end_seed64 - seed_local;
        uint64_t seed_count = (remaining < outputSizeB_T) ? (remaining + 1ull) : outputSizeB_T;

        current_seed = seed_local;

        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";


                ofs << std::hex << std::setw(16) << std::setfill('0') << seed_local << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev64", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(true, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        for (size_t suz = 0; suz < Sizes.size(); ++suz)
                        {
                            int custom_size = Sizes[suz];



                            for (size_t num = 0; num < Iterations.size(); ++num)
                            {

                                uint32_t ITERATION_HOST = Iterations[num];
                                std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                                metal_launch("workerBip32_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, BIP32_MODE, ITERATION_HOST, seed_local, seed_count, true, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);

                                metalStatus = metalGetLastError();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }

                                counterTotal += seed_count;




                                metalStatus = metalDeviceSynchronize();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                                    goto Error;
                                }
                                //show status
                                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                if (tHash > 2500) {
                                    counter = 0;
                                    beginCountHashrate = std::chrono::steady_clock::now();
                                }
                                //check result 2
                                if (read_result_flag_host(buffIsResult)) {
                                    clear_result_flag_host(buffIsResult);
                                    SaveResultBip32Gen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                }
                            }
                        }

                    }
                }

            }
        }
        if (isRandom)
        {
            seed_local = random_seed64_inclusive(start_seed64, end_seed64);
        }
        else
        {
            if (seed_local > (std::numeric_limits<uint64_t>::max() - seed_count)) {
                break;
            }
            seed_local += seed_count;
        }

    }
Error:

    return metalStatus;
}

//Seed modes

metalError_t processMetalSeed(std::istream& stream)
{
    if (der_thread_mode) return processMetalDerThread(1, stream);
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalSeed(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 128);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 128);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";

    uint32_t* _devIndexes1 = nullptr;
    uint32_t* _devIndexes2 = nullptr;
    uint32_t* _derIndex = nullptr;
    char* _devLines1 = nullptr;
    char* _devLines2 = nullptr;
    uint32_t* derivation_list = nullptr;

    metalStatus = metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _derIndex failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc derivation_list failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Derivations.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy derIndex.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            counterTotal++;
            /*if (buffer.length() == 0) {
                buffer = '\n';
            }*/
            combined1.append(buffer.data(), buffer.size());
            indexes1.emplace_back(combined1.size());
            nr1++;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        assign_last_raw_batch_line(nr1Last, combined1, indexes1);
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes1, indexes1.data(), indexes1.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
        }

        //sync kernel 2
        if (nr2 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
            }
        }

        //launch kernel 1
        if (nr1 > 0) {
            metal_launch("workerSeed", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines1, _devIndexes1, nr1, derivation_list, _derIndex, derIndex_size, 0, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }

        STATUS = nr2Last;
        counter += nr1;

        //read file 1
        combined2.clear();
        indexes2.clear();
        nr2 = 0;
        data2ready = false;
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            counterTotal++;
            /*if (buffer.length() == 0) {
                buffer = '\n';
            }*/

            combined2.append(buffer.data(), buffer.size());
            indexes2.emplace_back(combined2.size());
            nr2++;
            if (nr2 < outputSizeB_T) {
                continue;
            }
            data2ready = true;
            break;
        }
        assign_last_raw_batch_line(nr2Last, combined2, indexes2);
        if (!data2ready) {
            isData = false;
        }
        if (nr2 > 0) {
            //copy data 2 -> device
            metalStatus = copy_to_device_grow((void**)&_devLines2, combined2.data(), combined2.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes2, indexes2.data(), indexes2.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //sync kernel 1
        if (nr1 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 1
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
            }
        }
        //launch kernel 2
        if (nr2 > 0) {
            metal_launch("workerSeed", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, _devLines2, _devIndexes2, nr2, derivation_list, _derIndex, derIndex_size, 0, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        STATUS = nr1Last;
        counter += nr2;

    }
    metalDeviceSynchronize();

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(_devIndexes1);
    metalFree(_devIndexes2);
    metalFree(_derIndex);
    metalFree(_devLines1);
    metalFree(_devLines2);
    metalFree(derivation_list);
    return metalStatus;
}

// processMetalSeedFile: runs the Metal workflow for seed file.
metalError_t processMetalSeedFile(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);



        metalError_t st;

        if (use_combos)
        {


            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });


            st = processMetalSeed(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = processMetalSeed(stream);
        }


        if (st != metalSuccess) {
            std::cerr << "processMetalSeed failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalSeedSeq: runs the Metal workflow for seed seq.
metalError_t processMetalSeedSeq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalSeedSeq();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;


    metalMalloc((void**)&start_pvk_dev, 64);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);


    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp_host(start_seed_point, end_seed_point, 64);
        if (result > 0)
        {
            break;
        }
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_seed_point, 64, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metal_launch("workerSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, start_pvk_dev, min_len, Rounds);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();

            {
                FILE* fp = open_runtime_log("SeedSeq_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, start_seed_point, 64, (size_t)64);
                }

                if (fp) fclose(fp);
            }
        }

        //check result 2
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);

        }


        uint64_t valLE[8];
        uint64_t valBE[8];

        array64_to_8x64_le(start_seed_point, valLE);

        add64to512_host(valLE, outputSizeB_T * step, valBE);

        array8x64_le_to64(valBE, start_seed_point);

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

