// processMetalSeedSeqBoth: runs the Metal workflow for seed seq both.
metalError_t processMetalSeedSeqBoth()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalSeedSeqBoth();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_seed_point[64] = { 0 };
    uint8_t minus_seed_point[64] = { 0 };

    init_seq_both_points(plus_seed_point, minus_seed_point, start_seed_point, end_seed_point, 64);

    metalMalloc((void**)&plus_pvk_dev, 64);
    metalMalloc((void**)&minus_pvk_dev, 64);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);


    uint64_t valLE[8];
    uint64_t valBE[8];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;
    bool range_active = seq_both_round_active(plus_seed_point, minus_seed_point, start_seed_point, end_seed_point, 64);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_seed_point, 64, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_seed_point, 64, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        //+
        metal_launch("workerSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, min_len, Rounds);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metalStatus = metalDeviceSynchronize();
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
        }
        metal_launch("workerSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, min_len, Rounds);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }

        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();

            {
                FILE* fp = open_runtime_log("SeedSeqBoth_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, plus_seed_point, 64, (size_t)plus_size);
                    write_hex_last(fp, minus_seed_point, 64, (size_t)minus_size, true);
                }

                if (fp) fclose(fp);
            }
        }
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
        }

        array64_to_8x64_le(plus_seed_point, valLE);
        add64to512_host(valLE, outputSizeB_T * step, valBE);
        array8x64_le_to64(valBE, plus_seed_point);

        plus_size = sizeBE_64(valBE, 8);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array64_to_8x64_le(minus_seed_point, valLE);
        sub64from512_host(valLE, outputSizeB_T * step, valBE);
        array8x64_le_to64(valBE, minus_seed_point);

        minus_size = sizeBE_64(valBE, 8);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }

        local_n += outputSizeB_T;
        range_active = seq_both_round_active(plus_seed_point, minus_seed_point, start_seed_point, end_seed_point, 64);
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultSeed(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalSeedRandom: runs the Metal workflow for seed random.
metalError_t processMetalSeedRandom()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalSeedRandom();
