// processMetalHmacSeqBoth: runs the Metal workflow for HMAC seq both.
metalError_t processMetalHmacSeqBoth()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalHmacSeqBoth();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_seed_point[64] = { 0 };
    uint8_t minus_seed_point[64] = { 0 };

    init_seq_both_points(plus_seed_point, minus_seed_point, start_seed_point, end_seed_point, 64);

    metalMalloc((void**)&plus_pvk_dev, 64);
    metalMalloc((void**)&minus_pvk_dev, 64);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t valLE[8];
    uint64_t valBE[8];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;
    bool range_active = seq_both_round_active(plus_seed_point, minus_seed_point, start_seed_point, end_seed_point, 64);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        local_n += outputSizeB_T;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_seed_point, 64, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_seed_point, 64, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        //+
        metal_launch("workerHmac_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, Rounds);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metalStatus = metalDeviceSynchronize();

        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultHmac(OUT_FILE, Founds, save, Derivations_list);

        }
        metal_launch("workerHmac_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, Rounds);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }



        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();

            {
                FILE* fp = open_runtime_log("HmacSeqBoth_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, plus_seed_point, 64, (size_t)plus_size);
                    write_hex_last(fp, minus_seed_point, 64, (size_t)minus_size, true);
                }

                if (fp) fclose(fp);
            }
        }

        //check result 2
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultHmac(OUT_FILE, Founds, save, Derivations_list);

        }

        array64_to_8x64_le(plus_seed_point, valLE);
        add64to512_host(valLE, outputSizeB_T * step, valBE);
        array8x64_le_to64(valBE, plus_seed_point);

        plus_size = sizeBE_64(valBE, 8);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array64_to_8x64_le(minus_seed_point, valLE);
        sub64from512_host(valLE, outputSizeB_T * step, valBE);
        array8x64_le_to64(valBE, minus_seed_point);

        minus_size = sizeBE_64(valBE, 8);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }
        range_active = seq_both_round_active(plus_seed_point, minus_seed_point, start_seed_point, end_seed_point, 64);

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultHmac(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalHmacRandom: runs the Metal workflow for HMAC random.
metalError_t processMetalHmacRandom()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalHmacRandom();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t start_pvk_point_local[64] = { 0 };

    if (seqMode)
    {
        random_bytes_seq(start_seed_point, end_seed_point, start_pvk_point_local, 64);
    }
    else
    {
        random_bytes(start_pvk_point_local, 64, entropy_len);
    }


    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_seed_point[64] = { 0 };
    uint8_t minus_seed_point[64] = { 0 };

    memcpy(&plus_seed_point[0], &start_pvk_point_local[0], 64);
    memcpy(&minus_seed_point[0], &start_pvk_point_local[0], 64);

    metalMalloc((void**)&plus_pvk_dev, 64);
    metalMalloc((void**)&minus_pvk_dev, 64);

    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;


    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t));

    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);

    uint64_t valLE[8];
    uint64_t valBE[8];



    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        for (uint64_t local_n = 0; local_n <= n_number; local_n += outputSizeB_T)
        {


            metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_seed_point, 64, metalMemcpyHostToDevice);
            metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_seed_point, 64, metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            //+
            metal_launch("workerHmac_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 1, plus_pvk_dev, Rounds);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T;
            counterTotal += outputSizeB_T;

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }


            metal_launch("workerHmac_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, 0, minus_pvk_dev, Rounds);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T;
            counterTotal += outputSizeB_T;

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }


            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }



            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

            }

            // check result after both (+/-) launches in this chunk
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultHmac(OUT_FILE, Founds, save, Derivations_list);

            }

            array64_to_8x64_le(plus_seed_point, valLE);
            add64to512_host(valLE, outputSizeB_T * step, valBE);
            array8x64_le_to64(valBE, plus_seed_point);


            array64_to_8x64_le(minus_seed_point, valLE);
            add64to512_host(valLE, outputSizeB_T * step, valBE);
            array8x64_le_to64(valBE, minus_seed_point);

        }

        if (seqMode)
        {
            random_bytes_seq(start_seed_point, end_seed_point, start_pvk_point_local, 64);
        }
        else
        {
            random_bytes(start_pvk_point_local, 64, entropy_len);
        }
        memcpy(&plus_seed_point[0], &start_pvk_point_local[0], 64);
        memcpy(&minus_seed_point[0], &start_pvk_point_local[0], 64);




    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultHmac(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalHmacGen: runs the Metal workflow for HMAC gen.
metalError_t processMetalHmacGen()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalHmacGen();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;



    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    // Allocate derivation list buffer on device.
    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t)); // Derivations-only buffer size.
    // Copy derivation list from host to device.
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed; seed_local <= end_seed;) {

        uint64_t remaining = end_seed - seed_local + 1;
        uint64_t seed_count = (remaining < outputSizeB_T) ? remaining : outputSizeB_T;


        current_seed = seed_local;

        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFULL);

                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];

            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];

                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;



                        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                        metal_launch("workerHmac_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }


                        counterTotal += seed_count;




                        metalStatus = metalDeviceSynchronize();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                            goto Error;
                        }
                        //show status
                        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                        if (tHash > 2500) {
                            counter = 0;
                            beginCountHashrate = std::chrono::steady_clock::now();
                        }
                        //check result 2
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResultHmacGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                        }
                    }
                }
            }

        }
        if (isRandom)
        {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else
        {
            seed_local += seed_count;
        }

    }
Error:

    return metalStatus;
}

// processMetalHmacGen64: runs the Metal workflow for HMAC gen 64.
metalError_t processMetalHmacGen64()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalHmacGen64();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;



    uint32_t* _derIndex;

    metalMalloc((void**)&_derIndex, derIndex.size() * sizeof(uint32_t));


    uint32_t* derivation_list;

    // Allocate derivation list buffer on device.
    metalError_t err = metalMalloc((void**)&derivation_list, Derivations.size() * sizeof(uint32_t)); // Derivations-only buffer size.
    // Copy derivation list from host to device.
    err = metalMemcpy(derivation_list, Derivations.data(), Derivations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    err = metalMemcpy(_derIndex, derIndex.data(), derIndex.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    for (uint64_t seed_local = isRandom ? random_seed64_inclusive(start_seed64, end_seed64) : start_seed64; seed_local <= end_seed64;) {

        uint64_t remaining = end_seed64 - seed_local;
        uint64_t seed_count = (remaining < outputSizeB_T) ? (remaining + 1ull) : outputSizeB_T;


        current_seed = seed_local;

        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                ofs << std::hex << std::setw(16) << std::setfill('0') << seed_local << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];

            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev64", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];

                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(true, gen_h, mode_h)) continue;
                        current_mode = mode_h;



                        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                        metal_launch("workerHmac_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, _derIndex, derIndex_size, 0, seed_local, seed_count, true, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }


                        counterTotal += seed_count;




                        metalStatus = metalDeviceSynchronize();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                            goto Error;
                        }
                        //show status
                        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                        if (tHash > 2500) {
                            counter = 0;
                            beginCountHashrate = std::chrono::steady_clock::now();
                        }
                        //check result 2
                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResultHmacGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                        }
                    }
                }
            }

        }
        if (isRandom)
        {
            seed_local = random_seed64_inclusive(start_seed64, end_seed64);
        }
        else
        {
            if (seed_local > (std::numeric_limits<uint64_t>::max() - seed_count)) {
                break;
            }
            seed_local += seed_count;
        }

    }
Error:

    return metalStatus;
}

//Private keys modes

metalError_t processMetalPRIV(std::istream& stream)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalPRIV(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);
    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 64);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 64);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t* _devIndexes1;
    uint32_t* _devIndexes2;
    char* _devLines1;
    char* _devLines2;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";

    _devIndexes1 = nullptr;
    _devIndexes2 = nullptr;
    _devLines1 = nullptr;
    _devLines2 = nullptr;


    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            if (buffer.length() == 0) {
                continue;
            }
            if (!append_normalized_priv_line(buffer, combined1, indexes1, nr1, IS_HEX)) {
                continue;
            }
            nr1Last = buffer;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes1, indexes1.data(), indexes1.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
        }

        //sync kernel 2
        if (nr2 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
            }
        }
        //launch kernel 1
        if (nr1 > 0) {
            metal_launch("workerPRIV", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _devLines1, _devIndexes1, nr1, _dev_precomp, pitch, true_priv_mode, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }

        STATUS = nr1Last;
        counter += nr1 * ((Rounds *2)+ 1);
        counterTotal += nr1 * ((Rounds *2)+ 1);
        //read file 1
        combined2.clear();
        indexes2.clear();
        nr2 = 0;
        data2ready = false;
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            if (buffer.length() == 0) {
                continue;
            }
            if (!append_normalized_priv_line(buffer, combined2, indexes2, nr2, IS_HEX)) {
                continue;
            }
            nr2Last = buffer;
            if (nr2 < outputSizeB_T) {
                continue;
            }
            data2ready = true;
            break;
        }
        if (!data2ready) {
            isData = false;
        }
        if (nr2 > 0) {
            //copy data 2 -> device
            metalStatus = copy_to_device_grow((void**)&_devLines2, combined2.data(), combined2.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes2, indexes2.data(), indexes2.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //sync kernel 1
        if (nr1 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 1
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
            }
        }
        //launch kernel 2
        if (nr2 > 0) {
            metal_launch("workerPRIV", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _devLines2, _devIndexes2, nr2, _dev_precomp, pitch, true_priv_mode, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        STATUS = nr2Last;
        counter += nr2 * ((Rounds *2)+ 1);
        counterTotal += nr2 * ((Rounds *2)+ 1);
    }
    metalDeviceSynchronize();
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(_devIndexes1);
    metalFree(_devIndexes2);
    metalFree(_devLines1);
    metalFree(_devLines2);
    return metalStatus;
}

// processMetalPRIVPATTERN_gpu_slot: executes -priv 6 pattern workflow for one GPU slot.
static metalError_t processMetalPRIVPATTERN_gpu_slot(const size_t gpu_slot, const size_t gpu_count)
{
    metalError_t metalStatus = metalSuccess;

    const uint64_t thread_count = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (thread_count == 0) {
        return metalErrorInvalidConfiguration;
    }

    const uint64_t variants_per_base = priv_pattern_last_cycle
        ? static_cast<uint64_t>((THREAD_STEPS < 16) ? THREAD_STEPS : 16)
        : 1ull;
    uint64_t bases_per_thread = static_cast<uint64_t>(THREAD_STEPS) / variants_per_base;
    if (bases_per_thread == 0) {
        bases_per_thread = 1;
    }
    const uint64_t launch_bases = thread_count * bases_per_thread;
    if (launch_bases == 0) {
        return metalErrorInvalidConfiguration;
    }

    if (gpu_count == 0u) {
        return metalErrorInvalidConfiguration;
    }
    if (launch_bases > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(gpu_count))) {
        fprintf(stderr, "[!] Error: internal launch delta overflow in -priv 6 pattern mode [!]\n");
        return metalErrorInvalidValue;
    }
    const uint64_t launch_delta = launch_bases * static_cast<uint64_t>(gpu_count);

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(thread_count, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    uint8_t* d_pattern_start = nullptr;
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_pattern_start), 64u);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_pattern_start failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }

    const uint64_t iter_mul = (Rounds * 2ull) + 1ull;
    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();

    for (size_t len_idx = 0; len_idx < priv_pattern_lengths.size() && isRun; ++len_idx) {
        const int pattern_len_i = priv_pattern_lengths[len_idx];
        if (pattern_len_i <= 0 || pattern_len_i > 64) {
            continue;
        }
        const uint8_t pattern_len = static_cast<uint8_t>(pattern_len_i);

        std::vector<uint8_t> counter_nibbles(static_cast<size_t>(pattern_len), 0u);
        if (!add_hex_counter_inplace(counter_nibbles, static_cast<uint64_t>(gpu_slot))) {
            continue;
        }

        while (isRun) {
            metalStatus = metalMemcpyAsync(d_pattern_start, counter_nibbles.data(), counter_nibbles.size(), metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy d_pattern_start failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metal_launch("workerPRIV_pattern", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_pattern_start, pattern_len, static_cast<uint64_t>(gpu_count), priv_pattern_last_cycle, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "workerPRIV_pattern launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after workerPRIV_pattern launch!\n", metalStatus);
                goto Error;
            }

            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
            }

            STATUS = hex_string_from_nibbles(counter_nibbles);

            counterTotal += launch_bases * iter_mul * variants_per_base;

            const long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {

                beginCountHashrate = std::chrono::steady_clock::now();
            }

            if (!add_hex_counter_inplace(counter_nibbles, launch_delta)) {
                break;
            }
        }
    }

    metalStatus = metalDeviceSynchronize();
    if (metalStatus != metalSuccess) {
        goto Error;
    }
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
    }

Error:
    metalFree(d_pattern_start);
    return metalStatus;
}

// processMetalPRIVPATTERN: executes -priv 6 pattern mode on active GPU(s).
metalError_t processMetalPRIVPATTERN()
{
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return processMetalPRIVPATTERN_gpu_slot(0u, 1u);
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    workers.reserve(gpu_count);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            restore_thread_input_snapshot(base_snapshot);
            g_disable_multi_gpu_dispatch = true;
            statuses[gpu_idx] = processMetalPRIVPATTERN_gpu_slot(gpu_idx, gpu_count);
            g_disable_multi_gpu_dispatch = false;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) {
            th.join();
        }
    }

    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    metalError_t first_error = metalSuccess;
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            first_error = statuses[gpu_idx];
            fprintf(stderr, "[!] mode %s failed on GPU %d: %s [!]\n",
                __func__,
                g_gpu_contexts[gpu_idx].device_id,
                metalGetErrorString(statuses[gpu_idx]));
            break;
        }
    }
    return first_error;
}

// processMetalPRIVPATTERNRun: validates args and runs -priv 6 pattern mode.
metalError_t processMetalPRIVPATTERNRun()
{
    if (!priv_pattern_range_set || priv_pattern_lengths.empty()) {
        fprintf(stderr, "[!] Error: -priv 6 pattern lengths are not set. Use -pb list/range (example: 1,2,3-6) [!]\n");
        return metalErrorInvalidValue;
    }
    return processMetalPRIVPATTERN();
}

template <typename Fn>
// dispatch_hexset_mode_multi_gpu: dispatches -hexset mode across all active GPUs.
static metalError_t dispatch_hexset_mode_multi_gpu(const char* mode_name, Fn&& worker_fn) {
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return worker_fn(0u, 1u);
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    workers.reserve(gpu_count);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            restore_thread_input_snapshot(base_snapshot);
            g_disable_multi_gpu_dispatch = true;
            statuses[gpu_idx] = worker_fn(gpu_idx, gpu_count);
            g_disable_multi_gpu_dispatch = false;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) {
            th.join();
        }
    }

    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    metalError_t first_error = metalSuccess;
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            first_error = statuses[gpu_idx];
            fprintf(stderr, "[!] mode %s failed on GPU %d: %s [!]\n",
                mode_name,
                g_gpu_contexts[gpu_idx].device_id,
                metalGetErrorString(statuses[gpu_idx]));
            break;
        }
    }
    return first_error;
}

// init_u32_device_buffer: allocates and copies uint32 buffer to the current GPU.
static inline metalError_t init_u32_device_buffer(const std::vector<uint32_t>& src, uint32_t*& dst) {
    dst = nullptr;
    if (src.empty()) {
        return metalSuccess;
    }
    metalError_t st = metalMalloc(reinterpret_cast<void**>(&dst), src.size() * sizeof(uint32_t));
    if (st != metalSuccess) {
        return st;
    }
    st = metalMemcpyAsync(dst, src.data(), src.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (st != metalSuccess) {
        metalFree(dst);
        dst = nullptr;
    }
    return st;
}

// init_derivation_device_buffers: uploads derivation list and index to the current GPU.
static inline metalError_t init_derivation_device_buffers(uint32_t*& derivation_list, uint32_t*& der_index_dev) {
    derivation_list = nullptr;
    der_index_dev = nullptr;
    metalError_t st = init_u32_device_buffer(Derivations, derivation_list);
    if (st != metalSuccess) {
        return st;
    }
    st = init_u32_device_buffer(derIndex, der_index_dev);
    if (st != metalSuccess) {
        if (derivation_list) metalFree(derivation_list);
        derivation_list = nullptr;
        return st;
    }
    return metalSuccess;
}

// init_iteration_device_buffer: uploads iteration list to the current GPU.
static inline metalError_t init_iteration_device_buffer(uint32_t*& dev_iter, uint32_t& iter_count) {
    iter_count = static_cast<uint32_t>(Iterations.size());
    return init_u32_device_buffer(Iterations, dev_iter);
}

template <typename SaveFn>
// flush_hexset_result_if_any: flushes staged save data if the kernel reported a match.
static inline void flush_hexset_result_if_any(bool* buffIsResult, SaveFn&& save_fn) {
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        save_fn();
    }
}

template <typename LaunchFn, typename SaveFn>
// run_hexset_mode_gpu_slot: common host loop for one GPU slot in -hexset mode.
static metalError_t run_hexset_mode_gpu_slot(
    const size_t gpu_slot,
    const size_t gpu_count,
    const uint64_t output_entries,
    const uint64_t launch_candidates,
    const uint64_t tested_per_launch_unit,
    const size_t max_bytes,
    const char* log_path,
    LaunchFn&& launch_fn,
    SaveFn&& save_fn) {

    if (gpu_count == 0u || launch_candidates == 0ull || max_bytes == 0u) {
        return metalErrorInvalidConfiguration;
    }
    if (hexset_digits.empty() || hexset_start_bound_nibbles.empty()) {
        return metalErrorInvalidValue;
    }
    if (launch_candidates > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(gpu_count))) {
        fprintf(stderr, "[!] Error: -hexset launch delta overflow [!]\n");
        return metalErrorInvalidValue;
    }

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalError_t metalStatus = acquire_shared_result_buffers(output_entries, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    const uint32_t hexset_base = static_cast<uint32_t>(hexset_digits.size());
    const uint64_t launch_delta = launch_candidates * static_cast<uint64_t>(gpu_count);
    uint8_t* d_hexset_start_digits = nullptr;
    uint8_t* d_hexset_alphabet = nullptr;
    uint8_t* d_hexset_lower_exact = nullptr;
    uint8_t* d_hexset_upper_exact = nullptr;
    auto cleanup_and_return = [&](metalError_t status) -> metalError_t {
        if (d_hexset_start_digits) metalFree(d_hexset_start_digits);
        if (d_hexset_alphabet) metalFree(d_hexset_alphabet);
        if (d_hexset_lower_exact) metalFree(d_hexset_lower_exact);
        if (d_hexset_upper_exact) metalFree(d_hexset_upper_exact);
        return status;
    };
    metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&d_hexset_alphabet), hexset_digits.data(), hexset_digits.size());
    if (metalStatus != metalSuccess) {
        return cleanup_and_return(metalStatus);
    }

    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    int min_size = 0;
    int max_size_for_mode = 0;
    if (!hexset_size_config_for_current_mode(min_size, max_size_for_mode)) {
        return cleanup_and_return(metalErrorInvalidValue);
    }
    int start_len_bytes = static_cast<int>(hexset_start_bound_nibbles.size() / 2u);
    int end_len_bytes = hexset_effective_end_len_for_current_mode();
    if (start_len_bytes < min_size || static_cast<size_t>(start_len_bytes) > max_bytes || end_len_bytes < start_len_bytes) {
        return cleanup_and_return(metalErrorInvalidValue);
    }
    if (end_len_bytes > max_size_for_mode) {
        end_len_bytes = max_size_for_mode;
    }
    if (static_cast<size_t>(end_len_bytes) > max_bytes) {
        end_len_bytes = static_cast<int>(max_bytes);
    }

    for (int current_size_i = start_len_bytes; current_size_i <= end_len_bytes && isRun; ++current_size_i) {
        const uint32_t current_size = static_cast<uint32_t>(current_size_i);
        std::vector<uint8_t> lower_nibbles;
        std::vector<uint8_t> upper_nibbles;
        build_hexset_numeric_bounds_for_length(current_size_i, start_len_bytes, end_len_bytes, lower_nibbles, upper_nibbles);

        std::vector<uint8_t> first_counter_digits;
        std::vector<uint8_t> last_counter_digits;
        if (!find_first_hexset_counter_ge_bound(lower_nibbles, hexset_digits, first_counter_digits)) {
            continue;
        }
        if (!find_last_hexset_counter_le_bound(upper_nibbles, hexset_digits, last_counter_digits)) {
            continue;
        }
        if (compare_hexset_counter_digits(first_counter_digits, last_counter_digits) > 0) {
            continue;
        }

        std::vector<uint8_t> lower_exact;
        std::vector<uint8_t> upper_exact;
        nibble_vector_to_bytes(lower_nibbles, lower_exact);
        nibble_vector_to_bytes(upper_nibbles, upper_exact);
        metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&d_hexset_lower_exact), lower_exact.data(), lower_exact.size());
        if (metalStatus != metalSuccess) {
            return cleanup_and_return(metalStatus);
        }
        metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&d_hexset_upper_exact), upper_exact.data(), upper_exact.size());
        if (metalStatus != metalSuccess) {
            return cleanup_and_return(metalStatus);
        }

        std::vector<uint8_t> counter_digits = first_counter_digits;
        if (gpu_slot != 0u && !add_baseN_counter_inplace(counter_digits, hexset_base, static_cast<uint64_t>(gpu_slot))) {
            continue;
        }
        if (compare_hexset_counter_digits(counter_digits, last_counter_digits) > 0) {
            continue;
        }

        while (isRun) {
            if (compare_hexset_counter_digits(counter_digits, last_counter_digits) > 0) {
                break;
            }
            metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&d_hexset_start_digits), counter_digits.data(), counter_digits.size());
            if (metalStatus != metalSuccess) {
                return cleanup_and_return(metalStatus);
            }

            uint64_t launches_issued = 0ull;
            metalStatus = launch_fn(
                buffIsResult,
                buffDeviceResult,
                d_hexset_start_digits,
                d_hexset_lower_exact,
                d_hexset_upper_exact,
                d_hexset_alphabet,
                current_size,
                static_cast<uint32_t>(counter_digits.size()),
                launches_issued);
            if (metalStatus != metalSuccess) {
                return cleanup_and_return(metalStatus);
            }

            STATUS = materialize_hexset_counter_to_hex(counter_digits, hexset_digits);
            if (launches_issued > 0ull) {
                if (tested_per_launch_unit > 0ull && launches_issued > (std::numeric_limits<uint64_t>::max() / tested_per_launch_unit)) {
                    return cleanup_and_return(metalErrorInvalidValue);
                }
                counterTotal += tested_per_launch_unit * launches_issued;
            }

            const long long tStatus = std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::steady_clock::now() - beginCountStatus).count();
            if (tStatus > 2500) {
                write_text_log_snapshot(log_path, STATUS);
                beginCountStatus = std::chrono::steady_clock::now();
            }

            if (!add_baseN_counter_inplace(counter_digits, hexset_base, launch_delta)) {
                break;
            }
        }
    }

    flush_hexset_result_if_any(buffIsResult, save_fn);
    return cleanup_and_return(metalStatus);
}

template <typename LaunchFn, typename SaveFn>
// run_recovery_hexset_mode_gpu_slot: common host loop for mode-scoped -recovery + -hexset.
static metalError_t run_recovery_hexset_mode_gpu_slot(
    const size_t gpu_slot,
    const size_t gpu_count,
    const uint64_t output_entries,
    const uint64_t launch_candidates,
    const uint64_t tested_per_launch_unit,
    const size_t max_bytes,
    const char* log_path,
    LaunchFn&& launch_fn,
    SaveFn&& save_fn) {

    if (gpu_count == 0u || launch_candidates == 0ull || max_bytes == 0u) {
        return metalErrorInvalidConfiguration;
    }
    if (hexset_digits.empty() || recovery_hex_template_nibbles.empty()) {
        return metalErrorInvalidValue;
    }
    if ((recovery_hex_template_nibbles.size() & 1u) != 0u || (recovery_hex_template_nibbles.size() / 2u) > max_bytes) {
        return metalErrorInvalidValue;
    }
    if (launch_candidates > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(gpu_count))) {
        fprintf(stderr, "[!] Error: recovery hexset launch delta overflow [!]\n");
        return metalErrorInvalidValue;
    }

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalError_t metalStatus = acquire_shared_result_buffers(output_entries, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    const uint32_t hexset_base = static_cast<uint32_t>(hexset_digits.size());
    const uint64_t launch_delta = launch_candidates * static_cast<uint64_t>(gpu_count);
    uint64_t domain_count = 1ull;
    bool domain_count_exact = true;
    for (uint32_t i = 0u; i < recovery_hex_wildcards; ++i) {
        if (domain_count > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(hexset_base))) {
            domain_count_exact = false;
            break;
        }
        domain_count *= static_cast<uint64_t>(hexset_base);
    }
    uint64_t current_linear = static_cast<uint64_t>(gpu_slot);
    const uint64_t tested_per_candidate =
        (launch_candidates != 0ull && (tested_per_launch_unit % launch_candidates) == 0ull)
        ? (tested_per_launch_unit / launch_candidates)
        : 1ull;
    uint8_t* d_recovery_template_and_counter = nullptr;
    uint8_t* d_hexset_alphabet = nullptr;
    auto cleanup_and_return = [&](metalError_t status) -> metalError_t {
        if (d_recovery_template_and_counter) metalFree(d_recovery_template_and_counter);
        if (d_hexset_alphabet) metalFree(d_hexset_alphabet);
        return status;
    };

    metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&d_hexset_alphabet), hexset_digits.data(), hexset_digits.size());
    if (metalStatus != metalSuccess) {
        return cleanup_and_return(metalStatus);
    }

    std::vector<uint8_t> counter_digits(recovery_hex_template_nibbles.size(), 0u);
    if (gpu_slot != 0u && !add_recovery_hexset_counter_inplace(counter_digits, recovery_hex_template_nibbles, hexset_base, static_cast<uint64_t>(gpu_slot))) {
        return cleanup_and_return(metalSuccess);
    }
    if (domain_count_exact && current_linear >= domain_count) {
        return cleanup_and_return(metalSuccess);
    }

    const uint32_t current_size = static_cast<uint32_t>(recovery_hex_template_nibbles.size() / 2u);
    const uint32_t digit_count = static_cast<uint32_t>(recovery_hex_template_nibbles.size());
    std::vector<uint8_t> encoded;
    encoded.resize(recovery_hex_template_nibbles.size() * 2u);
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();

    while (isRun) {
        uint64_t effective_launch_candidates = launch_candidates;
        if (domain_count_exact) {
            if (current_linear >= domain_count) {
                break;
            }
            const uint64_t remaining_for_gpu =
                ((domain_count - 1ull - current_linear) / static_cast<uint64_t>(gpu_count)) + 1ull;
            if (remaining_for_gpu == 0ull) {
                break;
            }
            if (effective_launch_candidates > remaining_for_gpu) {
                effective_launch_candidates = remaining_for_gpu;
            }
        }

        memcpy(encoded.data(), recovery_hex_template_nibbles.data(), recovery_hex_template_nibbles.size());
        memcpy(encoded.data() + recovery_hex_template_nibbles.size(), counter_digits.data(), counter_digits.size());
        metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&d_recovery_template_and_counter), encoded.data(), encoded.size());
        if (metalStatus != metalSuccess) {
            return cleanup_and_return(metalStatus);
        }

        uint64_t launches_issued = 0ull;
        metalStatus = launch_fn(
            buffIsResult,
            buffDeviceResult,
            d_recovery_template_and_counter,
            nullptr,
            nullptr,
            d_hexset_alphabet,
            current_size,
            digit_count,
            launches_issued);
        if (metalStatus != metalSuccess) {
            return cleanup_and_return(metalStatus);
        }

        STATUS = materialize_recovery_hexset_counter_to_hex(recovery_hex_template_nibbles, counter_digits, hexset_digits);
        if (launches_issued > 0ull && effective_launch_candidates > 0ull) {
            if (tested_per_candidate > 0ull && effective_launch_candidates > (std::numeric_limits<uint64_t>::max() / tested_per_candidate)) {
                return cleanup_and_return(metalErrorInvalidValue);
            }
            counterTotal += tested_per_candidate * effective_launch_candidates;
        }

        const long long tStatus = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - beginCountStatus).count();
        if (tStatus > 2500) {
            write_text_log_snapshot(log_path, STATUS);
            beginCountStatus = std::chrono::steady_clock::now();
        }

        if (domain_count_exact && effective_launch_candidates < launch_candidates) {
            break;
        }
        if (domain_count_exact) {
            if (effective_launch_candidates > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(gpu_count))) {
                return cleanup_and_return(metalErrorInvalidValue);
            }
            current_linear += effective_launch_candidates * static_cast<uint64_t>(gpu_count);
        }
        if (!add_recovery_hexset_counter_inplace(counter_digits, recovery_hex_template_nibbles, hexset_base, launch_delta)) {
            break;
        }
    }

    flush_hexset_result_if_any(buffIsResult, save_fn);
    return cleanup_and_return(metalStatus);
}

static metalError_t processMetalSeedHexsetSeq_gpu_slot(const size_t gpu_slot, const size_t gpu_count) {
    metalError_t metalStatus = metalSuccess;
    uint32_t* derivation_list = nullptr;
