static metalError_t processMetalHexsetSeq_gpu_slot(const size_t gpu_slot, const size_t gpu_count) {
    metalError_t metalStatus = metalSuccess;
    uint32_t* derivation_list = nullptr;
    uint32_t* der_index_dev = nullptr;
    uint32_t* dev_iter = nullptr;
    uint32_t iteration_size = 0u;
    metalStatus = init_derivation_device_buffers(derivation_list, der_index_dev);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }
    metalStatus = init_iteration_device_buffer(dev_iter, iteration_size);
    if (metalStatus != metalSuccess) {
        if (derivation_list) metalFree(derivation_list);
        if (der_index_dev) metalFree(der_index_dev);
        return metalStatus;
    }

    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    const uint32_t hexset_base = static_cast<uint32_t>(hexset_digits.size());
    auto save_fn = [&]() {
        SaveResultByte(OUT_FILE, Founds, save, Derivations_list);
    };

    metalStatus = run_hexset_mode_gpu_slot(
        gpu_slot, gpu_count,
        output_threads,
        output_threads,
        output_threads,
        512u,
        "MnemonicHexsetSeq_log.txt",
        [&](bool* buffIsResult, bool* buffDeviceResult, const uint8_t* d_start_digits, const uint8_t* d_lower_exact, const uint8_t* d_upper_exact, const uint8_t* d_alphabet, uint32_t current_size, uint32_t, uint64_t& launches_issued) -> metalError_t {
            launches_issued = 0ull;
            auto run_one = [&](uint32_t pass_len) -> metalError_t {
                metal_launch("worker_seq_hexset", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, derivation_list, der_index_dev, derIndex_size, 0, d_start_digits, d_lower_exact, d_upper_exact, d_alphabet, hexset_base, current_size, static_cast<uint64_t>(gpu_count), passwords_dev, pass_len, 0, Rounds, MNEMONIC_MODE, dev_iter, iteration_size, IS_STRING, dub_mnem);
                metalError_t st = metalGetLastError();
                if (st != metalSuccess) {
                    return st;
                }
                st = metalDeviceSynchronize();
                if (st != metalSuccess) {
                    return st;
                }
                ++launches_issued;
                flush_hexset_result_if_any(buffIsResult, save_fn);
                return metalSuccess;
            };

            if (pass_set) {
                for (size_t i = 0; i < passwords_files.size(); ++i) {
                    const std::string& fname = passwords_files[i];
                    std::ifstream* pass_stream = acquire_password_stream_for_rewind(fname);
                    if (pass_stream == nullptr) {
                        continue;
                    }
                    std::string password_line;
                    while (read_trimmed_line(*pass_stream, password_line, 128)) {
                        metalError_t st = metalDeviceSynchronize();
                        if (st != metalSuccess) {
                            return st;
                        }
                        st = copy_password_to_device(password_line.data(), password_line.size());
                        if (st != metalSuccess) {
                            return st;
                        }
                        st = run_one(static_cast<uint32_t>(password_line.size()));
                        if (st != metalSuccess) {
                            return st;
                        }
                    }
                }
                for (size_t i = 0; i < passwords_list.size(); ++i) {
                    const std::string password_line = passwords_list[i];
                    metalError_t st = metalDeviceSynchronize();
                    if (st != metalSuccess) {
                        return st;
                    }
                    st = copy_password_to_device(password_line.data(), password_line.size());
                    if (st != metalSuccess) {
                        return st;
                    }
                    st = run_one(static_cast<uint32_t>(password_line.size()));
                    if (st != metalSuccess) {
                        return st;
                    }
                }
                if (pass_brute) {
                    uint8_t start_pass_point_local[128];
                    memcpy(&start_pass_point_local[0], &start_pass_point[0], 128);
                    uint64_t start_pass[16];
                    uint64_t start_pass_plus[16];
                    int pass_len = 0;
                    array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                    pass_len = sizeBE_64(start_pass, 16);
                    if (pass_len < min_pass_len) {
                        pass_len = min_pass_len;
                    }

                    while (true) {
                        const int result = cmp_host(start_pass_point_local, end_pass_point, 128);
                        if (result > 0) {
                            break;
                        }
                        metalError_t st = metalDeviceSynchronize();
                        if (st != metalSuccess) {
                            return st;
                        }
                        st = copy_password_to_device(&start_pass_point_local[128 - pass_len], static_cast<size_t>(pass_len));
                        if (st != metalSuccess) {
                            return st;
                        }
                        st = run_one(static_cast<uint32_t>(pass_len));
                        if (st != metalSuccess) {
                            return st;
                        }

                        array128_to_16x64_le(&start_pass_point_local[0], &start_pass[0]);
                        add64to1024_host(start_pass, 1, start_pass_plus);
                        array16x64_le_to128(&start_pass_plus[0], &start_pass_point_local[0]);
                        pass_len = sizeBE_64(start_pass_plus, 16);
                        if (pass_len < min_pass_len) {
                            pass_len = min_pass_len;
                        }
                    }
                }
                return metalSuccess;
            }

            return run_one(passwords_lenght_dev);
        },
        save_fn);

    if (dev_iter) metalFree(dev_iter);
    if (derivation_list) metalFree(derivation_list);
    if (der_index_dev) metalFree(der_index_dev);
    return metalStatus;
}

metalError_t processMetalHexsetSeq() {
    return dispatch_hexset_mode_multi_gpu(__func__, [](const size_t gpu_slot, const size_t gpu_count) -> metalError_t {
        return processMetalHexsetSeq_gpu_slot(gpu_slot, gpu_count);
    });
}

