static metalError_t processMetalArmoryRootRecoveryHexset_gpu_slot(const size_t gpu_slot, const size_t gpu_count) {
    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    const uint32_t hexset_base = static_cast<uint32_t>(hexset_digits.size());
    auto save_fn = [&]() { SaveResultArmoryRoot(OUT_FILE, Founds, save); };

    uint64_t domain_count = 1ull;
    bool exact_domain = true;
    for (uint32_t i = 0u; i < recovery_hex_wildcards; ++i) {
        if (domain_count > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(hexset_base))) {
            exact_domain = false;
            break;
        }
        domain_count *= static_cast<uint64_t>(hexset_base);
    }
    if (exact_domain && gpu_count != 0u && gpu_slot < domain_count) {
        counterTotal += ((domain_count - 1ull - static_cast<uint64_t>(gpu_slot)) / static_cast<uint64_t>(gpu_count)) + 1ull;
    }

    metalError_t st = run_recovery_hexset_mode_gpu_slot(
        gpu_slot, gpu_count, output_threads, output_threads, 0ull, 512u, "ArmoryRootRecoveryHexset_log.txt",
        [&](bool* buffIsResult, bool* buffDeviceResult, const uint8_t* d_start_digits, const uint8_t*, const uint8_t*, const uint8_t* d_alphabet, uint32_t current_size, uint32_t, uint64_t& launches_issued) -> metalError_t {
            launches_issued = 0ull;
            const size_t iteration_count = Iterations.empty() ? 1u : Iterations.size();
            for (size_t num = 0; num < iteration_count; ++num) {
                const uint32_t iteration_host = Iterations.empty() ? 1u : Iterations[num];
                metal_launch("workerArmoryRoot_recovery_hexset", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, deep, Rounds, ARMORY_MODE, iteration_host, IS_STRING, d_start_digits, d_alphabet, hexset_base, current_size, static_cast<uint64_t>(gpu_count));
                metalError_t st = metalGetLastError(); if (st != metalSuccess) return st;
                st = metalDeviceSynchronize(); if (st != metalSuccess) return st;
                ++launches_issued;
                flush_hexset_result_if_any(buffIsResult, save_fn);
            }
            return metalSuccess;
        }, save_fn);
    return st;
}

metalError_t processMetalArmoryRootRecoveryHexset() {
    return dispatch_hexset_mode_multi_gpu(__func__, [](const size_t gpu_slot, const size_t gpu_count) -> metalError_t { return processMetalArmoryRootRecoveryHexset_gpu_slot(gpu_slot, gpu_count); });
}

// processMetalMINIKEYS_gpu_slot: executes -minikeys workflow for one GPU slot.
// Optimised:
//  [A] Staging buffer sized to 2x expected SHA-256 hit rate (1/256) + safety margin
//      instead of worst-case, saving ~125x GPU memory. OOB guard added to kernel.
//  [B] Double-buffered Metal streams: while slot N syncs results, slot N+1 runs on GPU.
//  [C] Log file written at most every 2.5 s, not on every kernel launch.
static metalError_t processMetalMINIKEYS_gpu_slot(const size_t gpu_slot, const size_t gpu_count, const std::vector<MiniKeyRange>& ranges)
{
    metalError_t metalStatus = metalSuccess;
    const uint64_t thread_count = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (thread_count == 0ull || gpu_count == 0ull) {
        return metalErrorInvalidConfiguration;
    }
    if (thread_count > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(THREAD_STEPS))) {
        fprintf(stderr, "[!] Error: mini key launch size overflow [!]\n");
        return metalErrorInvalidValue;
    }
    const uint64_t launch_candidates = thread_count * static_cast<uint64_t>(THREAD_STEPS);
    if (launch_candidates == 0ull) {
        return metalErrorInvalidConfiguration;
    }
    if (launch_candidates > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max())) {
        fprintf(stderr, "[!] Error: mini key launch size exceeds uint32 capacity [!]\n");
        return metalErrorInvalidValue;
    }
    if (launch_candidates > (std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(gpu_count))) {
        fprintf(stderr, "[!] Error: mini key launch delta overflow [!]\n");
        return metalErrorInvalidValue;
    }
    const uint64_t launch_delta = launch_candidates * static_cast<uint64_t>(gpu_count);

    // [A] Staging buffer capacity: 2x expected SHA-256 hit rate + safety.
    // P(valid per key) = 1/256.  Alloc launch_candidates/128 (~2x expected) + 1024 extra.
    // Minimum 4096 entries.  OOB writes guarded inside kernel emit_valid.
    const uint32_t actual_capacity = static_cast<uint32_t>(
        std::max<uint64_t>(uint64_t{4096}, (launch_candidates >> 7) + uint64_t{1024}));

    const uint64_t random_target   = (use_n_count && n_number > 0ull) ? n_number : launch_candidates;
    const uint64_t random_launches = (random_target + launch_candidates - 1ull) / launch_candidates;
    const bool persist_minikey_seq_point = (seqMode || end_point_set);

    // [B] Double-buffer slot resources.
    static constexpr int NSLOTS = 2;
    struct SlotBufs {
        uint8_t*       d_suffix_start      = nullptr;
        unsigned char* d_valid_minikey     = nullptr;
        uint8_t*       d_valid_minikey_len = nullptr;
        uint32_t*      d_valid_count       = nullptr;
        bool*          d_is_result         = nullptr;
        bool*          d_device_result     = nullptr;
        metalStream_t   stream              = nullptr;
        uint32_t*      h_count             = nullptr;  // pinned host memory
        bool           in_flight           = false;
        std::vector<uint8_t> queued_current;
    };
    SlotBufs slots[NSLOTS];

    // Shared read-only end-suffix buffer (updated only between ranges).
    uint8_t* d_suffix_end = nullptr;

    // Cleanup helper.
    auto free_all = [&]() {
        for (int s = 0; s < NSLOTS; ++s) {
            if (slots[s].h_count)              { metalFreeHost(slots[s].h_count);             slots[s].h_count = nullptr; }
            if (slots[s].d_valid_count)        { metalFree(slots[s].d_valid_count);           slots[s].d_valid_count = nullptr; }
            if (slots[s].d_valid_minikey_len)  { metalFree(slots[s].d_valid_minikey_len);     slots[s].d_valid_minikey_len = nullptr; }
            if (slots[s].d_valid_minikey)      { metalFree(slots[s].d_valid_minikey);         slots[s].d_valid_minikey = nullptr; }
            if (slots[s].d_suffix_start)       { metalFree(slots[s].d_suffix_start);          slots[s].d_suffix_start = nullptr; }
            if (slots[s].d_device_result)      { metalFree(slots[s].d_device_result);         slots[s].d_device_result = nullptr; }
            if (slots[s].d_is_result)          { metalFree(slots[s].d_is_result);             slots[s].d_is_result = nullptr; }
            if (slots[s].stream)               { metalStreamDestroy(slots[s].stream);         slots[s].stream = nullptr; }
        }
        if (d_suffix_end) { metalFree(d_suffix_end); d_suffix_end = nullptr; }
    };

    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_suffix_end), MINIKEY_MAX_SUFFIX_LEN);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_suffix_end failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }

    for (int s = 0; s < NSLOTS && metalStatus == metalSuccess; ++s) {
        metalStatus = metalStreamCreate(&slots[s].stream);
        if (metalStatus != metalSuccess) { fprintf(stderr, "metalStreamCreate[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }

        metalStatus = metalMalloc(reinterpret_cast<void**>(&slots[s].d_suffix_start), MINIKEY_MAX_SUFFIX_LEN);
        if (metalStatus != metalSuccess) { fprintf(stderr, "metalMalloc d_suffix_start[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }

        metalStatus = metalMalloc(reinterpret_cast<void**>(&slots[s].d_valid_minikey),
            static_cast<size_t>(actual_capacity) * MINIKEY_STAGE_STRIDE);
        if (metalStatus != metalSuccess) { fprintf(stderr, "metalMalloc d_valid_minikey[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }

        metalStatus = metalMalloc(reinterpret_cast<void**>(&slots[s].d_valid_minikey_len),
            static_cast<size_t>(actual_capacity));
        if (metalStatus != metalSuccess) { fprintf(stderr, "metalMalloc d_valid_minikey_len[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }

        metalStatus = metalMalloc(reinterpret_cast<void**>(&slots[s].d_valid_count), sizeof(uint32_t));
        if (metalStatus != metalSuccess) { fprintf(stderr, "metalMalloc d_valid_count[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }

        // Separate result buffers per slot to prevent races between concurrent process kernels.
        metalStatus = allocate_result_buffers_device(thread_count, &slots[s].d_is_result, &slots[s].d_device_result);
        if (metalStatus != metalSuccess) { fprintf(stderr, "allocate_result_buffers_device[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }

        // Pinned host memory for zero-copy async count readback.
        metalStatus = metalMallocHost(reinterpret_cast<void**>(&slots[s].h_count), sizeof(uint32_t));
        if (metalStatus != metalSuccess) { fprintf(stderr, "metalMallocHost h_count[%d] failed: %s\n", s, metalGetErrorString(metalStatus)); break; }
        *slots[s].h_count = 0u;
    }
    if (metalStatus != metalSuccess) {
        free_all();
        return metalStatus;
    }

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point lastLogWrite       = beginCountHashrate;

    // sync_slot: wait for slot s, read count, save results, update STATUS/log.
    auto sync_slot = [&](int s) -> bool {
        if (!slots[s].in_flight) return true;
        metalStatus = metalStreamSynchronize(slots[s].stream);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalStreamSynchronize[%d] error: %s\n", s, metalGetErrorString(metalStatus));
            return false;
        }
        slots[s].in_flight = false;
        const uint32_t vc = *slots[s].h_count;
        if (vc > 0u) {
            counterMiniValid += static_cast<uint64_t>(vc);
            bool has_result = false;
            metalMemcpy(&has_result, slots[s].d_is_result, sizeof(bool), metalMemcpyDeviceToHost);
            if (has_result) {
                const bool zero = false;
                metalMemcpy(slots[s].d_is_result, &zero, sizeof(bool), metalMemcpyHostToDevice);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
            }
        }
        counterTotal += launch_candidates;
        // [C] Update STATUS; write log at most every 2.5 s.
        if (persist_minikey_seq_point && !slots[s].queued_current.empty()) {
            STATUS = minikey_string_from_suffix(slots[s].queued_current);
            const auto now = std::chrono::steady_clock::now();
            if (std::chrono::duration_cast<std::chrono::milliseconds>(now - lastLogWrite).count() >= 2500) {
                lastLogWrite = now;
                FILE* fp = open_runtime_log("MiniKeysSeq_log.txt", "wb");
                if (fp) { fputs("+ ", fp); fputs(STATUS.c_str(), fp); fputc('\n', fp); fclose(fp); }
            }
        }
        const long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) { beginCountHashrate = std::chrono::steady_clock::now(); }
        return true;
    };

    // queue_launch: submit collect + process + async count readback on slot s.
    auto queue_launch = [&](int s, const std::vector<uint8_t>& current, const uint8_t suffix_len) -> bool {
        slots[s].queued_current = current;
        metalMemsetAsync(slots[s].d_is_result,     0, sizeof(bool),                       slots[s].stream);
        metalMemsetAsync(slots[s].d_device_result, 0, static_cast<size_t>(thread_count),  slots[s].stream);
        metalMemsetAsync(slots[s].d_valid_count,   0, sizeof(uint32_t),                   slots[s].stream);
        metalStatus = metalMemcpyAsync(slots[s].d_suffix_start, current.data(), suffix_len,
                                     metalMemcpyHostToDevice, slots[s].stream);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpyAsync d_suffix_start[%d] failed: %s\n", s, metalGetErrorString(metalStatus));
            return false;
        }
        metal_launch("workerMINIKEYS_collect", BLOCK_NUMBER, BLOCK_THREADS, slots[s].d_suffix_start, d_suffix_end, suffix_len, static_cast<uint64_t>(gpu_count), slots[s].d_valid_minikey, slots[s].d_valid_minikey_len, slots[s].d_valid_count, actual_capacity);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_collect[%d] launch failed: %s\n", s, metalGetErrorString(metalStatus));
            return false;
        }
        metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, slots[s].d_is_result, slots[s].d_device_result, _dev_precomp, pitch, slots[s].d_valid_minikey, slots[s].d_valid_minikey_len, slots[s].d_valid_count, Rounds, actual_capacity);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_process[%d] launch failed: %s\n", s, metalGetErrorString(metalStatus));
            return false;
        }
        // Async count readback into pinned host memory (arrives after process finishes).
        metalStatus = metalMemcpyAsync(slots[s].h_count, slots[s].d_valid_count, sizeof(uint32_t),
                                     metalMemcpyDeviceToHost, slots[s].stream);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpyAsync h_count[%d] failed: %s\n", s, metalGetErrorString(metalStatus));
            return false;
        }
        slots[s].in_flight = true;
        return true;
    };

    // Main dispatch: alternate slots 0,1,0,1,...
    // Before queuing slot S for iter N: sync slot S (its previous work, iter N-2).
    // Overlap: sync of slot S happens while slot (1-S) runs on the GPU. [B]
    int  slot_idx    = 0;
    bool dispatch_ok = true;

    if (!isRandom) {
        for (size_t range_idx = 0; range_idx < ranges.size() && isRun && dispatch_ok; ++range_idx) {
            const MiniKeyRange& range = ranges[range_idx];
            metalStatus = metalMemcpy(d_suffix_end, range.end.data(), range.suffix_len, metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy d_suffix_end failed: %s\n", metalGetErrorString(metalStatus));
                dispatch_ok = false; break;
            }
            std::vector<uint8_t> current = range.start;
            if (!add_base58_counter_inplace(current, static_cast<uint64_t>(gpu_slot))) continue;
            if (cmp_base58_counter(current, range.end) > 0) continue;

            while (isRun && dispatch_ok) {
                const int s = slot_idx & 1;
                dispatch_ok = sync_slot(s) && queue_launch(s, current, range.suffix_len);
                if (!dispatch_ok) break;
                ++slot_idx;
                if (!add_base58_counter_inplace(current, launch_delta)) break;
                if (cmp_base58_counter(current, range.end) > 0) break;
            }
        }
    } else {
        while (isRun && dispatch_ok) {
            for (size_t range_idx = 0; range_idx < ranges.size() && isRun && dispatch_ok; ++range_idx) {
                const MiniKeyRange& range = ranges[range_idx];
                metalStatus = metalMemcpy(d_suffix_end, range.end.data(), range.suffix_len, metalMemcpyHostToDevice);
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalMemcpy d_suffix_end failed: %s\n", metalGetErrorString(metalStatus));
                    dispatch_ok = false; break;
                }
                std::vector<uint8_t> current;
                if (!random_base58_counter_inclusive(range.start, range.end, current)) continue;

                for (uint64_t launch_idx = 0; launch_idx < random_launches && isRun && dispatch_ok; ++launch_idx) {
                    if (launch_idx > 0) {
                        if (!add_base58_counter_inplace(current, launch_delta)) break;
                        if (cmp_base58_counter(current, range.end) > 0) break;
                    }
                    const int s = slot_idx & 1;
                    dispatch_ok = sync_slot(s) && queue_launch(s, current, range.suffix_len);
                    if (!dispatch_ok) break;
                    ++slot_idx;
                }
            }
        }
    }

    // Flush all in-flight slots before releasing resources.
    for (int s = 0; s < NSLOTS; ++s) { sync_slot(s); }

    free_all();
    return metalStatus;
}

// processMetalMINIKEYS: executes -minikeys mode on active GPU(s).
metalError_t processMetalMINIKEYS()
{
    std::vector<MiniKeyRange> ranges;
    std::string range_error;
    if (!build_minikey_ranges_from_args(ranges, range_error)) {
        fprintf(stderr, "[!] Error: %s [!]\n", range_error.c_str());
        return metalErrorInvalidValue;
    }

    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return processMetalMINIKEYS_gpu_slot(0u, 1u, ranges);
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    workers.reserve(gpu_count);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            restore_thread_input_snapshot(base_snapshot);
            g_disable_multi_gpu_dispatch = true;
            statuses[gpu_idx] = processMetalMINIKEYS_gpu_slot(gpu_idx, gpu_count, ranges);
            g_disable_multi_gpu_dispatch = false;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) {
            th.join();
        }
    }

    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    metalError_t first_error = metalSuccess;
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            first_error = statuses[gpu_idx];
            fprintf(stderr, "[!] mode %s failed on GPU %d: %s [!]\n",
                __func__,
                g_gpu_contexts[gpu_idx].device_id,
                metalGetErrorString(statuses[gpu_idx]));
            break;
        }
    }
    return first_error;
}

// processMetalMINIKEYSStream: runs explicit -i/-f plain minikey input workflow.
metalError_t processMetalMINIKEYSStream(std::istream& stream)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalMINIKEYSStream(shared_stream);
        });
    }

    metalError_t metalStatus = metalSuccess;
    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (output_threads == 0ull || output_threads > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max())) {
        fprintf(stderr, "[!] Error: invalid launch size in -minikeys file mode [!]\n");
        return metalErrorInvalidConfiguration;
    }
    const uint32_t stage_capacity = static_cast<uint32_t>(output_threads);

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(output_threads, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    unsigned char* d_valid_minikey = nullptr;
    uint8_t* d_valid_minikey_len = nullptr;
    uint32_t* d_valid_count = nullptr;
    std::vector<unsigned char> h_valid_minikeys(static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE), 0u);
    std::vector<uint8_t> h_valid_minikey_lens(stage_capacity, 0u);
    std::string buffer;
    std::string normalized;

    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey),
        static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey_len), static_cast<size_t>(stage_capacity));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_count), sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    while (isRun) {
        uint32_t nr = 0u;
        uint32_t valid_count_host = 0u;
        std::string last_line;

        while (nr < stage_capacity && read_trimmed_line(stream, buffer, 64u)) {
            ++nr;
            last_line = buffer;
            if (normalize_minikey_candidate(buffer, normalized)) {
                const size_t dst = static_cast<size_t>(valid_count_host) * static_cast<size_t>(MINIKEY_STAGE_STRIDE);
                std::memset(&h_valid_minikeys[dst], 0, static_cast<size_t>(MINIKEY_STAGE_STRIDE));
                std::memcpy(&h_valid_minikeys[dst], normalized.data(), normalized.size());
                h_valid_minikey_lens[valid_count_host] = static_cast<uint8_t>(normalized.size());
                ++valid_count_host;
            }
        }

        if (nr == 0u) {
            break;
        }

        counterTotal += static_cast<uint64_t>(nr);
        if (!last_line.empty()) {
            STATUS = last_line;
        }
        if (valid_count_host == 0u) {
            continue;
        }

        metalStatus = metalMemcpyAsync(d_valid_minikey,
            h_valid_minikeys.data(),
            static_cast<size_t>(valid_count_host) * static_cast<size_t>(MINIKEY_STAGE_STRIDE),
            metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metalMemcpyAsync(d_valid_minikey_len,
            h_valid_minikey_lens.data(),
            static_cast<size_t>(valid_count_host),
            metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metalMemcpyAsync(d_valid_count, &valid_count_host, sizeof(uint32_t), metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_valid_minikey, d_valid_minikey_len, d_valid_count, Rounds, valid_count_host);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_process launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after minikey file launch!\n", metalStatus);
            goto Error;
        }

        counterMiniValid += static_cast<uint64_t>(valid_count_host);
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
        }
    }

    metalStatus = metalDeviceSynchronize();
    if (metalStatus == metalSuccess && read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }

Error:
    if (d_valid_count) metalFree(d_valid_count);
    if (d_valid_minikey_len) metalFree(d_valid_minikey_len);
    if (d_valid_minikey) metalFree(d_valid_minikey);
    return metalStatus;
}

// processMetalMINIKEYSFile: runs explicit -i/-f plain minikey input workflow.
metalError_t processMetalMINIKEYSFile(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);

        const metalError_t st = processMetalMINIKEYSStream(stream);
        if (st != metalSuccess) {
            std::cerr << "processMetalMINIKEYSStream failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();
        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalMINIKEYSRun: validates args and runs -minikeys mode.
metalError_t processMetalMINIKEYSRun()
{
    if (IS_MINIKEYS_SEED) {
        return processMetalMINIKEYSSeedRun();
    }
    if (backward || both) {
        fprintf(stderr, "[!] Error: -minikeys supports forward scan and -random only (no -back/-both) [!]\n");
        return metalErrorInvalidValue;
    }
    counterMiniValid = 0ull;
    if (!mnemonicFiles.empty()) {
        return processMetalMINIKEYSFile(mnemonicFiles);
    }
    return processMetalMINIKEYS();
}

// processMetalMINIKEYSSeed: runs stream/file workflow for -minikeys -seed.
metalError_t processMetalMINIKEYSSeed(std::istream& stream)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalMINIKEYSSeed(shared_stream);
        });
    }

    metalError_t metalStatus = metalSuccess;
    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (output_threads == 0ull || output_threads > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max())) {
        fprintf(stderr, "[!] Error: invalid launch size in -minikeys -seed stream mode [!]\n");
        return metalErrorInvalidConfiguration;
    }

    std::vector<uint8_t> sizes_host;
    std::string sizes_err;
    if (!minikey_seed_collect_sizes(sizes_host, sizes_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", sizes_err.c_str());
        return metalErrorInvalidValue;
    }
    const uint32_t sizes_count = static_cast<uint32_t>(sizes_host.size());
    if (output_threads > (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) / sizes_count)) {
        fprintf(stderr, "[!] Error: stage buffer size overflow in -minikeys -seed stream mode [!]\n");
        return metalErrorInvalidValue;
    }
    const uint32_t stage_capacity = static_cast<uint32_t>(output_threads * static_cast<uint64_t>(sizes_count));

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(output_threads, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    char* devLines = nullptr;
    uint32_t* devIndexes = nullptr;
    uint8_t* devSizes = nullptr;
    unsigned char* d_valid_minikey = nullptr;
    uint8_t* d_valid_minikey_len = nullptr;
    uint32_t* d_valid_count = nullptr;
    std::string buffer;
    std::string combined;
    std::vector<uint32_t> indexes;

    metalStatus = metalMalloc(reinterpret_cast<void**>(&devSizes), static_cast<size_t>(sizes_count));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(devSizes, sizes_host.data(), static_cast<size_t>(sizes_count), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey), static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey_len), static_cast<size_t>(stage_capacity));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_count), sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    reserve_batch_buffers(combined, indexes, output_threads, IS_HEX ? 1024u : 512u);

    while (isRun) {
        combined.clear();
        indexes.clear();
        uint32_t nr = 0u;
        std::string last_line;

        while (nr < static_cast<uint32_t>(output_threads) &&
            read_trimmed_line(stream, buffer, std::numeric_limits<size_t>::max())) {
            if (IS_HEX && buffer.size() > 1024u) {
                buffer.resize(1024u);
            }
            else if (!IS_HEX && buffer.size() > 512u) {
                buffer.resize(512u);
            }

            combined.append(buffer.data(), buffer.size());
            indexes.emplace_back(static_cast<uint32_t>(combined.size()));
            last_line = buffer;
            ++nr;
        }

        if (nr == 0u) {
            break;
        }

        metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&devLines), combined.data(), combined.size());
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy devLines failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = copy_to_device_grow(reinterpret_cast<void**>(&devIndexes), indexes.data(), indexes.size() * sizeof(uint32_t));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy devIndexes failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metalStatus = metalMemsetAsync(d_valid_count, 0, sizeof(uint32_t));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemset d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("workerMINIKEYS_seed_collect_file", BLOCK_NUMBER, BLOCK_THREADS, devLines, devIndexes, nr, devSizes, sizes_count, d_valid_minikey, d_valid_minikey_len, d_valid_count);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_seed_collect_file launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_valid_minikey, d_valid_minikey_len, d_valid_count, Rounds, stage_capacity);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_process launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after mini seed stream launch!\n", metalStatus);
            goto Error;
        }

        uint32_t valid_count_host = 0u;
        metalStatus = metalMemcpy(&valid_count_host, d_valid_count, sizeof(valid_count_host), metalMemcpyDeviceToHost);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        counterMiniValid += static_cast<uint64_t>(valid_count_host);
        counterTotal += static_cast<uint64_t>(nr) * static_cast<uint64_t>(sizes_count);
        STATUS = last_line;

        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
        }
    }

    metalStatus = metalDeviceSynchronize();
    if (metalStatus == metalSuccess && read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }

Error:
    if (d_valid_count) metalFree(d_valid_count);
    if (d_valid_minikey_len) metalFree(d_valid_minikey_len);
    if (d_valid_minikey) metalFree(d_valid_minikey);
    if (devSizes) metalFree(devSizes);
    if (devIndexes) metalFree(devIndexes);
    if (devLines) metalFree(devLines);
    return metalStatus;
}

// processMetalMINIKEYSSeedFile: runs file workflow for -minikeys -seed.
metalError_t processMetalMINIKEYSSeedFile(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);

        const metalError_t st = processMetalMINIKEYSSeed(stream);
        if (st != metalSuccess) {
            std::cerr << "processMetalMINIKEYSSeed failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();
        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalMINIKEYSSeedSeq: runs sequential workflow for -minikeys -seed.
metalError_t processMetalMINIKEYSSeedSeq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalMINIKEYSSeedSeq();
        });
    }

    metalError_t metalStatus = metalSuccess;
    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (output_threads == 0ull || output_threads > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max())) {
        fprintf(stderr, "[!] Error: invalid launch size in -minikeys -seed seq mode [!]\n");
        return metalErrorInvalidConfiguration;
    }

    std::vector<uint8_t> sizes_host;
    std::string sizes_err;
    if (!minikey_seed_collect_sizes(sizes_host, sizes_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", sizes_err.c_str());
        return metalErrorInvalidValue;
    }
    const uint32_t sizes_count = static_cast<uint32_t>(sizes_host.size());
    if (output_threads > (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) / sizes_count)) {
        fprintf(stderr, "[!] Error: stage buffer size overflow in -minikeys -seed seq mode [!]\n");
        return metalErrorInvalidValue;
    }
    const uint32_t stage_capacity = static_cast<uint32_t>(output_threads * static_cast<uint64_t>(sizes_count));

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(output_threads, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    uint8_t* start_seed_dev = nullptr;
    uint8_t* devSizes = nullptr;
    unsigned char* d_valid_minikey = nullptr;
    uint8_t* d_valid_minikey_len = nullptr;
    uint32_t* d_valid_count = nullptr;
    auto lastLogWrite = std::chrono::steady_clock::now() - std::chrono::milliseconds(2500);

    metalStatus = metalMalloc(reinterpret_cast<void**>(&start_seed_dev), 64u);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc start_seed_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&devSizes), static_cast<size_t>(sizes_count));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(devSizes, sizes_host.data(), static_cast<size_t>(sizes_count), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey), static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey_len), static_cast<size_t>(stage_capacity));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_count), sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    while (isRun) {
        if (cmp_host(start_seed_point, end_seed_point, 64) > 0) {
            break;
        }

        metalStatus = metalMemcpyAsync(start_seed_dev, start_seed_point, 64u, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_seed_dev failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metalMemsetAsync(d_valid_count, 0, sizeof(uint32_t));
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemset d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("workerMINIKEYS_seed_collect_seq", BLOCK_NUMBER, BLOCK_THREADS, start_seed_dev, 1, min_len, devSizes, sizes_count, d_valid_minikey, d_valid_minikey_len, d_valid_count);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_seed_collect_seq launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_valid_minikey, d_valid_minikey_len, d_valid_count, Rounds, stage_capacity);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "workerMINIKEYS_process launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after mini seed seq launch!\n", metalStatus);
            goto Error;
        }

        uint32_t valid_count_host = 0u;
        metalStatus = metalMemcpy(&valid_count_host, d_valid_count, sizeof(valid_count_host), metalMemcpyDeviceToHost);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        counterMiniValid += static_cast<uint64_t>(valid_count_host);
        counterTotal += static_cast<uint64_t>(output_threads) * static_cast<uint64_t>(sizes_count);
        STATUS = minikey_seed_point_to_hex(start_seed_point);

        const auto now = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::milliseconds>(now - lastLogWrite).count() >= 2500) {
            lastLogWrite = now;
            FILE* fp = open_runtime_log("MiniKeysSeedSeq_log.txt", "wb");
            if (fp) {
                write_hex_last(fp, start_seed_point, 64, 64);
                fclose(fp);
            }
        }

        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
        }

        uint64_t valLE[8];
        uint64_t valBE[8];
        array64_to_8x64_le(start_seed_point, valLE);
        add64to512_host(valLE, output_threads * step, valBE);
        array8x64_le_to64(valBE, start_seed_point);
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }

Error:
    if (d_valid_count) metalFree(d_valid_count);
    if (d_valid_minikey_len) metalFree(d_valid_minikey_len);
    if (d_valid_minikey) metalFree(d_valid_minikey);
    if (devSizes) metalFree(devSizes);
    if (start_seed_dev) metalFree(start_seed_dev);
    return metalStatus;
}

// processMetalMINIKEYSSeedRandom: runs random/seq-random workflow for -minikeys -seed.
metalError_t processMetalMINIKEYSSeedRandom()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalMINIKEYSSeedRandom();
        });
    }

    metalError_t metalStatus = metalSuccess;
    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (output_threads == 0ull || output_threads > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max())) {
        fprintf(stderr, "[!] Error: invalid launch size in -minikeys -seed random mode [!]\n");
        return metalErrorInvalidConfiguration;
    }

    std::vector<uint8_t> sizes_host;
    std::string sizes_err;
    if (!minikey_seed_collect_sizes(sizes_host, sizes_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", sizes_err.c_str());
        return metalErrorInvalidValue;
    }
    const uint32_t sizes_count = static_cast<uint32_t>(sizes_host.size());
    if (output_threads > (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) / sizes_count)) {
        fprintf(stderr, "[!] Error: stage buffer size overflow in -minikeys -seed random mode [!]\n");
        return metalErrorInvalidValue;
    }
    const uint32_t stage_capacity = static_cast<uint32_t>(output_threads * static_cast<uint64_t>(sizes_count));

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(output_threads, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    uint8_t* start_seed_dev = nullptr;
    uint8_t* devSizes = nullptr;
    unsigned char* d_valid_minikey = nullptr;
    uint8_t* d_valid_minikey_len = nullptr;
    uint32_t* d_valid_count = nullptr;
    const uint64_t random_target = (use_n_count && n_number > 0ull) ? n_number : output_threads;
    const uint64_t random_launches = (random_target + output_threads - 1ull) / output_threads;
    uint8_t start_seed_point_local[64] = { 0 };
    uint8_t current_seed_point[64] = { 0 };

    metalStatus = metalMalloc(reinterpret_cast<void**>(&start_seed_dev), 64u);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc start_seed_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&devSizes), static_cast<size_t>(sizes_count));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(devSizes, sizes_host.data(), static_cast<size_t>(sizes_count), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey), static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey_len), static_cast<size_t>(stage_capacity));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_count), sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    while (isRun) {
        if (seqMode) {
            random_bytes_seq(start_seed_point, end_seed_point, start_seed_point_local, 64);
        }
        else {
            random_bytes(start_seed_point_local, 64, entropy_len);
        }
        memcpy(current_seed_point, start_seed_point_local, 64);

        for (uint64_t launch_idx = 0; launch_idx < random_launches && isRun; ++launch_idx) {
            if (seqMode && cmp_host(current_seed_point, end_seed_point, 64) > 0) {
                break;
            }

            metalStatus = metalMemcpyAsync(start_seed_dev, current_seed_point, 64u, metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy start_seed_dev failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = metalMemsetAsync(d_valid_count, 0, sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemset d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metal_launch("workerMINIKEYS_seed_collect_seq", BLOCK_NUMBER, BLOCK_THREADS, start_seed_dev, 1, min_len, devSizes, sizes_count, d_valid_minikey, d_valid_minikey_len, d_valid_count);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "workerMINIKEYS_seed_collect_seq launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_valid_minikey, d_valid_minikey_len, d_valid_count, Rounds, stage_capacity);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "workerMINIKEYS_process launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after mini seed random launch!\n", metalStatus);
                goto Error;
            }

            uint32_t valid_count_host = 0u;
            metalStatus = metalMemcpy(&valid_count_host, d_valid_count, sizeof(valid_count_host), metalMemcpyDeviceToHost);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            counterMiniValid += static_cast<uint64_t>(valid_count_host);
            counterTotal += static_cast<uint64_t>(output_threads) * static_cast<uint64_t>(sizes_count);
            STATUS = minikey_seed_point_to_hex(current_seed_point);

            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
            }

            uint64_t valLE[8];
            uint64_t valBE[8];
            array64_to_8x64_le(current_seed_point, valLE);
            add64to512_host(valLE, output_threads * step, valBE);
            array8x64_le_to64(valBE, current_seed_point);
        }
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }

Error:
    if (d_valid_count) metalFree(d_valid_count);
    if (d_valid_minikey_len) metalFree(d_valid_minikey_len);
    if (d_valid_minikey) metalFree(d_valid_minikey);
    if (devSizes) metalFree(devSizes);
    if (start_seed_dev) metalFree(start_seed_dev);
    return metalStatus;
}

