    const uint32_t sizes_count = static_cast<uint32_t>(sizes_host.size());
    if (output_threads > (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) / sizes_count)) {
        fprintf(stderr, "[!] Error: stage buffer size overflow in -minikeys -seed -prng mode [!]\n");
        return metalErrorInvalidValue;
    }
    const uint32_t stage_capacity = static_cast<uint32_t>(output_threads * static_cast<uint64_t>(sizes_count));

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(output_threads, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    uint8_t* devSizes = nullptr;
    unsigned char* d_valid_minikey = nullptr;
    uint8_t* d_valid_minikey_len = nullptr;
    uint32_t* d_valid_count = nullptr;

    metalStatus = metalMalloc(reinterpret_cast<void**>(&devSizes), static_cast<size_t>(sizes_count));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(devSizes, sizes_host.data(), static_cast<size_t>(sizes_count), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey), static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey_len), static_cast<size_t>(stage_capacity));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_count), sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed;
        isRun && seed_local <= static_cast<uint64_t>(end_seed);) {

        const uint64_t remaining = static_cast<uint64_t>(end_seed) - seed_local + 1ull;
        const uint64_t seed_count = (remaining < output_threads) ? remaining : output_threads;

        current_seed = seed_local;
        if (isLog) {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (ofs.is_open()) {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);
                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);
                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED: ";
                const uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFull);
                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }

        for (size_t entr_len = 0; entr_len < PrngBytes.size() && isRun; ++entr_len) {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size() && isRun; ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size() && isRun; ++n) {
                    const int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size() && isRun; ++i) {
                        const int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;

                        metalStatus = metalMemsetAsync(d_valid_count, 0, sizeof(uint32_t));
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemset d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metal_launch("workerMINIKEYS_seed_collect_gen", BLOCK_NUMBER, BLOCK_THREADS, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, devSizes, sizes_count, d_valid_minikey, d_valid_minikey_len, d_valid_count);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "workerMINIKEYS_seed_collect_gen launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_valid_minikey, d_valid_minikey_len, d_valid_count, Rounds, stage_capacity);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "workerMINIKEYS_process launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metalStatus = metalDeviceSynchronize();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalDeviceSynchronize returned error code %d after mini seed -prng launch!\n", metalStatus);
                            goto Error;
                        }

                        uint32_t valid_count_host = 0u;
                        metalStatus = metalMemcpy(&valid_count_host, d_valid_count, sizeof(valid_count_host), metalMemcpyDeviceToHost);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        counterMiniValid += static_cast<uint64_t>(valid_count_host);
                        counterTotal += seed_count * static_cast<uint64_t>(sizes_count);

                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
                        }
                    }
                }
            }
        }

        if (isRandom) {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else {
            seed_local += seed_count;
        }
    }

Error:
    if (d_valid_count) metalFree(d_valid_count);
    if (d_valid_minikey_len) metalFree(d_valid_minikey_len);
    if (d_valid_minikey) metalFree(d_valid_minikey);
    if (devSizes) metalFree(devSizes);
    return metalStatus;
}

// processMetalMINIKEYSSeedGen64: runs PRNG64 workflow for -minikeys -seed.
metalError_t processMetalMINIKEYSSeedGen64()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalMINIKEYSSeedGen64();
        });
    }

    metalError_t metalStatus = metalSuccess;
    const uint64_t output_threads = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
    if (output_threads == 0ull || output_threads > static_cast<uint64_t>(std::numeric_limits<uint32_t>::max())) {
        fprintf(stderr, "[!] Error: invalid launch size in -minikeys -seed -prng64 mode [!]\n");
        return metalErrorInvalidConfiguration;
    }

    std::vector<uint8_t> sizes_host;
    std::string sizes_err;
    if (!minikey_seed_collect_sizes(sizes_host, sizes_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", sizes_err.c_str());
        return metalErrorInvalidValue;
    }
    const uint32_t sizes_count = static_cast<uint32_t>(sizes_host.size());
    if (output_threads > (static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) / sizes_count)) {
        fprintf(stderr, "[!] Error: stage buffer size overflow in -minikeys -seed -prng64 mode [!]\n");
        return metalErrorInvalidValue;
    }
    const uint32_t stage_capacity = static_cast<uint32_t>(output_threads * static_cast<uint64_t>(sizes_count));

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(output_threads, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        return metalStatus;
    }

    uint8_t* devSizes = nullptr;
    unsigned char* d_valid_minikey = nullptr;
    uint8_t* d_valid_minikey_len = nullptr;
    uint32_t* d_valid_count = nullptr;

    metalStatus = metalMalloc(reinterpret_cast<void**>(&devSizes), static_cast<size_t>(sizes_count));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(devSizes, sizes_host.data(), static_cast<size_t>(sizes_count), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy devSizes failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey), static_cast<size_t>(stage_capacity) * static_cast<size_t>(MINIKEY_STAGE_STRIDE));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_minikey_len), static_cast<size_t>(stage_capacity));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_minikey_len failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc(reinterpret_cast<void**>(&d_valid_count), sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    for (uint64_t seed_local = isRandom ? random_seed64_inclusive(start_seed64, end_seed64) : start_seed64;
        isRun && seed_local <= end_seed64;) {

        const uint64_t remaining = end_seed64 - seed_local;
        const uint64_t seed_count = (remaining < output_threads) ? (remaining + 1ull) : output_threads;

        current_seed = seed_local;
        if (isLog) {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (ofs.is_open()) {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);
                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);
                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED: ";
                ofs << std::hex << std::setw(16) << std::setfill('0') << seed_local << "\n";
            }
        }

        for (size_t entr_len = 0; entr_len < PrngBytes.size() && isRun; ++entr_len) {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size() && isRun; ++skip) {
                metal_launch("SetSkipDev64", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size() && isRun; ++n) {
                    const int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size() && isRun; ++i) {
                        const int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(true, gen_h, mode_h)) continue;
                        current_mode = mode_h;

                        metalStatus = metalMemsetAsync(d_valid_count, 0, sizeof(uint32_t));
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemset d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metal_launch("workerMINIKEYS_seed_collect_gen", BLOCK_NUMBER, BLOCK_THREADS, seed_local, seed_count, true, PrngBytes[entr_len], mode_h - 1, gen_h - 1, devSizes, sizes_count, d_valid_minikey, d_valid_minikey_len, d_valid_count);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "workerMINIKEYS_seed_collect_gen launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metal_launch("workerMINIKEYS_process", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, d_valid_minikey, d_valid_minikey_len, d_valid_count, Rounds, stage_capacity);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "workerMINIKEYS_process launch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        metalStatus = metalDeviceSynchronize();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalDeviceSynchronize returned error code %d after mini seed -prng64 launch!\n", metalStatus);
                            goto Error;
                        }

                        uint32_t valid_count_host = 0u;
                        metalStatus = metalMemcpy(&valid_count_host, d_valid_count, sizeof(valid_count_host), metalMemcpyDeviceToHost);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy d_valid_count failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }

                        counterMiniValid += static_cast<uint64_t>(valid_count_host);
                        counterTotal += seed_count * static_cast<uint64_t>(sizes_count);

                        if (read_result_flag_host(buffIsResult)) {
                            clear_result_flag_host(buffIsResult);
                            SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
                        }
                    }
                }
            }
        }

        if (isRandom) {
            seed_local = random_seed64_inclusive(start_seed64, end_seed64);
        }
        else {
            if (seed_local > (std::numeric_limits<uint64_t>::max() - seed_count)) {
                break;
            }
            seed_local += seed_count;
        }
    }

Error:
    if (d_valid_count) metalFree(d_valid_count);
    if (d_valid_minikey_len) metalFree(d_valid_minikey_len);
    if (d_valid_minikey) metalFree(d_valid_minikey);
    if (devSizes) metalFree(devSizes);
    return metalStatus;
}

// processMetalMINIKEYSSeedRun: validates and dispatches -minikeys -seed submode.
metalError_t processMetalMINIKEYSSeedRun()
{
    if (backward || both) {
        fprintf(stderr, "[!] Error: -minikeys -seed supports forward scan and -random only (no -back/-both) [!]\n");
        return metalErrorInvalidValue;
    }
    if (seqMode && isRandom && !end_point_set) {
        fprintf(stderr, "[!] Error: -minikeys -seed -start -random requires -end [!]\n");
        return metalErrorInvalidValue;
    }

    std::string point_err;
    if (!configure_minikey_seed_seq_points_from_args(point_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", point_err.c_str());
        return metalErrorInvalidValue;
    }

    std::vector<uint8_t> sizes_host;
    std::string sizes_err;
    if (!minikey_seed_collect_sizes(sizes_host, sizes_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", sizes_err.c_str());
        return metalErrorInvalidValue;
    }

    counterMiniValid = 0ull;

    if (prng_gen) {
        return processMetalMINIKEYSSeedGen();
    }
    if (prng64_gen) {
        return processMetalMINIKEYSSeedGen64();
    }
    if (seqMode) {
        return isRandom ? processMetalMINIKEYSSeedRandom() : processMetalMINIKEYSSeedSeq();
    }
    if (isRandom) {
        return processMetalMINIKEYSSeedRandom();
    }

    if (PHRASE_IN) {
        return processMetalMINIKEYSSeed(std::cin);
    }
    return processMetalMINIKEYSSeedFile(mnemonicFiles);
}

// processMetalPRIVFile: runs the Metal workflow for privfile.
metalError_t processMetalPRIVFile(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);



        metalError_t st;

        if (use_combos)
        {


            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });


            st = processMetalPRIV(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = processMetalPRIV(stream);
        }


        if (st != metalSuccess) {
            std::cerr << "processMetalPRIV failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// Identifies which kernel family was launched for current PRIV iteration.
enum : uint8_t {
    PRIV_LAUNCH_SEQ128 = 0u,
    PRIV_LAUNCH_VANITY_X = 1u,
    PRIV_LAUNCH_VANITY_C = 2u,
    PRIV_LAUNCH_VANITY_U = 3u,
    PRIV_LAUNCH_VANITY_S = 4u,
    PRIV_LAUNCH_VANITY_R = 5u,
    PRIV_LAUNCH_VANITY_E = 6u,
    PRIV_LAUNCH_VANITY_CUSR = 7u,
    PRIV_LAUNCH_VANITY_P = 8u
};

// Returns effective check multiplier used by performance counter for endomorphism mode.
static inline uint64_t endo_multiplier_for_launch_kind(uint8_t launch_kind) {
    if (!Endomorphism) {
        return 1ull;
    }
    // Count extra checks only when the launched kernel path actually performs endomorphism probes.
    if (launch_kind != PRIV_LAUNCH_VANITY_CUSR) {
        return 1ull;
    }
    uint64_t checks = 0ull;
    if (Compressed) checks += 6ull;
    if (Segwit) checks += 6ull;
    if (P2wsh) checks += 6ull;
    if (Uncompressed) checks += 6ull;
    if (Taproot) checks += 3ull;
    if (Ethereum) checks += 3ull;
    if (Xpoint) checks += 3ull;
    return (checks == 0ull) ? 1ull : checks;
}

// Selects the best PRIV kernel for the active -c mode and reports launch kind for accounting.
static inline metalError_t launch_workerPRIV_seq(
    int keys_per_chunk,
    MetalGridSize grid, MetalGridSize block,
    bool* buffIsResult,
    bool* buffDeviceResult,
    const secp256k1_ge_storage* _dev_precomp,
    size_t pitch,
    int mode,
    uint8_t* start_pvk_dev,
    uint64_t Step,
    int THREAD_STEPS_PUB_H,
    uint64_t* startx_buf,
    uint64_t* starty_buf,
    uint8_t* launch_kind)
{
    (void)keys_per_chunk;
    if (launch_kind) {
        *launch_kind = PRIV_LAUNCH_SEQ128;
    }
    bool has_other = Solana || Ton || Ton_all || Dot || Aptos || Sui || Xrp || Exodus || Iota || Ada || Icp || Fil || Xtz;
    metalError_t launch_status = metalSuccess;
    if (Endomorphism && !has_other && (Compressed || Uncompressed || Segwit || P2wsh || Taproot || Ethereum || Xpoint)) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_CUSR;
        launch_status = metal_launch("workerPRIV_seq_vanity_cusr", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!P2wsh && !Endomorphism && !has_other && !Ethereum && !Compressed && !Uncompressed && !Segwit && !Taproot && Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_X;
        launch_status = metal_launch("workerPRIV_seq_vanity_x", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!P2wsh && !Endomorphism && !has_other && !Ethereum && Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_C;
        launch_status = metal_launch("workerPRIV_seq_vanity_c", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!P2wsh && !Endomorphism && !has_other && !Ethereum && !Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_U;
        launch_status = metal_launch("workerPRIV_seq_vanity_u", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!P2wsh && !Endomorphism && !has_other && !Ethereum && !Compressed && !Uncompressed && Segwit && !Taproot && !Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_S;
        launch_status = metal_launch("workerPRIV_seq_vanity_s", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!P2wsh && !Endomorphism && !has_other && !Ethereum && !Compressed && !Uncompressed && !Segwit && Taproot && !Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_R;
        launch_status = metal_launch("workerPRIV_seq_vanity_r", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!P2wsh && !Endomorphism && !has_other && Ethereum && !Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_E;
        launch_status = metal_launch("workerPRIV_seq_vanity_e", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (P2wsh && !Endomorphism && !has_other && !Ethereum && !Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_P;
        launch_status = metal_launch("workerPRIV_seq_vanity_p", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else if (!has_other && (Compressed || Uncompressed || Segwit || P2wsh || Taproot || Xpoint || Ethereum)) {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_VANITY_CUSR;
        launch_status = metal_launch("workerPRIV_seq_vanity_cusr", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
    } else {
        if (launch_kind) *launch_kind = PRIV_LAUNCH_SEQ128;
        if (has_secp_output_targets()) {
            launch_status = metal_launch("workerPRIV_seq_128", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
        } else {
            launch_status = metal_launch("workerPRIV_seq_128_edonly", grid, block, buffIsResult, buffDeviceResult, _dev_precomp, pitch, mode, start_pvk_dev, Step, THREAD_STEPS_PUB_H, startx_buf, starty_buf);
        }
    }
    return launch_status;
}


static inline int profanity_target_count()
{
    int n = 0;
    if (Compressed) ++n;
    if (Uncompressed) ++n;
    if (Segwit) ++n;
    if (P2wsh) ++n;
    if (Taproot) ++n;
    if (Xpoint) ++n;
    if (Ethereum) ++n;
    return n;
}

static inline const char* profanity_recovery_filter_label(bool xc_only, bool xuc_only, bool xh_only)
{
    if (xc_only) return "xc";
    if (xuc_only) return "xuc";
    if (xh_only) return "xh";
    if (useXorUn && !useXor && !useXorUc && !useXorHc) return "xu";
    return "mixed";
}

static inline uint64_t profanity_lanes_per_launch()
{
    return static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS);
}

static inline uint64_t profanity_recovery_historical_lane_count()
{
    // Original Profanity default: inverse-size 255 * inverse-multiple 16384.
    return 255ull * 16384ull;
}

static inline uint64_t profanity_direct_foundid_count()
{
    // Direct -profanity defaults to the original foundId domain. A manual -b
    // intentionally changes that domain through the physical grid size.
    return set_block ? profanity_lanes_per_launch() : profanity_recovery_historical_lane_count();
}

static inline uint64_t profanity_walk_rounds_per_launch()
{
    return 1024ull;
}

static inline uint64_t profanity_direct_rounds_per_launch()
{
    if (BLOCK_NUMBER >= 16320u) {
        return 2048ull;
    }
    const int targets = profanity_target_count();
    if (targets == 1) {
        if (Xpoint) {
            return 4096ull;
        }
        if (Compressed || Uncompressed || Segwit || P2wsh || Ethereum) {
            return 8192ull;
        }
    }
    return 1024ull;
}

static inline uint64_t profanity_recovery_lane_chunk_limit()
{
    const uint64_t historical_lanes = profanity_recovery_historical_lane_count();
    const uint64_t tuned_lanes = 1024ull * 1024ull;
    if (set_block) {
        const uint64_t manual_lanes = profanity_lanes_per_launch();
        if (manual_lanes > 0ull) {
            return std::min<uint64_t>(std::min(historical_lanes, tuned_lanes), manual_lanes);
        }
    }
    return std::min(historical_lanes, tuned_lanes);
}

static inline unsigned int profanity_blocks_for_lane_count(uint64_t lane_count)
{
    if (lane_count == 0ull) {
        return 1u;
    }
    const uint64_t threads = std::max<uint64_t>(1ull, static_cast<uint64_t>(BLOCK_THREADS));
    const uint64_t blocks = (lane_count + threads - 1ull) / threads;
    return static_cast<unsigned int>(std::min<uint64_t>(
        blocks,
        static_cast<uint64_t>(std::numeric_limits<unsigned int>::max())));
}

static inline uint64_t profanity_metal_walk_order_rank(uint64_t relative_round)
{
    constexpr uint64_t kWalkBatch = 1024ull;
    constexpr uint64_t kWalkHalf = kWalkBatch / 2ull;
    const uint64_t batch = relative_round / kWalkBatch;
    const uint64_t pk_field = relative_round % kWalkBatch;
    uint64_t rank = 0ull;
    if (pk_field == kWalkHalf) {
        rank = 0ull;
    }
    else if (pk_field > kWalkHalf) {
        rank = 1ull + ((pk_field - (kWalkHalf + 1ull)) * 2ull);
    }
    else if (pk_field != 0ull) {
        rank = 2ull + (((kWalkHalf - 1ull) - pk_field) * 2ull);
    }
    else {
        rank = kWalkBatch - 1ull;
    }
    return batch * kWalkBatch + rank;
}

static inline uint64_t profanity_metal_lane_order_rank(uint64_t lane_delta, uint64_t block_threads)
{
    if (block_threads != 256ull) {
        return lane_delta;
    }
    const uint64_t block = lane_delta / block_threads;
    const uint64_t lane = lane_delta % block_threads;
    uint64_t rank_in_block = lane;
    if (lane >= 64ull && lane < 128ull) {
        rank_in_block = lane - 64ull;
    }
    else if (lane >= 192ull) {
        rank_in_block = 64ull + (lane - 192ull);
    }
    else if (lane < 64ull) {
        rank_in_block = 128ull + lane;
    }
    else {
        rank_in_block = 192ull + (lane - 128ull);
    }
    return block * block_threads + rank_in_block;
}

static inline unsigned int profanity_result_type_order_rank(uint8_t type)
{
    switch (type) {
    case 0x01: return 0u;
    case 0x02: return 1u;
    case 0x03: return 2u;
    case 0x07: return 3u;
    case 0x04: return 4u;
    case 0x05: return 5u;
    case 0x06: return 6u;
    default: return 7u + static_cast<unsigned int>(type);
    }
}

static void order_profanity_results_by_lane(
    std::vector<ProfanityVerifiedResult>& results,
    uint64_t lane_chunk_start,
    uint64_t round_start)
{
    if (results.size() < 2u) {
        return;
    }
    const uint64_t block_threads = std::max<uint64_t>(1ull, static_cast<uint64_t>(BLOCK_THREADS));
    std::stable_sort(results.begin(), results.end(),
        [lane_chunk_start, round_start, block_threads](const ProfanityVerifiedResult& a, const ProfanityVerifiedResult& b) {
            const uint64_t a_round_delta = (a.round >= round_start) ? (a.round - round_start) : a.round;
            const uint64_t b_round_delta = (b.round >= round_start) ? (b.round - round_start) : b.round;
            const uint64_t a_round_rank = profanity_metal_walk_order_rank(a_round_delta);
            const uint64_t b_round_rank = profanity_metal_walk_order_rank(b_round_delta);
            if (a_round_rank != b_round_rank) {
                return a_round_rank < b_round_rank;
            }
            const uint64_t a_lane_delta = (a.lane_id >= lane_chunk_start) ? (a.lane_id - lane_chunk_start) : a.lane_id;
            const uint64_t b_lane_delta = (b.lane_id >= lane_chunk_start) ? (b.lane_id - lane_chunk_start) : b.lane_id;
            const uint64_t a_lane_rank = profanity_metal_lane_order_rank(a_lane_delta, block_threads);
            const uint64_t b_lane_rank = profanity_metal_lane_order_rank(b_lane_delta, block_threads);
            if (a_lane_rank != b_lane_rank) {
                return a_lane_rank < b_lane_rank;
            }
            const unsigned int a_type_rank = profanity_result_type_order_rank(a.type);
            const unsigned int b_type_rank = profanity_result_type_order_rank(b.type);
            if (a_type_rank != b_type_rank) {
                return a_type_rank < b_type_rank;
            }
            return a.type < b.type;
        });
}

static inline unsigned int profanity_seed_resolve_blocks()
{
    return 4096u;
}

static inline void speed_counter_pause_since(std::chrono::steady_clock::time_point begin)
{
    const auto now = std::chrono::steady_clock::now();
    const auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(now - begin).count();
    if (ns > 0) {
        counterSpeedPausedNs += static_cast<uint64_t>(ns);
    }
}

static inline void profanity_recovery_guard_launch_geometry()
{
    constexpr unsigned int kPreferredThreads = 256u;
    constexpr unsigned int kMinAutoBlocks = 16384u;

    bool changed = false;
    if (BLOCK_THREADS != kPreferredThreads) {
        BLOCK_THREADS = kPreferredThreads;
        changed = true;
    }

    if (!set_block && BLOCK_NUMBER < kMinAutoBlocks) {
        BLOCK_NUMBER = kMinAutoBlocks;
        changed = true;
    }
    else if (set_block && BLOCK_NUMBER < kMinAutoBlocks) {
        fprintf(stderr,
            "[!] Warning: -profanity -recovery works best with at least %u blocks; manual -b %u is kept [!]\n",
            kMinAutoBlocks,
            BLOCK_NUMBER);
    }

    if (changed) {
        fprintf(stderr,
            "[!] Profanity recovery launch geometry adjusted for throughput: Blocks=%u Threads=%u [!]\n",
            BLOCK_NUMBER,
            BLOCK_THREADS);
    }
}

static inline void profanity_direct_guard_launch_geometry()
{
    constexpr unsigned int kPreferredThreads = 256u;
    constexpr unsigned int kDefaultBlocks = 16384u;

    bool changed = false;
    if (BLOCK_THREADS != kPreferredThreads) {
        BLOCK_THREADS = kPreferredThreads;
        changed = true;
    }
    if (!set_block && BLOCK_NUMBER < kDefaultBlocks) {
        BLOCK_NUMBER = kDefaultBlocks;
        changed = true;
    }
    if (changed) {
        workSize = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
        fprintf(stderr,
            "[!] Profanity launch geometry adjusted: Blocks=%u Threads=%u [!]\n",
            BLOCK_NUMBER,
            BLOCK_THREADS);
    }
}

static inline uint64_t profanity_range_remaining_inclusive(uint64_t current, uint64_t end_inclusive)
{
    if (current > end_inclusive) {
        return 0ull;
    }
    if (end_inclusive == std::numeric_limits<uint64_t>::max()) {
        return std::numeric_limits<uint64_t>::max() - current;
    }
    return end_inclusive - current + 1ull;
}

static inline bool profanity_recovery_acquire_round_window(
    uint64_t reverse_end,
    uint64_t rounds_per_launch,
    uint64_t& round,
    uint64_t& round_count)
{
    if (!profanity_recovery_round_queue_active || profanity_recovery_next_round == nullptr) {
        return false;
    }
    while (true) {
        if (RECOVERY_MODE && g_profanity_recovery_found_any.load(std::memory_order_relaxed)) {
            return false;
        }
        uint64_t current = profanity_recovery_next_round->load(std::memory_order_relaxed);
        if (current > reverse_end) {
            return false;
        }
        const uint64_t remain = profanity_range_remaining_inclusive(current, reverse_end);
        if (remain == 0ull) {
            return false;
        }
        const uint64_t count = std::min(rounds_per_launch, remain);
        const uint64_t next = (count > (std::numeric_limits<uint64_t>::max() - current))
            ? std::numeric_limits<uint64_t>::max()
            : (current + count);
        if (profanity_recovery_next_round->compare_exchange_weak(
            current,
            next,
            std::memory_order_relaxed,
            std::memory_order_relaxed)) {
            round = current;
            round_count = count;
            return true;
        }
    }
}

// Direct -profanity: -n is rounds checked by every Metal logical lane.
static inline bool profanity_round_window(uint64_t& out_begin, uint64_t& out_end)
{
    if (profanity_direct_round_window_override_active) {
        if (profanity_direct_round_window_begin > profanity_direct_round_window_end) {
            return false;
        }
        out_begin = profanity_direct_round_window_begin;
        out_end = profanity_direct_round_window_end;
        return true;
    }

    const uint64_t check_count = use_n_count ? n_number : (1ull << 32);
    if (check_count == 0ull) {
        return false;
    }
    out_begin = profanity_offset_explicit ? profanity_offset : 1ull;
    const uint64_t span = check_count - 1ull;
    out_end = (span > (std::numeric_limits<uint64_t>::max() - out_begin))
        ? std::numeric_limits<uint64_t>::max()
        : (out_begin + span);
    return true;
}

static inline uint64_t profanity_mul_saturate_u64(uint64_t a, uint64_t b)
{
    if (a == 0ull || b == 0ull) return 0ull;
    if (a > (std::numeric_limits<uint64_t>::max() / b)) {
        return std::numeric_limits<uint64_t>::max();
    }
    return a * b;
}

static inline const char* profanity_gpu_split_mode_name(ProfanityGpuSplitMode mode)
{
    switch (mode) {
    case ProfanityGpuSplitMode::Round: return "round";
    case ProfanityGpuSplitMode::Seed: return "seed";
    case ProfanityGpuSplitMode::FoundId: return "foundid";
    default: return "round";
    }
}

static inline bool parse_profanity_gpu_split_mode(const char* raw, ProfanityGpuSplitMode& out)
{
    if (raw == nullptr) return false;
    std::string value(raw);
    std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    if (value == "round") {
        out = ProfanityGpuSplitMode::Round;
        return true;
    }
    if (value == "seed") {
        out = ProfanityGpuSplitMode::Seed;
        return true;
    }
    if (value == "foundid" || value == "found-id" || value == "found_id") {
        out = ProfanityGpuSplitMode::FoundId;
        return true;
    }
    return false;
}

static bool xp_path_has_source_scan_ext(const std::string& path)
{
    std::string lower_path = path;
    std::transform(lower_path.begin(), lower_path.end(), lower_path.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    const size_t dot = path.find_last_of('.');
    if (dot == std::string::npos) {
        return false;
    }
    std::string ext = lower_path.substr(dot);
    std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    if (ext == ".bin") {
        const bool output_like =
            lower_path.find("cryptgenrandom") != std::string::npos ||
            lower_path.find("rand_bytes") != std::string::npos ||
            lower_path.find("randbytes") != std::string::npos ||
            lower_path.find("cgr_output") != std::string::npos ||
            lower_path.find("out40") != std::string::npos ||
            lower_path.find("out_dest") != std::string::npos ||
            lower_path.find("final_dst") != std::string::npos ||
            lower_path.find("user_out") != std::string::npos;
        const bool internal_state =
            lower_path.find("state20") != std::string::npos ||
            lower_path.find("aux20") != std::string::npos ||
            lower_path.find("seedbase") != std::string::npos ||
            lower_path.find("pool") != std::string::npos ||
            lower_path.find("local_before") != std::string::npos ||
            lower_path.find("local_after") != std::string::npos;
        return output_like && !internal_state;
    }
    return ext == ".json" || ext == ".jsonl" || ext == ".txt" ||
        ext == ".log" || ext == ".tsv" || ext == ".csv";
}

static bool xp_should_skip_source_scan_dir(const std::string& name)
{
    std::string lower_name = name;
    std::transform(lower_name.begin(), lower_name.end(), lower_name.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    return lower_name == ".git" ||
        lower_name == ".svn" ||
        lower_name == ".hg" ||
        lower_name == "__pycache__" ||
        lower_name == "node_modules";
}

static void xp_collect_source_scan_files(const std::string& path, std::vector<std::string>& out)
{
    const MacPathKind kind = mac_path_kind(path);
    if (kind == MacPathKind::Missing) {
        return;
    }
    if (kind != MacPathKind::Directory) {
        if (xp_path_has_source_scan_ext(path)) {
            out.push_back(path);
        }
        return;
    }

    std::vector<MacDirectoryEntry> entries;
    if (!mac_list_directory(path, entries)) {
        return;
    }

    for (const MacDirectoryEntry& entry : entries) {
        if (xp_should_skip_source_scan_dir(entry.name)) {
            continue;
        }
        xp_collect_source_scan_files(entry.path, out);
    }
}

static void xp_collect_all_regular_files(const std::string& path, std::vector<std::string>& out)
{
    const MacPathKind kind = mac_path_kind(path);
    if (kind == MacPathKind::Missing) {
        return;
    }
    if (kind != MacPathKind::Directory) {
        out.push_back(path);
        return;
    }

    std::vector<MacDirectoryEntry> entries;
    if (!mac_list_directory(path, entries)) {
        return;
    }

    for (const MacDirectoryEntry& entry : entries) {
        if (xp_should_skip_source_scan_dir(entry.name)) {
            continue;
        }
        xp_collect_all_regular_files(entry.path, out);
    }
}

static bool xp_source_scan_line_has_output_marker(const std::string& lower_line)
{
    const bool internal_state =
        lower_line.find("state_after_stir") != std::string::npos ||
        lower_line.find("state20") != std::string::npos ||
        lower_line.find("aux20") != std::string::npos ||
        lower_line.find("seedbase") != std::string::npos ||
        lower_line.find("local_md") != std::string::npos ||
        lower_line.find("input_md_c") != std::string::npos ||
        lower_line.find("iter_state") != std::string::npos ||
        lower_line.find("state_xor") != std::string::npos;
    if (internal_state) {
        return false;
    }
    return lower_line.find("cryptgenrandom") != std::string::npos ||
        lower_line.find("\"stage\":\"after\"") != std::string::npos ||
        lower_line.find("\"stage\": \"after\"") != std::string::npos ||
        lower_line.find("cgr_output32") != std::string::npos ||
        lower_line.find("cgr_output") != std::string::npos ||
        lower_line.find("secret_hex") != std::string::npos ||
        lower_line.find("out40") != std::string::npos ||
        lower_line.find("out_dest") != std::string::npos ||
        lower_line.find("destination") != std::string::npos ||
        lower_line.find("final_dst32") != std::string::npos ||
        lower_line.find("final_src32") != std::string::npos ||
        lower_line.find("user_out") != std::string::npos;
}

static void xp_add_raw32_observed_input(
    std::vector<XpCgrStateInput>& out,
    std::unordered_set<std::string>& seen,
    const std::string& label,
    const std::string& raw_hex)
{
    std::string clean;
    clean.reserve(raw_hex.size());
    for (char c : raw_hex) {
        if (std::isxdigit(static_cast<unsigned char>(c))) {
            clean.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
        }
    }
    if (clean.size() < 64u) {
        return;
    }
    const std::string raw32_hex = clean.substr(0u, 64u);
    if (!seen.insert(raw32_hex).second) {
        return;
    }
    std::string parse_err;
    uint8_t raw32[32];
    if (!wallet_hex_to_fixed(raw32_hex, raw32, 32u, parse_err)) {
        return;
    }
    XpCgrStateInput item{};
    memcpy(item.state20, raw32, 20u);
    memcpy(item.aux20, raw32 + 20u, 12u);
    const size_t n = std::min<size_t>(label.size(), XP_CGR_LABEL_MAX);
    if (n != 0u) {
        memcpy(item.label, label.data(), n);
        item.label_len = static_cast<uint8_t>(n);
    }
    out.push_back(item);
}

static void xp_add_raw32_observed_input_chunks(
    std::vector<XpCgrStateInput>& out,
    std::unordered_set<std::string>& seen,
    const std::string& label,
    const std::string& raw_hex)
{
    std::string clean;
    clean.reserve(raw_hex.size());
    for (char c : raw_hex) {
        if (std::isxdigit(static_cast<unsigned char>(c))) {
            clean.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
        }
    }
    if (clean.size() < 64u) {
        return;
    }
    size_t chunk = 0u;
    for (size_t off = 0u; off + 64u <= clean.size(); off += 64u, ++chunk) {
        std::ostringstream chunk_label;
        chunk_label << label;
        if (chunk != 0u) {
            chunk_label << "#" << chunk;
        }
        xp_add_raw32_observed_input(out, seen, chunk_label.str(), clean.substr(off, 64u));
    }
}

static bool xp_try_add_raw32_json_after_input(
    std::vector<XpCgrStateInput>& out,
    const std::string& file,
    const size_t line_no,
    const std::string& line,
    bool& handled,
    std::string& err)
{
    handled = false;
    if (line.find("\"stage\"") == std::string::npos || line.find("\"data\"") == std::string::npos) {
        return true;
    }

    std::string stage;
    if (!wallet_json_get_string(line, "stage", stage)) {
        return true;
    }
    std::transform(stage.begin(), stage.end(), stage.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    if (stage != "after") {
        handled = true;
        return true;
    }

    std::string data_hex;
    if (!wallet_json_get_string(line, "data", data_hex)) {
        std::ostringstream oss;
        oss << file << ":" << line_no << ": stage=after JSONL entry has no data field";
        err = oss.str();
        return false;
    }

    std::string clean;
    clean.reserve(data_hex.size());
    for (char c : data_hex) {
        if (std::isxdigit(static_cast<unsigned char>(c))) {
            clean.push_back(c);
        }
    }
    if (clean.size() != 64u && clean.size() != 80u) {
        std::ostringstream oss;
        oss << file << ":" << line_no << ": stage=after raw32 expects 32 bytes or out40 expects 40 bytes, got "
            << (clean.size() / 2u) << " bytes";
        err = oss.str();
        return false;
    }

    std::string parse_err;
    uint8_t raw32[32];
    if (!wallet_hex_to_fixed(clean.substr(0u, 64u), raw32, 32u, parse_err)) {
        std::ostringstream oss;
        oss << file << ":" << line_no << ": invalid stage=after raw32: " << parse_err;
        err = oss.str();
        return false;
    }

    XpCgrStateInput item{};
    memcpy(item.state20, raw32, 20u);
    memcpy(item.aux20, raw32 + 20u, 12u);
    item.transition_count = 0u;
    std::ostringstream label;
    label << "json-after:" << line_no;
    const std::string label_s = label.str();
    const size_t n = std::min<size_t>(label_s.size(), XP_CGR_LABEL_MAX);
    memcpy(item.label, label_s.data(), n);
    item.label_len = static_cast<uint8_t>(n);
    out.push_back(item);
    handled = true;
    return true;
}

static void xp_add_cgr_state_observed_input(
    std::vector<XpCgrStateInput>& out,
    std::unordered_set<std::string>& seen,
    const std::string& label,
    const std::string& state_hex,
    const std::string& aux_hex)
{
    std::string parse_err;
    XpCgrStateInput item{};
    if (!wallet_hex_to_fixed(state_hex, item.state20, 20u, parse_err)) {
        return;
    }
    if (!wallet_hex_to_fixed(aux_hex, item.aux20, 20u, parse_err)) {
        return;
    }
    memcpy(item.chain_aux20[0], item.aux20, 20u);
    item.transition_count = 1u;

    char key[81];
    static const char* h = "0123456789abcdef";
    for (int i = 0; i < 20; ++i) {
        key[i * 2] = h[(item.state20[i] >> 4) & 15];
        key[i * 2 + 1] = h[item.state20[i] & 15];
        key[40 + i * 2] = h[(item.aux20[i] >> 4) & 15];
        key[40 + i * 2 + 1] = h[item.aux20[i] & 15];
    }
    key[80] = '\0';
    if (!seen.insert(key).second) {
        return;
    }

    const size_t n = std::min<size_t>(label.size(), XP_CGR_LABEL_MAX);
    if (n != 0u) {
        memcpy(item.label, label.data(), n);
        item.label_len = static_cast<uint8_t>(n);
    }
    out.push_back(item);
}

static bool xp_add_cgr_chain_observed_input(
    std::vector<XpCgrStateInput>& out,
    std::unordered_set<std::string>& seen,
    const std::string& label,
    const std::string& state_hex,
    const std::vector<std::pair<std::string, std::string>>& transitions,
    const bool bridge_chain)
{
    if (transitions.empty() || transitions.size() > XP_CGR_CHAIN_MAX) {
        return false;
    }

    std::string parse_err;
    XpCgrStateInput item{};
    if (!wallet_hex_to_fixed(state_hex, item.state20, 20u, parse_err)) {
        return false;
    }

    std::string key = state_hex;
    for (size_t i = 0u; i < transitions.size(); ++i) {
        if (!wallet_hex_to_fixed(transitions[i].first, item.chain_aux20[i], 20u, parse_err)) {
            return false;
        }
        key += ":";
        key += transitions[i].first;
        if (bridge_chain) {
            if (!wallet_hex_to_fixed(transitions[i].second, item.chain_prefix20[i], 20u, parse_err)) {
                return false;
            }
            item.xor_mask |= static_cast<uint8_t>(1u << i);
            key += ":";
            key += transitions[i].second;
        }
        if (i == 0u) {
            memcpy(item.aux20, item.chain_aux20[0], 20u);
            memcpy(item.outbuf_prefix20, item.chain_prefix20[0], 20u);
        }
    }
    if (!seen.insert(key).second) {
        return false;
    }

    item.transition_count = static_cast<uint8_t>(transitions.size());
    const size_t n = std::min<size_t>(label.size(), XP_CGR_LABEL_MAX);
    if (n != 0u) {
        memcpy(item.label, label.data(), n);
        item.label_len = static_cast<uint8_t>(n);
    }
    out.push_back(item);
    return true;
}

static bool xp_scan_context_is_checksum(const std::string& lower_line, const size_t run_start)
{
    const size_t begin = (run_start > 24u) ? run_start - 24u : 0u;
    const std::string prefix = lower_line.substr(begin, run_start - begin);
    return prefix.find("sha256") != std::string::npos ||
        prefix.find("sha-256") != std::string::npos ||
        prefix.find("checksum") != std::string::npos;
}

static bool xp_source_scan_binary_raw32(
    const std::string& file,
    std::vector<XpCgrStateInput>& out,
    std::unordered_set<std::string>& seen,
    const size_t label_index)
{
    std::ifstream in(file, std::ios::binary);
    if (!in) {
        return false;
    }
    tune_ifstream_buffer(in);
    print_opened_input_file(file);
    uint8_t raw32[32];
    in.read(reinterpret_cast<char*>(raw32), sizeof(raw32));
    if (in.gcount() != static_cast<std::streamsize>(sizeof(raw32))) {
        return false;
    }
    char hexbuf[65];
    static const char* h = "0123456789abcdef";
    for (int i = 0; i < 32; ++i) {
        hexbuf[i * 2] = h[(raw32[i] >> 4) & 15];
        hexbuf[i * 2 + 1] = h[raw32[i] & 15];
    }
    hexbuf[64] = '\0';
    std::ostringstream label;
    label << "bin#" << label_index;
    xp_add_raw32_observed_input(out, seen, label.str(), hexbuf);
    return true;
}

static size_t xp_source_scan_raw32_dirs(std::vector<XpCgrStateInput>& out)
{
    std::vector<std::string> files;
    for (const std::string& root : xp_artifact_dirs) {
        xp_collect_source_scan_files(root, files);
    }
    std::sort(files.begin(), files.end());
    files.erase(std::unique(files.begin(), files.end()), files.end());

    std::unordered_set<std::string> seen;
    for (const XpCgrStateInput& existing : out) {
        char hexbuf[65];
        static const char* h = "0123456789abcdef";
        uint8_t raw32[32];
        memcpy(raw32, existing.state20, 20u);
        memcpy(raw32 + 20u, existing.aux20, 12u);
        for (int i = 0; i < 32; ++i) {
            hexbuf[i * 2] = h[(raw32[i] >> 4) & 15];
            hexbuf[i * 2 + 1] = h[raw32[i] & 15];
        }
        hexbuf[64] = '\0';
        seen.insert(hexbuf);
    }

    const size_t before = out.size();
    for (const std::string& file : files) {
        std::string lower_file = file;
        std::transform(lower_file.begin(), lower_file.end(), lower_file.begin(), [](unsigned char c) {
            return static_cast<char>(std::tolower(c));
            });
        if (lower_file.size() >= 4u && lower_file.substr(lower_file.size() - 4u) == ".bin") {
            xp_source_scan_binary_raw32(file, out, seen, out.size() - before);
            continue;
        }
        std::ifstream in(file, std::ios::binary);
        if (!in) {
            continue;
        }
        tune_ifstream_buffer(in);
        print_opened_input_file(file);
        std::string line;
        size_t line_no = 0u;
        uint32_t output_marker_window = 0u;
        while (std::getline(in, line)) {
            ++line_no;
            if (!line.empty() && line.back() == '\r') line.pop_back();
            std::string lower_line = line;
            std::transform(lower_line.begin(), lower_line.end(), lower_line.begin(), [](unsigned char c) {
                return static_cast<char>(std::tolower(c));
                });
            const bool line_has_output_marker = xp_source_scan_line_has_output_marker(lower_line);
            if (line_has_output_marker) {
                output_marker_window = 8u;
            }
            else if (output_marker_window == 0u) {
                continue;
            }
            std::string run;
            size_t run_start = 0u;
            auto flush_run = [&]() {
                if (run.size() >= 64u && !xp_scan_context_is_checksum(lower_line, run_start)) {
                    std::ostringstream label;
                    label << "src#" << (out.size() - before) << ":" << line_no;
                    xp_add_raw32_observed_input_chunks(out, seen, label.str(), run);
                }
                run.clear();
            };
            for (size_t ci = 0u; ci < line.size(); ++ci) {
                const char c = line[ci];
                if (std::isxdigit(static_cast<unsigned char>(c))) {
                    if (run.empty()) {
                        run_start = ci;
                    }
                    run.push_back(c);
                    if (run.size() > 4096u) {
                        flush_run();
                    }
                }
                else {
                    flush_run();
                }
            }
            flush_run();
            if (!line_has_output_marker && output_marker_window != 0u) {
                --output_marker_window;
            }
        }
    }
    return out.size() - before;
}

static bool xp_read_exact_hex_file(const std::string& path, const size_t bytes, std::string& hex_out);

static bool xp_cgr_scan_get_hex20(
    const std::unordered_map<std::string, std::string>& files,
    const std::initializer_list<const char*>& names,
    std::string& out_hex)
{
    for (const char* name : names) {
        auto it = files.find(name);
        if (it != files.end()) {
            out_hex = it->second;
            return true;
        }
    }
    return false;
}

static size_t xp_source_scan_cgr_transition_dirs(std::vector<XpCgrStateInput>& out)
{
    std::vector<std::string> files;
    for (const std::string& root : xp_artifact_dirs) {
        xp_collect_all_regular_files(root, files);
    }
    std::sort(files.begin(), files.end());
    files.erase(std::unique(files.begin(), files.end()), files.end());

    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> by_dir;
    for (const std::string& file : files) {
        std::string lower_file = file;
        std::transform(lower_file.begin(), lower_file.end(), lower_file.begin(), [](unsigned char c) {
            return static_cast<char>(std::tolower(c));
            });
        if (lower_file.size() < 4u || lower_file.substr(lower_file.size() - 4u) != ".bin") {
            continue;
        }
        const size_t slash = file.find_last_of('/');
        const std::string dir = (slash == std::string::npos) ? std::string() : file.substr(0u, slash);
        const std::string name = (slash == std::string::npos) ? lower_file : lower_file.substr(slash + 1u);
        std::string hex20;
        if (!xp_read_exact_hex_file(file, 20u, hex20)) {
            continue;
        }
        by_dir[dir][name] = hex20;
    }

    std::unordered_set<std::string> seen;
    for (const XpCgrStateInput& existing : out) {
        char key[(1 + XP_CGR_CHAIN_MAX * 2) * 40 + 16];
        static const char* h = "0123456789abcdef";
        size_t pos = 0u;
        auto append20 = [&](const uint8_t bytes[20]) {
            for (int i = 0; i < 20; ++i) {
                key[pos++] = h[(bytes[i] >> 4) & 15];
                key[pos++] = h[bytes[i] & 15];
            }
        };
        append20(existing.state20);
        const uint8_t count = (existing.transition_count == 0u) ? 1u : existing.transition_count;
        for (uint8_t ti = 0u; ti < count && ti < XP_CGR_CHAIN_MAX; ++ti) {
            key[pos++] = ':';
            append20(existing.chain_aux20[ti]);
            if (existing.xor_mask & (1u << ti)) {
                key[pos++] = ':';
                append20(existing.chain_prefix20[ti]);
            }
        }
        key[pos] = '\0';
        seen.insert(key);
    }

    const size_t before = out.size();
    const bool bridge_profile = (xp_profile_kind == XP_PROFILE_CGR_BRIDGE ||
        xp_profile_kind == XP_PROFILE_CGR_XOR ||
        xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE);
    const bool chain_profile = (xp_profile_kind == XP_PROFILE_CGR_CHAIN ||
        xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE);

    for (const auto& dir_entry : by_dir) {
        const auto& m = dir_entry.second;
        std::string state_hex;
        if (!xp_cgr_scan_get_hex20(m, { "init_state20_before.bin", "state20_before.bin", "state20.bin" }, state_hex)) {
            continue;
        }

        if (chain_profile) {
            std::vector<std::pair<std::string, std::string>> transitions;
            static const char* chain_prefixes[] = { "init_", "bridge00_", "bridge01_", "runtime_" };
            for (const char* prefix : chain_prefixes) {
                std::string raw_hex;
                std::string prefix_hex;
                if (bridge_profile) {
                    const std::string raw_name = std::string(prefix) + "sysfunc036_raw20.bin";
                    const std::string prefix_name = std::string(prefix) + "outbuf_prefix20.bin";
                    auto ri = m.find(raw_name);
                    auto pi = m.find(prefix_name);
                    if (ri == m.end() || pi == m.end()) {
                        continue;
                    }
                    raw_hex = ri->second;
                    prefix_hex = pi->second;
                }
                else {
                    const std::string aux_final_name = std::string(prefix) + "aux20_final.bin";
                    const std::string aux_name = std::string(prefix) + "aux20.bin";
                    auto ai = m.find(aux_final_name);
                    if (ai == m.end()) {
                        ai = m.find(aux_name);
                    }
                    if (ai == m.end()) {
                        continue;
                    }
                    raw_hex = ai->second;
                }
                transitions.emplace_back(raw_hex, prefix_hex);
                if (transitions.size() >= XP_CGR_CHAIN_MAX) {
                    break;
                }
            }
            if (!transitions.empty()) {
                std::ostringstream label;
                label << "src-cgr-chain#" << (out.size() - before);
                xp_add_cgr_chain_observed_input(out, seen, label.str(), state_hex, transitions, bridge_profile);
            }
            continue;
        }

        if (bridge_profile) {
            static const char* prefixes[] = { "", "init_", "bridge00_", "bridge01_", "runtime_" };
            for (const char* prefix : prefixes) {
                std::string local_state_hex = state_hex;
                if (prefix[0] != '\0') {
                    const std::string state_name = std::string(prefix) + "state20_before.bin";
                    auto si = m.find(state_name);
                    if (si != m.end()) {
                        local_state_hex = si->second;
                    }
                }
                std::string raw_hex;
                std::string prefix_hex;
                if (prefix[0] == '\0') {
                    if (!xp_cgr_scan_get_hex20(m, { "sysfunc036_raw20.bin", "raw20.bin", "src20.bin" }, raw_hex) ||
                        !xp_cgr_scan_get_hex20(m, { "outbuf_prefix20.bin", "prefix20.bin", "local_before.bin" }, prefix_hex)) {
                        continue;
                    }
                }
                else {
                    const std::string raw_name = std::string(prefix) + "sysfunc036_raw20.bin";
                    const std::string prefix_name = std::string(prefix) + "outbuf_prefix20.bin";
                    auto ri = m.find(raw_name);
                    auto pi = m.find(prefix_name);
                    if (ri == m.end() || pi == m.end()) {
                        continue;
                    }
                    raw_hex = ri->second;
                    prefix_hex = pi->second;
                }

                std::ostringstream label;
                label << "src-cgr-bridge#" << (out.size() - before);
                std::vector<std::pair<std::string, std::string>> one;
                one.emplace_back(raw_hex, prefix_hex);
                xp_add_cgr_chain_observed_input(out, seen, label.str(), local_state_hex, one, true);
            }
        }
    }

    return out.size() - before;
}

static bool xp_read_exact_hex_file(const std::string& path, const size_t bytes, std::string& hex_out)
{
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        return false;
    }
    tune_ifstream_buffer(in);
    std::vector<uint8_t> buf(bytes);
    in.read(reinterpret_cast<char*>(buf.data()), static_cast<std::streamsize>(bytes));
    if (in.gcount() != static_cast<std::streamsize>(bytes)) {
        return false;
    }
    char tmp[41];
    static const char* h = "0123456789abcdef";
    for (size_t i = 0; i < bytes; ++i) {
        tmp[i * 2] = h[(buf[i] >> 4) & 15];
        tmp[i * 2 + 1] = h[buf[i] & 15];
    }
    tmp[bytes * 2] = '\0';
    hex_out.assign(tmp, bytes * 2);
    return true;
}

static bool xp_extract_jsonish_hex_field(
    const std::string& line,
    const std::string& lower_line,
    const char* key,
    const char* quoted_key,
    std::string& out_hex)
{
    size_t pos = lower_line.find(quoted_key);
    if (pos == std::string::npos) {
        pos = lower_line.find(key);
    }
    if (pos == std::string::npos) {
        return false;
    }
    pos = lower_line.find(':', pos);
    if (pos == std::string::npos) {
        return false;
    }
    ++pos;
    while (pos < line.size() && (std::isspace(static_cast<unsigned char>(line[pos])) || line[pos] == '"' || line[pos] == '\'')) {
        ++pos;
    }
    char hex[41];
    size_t hex_len = 0u;
    while (pos < line.size()) {
        const char c = line[pos];
        if (!std::isxdigit(static_cast<unsigned char>(c))) {
            break;
        }
        if (hex_len < 40u) {
            hex[hex_len] = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        }
        ++hex_len;
        ++pos;
    }
    if (hex_len < 40u) {
        return false;
    }
    out_hex.assign(hex, 40u);
    return true;
}

struct XpJsonishHexKey {
    const char* key;
    const char* quoted_key;
};

static size_t xp_source_scan_cgr_state_dirs(std::vector<XpCgrStateInput>& out)
{
    std::vector<std::string> files;
    for (const std::string& root : xp_artifact_dirs) {
        xp_collect_all_regular_files(root, files);
    }
    std::sort(files.begin(), files.end());
    files.erase(std::unique(files.begin(), files.end()), files.end());

    std::unordered_set<std::string> seen;
    for (const XpCgrStateInput& existing : out) {
        char key[81];
        static const char* h = "0123456789abcdef";
        for (int i = 0; i < 20; ++i) {
            key[i * 2] = h[(existing.state20[i] >> 4) & 15];
            key[i * 2 + 1] = h[existing.state20[i] & 15];
            key[40 + i * 2] = h[(existing.aux20[i] >> 4) & 15];
            key[40 + i * 2 + 1] = h[existing.aux20[i] & 15];
        }
        key[80] = '\0';
        seen.insert(key);
    }

    const size_t before = out.size();

    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> by_dir;
    for (const std::string& file : files) {
        std::string lower_file = file;
        std::transform(lower_file.begin(), lower_file.end(), lower_file.begin(), [](unsigned char c) {
            return static_cast<char>(std::tolower(c));
            });
        if (lower_file.size() < 4u || lower_file.substr(lower_file.size() - 4u) != ".bin") {
            continue;
        }
        const size_t slash = file.find_last_of('/');
        const std::string dir = (slash == std::string::npos) ? std::string() : file.substr(0u, slash);
        const std::string name = (slash == std::string::npos) ? lower_file : lower_file.substr(slash + 1u);
        std::string hex20;
        if (!xp_read_exact_hex_file(file, 20u, hex20)) {
            continue;
        }
        by_dir[dir][name] = hex20;
    }

    static const char* prefixes[] = { "", "init_", "bridge00_", "runtime_" };
    for (const auto& dir_entry : by_dir) {
        const auto& m = dir_entry.second;
        auto add_pair = [&](const std::string& state_name, const std::string& aux_name, const std::string& label) {
            auto si = m.find(state_name);
            auto ai = m.find(aux_name);
            if (si != m.end() && ai != m.end()) {
                xp_add_cgr_state_observed_input(out, seen, label, si->second, ai->second);
            }
        };
        add_pair("state20_entry.bin", "aux20_entry.bin", "fips_entry");
        add_pair("state20_before.bin", "aux20_final.bin", "provider_final");
        add_pair("state20_before.bin", "aux20.bin", "provider_aux");
        add_pair("state20.bin", "aux20.bin", "provider_state_aux");
        for (const char* prefix : prefixes) {
            if (prefix[0] == '\0') continue;
            add_pair(std::string(prefix) + "state20_before.bin", std::string(prefix) + "aux20_final.bin", prefix);
            add_pair(std::string(prefix) + "state20_before.bin", std::string(prefix) + "aux20.bin", std::string(prefix) + "aux");
        }
    }

    static const XpJsonishHexKey state_keys[] = {
        { "state20_before_fips", "\"state20_before_fips\"" },
        { "state20_before", "\"state20_before\"" },
        { "runtime_state20_before", "\"runtime_state20_before\"" },
        { "bridge00_state20_before", "\"bridge00_state20_before\"" },
        { "init_state20_before", "\"init_state20_before\"" }
    };
    static const XpJsonishHexKey aux_keys[] = {
        { "fips_arg2_aux20", "\"fips_arg2_aux20\"" },
        { "aux20_final", "\"aux20_final\"" },
        { "runtime_aux20_final", "\"runtime_aux20_final\"" },
        { "bridge00_aux20_final", "\"bridge00_aux20_final\"" },
        { "init_aux20_final", "\"init_aux20_final\"" },
        { "aux20", "\"aux20\"" }
    };
    for (const std::string& file : files) {
        std::string lower_file = file;
        std::transform(lower_file.begin(), lower_file.end(), lower_file.begin(), [](unsigned char c) {
            return static_cast<char>(std::tolower(c));
            });
        if (lower_file.size() >= 4u && lower_file.substr(lower_file.size() - 4u) == ".bin") {
            continue;
        }
        std::ifstream in(file, std::ios::binary);
        if (!in) {
            continue;
        }
        tune_ifstream_buffer(in);
        print_opened_input_file(file);
        std::string line;
        size_t line_no = 0u;
        while (std::getline(in, line)) {
            ++line_no;
            if (!line.empty() && line.back() == '\r') line.pop_back();
            std::string lower_line = line;
            std::transform(lower_line.begin(), lower_line.end(), lower_line.begin(), [](unsigned char c) {
                return static_cast<char>(std::tolower(c));
                });
            std::string state_hex, aux_hex;
            for (const XpJsonishHexKey& key : state_keys) {
                if (xp_extract_jsonish_hex_field(line, lower_line, key.key, key.quoted_key, state_hex)) break;
            }
            for (const XpJsonishHexKey& key : aux_keys) {
                if (xp_extract_jsonish_hex_field(line, lower_line, key.key, key.quoted_key, aux_hex)) break;
            }
            if (state_hex.size() == 40u && aux_hex.size() == 40u) {
                std::ostringstream label;
                label << "src-cgr#" << (out.size() - before) << ":" << line_no;
                xp_add_cgr_state_observed_input(out, seen, label.str(), state_hex, aux_hex);
            }
        }
    }

    return out.size() - before;
}

static bool xp_load_cgr_state_inputs(std::vector<XpCgrStateInput>& out, std::string& err)
{
    out.clear();
    auto looks_hex_n = [](const std::string& value, const size_t bytes) -> bool {
        size_t n = 0;
        for (char c : value) {
            if (std::isxdigit(static_cast<unsigned char>(c))) {
                ++n;
            }
        }
        return n == bytes * 2u;
    };
    auto set_transition = [&](XpCgrStateInput& item, const uint32_t index,
        const std::string& raw_hex, const std::string& prefix_hex, const bool use_xor,
        const std::string& file, const size_t line_no, std::string& parse_err) -> bool {
        if (index >= XP_CGR_CHAIN_MAX) {
            std::ostringstream oss;
            oss << file << ":" << line_no << ": too many CGR transitions, max " << XP_CGR_CHAIN_MAX;
            err = oss.str();
            return false;
        }
        if (!wallet_hex_to_fixed(raw_hex, item.chain_aux20[index], 20u, parse_err)) {
            std::ostringstream oss;
            oss << file << ":" << line_no << ": invalid aux/raw20 at transition " << index << ": " << parse_err;
            err = oss.str();
            return false;
        }
        if (use_xor) {
            if (!wallet_hex_to_fixed(prefix_hex, item.chain_prefix20[index], 20u, parse_err)) {
                std::ostringstream oss;
                oss << file << ":" << line_no << ": invalid prefix/src20 at transition " << index << ": " << parse_err;
                err = oss.str();
                return false;
            }
            item.xor_mask |= static_cast<uint8_t>(1u << index);
        }
        if (index == 0u) {
            memcpy(item.aux20, item.chain_aux20[0], 20u);
            memcpy(item.outbuf_prefix20, item.chain_prefix20[0], 20u);
        }
        return true;
    };
    std::vector<std::string> input_files = mnemonicFiles;

    for (const std::string& file : input_files) {
        std::ifstream in(file);
        if (!in) {
            err = "cannot open -i file: " + file;
            return false;
        }
        tune_ifstream_buffer(in);
        print_opened_input_file(file);
        std::string line;
        size_t line_no = 0;
        while (std::getline(in, line)) {
            ++line_no;
            if (!line.empty() && line.back() == '\r') line.pop_back();
            line = wallet_trim_copy(line);
            if (line.empty() || line[0] == '#') continue;
            if (xp_profile_kind == XP_PROFILE_RAW32) {
                bool handled_json_after = false;
                if (!xp_try_add_raw32_json_after_input(out, file, line_no, line, handled_json_after, err)) {
                    return false;
                }
                if (handled_json_after) {
                    continue;
                }
            }
            std::vector<std::string> parts;
            size_t start = 0;
            while (true) {
                const size_t pos = line.find(':', start);
                if (pos == std::string::npos) {
                    parts.push_back(line.substr(start));
                    break;
                }
                parts.push_back(line.substr(start, pos - start));
                start = pos + 1;
            }
            XpCgrStateInput item{};
            std::string parse_err;
            std::string label;
            if (xp_profile_kind == XP_PROFILE_RAW32) {
                size_t raw_index = 0u;
                if (!parts.empty() && !looks_hex_n(parts[0], 32u) && !looks_hex_n(parts[0], 40u)) {
                    label = parts[0];
                    raw_index = 1u;
                }
                if (parts.size() != raw_index + 1u) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": expected raw32/output32 or label:raw32/output32";
                    err = oss.str();
                    return false;
                }
                std::string clean;
                clean.reserve(parts[raw_index].size());
                for (char c : parts[raw_index]) {
                    if (std::isxdigit(static_cast<unsigned char>(c))) {
                        clean.push_back(c);
                    }
                }
                if (clean.size() == 65u && clean[0] == '0') {
                    clean.erase(0, 1);
                }
                if (clean.size() != 64u && clean.size() != 80u) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": raw32 expects 32 bytes or out40 expects 40 bytes, got " << (clean.size() / 2u) << " bytes";
                    err = oss.str();
                    return false;
                }
                uint8_t raw32[32];
                if (!wallet_hex_to_fixed(clean.substr(0, 64u), raw32, 32u, parse_err)) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid raw32: " << parse_err;
                    err = oss.str();
                    return false;
                }
                memcpy(item.state20, raw32, 20u);
                memcpy(item.aux20, raw32 + 20u, 12u);
                item.transition_count = 0u;
                if (!label.empty()) {
                    const size_t n = std::min<size_t>(label.size(), XP_CGR_LABEL_MAX);
                    memcpy(item.label, label.data(), n);
                    item.label_len = static_cast<uint8_t>(n);
                }
                out.push_back(item);
                continue;
            }
            size_t state_index = 0u;
            if (!parts.empty() && !looks_hex_n(parts[0], 20u)) {
                label = parts[0];
                state_index = 1u;
            }
            if (parts.size() <= state_index) {
                std::ostringstream oss;
                oss << file << ":" << line_no << ": missing state20";
                err = oss.str();
                return false;
            }
            const std::string& state_hex = parts[state_index];
            if (!wallet_hex_to_fixed(state_hex, item.state20, 20u, parse_err)) {
                std::ostringstream oss;
                oss << file << ":" << line_no << ": invalid state20: " << parse_err;
                err = oss.str();
                return false;
            }

            const size_t first = state_index + 1u;
            if (xp_profile_kind == XP_PROFILE_CGR_BRIDGE || xp_profile_kind == XP_PROFILE_CGR_XOR) {
                if (parts.size() != first + 2u) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": expected state20:raw20:prefix20 or label:state20:raw20:prefix20";
                    err = oss.str();
                    return false;
                }
                if (!set_transition(item, 0u, parts[first], parts[first + 1u], true, file, line_no, parse_err)) {
                    return false;
                }
                item.transition_count = 1u;
            }
            else if (xp_profile_kind == XP_PROFILE_CGR_CHAIN || xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE) {
                const bool bridge_chain = (xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE);
                const size_t remaining = parts.size() - first;
                if (remaining == 0u || remaining > (bridge_chain ? XP_CGR_CHAIN_MAX * 2u : XP_CGR_CHAIN_MAX) ||
                    (bridge_chain && ((remaining & 1u) != 0u))) {
                    std::ostringstream oss;
                    if (bridge_chain) {
                        oss << file << ":" << line_no << ": expected state20:raw20:prefix20[:raw20:prefix20...], max " << XP_CGR_CHAIN_MAX << " transitions";
                    }
                    else {
                        oss << file << ":" << line_no << ": expected state20:aux20[:aux20...], max " << XP_CGR_CHAIN_MAX << " transitions";
                    }
                    err = oss.str();
                    return false;
                }
                const uint32_t transition_count = bridge_chain
                    ? static_cast<uint32_t>(remaining / 2u)
                    : static_cast<uint32_t>(remaining);
                for (uint32_t ti = 0u; ti < transition_count; ++ti) {
                    const size_t raw_pos = first + (bridge_chain ? ti * 2u : ti);
                    const std::string empty_prefix;
                    const std::string& prefix = bridge_chain ? parts[raw_pos + 1u] : empty_prefix;
                    if (!set_transition(item, ti, parts[raw_pos], prefix, bridge_chain, file, line_no, parse_err)) {
                        return false;
                    }
                }
                item.transition_count = static_cast<uint8_t>(transition_count);
            }
            else {
                if (parts.size() != first + 1u) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": expected state20:aux20 or label:state20:aux20";
                    err = oss.str();
                    return false;
                }
                if (!set_transition(item, 0u, parts[first], std::string(), false, file, line_no, parse_err)) {
                    return false;
                }
                item.transition_count = 1u;
            }
            if (!label.empty()) {
                const size_t n = std::min<size_t>(label.size(), XP_CGR_LABEL_MAX);
                memcpy(item.label, label.data(), n);
                item.label_len = static_cast<uint8_t>(n);
            }
            out.push_back(item);
        }
    }
    if (xp_profile_kind == XP_PROFILE_RAW32 && !xp_artifact_dirs.empty()) {
        const size_t added = xp_source_scan_raw32_dirs(out);
        printf("[!] XP raw32 source scan: %zu entr%s loaded from %zu director%s [!]\n",
            added,
            added == 1u ? "y" : "ies",
            xp_artifact_dirs.size(),
            xp_artifact_dirs.size() == 1u ? "y" : "ies");
    }
    else if (xp_profile_kind == XP_PROFILE_CGR_STATE && !xp_artifact_dirs.empty()) {
        const size_t added = xp_source_scan_cgr_state_dirs(out);
        printf("[!] XP cgr-state source scan: %zu entr%s loaded from %zu director%s [!]\n",
            added,
            added == 1u ? "y" : "ies",
            xp_artifact_dirs.size(),
            xp_artifact_dirs.size() == 1u ? "y" : "ies");
    }
    else if ((xp_profile_kind == XP_PROFILE_CGR_BRIDGE || xp_profile_kind == XP_PROFILE_CGR_XOR ||
        xp_profile_kind == XP_PROFILE_CGR_CHAIN || xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE) &&
        !xp_artifact_dirs.empty()) {
        const size_t added = xp_source_scan_cgr_transition_dirs(out);
        printf("[!] XP %s source scan: %zu entr%s loaded from %zu director%s [!]\n",
            (xp_profile_kind == XP_PROFILE_CGR_BRIDGE) ? "cgr-bridge" :
            (xp_profile_kind == XP_PROFILE_CGR_XOR) ? "cgr-xor" :
            (xp_profile_kind == XP_PROFILE_CGR_CHAIN) ? "cgr-chain" : "cgr-chain-bridge",
            added,
            added == 1u ? "y" : "ies",
            xp_artifact_dirs.size(),
            xp_artifact_dirs.size() == 1u ? "y" : "ies");
    }
    if (out.empty()) {
        err = ((xp_profile_kind == XP_PROFILE_RAW32 || xp_profile_kind == XP_PROFILE_CGR_STATE ||
            xp_profile_kind == XP_PROFILE_CGR_BRIDGE || xp_profile_kind == XP_PROFILE_CGR_XOR ||
            xp_profile_kind == XP_PROFILE_CGR_CHAIN || xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE) &&
            !xp_artifact_dirs.empty())
            ? "no XP source-grounded entries loaded from -i/-f"
            : "no CGR replay entries loaded from -i";
        return false;
    }
    return true;
}

static bool xp_hex_to_vec_field(const std::string& value, std::vector<uint8_t>& out, std::string& err)
{
    std::string clean;
    clean.reserve(value.size());
    for (char c : value) {
        if (std::isxdigit(static_cast<unsigned char>(c))) {
            clean.push_back(c);
        }
    }
    if ((clean.size() & 1u) != 0u) {
        err = "odd-length hex field";
        return false;
    }
    out.assign(clean.size() / 2u, 0u);
    for (size_t i = 0; i < out.size(); ++i) {
        const int hi = hex_nibble_value(clean[i * 2u]);
        const int lo = hex_nibble_value(clean[i * 2u + 1u]);
        if (hi < 0 || lo < 0) {
            err = "non-hex character";
            return false;
        }
        out[i] = static_cast<uint8_t>((hi << 4) | lo);
    }
    return true;
}

static bool xp_copy_exact_field(const std::vector<uint8_t>& src, uint8_t* dst, size_t n, std::string& err)
{
    if (src.size() != n) {
        std::ostringstream oss;
        oss << "expected " << n << " bytes, got " << src.size();
        err = oss.str();
        return false;
    }
    memcpy(dst, src.data(), n);
    return true;
}

struct XpSsleayIterHost {
    std::array<uint8_t, 20> local_md{};
    std::array<uint8_t, 8> md_c{};
    std::array<uint8_t, XP_SSLEAY_SLICE_LEN> input_buf{};
    std::array<uint8_t, XP_SSLEAY_SLICE_LEN> logged_state{};
    uint8_t input_len = 0u;
    bool has_local_md = false;
    bool has_md_c = false;
    bool has_buf = false;
    bool has_state = false;
};

static bool xp_load_ssleay_inputs(std::vector<XpSsleayInput>& out, std::string& err)
{
    out.clear();
    std::vector<std::string> sources = mnemonicFiles;
    const size_t explicit_source_count = sources.size();
    if (!xp_artifact_dirs.empty()) {
        std::vector<std::string> dir_files;
        for (const std::string& root : xp_artifact_dirs) {
            xp_collect_all_regular_files(root, dir_files);
        }
        for (const std::string& file : dir_files) {
            std::string lower_file = file;
            std::transform(lower_file.begin(), lower_file.end(), lower_file.begin(), [](unsigned char c) {
                return static_cast<char>(std::tolower(c));
                });
            const size_t slash = lower_file.find_last_of('/');
            const std::string name = (slash == std::string::npos) ? lower_file : lower_file.substr(slash + 1u);
            if (name == "ssleay_stir_randbytes_trace.jsonl") {
                sources.push_back(file);
            }
        }
    }
    std::sort(sources.begin(), sources.end());
    sources.erase(std::unique(sources.begin(), sources.end()), sources.end());
    if (!xp_artifact_dirs.empty()) {
        const size_t scanned_source_count = sources.size() > explicit_source_count
            ? sources.size() - explicit_source_count
            : 0u;
        printf("[!] XP ssleay-stir source scan: %zu trace file%s loaded from %zu director%s [!]\n",
            scanned_source_count,
            scanned_source_count == 1u ? "" : "s",
            xp_artifact_dirs.size(),
            xp_artifact_dirs.size() == 1u ? "y" : "ies");
    }
    if (sources.empty()) {
        err = "no ssleay-stir trace files provided by -i/-f";
        return false;
    }
    for (const std::string& file : sources) {
        std::ifstream in(file);
        if (!in) {
            err = "cannot open -i file: " + file;
            return false;
        }
        tune_ifstream_buffer(in);
        print_opened_input_file(file);
        std::vector<uint8_t> state_after_stir;
        uint32_t selected_index = UINT32_MAX;
        std::vector<XpSsleayIterHost> iterations;
        XpSsleayIterHost current{};
        bool current_used = false;

        auto flush_current = [&]() {
            if (current_used) {
                iterations.push_back(current);
                current = XpSsleayIterHost{};
                current_used = false;
            }
        };

        std::string line;
        size_t line_no = 0;
        while (std::getline(in, line)) {
            ++line_no;
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.find("\"stage\"") == std::string::npos) continue;
            std::string stage;
            if (!wallet_json_get_string(line, "stage", stage)) continue;

            if (stage == "state_after_stir") {
                std::string data;
                if (!wallet_json_get_string(line, "data", data) || !xp_hex_to_vec_field(data, state_after_stir, err)) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid state_after_stir";
                    err = oss.str();
                    return false;
                }
                continue;
            }
            if (stage == "state_index_after_stir") {
                if (!wallet_json_get_u32(line, "value", selected_index)) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid state_index_after_stir";
                    err = oss.str();
                    return false;
                }
                continue;
            }

            std::string data;
            std::vector<uint8_t> bytes;
            if (stage == "rand_bytes_iter_0_input_local_md") {
                flush_current();
                if (!wallet_json_get_string(line, "data", data) || !xp_hex_to_vec_field(data, bytes, err) ||
                    !xp_copy_exact_field(bytes, current.local_md.data(), 20u, err)) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid local_md";
                    err = oss.str();
                    return false;
                }
                current.has_local_md = true;
                current_used = true;
            }
            else if (stage == "rand_bytes_iter_0_input_md_c") {
                if (!wallet_json_get_string(line, "data", data) || !xp_hex_to_vec_field(data, bytes, err) ||
                    !xp_copy_exact_field(bytes, current.md_c.data(), 8u, err)) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid md_c";
                    err = oss.str();
                    return false;
                }
                current.has_md_c = true;
                current_used = true;
            }
            else if (stage == "rand_bytes_iter_0_input_buf") {
                if (!wallet_json_get_string(line, "data", data) || !xp_hex_to_vec_field(data, bytes, err) ||
                    bytes.empty() || bytes.size() > XP_SSLEAY_SLICE_LEN) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid input_buf length";
                    err = oss.str();
                    return false;
                }
                std::fill(current.input_buf.begin(), current.input_buf.end(), 0u);
                memcpy(current.input_buf.data(), bytes.data(), bytes.size());
                current.input_len = static_cast<uint8_t>(bytes.size());
                current.has_buf = true;
                current_used = true;
            }
            else if (stage == "rand_bytes_iter_state") {
                if (!wallet_json_get_string(line, "data", data) || !xp_hex_to_vec_field(data, bytes, err) ||
                    !xp_copy_exact_field(bytes, current.logged_state.data(), XP_SSLEAY_SLICE_LEN, err)) {
                    std::ostringstream oss;
                    oss << file << ":" << line_no << ": invalid iter_state";
                    err = oss.str();
                    return false;
                }
                current.has_state = true;
                current_used = true;
            }
        }
        flush_current();

        if (iterations.size() < XP_SSLEAY_ITERATIONS) {
            std::ostringstream oss;
            oss << file << ": expected at least " << XP_SSLEAY_ITERATIONS << " ssleay iterations";
            err = oss.str();
            return false;
        }
        if (selected_index == UINT32_MAX && state_after_stir.empty()) {
            err = file + ": missing state_after_stir/state_index_after_stir";
            return false;
        }

        XpSsleayInput item{};
        item.iter_count = XP_SSLEAY_ITERATIONS;
        item.out_len = 32u;
        const std::string label = std::string("ssleay:") + file;
        const size_t label_n = std::min<size_t>(label.size(), XP_CGR_LABEL_MAX);
        memcpy(item.label, label.data(), label_n);
        item.label_len = static_cast<uint8_t>(label_n);
        for (uint32_t i = 0; i < XP_SSLEAY_ITERATIONS; ++i) {
            const XpSsleayIterHost& it = iterations[i];
            if (!it.has_local_md || !it.has_md_c || !it.has_buf) {
                std::ostringstream oss;
                oss << file << ": incomplete ssleay iteration " << i;
                err = oss.str();
                return false;
            }
            memcpy(item.local_md[i], it.local_md.data(), 20u);
            memcpy(item.md_c[i], it.md_c.data(), 8u);
            memcpy(item.input_buf[i], it.input_buf.data(), XP_SSLEAY_SLICE_LEN);
            item.input_len[i] = it.input_len;
            if (!state_after_stir.empty() && selected_index != UINT32_MAX &&
                static_cast<size_t>(selected_index) + (size_t)i * XP_SSLEAY_SLICE_LEN + XP_SSLEAY_SLICE_LEN <= state_after_stir.size()) {
                memcpy(item.state_slice[i],
                    state_after_stir.data() + static_cast<size_t>(selected_index) + (size_t)i * XP_SSLEAY_SLICE_LEN,
                    XP_SSLEAY_SLICE_LEN);
            }
            else if (it.has_state) {
                memcpy(item.state_slice[i], it.logged_state.data(), XP_SSLEAY_SLICE_LEN);
            }
            else {
                std::ostringstream oss;
                oss << file << ": missing state slice for ssleay iteration " << i;
                err = oss.str();
                return false;
            }
        }
        out.push_back(item);
    }
    if (out.empty()) {
        err = "no ssleay-stir entries loaded from -i/-f";
        return false;
    }
    return true;
}

static uint64_t xp_pybtc_mt_time_count()
{
    // pybtc-mt:ts microsecond timestamp low32 window size (>=1).
    if (walletjs_time_end >= walletjs_time_start) {
        return static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull;
    }
    return 1ull;
}

static uint64_t xp_domain_linear_count()
{
    if (xp_profile_kind == XP_PROFILE_OPENSSL) {
        const uint64_t pid_count = (start_seed <= end_seed)
            ? (static_cast<uint64_t>(end_seed) - static_cast<uint64_t>(start_seed) + 1ull)
            : 0ull;
        return pid_count * static_cast<uint64_t>(xp_path_count) * static_cast<uint64_t>(XP_OPENSSL_ARCH_COUNT);
    }
    if (xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        const bool explicit_time_range = walletjs_time_start_seen && walletjs_time_end_seen;
        const uint64_t time_count = explicit_time_range && walletjs_time_end >= walletjs_time_start
            ? (static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull)
            : 1ull;
        const uint64_t delta_count = static_cast<uint64_t>(walletjs_time_delta_max) + 1ull;
        const uint64_t mileage_count = xp_randstorm_mileage_count_host();
        uint64_t tmp = 0ull;
        uint64_t tmp2 = 0ull;
        uint64_t tmp3 = 0ull;
        uint64_t tmp4 = 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, time_count, tmp) ||
            !mul_u64_checked(tmp, delta_count, tmp2) ||
            !mul_u64_checked(tmp2, static_cast<uint64_t>(n_number), tmp3) ||
            !mul_u64_checked(tmp3, mileage_count, tmp4) ||
            !mul_u64_checked(tmp4, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_RANDSTORM_PYMT) {
        return (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
    }
    if (xp_profile_kind == XP_PROFILE_PHPCOINADDRESS) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_BLUEWALLET_ISAAC) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t linear_state_count = state_count;
        if ((xp_path_mask & (1ull << XP_TIME_LCG_DIRECT_VARIANT_GLIBC_XOR_PID)) != 0u &&
            !mul_u64_checked(state_count, XP_TIME_LCG_DIRECT_XOR_PID_COUNT, linear_state_count)) {
            return 0ull;
        }
        uint64_t total = 0ull;
        if (!mul_u64_checked(linear_state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_TIME_MT) {
        return (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
    }
    if (xp_profile_kind == XP_PROFILE_JAVA_LCG_DIRECT) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_SHA256_DIRECT) {
        if (start_seed64 == 0ull && end_seed64 == std::numeric_limits<uint64_t>::max()) {
            return 0ull;
        }
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_PID_HASH_DIRECT) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_LOWBITS_DIRECT) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_PYBTC_MT) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        // linear = key × time × state × variant  (variant outermost)
        const uint64_t time_count = xp_pybtc_mt_time_mode ? xp_pybtc_mt_time_count() : 1ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, time_count, total)) return 0ull;
        if (!mul_u64_checked(total, n_number, total)) return 0ull;
        if (!mul_u64_checked(total, static_cast<uint64_t>(xp_path_count), total)) return 0ull;
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_NANO_JAVA_RANDOM) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        // linear = key × state × variant  (variant outermost)
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, n_number, total)) return 0ull;
        if (!mul_u64_checked(total, static_cast<uint64_t>(xp_path_count), total)) return 0ull;
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_PYWALLET_TS_WEAK) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        // linear = state × variant  (n forced to 1)
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(xp_path_count), total)) return 0ull;
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_RANDSTORM_BYTES || xp_profile_kind == XP_PROFILE_RANDSTORM_CRYPTO1_JSBN ||
        xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_BYTES ||
        xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_POOL32) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        const uint64_t mileage_count = xp_randstorm_mileage_count_host();
        uint64_t tmp = 0ull;
        uint64_t tmp2 = 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, static_cast<uint64_t>(n_number), tmp) ||
            !mul_u64_checked(tmp, mileage_count, tmp2) ||
            !mul_u64_checked(tmp2, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    if (xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT || xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32) {
        const uint64_t state_count = (start_seed64 <= end_seed64) ? (end_seed64 - start_seed64 + 1ull) : 0ull;
        const bool explicit_time_range = walletjs_time_start_seen && walletjs_time_end_seen;
        const uint64_t time_count = explicit_time_range && walletjs_time_end >= walletjs_time_start
            ? (static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull)
            : 1ull;
        const uint64_t delta_count = static_cast<uint64_t>(walletjs_time_delta_max) + 1ull;
        const uint64_t mileage_count = xp_randstorm_mileage_count_host();
        uint64_t tmp = 0ull;
        uint64_t tmp2 = 0ull;
        uint64_t tmp3 = 0ull;
        uint64_t tmp4 = 0ull;
        uint64_t total = 0ull;
        if (!mul_u64_checked(state_count, time_count, tmp) ||
            !mul_u64_checked(tmp, delta_count, tmp2) ||
            !mul_u64_checked(tmp2, static_cast<uint64_t>(n_number), tmp3) ||
            !mul_u64_checked(tmp3, mileage_count, tmp4) ||
            !mul_u64_checked(tmp4, static_cast<uint64_t>(xp_path_count), total)) {
            return 0ull;
        }
        return total;
    }
    return 0ull;
}

static metalError_t launch_workerXP(
    MetalGridSize grid,
    MetalGridSize block,
    bool* buffIsResult,
    bool* buffDeviceResult,
    const secp256k1_ge_storage* prec,
    const size_t prec_pitch,
    uint8_t profile_kind,
    uint64_t path_mask,
    uint32_t path_count,
    uint32_t pid_start,
    uint32_t pid_count,
    uint32_t keys_per_pid,
    uint64_t linear_start,
    uint64_t linear_count,
    uint64_t randstorm_state_start,
    uint64_t randstorm_state_count,
    uint32_t randstorm_time_start,
    uint32_t randstorm_time_count,
    uint32_t randstorm_delta_count,
    const XpCgrStateInput* cgr_inputs,
    uint32_t cgr_count,
    const XpSsleayInput* ssleay_inputs,
    uint32_t ssleay_count,
    uint32_t input_line_base)
{
    const bool xp_extended_targets =
        Solana || Ton || Ton_all || Dot || Aptos || Sui || Xrp ||
        Exodus || Iota || Ada || Icp || Fil || Xtz || Endomorphism;
    if (profile_kind == XP_PROFILE_BLUEWALLET_ISAAC || xp_extended_targets) {
        metal_launch("workerXP_common", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
        return metalGetLastError();
    }
    if (P2wsh && !Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_p", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
        return metalGetLastError();
    }
    if (P2wsh) {
        metal_launch("workerXP_common", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
        return metalGetLastError();
    }
    if (Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_c", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (!Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_u", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (!Compressed && !Uncompressed && Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_s", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (!Compressed && !Uncompressed && !Segwit && Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_r", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (!Compressed && !Uncompressed && !Segwit && !Taproot && Xpoint && !Ethereum) {
        metal_launch("workerXP_x", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (!Compressed && !Uncompressed && !Segwit && !Taproot && !Xpoint && Ethereum) {
        metal_launch("workerXP_e", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (Compressed && Uncompressed && !Segwit && !Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_cu", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (Compressed && Uncompressed && Segwit && Taproot && !Xpoint && !Ethereum) {
        metal_launch("workerXP_cusr", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else if (Compressed && Uncompressed && Segwit && Taproot && Xpoint && Ethereum) {
        metal_launch("workerXP_cusrxe", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    else {
        metal_launch("workerXP_common", grid, block, p_xp_results, p_xp_count, prec, prec_pitch, profile_kind, path_mask, path_count, pid_start, pid_count, keys_per_pid, linear_start, linear_count, randstorm_state_start, randstorm_state_count, randstorm_time_start, randstorm_time_count, randstorm_delta_count, cgr_inputs, cgr_count, ssleay_inputs, ssleay_count, input_line_base);
    }
    return metalGetLastError();
}

static metalError_t dispatch_xp_multi_gpu()
{
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return processMetalXP();
    }
    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    uint64_t total_linear = 0ull;
    std::vector<XpCgrStateInput> shared_cgr_inputs;
    std::vector<XpSsleayInput> shared_ssleay_inputs;
    if (xp_profile_kind == XP_PROFILE_OPENSSL) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_RANDSTORM_PYMT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_PHPCOINADDRESS) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_BLUEWALLET_ISAAC) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_TIME_MT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_JAVA_LCG_DIRECT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_SHA256_DIRECT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_PID_HASH_DIRECT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_LOWBITS_DIRECT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_PYBTC_MT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_NANO_JAVA_RANDOM) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_PYWALLET_TS_WEAK) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_RANDSTORM_BYTES ||
        xp_profile_kind == XP_PROFILE_RANDSTORM_CRYPTO1_JSBN) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_BYTES ||
        xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_POOL32) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32) {
        total_linear = xp_domain_linear_count();
    }
    else if (xp_profile_kind == XP_PROFILE_CGR_STATE || xp_profile_kind == XP_PROFILE_CGR_BRIDGE ||
        xp_profile_kind == XP_PROFILE_CGR_XOR || xp_profile_kind == XP_PROFILE_CGR_CHAIN ||
        xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE || xp_profile_kind == XP_PROFILE_RAW32) {
        std::string err;
        if (!xp_load_cgr_state_inputs(shared_cgr_inputs, err)) {
            fprintf(stderr, "[!] Error: %s [!]\n", err.c_str());
            return metalErrorInvalidValue;
        }
        total_linear = static_cast<uint64_t>(shared_cgr_inputs.size());
    }
    else if (xp_profile_kind == XP_PROFILE_SSLEAY_STIR) {
        std::string err;
        if (!xp_load_ssleay_inputs(shared_ssleay_inputs, err)) {
            fprintf(stderr, "[!] Error: %s [!]\n", err.c_str());
            return metalErrorInvalidValue;
        }
        total_linear = static_cast<uint64_t>(shared_ssleay_inputs.size());
    }
    if (total_linear == 0ull) {
        return metalErrorInvalidValue;
    }
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    std::vector<std::thread> workers;
    workers.reserve(gpu_count);
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        const uint64_t begin = (total_linear * static_cast<uint64_t>(gpu_idx)) / static_cast<uint64_t>(gpu_count);
        const uint64_t end = (total_linear * static_cast<uint64_t>(gpu_idx + 1u)) / static_cast<uint64_t>(gpu_count);
        workers.emplace_back([&, gpu_idx, begin, end]() {
            if (end <= begin) return;
            if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                statuses[gpu_idx] = metalErrorInvalidDevice;
                return;
            }
            restore_thread_input_snapshot(base_snapshot);
            g_disable_multi_gpu_dispatch = true;
            xp_linear_partition_active = true;
            xp_linear_partition_start = begin;
            xp_linear_partition_count = end - begin;
            xp_cgr_inputs_override = shared_cgr_inputs.empty() ? nullptr : &shared_cgr_inputs;
            xp_ssleay_inputs_override = shared_ssleay_inputs.empty() ? nullptr : &shared_ssleay_inputs;
            statuses[gpu_idx] = processMetalXP();
            xp_ssleay_inputs_override = nullptr;
            xp_cgr_inputs_override = nullptr;
            xp_linear_partition_active = false;
            xp_linear_partition_start = 0ull;
            xp_linear_partition_count = 0ull;
            g_disable_multi_gpu_dispatch = false;
        });
    }
    for (auto& t : workers) {
        if (t.joinable()) t.join();
    }
    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            fprintf(stderr, "[!] mode processMetalXP failed on GPU %d: %s [!]\n",
                g_gpu_contexts[gpu_idx].device_id, metalGetErrorString(statuses[gpu_idx]));
            return statuses[gpu_idx];
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return metalSuccess;
}

metalError_t processMetalXP()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_xp_multi_gpu();
    }
    if (Endomorphism) {
        fprintf(stderr, "[!] Error: -xp does not support endomorphism mode; use direct -c target letters instead [!]\n");
        return metalErrorInvalidValue;
    }
    metalError_t metalStatus = metalSuccess;
    XpCgrStateInput* d_cgr_inputs = nullptr;
	XpSsleayInput* d_ssleay_inputs = nullptr;
	uint32_t cgr_count = 0u;
	uint32_t ssleay_count = 0u;
	uint32_t input_line_base = 0u;
	std::vector<XpCgrStateInput> cgr_inputs_host;
	std::vector<XpSsleayInput> ssleay_inputs_host;
	const XpCgrStateInput* cgr_upload_ptr = nullptr;
	const XpSsleayInput* ssleay_upload_ptr = nullptr;

    if (p_xp_results == nullptr || p_xp_count == nullptr) {
        fprintf(stderr, "[!] Error: XP result buffer is not allocated on GPU %d [!]\n", DEVICE_NR);
        metalStatus = metalErrorInvalidDevicePointer;
        goto Error;
    }
    if (xp_profile_kind == XP_PROFILE_CGR_STATE || xp_profile_kind == XP_PROFILE_CGR_BRIDGE ||
        xp_profile_kind == XP_PROFILE_CGR_XOR || xp_profile_kind == XP_PROFILE_CGR_CHAIN ||
        xp_profile_kind == XP_PROFILE_CGR_CHAIN_BRIDGE || xp_profile_kind == XP_PROFILE_RAW32) {
        if (xp_cgr_inputs_override == nullptr) {
            std::string err;
            if (!xp_load_cgr_state_inputs(cgr_inputs_host, err)) {
                fprintf(stderr, "[!] Error: %s [!]\n", err.c_str());
                metalStatus = metalErrorInvalidValue;
                goto Error;
            }
        }
		if (xp_linear_partition_active) {
			const size_t source_size = xp_cgr_inputs_override != nullptr ? xp_cgr_inputs_override->size() : cgr_inputs_host.size();
			const uint64_t total = static_cast<uint64_t>(source_size);
			const uint64_t begin = std::min<uint64_t>(xp_linear_partition_start, total);
			const uint64_t count = std::min<uint64_t>(xp_linear_partition_count, total - begin);
            if (begin > static_cast<uint64_t>(UINT32_MAX)) {
                fprintf(stderr, "[!] Error: XP CGR input line base exceeds uint32 range [!]\n");
                metalStatus = metalErrorInvalidValue;
                goto Error;
			}
			input_line_base = static_cast<uint32_t>(begin);
			cgr_upload_ptr = (xp_cgr_inputs_override != nullptr ? xp_cgr_inputs_override->data() : cgr_inputs_host.data())
				+ static_cast<size_t>(begin);
			cgr_count = static_cast<uint32_t>(std::min<uint64_t>(count, static_cast<uint64_t>(UINT32_MAX)));
		}
		else if (xp_cgr_inputs_override != nullptr) {
			cgr_upload_ptr = xp_cgr_inputs_override->data();
			cgr_count = static_cast<uint32_t>(std::min<size_t>(xp_cgr_inputs_override->size(), UINT32_MAX));
		}
		else {
			cgr_upload_ptr = cgr_inputs_host.data();
			cgr_count = static_cast<uint32_t>(std::min<size_t>(cgr_inputs_host.size(), UINT32_MAX));
		}
		metalStatus = metalMalloc(reinterpret_cast<void**>(&d_cgr_inputs), static_cast<size_t>(cgr_count) * sizeof(XpCgrStateInput));
		if (metalStatus != metalSuccess) {
			fprintf(stderr, "[!] Metal Malloc XP CGR inputs failed: %s [!]\n", metalGetErrorString(metalStatus));
			goto Error;
		}
		metalStatus = metalMemcpy(d_cgr_inputs, cgr_upload_ptr, static_cast<size_t>(cgr_count) * sizeof(XpCgrStateInput), metalMemcpyHostToDevice);
		if (metalStatus != metalSuccess) {
			fprintf(stderr, "[!] Metal Memcpy XP CGR inputs failed: %s [!]\n", metalGetErrorString(metalStatus));
			goto Error;
		}
    }
    else if (xp_profile_kind == XP_PROFILE_SSLEAY_STIR) {
        if (xp_ssleay_inputs_override == nullptr) {
            std::string err;
            if (!xp_load_ssleay_inputs(ssleay_inputs_host, err)) {
                fprintf(stderr, "[!] Error: %s [!]\n", err.c_str());
                metalStatus = metalErrorInvalidValue;
                goto Error;
            }
        }
        if (xp_linear_partition_active) {
            const size_t source_size = xp_ssleay_inputs_override != nullptr ? xp_ssleay_inputs_override->size() : ssleay_inputs_host.size();
            const uint64_t total = static_cast<uint64_t>(source_size);
            const uint64_t begin = std::min<uint64_t>(xp_linear_partition_start, total);
            const uint64_t count = std::min<uint64_t>(xp_linear_partition_count, total - begin);
            if (begin > static_cast<uint64_t>(UINT32_MAX)) {
                fprintf(stderr, "[!] Error: XP SSLeay input line base exceeds uint32 range [!]\n");
                metalStatus = metalErrorInvalidValue;
                goto Error;
			}
			input_line_base = static_cast<uint32_t>(begin);
			ssleay_upload_ptr = (xp_ssleay_inputs_override != nullptr ? xp_ssleay_inputs_override->data() : ssleay_inputs_host.data())
				+ static_cast<size_t>(begin);
			ssleay_count = static_cast<uint32_t>(std::min<uint64_t>(count, static_cast<uint64_t>(UINT32_MAX)));
		}
		else if (xp_ssleay_inputs_override != nullptr) {
			ssleay_upload_ptr = xp_ssleay_inputs_override->data();
			ssleay_count = static_cast<uint32_t>(std::min<size_t>(xp_ssleay_inputs_override->size(), UINT32_MAX));
		}
		else {
			ssleay_upload_ptr = ssleay_inputs_host.data();
			ssleay_count = static_cast<uint32_t>(std::min<size_t>(ssleay_inputs_host.size(), UINT32_MAX));
		}
		metalStatus = metalMalloc(reinterpret_cast<void**>(&d_ssleay_inputs), static_cast<size_t>(ssleay_count) * sizeof(XpSsleayInput));
		if (metalStatus != metalSuccess) {
			fprintf(stderr, "[!] Metal Malloc XP SSLeay inputs failed: %s [!]\n", metalGetErrorString(metalStatus));
			goto Error;
		}
		metalStatus = metalMemcpy(d_ssleay_inputs, ssleay_upload_ptr, static_cast<size_t>(ssleay_count) * sizeof(XpSsleayInput), metalMemcpyHostToDevice);
		if (metalStatus != metalSuccess) {
			fprintf(stderr, "[!] Metal Memcpy XP SSLeay inputs failed: %s [!]\n", metalGetErrorString(metalStatus));
			goto Error;
        }
    }

    {
        const uint32_t keys_per_pid = (xp_profile_kind == XP_PROFILE_OPENSSL || xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_PYMT || xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32 || xp_profile_kind == XP_PROFILE_RANDSTORM_BYTES ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_CRYPTO1_JSBN ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_BYTES || xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_POOL32 ||
            xp_profile_kind == XP_PROFILE_PHPCOINADDRESS || xp_profile_kind == XP_PROFILE_BLUEWALLET_ISAAC ||
            xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT || xp_profile_kind == XP_PROFILE_JAVA_LCG_DIRECT ||
            xp_profile_kind == XP_PROFILE_TIME_MT ||
            xp_profile_kind == XP_PROFILE_SHA256_DIRECT || xp_profile_kind == XP_PROFILE_LOWBITS_DIRECT ||
            xp_profile_kind == XP_PROFILE_PYBTC_MT || xp_profile_kind == XP_PROFILE_NANO_JAVA_RANDOM ||
            xp_profile_kind == XP_PROFILE_PYWALLET_TS_WEAK)
            ? static_cast<uint32_t>(n_number)
            : 1u;
        const uint32_t pid_count = (xp_profile_kind == XP_PROFILE_OPENSSL)
            ? static_cast<uint32_t>(static_cast<uint64_t>(end_seed) - static_cast<uint64_t>(start_seed) + 1ull)
            : 0u;
        uint64_t randstorm_state_count = 0ull;
        if ((xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN || xp_profile_kind == XP_PROFILE_RANDSTORM_PYMT ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT || xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32 ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_BYTES || xp_profile_kind == XP_PROFILE_RANDSTORM_CRYPTO1_JSBN ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_BYTES ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_POOL32 || xp_profile_kind == XP_PROFILE_PHPCOINADDRESS ||
            xp_profile_kind == XP_PROFILE_BLUEWALLET_ISAAC || xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT ||
            xp_profile_kind == XP_PROFILE_TIME_MT ||
            xp_profile_kind == XP_PROFILE_JAVA_LCG_DIRECT || xp_profile_kind == XP_PROFILE_SHA256_DIRECT ||
            xp_profile_kind == XP_PROFILE_PID_HASH_DIRECT || xp_profile_kind == XP_PROFILE_LOWBITS_DIRECT ||
            xp_profile_kind == XP_PROFILE_PYBTC_MT || xp_profile_kind == XP_PROFILE_NANO_JAVA_RANDOM ||
            xp_profile_kind == XP_PROFILE_PYWALLET_TS_WEAK) &&
            end_seed64 >= start_seed64) {
            randstorm_state_count = end_seed64 - start_seed64 + 1ull;
            if (xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT &&
                (xp_path_mask & (1ull << XP_TIME_LCG_DIRECT_VARIANT_GLIBC_XOR_PID)) != 0u) {
                uint64_t expanded_state_count = 0ull;
                randstorm_state_count = mul_u64_checked(randstorm_state_count, XP_TIME_LCG_DIRECT_XOR_PID_COUNT, expanded_state_count)
                    ? expanded_state_count
                    : 0ull;
            }
        }
        const bool randstorm_explicit_time_range = walletjs_time_start_seen && walletjs_time_end_seen;
        const uint64_t randstorm_time_count64 = ((xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT || xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32 ||
            (xp_profile_kind == XP_PROFILE_PYBTC_MT && xp_pybtc_mt_time_mode)) &&
            randstorm_explicit_time_range && walletjs_time_end >= walletjs_time_start)
            ? (static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull)
            : 0ull;
        const uint32_t randstorm_time_count = (randstorm_time_count64 <= static_cast<uint64_t>(UINT32_MAX))
            ? static_cast<uint32_t>(randstorm_time_count64)
            : 0u;
        const uint32_t randstorm_delta_count = (xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT || xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32 ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_BYTES || xp_profile_kind == XP_PROFILE_RANDSTORM_CRYPTO1_JSBN ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_BYTES ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_POOL32)
            ? (walletjs_time_delta_max + 1u)
            : 0u;
        uint64_t linear_total = 0ull;
        if (xp_profile_kind == XP_PROFILE_OPENSSL) {
            linear_total = static_cast<uint64_t>(pid_count) * static_cast<uint64_t>(xp_path_count) * static_cast<uint64_t>(XP_OPENSSL_ARCH_COUNT);
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_JSBN) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_PYMT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_PHPCOINADDRESS) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_BLUEWALLET_ISAAC) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_TIME_MT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_JAVA_LCG_DIRECT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_SHA256_DIRECT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_PID_HASH_DIRECT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_LOWBITS_DIRECT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_PYBTC_MT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_NANO_JAVA_RANDOM) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_PYWALLET_TS_WEAK) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_BYTES ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_CRYPTO1_JSBN) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_BYTES ||
            xp_profile_kind == XP_PROFILE_RANDSTORM_V8INIT_POOL32) {
            linear_total = xp_domain_linear_count();
        }
        else if (xp_profile_kind == XP_PROFILE_RANDSTORM_MWC32) {
            linear_total = xp_domain_linear_count();
        }
        else {
            linear_total = (xp_profile_kind == XP_PROFILE_SSLEAY_STIR) ? static_cast<uint64_t>(ssleay_count) : static_cast<uint64_t>(cgr_count);
        }
        const bool input_profile = (xp_profile_kind != XP_PROFILE_OPENSSL && xp_profile_kind != XP_PROFILE_RANDSTORM_JSBN &&
            xp_profile_kind != XP_PROFILE_RANDSTORM_PYMT && xp_profile_kind != XP_PROFILE_RANDSTORM_V8INIT &&
            xp_profile_kind != XP_PROFILE_RANDSTORM_MWC32 && xp_profile_kind != XP_PROFILE_RANDSTORM_BYTES &&
            xp_profile_kind != XP_PROFILE_RANDSTORM_CRYPTO1_JSBN &&
            xp_profile_kind != XP_PROFILE_RANDSTORM_V8INIT_BYTES &&
            xp_profile_kind != XP_PROFILE_RANDSTORM_V8INIT_POOL32 &&
            xp_profile_kind != XP_PROFILE_PHPCOINADDRESS &&
            xp_profile_kind != XP_PROFILE_BLUEWALLET_ISAAC &&
            xp_profile_kind != XP_PROFILE_TIME_LCG_DIRECT &&
            xp_profile_kind != XP_PROFILE_TIME_MT &&
            xp_profile_kind != XP_PROFILE_JAVA_LCG_DIRECT &&
            xp_profile_kind != XP_PROFILE_SHA256_DIRECT &&
            xp_profile_kind != XP_PROFILE_PID_HASH_DIRECT &&
            xp_profile_kind != XP_PROFILE_LOWBITS_DIRECT &&
            xp_profile_kind != XP_PROFILE_PYBTC_MT &&
            xp_profile_kind != XP_PROFILE_NANO_JAVA_RANDOM &&
            xp_profile_kind != XP_PROFILE_PYWALLET_TS_WEAK);
        const bool repeat_domain = false;
        uint64_t linear_begin = (xp_linear_partition_active && !input_profile) ? xp_linear_partition_start : 0ull;
        uint64_t linear_count = (xp_linear_partition_active && !input_profile) ? xp_linear_partition_count : linear_total;
        if (linear_begin > linear_total) linear_begin = linear_total;
        if (linear_count > linear_total - linear_begin) linear_count = linear_total - linear_begin;
        const uint64_t launch_capacity = std::max<uint64_t>(1ull, static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS));

        do {
            uint64_t done = 0ull;
            while (isRun && done < linear_count) {
                const uint64_t launch_count = std::min<uint64_t>(launch_capacity, linear_count - done);
                const uint32_t launch_blocks = static_cast<uint32_t>((launch_count + BLOCK_THREADS - 1ull) / BLOCK_THREADS);
                metalStatus = metalMemset(p_xp_count, 0, sizeof(unsigned long long));
                if (metalStatus != metalSuccess) goto Error;

                metalStatus = launch_workerXP(MetalGridSize(launch_blocks), MetalGridSize(BLOCK_THREADS),
                    nullptr, nullptr, _dev_precomp, pitch,
                    xp_profile_kind, xp_path_mask, xp_path_count, start_seed, pid_count, keys_per_pid,
                    linear_begin + done, launch_count,
                    start_seed64, randstorm_state_count, walletjs_time_start, randstorm_time_count, randstorm_delta_count,
                    d_cgr_inputs, cgr_count, d_ssleay_inputs, ssleay_count,
                    input_line_base);
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "workerXP launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                metalStatus = metalDeviceSynchronize();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "workerXP sync failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }

                const uint64_t checks = (xp_profile_kind == XP_PROFILE_OPENSSL || xp_profile_kind == XP_PROFILE_RANDSTORM_PYMT ||
                    xp_profile_kind == XP_PROFILE_PHPCOINADDRESS || xp_profile_kind == XP_PROFILE_BLUEWALLET_ISAAC ||
                    xp_profile_kind == XP_PROFILE_TIME_LCG_DIRECT || xp_profile_kind == XP_PROFILE_JAVA_LCG_DIRECT ||
                    xp_profile_kind == XP_PROFILE_TIME_MT ||
                    xp_profile_kind == XP_PROFILE_SHA256_DIRECT || xp_profile_kind == XP_PROFILE_PID_HASH_DIRECT ||
                    xp_profile_kind == XP_PROFILE_LOWBITS_DIRECT ||
                    xp_profile_kind == XP_PROFILE_PYBTC_MT || xp_profile_kind == XP_PROFILE_NANO_JAVA_RANDOM)
                    ? launch_count * static_cast<uint64_t>(keys_per_pid)
                    : launch_count;
                counterTotal += checks;

                unsigned long long xp_count_host = 0ull;
                metalStatus = metalMemcpy(&xp_count_host, p_xp_count, sizeof(xp_count_host), metalMemcpyDeviceToHost);
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalMemcpy XP count failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                if (xp_count_host > 0ull) {
                    if (xp_count_host > static_cast<unsigned long long>(MAX_FOUNDS)) {
                        fprintf(stderr, "[!] Warning: XP found buffer overflow (%llu > %u); increase -fsize [!]\n",
                            xp_count_host, MAX_FOUNDS);
                    }
                    const size_t save_count = static_cast<size_t>(std::min<unsigned long long>(
                        xp_count_host, static_cast<unsigned long long>(MAX_FOUNDS)));
                    std::vector<XpReplayResult> host_results(save_count);
                    metalStatus = metalMemcpy(host_results.data(), p_xp_results, save_count * sizeof(XpReplayResult), metalMemcpyDeviceToHost);
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy XP results failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    SaveResultXP(OUT_FILE, Founds, save, host_results.data(), static_cast<unsigned long long>(save_count));
                    flush_all_async_save_queues();
                }
                done += launch_count;
            }
        } while (isRun && repeat_domain && !xp_once && !input_profile);
    }

Error:
    if (d_ssleay_inputs) metalFree(d_ssleay_inputs);
    if (d_cgr_inputs) metalFree(d_cgr_inputs);
    return metalStatus;
}

static inline metalError_t launch_workerProfanity(
    MetalGridSize grid,
    MetalGridSize block,
    bool* buffIsResult,
    bool* buffDeviceResult,
    const secp256k1_ge_storage* prec,
    size_t prec_pitch,
    uint32_t seed32,
    uint64_t lane_start,
    uint64_t lane_count,
    uint64_t state_index_start,
    uint64_t round_start,
    uint64_t round_count,
    ProfanityWalkState* walk_state,
    uint64_t walk_state_capacity,
    bool use_walk_state,
    bool store_walk_state)
{
    const ProfanitySeedWords seed_words = profanity_seed_words(seed32);
    const uint64_t s0 = seed_words.s[0];
    const uint64_t s1 = seed_words.s[1];
    const uint64_t s2 = seed_words.s[2];
    const uint64_t s3 = seed_words.s[3];
    const int targets = profanity_target_count();
    if (targets == 1) {
        if (Compressed) {
            metal_launch("workerProfanity_c", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (Uncompressed) {
            metal_launch("workerProfanity_u", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (Segwit) {
            metal_launch("workerProfanity_s", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (Taproot) {
            metal_launch("workerProfanity_r", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (Xpoint) {
            metal_launch("workerProfanity_x", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (P2wsh) {
            metal_launch("workerProfanity_p", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (Ethereum) {
            metal_launch("workerProfanity_e", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
    }
    if (!Ethereum && !Xpoint && !P2wsh) {
        if (Compressed && Uncompressed && !Segwit && !Taproot) {
            metal_launch("workerProfanity_cu", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
        if (Compressed || Uncompressed || Segwit || Taproot) {
            metal_launch("workerProfanity_cusr", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
            return metalGetLastError();
        }
    }

    metal_launch("workerProfanity_cusrxe", grid, block, buffIsResult, buffDeviceResult, prec, prec_pitch, s0, s1, s2, s3, seed32, lane_start, lane_count, state_index_start, round_start, round_count, walk_state, walk_state_capacity, use_walk_state, store_walk_state);
    return metalGetLastError();
}

static bool parse_profanity_pubkey_bytes_from_hex(
    const std::string& raw,
    std::array<uint8_t, 65>& out,
    uint32_t& out_len,
    std::string& normalized,
    std::string& err)
{
    std::string s = raw;
    if (s.size() >= 2u && s[0] == '0' && ((s[1] | 0x20) == 'x')) {
        s.erase(0, 2);
    }
    if (s.size() != 66u && s.size() != 130u) {
        if (s.size() >= 8u && s.size() <= 40u && ((s.size() & 1u) == 0u)) {
            err = "-profanity -recovery needs a public key; address/hash160 targets are not enough for Q-kG";
        }
        else {
            err = "-target/-hash expects 33-byte compressed or 65-byte uncompressed public key hex";
        }
        return false;
    }
    for (const char c : s) {
        if (!std::isxdigit(static_cast<unsigned char>(c))) {
            err = "-target/-hash contains non-hex characters";
            return false;
        }
    }
    memset(out.data(), 0, out.size());
    out_len = static_cast<uint32_t>(s.size() / 2u);
    for (size_t i = 0; i < out_len; ++i) {
        const int hi = hex_nibble_value(s[i * 2u]);
        const int lo = hex_nibble_value(s[i * 2u + 1u]);
        if (hi < 0 || lo < 0) {
            err = "-target/-hash contains non-hex characters";
            return false;
        }
        out[i] = static_cast<uint8_t>((hi << 4) | lo);
    }
    if (out_len == 33u && out[0] != 0x02u && out[0] != 0x03u) {
        err = "compressed -target/-hash public key must start with 02 or 03";
        return false;
    }
    if (out_len == 65u && out[0] != 0x04u) {
        err = "uncompressed -target/-hash public key must start with 04";
        return false;
    }
    normalized.clear();
    normalized.reserve(s.size());
    for (char c : s) {
        normalized.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
    }
    return true;
}

static bool parse_profanity_pubkey_bytes(std::array<uint8_t, 65>& out, uint32_t& out_len, std::string& err)
{
    std::string normalized;
    if (!parse_profanity_pubkey_bytes_from_hex(profanity_target_hex, out, out_len, normalized, err)) {
        return false;
    }
    profanity_target_hex = normalized;
    return true;
}

static metalError_t ensure_profanity_recovery_target_prepared(
    const std::array<uint8_t, 65>& target_pubkey,
    uint32_t target_len)
{
    if (p_profanity_recovery_target_pubkey == nullptr ||
        p_profanity_recovery_target_ge == nullptr ||
        p_profanity_recovery_target_ge_ok == nullptr) {
        fprintf(stderr, "[!] Error: Profanity recovery target cache is not allocated on GPU %d [!]\n", DEVICE_NR);
        return metalErrorInvalidDevicePointer;
    }

    if (p_profanity_recovery_target_cache_hex == profanity_target_hex &&
        p_profanity_recovery_target_cache_len == target_len) {
        return metalSuccess;
    }

    metalError_t metalStatus = metalMemcpy(
        p_profanity_recovery_target_pubkey,
        target_pubkey.data(),
        65,
        metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy target pubkey failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }
    metalStatus = metalMemset(p_profanity_recovery_target_ge_ok, 0, sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemset target point status failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }
    metal_launch("workerProfanityPrepareTargetGe", 1, 1, p_profanity_recovery_target_pubkey, target_len, p_profanity_recovery_target_ge, p_profanity_recovery_target_ge_ok);
    metalStatus = metalGetLastError();
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "workerProfanityPrepareTargetGe launch failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }
    metalStatus = metalDeviceSynchronize();
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "workerProfanityPrepareTargetGe sync failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }

    uint32_t target_ok = 0;
    metalStatus = metalMemcpy(&target_ok, p_profanity_recovery_target_ge_ok, sizeof(uint32_t), metalMemcpyDeviceToHost);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy target point status failed: %s\n", metalGetErrorString(metalStatus));
        return metalStatus;
    }
    if (target_ok == 0u) {
        fprintf(stderr, "[!] Error: failed to decode -target/-hash public key on GPU [!]\n");
        return metalErrorInvalidValue;
    }

    p_profanity_recovery_target_cache_hex = profanity_target_hex;
    p_profanity_recovery_target_cache_len = target_len;
    p_profanity_recovery_walk_state_valid = false;
    p_profanity_recovery_walk_state_target_hex.clear();
    return metalSuccess;
}

struct ProfanityRecoveryFileEntry {
    std::string original_line;
    std::string pubkey_hex;
    uint64_t offset = 0ull;
    bool found = false;
    bool passthrough = false;
    size_t line_no = 0u;
};

static inline std::string profanity_trim_copy(const std::string& in)
{
    size_t first = 0u;
    while (first < in.size() && std::isspace(static_cast<unsigned char>(in[first]))) {
        ++first;
    }
    size_t last = in.size();
    while (last > first && std::isspace(static_cast<unsigned char>(in[last - 1u]))) {
        --last;
    }
    return in.substr(first, last - first);
}

static inline std::string profanity_lower_copy(std::string in)
{
    std::transform(in.begin(), in.end(), in.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
        });
    return in;
}

static bool parse_profanity_u64_hex(const std::string& raw, uint64_t& out, std::string& err)
{
    std::string s = profanity_trim_copy(raw);
    if (s.size() >= 2u && s[0] == '0' && ((s[1] | 0x20) == 'x')) {
        s.erase(0, 2);
    }
    if (s.empty()) {
        err = "empty offset";
        return false;
    }
    if (s.size() > 16u) {
        err = "offset is wider than 64-bit";
        return false;
    }
    out = 0ull;
    for (char c : s) {
        const int nib = hex_nibble_value(c);
        if (nib < 0) {
            err = "offset contains non-hex characters";
            return false;
        }
        out = (out << 4) | static_cast<uint64_t>(nib);
    }
    return true;
}

static std::string profanity_hex16(uint64_t value)
{
    char buf[17];
    snprintf(buf, sizeof(buf), "%016llx", static_cast<unsigned long long>(value));
    return std::string(buf);
}

static bool load_profanity_recovery_file(
    const std::string& path,
    std::vector<ProfanityRecoveryFileEntry>& entries,
    std::string& err)
{
    entries.clear();
    std::ifstream in(path);
    if (!in) {
        err = "failed to open recovery file: " + path;
        return false;
    }
    tune_ifstream_buffer(in);
    print_opened_input_file(path);

    std::string line;
    size_t line_no = 0u;
    while (std::getline(in, line)) {
        ++line_no;
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
        ProfanityRecoveryFileEntry entry;
        entry.original_line = line;
        entry.line_no = line_no;

        const std::string trimmed = profanity_trim_copy(line);
        if (trimmed.empty() || trimmed[0] == '#') {
            entry.passthrough = true;
            entries.emplace_back(std::move(entry));
            continue;
        }

        std::vector<std::string> parts;
        size_t pos = 0u;
        while (true) {
            const size_t next = trimmed.find(':', pos);
            parts.emplace_back(profanity_trim_copy(trimmed.substr(pos, next == std::string::npos ? std::string::npos : next - pos)));
            if (next == std::string::npos) {
                break;
            }
            pos = next + 1u;
        }
        if (parts.empty() || parts.size() > 3u) {
            err = "line " + std::to_string(line_no) + ": expected <pubkey>[:offset][:found]";
            return false;
        }

        std::array<uint8_t, 65> pubkey{};
        uint32_t pubkey_len = 0u;
        std::string normalized;
        std::string parse_err;
        if (!parse_profanity_pubkey_bytes_from_hex(parts[0], pubkey, pubkey_len, normalized, parse_err)) {
            err = "line " + std::to_string(line_no) + ": " + parse_err;
            return false;
        }
        entry.pubkey_hex = normalized;

        if (parts.size() >= 2u && !parts[1].empty()) {
            if (!parse_profanity_u64_hex(parts[1], entry.offset, parse_err)) {
                err = "line " + std::to_string(line_no) + ": " + parse_err;
                return false;
            }
        }
        if (parts.size() >= 3u) {
            if (profanity_lower_copy(parts[2]) != "found") {
                err = "line " + std::to_string(line_no) + ": third field must be 'found'";
                return false;
            }
            entry.found = true;
        }
        entries.emplace_back(std::move(entry));
    }
    return true;
}

static bool save_profanity_recovery_file(
    const std::string& path,
    const std::vector<ProfanityRecoveryFileEntry>& entries,
    std::string& err)
{
    const std::string tmp_path = path + ".tmp";
    {
        std::ofstream out(tmp_path, std::ios::trunc);
        if (!out) {
            err = "failed to open temp recovery file: " + tmp_path;
            return false;
        }
        for (const auto& entry : entries) {
            if (entry.passthrough) {
                out << entry.original_line << '\n';
                continue;
            }
            out << entry.pubkey_hex << ':' << profanity_hex16(entry.offset);
            if (entry.found) {
                out << ":found";
            }
            out << '\n';
        }
        if (!out) {
            err = "failed to write temp recovery file: " + tmp_path;
            return false;
        }
    }

    std::remove(path.c_str());
    if (std::rename(tmp_path.c_str(), path.c_str()) != 0) {
        err = "failed to replace recovery file: " + path;
        return false;
    }
    return true;
}

static size_t count_active_profanity_recovery_entries(const std::vector<ProfanityRecoveryFileEntry>& entries)
{
    size_t active = 0u;
    for (const auto& entry : entries) {
        if (!entry.passthrough && !entry.found) {
            ++active;
        }
    }
    return active;
}

static metalError_t dispatch_profanity_recovery_multi_gpu()
{
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return processMetalProfanityRecovery();
    }

    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    std::atomic<uint64_t> next_round(profanity_offset_explicit ? profanity_offset : 0ull);
    const uint64_t historical_lane_count = profanity_recovery_historical_lane_count();
    const bool bounded_file_window = g_profanity_recovery_window_override_active.load(std::memory_order_relaxed);
    const uint64_t bounded_begin = profanity_offset_explicit ? profanity_offset : 0ull;
    const uint64_t bounded_end = bounded_file_window
        ? g_profanity_recovery_window_end.load(std::memory_order_relaxed)
        : std::numeric_limits<uint64_t>::max();
    std::vector<std::thread> workers;
    std::vector<metalError_t> statuses(gpu_count, metalSuccess);
    workers.reserve(gpu_count);

    auto bounded_gpu_window = [&](size_t gpu_idx, uint64_t& begin, uint64_t& end) -> bool {
        if (!bounded_file_window || bounded_begin > bounded_end) return false;
        const uint64_t total = bounded_end - bounded_begin + 1ull;
        const uint64_t base = total / static_cast<uint64_t>(gpu_count);
        const uint64_t rem = total % static_cast<uint64_t>(gpu_count);
        const uint64_t idx = static_cast<uint64_t>(gpu_idx);
        const uint64_t span = base + (idx < rem ? 1ull : 0ull);
        if (span == 0ull) return false;
        const uint64_t prior = base * idx + std::min<uint64_t>(idx, rem);
        begin = bounded_begin + prior;
        end = begin + span - 1ull;
        return true;
    };

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        workers.emplace_back([&, gpu_idx]() {
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                    statuses[gpu_idx] = metalErrorInvalidDevice;
                    return;
                }
            }

            restore_thread_input_snapshot(base_snapshot);
            g_disable_multi_gpu_dispatch = true;
            profanity_lane_partition_active = true;
            profanity_partition_gpu_id = g_gpu_contexts[gpu_idx].device_id;
            profanity_partition_lane_start = 0ull;
            profanity_partition_lane_count = historical_lane_count;
            uint64_t gpu_round_begin = 0ull;
            uint64_t gpu_round_end = 0ull;
            if (bounded_file_window) {
                if (bounded_gpu_window(gpu_idx, gpu_round_begin, gpu_round_end)) {
                    profanity_recovery_round_window_thread_override_active = true;
                    profanity_recovery_round_window_thread_begin = gpu_round_begin;
                    profanity_recovery_round_window_thread_end = gpu_round_end;
                    profanity_recovery_round_queue_active = false;
                    profanity_recovery_next_round = nullptr;
                    statuses[gpu_idx] = processMetalProfanityRecovery();
                }
                else {
                    statuses[gpu_idx] = metalSuccess;
                }
            }
            else {
                profanity_recovery_round_queue_active = true;
                profanity_recovery_next_round = &next_round;
                statuses[gpu_idx] = processMetalProfanityRecovery();
            }
            {
                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                if (metalSetDevice(g_gpu_contexts[gpu_idx].device_id) == metalSuccess) {
                    g_gpu_contexts[gpu_idx] = capture_current_gpu_context();
                }
            }
            profanity_recovery_next_round = nullptr;
            profanity_recovery_round_queue_active = false;
            profanity_recovery_round_window_thread_override_active = false;
            profanity_recovery_round_window_thread_begin = 0ull;
            profanity_recovery_round_window_thread_end = 0ull;
            profanity_lane_partition_active = false;
            profanity_partition_gpu_id = -1;
            g_disable_multi_gpu_dispatch = false;
        });
    }

    for (auto& th : workers) {
        if (th.joinable()) th.join();
    }
    if (!g_gpu_contexts.empty()) {
        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
        activate_gpu_context(g_gpu_contexts.front());
    }
    restore_thread_input_snapshot(base_snapshot);

    for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
        if (statuses[gpu_idx] != metalSuccess) {
            fprintf(stderr, "[!] mode processMetalProfanityRecovery failed on GPU %d: %s [!]\n",
                g_gpu_contexts[gpu_idx].device_id, metalGetErrorString(statuses[gpu_idx]));
            return statuses[gpu_idx];
        }
    }
    return metalSuccess;
}

static metalError_t dispatch_profanity_multi_gpu()
{
    if (!is_multi_gpu_active() || g_disable_multi_gpu_dispatch) {
        return processMetalProfanity();
    }

    profanity_direct_guard_launch_geometry();
    const ThreadInputSnapshot base_snapshot = capture_thread_input_snapshot();
    const size_t gpu_count = g_gpu_contexts.size();
    uint64_t round_begin_window = 0ull;
    uint64_t round_end_window = 0ull;
    if (!profanity_round_window(round_begin_window, round_end_window)) {
        fprintf(stderr, "[!] Error: -profanity requires -n > 0 [!]\n");
        return metalErrorInvalidValue;
    }
    const uint64_t round_span = use_n_count ? n_number : (1ull << 32);
    if (round_span == 0ull) {
        fprintf(stderr, "[!] Error: -profanity requires -n > 0 [!]\n");
        return metalErrorInvalidValue;
    }
    const uint64_t base_foundid_count = profanity_direct_foundid_count();
    if (base_foundid_count == 0ull) {
        fprintf(stderr, "[!] Error: -profanity has zero active foundId lanes [!]\n");
        return metalErrorInvalidValue;
    }

    struct DirectGpuJob {
        bool valid = false;
        size_t gpu_idx = 0u;
        uint32_t seed = 0u;
        uint64_t lane_start = 0ull;
        uint64_t lane_count = 0ull;
        uint64_t state_index_start = 0ull;
        uint64_t round_begin = 0ull;
        uint64_t round_end = 0ull;
        bool use_round_queue = false;
        std::atomic<uint64_t>* round_queue = nullptr;
    };

    auto make_round_window_for_gpu = [&](size_t gpu_idx, uint64_t& begin, uint64_t& end, bool warn) -> bool {
        const uint64_t gpu_index = static_cast<uint64_t>(gpu_idx);
        if (gpu_index > (std::numeric_limits<uint64_t>::max() / round_span)) {
            if (warn) {
                fprintf(stderr, "[!] Warning: -profanity GPU slot %zu skipped: round offset overflow [!]\n", gpu_idx);
            }
            return false;
        }
        const uint64_t gpu_delta = gpu_index * round_span;
        if (gpu_delta > (std::numeric_limits<uint64_t>::max() - round_begin_window)) {
            if (warn) {
                fprintf(stderr, "[!] Warning: -profanity GPU slot %zu skipped: round offset overflow [!]\n", gpu_idx);
            }
            return false;
        }
        begin = round_begin_window + gpu_delta;
        const uint64_t span_minus_one = round_span - 1ull;
        if (span_minus_one > (std::numeric_limits<uint64_t>::max() - begin)) {
            if (warn) {
                fprintf(stderr, "[!] Warning: -profanity GPU slot %zu skipped: round end overflow [!]\n", gpu_idx);
            }
            return false;
        }
        end = begin + span_minus_one;
        return true;
    };

    auto make_partitioned_round_window_for_gpu = [&](size_t gpu_idx, uint64_t& begin, uint64_t& end) -> bool {
        if (gpu_count == 0u || gpu_idx >= gpu_count || round_begin_window > round_end_window) {
            return false;
        }
        uint64_t total_rounds = 0ull;
        if (round_end_window == std::numeric_limits<uint64_t>::max() && round_begin_window == 0ull) {
            total_rounds = std::numeric_limits<uint64_t>::max();
        }
        else {
            total_rounds = round_end_window - round_begin_window + 1ull;
        }
        if (total_rounds == 0ull) {
            return false;
        }
        const uint64_t gpu_total = static_cast<uint64_t>(gpu_count);
        const uint64_t base = total_rounds / gpu_total;
        const uint64_t rem = total_rounds % gpu_total;
        const uint64_t gpu_index = static_cast<uint64_t>(gpu_idx);
        const uint64_t count = base + ((gpu_index < rem) ? 1ull : 0ull);
        if (count == 0ull) {
            return false;
        }
        const uint64_t offset = base * gpu_index + std::min<uint64_t>(gpu_index, rem);
        begin = round_begin_window + offset;
        end = begin + count - 1ull;
        return true;
    };

    auto run_gpu_jobs = [&](const std::vector<DirectGpuJob>& jobs) -> metalError_t {
        std::vector<std::thread> workers;
        std::vector<metalError_t> statuses(gpu_count, metalSuccess);
        workers.reserve(jobs.size());

        for (const DirectGpuJob& job : jobs) {
            if (!job.valid) {
                continue;
            }
            workers.emplace_back([&, job]() {
                {
                    std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                    if (!activate_gpu_context(g_gpu_contexts[job.gpu_idx])) {
                        statuses[job.gpu_idx] = metalErrorInvalidDevice;
                        return;
                    }
                }

                restore_thread_input_snapshot(base_snapshot);
                start_seed = job.seed;
                end_seed = job.seed;
                g_disable_multi_gpu_dispatch = true;
                profanity_direct_fixed_seed_pass_active = true;
                profanity_direct_fixed_seed_value = job.seed;
                profanity_lane_partition_active = true;
                profanity_partition_gpu_id = g_gpu_contexts[job.gpu_idx].device_id;
                profanity_partition_lane_start = job.lane_start;
                profanity_partition_lane_count = job.lane_count;
                profanity_partition_state_index_start = job.state_index_start;
                profanity_direct_round_window_override_active = true;
                profanity_direct_round_window_begin = job.round_begin;
                profanity_direct_round_window_end = job.round_end;
                profanity_recovery_round_queue_active = job.use_round_queue;
                profanity_recovery_next_round = job.round_queue;
                statuses[job.gpu_idx] = processMetalProfanity();
                profanity_recovery_next_round = nullptr;
                profanity_recovery_round_queue_active = false;
                profanity_direct_fixed_seed_pass_active = false;
                profanity_direct_fixed_seed_value = 0u;
                profanity_direct_round_window_end = 0ull;
                profanity_direct_round_window_begin = 0ull;
                profanity_direct_round_window_override_active = false;
                profanity_partition_state_index_start = 0ull;
                profanity_lane_partition_active = false;
                profanity_partition_gpu_id = -1;
                g_disable_multi_gpu_dispatch = false;
            });
        }

        for (auto& th : workers) {
            if (th.joinable()) th.join();
        }
        if (!g_gpu_contexts.empty()) {
            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
            activate_gpu_context(g_gpu_contexts.front());
        }
        restore_thread_input_snapshot(base_snapshot);

        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            if (statuses[gpu_idx] != metalSuccess) {
                fprintf(stderr, "[!] mode processMetalProfanity failed on GPU %d: %s [!]\n",
                    g_gpu_contexts[gpu_idx].device_id, metalGetErrorString(statuses[gpu_idx]));
                return statuses[gpu_idx];
            }
        }
        return metalSuccess;
    };

    auto run_seed_round_split = [&](uint32_t seed) -> metalError_t {
        bool can_use_fixed_windows = true;
        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            uint64_t ignored_begin = 0ull;
            uint64_t ignored_end = 0ull;
            if (!make_round_window_for_gpu(gpu_idx, ignored_begin, ignored_end, false)) {
                can_use_fixed_windows = false;
                break;
            }
        }

        std::vector<DirectGpuJob> jobs;
        jobs.reserve(gpu_count);
        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            uint64_t gpu_begin = 0ull;
            uint64_t gpu_end = 0ull;
            if (can_use_fixed_windows) {
                if (!make_round_window_for_gpu(gpu_idx, gpu_begin, gpu_end, true)) {
                    continue;
                }
            }
            else {
                if (!make_partitioned_round_window_for_gpu(gpu_idx, gpu_begin, gpu_end)) {
                    continue;
                }
            }
            DirectGpuJob job;
            job.valid = true;
            job.gpu_idx = gpu_idx;
            job.seed = seed;
            job.lane_start = 0ull;
            job.lane_count = base_foundid_count;
            job.state_index_start = 0ull;
            job.round_begin = gpu_begin;
            job.round_end = gpu_end;
            job.use_round_queue = false;
            job.round_queue = nullptr;
            jobs.emplace_back(job);
        }
        return run_gpu_jobs(jobs);
    };

    auto run_seed_foundid_split = [&](uint32_t seed) -> metalError_t {
        std::vector<DirectGpuJob> jobs;
        jobs.reserve(gpu_count);
        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            const uint64_t gpu_index = static_cast<uint64_t>(gpu_idx);
            if (gpu_index > (std::numeric_limits<uint64_t>::max() / base_foundid_count)) {
                fprintf(stderr, "[!] Warning: -profanity GPU slot %zu skipped: foundId offset overflow [!]\n", gpu_idx);
                continue;
            }
            DirectGpuJob job;
            job.valid = true;
            job.gpu_idx = gpu_idx;
            job.seed = seed;
            job.lane_start = gpu_index * base_foundid_count;
            job.lane_count = base_foundid_count;
            job.state_index_start = 0ull;
            job.round_begin = round_begin_window;
            job.round_end = round_end_window;
            jobs.emplace_back(job);
        }
        return run_gpu_jobs(jobs);
    };

    auto run_seed_split = [&]() -> metalError_t {
        const uint32_t seed_range_start = start_seed;
        const uint32_t seed_range_end = end_seed;
        std::atomic<uint64_t> next_seed(static_cast<uint64_t>(seed_range_start));
        std::mutex random_seed_mutex;
        ProfanityRandomSeedBlock random_seed_block;
        std::atomic<bool> stop(false);
        std::vector<std::thread> workers;
        std::vector<metalError_t> statuses(gpu_count, metalSuccess);
        workers.reserve(gpu_count);

        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            workers.emplace_back([&, gpu_idx]() {
                while (isRun && !stop.load(std::memory_order_relaxed)) {
                    uint32_t seed = 0u;
                    if (isRandom) {
                        std::lock_guard<std::mutex> seed_lock(random_seed_mutex);
                        if (!profanity_next_random_seed(seed_range_start, seed_range_end, random_seed_block, seed)) {
                            statuses[gpu_idx] = metalErrorInvalidValue;
                            stop.store(true, std::memory_order_relaxed);
                            break;
                        }
                    }
                    else {
                        const uint64_t seed64 = next_seed.fetch_add(1ull, std::memory_order_relaxed);
                        if (seed64 > static_cast<uint64_t>(seed_range_end) || seed64 > static_cast<uint64_t>(UINT32_MAX)) {
                            break;
                        }
                        seed = static_cast<uint32_t>(seed64);
                    }

                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gpu_idx])) {
                            statuses[gpu_idx] = metalErrorInvalidDevice;
                            stop.store(true, std::memory_order_relaxed);
                            break;
                        }
                    }

                    restore_thread_input_snapshot(base_snapshot);
                    start_seed = seed;
                    end_seed = seed;
                    g_disable_multi_gpu_dispatch = true;
                    profanity_direct_fixed_seed_pass_active = true;
                    profanity_direct_fixed_seed_value = seed;
                    profanity_lane_partition_active = true;
                    profanity_partition_gpu_id = g_gpu_contexts[gpu_idx].device_id;
                    profanity_partition_lane_start = 0ull;
                    profanity_partition_lane_count = base_foundid_count;
                    profanity_partition_state_index_start = 0ull;
                    profanity_direct_round_window_override_active = true;
                    profanity_direct_round_window_begin = round_begin_window;
                    profanity_direct_round_window_end = round_end_window;
                    const metalError_t st = processMetalProfanity();
                    profanity_direct_fixed_seed_pass_active = false;
                    profanity_direct_fixed_seed_value = 0u;
                    profanity_direct_round_window_end = 0ull;
                    profanity_direct_round_window_begin = 0ull;
                    profanity_direct_round_window_override_active = false;
                    profanity_partition_state_index_start = 0ull;
                    profanity_lane_partition_active = false;
                    profanity_partition_gpu_id = -1;
                    g_disable_multi_gpu_dispatch = false;
                    if (st != metalSuccess) {
                        statuses[gpu_idx] = st;
                        stop.store(true, std::memory_order_relaxed);
                        break;
                    }
                    if (isRandom) {
                        continue;
                    }
                }
            });
        }

        for (auto& th : workers) {
            if (th.joinable()) th.join();
        }
        if (!g_gpu_contexts.empty()) {
            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
            activate_gpu_context(g_gpu_contexts.front());
        }
        restore_thread_input_snapshot(base_snapshot);

        for (size_t gpu_idx = 0; gpu_idx < gpu_count; ++gpu_idx) {
            if (statuses[gpu_idx] != metalSuccess) {
                fprintf(stderr, "[!] mode processMetalProfanity failed on GPU %d: %s [!]\n",
                    g_gpu_contexts[gpu_idx].device_id, metalGetErrorString(statuses[gpu_idx]));
                return statuses[gpu_idx];
            }
        }
        return metalSuccess;
    };

    if (profanity_gpu_split_mode == ProfanityGpuSplitMode::Seed) {
        return run_seed_split();
    }

    auto run_seed_on_all_gpus = [&](uint32_t seed) -> metalError_t {
        if (profanity_gpu_split_mode == ProfanityGpuSplitMode::FoundId) {
            return run_seed_foundid_split(seed);
        }
        return run_seed_round_split(seed);
    };

    if (isRandom) {
        ProfanityRandomSeedBlock random_seed_block;
        while (isRun) {
            uint32_t seed = 0u;
            if (!profanity_next_random_seed(start_seed, end_seed, random_seed_block, seed)) {
                fprintf(stderr, "[!] Error: -profanity -random failed to pick seed block [!]\n");
                return metalErrorInvalidValue;
            }
            const metalError_t st = run_seed_on_all_gpus(seed);
            if (st != metalSuccess) {
                return st;
            }
        }
    }
    else {
        uint32_t seed = start_seed;
        while (isRun) {
            const metalError_t st = run_seed_on_all_gpus(seed);
            if (st != metalSuccess) {
                return st;
            }
            if (seed == end_seed || seed == UINT32_MAX) {
                break;
            }
            ++seed;
        }
    }
    return metalSuccess;
}


bool Contain_cpu(const uint64_t& item, int xors);

static inline bool profanity_cpu_xor_u_contains_pair(const uint64_t lo, const uint64_t hi)
{
    for (int i = 0; i < xor_count; ++i) {
        if (fingerprints[i] == nullptr) {
            continue;
        }
        // The uncompressed filter stores two 64-bit probes for the same 20-byte item.
        if (!Contain_cpu(hi, i)) {
            continue;
        }
        if (Contain_cpu(lo, i)) {
            return true;
        }
    }
    return false;
}

static bool profanity_cpu_xx_confirm_hit(const ProfanityRecoveryHit& hit, const bool recovery_use_xx)
{
    if (!recovery_use_xx) {
        return true;
    }

    uint8_t raw20[20] = {};
    profanity_x_filter_value20_from_x32(hit.x32, raw20);

    uint8_t masked20[20] = {};
    memcpy(masked20, raw20, sizeof(raw20));
    masked20[3] &= masked20[16];
    masked20[7] &= masked20[17];
    masked20[11] &= masked20[18];
    masked20[15] &= masked20[19];

    const uint64_t masked_lo = profanity_load_le64(masked20 + 0);
    const uint64_t masked_hi = profanity_load_le64(masked20 + 8);
    if (profanity_cpu_xor_u_contains_pair(masked_lo, masked_hi)) {
        return true;
    }

    // Compatibility path for filters built from raw X20 without uncompressed masking.
    const uint64_t raw_lo = profanity_load_le64(raw20 + 0);
    const uint64_t raw_hi = profanity_load_le64(raw20 + 8);
    return profanity_cpu_xor_u_contains_pair(raw_lo, raw_hi);
}

metalError_t processMetalKeystore()
{
    std::vector<std::string> target_paths = wallet_artifact_files;
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, { ".json", ".key", ".keystore", ".txt", ".hash", ".log", ".ldb", "", "@prefix:utc--", "@prefix:utc_" }, target_paths);
    }
    if (target_paths.empty()) {
        fprintf(stderr, "[!] Error: -keystore requires FILE or -f DIR [!]\n");
        return metalErrorInvalidValue;
    }

    std::vector<WalletKeystoreHostTarget> host_targets;
    host_targets.reserve(target_paths.size());
    std::vector<std::string> target_files;
    size_t skipped_files = 0u;
    const bool multi_file_mode = target_paths.size() > 1u || !wallet_artifact_dirs.empty();
    size_t warning_printed = 0u;
    size_t warning_suppressed = 0u;
    std::unordered_map<std::string, size_t> skip_reasons;
    const size_t kKeystoreMaxInlineWarnings = multi_file_mode ? 16u : 64u;
    for (const auto& path : target_paths) {
        std::vector<WalletKeystoreHostTarget> parsed_targets;
        std::string err;
        if (wallet_parse_keystore_v3_file_targets(path, parsed_targets, err) == 0u) {
            if (!multi_file_mode) {
                fprintf(stderr, "[!] Error: keystore '%s': %s [!]\n", path.c_str(), err.c_str());
                return metalErrorInvalidValue;
            }
            ++skipped_files;
            wallet_add_skip_reason(skip_reasons, err);
            if (warning_printed < kKeystoreMaxInlineWarnings) {
                fprintf(stderr, "[!] Warning: keystore '%s': skipped, %s [!]\n", path.c_str(), err.c_str());
                ++warning_printed;
            }
            else {
                ++warning_suppressed;
            }
            continue;
        }
        for (WalletKeystoreHostTarget& target : parsed_targets) {
            target.dev.target_index = static_cast<uint32_t>(host_targets.size());
            if (target.file.empty()) target.file = path;
            const std::string target_label = target.file;
            host_targets.emplace_back(std::move(target));
            target_files.push_back(target_label);
        }
    }
    if (host_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable keystore targets loaded");
        if (skipped_files != 0u) {
            fprintf(stderr, " (%zu file(s) skipped)", skipped_files);
        }
        fprintf(stderr, " [!]\n");
        return metalErrorInvalidValue;
    }

    auto make_keystore_dedup_key = [](const WalletKeystoreTarget& t) {
        std::string key;
        key.reserve(1u + 7u * sizeof(uint32_t) + WALLET_MAX_SALT_LEN +
            16u + WALLET_MAX_CIPHERTEXT_LEN + 32u);
        auto append_u8 = [&](uint8_t v) {
            key.push_back(static_cast<char>(v));
        };
        auto append_u32 = [&](uint32_t v) {
            key.push_back(static_cast<char>(v & 0xffu));
            key.push_back(static_cast<char>((v >> 8) & 0xffu));
            key.push_back(static_cast<char>((v >> 16) & 0xffu));
            key.push_back(static_cast<char>((v >> 24) & 0xffu));
        };
        auto append_bytes = [&](const uint8_t* data, size_t n) {
            if (data != nullptr && n != 0u) {
                key.append(reinterpret_cast<const char*>(data), n);
            }
        };
        append_u8(t.kdf_type);
        append_u32(t.iterations);
        append_u32(t.dklen);
        append_u32(t.scrypt_n);
        append_u32(t.scrypt_r);
        append_u32(t.scrypt_p);
        append_u32(t.salt_len);
        append_bytes(t.salt, std::min<size_t>(t.salt_len, WALLET_MAX_SALT_LEN));
        append_bytes(t.iv, sizeof(t.iv));
        append_u32(t.ciphertext_len);
        append_bytes(t.ciphertext, std::min<size_t>(t.ciphertext_len, WALLET_MAX_CIPHERTEXT_LEN));
        append_bytes(t.mac, sizeof(t.mac));
        return key;
    };

    std::vector<WalletKeystoreTarget> compact_targets;
    compact_targets.reserve(host_targets.size());
    std::vector<std::string> compact_target_files;
    compact_target_files.reserve(target_files.size());
    std::unordered_map<std::string, size_t> keystore_dedup;
    keystore_dedup.reserve(host_targets.size());
    size_t duplicate_keystore_targets = 0u;

    for (size_t i = 0; i < host_targets.size(); ++i) {
        WalletKeystoreTarget compact = host_targets[i].dev;
        const std::string key = make_keystore_dedup_key(compact);
        auto it = keystore_dedup.find(key);
        if (it == keystore_dedup.end()) {
            const size_t compact_index = compact_targets.size();
            compact.target_index = static_cast<uint32_t>(compact_index);
            keystore_dedup.emplace(key, compact_index);
            compact_targets.emplace_back(compact);
            compact_target_files.push_back(target_files[i]);
            continue;
        }

        ++duplicate_keystore_targets;
        const size_t compact_index = it->second;
        if (compact_index < compact_targets.size() &&
            compact_targets[compact_index].has_address == 0u &&
            compact.has_address != 0u) {
            compact.target_index = static_cast<uint32_t>(compact_index);
            compact_targets[compact_index] = compact;
            if (compact_index < compact_target_files.size()) {
                compact_target_files[compact_index] = target_files[i];
            }
        }
    }
    target_files.swap(compact_target_files);
    counterWalletActiveTargets = static_cast<uint64_t>(compact_targets.size());

    std::stable_sort(compact_targets.begin(), compact_targets.end(), [](const WalletKeystoreTarget& a, const WalletKeystoreTarget& b) {
        if (a.kdf_type != b.kdf_type) return a.kdf_type < b.kdf_type;
        if (a.kdf_type == WALLET_KDF_SCRYPT) {
            if (a.scrypt_n != b.scrypt_n) return a.scrypt_n < b.scrypt_n;
            if (a.scrypt_r != b.scrypt_r) return a.scrypt_r < b.scrypt_r;
            if (a.scrypt_p != b.scrypt_p) return a.scrypt_p < b.scrypt_p;
        }
        else if (a.iterations != b.iterations) {
            return a.iterations < b.iterations;
        }
        return a.target_index < b.target_index;
        });

    uint32_t keystore_pbkdf2_offset = 0u;
    uint32_t keystore_pbkdf2_count = 0u;
    uint32_t keystore_scrypt_offset = 0u;
    uint32_t keystore_scrypt_count = 0u;
    for (const WalletKeystoreTarget& target : compact_targets) {
        if (target.kdf_type == WALLET_KDF_PBKDF2_SHA256) {
            ++keystore_pbkdf2_count;
        }
    }
    keystore_scrypt_offset = keystore_pbkdf2_count;
    for (const WalletKeystoreTarget& target : compact_targets) {
        if (target.kdf_type == WALLET_KDF_SCRYPT) {
            ++keystore_scrypt_count;
        }
    }

    bool keystore_has_scrypt = false;
    uint64_t max_scrypt_scratch_stride = 0;
    for (size_t i = 0; i < compact_targets.size(); ++i) {
        if (compact_targets[i].kdf_type == WALLET_KDF_SCRYPT) {
            keystore_has_scrypt = true;
            const uint64_t block_size = 128ull * static_cast<uint64_t>(compact_targets[i].scrypt_r);
            const uint64_t stride = wallet_scrypt_align_stride(
                block_size * static_cast<uint64_t>(compact_targets[i].scrypt_n) +
                block_size * static_cast<uint64_t>(compact_targets[i].scrypt_p) + 4ull + block_size);
            if (stride > max_scrypt_scratch_stride) {
                max_scrypt_scratch_stride = stride;
            }
        }
    }

    printf("[!] starting KEYSTORE mode [!]\n");
    printf("[!] loaded keystore targets: %zu [!]\n", compact_targets.size());
    printf("[!] keystore KDF groups: pbkdf2=%u scrypt=%u [!]\n",
        keystore_pbkdf2_count, keystore_scrypt_count);
    if (duplicate_keystore_targets != 0u) {
        printf("[!] keystore compact targets: %zu unique [saved %zu duplicate KDF check(s)] [!]\n",
            compact_targets.size(), duplicate_keystore_targets);
    }
    if (skipped_files != 0u) {
        printf("[!] skipped keystore files: %zu [!]\n", skipped_files);
    }
    if (warning_suppressed != 0u) {
        printf("[!] keystore load warnings suppressed: %zu more skipped/invalid file warning(s) [!]\n",
            warning_suppressed);
    }
    wallet_print_skip_reason_summary("keystore", skip_reasons, skipped_files);
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after keystore target load [!]\n");
        return metalSuccess;
    }

    const uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0
        ? n_number
        : static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
    const bool keystore_dictionary_mode = wallet_masks.empty() && !seqMode;
    WalletPassReader keystore_dictionary_reader;
    std::vector<WalletPassBuf> keystore_dictionary_batches;
    bool keystore_dictionary_batch_ready = false;
    uint64_t keystore_dictionary_concurrency_cap = std::min<uint64_t>(
        wallet_scrypt_default_concurrency_cap(),
        WALLET_KEYSTORE_SCRYPT_LARGE_DICTIONARY_CONCURRENCY_CAP);
    if (keystore_dictionary_mode) {
        if (mnemonicFiles.empty()) {
            fprintf(stderr, "[!] Error: -keystore requires candidate input: -i FILE, -mask MASK, or -start/-end [!]\n");
            return metalErrorInvalidValue;
        }
        if (!keystore_dictionary_reader.open(mnemonicFiles, IS_HEX)) {
            fprintf(stderr, "[!] Error: %s [!]\n", keystore_dictionary_reader.error.c_str());
            return metalErrorInvalidValue;
        }
        const uint32_t batch_sz = static_cast<uint32_t>(std::min<uint64_t>(
            static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()),
            wallet_generated_launch_chunk));
        keystore_dictionary_batch_ready = wallet_read_split_pass_batch(
            keystore_dictionary_reader,
            batch_sz,
            g_gpu_contexts.size(),
            keystore_dictionary_batches);
        if (keystore_dictionary_reader.failed) {
            fprintf(stderr, "[!] Error: %s [!]\n", keystore_dictionary_reader.error.c_str());
            return metalErrorInvalidValue;
        }
        uint32_t max_batch_count = 0u;
        for (const WalletPassBuf& batch : keystore_dictionary_batches) {
            max_batch_count = std::max<uint32_t>(max_batch_count, batch.count);
        }
        if (max_batch_count <= WALLET_KEYSTORE_SCRYPT_SMALL_BATCH_CONCURRENCY_CAP) {
            keystore_dictionary_concurrency_cap = std::min<uint64_t>(
                keystore_dictionary_concurrency_cap,
                WALLET_KEYSTORE_SCRYPT_SMALL_BATCH_CONCURRENCY_CAP);
        } else if (max_batch_count <= WALLET_KEYSTORE_SCRYPT_DEFAULT_CONCURRENCY_CAP) {
            keystore_dictionary_concurrency_cap = std::min<uint64_t>(
                keystore_dictionary_concurrency_cap,
                WALLET_KEYSTORE_SCRYPT_DEFAULT_CONCURRENCY_CAP);
        }
    }

    std::vector<WalletKeystoreDeviceState> states(g_gpu_contexts.size());
    std::vector<uint8_t> solved_files(target_files.size(), 0u);
    {
        std::lock_guard<std::mutex> solved_lock(keystore_solved_mutex);
        keystore_solved_version = 0ull;
    }
    bool all_solved = false;
    metalError_t st = metalSuccess;
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) {
            st = metalErrorInvalidDevice;
            goto Done;
        }
        states[gi].target_count = static_cast<uint32_t>(compact_targets.size());
        states[gi].solved_count = static_cast<uint32_t>(target_files.size());
        states[gi].target_file_indices.clear();
        states[gi].target_file_indices.reserve(compact_targets.size());
        for (const WalletKeystoreTarget& target : compact_targets) {
            states[gi].target_file_indices.push_back(target.target_index);
        }
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), compact_targets.size() * sizeof(WalletKeystoreTarget));
        if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, compact_targets.data(), compact_targets.size() * sizeof(WalletKeystoreTarget), metalMemcpyHostToDevice);
        if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), target_files.empty() ? 1u : target_files.size());
        if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, target_files.empty() ? 1u : target_files.size());
        if (st != metalSuccess) goto Done;
        if (keystore_has_scrypt) {
            size_t free_mem = 0, total_mem = 0;
            st = metalMemGetInfo(&free_mem, &total_mem);
            if (st != metalSuccess) goto Done;
            const uint64_t reserve_target = wallet_scrypt_memory_reserve_bytes();
            const uint64_t reserve = std::min<uint64_t>(
                static_cast<uint64_t>(free_mem / 2u),
                reserve_target);
            const uint64_t hard_cap = static_cast<uint64_t>(free_mem > reserve ? free_mem - reserve : free_mem / 2u);
            uint64_t concurrency = max_scrypt_scratch_stride ? (hard_cap / max_scrypt_scratch_stride) : 0ull;
            const uint64_t launch_lanes = static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
            if (concurrency > launch_lanes) concurrency = launch_lanes;
            const uint64_t requested_concurrency_cap = use_n_count && n_number > 0
                ? n_number
                : (keystore_dictionary_mode
                    ? keystore_dictionary_concurrency_cap
                    : wallet_keystore_scrypt_default_concurrency_cap());
            if (concurrency > requested_concurrency_cap) concurrency = requested_concurrency_cap;
            if (concurrency == 0ull) {
                fprintf(stderr, "[!] Error: not enough GPU memory for keystore scrypt scratch on GPU %d; need at least %llu bytes [!]\n",
                    g_gpu_contexts[gi].device_id,
                    static_cast<unsigned long long>(max_scrypt_scratch_stride));
                st = metalErrorMemoryAllocation;
                goto Done;
            }
            const uint64_t requested_concurrency = concurrency;
            while (concurrency > 0ull) {
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].scrypt_scratch),
                    static_cast<size_t>(concurrency * max_scrypt_scratch_stride));
                if (st == metalSuccess) {
                    break;
                }
                if (st != metalErrorMemoryAllocation) goto Done;
                states[gi].scrypt_scratch = nullptr;
                concurrency = wallet_scrypt_next_backoff_concurrency(concurrency);
            }
            if (st != metalSuccess || concurrency == 0ull) goto Done;
            states[gi].scrypt_scratch_stride = max_scrypt_scratch_stride;
            states[gi].scrypt_concurrency = concurrency;
            if (concurrency != requested_concurrency) {
                printf("[!] GPU %d keystore scrypt scratch allocation backoff: %llu -> %llu active candidates [!]\n",
                    g_gpu_contexts[gi].device_id,
                    static_cast<unsigned long long>(requested_concurrency),
                    static_cast<unsigned long long>(concurrency));
            }
            printf("[!] GPU %d keystore scrypt scratch: %.2f MiB, active candidates/launch: %llu [!]\n",
                g_gpu_contexts[gi].device_id,
                static_cast<double>(concurrency * max_scrypt_scratch_stride) / 1048576.0,
                static_cast<unsigned long long>(concurrency));
            printf("[!] GPU %d keystore scrypt memory reserve: %.2f MiB [!]\n",
                g_gpu_contexts[gi].device_id,
                static_cast<double>(reserve) / 1048576.0);
        }
    }
    if (keystore_has_scrypt) {
        uint64_t min_concurrency = std::numeric_limits<uint64_t>::max();
        for (const auto& state : states) {
            min_concurrency = std::min<uint64_t>(min_concurrency, state.scrypt_concurrency);
        }
        if (min_concurrency == 0 || min_concurrency == std::numeric_limits<uint64_t>::max()) {
            st = metalErrorMemoryAllocation;
            goto Done;
        }
        if (keystore_pbkdf2_count != 0u && min_concurrency < wallet_generated_launch_chunk) {
            printf("[!] keystore mixed KDF scheduler: PBKDF2 window=%llu, scrypt sublaunch<=%llu candidate(s)/GPU [!]\n",
                static_cast<unsigned long long>(wallet_generated_launch_chunk),
                static_cast<unsigned long long>(min_concurrency));
        }
    }

    if (!wallet_masks.empty()) {
        for (const auto& mask : wallet_masks) {
            if (all_solved) break;
            WalletMaskSpec spec{};
            std::string err;
            if (!wallet_prepare_mask_spec(mask, spec, err)) {
                fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str());
                st = metalErrorInvalidValue;
                goto Done;
            }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                if (states[gi].mask_spec == nullptr) {
                    st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec));
                    if (st != metalSuccess) goto Done;
                }
                st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice);
                if (st != metalSuccess) goto Done;
            }

            const uint64_t launch_chunk = wallet_generated_launch_chunk;
            uint64_t processed = 0;
            while (processed < spec.total_candidates && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                uint64_t round_base = processed;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    const uint64_t start = round_base + static_cast<uint64_t>(gi) * launch_chunk;
                    if (start >= spec.total_candidates) break;
                    const uint64_t count = std::min<uint64_t>(launch_chunk, spec.total_candidates - start);
                    workers.emplace_back([&, gi, start, count]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        if (keystore_pbkdf2_count != 0u) {
                            gst[gi] = wallet_launch_keystore_generated(states[gi], WALLET_CANDIDATE_MASK,
                                keystore_pbkdf2_offset, keystore_pbkdf2_count, false,
                                start, count, target_files, solved_files, all_solved);
                        }
                        if (gst[gi] == metalSuccess && keystore_scrypt_count != 0u && !all_solved) {
                            gst[gi] = wallet_launch_keystore_generated(states[gi], WALLET_CANDIDATE_MASK,
                                keystore_scrypt_offset, keystore_scrypt_count, true,
                                start, count, target_files, solved_files, all_solved);
                        }
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                                g_gpu_contexts[gi] = capture_current_gpu_context();
                            }
                        }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
                const uint64_t step = launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                if (processed > std::numeric_limits<uint64_t>::max() - step) break;
                processed += step;
            }
        }
    }
    else if (seqMode) {
        WalletRangeHostState range_state{};
        std::string err;
        if (!wallet_prepare_range_state(range_state, err)) {
            fprintf(stderr, "[!] Error: invalid wallet raw range: %s [!]\n", err.c_str());
            st = metalErrorInvalidValue;
            goto Done;
        }
        for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
            if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
            st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec));
            if (st != metalSuccess) goto Done;
        }
        const uint64_t launch_chunk = wallet_generated_launch_chunk;
        while (range_state.valid && !all_solved) {
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                WalletRangeSpec spec{};
                uint64_t count = 0;
                if (!wallet_range_next_window(range_state, launch_chunk, spec, count)) break;
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice);
                if (st != metalSuccess) goto Done;
                workers.emplace_back([&, gi, count]() {
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                    }
                    if (keystore_pbkdf2_count != 0u) {
                        gst[gi] = wallet_launch_keystore_generated(states[gi], WALLET_CANDIDATE_RANGE,
                            keystore_pbkdf2_offset, keystore_pbkdf2_count, false,
                            0ull, count, target_files, solved_files, all_solved);
                    }
                    if (gst[gi] == metalSuccess && keystore_scrypt_count != 0u && !all_solved) {
                        gst[gi] = wallet_launch_keystore_generated(states[gi], WALLET_CANDIDATE_RANGE,
                            keystore_scrypt_offset, keystore_scrypt_count, true,
                            0ull, count, target_files, solved_files, all_solved);
                    }
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                            g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                    }
                    });
            }
            if (workers.empty()) break;
            for (auto& th : workers) th.join();
            for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
        }
    }
    else {
        std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
        std::vector<std::thread> workers;
        workers.reserve(g_gpu_contexts.size());
        while (!all_solved) {
            bool any = keystore_dictionary_batch_ready;
            if (keystore_dictionary_batch_ready) {
                keystore_dictionary_batch_ready = false;
            }
            else {
                const uint32_t batch_sz = static_cast<uint32_t>(std::min<uint64_t>(
                    static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()),
                    wallet_generated_launch_chunk));
                any = wallet_read_split_pass_batch(
                    keystore_dictionary_reader,
                    batch_sz,
                    g_gpu_contexts.size(),
                    keystore_dictionary_batches);
            }
            if (keystore_dictionary_reader.failed) {
                fprintf(stderr, "[!] Error: %s [!]\n", keystore_dictionary_reader.error.c_str());
                st = metalErrorInvalidValue;
                goto Done;
            }
            if (!any) break;
            std::fill(gst.begin(), gst.end(), metalSuccess);
            workers.clear();
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (keystore_dictionary_batches[gi].count == 0) continue;
                workers.emplace_back([&, gi]() {
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                    }
                    if (keystore_pbkdf2_count != 0u) {
                        gst[gi] = wallet_launch_keystore_dict_batch(keystore_dictionary_batches[gi], states[gi],
                            keystore_pbkdf2_offset, keystore_pbkdf2_count, false,
                            target_files, solved_files, all_solved);
                    }
                    if (gst[gi] == metalSuccess && keystore_scrypt_count != 0u && !all_solved) {
                        gst[gi] = wallet_launch_keystore_dict_batch(keystore_dictionary_batches[gi], states[gi],
                            keystore_scrypt_offset, keystore_scrypt_count, true,
                            target_files, solved_files, all_solved);
                    }
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                            g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                    }
                    });
            }
            for (auto& th : workers) th.join();
            for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
        }
    }

Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_keystore_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalWalletDat()
{
    std::vector<std::string> files = wallet_artifact_files;
    for (const auto& dir : wallet_artifact_dirs) {
        if (walletdat_scan_all) {
            wallet_scan_dir(dir, { "*" }, files);
        }
        else {
            wallet_scan_dir(dir, { ".dat" }, files);
        }
    }
    if (files.empty()) {
        fprintf(stderr, "[!] Error: -walletdat requires one or more .dat files or -f DIR [!]\n");
        return metalErrorInvalidValue;
    }
    printf("[!] wallet.dat files discovered: %zu%s [!]\n", files.size(), walletdat_scan_all ? " (scan-all)" : "");
    fflush(stdout);

    std::vector<WalletDatHostTarget> host_targets;
    std::vector<std::string> target_files;
    target_files.reserve(files.size());
    size_t skipped_files = 0;
    size_t processed_files = 0;
    size_t loaded_hash_lines = 0;
    size_t skipped_hash_lines = 0;
    const bool compact_load_log = files.size() > 256u;
    size_t load_warning_printed = 0;
    size_t load_warning_suppressed = 0;
    const size_t kWalletDatMaxInlineWarnings = compact_load_log ? 16u : 64u;
    walletdat_quiet_raw_ckey_cap_warnings = compact_load_log;
    walletdat_raw_ckey_cap_warning_count = 0u;
    auto print_load_warning = [&](const char* fmt, const std::string& path, const std::string& detail) {
        if (load_warning_printed < kWalletDatMaxInlineWarnings) {
            fprintf(stderr, fmt, path.c_str(), detail.c_str());
            ++load_warning_printed;
        }
        else {
            ++load_warning_suppressed;
        }
    };
    const auto load_begin = std::chrono::steady_clock::now();
    auto load_last_report = load_begin;
    auto print_load_progress = [&](const bool force) {
        const auto now = std::chrono::steady_clock::now();
        const double since_last = std::chrono::duration<double>(now - load_last_report).count();
        if (!force && since_last < 5.0 && processed_files != files.size()) {
            return;
        }
        load_last_report = now;
        const double elapsed = std::chrono::duration<double>(now - load_begin).count();
        printf("[!] wallet.dat load progress: %zu/%zu files | loaded:%zu skipped:%zu targets:%zu | %.1fs [!]\n",
            processed_files, files.size(), target_files.size(), skipped_files, host_targets.size(), elapsed);
        fflush(stdout);
    };

    const size_t loader_threads = walletdat_loader_thread_count(files.size());
    if (loader_threads > 1u) {
        printf("[!] wallet.dat loader threads: %zu [!]\n", loader_threads);
        fflush(stdout);
    }
    std::vector<WalletDatLoadFileResult> load_results(files.size());
    std::atomic<size_t> next_file_idx{ 0u };
    std::atomic<size_t> done_files{ 0u };
    std::atomic<size_t> loaded_labels_live{ 0u };
    std::atomic<size_t> skipped_files_live{ 0u };
    std::atomic<size_t> loaded_targets_live{ 0u };

    auto load_worker = [&]() {
        for (;;) {
            const size_t idx = next_file_idx.fetch_add(1u, std::memory_order_relaxed);
            if (idx >= files.size()) {
                break;
            }
            WalletDatLoadFileResult result = walletdat_load_one_file(files[idx], walletdat_scan_all);
            if (result.loaded) {
                loaded_labels_live.fetch_add(result.labels.size(), std::memory_order_relaxed);
                loaded_targets_live.fetch_add(result.targets.size(), std::memory_order_relaxed);
            }
            else if (result.skipped) {
                skipped_files_live.fetch_add(1u, std::memory_order_relaxed);
            }
            load_results[idx] = std::move(result);
            done_files.fetch_add(1u, std::memory_order_release);
        }
    };

    std::vector<std::thread> loader_pool;
    loader_pool.reserve(loader_threads);
    for (size_t t = 0u; t < loader_threads; ++t) {
        loader_pool.emplace_back(load_worker);
    }
    while (done_files.load(std::memory_order_acquire) < files.size()) {
        processed_files = done_files.load(std::memory_order_relaxed);
        const size_t loaded_live = loaded_labels_live.load(std::memory_order_relaxed);
        const size_t skipped_live = skipped_files_live.load(std::memory_order_relaxed);
        const size_t targets_live = loaded_targets_live.load(std::memory_order_relaxed);
        const auto now = std::chrono::steady_clock::now();
        const double since_last = std::chrono::duration<double>(now - load_last_report).count();
        if (since_last >= 5.0) {
            load_last_report = now;
            const double elapsed = std::chrono::duration<double>(now - load_begin).count();
            printf("[!] wallet.dat load progress: %zu/%zu files | loaded:%zu skipped:%zu targets:%zu | %.1fs [!]\n",
                processed_files, files.size(), loaded_live, skipped_live, targets_live, elapsed);
            fflush(stdout);
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(250));
    }
    for (std::thread& t : loader_pool) {
        if (t.joinable()) {
            t.join();
        }
    }

    for (WalletDatLoadFileResult& result : load_results) {
        if (!result.loaded) {
            ++skipped_files;
            print_load_warning("[!] Warning: wallet.dat '%s': skipped, %s [!]\n", result.path, result.err.empty() ? "unsupported or invalid" : result.err);
            continue;
        }
        const uint32_t base_index = static_cast<uint32_t>(target_files.size());
        for (const std::string& label : result.labels) {
            target_files.push_back(label);
        }
        for (WalletDatHostTarget& target : result.targets) {
            const uint32_t local_index = target.dev.target_index;
            const uint32_t mapped_index = base_index + ((local_index < result.labels.size()) ? local_index : 0u);
            target.dev.target_index = mapped_index;
            target.file = target_files[mapped_index];
            host_targets.push_back(target);
        }
        loaded_hash_lines += result.valid_hash_lines;
        skipped_hash_lines += result.invalid_hash_lines;
        walletdat_raw_ckey_cap_warning_count += result.raw_ckey_cap_hits;
        if (!compact_load_log) {
            if (result.valid_hash_lines != 0u) {
                printf("[!] wallet.dat hash list '%s': loaded %zu $bitcoin$ target(s) [!]\n",
                    result.path.c_str(), result.valid_hash_lines);
            }
            else {
                printf("[!] wallet.dat '%s': loaded %zu encrypted key target(s) [!]\n",
                    result.path.c_str(), result.targets.size());
            }
        }
    }
    processed_files = files.size();
    print_load_progress(true);
    if (load_warning_suppressed != 0u) {
        fprintf(stderr, "[!] wallet.dat load warnings suppressed: %zu more skipped/invalid file warning(s) [!]\n",
            load_warning_suppressed);
    }
    if (walletdat_raw_ckey_cap_warning_count != 0u) {
        fprintf(stderr, "[!] wallet.dat raw ckey scan cap reached in %zu file(s) [!]\n",
            walletdat_raw_ckey_cap_warning_count);
    }
    wallet_print_skip_reason_summary_from_results("wallet.dat", load_results);
    walletdat_quiet_raw_ckey_cap_warnings = false;
    if (host_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable wallet.dat targets loaded");
        if (skipped_files != 0) {
            fprintf(stderr, " (%zu file(s) skipped)", skipped_files);
        }
        fprintf(stderr, " [!]\n");
        return metalErrorInvalidValue;
    }

    std::vector<WalletDatTarget> compact_targets;
    std::vector<std::string> runtime_target_files;
    walletdat_compact_master_targets(host_targets, compact_targets, runtime_target_files);
    if (compact_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable wallet.dat master targets after compaction [!]\n");
        return metalErrorInvalidValue;
    }
    size_t iteration_filtered_targets = 0u;
    if (walletdat_max_iterations_filter != 0u) {
        std::vector<WalletDatTarget> filtered_targets;
        std::vector<std::string> filtered_files;
        filtered_targets.reserve(compact_targets.size());
        filtered_files.reserve(runtime_target_files.size());
        for (size_t i = 0u; i < compact_targets.size(); ++i) {
            if (compact_targets[i].iterations > walletdat_max_iterations_filter) {
                ++iteration_filtered_targets;
                continue;
            }
            WalletDatTarget target = compact_targets[i];
            target.target_index = static_cast<uint32_t>(filtered_files.size());
            filtered_targets.push_back(target);
            filtered_files.push_back(i < runtime_target_files.size() ? runtime_target_files[i] : std::string());
        }
        compact_targets.swap(filtered_targets);
        runtime_target_files.swap(filtered_files);
        if (compact_targets.empty()) {
            fprintf(stderr, "[!] Error: -walletdat-max-iter filtered out every wallet.dat target [!]\n");
            return metalErrorInvalidValue;
        }
    }
    std::sort(compact_targets.begin(), compact_targets.end(),
        [](const WalletDatTarget& a, const WalletDatTarget& b) {
            if (a.iterations != b.iterations) return a.iterations < b.iterations;
            if (a.salt_len != b.salt_len) return a.salt_len < b.salt_len;
            const int salt_cmp = std::memcmp(a.salt, b.salt, std::min<uint32_t>(a.salt_len, b.salt_len));
            if (salt_cmp != 0) return salt_cmp < 0;
            return a.target_index < b.target_index;
        });
    counterWalletActiveTargets = static_cast<uint64_t>(compact_targets.size());
    std::vector<WalletDatGroup> kdf_groups;
    uint64_t grouped_iteration_work = 0ull;
    walletdat_build_kdf_groups(compact_targets, kdf_groups, grouped_iteration_work);
    counterWalletDatKdfWorkPerPassword = std::max<uint64_t>(1ull, grouped_iteration_work);
    std::vector<WalletDatTargetChunk> target_chunks;
    walletdat_build_group_chunks(kdf_groups, target_chunks);
    uint32_t min_iterations = compact_targets.front().iterations;
    uint32_t max_iterations = compact_targets.front().iterations;
    uint64_t total_iterations = 0ull;
    size_t slow_over_1m = 0u;
    size_t slow_over_5m = 0u;
    size_t slow_over_10m = 0u;
    for (const WalletDatTarget& target : compact_targets) {
        min_iterations = std::min<uint32_t>(min_iterations, target.iterations);
        max_iterations = std::max<uint32_t>(max_iterations, target.iterations);
        total_iterations += static_cast<uint64_t>(target.iterations);
        if (target.iterations > 1000000u) ++slow_over_1m;
        if (target.iterations > 5000000u) ++slow_over_5m;
        if (target.iterations > 10000000u) ++slow_over_10m;
    }
    const auto pct_iter = [&](const size_t pct) -> uint32_t {
        const size_t idx = std::min<size_t>(compact_targets.size() - 1u, (compact_targets.size() * pct) / 100u);
        return compact_targets[idx].iterations;
    };

    printf("[!] starting WALLETDAT mode [!]\n");
    printf("[!] loaded wallet.dat files: %zu [!]\n", target_files.size());
    if (walletdat_scan_all) {
        printf("[!] wallet.dat scan-all: enabled [!]\n");
        if (loaded_hash_lines != 0u || skipped_hash_lines != 0u) {
            printf("[!] wallet.dat $bitcoin$ hash lines: loaded=%zu skipped=%zu [!]\n",
                loaded_hash_lines, skipped_hash_lines);
        }
    }
    if (skipped_files != 0) {
        printf("[!] skipped wallet.dat files: %zu [!]\n", skipped_files);
    }
    if (walletdat_max_raw_ckey_records == 0u) {
        printf("[!] wallet.dat raw ckey scan cap: unlimited [!]\n");
    }
    else {
        printf("[!] wallet.dat raw ckey scan cap: %zu per file [!]\n", walletdat_max_raw_ckey_records);
    }
    printf("[!] loaded wallet.dat encrypted key targets: %zu [!]\n", host_targets.size());
    if (walletdat_max_iterations_filter != 0u) {
        printf("[!] wallet.dat iteration cap: <=%u [filtered %zu compact master target(s)] [!]\n",
            walletdat_max_iterations_filter, iteration_filtered_targets);
    }
    size_t compact_ckey_slots = 0u;
    for (const WalletDatTarget& t : compact_targets) {
        compact_ckey_slots += std::min<uint32_t>(t.ckey_count, WALLETDAT_MAX_CKEY_SLOTS);
    }
    if (compact_targets.size() != host_targets.size()) {
        printf("[!] wallet.dat compact master targets: %zu [saved %zu duplicate ckey checks] [!]\n",
            compact_targets.size(), host_targets.size() - compact_targets.size());
    }
    if (compact_ckey_slots != compact_targets.size()) {
        printf("[!] wallet.dat compact ckey slots: %zu [up to %u per master target] [!]\n",
            compact_ckey_slots, WALLETDAT_MAX_CKEY_SLOTS);
    }
    if (runtime_target_files.size() != target_files.size()) {
        printf("[!] wallet.dat runtime unique target labels: %zu [deduped %zu duplicate wallet labels] [!]\n",
            runtime_target_files.size(), target_files.size() - runtime_target_files.size());
    }
    printf("[!] wallet.dat iterations: min=%u p50=%u p90=%u p99=%u max=%u avg=%.1f [!]\n",
        min_iterations, pct_iter(50), pct_iter(90), pct_iter(99), max_iterations,
        static_cast<double>(total_iterations) / static_cast<double>(compact_targets.size()));
    if (slow_over_1m != 0u) {
        printf("[!] wallet.dat slow iteration targets: >1M=%zu >5M=%zu >10M=%zu [use -walletdat-max-iter N to exclude for speed] [!]\n",
            slow_over_1m, slow_over_5m, slow_over_10m);
    }
    if (!kdf_groups.empty()) {
        const double kdf_saved = grouped_iteration_work == 0ull
            ? 1.0
            : static_cast<double>(total_iterations) / static_cast<double>(grouped_iteration_work);
        printf("[!] wallet.dat KDF groups: %zu [saved %.2fx SHA512 KDF work] [!]\n",
            kdf_groups.size(), kdf_saved);
    }
    printf("[!] wallet.dat launch chunks: %zu chunk(s), <=%llu KDF-iterations per launch window [!]\n",
        target_chunks.size(), static_cast<unsigned long long>(walletdat_max_kdf_iter_work_per_launch));
    {
        size_t uniform_chunks = 0u;
        uint64_t padded_work = 0ull;
        for (const WalletDatTargetChunk& chunk : target_chunks) {
            if (chunk.min_iterations == chunk.max_iterations) {
                ++uniform_chunks;
            }
            padded_work += static_cast<uint64_t>(chunk.count) * static_cast<uint64_t>(chunk.max_iterations);
        }
        const double efficiency = padded_work == 0ull
            ? 100.0
            : (100.0 * static_cast<double>(grouped_iteration_work)) / static_cast<double>(padded_work);
        printf("[!] wallet.dat KDF chunk efficiency: %.2f%% [%zu uniform chunk(s)] [!]\n",
            efficiency, uniform_chunks);
    }
    if (!WALLET_LOAD_ONLY) {
        printf("[!] wallet.dat launch min jobs: %llu password-target job(s)%s [!]\n",
            static_cast<unsigned long long>(walletdat_effective_min_jobs_per_launch()),
            walletdat_min_jobs_per_launch == 0ull ? " (auto capped occupancy)" : "");
        printf("[!] wallet.dat staged KDF loop: %u iteration(s)/kernel [!]\n",
            walletdat_staged_kdf_loop_iters);
    }
    fflush(stdout);
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after wallet.dat target load [!]\n");
        return metalSuccess;
    }
    std::vector<uint8_t> solved_files(runtime_target_files.size(), 0u);
    {
        std::lock_guard<std::mutex> solved_lock(walletdat_solved_mutex);
        walletdat_solved_version = 0ull;
    }
    bool all_solved = false;

    std::vector<WalletDatDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    const uint64_t wallet_requested_launch_chunk = use_n_count && n_number > 0 ? n_number : static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
    const uint64_t wallet_generated_launch_chunk = walletdat_effective_generated_window(wallet_requested_launch_chunk);
    if (wallet_generated_launch_chunk != wallet_requested_launch_chunk) {
        printf("[!] wallet.dat generated launch window raised to %llu candidate(s)/GPU for occupancy (requested %llu) [!]\n",
            static_cast<unsigned long long>(wallet_generated_launch_chunk),
            static_cast<unsigned long long>(wallet_requested_launch_chunk));
        fflush(stdout);
    }
    uint64_t walletdat_tmp_candidate_window = wallet_generated_launch_chunk;
    if (wallet_masks.empty() && !seqMode && !mnemonicFiles.empty()) {
        walletdat_tmp_candidate_window = wallet_effective_dict_batch_per_gpu(wallet_generated_launch_chunk);
    }
    const uint64_t walletdat_tmp_capacity = walletdat_estimate_kdf_tmp_capacity(target_chunks, walletdat_tmp_candidate_window);
    if (walletdat_tmp_capacity != walletdat_launch_thread_count()) {
        printf("[!] wallet.dat KDF tmp jobs: %llu [reduced from %llu for current launch window] [!]\n",
            static_cast<unsigned long long>(walletdat_tmp_capacity),
            static_cast<unsigned long long>(walletdat_launch_thread_count()));
        fflush(stdout);
    }
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) {
            st = metalErrorInvalidDevice;
            goto Done;
        }
        states[gi].target_count = static_cast<uint32_t>(compact_targets.size());
        states[gi].group_count = static_cast<uint32_t>(kdf_groups.size());
        states[gi].solved_count = static_cast<uint32_t>(runtime_target_files.size());
        states[gi].target_chunks = target_chunks;
        states[gi].target_file_indices.reserve(compact_targets.size());
        for (const WalletDatTarget& target : compact_targets) {
            states[gi].target_file_indices.push_back(target.target_index);
        }
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), compact_targets.size() * sizeof(WalletDatTarget));
        if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, compact_targets.data(), compact_targets.size() * sizeof(WalletDatTarget), metalMemcpyHostToDevice);
        if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].groups), std::max<size_t>(1u, kdf_groups.size()) * sizeof(WalletDatGroup));
        if (st != metalSuccess) goto Done;
        if (!kdf_groups.empty()) {
            st = metalMemcpy(states[gi].groups, kdf_groups.data(), kdf_groups.size() * sizeof(WalletDatGroup), metalMemcpyHostToDevice);
            if (st != metalSuccess) goto Done;
        }
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].master_hits), static_cast<size_t>(std::max<uint32_t>(1u, MAX_FOUNDS)) * sizeof(WalletDatMasterHit));
        if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].master_hit_count), sizeof(uint32_t));
        if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].master_hit_count, 0, sizeof(uint32_t));
        if (st != metalSuccess) goto Done;
        states[gi].kdf_tmp_capacity = walletdat_tmp_capacity;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].kdf_tmp), static_cast<size_t>(states[gi].kdf_tmp_capacity) * sizeof(WalletDatKdfTmp));
        if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), runtime_target_files.empty() ? 1u : runtime_target_files.size());
        if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, runtime_target_files.empty() ? 1u : runtime_target_files.size());
        if (st != metalSuccess) goto Done;
    }

    {
        if (!wallet_masks.empty()) {
            for (const auto& mask : wallet_masks) {
                WalletMaskSpec spec{};
                std::string err;
                if (!wallet_prepare_mask_spec(mask, spec, err)) {
                    fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str());
                    st = metalErrorInvalidValue;
                    goto Done;
                }
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    if (states[gi].mask_spec == nullptr) {
                        st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec));
                        if (st != metalSuccess) goto Done;
                    }
                    st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice);
                    if (st != metalSuccess) goto Done;
                }

                const uint64_t launch_chunk = wallet_generated_launch_chunk;
                uint64_t processed = 0;
                while (processed < spec.total_candidates && !all_solved) {
                    std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                    std::vector<std::thread> workers;
                    const uint64_t round_base = processed;
                    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                        const uint64_t start = round_base + static_cast<uint64_t>(gi) * launch_chunk;
                        if (start >= spec.total_candidates) break;
                        const uint64_t count = std::min<uint64_t>(launch_chunk, spec.total_candidates - start);
                        workers.emplace_back([&, gi, start, count]() {
                            {
                                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                                if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                            }
                            gst[gi] = wallet_launch_walletdat_generated(states[gi], WALLET_CANDIDATE_MASK, start, count, runtime_target_files, solved_files, all_solved);
                            {
                                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                                if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                                    g_gpu_contexts[gi] = capture_current_gpu_context();
                                }
                            }
                            });
                    }
                    for (auto& th : workers) th.join();
                    for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
                    const uint64_t step = launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                    if (processed > std::numeric_limits<uint64_t>::max() - step) break;
                    processed += step;
                }
            }
        }
        else if (seqMode) {
            WalletRangeHostState range_state{};
            std::string err;
            if (!wallet_prepare_range_state(range_state, err)) {
                fprintf(stderr, "[!] Error: invalid wallet raw range: %s [!]\n", err.c_str());
                st = metalErrorInvalidValue;
                goto Done;
            }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec));
                if (st != metalSuccess) goto Done;
            }
            const uint64_t launch_chunk = wallet_generated_launch_chunk;
            while (range_state.valid && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    WalletRangeSpec spec{};
                    uint64_t count = 0;
                    if (!wallet_range_next_window(range_state, launch_chunk, spec, count)) break;
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice);
                    if (st != metalSuccess) goto Done;
                    workers.emplace_back([&, gi, count]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_walletdat_generated(states[gi], WALLET_CANDIDATE_RANGE, 0ull, count, runtime_target_files, solved_files, all_solved);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                                g_gpu_contexts[gi] = capture_current_gpu_context();
                            }
                        }
                        });
                }
                if (workers.empty()) break;
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
            }
        }
        else {
            if (mnemonicFiles.empty()) {
                fprintf(stderr, "[!] Error: -walletdat requires candidate input: -i FILE, -mask MASK, or -start/-end [!]\n");
                st = metalErrorInvalidValue;
                goto Done;
            }
            WalletPassReader reader;
            if (!reader.open(mnemonicFiles, IS_HEX)) {
                fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str());
                st = metalErrorInvalidValue;
                goto Done;
            }
            const uint32_t steady_per_gpu_batch_sz = wallet_effective_dict_batch_u32("wallet.dat", wallet_generated_launch_chunk);
            const bool use_early_probe = walletdat_dict_use_early_probe(target_chunks);
            const uint32_t first_probe_batch = walletdat_dict_batch_for_round(steady_per_gpu_batch_sz, 0ull, use_early_probe);
            if (first_probe_batch < steady_per_gpu_batch_sz) {
                printf("[!] wallet.dat dictionary early probe: 4096/65536/262144 password(s)/GPU before steady %u [!]\n",
                    steady_per_gpu_batch_sz);
                fflush(stdout);
            }
            else if (!use_early_probe && target_chunks.size() > 1u) {
                printf("[!] wallet.dat dictionary early probe skipped for %zu target chunk(s); using steady %u password(s)/GPU [!]\n",
                    target_chunks.size(), steady_per_gpu_batch_sz);
                fflush(stdout);
            }
            std::vector<WalletPassBuf> batches;
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            workers.reserve(g_gpu_contexts.size());
            uint64_t dict_batch_round = 0ull;
            while (!all_solved) {
                const uint32_t per_gpu_batch_sz = walletdat_dict_batch_for_round(steady_per_gpu_batch_sz, dict_batch_round, use_early_probe);
                ++dict_batch_round;
                const bool any = wallet_read_split_pass_batch(reader, per_gpu_batch_sz, g_gpu_contexts.size(), batches);
                if (reader.failed) {
                    fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str());
                    st = metalErrorInvalidValue;
                    goto Done;
                }
                if (!any) break;
                std::fill(gst.begin(), gst.end(), metalSuccess);
                workers.clear();
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (batches[gi].count == 0) continue;
                    workers.emplace_back([&, gi]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_walletdat_dict_batch(batches[gi], states[gi], runtime_target_files, solved_files, all_solved);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                                g_gpu_contexts[gi] = capture_current_gpu_context();
                            }
                        }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
            }
        }
    }

Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_walletdat_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalWalletJS()
{
    if (walletjs_profile.empty()) {
        fprintf(stderr, "[!] Error: -walletjs requires PROFILE [!]\n");
        return metalErrorInvalidValue;
    }
    WalletJsHostProfile profile;
    std::string err;
    if (!walletjs_parse_profile(walletjs_profile, profile, err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", err.c_str());
        return metalErrorInvalidValue;
    }
    if (Solana || Ton || Ton_all || Dot || Aptos || Sui || Xrp || Exodus || Iota || Ada || Icp || Fil || Xtz || Endomorphism) {
        fprintf(stderr, "[!] Error: -walletjs currently supports only secp targets c/u/s/p/r/x/e [!]\n");
        return metalErrorInvalidValue;
    }
    if (!Compressed && !Uncompressed && !Segwit && !P2wsh && !Taproot && !Ethereum && !Xpoint) {
        fprintf(stderr, "[!] Error: -walletjs requires at least one secp target in -c c/u/s/p/r/x/e [!]\n");
        return metalErrorInvalidValue;
    }

    printf("[!] starting WALLETJS mode [!]\n");
    printf("[!] walletjs profile: %s [!]\n", profile.name.c_str());
    const std::vector<std::string> profile_names = { profile.name };

    std::vector<WalletJsDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    const uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0 ? n_number : static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;

    if (profile.exact_seed_profile) {
        if (!walletjs_time_start_seen || !walletjs_time_end_seen) {
            fprintf(stderr, "[!] Error: walletjs exact JSBN ARC4 profiles require -time-s HEX and -time-e HEX [!]\n");
            st = metalErrorInvalidValue;
            goto Done;
        }
        if (walletjs_time_end < walletjs_time_start) {
            fprintf(stderr, "[!] Error: -time-e must be >= -time-s for walletjs exact JSBN ARC4 profiles [!]\n");
            st = metalErrorInvalidValue;
            goto Done;
        }
        if (end_seed64 < start_seed64) {
            fprintf(stderr, "[!] Error: -e must be >= -s for walletjs exact JSBN ARC4 profiles [!]\n");
            st = metalErrorInvalidValue;
            goto Done;
        }
        const uint64_t state_count = end_seed64 - start_seed64 + 1ull;
        const uint64_t time_count = static_cast<uint64_t>(walletjs_time_end - walletjs_time_start) + 1ull;
        const uint64_t delta_count = static_cast<uint64_t>(walletjs_time_delta_max) + 1ull;
        uint64_t total_state_time = 0ull;
        uint64_t flat_total = 0ull;
        if (!mul_u64_checked(state_count, time_count, total_state_time) ||
            !mul_u64_checked(total_state_time, delta_count, flat_total)) {
            fprintf(stderr, "[!] Error: walletjs exact JSBN ARC4 scan range overflows uint64 [!]\n");
            st = metalErrorInvalidValue;
            goto Done;
        }
        profile.spec.randstorm_state_start = start_seed64;
        profile.spec.randstorm_time_start = walletjs_time_start;
        profile.spec.randstorm_time_count = time_count;
        profile.spec.randstorm_time_delta_count = static_cast<uint32_t>(delta_count);
        printf("[!] walletjs exact JSBN ARC4 state range: %016llx-%016llx [!]\n",
            (unsigned long long)start_seed64, (unsigned long long)end_seed64);
        printf("[!] walletjs exact JSBN ARC4 time low32 range: %08x-%08x delta=0..%u ms [!]\n",
            walletjs_time_start, walletjs_time_end, walletjs_time_delta_max);
        uint64_t flat_pos = 0ull;
        while (isRun && flat_pos < flat_total) {
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                const uint64_t start = flat_pos + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                if (start >= flat_total) break;
                const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, flat_total - start);
                workers.emplace_back([&, gi, start, count]() {
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                    }
                    gst[gi] = wallet_launch_walletjs_generated(states[gi], profile, WALLET_CANDIDATE_RANGE, start, count, profile_names);
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                            g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                    }
                    });
            }
            if (workers.empty()) break;
            for (auto& th : workers) th.join();
            for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
            const uint64_t step = wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
            if (flat_pos > std::numeric_limits<uint64_t>::max() - step) break;
            flat_pos += step;
        }
    }
    else if (profile.seed_profile) {
        uint64_t seed_pos = start_seed64;
        while (isRun && seed_pos <= end_seed64) {
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                const uint64_t start = isRandom
                    ? random_seed64_inclusive(start_seed64, end_seed64)
                    : seed_pos + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                if (!isRandom && start > end_seed64) break;
                const uint64_t remaining = end_seed64 - start;
                const uint64_t count = isRandom
                    ? wallet_generated_launch_chunk
                    : std::min<uint64_t>(wallet_generated_launch_chunk, remaining + 1ull);
                workers.emplace_back([&, gi, start, count]() {
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                    }
                    gst[gi] = wallet_launch_walletjs_generated(states[gi], profile, WALLET_CANDIDATE_RANGE, start, count, profile_names);
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                            g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                    }
                    });
            }
            if (workers.empty()) break;
            for (auto& th : workers) th.join();
            for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
            if (isRandom) {
                continue;
            }
            const uint64_t step = wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
            if (seed_pos > std::numeric_limits<uint64_t>::max() - step) break;
            seed_pos += step;
        }
    }
    else if (!wallet_masks.empty()) {
        for (const auto& mask : wallet_masks) {
            WalletMaskSpec spec{};
            if (!wallet_prepare_mask_spec(mask, spec, err)) {
                fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str());
                st = metalErrorInvalidValue;
                goto Done;
            }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                if (states[gi].mask_spec == nullptr) {
                    st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec));
                    if (st != metalSuccess) goto Done;
                }
                st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice);
                if (st != metalSuccess) goto Done;
            }
            uint64_t processed = 0;
            while (processed < spec.total_candidates) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    const uint64_t start = processed + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                    if (start >= spec.total_candidates) break;
                    const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, spec.total_candidates - start);
                    workers.emplace_back([&, gi, start, count]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_walletjs_generated(states[gi], profile, WALLET_CANDIDATE_MASK, start, count, profile_names);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                                g_gpu_contexts[gi] = capture_current_gpu_context();
                            }
                        }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
                const uint64_t step = wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                if (processed > std::numeric_limits<uint64_t>::max() - step) break;
                processed += step;
            }
        }
    }
    else if (seqMode) {
        WalletRangeHostState range_state{};
        if (!wallet_prepare_range_state(range_state, err)) {
            fprintf(stderr, "[!] Error: invalid walletjs raw range: %s [!]\n", err.c_str());
            st = metalErrorInvalidValue;
            goto Done;
        }
        for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
            if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
            st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec));
            if (st != metalSuccess) goto Done;
        }
        while (range_state.valid) {
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                WalletRangeSpec spec{};
                uint64_t count = 0;
                if (!wallet_range_next_window(range_state, wallet_generated_launch_chunk, spec, count)) break;
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice);
                if (st != metalSuccess) goto Done;
                workers.emplace_back([&, gi, count]() {
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                    }
                    gst[gi] = wallet_launch_walletjs_generated(states[gi], profile, WALLET_CANDIDATE_RANGE, 0ull, count, profile_names);
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                            g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                    }
                    });
            }
            if (workers.empty()) break;
            for (auto& th : workers) th.join();
            for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
        }
    }
    else {
        if (mnemonicFiles.empty()) {
            fprintf(stderr, "[!] Error: walletjs profile '%s' requires candidate input: -i FILE, -mask MASK, or -start/-end [!]\n", profile.name.c_str());
            st = metalErrorInvalidValue;
            goto Done;
        }
        WalletPassReader reader;
        if (!reader.open(mnemonicFiles, IS_HEX)) {
            fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str());
            st = metalErrorInvalidValue;
            goto Done;
        }
        const uint32_t batch_sz = static_cast<uint32_t>(std::min<uint64_t>(
            static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()),
            wallet_generated_launch_chunk));
        std::vector<WalletPassBuf> batches;
        std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
        std::vector<std::thread> workers;
        workers.reserve(g_gpu_contexts.size());
        while (true) {
            const bool any = wallet_read_split_pass_batch(reader, batch_sz, g_gpu_contexts.size(), batches);
            if (reader.failed) {
                fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str());
                st = metalErrorInvalidValue;
                goto Done;
            }
            if (!any) break;
            std::fill(gst.begin(), gst.end(), metalSuccess);
            workers.clear();
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (batches[gi].count == 0) continue;
                workers.emplace_back([&, gi]() {
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                    }
                    gst[gi] = wallet_launch_walletjs_dict_batch(batches[gi], states[gi], profile, profile_names);
                    {
                        std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                        if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) {
                            g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                    }
                    });
            }
            for (auto& th : workers) th.join();
            for (metalError_t e : gst) { if (e != metalSuccess) { st = e; goto Done; } }
        }
    }

Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_walletjs_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalBrowserVault()
{
    const bool substrate_mode = SUBSTRATEWALLET_MODE;
    const bool copay_mode = COPAYWALLET_MODE;
    const bool terra_mode = TERRAWALLET_MODE;
    const bool bitshares_mode = BITSHARESWALLET_MODE;
    const bool yoroi_mode = YOROIWALLET_MODE;
    const bool stellar_mode = STELLARWALLET_MODE;
    const bool blockchain_mode = BLOCKCHAINWALLET_MODE;
    const bool multibit_mode = MULTIBITWALLET_MODE;
    const bool bip38_mode = BIP38_MODE;
    const bool dogechain_mode = DOGECHAINWALLET_MODE;
    const bool ethpresale_mode = ETHPRESALE_MODE;
    const bool bisq_mode = BISQWALLET_MODE;
    const bool android_mode = ANDROIDWALLET_MODE;
    const char* mode_name = "BROWSERVAULT";
    const char* mode_lc = "browservault";
    if (stellar_mode) { mode_name = "STELLARWALLET"; mode_lc = "stellarwallet"; }
    if (blockchain_mode) { mode_name = "BLOCKCHAINWALLET"; mode_lc = "blockchainwallet"; }
    if (multibit_mode) { mode_name = "MULTIBITWALLET"; mode_lc = "multibitwallet"; }
    if (android_mode) { mode_name = "ANDROIDWALLET"; mode_lc = "androidwallet"; }
    if (dogechain_mode) { mode_name = "DOGECHAINWALLET"; mode_lc = "dogechainwallet"; }
    if (bisq_mode) { mode_name = "BISQWALLET"; mode_lc = "bisqwallet"; }
    if (ethpresale_mode) { mode_name = "ETHPRESALE"; mode_lc = "ethpresale"; }
    if (bip38_mode) { mode_name = "BIP38"; mode_lc = "bip38"; }
    if (terra_mode) { mode_name = "TERRAWALLET"; mode_lc = "terrawallet"; }
    if (bitshares_mode) { mode_name = "BITSHARESWALLET"; mode_lc = "bitshareswallet"; }
    if (yoroi_mode) { mode_name = "YOROIWALLET"; mode_lc = "yoroiwallet"; }
    if (copay_mode) { mode_name = "COPAYWALLET"; mode_lc = "copaywallet"; }
    if (substrate_mode) { mode_name = "SUBSTRATEWALLET"; mode_lc = "substratewallet"; }
    const std::vector<std::string> scan_exts = (blockchain_mode || dogechain_mode || ethpresale_mode || bip38_mode || bisq_mode || android_mode)
        ? std::vector<std::string>{ ".txt", ".hash", ".json", ".wallet", "" }
        : (multibit_mode
            ? std::vector<std::string>{ ".txt", ".hash", ".key", ".wallet", "" }
        : ((substrate_mode || copay_mode || bitshares_mode || yoroi_mode)
            ? std::vector<std::string>{ ".json", "" }
        : (terra_mode
            ? std::vector<std::string>{ ".json", ".txt", "" }
        : (stellar_mode
            ? std::vector<std::string>{ ".txt", ".hash", ".stellar", "" }
            : std::vector<std::string>{ ".ldb", ".log", ".json", ".txt", "" }))));

    std::vector<std::string> files = wallet_artifact_files;
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, scan_exts, files);
    }
    if (files.empty()) {
        fprintf(stderr, "[!] Error: -%s requires FILE or -f DIR [!]\n", mode_lc);
        return metalErrorInvalidValue;
    }
    printf("[!] %s files discovered: %zu [!]\n", mode_lc, files.size());

    std::vector<BrowserVaultHostTarget> host_targets;
    std::unordered_set<std::string> seen;
    size_t skipped_files = 0u;
    size_t warnings = 0u;
    std::vector<BrowserVaultLoadFileResult> load_results;
    if (substrate_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results,
                                   wallet_load_one_substratewallet_file);
    }
    else if (copay_mode) {
        wallet_parallel_load_files(
            files, mode_lc, load_results, wallet_load_one_copaywallet_file);
    }
    else if (terra_mode) {
        wallet_parallel_load_files(
            files, mode_lc, load_results, wallet_load_one_terrawallet_file);
    }
    else if (bitshares_mode) {
        wallet_parallel_load_files(
            files, mode_lc, load_results, wallet_load_one_bitshareswallet_file);
    }
    else if (yoroi_mode) {
        wallet_parallel_load_files(
            files, mode_lc, load_results,
            wallet_load_one_yoroiwallet_file);
    }
    else if (blockchain_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_blockchainwallet_file);
    }
    else if (multibit_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_multibitwallet_file);
    }
    else if (bisq_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_bisqwallet_file);
    }
    else if (bip38_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_bip38wallet_file);
    }
    else if (dogechain_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_dogechainwallet_file);
    }
    else if (android_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_androidwallet_file);
    }
    else if (ethpresale_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_ethpresalewallet_file);
    }
    else if (stellar_mode) {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_stellarwallet_file);
    }
    else {
        wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_browservault_file);
    }
    for (BrowserVaultLoadFileResult& result : load_results) {
        if (!result.loaded) {
            ++skipped_files;
            if (warnings < 32u) {
                fprintf(stderr, "[!] Warning: %s '%s': skipped, %s [!]\n",
                    mode_lc,
                    result.path.c_str(), result.err.empty() ? "unsupported or invalid" : result.err.c_str());
                ++warnings;
            }
            continue;
        }
        for (BrowserVaultHostTarget& target : result.targets) {
            const std::string key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
            if (!seen.insert(key).second) {
                continue;
            }
            if (target.file.empty()) target.file = result.path;
            host_targets.push_back(target);
        }
    }
    wallet_print_skip_reason_summary_from_results(mode_lc, load_results);
    if (host_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable %s targets loaded (%zu file(s) skipped) [!]\n", mode_lc, skipped_files);
        return metalErrorInvalidValue;
    }

    std::vector<std::string> target_files;
    std::vector<BrowserVaultHostTarget> sorted_targets;
    target_files.reserve(host_targets.size());
    sorted_targets.reserve(host_targets.size());
    for (size_t i = 0; i < host_targets.size(); ++i) {
        host_targets[i].dev.target_index = static_cast<uint32_t>(i);
        target_files.push_back(host_targets[i].file);
        sorted_targets.push_back(std::move(host_targets[i]));
    }
    std::sort(sorted_targets.begin(), sorted_targets.end(), [](const BrowserVaultHostTarget& a, const BrowserVaultHostTarget& b) {
        if (a.dev.profile != b.dev.profile) return a.dev.profile < b.dev.profile;
        if (a.dev.iterations != b.dev.iterations) return a.dev.iterations < b.dev.iterations;
        if (a.dev.scrypt_n != b.dev.scrypt_n) return a.dev.scrypt_n < b.dev.scrypt_n;
        if (a.dev.scrypt_r != b.dev.scrypt_r) return a.dev.scrypt_r < b.dev.scrypt_r;
        if (a.dev.scrypt_p != b.dev.scrypt_p) return a.dev.scrypt_p < b.dev.scrypt_p;
        if (a.dev.salt_len != b.dev.salt_len) return a.dev.salt_len < b.dev.salt_len;
        const int salt_cmp = memcmp(a.dev.salt, b.dev.salt, std::min<uint32_t>(a.dev.salt_len, b.dev.salt_len));
        if (salt_cmp != 0) return salt_cmp < 0;
        return a.dev.target_index < b.dev.target_index;
        });
    std::vector<BrowserVaultDeviceTarget> targets;
    std::vector<uint8_t> ciphertext_pool;
    targets.reserve(sorted_targets.size());
    uint64_t ciphertext_pool_bytes = 0ull;
    for (const BrowserVaultHostTarget& t : sorted_targets) {
        ciphertext_pool_bytes += static_cast<uint64_t>(t.ciphertext.size());
    }
    if (ciphertext_pool_bytes > static_cast<uint64_t>(std::numeric_limits<size_t>::max())) {
        fprintf(stderr, "[!] Error: browser vault ciphertext pool is too large for this host [!]\n");
        return metalErrorMemoryAllocation;
    }
    ciphertext_pool.reserve(static_cast<size_t>(ciphertext_pool_bytes));
    size_t metamask_targets = 0u;
    size_t phantom_pbkdf2_targets = 0u;
    size_t phantom_scrypt_targets = 0u;
    size_t substrate_scrypt_targets = 0u;
    size_t substrate_legacy_targets = 0u;
    size_t copay_sjcl_targets = 0u;
    size_t terra_station_targets = 0u;
    size_t bitshares_0x_targets = 0u;
    size_t yoroi_emip3_targets = 0u;
    size_t atomic_cryptojs_targets = 0u;
    size_t stellar_targets = 0u;
    size_t blockchain_targets = 0u;
    size_t multibit_classic_md5_targets = 0u;
    size_t multibit_hd_scrypt_targets = 0u;
    size_t multibit_classic_scrypt_targets = 0u;
    size_t bip38_non_ec_targets = 0u;
    size_t bip38_ec_targets = 0u;
    size_t dogechain_targets = 0u;
    size_t ethpresale_targets = 0u;
    size_t bisq_targets = 0u;
    size_t android_backup_targets = 0u;
    bool browservault_has_scrypt = false;
    uint64_t max_scrypt_scratch_stride = 0ull;
    for (BrowserVaultHostTarget& t : sorted_targets) {
        t.dev.ciphertext_offset = static_cast<uint64_t>(ciphertext_pool.size());
        ciphertext_pool.insert(ciphertext_pool.end(), t.ciphertext.begin(), t.ciphertext.end());
        if (t.dev.profile == BROWSERVAULT_PROFILE_METAMASK_AES_GCM) {
            ++metamask_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_PBKDF2) {
            ++phantom_pbkdf2_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_SCRYPT) {
            ++phantom_scrypt_targets;
            browservault_has_scrypt = true;
            const uint64_t block_size = 128ull * static_cast<uint64_t>(t.dev.scrypt_r);
            const uint64_t stride = wallet_scrypt_align_stride(
                block_size * static_cast<uint64_t>(t.dev.scrypt_n) +
                block_size * static_cast<uint64_t>(t.dev.scrypt_p) + 4ull + block_size);
            max_scrypt_scratch_stride = std::max<uint64_t>(max_scrypt_scratch_stride, stride);
        }
        else if (t.dev.profile ==
                 BROWSERVAULT_PROFILE_SUBSTRATE_SCRYPT_PKCS8) {
            ++substrate_scrypt_targets;
            browservault_has_scrypt = true;
            const uint64_t block_size =
                128ull * static_cast<uint64_t>(t.dev.scrypt_r);
            const uint64_t stride = wallet_scrypt_align_stride(
                block_size * static_cast<uint64_t>(t.dev.scrypt_n) +
                block_size * static_cast<uint64_t>(t.dev.scrypt_p) +
                4ull + block_size);
            max_scrypt_scratch_stride =
                std::max<uint64_t>(max_scrypt_scratch_stride, stride);
        }
        else if (t.dev.profile ==
                 BROWSERVAULT_PROFILE_SUBSTRATE_LEGACY_PKCS8) {
            ++substrate_legacy_targets;
        }
        else if (t.dev.profile ==
                 BROWSERVAULT_PROFILE_COPAY_SJCL_AES_CCM) {
            ++copay_sjcl_targets;
        }
        else if (t.dev.profile ==
                 BROWSERVAULT_PROFILE_TERRA_STATION_AES_CBC) {
            ++terra_station_targets;
        }
        else if (t.dev.profile ==
                 BROWSERVAULT_PROFILE_BITSHARES_0X_AES_CBC) {
            ++bitshares_0x_targets;
        }
        else if (t.dev.profile ==
                 BROWSERVAULT_PROFILE_YOROI_EMIP3) {
            ++yoroi_emip3_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_ATOMIC_CRYPTOJS_AES) {
            ++atomic_cryptojs_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_STELLAR_AES_GCM) {
            ++stellar_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_BLOCKCHAIN_V2_PBKDF2_AES_CBC) {
            ++blockchain_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_MD5_AES) {
            ++multibit_classic_md5_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_MULTIBIT_HD_SCRYPT_AES ||
            t.dev.profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_SCRYPT_AES ||
            t.dev.profile == BROWSERVAULT_PROFILE_BISQ_SCRYPT_AES) {
            if (t.dev.profile == BROWSERVAULT_PROFILE_MULTIBIT_HD_SCRYPT_AES) {
                ++multibit_hd_scrypt_targets;
            }
            else if (t.dev.profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_SCRYPT_AES) {
                ++multibit_classic_scrypt_targets;
            }
            else {
                ++bisq_targets;
            }
            browservault_has_scrypt = true;
            const uint64_t block_size = 128ull * static_cast<uint64_t>(t.dev.scrypt_r);
            const uint64_t stride = wallet_scrypt_align_stride(
                block_size * static_cast<uint64_t>(t.dev.scrypt_n) +
                block_size * static_cast<uint64_t>(t.dev.scrypt_p) + 4ull + block_size);
            max_scrypt_scratch_stride = std::max<uint64_t>(max_scrypt_scratch_stride, stride);
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_BIP38_NON_EC ||
            t.dev.profile == BROWSERVAULT_PROFILE_BIP38_EC) {
            if (t.dev.profile == BROWSERVAULT_PROFILE_BIP38_NON_EC) {
                ++bip38_non_ec_targets;
            }
            else {
                ++bip38_ec_targets;
            }
            browservault_has_scrypt = true;
            const uint64_t block_size = 128ull * static_cast<uint64_t>(t.dev.scrypt_r);
            const uint64_t stride = wallet_scrypt_align_stride(
                block_size * static_cast<uint64_t>(t.dev.scrypt_n) +
                block_size * static_cast<uint64_t>(t.dev.scrypt_p) + 4ull + block_size);
            max_scrypt_scratch_stride = std::max<uint64_t>(max_scrypt_scratch_stride, stride);
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_DOGECHAIN_PBKDF2_AES_CBC) {
            ++dogechain_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_ANDROID_BACKUP_PBKDF2_SHA1_AES_CBC) {
            ++android_backup_targets;
        }
        else if (t.dev.profile == BROWSERVAULT_PROFILE_ETHPRESALE_PBKDF2_AES_CBC) {
            ++ethpresale_targets;
        }
        targets.push_back(t.dev);
    }
    std::vector<BrowserVaultGroup> groups;
    std::vector<uint64_t> work_by_group;
    wallet_build_browservault_groups(targets, groups, work_by_group);
    std::vector<uint64_t> scratch_by_group;
    scratch_by_group.reserve(groups.size());
    for (const BrowserVaultGroup& group : groups) {
        if (group.profile == BROWSERVAULT_PROFILE_PHANTOM_SECRETBOX_SCRYPT ||
            group.profile == BROWSERVAULT_PROFILE_SUBSTRATE_SCRYPT_PKCS8 ||
            group.profile == BROWSERVAULT_PROFILE_MULTIBIT_HD_SCRYPT_AES ||
            group.profile == BROWSERVAULT_PROFILE_MULTIBIT_CLASSIC_SCRYPT_AES ||
            group.profile == BROWSERVAULT_PROFILE_BISQ_SCRYPT_AES ||
            group.profile == BROWSERVAULT_PROFILE_BIP38_NON_EC ||
            group.profile == BROWSERVAULT_PROFILE_BIP38_EC) {
            const uint64_t block_size = 128ull * static_cast<uint64_t>(group.scrypt_r);
            scratch_by_group.push_back(wallet_scrypt_align_stride(
                block_size * static_cast<uint64_t>(group.scrypt_n) +
                block_size * static_cast<uint64_t>(group.scrypt_p) + 4ull + block_size));
        }
        else {
            scratch_by_group.push_back(0ull);
        }
    }
    std::vector<WalletGenericTargetChunk> chunks;
    wallet_build_generic_chunks_from_work(work_by_group, chunks, walletdat_max_kdf_iter_work_per_launch, &scratch_by_group);
    std::vector<uint32_t> chunk_target_counts;
    wallet_count_chunk_targets_from_groups(groups, chunks, chunk_target_counts);
    size_t singleton_groups = 0u;
    uint32_t max_group_targets = 0u;
    for (const BrowserVaultGroup& group : groups) {
        if (group.target_count == 1u) ++singleton_groups;
        max_group_targets = std::max<uint32_t>(max_group_targets, group.target_count);
    }
    const bool simple_aes_gcm_singletons =
        !targets.empty() &&
        groups.size() == targets.size() &&
        targets.size() == (metamask_targets + stellar_targets);

    printf("[!] starting %s mode [!]\n", mode_name);
    printf("[!] loaded %s targets: %zu [!]\n", mode_lc, targets.size());
    counterWalletActiveTargets = static_cast<uint64_t>(targets.size());
    printf("[!] %s profiles: metamask=%zu phantom_pbkdf2=%zu phantom_scrypt=%zu substrate_v3=%zu substrate_v2=%zu copay_sjcl=%zu terra_station=%zu bitshares_0x=%zu yoroi_emip3=%zu atomic_cryptojs=%zu stellar=%zu blockchain=%zu multibit_md5=%zu multibit_hd=%zu multibit_scrypt=%zu bisq=%zu bip38_non_ec=%zu bip38_ec=%zu dogechain=%zu android_backup=%zu ethpresale=%zu [!]\n",
        mode_lc, metamask_targets, phantom_pbkdf2_targets, phantom_scrypt_targets, substrate_scrypt_targets, substrate_legacy_targets, copay_sjcl_targets, terra_station_targets, bitshares_0x_targets, yoroi_emip3_targets, atomic_cryptojs_targets, stellar_targets, blockchain_targets,
        multibit_classic_md5_targets, multibit_hd_scrypt_targets, multibit_classic_scrypt_targets, bisq_targets, bip38_non_ec_targets, bip38_ec_targets, dogechain_targets, android_backup_targets, ethpresale_targets);
    printf("[!] %s KDF groups: %zu [saved %.2fx KDF work, singletons=%zu, max_group=%u] [!]\n",
        mode_lc,
        groups.size(),
        groups.empty() ? 1.0 : static_cast<double>(targets.size()) / static_cast<double>(groups.size()),
        singleton_groups,
        max_group_targets);
    const uint64_t fixed_ciphertext_layout_bytes =
        static_cast<uint64_t>(targets.size()) * static_cast<uint64_t>(BROWSERVAULT_MAX_BLOB_LEN);
    printf("[!] %s ciphertext pool: %.2f MiB [saved %.2f MiB vs fixed target layout] [!]\n",
        mode_lc,
        static_cast<double>(ciphertext_pool.size()) / 1048576.0,
        static_cast<double>(fixed_ciphertext_layout_bytes - static_cast<uint64_t>(ciphertext_pool.size())) / 1048576.0);
    if (skipped_files != 0u) printf("[!] skipped %s files: %zu [!]\n", mode_lc, skipped_files);
    printf("[!] %s launch chunks: %zu chunk(s), <=%llu KDF-work units per launch window [!]\n",
        mode_lc, chunks.size(), static_cast<unsigned long long>(walletdat_max_kdf_iter_work_per_launch));
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after %s target load [!]\n", mode_lc);
        return metalSuccess;
    }

    uint64_t wallet_scratch_hard_cap = std::numeric_limits<uint64_t>::max();
    if ((browservault_has_scrypt &&
         (bip38_mode || substrate_mode || wallet_memory_explicit)) ||
        copay_mode || terra_mode || bitshares_mode || yoroi_mode) {
        std::vector<modeinfra::MemoryDeviceInfo> memory_devices;
        memory_devices.reserve(g_gpu_contexts.size());
        for (const GpuRuntimeContext& context : g_gpu_contexts) {
            metalDeviceProp properties{};
            const metalError_t properties_status =
                metalGetDeviceProperties(&properties, context.device_id);
            if (properties_status != metalSuccess) {
                fprintf(stderr,
                    "[!] Error: cannot query Metal memory limits for GPU %d: %s [!]\n",
                    context.device_id,
                    metalGetErrorString(properties_status));
                return properties_status;
            }
            memory_devices.push_back(modeinfra::MemoryDeviceInfo{
                properties.recommendedMaxWorkingSetSize,
                properties.currentAllocatedSize,
                properties.maxBufferLength,
                properties.hasUnifiedMemory != 0
            });
        }
        const uint64_t mandatory_per_device =
            static_cast<uint64_t>(targets.size()) * sizeof(BrowserVaultDeviceTarget) +
            static_cast<uint64_t>(groups.size()) * sizeof(BrowserVaultGroup) +
            static_cast<uint64_t>(ciphertext_pool.size()) +
            static_cast<uint64_t>(target_files.size());
        const uint64_t host_resident_bytes =
            static_cast<uint64_t>(sorted_targets.size()) * sizeof(BrowserVaultHostTarget) +
            static_cast<uint64_t>(targets.size()) * sizeof(BrowserVaultDeviceTarget) +
            static_cast<uint64_t>(groups.size()) * sizeof(BrowserVaultGroup) +
            static_cast<uint64_t>(ciphertext_pool.size()) +
            static_cast<uint64_t>(target_files.size());
        modeinfra::MemoryBudget memory_budget{};
        std::string memory_error;
        if (!modeinfra::resolve_memory_budget(
                wallet_memory_explicit
                    ? wallet_memory_spec
                    : modeinfra::MemorySpec{ modeinfra::MemoryKind::Auto, 0ull },
                memory_devices,
                mandatory_per_device,
                host_resident_bytes,
                memory_budget,
                memory_error)) {
            fprintf(stderr, "[!] Error: -wallet-mem: %s [!]\n", memory_error.c_str());
            return metalErrorMemoryAllocation;
        }
        if (browservault_has_scrypt &&
            memory_budget.per_device_budget <= mandatory_per_device) {
            fprintf(stderr,
                "[!] Error: -wallet-mem leaves no room for one %s scrypt job [!]\n",
                mode_lc);
            return metalErrorMemoryAllocation;
        }
        wallet_scratch_hard_cap =
            memory_budget.per_device_budget - mandatory_per_device;
        printf("[!] %s wallet memory budget: %.2f GiB total, %.2f GiB/device, unified=%s [!]\n",
            mode_lc,
            static_cast<double>(memory_budget.total_budget) / 1073741824.0,
            static_cast<double>(memory_budget.per_device_budget) / 1073741824.0,
            memory_budget.unified ? "yes" : "no");
    }

    std::vector<uint8_t> solved_files(target_files.size(), 0u);
    { std::lock_guard<std::mutex> lock(browservault_solved_mutex); browservault_solved_version = 0ull; }
    bool all_solved = false;
    std::vector<BrowserVaultDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    bool wallet_progress_active = false;
    uint64_t wallet_working_set_bytes = 0ull;
    if (bip38_mode || substrate_mode || copay_mode || terra_mode ||
        bitshares_mode || yoroi_mode) {
        modeinfra::ModeProgress& progress = modeinfra::global_mode_progress();
        progress.begin(mode_name, modeinfra::ProgressUnit::Kdf,
                       modeinfra::ProgressPhase::Build);
        progress.set_targets(static_cast<uint64_t>(target_files.size()),
                             static_cast<uint64_t>(target_files.size()),
                             0ull);
        wallet_progress_active = true;
    }
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
        states[gi].target_count = static_cast<uint32_t>(targets.size());
        states[gi].group_count = static_cast<uint32_t>(groups.size());
        states[gi].simple_aes_gcm_singletons = simple_aes_gcm_singletons;
        states[gi].solved_count = static_cast<uint32_t>(target_files.size());
        states[gi].target_chunks = chunks;
        states[gi].chunk_target_counts = chunk_target_counts;
        states[gi].group_target_counts.reserve(groups.size());
        for (const BrowserVaultGroup& group : groups) {
            states[gi].group_target_counts.push_back(group.target_count);
        }
        for (const BrowserVaultDeviceTarget& t : targets) states[gi].target_file_indices.push_back(t.target_index);
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), targets.size() * sizeof(BrowserVaultDeviceTarget));
        if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, targets.data(), targets.size() * sizeof(BrowserVaultDeviceTarget), metalMemcpyHostToDevice);
        if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].groups), groups.empty() ? 1u : groups.size() * sizeof(BrowserVaultGroup));
        if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].groups, groups.empty() ? nullptr : groups.data(),
            groups.empty() ? 1u : groups.size() * sizeof(BrowserVaultGroup), metalMemcpyHostToDevice);
        if (st != metalSuccess) goto Done;
        states[gi].ciphertext_pool_size = static_cast<uint64_t>(ciphertext_pool.size());
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].ciphertext_pool), ciphertext_pool.empty() ? 1u : ciphertext_pool.size());
        if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].ciphertext_pool, ciphertext_pool.empty() ? nullptr : ciphertext_pool.data(),
            ciphertext_pool.empty() ? 1u : ciphertext_pool.size(), metalMemcpyHostToDevice);
        if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), target_files.empty() ? 1u : target_files.size());
        if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, target_files.empty() ? 1u : target_files.size());
        if (st != metalSuccess) goto Done;
        if (browservault_has_scrypt) {
            size_t free_mem = 0, total_mem = 0;
            metalMemGetInfo(&free_mem, &total_mem);
            const uint64_t reserve_target = wallet_scrypt_memory_reserve_bytes();
            const uint64_t reserve = std::min<uint64_t>(static_cast<uint64_t>(free_mem / 2u), reserve_target);
            const uint64_t available_cap =
                static_cast<uint64_t>(free_mem > reserve ? free_mem - reserve : free_mem / 2u);
            const uint64_t hard_cap =
                std::min<uint64_t>(available_cap, wallet_scratch_hard_cap);
            uint64_t scratch_bytes = wallet_scrypt_scratch_budget_bytes(hard_cap, max_scrypt_scratch_stride);
            if (bip38_mode && !wallet_scrypt_scratch_budget_explicit) {
                const bool automatic_memory =
                    !wallet_memory_explicit ||
                    wallet_memory_spec.kind == modeinfra::MemoryKind::Auto;
                const uint64_t preferred = automatic_memory
                    ? WALLET_BIP38_AUTO_SCRYPT_SCRATCH_BUDGET
                    : hard_cap;
                scratch_bytes = std::min<uint64_t>(
                    hard_cap,
                    std::max<uint64_t>(max_scrypt_scratch_stride, preferred));
            }
            if (substrate_mode &&
                !wallet_scrypt_scratch_budget_explicit &&
                wallet_memory_explicit &&
                wallet_memory_spec.kind != modeinfra::MemoryKind::Auto) {
                scratch_bytes = hard_cap;
            }
            const bool bisq_auto_large_stride_cap =
                bisq_mode && !wallet_scrypt_scratch_budget_explicit &&
                max_scrypt_scratch_stride >= WALLET_BISQ_SCRYPT_LARGE_STRIDE_THRESHOLD;
            if (bisq_auto_large_stride_cap) {
                scratch_bytes = std::min<uint64_t>(
                    scratch_bytes, WALLET_BISQ_SCRYPT_LARGE_STRIDE_BUDGET);
            }
            uint64_t concurrency = max_scrypt_scratch_stride ? scratch_bytes / max_scrypt_scratch_stride : 0ull;
            const uint64_t launch_lanes = static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
            concurrency = std::min<uint64_t>(concurrency, launch_lanes);
            uint64_t requested_concurrency_cap = use_n_count && n_number > 0
                ? std::min<uint64_t>(n_number, launch_lanes)
                : launch_lanes;
            if (bisq_auto_large_stride_cap) {
                requested_concurrency_cap = std::min<uint64_t>(
                    requested_concurrency_cap, wallet_scrypt_default_concurrency_cap());
            }
            concurrency = std::min<uint64_t>(concurrency, requested_concurrency_cap);
            if (max_scrypt_scratch_stride != 0ull && requested_concurrency_cap != 0ull) {
                const uint64_t budget_concurrency = scratch_bytes / max_scrypt_scratch_stride;
                if (budget_concurrency > requested_concurrency_cap) {
                    scratch_bytes = requested_concurrency_cap * max_scrypt_scratch_stride;
                }
            }
            if (scratch_bytes == 0ull || concurrency == 0ull) {
                fprintf(stderr, "[!] Error: not enough GPU memory for %s scrypt scratch on GPU %d; need at least %llu bytes [!]\n",
                    mode_lc,
                    g_gpu_contexts[gi].device_id, static_cast<unsigned long long>(max_scrypt_scratch_stride));
                st = metalErrorMemoryAllocation;
                goto Done;
            }
            const uint64_t requested_scratch_bytes = scratch_bytes;
            while (scratch_bytes >= max_scrypt_scratch_stride) {
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].scrypt_scratch),
                    static_cast<size_t>(scratch_bytes));
                if (st == metalSuccess) {
                    break;
                }
                if (st != metalErrorMemoryAllocation) goto Done;
                states[gi].scrypt_scratch = nullptr;
                scratch_bytes = (scratch_bytes * 15ull) / 16ull;
            }
            if (st != metalSuccess || scratch_bytes < max_scrypt_scratch_stride) goto Done;
            concurrency = std::min<uint64_t>(requested_concurrency_cap, scratch_bytes / max_scrypt_scratch_stride);
            states[gi].scrypt_scratch_stride = max_scrypt_scratch_stride;
            states[gi].scrypt_scratch_bytes = scratch_bytes;
            states[gi].scrypt_concurrency = concurrency;
            if (scratch_bytes != requested_scratch_bytes) {
                printf("[!] GPU %d %s scrypt scratch allocation backoff: %.2f -> %.2f MiB [!]\n",
                    g_gpu_contexts[gi].device_id,
                    mode_lc,
                    static_cast<double>(requested_scratch_bytes) / 1048576.0,
                    static_cast<double>(scratch_bytes) / 1048576.0);
            }
            printf("[!] GPU %d %s scrypt scratch: %.2f MiB, max active jobs/launch: %llu [!]\n",
                g_gpu_contexts[gi].device_id,
                mode_lc,
                static_cast<double>(scratch_bytes) / 1048576.0,
                static_cast<unsigned long long>(concurrency));
        }
        if (bip38_mode || substrate_mode || copay_mode || terra_mode ||
            bitshares_mode || yoroi_mode) {
            const uint64_t fixed_bytes =
                static_cast<uint64_t>(targets.size()) * sizeof(BrowserVaultDeviceTarget) +
                static_cast<uint64_t>(groups.size()) * sizeof(BrowserVaultGroup) +
                std::max<uint64_t>(1ull, static_cast<uint64_t>(ciphertext_pool.size())) +
                std::max<uint64_t>(1ull, static_cast<uint64_t>(target_files.size()));
            const uint64_t device_bytes = fixed_bytes + states[gi].scrypt_scratch_bytes;
            if (wallet_working_set_bytes >
                std::numeric_limits<uint64_t>::max() - device_bytes) {
                wallet_working_set_bytes = std::numeric_limits<uint64_t>::max();
            }
            else {
                wallet_working_set_bytes += device_bytes;
            }
        }
    }

    {
        if (bip38_mode || substrate_mode || copay_mode || terra_mode ||
            bitshares_mode || yoroi_mode) {
            modeinfra::ModeProgress& progress = modeinfra::global_mode_progress();
            progress.set_allocated_working_set(wallet_working_set_bytes);
            progress.set_phase(modeinfra::ProgressPhase::Search);
        }
        const uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0 ? n_number : static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
        if (!wallet_masks.empty()) {
            for (const auto& mask : wallet_masks) {
                WalletMaskSpec spec{}; std::string err;
                if (!wallet_prepare_mask_spec(mask, spec, err)) { fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str()); st = metalErrorInvalidValue; goto Done; }
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    if (states[gi].mask_spec == nullptr) { st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec)); if (st != metalSuccess) goto Done; }
                    st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                }
                uint64_t processed = 0;
                while (processed < spec.total_candidates && !all_solved) {
                    std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                    std::vector<std::thread> workers;
                    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                        const uint64_t start = processed + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                        if (start >= spec.total_candidates) break;
                        const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, spec.total_candidates - start);
                        workers.emplace_back([&, gi, start, count]() {
                            {
                                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                                if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                            }
                            gst[gi] = wallet_launch_browservault_generated(states[gi], WALLET_CANDIDATE_MASK, start, count, target_files, solved_files, all_solved);
                            {
                                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                                if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context();
                            }
                            });
                    }
                    for (auto& th : workers) th.join();
                    for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
                    processed += wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                }
            }
        }
        else if (seqMode) {
            WalletRangeHostState range_state{}; std::string err;
            if (!wallet_prepare_range_state(range_state, err)) { fprintf(stderr, "[!] Error: invalid %s raw range: %s [!]\n", mode_lc, err.c_str()); st = metalErrorInvalidValue; goto Done; }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec)); if (st != metalSuccess) goto Done;
            }
            while (range_state.valid && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    WalletRangeSpec spec{}; uint64_t count = 0;
                    if (!wallet_range_next_window(range_state, wallet_generated_launch_chunk, spec, count)) break;
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                    workers.emplace_back([&, gi, count]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_browservault_generated(states[gi], WALLET_CANDIDATE_RANGE, 0ull, count, target_files, solved_files, all_solved);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                        });
                }
                if (workers.empty()) break;
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
        else {
            WalletPassReader reader;
            if (!reader.open(mnemonicFiles, IS_HEX, bip38_mode)) { fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str()); st = metalErrorInvalidValue; goto Done; }
            const uint32_t batch_sz = wallet_effective_dict_batch_u32(mode_lc, wallet_generated_launch_chunk);
            std::vector<WalletPassBuf> batches;
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            workers.reserve(g_gpu_contexts.size());
            while (!all_solved) {
                const bool any = wallet_read_split_pass_batch(reader, batch_sz, g_gpu_contexts.size(), batches);
                if (reader.failed) {
                    fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str());
                    st = metalErrorInvalidValue;
                    goto Done;
                }
                if (!any) break;
                std::fill(gst.begin(), gst.end(), metalSuccess);
                workers.clear();
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) if (batches[gi].count != 0) {
                    workers.emplace_back([&, gi]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_browservault_dict_batch(batches[gi], states[gi], target_files, solved_files, all_solved);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
    }

Done:
    if (wallet_progress_active) {
        wallet_update_browser_mode_progress(
            solved_files, 0ull, 0ull, 0ull);
        modeinfra::global_mode_progress().end();
    }
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_browservault_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalExodusSeco()
{
    std::vector<std::string> files = wallet_artifact_files;
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, { ".seco" }, files);
    }
    if (files.empty()) {
        fprintf(stderr, "[!] Error: -exodusseco requires FILE or -f DIR [!]\n");
        return metalErrorInvalidValue;
    }
    printf("[!] exodusseco files discovered: %zu [!]\n", files.size());

    std::vector<ExodusSecoHostTarget> host_targets;
    std::unordered_set<std::string> seen;
    size_t skipped = 0u, warnings = 0u;
    std::unordered_map<std::string, size_t> skip_reasons;
    size_t duplicate_targets = 0u;
    for (const auto& path : files) {
        ExodusSecoHostTarget target;
        std::string err;
        if (!mac_is_regular_file(path) || !wallet_parse_exodusseco_file(path, target, err)) {
            ++skipped;
            wallet_add_skip_reason(skip_reasons, err);
            if (warnings < 32u) {
                fprintf(stderr, "[!] Warning: exodusseco '%s': skipped, %s [!]\n", path.c_str(), err.c_str());
                ++warnings;
            }
            continue;
        }
        const std::string dedup_key(reinterpret_cast<const char*>(target.dev.vault_hash), 32u);
        if (!seen.insert(dedup_key).second) {
            ++duplicate_targets;
            continue;
        }
        target.dev.target_index = static_cast<uint32_t>(host_targets.size());
        host_targets.push_back(target);
    }
    if (host_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable Exodus SECO targets loaded (%zu skipped) [!]\n", skipped);
        return metalErrorInvalidValue;
    }

    std::vector<std::string> target_files;
    std::vector<ExodusSecoTarget> targets;
    target_files.reserve(host_targets.size());
    targets.reserve(host_targets.size());
    uint64_t max_scrypt_scratch_stride = 0ull;
    for (size_t i = 0; i < host_targets.size(); ++i) {
        host_targets[i].dev.target_index = static_cast<uint32_t>(i);
        target_files.push_back(host_targets[i].file);
        targets.push_back(host_targets[i].dev);
        const uint64_t block_size = 128ull * static_cast<uint64_t>(host_targets[i].dev.scrypt_r);
        const uint64_t stride = wallet_scrypt_align_stride(
            block_size * static_cast<uint64_t>(host_targets[i].dev.scrypt_n) +
            block_size * static_cast<uint64_t>(host_targets[i].dev.scrypt_p) + 4ull + block_size);
        max_scrypt_scratch_stride = std::max<uint64_t>(max_scrypt_scratch_stride, stride);
    }
    std::sort(targets.begin(), targets.end(), [](const ExodusSecoTarget& a, const ExodusSecoTarget& b) {
        if (a.scrypt_n != b.scrypt_n) return a.scrypt_n < b.scrypt_n;
        return a.target_index < b.target_index;
        });
    std::vector<uint64_t> work_by_target;
    std::vector<uint64_t> scratch_by_target;
    work_by_target.reserve(targets.size());
    scratch_by_target.reserve(targets.size());
    for (const auto& t : targets) {
        work_by_target.push_back(std::max<uint64_t>(1ull, static_cast<uint64_t>(t.scrypt_n)));
        const uint64_t block_size = 128ull * static_cast<uint64_t>(t.scrypt_r);
        scratch_by_target.push_back(wallet_scrypt_align_stride(
            block_size * static_cast<uint64_t>(t.scrypt_n) +
            block_size * static_cast<uint64_t>(t.scrypt_p) + 4ull + block_size));
    }
    std::vector<WalletGenericTargetChunk> chunks;
    wallet_build_generic_chunks_from_work(work_by_target, chunks, walletdat_max_kdf_iter_work_per_launch, &scratch_by_target);
    counterWalletActiveTargets = static_cast<uint64_t>(targets.size());

    printf("[!] starting EXODUSSECO mode [!]\n");
    printf("[!] loaded Exodus SECO targets: %zu [!]\n", targets.size());
    if (duplicate_targets != 0u) {
        printf("[!] exodusseco compact targets: %zu unique [saved %zu duplicate KDF check(s)] [!]\n",
            targets.size(), duplicate_targets);
    }
    if (skipped != 0u) printf("[!] skipped Exodus SECO files: %zu [!]\n", skipped);
    wallet_print_skip_reason_summary("exodusseco", skip_reasons, skipped);
    printf("[!] exodusseco launch chunks: %zu chunk(s), <=%llu scrypt-N work per launch window [!]\n",
        chunks.size(), static_cast<unsigned long long>(walletdat_max_kdf_iter_work_per_launch));
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after exodusseco target load [!]\n");
        return metalSuccess;
    }

    std::vector<uint8_t> solved_files(target_files.size(), 0u);
    { std::lock_guard<std::mutex> lock(exodusseco_solved_mutex); exodusseco_solved_version = 0ull; }
    bool all_solved = false;
    std::vector<ExodusSecoDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    uint64_t min_concurrency = std::numeric_limits<uint64_t>::max();
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
        states[gi].target_count = static_cast<uint32_t>(targets.size());
        states[gi].solved_count = static_cast<uint32_t>(target_files.size());
        states[gi].target_chunks = chunks;
        for (const ExodusSecoTarget& t : targets) states[gi].target_file_indices.push_back(t.target_index);
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), targets.size() * sizeof(ExodusSecoTarget)); if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, targets.data(), targets.size() * sizeof(ExodusSecoTarget), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;

        size_t free_mem = 0, total_mem = 0;
        st = metalMemGetInfo(&free_mem, &total_mem); if (st != metalSuccess) goto Done;
        const uint64_t reserve_target = wallet_scrypt_memory_reserve_bytes();
        const uint64_t reserve = std::min<uint64_t>(static_cast<uint64_t>(free_mem / 2u), reserve_target);
        const uint64_t hard_cap = static_cast<uint64_t>(free_mem > reserve ? free_mem - reserve : free_mem / 2u);
        uint64_t scratch_bytes = wallet_scrypt_scratch_budget_bytes(hard_cap, max_scrypt_scratch_stride);
        uint64_t concurrency = max_scrypt_scratch_stride ? scratch_bytes / max_scrypt_scratch_stride : 0ull;
        const uint64_t launch_lanes = static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
        concurrency = std::min<uint64_t>(concurrency, launch_lanes);
        const uint64_t requested_concurrency_cap = use_n_count && n_number > 0
            ? n_number
            : wallet_scrypt_default_concurrency_cap();
        concurrency = std::min<uint64_t>(concurrency, requested_concurrency_cap);
        if (scratch_bytes == 0ull || concurrency == 0ull) {
            fprintf(stderr, "[!] Error: not enough GPU memory for Exodus SECO scrypt scratch on GPU %d; need at least %llu bytes [!]\n",
                g_gpu_contexts[gi].device_id, static_cast<unsigned long long>(max_scrypt_scratch_stride));
            st = metalErrorMemoryAllocation;
            goto Done;
        }
        const uint64_t requested_scratch_bytes = scratch_bytes;
        while (scratch_bytes >= max_scrypt_scratch_stride) {
            st = metalMalloc(reinterpret_cast<void**>(&states[gi].scrypt_scratch),
                static_cast<size_t>(scratch_bytes));
            if (st == metalSuccess) {
                break;
            }
            if (st != metalErrorMemoryAllocation) goto Done;
            states[gi].scrypt_scratch = nullptr;
            scratch_bytes = (scratch_bytes * 15ull) / 16ull;
        }
        if (st != metalSuccess || scratch_bytes < max_scrypt_scratch_stride) goto Done;
        concurrency = std::min<uint64_t>(requested_concurrency_cap, scratch_bytes / max_scrypt_scratch_stride);
        states[gi].scrypt_scratch_stride = max_scrypt_scratch_stride;
        states[gi].scrypt_scratch_bytes = scratch_bytes;
        states[gi].scrypt_concurrency = concurrency;
        if (scratch_bytes != requested_scratch_bytes) {
            printf("[!] GPU %d exodusseco scrypt scratch allocation backoff: %.2f -> %.2f MiB [!]\n",
                g_gpu_contexts[gi].device_id,
                static_cast<double>(requested_scratch_bytes) / 1048576.0,
                static_cast<double>(scratch_bytes) / 1048576.0);
        }
        min_concurrency = std::min<uint64_t>(min_concurrency, std::max<uint64_t>(1ull, states[gi].scrypt_concurrency));
        printf("[!] GPU %d exodusseco scrypt scratch: %.2f MiB, max active jobs/launch: %llu [!]\n",
            g_gpu_contexts[gi].device_id,
            static_cast<double>(scratch_bytes) / 1048576.0,
            static_cast<unsigned long long>(concurrency));
        printf("[!] GPU %d exodusseco VRAM safety reserve: %.2f MiB [!]\n",
            g_gpu_contexts[gi].device_id,
            static_cast<double>(reserve) / 1048576.0);
    }

    {
        const uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0 ? n_number : std::max<uint64_t>(1ull, min_concurrency);
        if (!wallet_masks.empty()) {
            for (const auto& mask : wallet_masks) {
                WalletMaskSpec spec{}; std::string err;
                if (!wallet_prepare_mask_spec(mask, spec, err)) { fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str()); st = metalErrorInvalidValue; goto Done; }
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    if (states[gi].mask_spec == nullptr) { st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec)); if (st != metalSuccess) goto Done; }
                    st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                }
                uint64_t processed = 0;
                while (processed < spec.total_candidates && !all_solved) {
                    std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                    std::vector<std::thread> workers;
                    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                        const uint64_t start = processed + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                        if (start >= spec.total_candidates) break;
                        const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, spec.total_candidates - start);
                        workers.emplace_back([&, gi, start, count]() {
                            { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                            gst[gi] = wallet_launch_exodusseco_generated(states[gi], WALLET_CANDIDATE_MASK, start, count, target_files, solved_files, all_solved);
                            { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                            });
                    }
                    for (auto& th : workers) th.join();
                    for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
                    processed += wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                }
            }
        }
        else if (seqMode) {
            WalletRangeHostState range_state{}; std::string err;
            if (!wallet_prepare_range_state(range_state, err)) { fprintf(stderr, "[!] Error: invalid exodusseco raw range: %s [!]\n", err.c_str()); st = metalErrorInvalidValue; goto Done; }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec)); if (st != metalSuccess) goto Done;
            }
            while (range_state.valid && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    WalletRangeSpec spec{}; uint64_t count = 0;
                    if (!wallet_range_next_window(range_state, wallet_generated_launch_chunk, spec, count)) break;
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                    workers.emplace_back([&, gi, count]() {
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                        gst[gi] = wallet_launch_exodusseco_generated(states[gi], WALLET_CANDIDATE_RANGE, 0ull, count, target_files, solved_files, all_solved);
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                        });
                }
                if (workers.empty()) break;
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
        else {
            WalletPassReader reader;
            if (!reader.open(mnemonicFiles, IS_HEX)) { fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str()); st = metalErrorInvalidValue; goto Done; }
            const uint32_t batch_sz = static_cast<uint32_t>(std::min<uint64_t>(static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()), wallet_generated_launch_chunk));
            std::vector<WalletPassBuf> batches;
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            workers.reserve(g_gpu_contexts.size());
            while (!all_solved) {
                const bool any = wallet_read_split_pass_batch(reader, batch_sz, g_gpu_contexts.size(), batches);
                if (reader.failed) { st = metalErrorInvalidValue; goto Done; }
                if (!any) break;
                std::fill(gst.begin(), gst.end(), metalSuccess);
                workers.clear();
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) if (batches[gi].count != 0) {
                    workers.emplace_back([&, gi]() {
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                        gst[gi] = wallet_launch_exodusseco_dict_batch(batches[gi], states[gi], target_files, solved_files, all_solved);
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
    }

Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_exodusseco_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalBitcoinJWallet()
{
    const bool android_mode = ANDROIDWALLET_MODE;
    const char* mode_lc = android_mode ? "androidwallet" : "bitcoinjwallet";
    const char* mode_name = android_mode ? "ANDROIDWALLET" : "BITCOINJWALLET";
    std::vector<std::string> files = wallet_artifact_files;
    std::vector<std::string> dir_files;
    const std::vector<std::string> scan_exts = android_mode
        ? std::vector<std::string>{ ".wallet", ".dat", ".backup", ".key", "" }
        : std::vector<std::string>{ ".wallet", ".dat", "" };
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, scan_exts, dir_files);
    }
    const size_t raw_dir_files = dir_files.size();
    size_t prefiltered_dir_files = 0u;
    for (const std::string& path : dir_files) {
        if (wallet_bitcoinj_should_try_dir_file(path)) {
            files.push_back(path);
        }
        else {
            ++prefiltered_dir_files;
        }
    }
    if (files.empty()) {
        fprintf(stderr, "[!] Error: -%s requires FILE or -f DIR [!]\n", mode_lc);
        return metalErrorInvalidValue;
    }
    printf("[!] %s files discovered: %zu [!]\n", mode_lc, files.size());
    if (prefiltered_dir_files != 0u) {
        printf("[!] %s prefilter skipped obvious non-protobuf files: %zu/%zu [!]\n",
            mode_lc,
            prefiltered_dir_files, raw_dir_files);
    }

    std::vector<BitcoinJWalletHostTarget> host_targets;
    std::vector<std::string> target_files;
    std::unordered_set<std::string> seen;
    size_t skipped = 0u, warnings = 0u, warnings_suppressed = 0u;
    size_t duplicate_targets = 0u;
    std::vector<BitcoinJWalletLoadFileResult> load_results;
    wallet_parallel_load_files(files, mode_lc, load_results, wallet_load_one_bitcoinjwallet_file);
    for (BitcoinJWalletLoadFileResult& result : load_results) {
        if (!result.loaded) {
            ++skipped;
            if (warnings < 32u) {
                fprintf(stderr, "[!] Warning: %s '%s': skipped, %s [!]\n",
                    mode_lc,
                    result.path.c_str(), result.err.empty() ? "unsupported or invalid" : result.err.c_str());
                ++warnings;
            }
            else {
                ++warnings_suppressed;
            }
            continue;
        }
        for (BitcoinJWalletHostTarget& target : result.targets) {
            const std::string key = wallet_bitcoinj_target_key(target.dev);
            if (!seen.insert(key).second) {
                ++duplicate_targets;
                continue;
            }
            const uint32_t file_index = static_cast<uint32_t>(target_files.size());
            target.dev.target_index = file_index;
            target.file = result.path;
            target_files.push_back(result.path);
            host_targets.push_back(std::move(target));
        }
    }
    if (host_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable %s encrypted wallet targets loaded (%zu skipped) [!]\n", mode_lc, skipped);
        return metalErrorInvalidValue;
    }

    std::vector<BitcoinJWalletTarget> targets;
    targets.reserve(host_targets.size());
    uint64_t max_scrypt_scratch_stride = 0ull;
    for (const auto& host : host_targets) {
        targets.push_back(host.dev);
        const uint64_t block_size = 128ull * static_cast<uint64_t>(host.dev.scrypt_r);
        const uint64_t stride = wallet_scrypt_align_stride(
            block_size * static_cast<uint64_t>(host.dev.scrypt_n) +
            block_size * static_cast<uint64_t>(host.dev.scrypt_p) + 4ull + block_size);
        max_scrypt_scratch_stride = std::max<uint64_t>(max_scrypt_scratch_stride, stride);
    }
    std::sort(targets.begin(), targets.end(), [](const BitcoinJWalletTarget& a, const BitcoinJWalletTarget& b) {
        if (a.scrypt_n != b.scrypt_n) return a.scrypt_n < b.scrypt_n;
        if (a.scrypt_r != b.scrypt_r) return a.scrypt_r < b.scrypt_r;
        if (a.scrypt_p != b.scrypt_p) return a.scrypt_p < b.scrypt_p;
        return a.target_index < b.target_index;
        });
    std::vector<uint64_t> work_by_target;
    std::vector<uint64_t> scratch_by_target;
    work_by_target.reserve(targets.size());
    scratch_by_target.reserve(targets.size());
    for (const auto& t : targets) {
        work_by_target.push_back(std::max<uint64_t>(1ull, static_cast<uint64_t>(t.scrypt_n)));
        const uint64_t block_size = 128ull * static_cast<uint64_t>(t.scrypt_r);
        scratch_by_target.push_back(wallet_scrypt_align_stride(
            block_size * static_cast<uint64_t>(t.scrypt_n) +
            block_size * static_cast<uint64_t>(t.scrypt_p) + 4ull + block_size));
    }
    std::vector<WalletGenericTargetChunk> chunks;
    wallet_build_generic_chunks_from_work(work_by_target, chunks, walletdat_max_kdf_iter_work_per_launch, &scratch_by_target);
    counterWalletActiveTargets = static_cast<uint64_t>(targets.size());

    printf("[!] starting %s mode [!]\n", mode_name);
    printf("[!] loaded %s encrypted key targets: %zu [!]\n", mode_lc, targets.size());
    if (duplicate_targets != 0u) {
        printf("[!] %s compact targets: %zu unique [saved %zu duplicate KDF check(s)] [!]\n",
            mode_lc,
            targets.size(), duplicate_targets);
    }
    if (skipped != 0u) printf("[!] skipped %s files: %zu [!]\n", mode_lc, skipped);
    if (warnings_suppressed != 0u) {
        printf("[!] %s load warnings suppressed: %zu more skipped/invalid file warning(s) [!]\n",
            mode_lc,
            warnings_suppressed);
    }
    wallet_print_skip_reason_summary_from_results(mode_lc, load_results);
    printf("[!] %s launch chunks: %zu chunk(s), <=%llu scrypt-N work per launch window [!]\n",
        mode_lc,
        chunks.size(), static_cast<unsigned long long>(walletdat_max_kdf_iter_work_per_launch));
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after %s target load [!]\n", mode_lc);
        return metalSuccess;
    }

    std::vector<uint8_t> solved_files(target_files.size(), 0u);
    { std::lock_guard<std::mutex> lock(bitcoinjwallet_solved_mutex); bitcoinjwallet_solved_version = 0ull; }
    bool all_solved = false;
    std::vector<BitcoinJWalletDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    uint64_t min_concurrency = std::numeric_limits<uint64_t>::max();
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
        states[gi].result_mode = android_mode ? WALLET_MODE_ANDROIDWALLET : WALLET_MODE_BITCOINJ;
        states[gi].target_count = static_cast<uint32_t>(targets.size());
        states[gi].solved_count = static_cast<uint32_t>(target_files.size());
        states[gi].target_chunks = chunks;
        for (const BitcoinJWalletTarget& t : targets) states[gi].target_file_indices.push_back(t.target_index);
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), targets.size() * sizeof(BitcoinJWalletTarget)); if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, targets.data(), targets.size() * sizeof(BitcoinJWalletTarget), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;

        size_t free_mem = 0, total_mem = 0;
        st = metalMemGetInfo(&free_mem, &total_mem); if (st != metalSuccess) goto Done;
        const uint64_t reserve_target = wallet_scrypt_memory_reserve_bytes();
        const uint64_t reserve = std::min<uint64_t>(static_cast<uint64_t>(free_mem / 2u), reserve_target);
        const uint64_t hard_cap = static_cast<uint64_t>(free_mem > reserve ? free_mem - reserve : free_mem / 2u);
        uint64_t scratch_bytes = wallet_scrypt_scratch_budget_bytes(hard_cap, max_scrypt_scratch_stride);
        uint64_t concurrency = max_scrypt_scratch_stride ? scratch_bytes / max_scrypt_scratch_stride : 0ull;
        const uint64_t launch_lanes = static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
        concurrency = std::min<uint64_t>(concurrency, launch_lanes);
        const uint64_t default_cap = wallet_scrypt_default_concurrency_cap();
        const uint64_t requested_concurrency_cap = use_n_count && n_number > 0 ? n_number : default_cap;
        concurrency = std::min<uint64_t>(concurrency, requested_concurrency_cap);
        if (scratch_bytes == 0ull || concurrency == 0ull) {
            fprintf(stderr, "[!] Error: not enough GPU memory for %s scrypt scratch on GPU %d; need at least %llu bytes [!]\n",
                mode_lc, g_gpu_contexts[gi].device_id, static_cast<unsigned long long>(max_scrypt_scratch_stride));
            st = metalErrorMemoryAllocation;
            goto Done;
        }
        const uint64_t requested_scratch_bytes = scratch_bytes;
        while (scratch_bytes >= max_scrypt_scratch_stride) {
            st = metalMalloc(reinterpret_cast<void**>(&states[gi].scrypt_scratch),
                static_cast<size_t>(scratch_bytes));
            if (st == metalSuccess) break;
            if (st != metalErrorMemoryAllocation) goto Done;
            states[gi].scrypt_scratch = nullptr;
            scratch_bytes = (scratch_bytes * 15ull) / 16ull;
        }
        if (st != metalSuccess || scratch_bytes < max_scrypt_scratch_stride) goto Done;
        concurrency = std::min<uint64_t>(requested_concurrency_cap, scratch_bytes / max_scrypt_scratch_stride);
        states[gi].scrypt_scratch_stride = max_scrypt_scratch_stride;
        states[gi].scrypt_scratch_bytes = scratch_bytes;
        states[gi].scrypt_concurrency = concurrency;
        if (scratch_bytes != requested_scratch_bytes) {
            printf("[!] GPU %d %s scrypt scratch allocation backoff: %.2f -> %.2f MiB [!]\n",
                g_gpu_contexts[gi].device_id,
                mode_lc,
                static_cast<double>(requested_scratch_bytes) / 1048576.0,
                static_cast<double>(scratch_bytes) / 1048576.0);
        }
        min_concurrency = std::min<uint64_t>(min_concurrency, std::max<uint64_t>(1ull, states[gi].scrypt_concurrency));
        printf("[!] GPU %d %s scrypt scratch: %.2f MiB, max active jobs/launch: %llu [!]\n",
            g_gpu_contexts[gi].device_id,
            mode_lc,
            static_cast<double>(scratch_bytes) / 1048576.0,
            static_cast<unsigned long long>(concurrency));
        printf("[!] GPU %d %s VRAM safety reserve: %.2f MiB [!]\n",
            g_gpu_contexts[gi].device_id,
            mode_lc,
            static_cast<double>(reserve) / 1048576.0);
    }

    {
        const uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0 ? n_number : std::max<uint64_t>(1ull, min_concurrency);
        if (!wallet_masks.empty()) {
            for (const auto& mask : wallet_masks) {
                WalletMaskSpec spec{}; std::string err;
                if (!wallet_prepare_mask_spec(mask, spec, err)) { fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str()); st = metalErrorInvalidValue; goto Done; }
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    if (states[gi].mask_spec == nullptr) { st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec)); if (st != metalSuccess) goto Done; }
                    st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                }
                uint64_t processed = 0;
                while (processed < spec.total_candidates && !all_solved) {
                    std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                    std::vector<std::thread> workers;
                    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                        const uint64_t start = processed + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                        if (start >= spec.total_candidates) break;
                        const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, spec.total_candidates - start);
                        workers.emplace_back([&, gi, start, count]() {
                            { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                            gst[gi] = wallet_launch_bitcoinjwallet_generated(states[gi], WALLET_CANDIDATE_MASK, start, count, target_files, solved_files, all_solved);
                            { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                            });
                    }
                    for (auto& th : workers) th.join();
                    for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
                    processed += wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                }
            }
        }
        else if (seqMode) {
            WalletRangeHostState range_state{}; std::string err;
            if (!wallet_prepare_range_state(range_state, err)) { fprintf(stderr, "[!] Error: invalid %s raw range: %s [!]\n", mode_lc, err.c_str()); st = metalErrorInvalidValue; goto Done; }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec)); if (st != metalSuccess) goto Done;
            }
            while (range_state.valid && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    WalletRangeSpec spec{}; uint64_t count = 0;
                    if (!wallet_range_next_window(range_state, wallet_generated_launch_chunk, spec, count)) break;
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                    workers.emplace_back([&, gi, count]() {
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                        gst[gi] = wallet_launch_bitcoinjwallet_generated(states[gi], WALLET_CANDIDATE_RANGE, 0ull, count, target_files, solved_files, all_solved);
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                        });
                }
                if (workers.empty()) break;
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
        else {
            WalletPassReader reader;
            if (!reader.open(mnemonicFiles, IS_HEX)) { fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str()); st = metalErrorInvalidValue; goto Done; }
            const uint32_t batch_sz = static_cast<uint32_t>(std::min<uint64_t>(static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()), wallet_generated_launch_chunk));
            std::vector<WalletPassBuf> batches;
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            workers.reserve(g_gpu_contexts.size());
            while (!all_solved) {
                const bool any = wallet_read_split_pass_batch(reader, batch_sz, g_gpu_contexts.size(), batches);
                if (reader.failed) { st = metalErrorInvalidValue; goto Done; }
                if (!any) break;
                std::fill(gst.begin(), gst.end(), metalSuccess);
                workers.clear();
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) if (batches[gi].count != 0) {
                    workers.emplace_back([&, gi]() {
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                        gst[gi] = wallet_launch_bitcoinjwallet_dict_batch(batches[gi], states[gi], target_files, solved_files, all_solved);
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
    }

Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_bitcoinjwallet_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalArmoryWallet()
{
    std::vector<std::string> files = wallet_artifact_files;
    std::vector<std::string> dir_files;
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, { ".wallet", ".dat", "" }, dir_files);
    }
    const size_t raw_dir_files = dir_files.size();
    size_t prefiltered_dir_files = 0u;
    for (const std::string& path : dir_files) {
        if (wallet_armory_should_try_dir_file(path)) {
            files.push_back(path);
        }
        else {
            ++prefiltered_dir_files;
        }
    }
    if (files.empty()) {
        fprintf(stderr, "[!] Error: -armorywallet requires FILE or -f DIR [!]\n");
        return metalErrorInvalidValue;
    }
    printf("[!] armorywallet files discovered: %zu [!]\n", files.size());
    if (prefiltered_dir_files != 0u) {
        printf("[!] armorywallet prefilter skipped non-Armory files: %zu/%zu [!]\n",
            prefiltered_dir_files, raw_dir_files);
    }

    std::vector<ArmoryWalletHostTarget> host_targets;
    std::vector<std::string> target_files;
    std::unordered_set<std::string> seen;
    size_t skipped = 0u, skipped_plain = 0u, warnings = 0u, warnings_suppressed = 0u, duplicate_targets = 0u;
    std::vector<ArmoryWalletLoadFileResult> load_results;
    wallet_parallel_load_files(files, "armorywallet", load_results, wallet_load_one_armorywallet_file);
    for (ArmoryWalletLoadFileResult& result : load_results) {
        if (!result.loaded) {
            ++skipped;
            if (result.unencrypted) ++skipped_plain;
            if (warnings < 32u && !result.unencrypted) {
                fprintf(stderr, "[!] Warning: armorywallet '%s': skipped, %s [!]\n",
                    result.path.c_str(), result.err.empty() ? "unsupported or invalid" : result.err.c_str());
                ++warnings;
            }
            else if (!result.unencrypted) {
                ++warnings_suppressed;
            }
            continue;
        }
        std::string key = wallet_armory_target_key(result.target.dev);
        if (!seen.insert(std::move(key)).second) {
            ++duplicate_targets;
            continue;
        }
        const uint32_t file_index = static_cast<uint32_t>(target_files.size());
        result.target.dev.target_index = file_index;
        result.target.file = result.path;
        target_files.push_back(result.path);
        host_targets.push_back(std::move(result.target));
    }
    if (host_targets.empty()) {
        fprintf(stderr, "[!] Error: no usable encrypted Armory wallet targets loaded (%zu skipped, %zu plaintext) [!]\n",
            skipped, skipped_plain);
        return metalErrorInvalidValue;
    }

    std::vector<ArmoryWalletTarget> targets;
    targets.reserve(host_targets.size());
    uint64_t max_romix_scratch_stride = 0ull;
    uint64_t min_mem = UINT64_MAX, max_mem = 0ull, total_mem = 0ull;
    uint32_t min_iter = UINT32_MAX, max_iter = 0u;
    for (const auto& host : host_targets) {
        targets.push_back(host.dev);
        const uint64_t stride = wallet_scrypt_align_stride(static_cast<uint64_t>(host.dev.kdf_mem));
        max_romix_scratch_stride = std::max<uint64_t>(max_romix_scratch_stride, stride);
        min_mem = std::min<uint64_t>(min_mem, host.dev.kdf_mem);
        max_mem = std::max<uint64_t>(max_mem, host.dev.kdf_mem);
        total_mem += host.dev.kdf_mem;
        min_iter = std::min<uint32_t>(min_iter, host.dev.kdf_iterations);
        max_iter = std::max<uint32_t>(max_iter, host.dev.kdf_iterations);
    }
    std::sort(targets.begin(), targets.end(), [](const ArmoryWalletTarget& a, const ArmoryWalletTarget& b) {
        if (a.kdf_mem != b.kdf_mem) return a.kdf_mem < b.kdf_mem;
        if (a.kdf_iterations != b.kdf_iterations) return a.kdf_iterations < b.kdf_iterations;
        return a.target_index < b.target_index;
        });
    std::vector<uint64_t> work_by_target;
    std::vector<uint64_t> scratch_by_target;
    work_by_target.reserve(targets.size());
    scratch_by_target.reserve(targets.size());
    for (const auto& t : targets) {
        const uint64_t mem_blocks = std::max<uint64_t>(1ull, static_cast<uint64_t>(t.kdf_mem) >> 6);
        work_by_target.push_back(mem_blocks * std::max<uint32_t>(1u, t.kdf_iterations));
        scratch_by_target.push_back(wallet_scrypt_align_stride(static_cast<uint64_t>(t.kdf_mem)));
    }
    std::vector<WalletGenericTargetChunk> chunks;
    wallet_build_generic_chunks_from_work(work_by_target, chunks, walletdat_max_kdf_iter_work_per_launch, &scratch_by_target);
    counterWalletActiveTargets = static_cast<uint64_t>(targets.size());

    printf("[!] starting ARMORYWALLET mode [!]\n");
    printf("[!] loaded encrypted Armory wallet targets: %zu [!]\n", targets.size());
    if (duplicate_targets != 0u) {
        printf("[!] armorywallet compact targets: %zu unique [saved %zu duplicate KDF check(s)] [!]\n",
            targets.size(), duplicate_targets);
    }
    if (skipped != 0u) printf("[!] skipped Armory wallet files: %zu [plaintext=%zu] [!]\n", skipped, skipped_plain);
    if (warnings_suppressed != 0u) {
        printf("[!] armorywallet load warnings suppressed: %zu more skipped/invalid file warning(s) [!]\n",
            warnings_suppressed);
    }
    wallet_print_skip_reason_summary_from_results("armorywallet", load_results);
    const double avg_mem = targets.empty() ? 0.0 : static_cast<double>(total_mem) / static_cast<double>(targets.size());
    printf("[!] armorywallet KDF memory bytes: min=%llu avg=%.1f max=%llu; iterations min=%u max=%u [!]\n",
        static_cast<unsigned long long>(min_mem == UINT64_MAX ? 0ull : min_mem), avg_mem,
        static_cast<unsigned long long>(max_mem), min_iter == UINT32_MAX ? 0u : min_iter, max_iter);
    printf("[!] armorywallet launch chunks: %zu chunk(s), <=%llu KDF memory-block work per launch window [!]\n",
        chunks.size(), static_cast<unsigned long long>(walletdat_max_kdf_iter_work_per_launch));
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after armorywallet target load [!]\n");
        return metalSuccess;
    }

    std::vector<uint8_t> solved_files(target_files.size(), 0u);
    { std::lock_guard<std::mutex> lock(armorywallet_solved_mutex); armorywallet_solved_version = 0ull; }
    bool all_solved = false;
    std::vector<ArmoryWalletDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    uint64_t min_concurrency = std::numeric_limits<uint64_t>::max();
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
        states[gi].target_count = static_cast<uint32_t>(targets.size());
        states[gi].solved_count = static_cast<uint32_t>(target_files.size());
        states[gi].target_chunks = chunks;
        for (const ArmoryWalletTarget& t : targets) states[gi].target_file_indices.push_back(t.target_index);
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), targets.size() * sizeof(ArmoryWalletTarget)); if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, targets.data(), targets.size() * sizeof(ArmoryWalletTarget), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;

        size_t free_mem = 0, total_gpu_mem = 0;
        st = metalMemGetInfo(&free_mem, &total_gpu_mem); if (st != metalSuccess) goto Done;
        const uint64_t reserve_target = wallet_scrypt_memory_reserve_bytes();
        const uint64_t reserve = std::min<uint64_t>(static_cast<uint64_t>(free_mem / 2u), reserve_target);
        const uint64_t hard_cap = static_cast<uint64_t>(free_mem > reserve ? free_mem - reserve : free_mem / 2u);
        uint64_t scratch_bytes = wallet_scrypt_scratch_budget_bytes(hard_cap, max_romix_scratch_stride);
        uint64_t concurrency = max_romix_scratch_stride ? scratch_bytes / max_romix_scratch_stride : 0ull;
        const uint64_t launch_lanes = static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
        concurrency = std::min<uint64_t>(concurrency, launch_lanes);
        const uint64_t requested_concurrency_cap = use_n_count && n_number > 0
            ? n_number
            : wallet_scrypt_default_concurrency_cap();
        concurrency = std::min<uint64_t>(concurrency, requested_concurrency_cap);
        if (scratch_bytes == 0ull || concurrency == 0ull) {
            fprintf(stderr, "[!] Error: not enough GPU memory for Armory KdfRomix scratch on GPU %d; need at least %llu bytes [!]\n",
                g_gpu_contexts[gi].device_id, static_cast<unsigned long long>(max_romix_scratch_stride));
            st = metalErrorMemoryAllocation;
            goto Done;
        }
        const uint64_t requested_scratch_bytes = scratch_bytes;
        while (scratch_bytes >= max_romix_scratch_stride) {
            st = metalMalloc(reinterpret_cast<void**>(&states[gi].romix_scratch),
                static_cast<size_t>(scratch_bytes));
            if (st == metalSuccess) break;
            if (st != metalErrorMemoryAllocation) goto Done;
            states[gi].romix_scratch = nullptr;
            scratch_bytes = (scratch_bytes * 15ull) / 16ull;
        }
        if (st != metalSuccess || scratch_bytes < max_romix_scratch_stride) goto Done;
        concurrency = std::min<uint64_t>(requested_concurrency_cap, scratch_bytes / max_romix_scratch_stride);
        states[gi].romix_scratch_stride = max_romix_scratch_stride;
        states[gi].romix_scratch_bytes = scratch_bytes;
        states[gi].romix_concurrency = concurrency;
        if (scratch_bytes != requested_scratch_bytes) {
            printf("[!] GPU %d armorywallet KdfRomix scratch allocation backoff: %.2f -> %.2f MiB [!]\n",
                g_gpu_contexts[gi].device_id,
                static_cast<double>(requested_scratch_bytes) / 1048576.0,
                static_cast<double>(scratch_bytes) / 1048576.0);
        }
        min_concurrency = std::min<uint64_t>(min_concurrency, std::max<uint64_t>(1ull, states[gi].romix_concurrency));
        printf("[!] GPU %d armorywallet KdfRomix scratch: %.2f MiB, max active jobs/launch: %llu [!]\n",
            g_gpu_contexts[gi].device_id,
            static_cast<double>(scratch_bytes) / 1048576.0,
            static_cast<unsigned long long>(concurrency));
        printf("[!] GPU %d armorywallet VRAM safety reserve: %.2f MiB [!]\n",
            g_gpu_contexts[gi].device_id,
            static_cast<double>(reserve) / 1048576.0);
    }

    {
        const uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0 ? n_number : std::max<uint64_t>(1ull, min_concurrency);
        if (!wallet_masks.empty()) {
            for (const auto& mask : wallet_masks) {
                WalletMaskSpec spec{}; std::string err;
                if (!wallet_prepare_mask_spec(mask, spec, err)) { fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str()); st = metalErrorInvalidValue; goto Done; }
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    if (states[gi].mask_spec == nullptr) { st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec)); if (st != metalSuccess) goto Done; }
                    st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                }
                uint64_t processed = 0;
                while (processed < spec.total_candidates && !all_solved) {
                    std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                    std::vector<std::thread> workers;
                    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                        const uint64_t start = processed + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                        if (start >= spec.total_candidates) break;
                        const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, spec.total_candidates - start);
                        workers.emplace_back([&, gi, start, count]() {
                            { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                            gst[gi] = wallet_launch_armorywallet_generated(states[gi], WALLET_CANDIDATE_MASK, start, count, target_files, solved_files, all_solved);
                            { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                            });
                    }
                    for (auto& th : workers) th.join();
                    for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
                    processed += wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                }
            }
        }
        else if (seqMode) {
            WalletRangeHostState range_state{}; std::string err;
            if (!wallet_prepare_range_state(range_state, err)) { fprintf(stderr, "[!] Error: invalid armorywallet raw range: %s [!]\n", err.c_str()); st = metalErrorInvalidValue; goto Done; }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec)); if (st != metalSuccess) goto Done;
            }
            while (range_state.valid && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    WalletRangeSpec spec{}; uint64_t count = 0;
                    if (!wallet_range_next_window(range_state, wallet_generated_launch_chunk, spec, count)) break;
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                    workers.emplace_back([&, gi, count]() {
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                        gst[gi] = wallet_launch_armorywallet_generated(states[gi], WALLET_CANDIDATE_RANGE, 0ull, count, target_files, solved_files, all_solved);
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                        });
                }
                if (workers.empty()) break;
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
        else {
            WalletPassReader reader;
            if (!reader.open(mnemonicFiles, IS_HEX)) { fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str()); st = metalErrorInvalidValue; goto Done; }
            const uint32_t batch_sz = static_cast<uint32_t>(std::min<uint64_t>(static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()), wallet_generated_launch_chunk));
            std::vector<WalletPassBuf> batches;
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            workers.reserve(g_gpu_contexts.size());
            while (!all_solved) {
                const bool any = wallet_read_split_pass_batch(reader, batch_sz, g_gpu_contexts.size(), batches);
                if (reader.failed) { st = metalErrorInvalidValue; goto Done; }
                if (!any) break;
                std::fill(gst.begin(), gst.end(), metalSuccess);
                workers.clear();
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) if (batches[gi].count != 0) {
                    workers.emplace_back([&, gi]() {
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; } }
                        gst[gi] = wallet_launch_armorywallet_dict_batch(batches[gi], states[gi], target_files, solved_files, all_solved);
                        { std::lock_guard<std::mutex> lock(g_metal_context_api_mutex); if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context(); }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
    }

Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_armorywallet_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processMetalElectrumWallet()
{
    std::vector<std::string> files = wallet_artifact_files;
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, { ".wallet", ".dat", ".json", ".txt", ".hash", ".log", "" }, files);
    }
    if (files.empty()) {
        fprintf(stderr, "[!] Error: -electrumwallet requires FILE or -f DIR [!]\n");
        return metalErrorInvalidValue;
    }
    std::vector<ElectrumWalletHostTarget> host_targets;
    std::vector<std::string> target_files;
    std::vector<uint8_t> initial_solved_files;
    std::vector<WalletModeResult> plaintext_results;
    size_t skipped = 0u, skipped_bie2 = 0u, warnings = 0u;
    size_t warnings_suppressed = 0u;
    size_t duplicate_electrum_targets = 0u;
    std::unordered_set<std::string> electrum_seen;
    auto electrum_dedup_key = [](const ElectrumWalletHostTarget& target) {
        std::string key;
        key.reserve(1u + 32u);
        key.push_back(static_cast<char>(target.dev.kind));
        key.append(reinterpret_cast<const char*>(target.dev.detail_hash),
            reinterpret_cast<const char*>(target.dev.detail_hash) + 32u);
        return key;
    };
    std::vector<ElectrumWalletLoadFileResult> load_results;
    wallet_parallel_load_files(files, "electrumwallet", load_results, wallet_load_one_electrumwallet_file);
    for (ElectrumWalletLoadFileResult& result : load_results) {
        if (!result.loaded) {
            ++skipped;
            if (result.unsupported_bie2) ++skipped_bie2;
            if (warnings < 32u) {
                fprintf(stderr, "[!] Warning: electrumwallet '%s': skipped, %s [!]\n",
                    result.path.c_str(), result.err.empty() ? "unsupported or invalid" : result.err.c_str());
                ++warnings;
            }
            else {
                ++warnings_suppressed;
            }
            continue;
        }
        if (result.targets.empty()) {
            result.targets.emplace_back(std::move(result.target));
        }
        for (ElectrumWalletHostTarget& target : result.targets) {
            if (target.file.empty()) target.file = result.path;
            const std::string key = electrum_dedup_key(target);
            if (!electrum_seen.insert(key).second) {
                ++duplicate_electrum_targets;
                continue;
            }
            const uint32_t file_index = static_cast<uint32_t>(target_files.size());
            target.dev.target_index = file_index;
            const std::string target_label = target.file;
            target_files.push_back(target_label);
            if (target.dev.kind == ELECTRUMWALLET_TARGET_PLAINTEXT) {
                WalletModeResult r{};
                r.mode = WALLET_MODE_ELECTRUMWALLET;
                r.type = ELECTRUMWALLET_TARGET_PLAINTEXT;
                r.target_index = file_index;
                r.payload_len = 32u;
                memcpy(r.payload, target.dev.detail_hash, 32u);
                plaintext_results.push_back(r);
                initial_solved_files.push_back(1u);
            }
            else {
                initial_solved_files.push_back(0u);
                host_targets.push_back(std::move(target));
            }
        }
    }
    if (!plaintext_results.empty()) {
        SaveResultElectrumWallet(OUT_FILE, Founds, save, plaintext_results.data(),
            static_cast<unsigned long long>(plaintext_results.size()), target_files);
        flush_all_async_save_queues();
    }
    if (host_targets.empty() && plaintext_results.empty()) {
        fprintf(stderr, "[!] Error: no usable Electrum wallet targets loaded (%zu skipped, %zu BIE2 unsupported) [!]\n", skipped, skipped_bie2);
        return metalErrorInvalidValue;
    }
    std::vector<ElectrumWalletTarget> targets;
    std::vector<uint8_t> ciphertext_pool;
    targets.reserve(host_targets.size());
    uint64_t ciphertext_pool_bytes = 0ull;
    for (const auto& t : host_targets) ciphertext_pool_bytes += static_cast<uint64_t>(t.ciphertext.size());
    if (ciphertext_pool_bytes > static_cast<uint64_t>(std::numeric_limits<size_t>::max())) {
        fprintf(stderr, "[!] Error: Electrum ciphertext pool is too large for this host [!]\n");
        return metalErrorMemoryAllocation;
    }
    ciphertext_pool.reserve(static_cast<size_t>(ciphertext_pool_bytes));
    uint32_t electrum_bie1_targets = 0u;
    uint32_t electrum_field_targets = 0u;
    for (auto& t : host_targets) {
        t.dev.ciphertext_offset = static_cast<uint64_t>(ciphertext_pool.size());
        if (t.dev.kind == ELECTRUMWALLET_TARGET_BIE1) {
            t.dev.precomp_index = electrum_bie1_targets++;
        }
        else {
            t.dev.precomp_index = UINT32_MAX;
            if (t.dev.kind == ELECTRUMWALLET_TARGET_FIELD_V1) ++electrum_field_targets;
        }
        ciphertext_pool.insert(ciphertext_pool.end(), t.ciphertext.begin(), t.ciphertext.end());
        targets.push_back(t.dev);
    }
    printf("[!] starting ELECTRUMWALLET mode [!]\n");
    printf("[!] loaded Electrum encrypted targets: %zu [!]\n", targets.size());
    printf("[!] Electrum target types: BIE1=%u FIELD=%u [!]\n", electrum_bie1_targets, electrum_field_targets);
    if (duplicate_electrum_targets != 0u) {
        printf("[!] Electrum compact targets: %zu unique [saved %zu duplicate target(s)] [!]\n",
            targets.size() + plaintext_results.size(), duplicate_electrum_targets);
    }
    if (!plaintext_results.empty()) printf("[!] Electrum plaintext/open wallets saved immediately: %zu [!]\n", plaintext_results.size());
    printf("[!] Electrum ciphertext pool: %.2f MiB [!]\n",
        static_cast<double>(ciphertext_pool.size()) / 1048576.0);
    if (skipped != 0u) printf("[!] skipped Electrum wallet files: %zu (BIE2 unsupported: %zu) [!]\n", skipped, skipped_bie2);
    if (warnings_suppressed != 0u) {
        printf("[!] electrumwallet load warnings suppressed: %zu more skipped/invalid file warning(s) [!]\n",
            warnings_suppressed);
    }
    wallet_print_skip_reason_summary_from_results("electrumwallet", load_results);
    if (WALLET_LOAD_ONLY) {
        printf("[!] wallet load-only: exiting after electrumwallet target load [!]\n");
        return metalSuccess;
    }
    if (targets.empty()) {
        printf("[!] no encrypted Electrum targets left after plaintext extraction [!]\n");
        return metalSuccess;
    }

    std::vector<uint8_t> solved_files = initial_solved_files;
    if (solved_files.size() < target_files.size()) solved_files.resize(target_files.size(), 0u);
    { std::lock_guard<std::mutex> lock(electrumwallet_solved_mutex); electrumwallet_solved_version = 0ull; }
    bool all_solved = false;
    std::vector<ElectrumWalletDeviceState> states(g_gpu_contexts.size());
    metalError_t st = metalSuccess;
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
        states[gi].target_count = static_cast<uint32_t>(targets.size());
        states[gi].field_only = (electrum_bie1_targets == 0u && electrum_field_targets == states[gi].target_count);
        states[gi].ciphertext_pool_size = static_cast<uint64_t>(ciphertext_pool.size());
        states[gi].solved_count = static_cast<uint32_t>(target_files.size());
        for (const ElectrumWalletTarget& t : targets) states[gi].target_file_indices.push_back(t.target_index);
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].targets), targets.size() * sizeof(ElectrumWalletTarget)); if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].targets, targets.data(), targets.size() * sizeof(ElectrumWalletTarget), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
        if (electrum_bie1_targets != 0u) {
            st = metalMalloc(reinterpret_cast<void**>(&states[gi].ecdh_precomp),
                static_cast<size_t>(electrum_bie1_targets) * sizeof(ElectrumWalletEcdhPrecomp)); if (st != metalSuccess) goto Done;
        }
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].ciphertext_pool), ciphertext_pool.empty() ? 1u : ciphertext_pool.size()); if (st != metalSuccess) goto Done;
        st = metalMemcpy(states[gi].ciphertext_pool, ciphertext_pool.empty() ? nullptr : ciphertext_pool.data(),
            ciphertext_pool.empty() ? 1u : ciphertext_pool.size(), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
        {
            const uint32_t prep_blocks = static_cast<uint32_t>(std::min<uint64_t>(
                static_cast<uint64_t>(BLOCK_NUMBER),
                (static_cast<uint64_t>(targets.size()) + BLOCK_THREADS - 1ull) / BLOCK_THREADS));
            metal_launch("workerElectrumWalletPrepareTargets", std::max<uint32_t>(1u, prep_blocks), BLOCK_THREADS, states[gi].targets, states[gi].ecdh_precomp, electrum_bie1_targets, static_cast<uint32_t>(targets.size()));
            st = metalGetLastError(); if (st != metalSuccess) goto Done;
            st = metalDeviceSynchronize(); if (st != metalSuccess) goto Done;
        }
        printf("[!] GPU %d electrumwallet ECDH precompute: %.2f MiB [!]\n",
            g_gpu_contexts[gi].device_id,
            static_cast<double>(static_cast<size_t>(electrum_bie1_targets) * sizeof(ElectrumWalletEcdhPrecomp)) / 1048576.0);
        st = metalMalloc(reinterpret_cast<void**>(&states[gi].solved_flags), target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;
        st = metalMemset(states[gi].solved_flags, 0, target_files.empty() ? 1u : target_files.size()); if (st != metalSuccess) goto Done;
    }
    {
        uint64_t wallet_generated_launch_chunk = use_n_count && n_number > 0 ? n_number : static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS;
        const uint64_t electrum_min_launch_chunk = std::max<uint64_t>(1ull, static_cast<uint64_t>(BLOCK_NUMBER) * BLOCK_THREADS);
        if (wallet_generated_launch_chunk < electrum_min_launch_chunk) {
            printf("[!] electrumwallet launch chunk raised to %llu password(s)/GPU for occupancy (requested %llu) [!]\n",
                static_cast<unsigned long long>(electrum_min_launch_chunk),
                static_cast<unsigned long long>(wallet_generated_launch_chunk));
            fflush(stdout);
            wallet_generated_launch_chunk = electrum_min_launch_chunk;
        }
        if (!wallet_masks.empty()) {
            for (const auto& mask : wallet_masks) {
                WalletMaskSpec spec{}; std::string err;
                if (!wallet_prepare_mask_spec(mask, spec, err)) { fprintf(stderr, "[!] Error: invalid -mask '%s': %s [!]\n", mask.c_str(), err.c_str()); st = metalErrorInvalidValue; goto Done; }
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    if (states[gi].mask_spec == nullptr) { st = metalMalloc(reinterpret_cast<void**>(&states[gi].mask_spec), sizeof(WalletMaskSpec)); if (st != metalSuccess) goto Done; }
                    st = metalMemcpy(states[gi].mask_spec, &spec, sizeof(WalletMaskSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                }
                uint64_t processed = 0;
                while (processed < spec.total_candidates && !all_solved) {
                    std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                    std::vector<std::thread> workers;
                    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                        const uint64_t start = processed + static_cast<uint64_t>(gi) * wallet_generated_launch_chunk;
                        if (start >= spec.total_candidates) break;
                        const uint64_t count = std::min<uint64_t>(wallet_generated_launch_chunk, spec.total_candidates - start);
                        workers.emplace_back([&, gi, start, count]() {
                            {
                                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                                if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                            }
                            gst[gi] = wallet_launch_electrumwallet_generated(states[gi], WALLET_CANDIDATE_MASK, start, count, target_files, solved_files, all_solved);
                            {
                                std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                                if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context();
                            }
                            });
                    }
                    for (auto& th : workers) th.join();
                    for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
                    processed += wallet_generated_launch_chunk * static_cast<uint64_t>(std::max<size_t>(g_gpu_contexts.size(), 1u));
                }
            }
        }
        else if (seqMode) {
            WalletRangeHostState range_state{}; std::string err;
            if (!wallet_prepare_range_state(range_state, err)) { fprintf(stderr, "[!] Error: invalid electrumwallet raw range: %s [!]\n", err.c_str()); st = metalErrorInvalidValue; goto Done; }
            for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                st = metalMalloc(reinterpret_cast<void**>(&states[gi].range_spec), sizeof(WalletRangeSpec)); if (st != metalSuccess) goto Done;
            }
            while (range_state.valid && !all_solved) {
                std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
                std::vector<std::thread> workers;
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
                    WalletRangeSpec spec{}; uint64_t count = 0;
                    if (!wallet_range_next_window(range_state, wallet_generated_launch_chunk, spec, count)) break;
                    if (!activate_gpu_context(g_gpu_contexts[gi])) { st = metalErrorInvalidDevice; goto Done; }
                    st = metalMemcpy(states[gi].range_spec, &spec, sizeof(WalletRangeSpec), metalMemcpyHostToDevice); if (st != metalSuccess) goto Done;
                    workers.emplace_back([&, gi, count]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_electrumwallet_generated(states[gi], WALLET_CANDIDATE_RANGE, 0ull, count, target_files, solved_files, all_solved);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                        });
                }
                if (workers.empty()) break;
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
        else {
            WalletPassReader reader;
            if (!reader.open(mnemonicFiles, IS_HEX)) { fprintf(stderr, "[!] Error: %s [!]\n", reader.error.c_str()); st = metalErrorInvalidValue; goto Done; }
            const uint32_t batch_sz = wallet_effective_dict_batch_u32("electrumwallet", wallet_generated_launch_chunk);
            std::vector<WalletPassBuf> batches;
            std::vector<metalError_t> gst(g_gpu_contexts.size(), metalSuccess);
            std::vector<std::thread> workers;
            workers.reserve(g_gpu_contexts.size());
            while (!all_solved) {
                const bool any = wallet_read_split_pass_batch(reader, batch_sz, g_gpu_contexts.size(), batches);
                if (reader.failed) { st = metalErrorInvalidValue; goto Done; }
                if (!any) break;
                std::fill(gst.begin(), gst.end(), metalSuccess);
                workers.clear();
                for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) if (batches[gi].count != 0) {
                    workers.emplace_back([&, gi]() {
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (!activate_gpu_context(g_gpu_contexts[gi])) { gst[gi] = metalErrorInvalidDevice; return; }
                        }
                        gst[gi] = wallet_launch_electrumwallet_dict_batch(batches[gi], states[gi], target_files, solved_files, all_solved);
                        {
                            std::lock_guard<std::mutex> lock(g_metal_context_api_mutex);
                            if (metalSetDevice(g_gpu_contexts[gi].device_id) == metalSuccess) g_gpu_contexts[gi] = capture_current_gpu_context();
                        }
                        });
                }
                for (auto& th : workers) th.join();
                for (metalError_t e : gst) if (e != metalSuccess) { st = e; goto Done; }
            }
        }
    }
Done:
    for (size_t gi = 0; gi < g_gpu_contexts.size(); ++gi) {
        if (activate_gpu_context(g_gpu_contexts[gi])) {
            wallet_release_electrumwallet_device_state(states[gi]);
            g_gpu_contexts[gi] = capture_current_gpu_context();
        }
    }
    if (!g_gpu_contexts.empty()) activate_gpu_context(g_gpu_contexts.front());
    return st;
}

metalError_t processWalletScan()
{
    std::vector<std::string> files = wallet_artifact_files;
    for (const auto& dir : wallet_artifact_dirs) {
        wallet_scan_dir(dir, { ".txt", ".json", ".dat", ".wallet", ".ldb", ".log", ".seco", "" }, files);
    }
    std::vector<std::string> unique_files;
    unique_files.reserve(files.size());
    std::unordered_set<std::string> seen_files;
    seen_files.reserve(files.size() * 2u + 1u);
    for (const std::string& path : files) {
        if (seen_files.insert(path).second) {
            unique_files.emplace_back(path);
        }
    }
    files.swap(unique_files);

    printf("[!] starting WALLETSCAN inventory mode [!]\n");
    printf("[!] walletscan files discovered: %zu [!]\n", files.size());
    std::atomic<size_t> mnemonic_like_files{ 0u };
    std::atomic<size_t> wif_like_files{ 0u };
    std::atomic<size_t> xprv_like_files{ 0u };
    std::atomic<size_t> xpub_like_files{ 0u };
    std::atomic<size_t> exodus_seco_like_files{ 0u };
    std::atomic<size_t> armory_wallet_files{ 0u };
    std::atomic<size_t> proto_wallet_files{ 0u };
    std::atomic<size_t> unreadable_files{ 0u };
    std::atomic<size_t> next_file{ 0u };
    const unsigned int hw_threads = std::max(1u, std::thread::hardware_concurrency());
    const size_t worker_count = std::min<size_t>(
        files.empty() ? 1u : files.size(),
        std::min<size_t>(32u, static_cast<size_t>(hw_threads)));
    printf("[!] walletscan worker threads: %zu [!]\n", worker_count);

    struct WalletScanWorkerOutput {
        WalletScanExtractStats stats;
        std::vector<WalletScanFinding> findings;
        std::unordered_set<std::string> seen;
    };
    std::vector<WalletScanWorkerOutput> worker_outputs(worker_count);
    std::vector<std::thread> workers;
    workers.reserve(worker_count);
    for (size_t worker = 0u; worker < worker_count; ++worker) {
        workers.emplace_back([&, worker]() {
            WalletScanWorkerOutput& local = worker_outputs[worker];
            local.findings.reserve(1024u);
            local.seen.reserve(2048u);
            for (;;) {
                const size_t idx = next_file.fetch_add(1u, std::memory_order_relaxed);
                if (idx >= files.size()) {
                    break;
                }
                const std::string& path = files[idx];
                if (!mac_is_regular_file(path)) continue;
                std::vector<uint8_t> raw;
                std::string err;
                const bool raw_ok = mac_read_binary_file(path, raw, err);
                if (raw_ok && raw.size() >= 16u && memcmp(raw.data(), "SECO", 4u) == 0) {
                    exodus_seco_like_files.fetch_add(1u, std::memory_order_relaxed);
                    wallet_scan_add_finding(local.findings, local.seen, local.stats,
                        "EXODUSSECO", path, 1u, "seco-v0-scrypt-aes");
                }
                if (raw_ok && !raw.empty() && wallet_scan_is_armory_wallet_raw(raw)) {
                    armory_wallet_files.fetch_add(1u, std::memory_order_relaxed);
                    wallet_scan_extract_armory_wallet(path, raw, local.findings, local.seen, local.stats);
                }
                else if (raw_ok && !raw.empty() && wallet_scan_is_likely_proto_wallet_raw(path, raw)) {
                    proto_wallet_files.fetch_add(1u, std::memory_order_relaxed);
                    wallet_scan_add_finding(local.findings, local.seen, local.stats,
                        "PROTO_WALLET", path, 1u, "protobuf-wallet");
                }
                std::string text;
                const char* text_data = nullptr;
                size_t text_len = 0u;
                if (raw_ok) {
                    text_data = reinterpret_cast<const char*>(raw.data());
                    text_len = raw.size();
                }
                else if (!mac_read_text_file(path, text, err)) {
                    unreadable_files.fetch_add(1u, std::memory_order_relaxed);
                    continue;
                }
                else {
                    text_data = text.data();
                    text_len = text.size();
                }

                bool file_has_wif = false;
                bool file_has_xprv = false;
                bool file_has_xpub = false;
                bool file_has_mnemonic = false;

                wallet_scan_extract_base58(path, text_data, text_len, local.findings, local.seen, local.stats,
                    file_has_wif, file_has_xprv, file_has_xpub, nullptr);
                wallet_scan_extract_mnemonics(path, text_data, text_len, local.findings, local.seen, local.stats,
                    file_has_mnemonic, nullptr);

                if (file_has_wif) wif_like_files.fetch_add(1u, std::memory_order_relaxed);
                if (file_has_xprv) xprv_like_files.fetch_add(1u, std::memory_order_relaxed);
                if (file_has_xpub) xpub_like_files.fetch_add(1u, std::memory_order_relaxed);
                if (file_has_mnemonic) mnemonic_like_files.fetch_add(1u, std::memory_order_relaxed);
            }
            });
    }
    for (std::thread& worker : workers) {
        worker.join();
    }
    WalletScanExtractStats stats;
    std::vector<WalletScanFinding> findings;
    std::unordered_set<std::string> seen_findings;
    size_t total_local_findings = 0u;
    size_t local_duplicate_count = 0u;
    for (const WalletScanWorkerOutput& out : worker_outputs) {
        total_local_findings += out.findings.size();
        local_duplicate_count += out.stats.duplicates;
    }
    findings.reserve(total_local_findings);
    seen_findings.reserve(total_local_findings * 2u + 1u);
    for (const WalletScanWorkerOutput& out : worker_outputs) {
        for (const WalletScanFinding& f : out.findings) {
            wallet_scan_add_finding(findings, seen_findings, stats, f.type, f.file, f.line_no, f.value);
        }
    }
    stats.duplicates += local_duplicate_count;
    printf("[!] walletscan files with validated artifacts: mnemonic=%zu wif=%zu xprv=%zu xpub=%zu exodus_seco=%zu armory_wallet=%zu proto_wallet=%zu [!]\n",
        mnemonic_like_files.load(), wif_like_files.load(), xprv_like_files.load(), xpub_like_files.load(),
        exodus_seco_like_files.load(), armory_wallet_files.load(), proto_wallet_files.load());
    printf("[!] walletscan unique artifacts: mnemonic=%zu wif=%zu xprv=%zu xpub=%zu exodus_seco=%zu armory_wallet=%zu armory_root=%zu armory_priv=%zu proto_wallet=%zu duplicates=%zu unreadable=%zu [!]\n",
        stats.mnemonic, stats.wif, stats.xprv, stats.xpub, stats.exodus_seco, stats.armory_wallet,
        stats.armory_root, stats.armory_priv, stats.proto_wallet, stats.duplicates, unreadable_files.load());
    if (!host_silent_mode) {
        for (const WalletScanFinding& f : findings) {
            printf("WALLETSCAN:%s:%s:LINE:%zu:VALUE:%s\n",
                f.file.c_str(), f.type.c_str(), f.line_no, f.value.c_str());
        }
        fflush(stdout);
    }
    if (save && OUT_FILE != nullptr) {
        fprintf(OUT_FILE, "WALLETSCAN:SUMMARY:FILES:%zu:MNEMONIC:%zu:WIF:%zu:XPRV:%zu:XPUB:%zu:EXODUSSECO:%zu:ARMORYWALLET:%zu:ARMORY_ROOT:%zu:ARMORY_PRIV:%zu:PROTO_WALLET:%zu:DUPLICATES:%zu:UNREADABLE:%zu\n",
            files.size(), stats.mnemonic, stats.wif, stats.xprv, stats.xpub, stats.exodus_seco,
            stats.armory_wallet, stats.armory_root, stats.armory_priv, stats.proto_wallet, stats.duplicates, unreadable_files.load());
        for (const WalletScanFinding& f : findings) {
            fprintf(OUT_FILE, "WALLETSCAN:%s:%s:LINE:%zu:VALUE:%s\n",
                f.file.c_str(), f.type.c_str(), f.line_no, f.value.c_str());
            ++Founds;
        }
        fflush(OUT_FILE);
    }
    return metalSuccess;
}

metalError_t processMetalProfanity()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_profanity_multi_gpu();
    }
    metalError_t metalStatus = metalSuccess;
    profanity_direct_guard_launch_geometry();
    const uint64_t physical_lanes_per_launch = profanity_lanes_per_launch();
    const uint64_t logical_lane_start = profanity_lane_partition_active ? profanity_partition_lane_start : 0ull;
    const uint64_t logical_lane_count = profanity_lane_partition_active
        ? profanity_partition_lane_count
        : profanity_direct_foundid_count();
    const uint64_t logical_state_index_start = profanity_lane_partition_active ? profanity_partition_state_index_start : 0ull;
    const uint64_t rounds_per_launch = profanity_direct_rounds_per_launch();
    uint64_t round_begin_window = 0ull;
    uint64_t round_end_window = 0ull;
    if (!profanity_round_window(round_begin_window, round_end_window)) {
        fprintf(stderr, "[!] Error: -profanity requires -n > 0 [!]\n");
        return metalErrorInvalidValue;
    }
    if (physical_lanes_per_launch == 0ull || logical_lane_count == 0ull) {
        fprintf(stderr, "[!] Error: -profanity has zero active Metal lanes [!]\n");
        return metalErrorInvalidValue;
    }
    if (profanity_target_count() <= 0) {
        fprintf(stderr, "[!] Error: -profanity requires at least one secp target in -c cusrpex [!]\n");
        return metalErrorInvalidValue;
    }
    if (Solana || Ton || Ton_all || Dot || Aptos || Sui || Xrp || Exodus || Iota || Ada || Icp || Fil || Xtz || Endomorphism) {
        fprintf(stderr, "[!] Error: -profanity v1 supports only secp targets c/u/s/p/r/x/e and no endomorphism [!]\n");
        return metalErrorInvalidValue;
    }

    const bool direct_host_filters_active = FULL || useHashTarget || useBloom || useXor || useXorUn || useXorUc || useXorHc;
    const uint64_t direct_window_rounds = profanity_range_remaining_inclusive(round_begin_window, round_end_window);
    const bool direct_walk_state_required =
        direct_host_filters_active &&
        direct_window_rounds > rounds_per_launch;

    if (p_profanity_results == nullptr || p_profanity_count == nullptr) {
        fprintf(stderr, "[!] Error: Profanity result buffer is not allocated on GPU %d [!]\n", DEVICE_NR);
        metalStatus = metalErrorInvalidDevicePointer;
        goto Error;
    }
    if (direct_walk_state_required &&
        (p_profanity_walk_state == nullptr ||
            logical_state_index_start > (std::numeric_limits<uint64_t>::max() - logical_lane_count) ||
            p_profanity_walk_state_capacity < (logical_state_index_start + logical_lane_count))) {
        fprintf(stderr, "[!] Error: Profanity walk-state buffer is not allocated for %llu lanes on GPU %d [!]\n",
            static_cast<unsigned long long>(logical_lane_count),
            DEVICE_NR);
        metalStatus = metalErrorMemoryAllocation;
        goto Error;
    }
    metalStatus = metalMemset(p_profanity_count, 0, sizeof(unsigned long long));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemset profanity result count failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    {
        std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
        bool walk_state_valid = false;
        uint32_t walk_state_seed = 0;
        uint64_t walk_state_lane_start = 0ull;
        uint64_t walk_state_lane_count = 0ull;
        uint64_t walk_state_state_index_start = 0ull;
        uint64_t walk_state_next_round = 0ull;
        const bool host_filters_active = direct_host_filters_active && p_profanity_walk_state != nullptr;
        ProfanityRandomSeedBlock random_seed_block;
        uint32_t seed = profanity_direct_fixed_seed_pass_active ? profanity_direct_fixed_seed_value : start_seed;
        if (isRandom && !profanity_direct_fixed_seed_pass_active) {
            if (!profanity_next_random_seed(start_seed, end_seed, random_seed_block, seed)) {
                fprintf(stderr, "[!] Error: -profanity -random failed to pick seed block [!]\n");
                metalStatus = metalErrorInvalidValue;
                goto Error;
            }
        }
        while (isRun) {
            const uint64_t round_begin = round_begin_window;
            const uint64_t round_end = round_end_window;
            if (round_begin > round_end) {
                break;
            }
            uint64_t round = round_begin;
            while (isRun) {
                uint64_t batch_rounds = 0ull;
                uint64_t remain = 0ull;
                if (profanity_recovery_round_queue_active) {
                    if (!profanity_recovery_acquire_round_window(round_end, rounds_per_launch, round, batch_rounds)) {
                        break;
                    }
                }
                else {
                    if (round > round_end) {
                        break;
                    }
                    remain = profanity_range_remaining_inclusive(round, round_end);
                    if (remain == 0ull) {
                        break;
                    }
                    batch_rounds = std::min(rounds_per_launch, remain);
                }
                uint64_t lane_chunk_offset = 0ull;
                while (lane_chunk_offset < logical_lane_count && isRun) {
                    const uint64_t lane_chunk_count = std::min<uint64_t>(
                        physical_lanes_per_launch,
                        logical_lane_count - lane_chunk_offset);
                    const uint64_t lane_chunk_start = logical_lane_start + lane_chunk_offset;
                    const uint64_t lane_chunk_state_index_start = logical_state_index_start + lane_chunk_offset;
                    const unsigned int launch_blocks = profanity_blocks_for_lane_count(lane_chunk_count);
                    const uint64_t launch_checks = profanity_mul_saturate_u64(lane_chunk_count, batch_rounds);
                    const bool use_walk_state =
                        host_filters_active &&
                        walk_state_valid &&
                        walk_state_seed == seed &&
                        walk_state_lane_start == lane_chunk_start &&
                        walk_state_lane_count == lane_chunk_count &&
                        walk_state_state_index_start == lane_chunk_state_index_start &&
                        walk_state_next_round == round;
                    const bool store_walk_state =
                        host_filters_active &&
                        batch_rounds != 0ull &&
                        (batch_rounds % 1024ull) == 0ull;

                    metalStatus = launch_workerProfanity(MetalGridSize(launch_blocks), MetalGridSize(BLOCK_THREADS),
                        nullptr, nullptr, _dev_precomp, pitch, seed, lane_chunk_start, lane_chunk_count, lane_chunk_state_index_start, round, batch_rounds,
                        p_profanity_walk_state, p_profanity_walk_state_capacity, use_walk_state, store_walk_state);
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "workerProfanity launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    metalStatus = metalDeviceSynchronize();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "workerProfanity sync failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    if (store_walk_state && batch_rounds <= (std::numeric_limits<uint64_t>::max() - round)) {
                        walk_state_valid = true;
                        walk_state_seed = seed;
                        walk_state_lane_start = lane_chunk_start;
                        walk_state_lane_count = lane_chunk_count;
                        walk_state_state_index_start = lane_chunk_state_index_start;
                        walk_state_next_round = round + batch_rounds;
                    }
                    else {
                        walk_state_valid = false;
                    }

                    counterTotal += launch_checks;

                    unsigned long long profanity_count_host = 0ull;
                    metalStatus = metalMemcpy(&profanity_count_host, p_profanity_count, sizeof(profanity_count_host), metalMemcpyDeviceToHost);
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy profanity result count failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    if (profanity_count_host > 0ull) {
                        if (profanity_count_host > static_cast<unsigned long long>(MAX_FOUNDS)) {
                            fprintf(stderr,
                                "[!] Warning: Profanity found buffer overflow (%llu > %u); increase -fsize [!]\n",
                                profanity_count_host,
                                MAX_FOUNDS);
                        }
                        const size_t save_count = static_cast<size_t>(std::min<unsigned long long>(
                            profanity_count_host,
                            static_cast<unsigned long long>(MAX_FOUNDS)));
                        std::vector<ProfanityVerifiedResult> host_results(save_count);
                        metalStatus = metalMemcpy(host_results.data(), p_profanity_results,
                            save_count * sizeof(ProfanityVerifiedResult),
                            metalMemcpyDeviceToHost);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy profanity results failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        order_profanity_results_by_lane(host_results, lane_chunk_start, round);
                        SaveResultProfanity(OUT_FILE, Founds, save, host_results.data(),
                            static_cast<unsigned long long>(save_count));
                        flush_all_async_save_queues();
                        metalStatus = metalMemset(p_profanity_count, 0, sizeof(unsigned long long));
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemset profanity result count after save failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                    }

                    const long long tStatus = std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - beginCountStatus).count();
                    if (tStatus > 2500) {
                        char log_name[64];
                        const int profanity_gpu_id = (profanity_partition_gpu_id >= 0) ? profanity_partition_gpu_id : DEVICE_NR;
                        if (profanity_lane_partition_active) {
                            snprintf(log_name, sizeof(log_name), "Profanity_log_gpu%d.txt", profanity_gpu_id);
                        }
                        else {
                            snprintf(log_name, sizeof(log_name), "Profanity_log.txt");
                        }
                        FILE* fp = open_runtime_log(log_name, "wb");
                        if (fp) {
                            fprintf(fp, "gpu_id=%d gpu_split=%s seed=%08x lane_start=%016llx lane_count=%016llx lane_total_start=%016llx lane_total_count=%016llx state_index_start=%016llx round_offset=%016llx round_count=%016llx round_end=%016llx physical_blocks=%u physical_threads=%u\n",
                                profanity_gpu_id,
                                profanity_gpu_split_mode_name(profanity_gpu_split_mode),
                                seed,
                                static_cast<unsigned long long>(lane_chunk_start),
                                static_cast<unsigned long long>(lane_chunk_count),
                                static_cast<unsigned long long>(logical_lane_start),
                                static_cast<unsigned long long>(logical_lane_count),
                                static_cast<unsigned long long>(lane_chunk_state_index_start),
                                static_cast<unsigned long long>(round),
                                static_cast<unsigned long long>(batch_rounds),
                                static_cast<unsigned long long>(round_end),
                                launch_blocks,
                                BLOCK_THREADS);
                            fclose(fp);
                        }
                        beginCountStatus = std::chrono::steady_clock::now();
                    }

                    lane_chunk_offset += lane_chunk_count;
                }

                if (!profanity_recovery_round_queue_active) {
                    if (batch_rounds == remain) {
                        break;
                    }
                    round += batch_rounds;
                }
            }
            if (profanity_recovery_round_queue_active) {
                break;
            }
            if (profanity_direct_fixed_seed_pass_active) {
                break;
            }
            if (isRandom) {
                if (!profanity_next_random_seed(start_seed, end_seed, random_seed_block, seed)) {
                    fprintf(stderr, "[!] Error: -profanity -random failed to pick seed block [!]\n");
                    metalStatus = metalErrorInvalidValue;
                    goto Error;
                }
            }
            else {
                if (seed == end_seed || seed == UINT32_MAX) {
                    break;
                }
                ++seed;
            }
        }
    }

Error:
    return metalStatus;
}

metalError_t processMetalProfanityRecovery()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_profanity_recovery_multi_gpu();
    }

    metalError_t metalStatus = metalSuccess;
    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;

    std::array<uint8_t, 65> target_pubkey{};
    uint32_t target_len = 0;
    std::string parse_err;
    if (!parse_profanity_pubkey_bytes(target_pubkey, target_len, parse_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", parse_err.c_str());
        return metalErrorInvalidValue;
    }

    const bool has_basepoint_filter = useXor || useXorUn || useXorUc || useXorHc;
    if (!has_basepoint_filter) {
        fprintf(stderr, "[!] Error: -profanity -recovery requires at least one Profanity basepoint-X XOR filter (-xc/-xu/-xuc/-xh) [!]\n");
        return metalErrorInvalidValue;
    }
    if (useBloom || useBloomCPU) {
        fprintf(stderr, "[!] Error: -profanity -recovery supports XOR basepoint filters only; bloom filters are not supported here [!]\n");
        return metalErrorInvalidValue;
    }

    // In Profanity recovery, -xx confirms basepoint-X hits only. Verified
    // results use a dedicated save path instead of the generic PRIV buffers.
    const bool recovery_use_xx = useXorCPU;

    profanity_recovery_guard_launch_geometry();

    const uint64_t reverse_begin = profanity_recovery_round_window_thread_override_active
        ? profanity_recovery_round_window_thread_begin
        : (profanity_offset_explicit ? profanity_offset : 0ull);
    const uint64_t reverse_end = profanity_recovery_round_window_thread_override_active
        ? profanity_recovery_round_window_thread_end
        : (g_profanity_recovery_window_override_active.load(std::memory_order_relaxed)
            ? g_profanity_recovery_window_end.load(std::memory_order_relaxed)
            : std::numeric_limits<uint64_t>::max());
    if (reverse_begin > reverse_end) {
        return metalSuccess;
    }

    const uint64_t reverse_rounds_per_launch = profanity_walk_rounds_per_launch();
    const uint64_t reverse_lane_start = profanity_lane_partition_active ? profanity_partition_lane_start : 0ull;
    const uint64_t reverse_lane_count = profanity_lane_partition_active
        ? profanity_partition_lane_count
        : profanity_recovery_historical_lane_count();
    const bool recovery_stateful_window =
        g_profanity_recovery_window_override_active.load(std::memory_order_relaxed) &&
        p_profanity_walk_state != nullptr &&
        p_profanity_walk_state_capacity >= reverse_lane_count;
    const uint64_t reverse_lane_chunk_limit = recovery_stateful_window
        ? reverse_lane_count
        : std::min<uint64_t>(reverse_lane_count, profanity_recovery_lane_chunk_limit());
    const uint64_t seed_group_candidates_per_launch =
        static_cast<uint64_t>(profanity_seed_resolve_blocks()) * static_cast<uint64_t>(BLOCK_THREADS);
    const uint64_t seed_pair_candidates_per_launch = profanity_mul_saturate_u64(
        seed_group_candidates_per_launch,
        static_cast<uint64_t>(THREAD_STEPS));
    const uint64_t resolve_lane_count = 1ull;
    const uint64_t resolve_lane_start = reverse_lane_start;
    const uint32_t max_hits = MAX_FOUNDS;

    metalStatus = allocate_result_buffers_device(1ull, &buffIsResult, &buffDeviceResult);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "allocate_result_buffers failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = ensure_profanity_recovery_target_prepared(target_pubkey, target_len);
    if (metalStatus != metalSuccess) {
        goto Error;
    }
    if (p_profanity_recovery_hits == nullptr || p_profanity_recovery_hit_count == nullptr) {
        fprintf(stderr, "[!] Error: Profanity recovery hit buffer is not allocated on GPU %d [!]\n", DEVICE_NR);
        metalStatus = metalErrorInvalidDevicePointer;
        goto Error;
    }
    if (p_profanity_results == nullptr || p_profanity_count == nullptr) {
        fprintf(stderr, "[!] Error: Profanity result buffer is not allocated on GPU %d [!]\n", DEVICE_NR);
        metalStatus = metalErrorInvalidDevicePointer;
        goto Error;
    }

    {
        std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
        const bool recovery_xc_only = useXor && !useXorUn && !useXorUc && !useXorHc;
        const bool recovery_xuc_only = useXorUc && !useXor && !useXorUn && !useXorHc;
        const bool recovery_xh_only = useXorHc && !useXor && !useXorUn && !useXorUc;
        uint64_t round = reverse_begin;
        while (isRun && !g_profanity_recovery_found_any.load(std::memory_order_relaxed)) {
            uint64_t round_count = 0ull;
            if (profanity_recovery_round_queue_active) {
                if (!profanity_recovery_acquire_round_window(reverse_end, reverse_rounds_per_launch, round, round_count)) {
                    break;
                }
            }
            else {
                const uint64_t remain = profanity_range_remaining_inclusive(round, reverse_end);
                if (remain == 0ull) break;
                round_count = std::min(reverse_rounds_per_launch, remain);
            }
            uint64_t lane_chunk_offset = 0ull;
            while (lane_chunk_offset < reverse_lane_count &&
                !g_profanity_recovery_found_any.load(std::memory_order_relaxed)) {
                const uint64_t lane_chunk_count = std::min<uint64_t>(
                    reverse_lane_chunk_limit,
                    reverse_lane_count - lane_chunk_offset);
                const uint64_t lane_chunk_start = reverse_lane_start + lane_chunk_offset;
                const uint64_t lane_chunk_state_index_start = lane_chunk_offset;
                const unsigned int recovery_blocks = profanity_blocks_for_lane_count(lane_chunk_count);
                const uint64_t launch_count = profanity_mul_saturate_u64(lane_chunk_count, round_count);
                const bool use_recovery_walk_state =
                    recovery_stateful_window &&
                    p_profanity_recovery_walk_state_valid &&
                    p_profanity_recovery_walk_state_target_hex == profanity_target_hex &&
                    p_profanity_recovery_walk_state_lane_start == lane_chunk_start &&
                    p_profanity_recovery_walk_state_lane_count == lane_chunk_count &&
                    p_profanity_recovery_walk_state_next_round == round;
                const bool store_recovery_walk_state =
                    recovery_stateful_window &&
                    round_count == reverse_rounds_per_launch &&
                    round_count == 1024ull;

                metalStatus = metalMemset(p_profanity_recovery_hit_count, 0, sizeof(uint32_t));
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalMemset recovery hit count failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                const char* reverse_worker_name = "workerProfanityRecoveryReverse_ge";
                if (recovery_xc_only) {
                    reverse_worker_name = "workerProfanityRecoveryReverse_xc_ge";
                    metal_launch("workerProfanityRecoveryReverse_xc_ge", MetalGridSize(recovery_blocks), MetalGridSize(BLOCK_THREADS), _dev_precomp, pitch, p_profanity_recovery_target_ge, lane_chunk_start, lane_chunk_count, lane_chunk_state_index_start, round, round_count, p_profanity_recovery_hits, p_profanity_recovery_hit_count, max_hits, p_profanity_walk_state, p_profanity_walk_state_capacity, use_recovery_walk_state, store_recovery_walk_state);
                }
                else if (recovery_xuc_only) {
                    reverse_worker_name = "workerProfanityRecoveryReverse_xuc_ge";
                    metal_launch("workerProfanityRecoveryReverse_xuc_ge", MetalGridSize(recovery_blocks), MetalGridSize(BLOCK_THREADS), _dev_precomp, pitch, p_profanity_recovery_target_ge, lane_chunk_start, lane_chunk_count, lane_chunk_state_index_start, round, round_count, p_profanity_recovery_hits, p_profanity_recovery_hit_count, max_hits, p_profanity_walk_state, p_profanity_walk_state_capacity, use_recovery_walk_state, store_recovery_walk_state);
                }
                else if (recovery_xh_only) {
                    reverse_worker_name = "workerProfanityRecoveryReverse_xh_ge";
                    metal_launch("workerProfanityRecoveryReverse_xh_ge", MetalGridSize(recovery_blocks), MetalGridSize(BLOCK_THREADS), _dev_precomp, pitch, p_profanity_recovery_target_ge, lane_chunk_start, lane_chunk_count, lane_chunk_state_index_start, round, round_count, p_profanity_recovery_hits, p_profanity_recovery_hit_count, max_hits, p_profanity_walk_state, p_profanity_walk_state_capacity, use_recovery_walk_state, store_recovery_walk_state);
                }
                else {
                    metal_launch("workerProfanityRecoveryReverse_ge", MetalGridSize(recovery_blocks), MetalGridSize(BLOCK_THREADS), _dev_precomp, pitch, p_profanity_recovery_target_ge, lane_chunk_start, lane_chunk_count, lane_chunk_state_index_start, round, round_count, p_profanity_recovery_hits, p_profanity_recovery_hit_count, max_hits, p_profanity_walk_state, p_profanity_walk_state_capacity, use_recovery_walk_state, store_recovery_walk_state);
                }
                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "%s launch failed: %s\n", reverse_worker_name, metalGetErrorString(metalStatus));
                    goto Error;
                }
                metalStatus = metalDeviceSynchronize();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "%s sync failed: %s\n", reverse_worker_name, metalGetErrorString(metalStatus));
                    goto Error;
                }
                if (store_recovery_walk_state && round <= (std::numeric_limits<uint64_t>::max() - round_count)) {
                    p_profanity_recovery_walk_state_valid = true;
                    p_profanity_recovery_walk_state_target_hex = profanity_target_hex;
                    p_profanity_recovery_walk_state_lane_start = lane_chunk_start;
                    p_profanity_recovery_walk_state_lane_count = lane_chunk_count;
                    p_profanity_recovery_walk_state_next_round = round + round_count;
                }
                else if (recovery_stateful_window) {
                    p_profanity_recovery_walk_state_valid = false;
                }

                uint32_t hit_count_host = 0;
                metalStatus = metalMemcpy(&hit_count_host, p_profanity_recovery_hit_count, sizeof(uint32_t), metalMemcpyDeviceToHost);
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalMemcpy recovery hit count failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
                const uint32_t resolve_hits = std::min<uint32_t>(hit_count_host, max_hits);
                uint32_t cpu_confirmed_hits = 0u;
                uint32_t seed_resolve_hits = 0u;
                uint32_t seed_resolve_launches = 0u;
                if (resolve_hits > 0u) {
                    const auto hit_processing_begin = std::chrono::steady_clock::now();
                    std::vector<ProfanityRecoveryHit> host_hits(resolve_hits);
                    metalStatus = metalMemcpy(host_hits.data(), p_profanity_recovery_hits,
                        static_cast<size_t>(resolve_hits) * sizeof(ProfanityRecoveryHit),
                        metalMemcpyDeviceToHost);
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemcpy recovery hits failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    uint32_t confirmed_hits = 0u;
                    if (recovery_use_xx) {
                        for (uint32_t i = 0; i < resolve_hits; ++i) {
                            if (!profanity_cpu_xx_confirm_hit(host_hits[i], recovery_use_xx)) {
                                continue;
                            }
                            if (confirmed_hits != i) {
                                host_hits[confirmed_hits] = host_hits[i];
                            }
                            ++confirmed_hits;
                        }
                        cpu_confirmed_hits = confirmed_hits;
                        if (resolve_hits > confirmed_hits) {
                            false_positive.fetch_add(
                                static_cast<uint64_t>(resolve_hits - confirmed_hits),
                                std::memory_order_relaxed);
                        }
                    }
                    else {
                        confirmed_hits = resolve_hits;
                        cpu_confirmed_hits = 0u;
                    }
                    if (confirmed_hits == 0u) {
                        speed_counter_pause_since(hit_processing_begin);
                        goto SkipResolve;
                    }
                    seed_resolve_hits = confirmed_hits;
                    if (confirmed_hits != resolve_hits) {
                        metalStatus = metalMemcpy(p_profanity_recovery_hits, host_hits.data(),
                            static_cast<size_t>(confirmed_hits) * sizeof(ProfanityRecoveryHit),
                            metalMemcpyHostToDevice);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalMemcpy confirmed recovery hits failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                    }

                    const unsigned int seed_resolve_blocks = profanity_seed_resolve_blocks();
                    bool seed_resolve_found = false;
                    uint32_t seed_resolve_found_count = 0u;
                    uint32_t seed = start_seed;
                    metalStatus = metalMemset(p_profanity_count, 0, sizeof(unsigned long long));
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalMemset profanity recovery count before resolve failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }
                    while (true) {
                        const uint64_t seed_remain = static_cast<uint64_t>(end_seed) - static_cast<uint64_t>(seed) + 1ull;
                        uint64_t seed_chunk64 = 1ull;
                        if (resolve_lane_count > 0ull && resolve_lane_count < seed_pair_candidates_per_launch) {
                            seed_chunk64 = std::max<uint64_t>(1ull, seed_pair_candidates_per_launch / resolve_lane_count);
                        }
                        seed_chunk64 = std::min<uint64_t>(seed_chunk64, seed_remain);
                        const uint32_t seed_launch_count = static_cast<uint32_t>(std::min<uint64_t>(seed_chunk64, UINT32_MAX));
                        const uint64_t total_pairs = (static_cast<uint64_t>(seed_launch_count) + static_cast<uint64_t>(THREAD_STEPS) - 1ull) /
                            static_cast<uint64_t>(THREAD_STEPS);
                        uint64_t pair_start = 0ull;
                        while (pair_start < total_pairs) {
                            const uint64_t pair_count = std::min<uint64_t>(seed_group_candidates_per_launch, total_pairs - pair_start);
                            const uint64_t seeds_done_before = pair_start * static_cast<uint64_t>(THREAD_STEPS);
                            const uint64_t seeds_remaining_in_launch = (seeds_done_before >= static_cast<uint64_t>(seed_launch_count))
                                ? 0ull
                                : (static_cast<uint64_t>(seed_launch_count) - seeds_done_before);
                            const uint64_t seed_count_this_kernel = std::min<uint64_t>(
                                seeds_remaining_in_launch,
                                profanity_mul_saturate_u64(pair_count, static_cast<uint64_t>(THREAD_STEPS)));
                            const unsigned int seed_resolve_launch_blocks = std::min<unsigned int>(
                                seed_resolve_blocks,
                                profanity_blocks_for_lane_count(pair_count));
                            const auto seed_resolve_begin = std::chrono::steady_clock::now();
                            metal_launch("workerProfanitySeedResolveBatch", MetalGridSize(seed_resolve_launch_blocks), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, seed, seed_launch_count, resolve_lane_start, resolve_lane_count, pair_start, pair_count, p_profanity_recovery_target_pubkey, target_len, p_profanity_recovery_hits, confirmed_hits);
                            ++seed_resolve_launches;
                            metalStatus = metalGetLastError();
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "workerProfanitySeedResolveBatch launch failed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }
                            metalStatus = metalDeviceSynchronize();
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "workerProfanitySeedResolveBatch sync failed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }
                            const auto seed_resolve_end = std::chrono::steady_clock::now();
                            const auto seed_resolve_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
                                seed_resolve_end - seed_resolve_begin).count();
                            counterProfanitySeedResolve += seed_count_this_kernel;
                            if (seed_resolve_ns > 0) {
                                counterProfanitySeedResolveNs += static_cast<uint64_t>(seed_resolve_ns);
                            }

                            unsigned long long recovery_count_host = 0ull;
                            metalStatus = metalMemcpy(&recovery_count_host, p_profanity_count, sizeof(recovery_count_host), metalMemcpyDeviceToHost);
                            if (metalStatus != metalSuccess) {
                                fprintf(stderr, "metalMemcpy profanity recovery count failed: %s\n", metalGetErrorString(metalStatus));
                                goto Error;
                            }
                            if (recovery_count_host > 0ull) {
                                const size_t recovery_save_count = static_cast<size_t>(std::min<unsigned long long>(
                                    recovery_count_host,
                                    static_cast<unsigned long long>(max_hits)));
                                std::vector<ProfanityVerifiedResult> host_results(recovery_save_count);
                                metalStatus = metalMemcpy(host_results.data(), p_profanity_results,
                                    recovery_save_count * sizeof(ProfanityVerifiedResult),
                                    metalMemcpyDeviceToHost);
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalMemcpy profanity recovery results failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }
                                if (!host_results.empty()) {
                                    g_profanity_recovery_found_round.store(host_results.front().round, std::memory_order_relaxed);
                                }
                                g_profanity_recovery_found_any.store(true, std::memory_order_relaxed);
                                SaveResultProfanityRecovery(OUT_FILE, Founds, save, host_results.data(),
                                    static_cast<unsigned long long>(recovery_save_count));
                                flush_all_async_save_queues();
                                seed_resolve_found = true;
                                seed_resolve_found_count = static_cast<uint32_t>(std::min<size_t>(
                                    recovery_save_count,
                                    static_cast<size_t>(UINT32_MAX)));
                                metalStatus = metalMemset(p_profanity_count, 0, sizeof(unsigned long long));
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalMemset profanity recovery count after save failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }
                            }
                            if (seed_resolve_found) {
                                break;
                            }

                            if (pair_count == 0ull || pair_count >= (total_pairs - pair_start)) {
                                break;
                            }
                            pair_start += pair_count;
                        }

                        if (seed_resolve_found || seed_launch_count == seed_remain || seed == end_seed) {
                            break;
                        }
                        seed += seed_launch_count;
                    }
                    if (confirmed_hits > 0u) {
                        const uint32_t resolved_hits = std::min<uint32_t>(confirmed_hits, seed_resolve_found_count);
                        const uint32_t unresolved_hits = confirmed_hits - resolved_hits;
                        if (unresolved_hits > 0u) {
                            false_positive.fetch_add(
                                static_cast<uint64_t>(unresolved_hits),
                                std::memory_order_relaxed);
                        }
                    }
                    speed_counter_pause_since(hit_processing_begin);
                    if (seed_resolve_found) {
                        goto Finish;
                    }
                }

SkipResolve:
                counterTotal += launch_count;
                const long long tStatus = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - beginCountStatus).count();
                if (tStatus > 2500) {
                    char log_name[64];
                    const int recovery_gpu_id = (profanity_partition_gpu_id >= 0) ? profanity_partition_gpu_id : DEVICE_NR;
                    if (profanity_lane_partition_active) {
                        snprintf(log_name, sizeof(log_name), "Profanity_recovery_log_gpu%d.txt", recovery_gpu_id);
                    }
                    else {
                        snprintf(log_name, sizeof(log_name), "Profanity_recovery_log.txt");
                    }
                    FILE* fp = open_runtime_log(log_name, "wb");
                    if (fp) {
                        fprintf(fp, "gpu_id=%d filter=%s round_offset=%016llx round_count=%016llx gpu_hits=%u cpu_xx_hits=%u seed_resolve_hits=%u seed_resolve_launches=%u seed_range=%08x..%08x lane_start=%016llx lane_count=%016llx lane_total_start=%016llx lane_total_count=%016llx resolve_lane_count=%016llx\n",
                            recovery_gpu_id,
                            profanity_recovery_filter_label(recovery_xc_only, recovery_xuc_only, recovery_xh_only),
                            static_cast<unsigned long long>(round),
                            static_cast<unsigned long long>(round_count),
                            hit_count_host, cpu_confirmed_hits,
                            seed_resolve_hits, seed_resolve_launches, start_seed, end_seed,
                            static_cast<unsigned long long>(lane_chunk_start),
                            static_cast<unsigned long long>(lane_chunk_count),
                            static_cast<unsigned long long>(reverse_lane_start),
                            static_cast<unsigned long long>(reverse_lane_count),
                            static_cast<unsigned long long>(resolve_lane_count));
                        fclose(fp);
                    }
                    beginCountStatus = std::chrono::steady_clock::now();
                }

                lane_chunk_offset += lane_chunk_count;
            }

            if (!profanity_recovery_round_queue_active) {
                const uint64_t step = round_count;
                if (step == 0ull || round > (std::numeric_limits<uint64_t>::max() - step)) {
                    break;
                }
                round += step;
            }
        }
    }

Finish:
Error:
    if (buffIsResult) metalFree(buffIsResult);
    if (buffDeviceResult) metalFree(buffDeviceResult);
    return metalStatus;
}

metalError_t processMetalProfanityRecoveryFile()
{
    std::vector<ProfanityRecoveryFileEntry> entries;
    std::string file_err;
    if (!load_profanity_recovery_file(profanity_recovery_file_path, entries, file_err)) {
        fprintf(stderr, "[!] Error: %s [!]\n", file_err.c_str());
        return metalErrorInvalidValue;
    }

    const uint64_t rounds_per_pubkey = (use_n_count && n_number > 0ull) ? n_number : (1ull << 14);
    if (rounds_per_pubkey == 0ull) {
        fprintf(stderr, "[!] Error: -profanity -recovery -i FILE requires -n > 0 [!]\n");
        return metalErrorInvalidValue;
    }

    size_t active_count = count_active_profanity_recovery_entries(entries);
    if (active_count == 0u) {
        printf("[!] PROFANITY recovery file has no active pubkeys; all entries are marked found or skipped [!]\n");
        return metalSuccess;
    }

    const std::string saved_target = profanity_target_hex;
    const uint64_t saved_offset = profanity_offset;
    const bool saved_offset_explicit = profanity_offset_explicit;
    const bool saved_window_active = g_profanity_recovery_window_override_active.load(std::memory_order_relaxed);
    const uint64_t saved_window_end = g_profanity_recovery_window_end.load(std::memory_order_relaxed);

    metalError_t status = metalSuccess;
    while (isRun) {
        bool processed_any = false;
        active_count = count_active_profanity_recovery_entries(entries);
        if (active_count == 0u) {
            printf("[!] PROFANITY recovery file complete: all pubkeys are marked found [!]\n");
            break;
        }

        for (size_t i = 0u; i < entries.size() && isRun; ++i) {
            auto& entry = entries[i];
            if (entry.passthrough || entry.found) {
                continue;
            }
            processed_any = true;

            const uint64_t begin = entry.offset;
            const uint64_t span = rounds_per_pubkey - 1ull;
            const uint64_t end = (span > (std::numeric_limits<uint64_t>::max() - begin))
                ? std::numeric_limits<uint64_t>::max()
                : (begin + span);

            profanity_target_hex = entry.pubkey_hex;
            profanity_offset = begin;
            profanity_offset_explicit = true;
            g_profanity_recovery_found_any.store(false, std::memory_order_relaxed);
            g_profanity_recovery_found_round.store(begin, std::memory_order_relaxed);
            g_profanity_recovery_window_end.store(end, std::memory_order_relaxed);
            g_profanity_recovery_window_override_active.store(true, std::memory_order_relaxed);

            printf("[!] PROFANITY recovery file entry %zu/%zu: offset=%016llx end=%016llx pubkey=%.*s... [!]\n",
                i + 1u,
                entries.size(),
                static_cast<unsigned long long>(begin),
                static_cast<unsigned long long>(end),
                18,
                entry.pubkey_hex.c_str());

            status = processMetalProfanityRecovery();
            g_profanity_recovery_window_override_active.store(false, std::memory_order_relaxed);
            if (status != metalSuccess) {
                goto Done;
            }

            if (g_profanity_recovery_found_any.load(std::memory_order_relaxed)) {
                entry.offset = g_profanity_recovery_found_round.load(std::memory_order_relaxed);
                entry.found = true;
                printf("[!] PROFANITY recovery file entry %zu marked found at round %016llx [!]\n",
                    i + 1u,
                    static_cast<unsigned long long>(entry.offset));
            }
            else {
                if (!isRun) {
                    goto Done;
                }
                entry.offset = (end == std::numeric_limits<uint64_t>::max())
                    ? std::numeric_limits<uint64_t>::max()
                    : (end + 1ull);
            }

            if (!save_profanity_recovery_file(profanity_recovery_file_path, entries, file_err)) {
                fprintf(stderr, "[!] Error: %s [!]\n", file_err.c_str());
                status = metalErrorInvalidValue;
                goto Done;
            }

            active_count = count_active_profanity_recovery_entries(entries);
            if (entry.found && active_count == 0u) {
                printf("[!] PROFANITY recovery file complete: all pubkeys are marked found [!]\n");
                goto Done;
            }
        }

        if (!processed_any) {
            printf("[!] PROFANITY recovery file has no active pubkeys; all entries are marked found or skipped [!]\n");
            break;
        }
    }

Done:
    profanity_target_hex = saved_target;
    profanity_offset = saved_offset;
    profanity_offset_explicit = saved_offset_explicit;
    g_profanity_recovery_window_end.store(saved_window_end, std::memory_order_relaxed);
    g_profanity_recovery_window_override_active.store(saved_window_active, std::memory_order_relaxed);
    return status;
}

// processMetalPRIVSeq: runs the Metal workflow for privseq.
metalError_t processMetalPRIVSeq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalPRIVSeq();
        });
    }
    if (BLOCK_THREADS > 256u) {
        fprintf(stderr, "[!] Vanity mode: -t %u is unstable here; forcing -t 256 for correct performance accounting [!]\n", BLOCK_THREADS);
        BLOCK_THREADS = 256u;
    }
    metalError_t metalStatus = metalSuccess;
    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    THREAD_STEPS_PUB_H = chunks * keys_per_chunk;
    if (THREAD_STEPS_PUB_H % 1024 != 0) {
        THREAD_STEPS_PUB_H = ((THREAD_STEPS_PUB_H + 1023) / 1024) * 1024;
        fprintf(stderr, "[!] Vanity: THREAD_STEPS_PUB aligned to %d (multiple of 1024)\n", THREAD_STEPS_PUB_H);
    }
    uint64_t outputSizeB_T = 0;
    const uint64_t resultBufferEntries = 1ull;
    std::chrono::steady_clock::time_point beginCountHashrate;
    std::chrono::steady_clock::time_point beginCountStatus;
    uint64_t counter = 0;
    uint8_t* start_pvk_dev = nullptr;
    bool use_vanity_buf = false;
    bool has_other = false;
    bool vanity_seq_c_persistent = false;
    uint64_t vanity_persistent_shift = 0;
    bool vanity_buf_ready = false;
    uint64_t* d_startx = nullptr;
    uint64_t* d_starty = nullptr;
    const bool has_secp_targets = has_secp_output_targets();
    while (true) {
        outputSizeB_T = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS_PUB_H);
        metalStatus = allocate_result_buffers_device(resultBufferEntries, &buffIsResult, &buffDeviceResult);
        if (metalStatus == metalSuccess) {
            break;
        }
        if (metalStatus != metalErrorMemoryAllocation || BLOCK_NUMBER <= 1u) {
            fprintf(stderr, "allocate_result_buffers failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        BLOCK_NUMBER = std::max(1u, BLOCK_NUMBER / 2u);
        workSize = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
        fprintf(stderr, "[!] GPU %d: reduce blocks to %u due to result-buffer OOM [!]\n", DEVICE_NR, BLOCK_NUMBER);
    }

    beginCountHashrate = std::chrono::steady_clock::now();
    beginCountStatus = std::chrono::steady_clock::now();

    metalStatus = metalMalloc((void**)&start_pvk_dev, 32);
    if (metalStatus != metalSuccess || start_pvk_dev == nullptr) {
        fprintf(stderr, "metalMalloc start_pvk_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(start_pvk_dev, start_pvk_point, 32, metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy start_pvk_point failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    if (has_secp_targets) {
        metal_launch("compute_P0_H_kernel", 1, 1, start_pvk_dev, effective_seq_kernel_step(), _dev_precomp, pitch, 1);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "compute_P0_H_kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metal_vanity_set_step_increment(effective_seq_kernel_step(), _dev_precomp, pitch);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metal_vanity_set_step_increment failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
    }

    use_vanity_buf = has_secp_targets && (THREAD_STEPS_PUB_H % 1024 == 0) && (BLOCK_THREADS <= 256u);
    if (has_secp_targets && (THREAD_STEPS_PUB_H % 1024 == 0) && !use_vanity_buf) {
        fprintf(stderr, "[!] Vanity precompute disabled for BLOCK_THREADS=%u (>256); fallback to direct walk start compute [!]\n", BLOCK_THREADS);
    }
    has_other = Solana || Ton || Ton_all || Dot || Aptos || Sui || Xrp || Exodus || Iota || Ada || Icp || Fil || Xtz;
    vanity_seq_c_persistent = use_vanity_buf &&
        !has_other && !Ethereum && Compressed && !Uncompressed && !Segwit && !P2wsh && !Taproot && !Xpoint && !Endomorphism;
    if (vanity_seq_c_persistent) {
        if (outputSizeB_T > static_cast<uint64_t>(THREAD_STEPS_PUB_H)) {
            vanity_persistent_shift = outputSizeB_T - static_cast<uint64_t>(THREAD_STEPS_PUB_H);
        }
        metalStatus = metal_vanity_set_persistent_shift(vanity_persistent_shift);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metal_vanity_set_persistent_shift failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
    }
    if (use_vanity_buf) {
        size_t startBufSize = static_cast<size_t>(BLOCK_NUMBER) * BLOCK_THREADS * 4 * sizeof(uint64_t);
        metalStatus = metalMalloc((void**)&d_startx, startBufSize);
        if (metalStatus == metalSuccess) metalStatus = metalMalloc((void**)&d_starty, startBufSize);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMalloc vanity start buffers failed: %s\n", metalGetErrorString(metalStatus));
            if (d_startx) metalFree(d_startx);
            d_startx = nullptr;
            d_starty = nullptr;
            use_vanity_buf = false;
        }
    }

    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp256_host(start_pvk_point, end_pvk_point);
        if (result > 0)
        {
            break;
        }
        write_seq_checkpoint_log('+', start_pvk_point, 32, effective_seq_kernel_step());
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        if (use_vanity_buf && d_startx != nullptr && d_starty != nullptr &&
            (!vanity_seq_c_persistent || !vanity_buf_ready)) {
            metal_launch("precompute_vanity_starts_kernel", MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), d_startx, d_starty, THREAD_STEPS_PUB_H);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "precompute_vanity_starts_kernel failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            vanity_buf_ready = true;
        }
        uint8_t launch_kind = PRIV_LAUNCH_SEQ128;
        metalStatus = launch_workerPRIV_seq(keys_per_chunk, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, 1, start_pvk_dev, effective_seq_kernel_step(), THREAD_STEPS_PUB_H,
            use_vanity_buf ? d_startx : nullptr, use_vanity_buf ? d_starty : nullptr, &launch_kind);


        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }
        counterTotal += outputSizeB_T * endo_multiplier_for_launch_kind(launch_kind);
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
            {
                FILE* fp = open_runtime_log("PrivSeq_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, start_pvk_point, 32, (size_t)32);
                }

                if (fp) fclose(fp);
            }
            write_seq_checkpoint_log('+', start_pvk_point, 32, effective_seq_kernel_step());


        }
        //check result 2
        bool has_result2 = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result2);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result2) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }


        uint64_t valLE[4];
        uint64_t valBE[4];

        array32_to_4x64_le(start_pvk_point, valLE);

        add128to256_host(valLE, outputSizeB_T, step, valBE);

        array4x64_le_to32(valBE, start_pvk_point);

        metal_launch("advance_P0_kernel", 1, 1, outputSizeB_T);

        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }

        if (vanity_seq_c_persistent && vanity_buf_ready && d_startx != nullptr && d_starty != nullptr && vanity_persistent_shift != 0u) {
            metalStatus = metal_vanity_apply_persistent_shift(d_startx, d_starty, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metal_vanity_apply_persistent_shift failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }

    }

    {
        bool has_result = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }
    }
Error:
    metalFree(buffIsResult);
    metalFree(buffDeviceResult);
    if (d_startx) metalFree(d_startx);
    if (d_starty) metalFree(d_starty);
    metalFree(start_pvk_dev);
    return metalStatus;
}

// processMetalPRIVSeqBack: runs the Metal workflow for privseq back.
metalError_t processMetalPRIVSeqBack()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalPRIVSeqBack();
        });
    }
    if (BLOCK_THREADS > 256u) {
        fprintf(stderr, "[!] Vanity mode: -t %u is unstable here; forcing -t 256 for correct performance accounting [!]\n", BLOCK_THREADS);
        BLOCK_THREADS = 256u;
    }
    metalError_t metalStatus = metalSuccess;
    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    THREAD_STEPS_PUB_H = chunks * keys_per_chunk;
    if (THREAD_STEPS_PUB_H % 1024 != 0) {
        THREAD_STEPS_PUB_H = ((THREAD_STEPS_PUB_H + 1023) / 1024) * 1024;
        fprintf(stderr, "[!] Vanity: THREAD_STEPS_PUB aligned to %d (multiple of 1024)\n", THREAD_STEPS_PUB_H);
    }
    uint64_t outputSizeB_T = 0;
    const uint64_t resultBufferEntries = 1ull;
    std::chrono::steady_clock::time_point beginCountHashrate;
    std::chrono::steady_clock::time_point beginCountStatus;
    uint64_t counter = 0;
    uint8_t* start_pvk_dev = nullptr;
    bool use_vanity_buf = false;
    uint64_t* d_startx = nullptr;
    uint64_t* d_starty = nullptr;
    while (true) {
        outputSizeB_T = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS_PUB_H);
        metalStatus = allocate_result_buffers_device(resultBufferEntries, &buffIsResult, &buffDeviceResult);
        if (metalStatus == metalSuccess) {
            break;
        }
        if (metalStatus != metalErrorMemoryAllocation || BLOCK_NUMBER <= 1u) {
            fprintf(stderr, "allocate_result_buffers failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        BLOCK_NUMBER = std::max(1u, BLOCK_NUMBER / 2u);
        workSize = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
        fprintf(stderr, "[!] GPU %d: reduce blocks to %u due to result-buffer OOM [!]\n", DEVICE_NR, BLOCK_NUMBER);
    }

    beginCountHashrate = std::chrono::steady_clock::now();
    beginCountStatus = std::chrono::steady_clock::now();
    use_vanity_buf = (THREAD_STEPS_PUB_H % 1024 == 0) && (BLOCK_THREADS <= 256u);
    if ((THREAD_STEPS_PUB_H % 1024 == 0) && !use_vanity_buf) {
        fprintf(stderr, "[!] Vanity precompute disabled for BLOCK_THREADS=%u (>256); fallback to direct walk start compute [!]\n", BLOCK_THREADS);
    }
    if (use_vanity_buf) {
        size_t startBufSize = static_cast<size_t>(BLOCK_NUMBER) * BLOCK_THREADS * 4 * sizeof(uint64_t);
        metalStatus = metalMalloc((void**)&d_startx, startBufSize);
        if (metalStatus == metalSuccess) metalStatus = metalMalloc((void**)&d_starty, startBufSize);
        if (metalStatus != metalSuccess) {
            if (d_startx) metalFree(d_startx);
            d_startx = nullptr;
            d_starty = nullptr;
            use_vanity_buf = false;
        }
    }

    metalStatus = metalMalloc((void**)&start_pvk_dev, 32);
    if (metalStatus != metalSuccess || start_pvk_dev == nullptr) {
        fprintf(stderr, "metalMalloc start_pvk_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metalMemcpyAsync(start_pvk_dev, start_pvk_point, 32, metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    metalStatus = metal_vanity_set_step_increment(effective_seq_kernel_step(), _dev_precomp, pitch);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metal_vanity_set_step_increment failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp256_host(start_pvk_point, end_pvk_point);
        if (result < 0)
        {
            break;
        }

        write_seq_checkpoint_log('-', start_pvk_point, 32, effective_seq_kernel_step());
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("compute_P0_H_kernel", 1, 1, start_pvk_dev, effective_seq_kernel_step(), _dev_precomp, pitch, -1);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "compute_P0_H_kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        if (use_vanity_buf && d_startx != nullptr && d_starty != nullptr) {
            metal_launch("precompute_vanity_starts_kernel", MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), d_startx, d_starty, THREAD_STEPS_PUB_H);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "precompute_vanity_starts_kernel failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        uint8_t launch_kind = PRIV_LAUNCH_SEQ128;
        metalStatus = launch_workerPRIV_seq(keys_per_chunk, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, -1, start_pvk_dev, effective_seq_kernel_step(), THREAD_STEPS_PUB_H,
            use_vanity_buf ? d_startx : nullptr, use_vanity_buf ? d_starty : nullptr, &launch_kind);

        metalStatus = metalGetLastError();

        counterTotal += outputSizeB_T * endo_multiplier_for_launch_kind(launch_kind);

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
            {
                FILE* fp = open_runtime_log("PrivSeqBack_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, start_pvk_point, 32, (size_t)32, true);
                }

                if (fp) fclose(fp);
            }
            write_seq_checkpoint_log('-', start_pvk_point, 32, effective_seq_kernel_step());

        }
        //check result 2
        bool has_result = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }


        uint64_t valLE[4];
        uint64_t valBE[4];

        array32_to_4x64_le(start_pvk_point, valLE);

        sub128from256_host(valLE, outputSizeB_T, step, valBE);

        array4x64_le_to32(valBE, start_pvk_point);

        metal_launch("advance_P0_kernel", 1, 1, outputSizeB_T);

        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }

    }

    {
        bool has_result = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }
    }
Error:
    if (d_startx) metalFree(d_startx);
    if (d_starty) metalFree(d_starty);
    metalFree(start_pvk_dev);
    return metalStatus;
}

metalError_t processMetalPRIVSeqStep()
{
    metalError_t metalStatus = metalSuccess;
    if (!seq_priv_use_step_schedule) {
        return processMetalPRIVSeq();
    }

    uint8_t start_pvk_anchor[32] = { 0 };
    memcpy(start_pvk_anchor, start_pvk_point, sizeof(start_pvk_anchor));

    for (;;) {
        memcpy(start_pvk_point, start_pvk_anchor, sizeof(start_pvk_anchor));
        seq_priv_status_step.store(step, std::memory_order_relaxed);
        seq_priv_status_plus_step.store(seq_priv_plus_step, std::memory_order_relaxed);

        metalStatus = processMetalPRIVSeq();
        if (metalStatus != metalSuccess) {
            return metalStatus;
        }

        step += seq_priv_plus_step;
        if (seq_priv_has_end_step && (step >= seq_priv_end_step)) {
            step = seq_priv_start_step;
            if (seq_priv_has_add_plus_step) {
                seq_priv_plus_step += seq_priv_add_plus_step;
            }
        }
        seq_priv_status_step.store(step, std::memory_order_relaxed);
        seq_priv_status_plus_step.store(seq_priv_plus_step, std::memory_order_relaxed);
    }
    return metalStatus;
}

metalError_t processMetalPRIVSeqBackStep()
{
    metalError_t metalStatus = metalSuccess;
    if (!seq_priv_use_step_schedule) {
        return processMetalPRIVSeqBack();
    }

    uint8_t start_pvk_anchor[32] = { 0 };
    memcpy(start_pvk_anchor, start_pvk_point, sizeof(start_pvk_anchor));

    for (;;) {
        memcpy(start_pvk_point, start_pvk_anchor, sizeof(start_pvk_anchor));
        seq_priv_status_step.store(step, std::memory_order_relaxed);
        seq_priv_status_plus_step.store(seq_priv_plus_step, std::memory_order_relaxed);

        metalStatus = processMetalPRIVSeqBack();
        if (metalStatus != metalSuccess) {
            return metalStatus;
        }

        step += seq_priv_plus_step;
        if (seq_priv_has_end_step && (step >= seq_priv_end_step)) {
            step = seq_priv_start_step;
            if (seq_priv_has_add_plus_step) {
                seq_priv_plus_step += seq_priv_add_plus_step;
            }
        }
        seq_priv_status_step.store(step, std::memory_order_relaxed);
        seq_priv_status_plus_step.store(seq_priv_plus_step, std::memory_order_relaxed);
    }
    return metalStatus;
}

// processMetalPRIVSeqBoth: runs the Metal workflow for privseq both.
metalError_t processMetalPRIVSeqBoth()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalPRIVSeqBoth();
        });
    }
    if (BLOCK_THREADS > 256u) {
        fprintf(stderr, "[!] Vanity mode: -t %u is unstable here; forcing -t 256 for correct performance accounting [!]\n", BLOCK_THREADS);
        BLOCK_THREADS = 256u;
    }
    metalError_t metalStatus = metalSuccess;
    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    THREAD_STEPS_PUB_H = chunks * keys_per_chunk;
    if (THREAD_STEPS_PUB_H % 1024 != 0) {
        THREAD_STEPS_PUB_H = ((THREAD_STEPS_PUB_H + 1023) / 1024) * 1024;
        fprintf(stderr, "[!] Vanity: THREAD_STEPS_PUB aligned to %d (multiple of 1024)\n", THREAD_STEPS_PUB_H);
    }
    uint64_t outputSizeB_T = 0;
    const uint64_t resultBufferEntries = 1ull;
    std::chrono::steady_clock::time_point beginCountHashrate;
    std::chrono::steady_clock::time_point beginCountStatus;
    uint64_t counter = 0;
    uint8_t* plus_pvk_dev = nullptr;
    uint8_t* minus_pvk_dev = nullptr;
    bool use_vanity_buf = false;
    uint64_t* d_startx = nullptr;
    uint64_t* d_starty = nullptr;
    uint8_t plus_pvk_point[32] = { 0 };
    uint8_t minus_pvk_point[32] = { 0 };
    uint64_t plus_size = 0;
    uint64_t minus_size = 0;
    uint64_t local_n = 0;
    bool range_active = true;
    while (true) {
        outputSizeB_T = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS_PUB_H);
        metalStatus = allocate_result_buffers_device(resultBufferEntries, &buffIsResult, &buffDeviceResult);
        if (metalStatus == metalSuccess) {
            break;
        }
        if (metalStatus != metalErrorMemoryAllocation || BLOCK_NUMBER <= 1u) {
            fprintf(stderr, "allocate_result_buffers failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        BLOCK_NUMBER = std::max(1u, BLOCK_NUMBER / 2u);
        workSize = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
        fprintf(stderr, "[!] GPU %d: reduce blocks to %u due to result-buffer OOM [!]\n", DEVICE_NR, BLOCK_NUMBER);
    }

    beginCountHashrate = std::chrono::steady_clock::now();
    beginCountStatus = std::chrono::steady_clock::now();
    use_vanity_buf = (THREAD_STEPS_PUB_H % 1024 == 0) && (BLOCK_THREADS <= 256u);
    if ((THREAD_STEPS_PUB_H % 1024 == 0) && !use_vanity_buf) {
        fprintf(stderr, "[!] Vanity precompute disabled for BLOCK_THREADS=%u (>256); fallback to direct walk start compute [!]\n", BLOCK_THREADS);
    }
    if (use_vanity_buf) {
        size_t startBufSize = static_cast<size_t>(BLOCK_NUMBER) * BLOCK_THREADS * 4 * sizeof(uint64_t);
        metalStatus = metalMalloc((void**)&d_startx, startBufSize);
        if (metalStatus == metalSuccess) metalStatus = metalMalloc((void**)&d_starty, startBufSize);
        if (metalStatus != metalSuccess) {
            if (d_startx) metalFree(d_startx);
            d_startx = nullptr;
            d_starty = nullptr;
            use_vanity_buf = false;
        }
    }

    init_seq_both_points(plus_pvk_point, minus_pvk_point, start_pvk_point, end_pvk_point, 32);

    metalStatus = metalMalloc((void**)&plus_pvk_dev, 32);
    if (metalStatus != metalSuccess || plus_pvk_dev == nullptr) {
        fprintf(stderr, "metalMalloc plus_pvk_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc((void**)&minus_pvk_dev, 32);
    if (metalStatus != metalSuccess || minus_pvk_dev == nullptr) {
        fprintf(stderr, "metalMalloc minus_pvk_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    uint64_t valLE[4];
    uint64_t valBE[4];

    range_active = seq_both_round_active(plus_pvk_point, minus_pvk_point, start_pvk_point, end_pvk_point, 32);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        local_n += outputSizeB_T;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        write_seq_checkpoint_log_both(plus_pvk_point, minus_pvk_point, 32, effective_seq_kernel_step());


        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_pvk_point, 32, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("compute_P0_H_kernel", 1, 1, plus_pvk_dev, effective_seq_kernel_step(), _dev_precomp, pitch, 1);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "compute_P0_H_kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metal_vanity_set_step_increment(effective_seq_kernel_step(), _dev_precomp, pitch);
        if (metalStatus != metalSuccess) { fprintf(stderr, "metal_vanity_set_step_increment failed\n"); goto Error; }
        metalStatus = metalDeviceSynchronize();

        if (use_vanity_buf && d_startx != nullptr && d_starty != nullptr) {
            metal_launch("precompute_vanity_starts_kernel", MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), d_startx, d_starty, THREAD_STEPS_PUB_H);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "precompute_vanity_starts_kernel + failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        uint8_t launch_kind_plus = PRIV_LAUNCH_SEQ128;
        metalStatus = launch_workerPRIV_seq(keys_per_chunk, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, 1, plus_pvk_dev, effective_seq_kernel_step(), THREAD_STEPS_PUB_H,
            use_vanity_buf ? d_startx : nullptr, use_vanity_buf ? d_starty : nullptr, &launch_kind_plus);

        metalStatus = metalGetLastError();
        counterTotal += outputSizeB_T * endo_multiplier_for_launch_kind(launch_kind_plus);

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metalDeviceSynchronize();

         bool has_result_plus = false;
         metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result_plus);
         if (metalStatus != metalSuccess) {
             fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
             goto Error;
         }
         if (has_result_plus) {
             SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
         }

         metal_launch("compute_P0_H_kernel", 1, 1, minus_pvk_dev, effective_seq_kernel_step(), _dev_precomp, pitch, -1);
         metalStatus = metalGetLastError();
         if (metalStatus != metalSuccess) {
             fprintf(stderr, "compute_P0_H_kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
             goto Error;
         }
         metalStatus = metal_vanity_set_step_increment(effective_seq_kernel_step(), _dev_precomp, pitch);
         if (metalStatus != metalSuccess) { fprintf(stderr, "metal_vanity_set_step_increment failed\n"); goto Error; }
         metalStatus = metalDeviceSynchronize();

         if (use_vanity_buf && d_startx != nullptr && d_starty != nullptr) {
             metal_launch("precompute_vanity_starts_kernel", MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), d_startx, d_starty, THREAD_STEPS_PUB_H);
             metalStatus = metalGetLastError();
             if (metalStatus != metalSuccess) {
                 fprintf(stderr, "precompute_vanity_starts_kernel - failed: %s\n", metalGetErrorString(metalStatus));
                 goto Error;
             }
         }
         uint8_t launch_kind_minus = PRIV_LAUNCH_SEQ128;
         metalStatus = launch_workerPRIV_seq(keys_per_chunk, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, -1, minus_pvk_dev, effective_seq_kernel_step(), THREAD_STEPS_PUB_H,
             use_vanity_buf ? d_startx : nullptr, use_vanity_buf ? d_starty : nullptr, &launch_kind_minus);

        metalStatus = metalGetLastError();
        counterTotal += outputSizeB_T * endo_multiplier_for_launch_kind(launch_kind_minus);

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }


        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();

            {
                FILE* fp = open_runtime_log("PrivSeqBoth_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, plus_pvk_point, 32, (size_t)plus_size);
                    write_hex_last(fp, minus_pvk_point, 32, (size_t)minus_size, true);
                }

                if (fp) fclose(fp);
            }
            write_seq_checkpoint_log_both(plus_pvk_point, minus_pvk_point, 32, effective_seq_kernel_step());
        }
        //check result 2
        bool has_result_minus = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result_minus);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result_minus) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }


        array32_to_4x64_le(plus_pvk_point, valLE);
        add128to256_host(valLE, outputSizeB_T, step, valBE);
        array4x64_le_to32(valBE, plus_pvk_point);

        plus_size = sizeBE_64(valBE, 4);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array32_to_4x64_le(minus_pvk_point, valLE);
        sub128from256_host(valLE, outputSizeB_T, step, valBE);
        array4x64_le_to32(valBE, minus_pvk_point);

        minus_size = sizeBE_64(valBE, 4);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }
        range_active = seq_both_round_active(plus_pvk_point, minus_pvk_point, start_pvk_point, end_pvk_point, 32);

    }

    {
        bool has_result = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }
    }
Error:
    if (d_startx) metalFree(d_startx);
    if (d_starty) metalFree(d_starty);
    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

