    THREAD_STEPS_PUB_H = chunks * keys_per_chunk;
    if (THREAD_STEPS_PUB_H % 1024 != 0) {
        THREAD_STEPS_PUB_H = ((THREAD_STEPS_PUB_H + 1023) / 1024) * 1024;
        fprintf(stderr, "[!] Vanity: THREAD_STEPS_PUB aligned to %d (multiple of 1024)\n", THREAD_STEPS_PUB_H);
