    bool use_vanity_buf = false;
    uint64_t* d_startx = nullptr;
    uint64_t* d_starty = nullptr;
    uint8_t start_pvk_point_local[32] = { 0 };
    uint8_t* plus_pvk_dev = nullptr;
    uint8_t* minus_pvk_dev = nullptr;
    uint8_t plus_pvk_point[32] = { 0 };
    uint8_t minus_pvk_point[32] = { 0 };
    while (true) {
        outputSizeB_T = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS_PUB_H);
        metalStatus = allocate_result_buffers_device(resultBufferEntries, &buffIsResult, &buffDeviceResult);
        if (metalStatus == metalSuccess) {
            break;
        }
        if (metalStatus != metalErrorMemoryAllocation || BLOCK_NUMBER <= 1u) {
            fprintf(stderr, "allocate_result_buffers failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        BLOCK_NUMBER = std::max(1u, BLOCK_NUMBER / 2u);
        workSize = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
        fprintf(stderr, "[!] GPU %d: reduce blocks to %u due to result-buffer OOM [!]\n", DEVICE_NR, BLOCK_NUMBER);
    }

    beginCountHashrate = std::chrono::steady_clock::now();
    beginCountStatus = std::chrono::steady_clock::now();
    use_vanity_buf = (THREAD_STEPS_PUB_H % 1024 == 0) && (BLOCK_THREADS <= 256u);
    if ((THREAD_STEPS_PUB_H % 1024 == 0) && !use_vanity_buf) {
        fprintf(stderr, "[!] Vanity precompute disabled for BLOCK_THREADS=%u (>256); fallback to direct walk start compute [!]\n", BLOCK_THREADS);
    }
    if (use_vanity_buf) {
        size_t startBufSize = static_cast<size_t>(BLOCK_NUMBER) * BLOCK_THREADS * 4 * sizeof(uint64_t);
        metalStatus = metalMalloc((void**)&d_startx, startBufSize);
        if (metalStatus == metalSuccess) metalStatus = metalMalloc((void**)&d_starty, startBufSize);
        if (metalStatus != metalSuccess) {
            if (d_startx) metalFree(d_startx);
            d_startx = nullptr;
            d_starty = nullptr;
            use_vanity_buf = false;
        }
    }

    if (seqMode)
    {
        random_bytes_seq(start_pvk_point, end_pvk_point, start_pvk_point_local, 32);

    }
    else
    {
        random_bytes(start_pvk_point_local, 32, entropy_len);
    }

    memcpy(&plus_pvk_point[0], &start_pvk_point_local[0], 32);
    memcpy(&minus_pvk_point[0], &start_pvk_point_local[0], 32);

    metalStatus = metalMalloc((void**)&plus_pvk_dev, 32);
    if (metalStatus != metalSuccess || plus_pvk_dev == nullptr) {
        fprintf(stderr, "metalMalloc plus_pvk_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMalloc((void**)&minus_pvk_dev, 32);
    if (metalStatus != metalSuccess || minus_pvk_dev == nullptr) {
        fprintf(stderr, "metalMalloc minus_pvk_dev failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    uint64_t valLE[4];
    uint64_t valBE[4];



    while (true) {

        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        // plus direction: initialize walk once, then advance by chunks
        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus point failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("compute_P0_H_kernel", 1, 1, plus_pvk_dev, step, _dev_precomp, pitch, 1);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "compute_P0_H_kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metal_vanity_set_step_increment(step, _dev_precomp, pitch);
        if (metalStatus != metalSuccess) { fprintf(stderr, "metal_vanity_set_step_increment failed\n"); goto Error; }
        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after compute +!\n", metalStatus);
            goto Error;
        }

        for (uint64_t local_n = 0; local_n <= n_number; local_n += outputSizeB_T) {
            if (use_vanity_buf && d_startx != nullptr && d_starty != nullptr) {
                metal_launch("precompute_vanity_starts_kernel", MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), d_startx, d_starty, THREAD_STEPS_PUB_H);
                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "precompute_vanity_starts_kernel + failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
            }
            uint8_t launch_kind_plus = PRIV_LAUNCH_SEQ128;
        metalStatus = launch_workerPRIV_seq(keys_per_chunk, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, 1, plus_pvk_dev, step, THREAD_STEPS_PUB_H,
                use_vanity_buf ? d_startx : nullptr, use_vanity_buf ? d_starty : nullptr, &launch_kind_plus);

            metalStatus = metalGetLastError();
            counterTotal += outputSizeB_T * endo_multiplier_for_launch_kind(launch_kind_plus);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after + launch!\n", metalStatus);
                goto Error;
            }

            bool has_result = false;
            metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            if (has_result) {
                SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
            }

            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();
            }

            array32_to_4x64_le(plus_pvk_point, valLE);
            add128to256_host(valLE, outputSizeB_T, step, valBE);
            array4x64_le_to32(valBE, plus_pvk_point);

            metal_launch("advance_P0_kernel", 1, 1, outputSizeB_T);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "advance_P0_kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after advance +!\n", metalStatus);
                goto Error;
            }
        }

        // minus direction: initialize walk once, then advance by chunks
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy minus point failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("compute_P0_H_kernel", 1, 1, minus_pvk_dev, step, _dev_precomp, pitch, -1);
        metalStatus = metalGetLastError();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "compute_P0_H_kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        metalStatus = metal_vanity_set_step_increment(step, _dev_precomp, pitch);
        if (metalStatus != metalSuccess) { fprintf(stderr, "metal_vanity_set_step_increment failed\n"); goto Error; }
        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after compute -!\n", metalStatus);
            goto Error;
        }

        for (uint64_t local_n = 0; local_n <= n_number; local_n += outputSizeB_T) {
            if (use_vanity_buf && d_startx != nullptr && d_starty != nullptr) {
                metal_launch("precompute_vanity_starts_kernel", MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), d_startx, d_starty, THREAD_STEPS_PUB_H);
                metalStatus = metalGetLastError();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "precompute_vanity_starts_kernel - failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }
            }
            uint8_t launch_kind_minus = PRIV_LAUNCH_SEQ128;
         metalStatus = launch_workerPRIV_seq(keys_per_chunk, MetalGridSize(BLOCK_NUMBER), MetalGridSize(BLOCK_THREADS), buffIsResult, buffDeviceResult, _dev_precomp, pitch, -1, minus_pvk_dev, step, THREAD_STEPS_PUB_H,
                use_vanity_buf ? d_startx : nullptr, use_vanity_buf ? d_starty : nullptr, &launch_kind_minus);

            metalStatus = metalGetLastError();
            counterTotal += outputSizeB_T * endo_multiplier_for_launch_kind(launch_kind_minus);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }

            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after - launch!\n", metalStatus);
                goto Error;
            }

            bool has_result = false;
            metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            if (has_result) {
                SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
            }

            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();
            }

            array32_to_4x64_le(minus_pvk_point, valLE);
            sub128from256_host(valLE, outputSizeB_T, step, valBE);
            array4x64_le_to32(valBE, minus_pvk_point);

            metal_launch("advance_P0_kernel", 1, 1, outputSizeB_T);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "advance_P0_kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after advance -!\n", metalStatus);
                goto Error;
            }
        }

        if (seqMode)
        {
            random_bytes_seq(start_pvk_point, end_pvk_point, start_pvk_point_local, 32);

        }
        else
        {
            random_bytes(start_pvk_point_local, 32, entropy_len);
        }

        memcpy(&plus_pvk_point[0], &start_pvk_point_local[0], 32);
        memcpy(&minus_pvk_point[0], &start_pvk_point_local[0], 32);
    }

    {
        bool has_result = false;
        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "fetch result flag failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        if (has_result) {
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
        }
    }
Error:
    if (d_startx) metalFree(d_startx);
    if (d_starty) metalFree(d_starty);
    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalPRIVSeq_old: runs the Metal workflow for privseq old.
metalError_t processMetalPRIVSeq_old()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalPRIVSeq_old();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;


    metalMalloc((void**)&start_pvk_dev, 32);



    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp256_host(start_pvk_point, end_pvk_point);
        if (result > 0)
        {
            break;
        }
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }


        metal_launch("workerPRIV_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, 1, start_pvk_dev);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
            {
                FILE* fp = open_runtime_log("PrivSeq_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, start_pvk_point, 32, (size_t)32);
                }

                if (fp) fclose(fp);
            }


        }
        //check result 2
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);

        }


        uint64_t valLE[4];
        uint64_t valBE[4];

        array32_to_4x64_le(start_pvk_point, valLE);

        add128to256_host(valLE, outputSizeB_T, step, valBE);

        array4x64_le_to32(valBE, start_pvk_point);

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

