// processMetalPRIVSeqBoth_old: runs the Metal workflow for privseq both old.
metalError_t processMetalPRIVSeqBoth_old()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalPRIVSeqBoth_old();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_pvk_point[32] = { 0 };
    uint8_t minus_pvk_point[32] = { 0 };

    init_seq_both_points(plus_pvk_point, minus_pvk_point, start_pvk_point, end_pvk_point, 32);

    metalMalloc((void**)&plus_pvk_dev, 32);
    metalMalloc((void**)&minus_pvk_dev, 32);

    uint64_t valLE[4];
    uint64_t valBE[4];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;
    bool range_active = seq_both_round_active(plus_pvk_point, minus_pvk_point, start_pvk_point, end_pvk_point, 32);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        local_n += outputSizeB_T;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_pvk_point, 32, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_pvk_point, 32, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        //+
        metal_launch("workerPRIV_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, 1, plus_pvk_dev);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();

        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);

        }
        metal_launch("workerPRIV_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, 0, minus_pvk_dev);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }


        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();

            {
                FILE* fp = open_runtime_log("PrivSeqBoth_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, plus_pvk_point, 32, (size_t)plus_size);
                    write_hex_last(fp, minus_pvk_point, 32, (size_t)minus_size, true);
                }

                if (fp) fclose(fp);
            }
        }
        //check result 2
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);

        }


        array32_to_4x64_le(plus_pvk_point, valLE);
        add128to256_host(valLE, outputSizeB_T, step, valBE);
        array4x64_le_to32(valBE, plus_pvk_point);

        plus_size = sizeBE_64(valBE, 4);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array32_to_4x64_le(minus_pvk_point, valLE);
        sub128from256_host(valLE, outputSizeB_T, step, valBE);
        array4x64_le_to32(valBE, minus_pvk_point);

        minus_size = sizeBE_64(valBE, 4);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }
        range_active = seq_both_round_active(plus_pvk_point, minus_pvk_point, start_pvk_point, end_pvk_point, 32);

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultPRIV(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

