static metalError_t processMetalPRIVTransformFile(
    const vector<string>& mnemonicFiles,
    const char* mode_name,
    metalError_t (*process_stream)(std::istream&))
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);

        metalError_t st;
        if (use_combos)
        {
            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });

            st = process_stream(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = process_stream(stream);
        }

        if (st != metalSuccess) {
            std::cerr << mode_name << " failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalPRIVFileSWAP: runs the Metal workflow for privfile swap.
metalError_t processMetalPRIVFileSWAP(const vector<string>& mnemonicFiles)
{
    return processMetalPRIVTransformFile(mnemonicFiles, "processMetalPRIVSWAP", processMetalPRIVSWAP);
}

