// processMetalPRIVGen: runs the Metal workflow for privgen.
metalError_t processMetalPRIVGen()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalPRIVGen();
        });
    }
    metalError_t metalStatus = metalSuccess;

    uint64_t outputSizeB_T = 0;
    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    std::chrono::steady_clock::time_point beginCountHashrate;
    std::chrono::steady_clock::time_point beginCountStatus;
    uint64_t counter = 0;
    while (true) {
        outputSizeB_T = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
        metalStatus = allocate_result_buffers_device(outputSizeB_T, &buffIsResult, &buffDeviceResult);
        if (metalStatus == metalSuccess) {
            break;
        }
        if (metalStatus == metalErrorMemoryAllocation && BLOCK_NUMBER > 1u) {
            const unsigned int newBlocks = std::max(1u, BLOCK_NUMBER / 2u);
            if (newBlocks == BLOCK_NUMBER) {
                goto Error;
            }
            fprintf(stderr, "[!] GPU %d: reduce blocks to %u due to result-buffer OOM [!]\n", DEVICE_NR, newBlocks);
            BLOCK_NUMBER = newBlocks;
            workSize = static_cast<uint64_t>(BLOCK_NUMBER) * static_cast<uint64_t>(BLOCK_THREADS) * static_cast<uint64_t>(THREAD_STEPS);
            continue;
        }
        fprintf(stderr, "result buffer allocation failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }


    beginCountHashrate = std::chrono::steady_clock::now();
    beginCountStatus = std::chrono::steady_clock::now();
    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed; seed_local <= end_seed;) {

        uint64_t remaining = end_seed - seed_local + 1;
        uint64_t seed_count = (remaining < outputSizeB_T) ? remaining : outputSizeB_T;

        current_seed = seed_local;
        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFULL);

                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                        metal_launch("workerPRIV_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);
                        metalStatus = metalGetLastError();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                            cout << "mode: " << mode_h << "gen: " << gen_h << "seed: " << seed_local << "\n";
                            goto Error;
                        }


                        counterTotal += seed_count * ((Rounds * 2) + 1);




                        metalStatus = metalDeviceSynchronize();
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                            cout << "mode: " << mode_h << "gen: " << gen_h << "seed: " << seed_local << "\n";
                            goto Error;
                        }
                        //show status
                        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                        if (tHash > 2500) {
                            counter = 0;
                            beginCountHashrate = std::chrono::steady_clock::now();
                        }
                        //check result 2
                        bool has_result = false;
                        metalStatus = fetch_and_clear_result_flag(buffIsResult, has_result);
                        if (metalStatus != metalSuccess) {
                            fprintf(stderr, "result-flag fetch failed: %s\n", metalGetErrorString(metalStatus));
                            goto Error;
                        }
                        if (has_result) {
                            SaveResultPRIVGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                        }
                    }
                }
            }
        }
        if (isRandom)
        {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else
        {
            seed_local += seed_count;
        }

    }
Error:
    if (buffIsResult) {
        metalFree(buffIsResult);
    }
    if (buffDeviceResult) {
        metalFree(buffDeviceResult);
    }
    return metalStatus;
}

// processMetalPRIVGen64: runs the Metal workflow for privgen 64.
metalError_t processMetalPRIVGen64()
{
