                        current_mode = mode_h;


                        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                        metal_launch("workerPRIV_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, seed_local, seed_count, true, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);
