                        metal_launch("workerPRIVSwap_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, Rounds);
