//Brain modes

metalError_t processMetalBrain(std::istream& stream)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalBrain(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint32_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS_BRAIN;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);
    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 2048);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 2048);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);
    const bool expands_brain_candidates =
        g_brain_input_configuration.expands_candidates();
    brain_input::Expander brain_expander(g_brain_input_configuration);
    std::string brain_expand_error;
    const brain_input::Expander::ReadBase read_brain_base =
        [&](std::string& line) -> bool {
            return read_trimmed_line_known_lock(
                stream, line, 512, input_requires_shared_lock);
        };
    auto read_brain_candidate = [&](std::string& line) -> bool {
        if (!expands_brain_candidates) {
            return read_brain_base(line);
        }
        return brain_expander.next(
            read_brain_base, line, brain_expand_error);
    };

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t* _devIndexes1 = nullptr;
    uint32_t* _devIndexes2 = nullptr;
    uint32_t* _devIter = nullptr;
    char* _devLines1 = nullptr;
    char* _devLines2 = nullptr;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";
    uint32_t iteration_size = Iterations.size();
    metalStatus = metalMalloc((void**)&_devIter, Iterations.size() * sizeof(uint32_t));
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMalloc _devIter failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }
    metalStatus = metalMemcpyAsync(_devIter, Iterations.data(), Iterations.size() * sizeof(uint32_t), metalMemcpyHostToDevice);
    if (metalStatus != metalSuccess) {
        fprintf(stderr, "metalMemcpy Iterations.data() failed: %s\n", metalGetErrorString(metalStatus));
        goto Error;
    }

    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_brain_candidate(buffer))
        {
            if (buffer.length() == 0) {
                continue;
            }
            append_brain_line_to_batch(buffer, combined1, indexes1, nr1Last, IS_HEX);
            nr1++;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        if (!brain_expand_error.empty()) {
            fprintf(stderr, "[!] Error: %s [!]\n", brain_expand_error.c_str());
            metalStatus = metalErrorInvalidValue;
            goto Error;
        }
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes1, indexes1.data(), indexes1.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
        }

        //sync kernel 2
        if (nr2 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
            }
            const std::uint64_t completed =
                static_cast<std::uint64_t>(nr2) *
                ((static_cast<std::uint64_t>(Rounds) * 2u) + 1u) *
                Iterations.size();
            counter += completed;
            counterTotal += completed;
        }

        //launch kernel 1
        if (nr1 > 0) {
            metal_launch("workerBrain", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _devLines1, _devIndexes1, nr1, _dev_precomp, pitch, Rounds, brainMode, _devIter, iteration_size);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }

        STATUS = nr2Last;
        //read file 1
        combined2.clear();
        indexes2.clear();
        nr2 = 0;
        data2ready = false;
        while (read_brain_candidate(buffer))
        {
            if (buffer.length() == 0) {
                continue;
            }
            append_brain_line_to_batch(buffer, combined2, indexes2, nr2Last, IS_HEX);
            nr2++;
            if (nr2 < outputSizeB_T) {
                continue;
            }
            data2ready = true;
            break;
        }
        if (!brain_expand_error.empty()) {
            fprintf(stderr, "[!] Error: %s [!]\n", brain_expand_error.c_str());
            metalStatus = metalErrorInvalidValue;
            goto Error;
        }
        if (!data2ready) {
            isData = false;
        }
        if (nr2 > 0) {
            //copy data 2 -> device
            metalStatus = copy_to_device_grow((void**)&_devLines2, combined2.data(), combined2.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes2, indexes2.data(), indexes2.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //sync kernel 1
        if (nr1 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 1
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
            }
            const std::uint64_t completed =
                static_cast<std::uint64_t>(nr1) *
                ((static_cast<std::uint64_t>(Rounds) * 2u) + 1u) *
                Iterations.size();
            counter += completed;
            counterTotal += completed;
        }
        //launch kernel 2
        if (nr2 > 0) {
            metal_launch("workerBrain", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _devLines2, _devIndexes2, nr2, _dev_precomp, pitch, Rounds, brainMode, _devIter, iteration_size);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        STATUS = nr1Last;
    }
    metalDeviceSynchronize();
    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(_devIndexes1);
    metalFree(_devIndexes2);
    metalFree(_devIter);
    metalFree(_devLines1);
    metalFree(_devLines2);
    return metalStatus;
}

// processMetalBrainFile: runs the Metal workflow for brain file.
metalError_t processMetalBrainFile(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);



        metalError_t st;

        if (use_combos)
        {


            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });


            st = processMetalBrain(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = processMetalBrain(stream);
        }


        if (st != metalSuccess) {
            std::cerr << "processMetalBrain failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalBrainSeq: runs the Metal workflow for brain seq.
metalError_t processMetalBrainSeq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBrainSeq();
        });
    }
    metalError_t metalStatus;

    uint32_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS_BRAIN;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;

    metalMalloc((void**)&start_pvk_dev, 256);

    uint64_t plus_size = 0;

    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        int result = cmp_host(start_brain_point, end_brain_point, 256);
        if (result > 0)
        {
            break;
        }
        metalStatus = metalMemcpyAsync(start_pvk_dev, start_brain_point, 256, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        for (size_t num = 0; num < Iterations.size(); ++num)
        {

            uint32_t ITERATION_HOST = Iterations[num];
            metal_launch("workerBrain_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, 1, start_pvk_dev, min_len, ITERATION_HOST);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T * ((Rounds *2)+ 1);
            counterTotal += outputSizeB_T * ((Rounds *2)+ 1);

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }



            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }

            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();
                {
                    FILE* fp = open_runtime_log("BrainSeq_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, start_brain_point, 256, (size_t)plus_size);
                    }

                    if (fp) fclose(fp);
                }

            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);

            }
        }

        uint64_t valLE[32];
        uint64_t valBE[32];

        array256_to_32x64_le(start_brain_point, valLE);

        add64to2048_host(valLE, outputSizeB_T * step, valBE);

        array32x64_le_to256(valBE, start_brain_point);

        plus_size = sizeBE_64(valBE, 32);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }




    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

