    uint32_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS_BRAIN;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_brain_point[256] = { 0 };
    uint8_t minus_brain_point[256] = { 0 };

    init_seq_both_points(plus_brain_point, minus_brain_point, start_brain_point, end_brain_point, 256);

    metalMalloc((void**)&plus_pvk_dev, 256);
    metalMalloc((void**)&minus_pvk_dev, 256);

    uint64_t valLE[32];
    uint64_t valBE[32];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;

    bool range_active = seq_both_round_active(plus_brain_point, minus_brain_point, start_brain_point, end_brain_point, 256);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        local_n += outputSizeB_T;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        write_seq_checkpoint_log_both(plus_brain_point, minus_brain_point, 256, effective_seq_kernel_step());

        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_brain_point, 256, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_brain_point, 256, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        for (size_t num = 0; num < Iterations.size(); ++num)
        {

            uint32_t ITERATION_HOST = Iterations[num];

            //+
            metal_launch("workerBrain_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, 1, plus_pvk_dev, min_len, ITERATION_HOST);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T * ((Rounds *2)+ 1);
            counterTotal += outputSizeB_T * ((Rounds *2)+ 1);

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }


            metalStatus = metalDeviceSynchronize();

            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);

            }
            metal_launch("workerBrain_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, 0, minus_pvk_dev, min_len, ITERATION_HOST);
            metalStatus = metalGetLastError();
            counter += outputSizeB_T * ((Rounds *2)+ 1);
            counterTotal += outputSizeB_T * ((Rounds *2)+ 1);

            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }


            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }

            //show status
            long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
            if (tHash > 2500) {
                counter = 0;
                beginCountHashrate = std::chrono::steady_clock::now();

                {
                    FILE* fp = open_runtime_log("BrainSeqBoth_log.txt", "wb");
                    if (fp)
                    {
                        write_hex_last(fp, plus_brain_point, 256, (size_t)plus_size);
                        write_hex_last(fp, minus_brain_point, 256, (size_t)minus_size, true);
                    }

                    if (fp) fclose(fp);
                }
                write_seq_checkpoint_log_both(plus_brain_point, minus_brain_point, 256, effective_seq_kernel_step());
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);
                SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);

            }
        }



        array256_to_32x64_le(plus_brain_point, valLE);
        add64to2048_host(valLE, outputSizeB_T * step, valBE);
        array32x64_le_to256(valBE, plus_brain_point);

        plus_size = sizeBE_64(valBE, 32);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array256_to_32x64_le(minus_brain_point, valLE);
        sub64from2048_host(valLE, outputSizeB_T * step, valBE);
        array32x64_le_to256(valBE, minus_brain_point);

        minus_size = sizeBE_64(valBE, 32);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }
        range_active = seq_both_round_active(plus_brain_point, minus_brain_point, start_brain_point, end_brain_point, 256);


    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

