                metal_launch("workerBrain_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, 1, plus_pvk_dev, min_len, ITERATION_HOST);
                metalStatus = metalGetLastError();
                counter += outputSizeB_T * ((Rounds *2)+ 1);
                counterTotal += outputSizeB_T * ((Rounds *2)+ 1);

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
