                }


                metalStatus = metalDeviceSynchronize();

                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);

                }
                metal_launch("workerBrain_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, 0, minus_pvk_dev, min_len, ITERATION_HOST);
                metalStatus = metalGetLastError();
                counter += outputSizeB_T * ((Rounds *2)+ 1);
                counterTotal += outputSizeB_T * ((Rounds *2)+ 1);

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }


                metalStatus = metalDeviceSynchronize();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                    goto Error;
                }

                //show status
                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                if (tHash > 2500) {
                    counter = 0;
                    beginCountHashrate = std::chrono::steady_clock::now();

                }
                //check result 2
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);

                }
            }



            array256_to_32x64_le(plus_brain_point, valLE);
            add64to2048_host(valLE, outputSizeB_T * step, valBE);
            array32x64_le_to256(valBE, plus_brain_point);

            array256_to_32x64_le(minus_brain_point, valLE);
            add64to2048_host(valLE, outputSizeB_T * step, valBE);
            array32x64_le_to256(valBE, minus_brain_point);


        }
        if (seqMode)
        {
            random_bytes_seq(start_brain_point, end_brain_point, start_pvk_point_local, 256);
        }
        else
        {
            random_bytes(start_pvk_point_local, 256, entropy_len);
        }
        memcpy(&plus_brain_point[0], &start_pvk_point_local[0], 256);
        memcpy(&minus_brain_point[0], &start_pvk_point_local[0], 256);


    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultBrain(OUT_FILE, Founds, save, Derivations_list);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalBrainGen: runs the Metal workflow for brain gen.
metalError_t processMetalBrainGen()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBrainGen();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS_BRAIN;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;
    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed; seed_local <= end_seed;) {

        uint64_t remaining = end_seed - seed_local + 1;
        uint64_t seed_count = (remaining < outputSizeB_T) ? remaining : outputSizeB_T;

        current_seed = seed_local;
        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFULL);

                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        for (size_t suz = 0; suz < Sizes.size(); ++suz)
                        {
                            int custom_size = Sizes[suz];



                            for (size_t num = 0; num < Iterations.size(); ++num)
                            {

                                uint32_t ITERATION_HOST = Iterations[num];
                                std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                                metal_launch("workerBrain_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, ITERATION_HOST, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1);


                                metalStatus = metalGetLastError();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }


                                counterTotal += seed_count;




                                metalStatus = metalDeviceSynchronize();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                                    goto Error;
                                }
                                //show status
                                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                if (tHash > 2500) {
                                    counter = 0;
                                    beginCountHashrate = std::chrono::steady_clock::now();
                                }
                                //check result 2
                                if (read_result_flag_host(buffIsResult)) {
                                    clear_result_flag_host(buffIsResult);
                                    SaveResultBrainGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                }

                            }
                        }

                    }
                }

            }
        }

        if (isRandom)
        {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else
        {
            seed_local += seed_count;
        }
    }
Error:

    return metalStatus;
}

// processMetalBrainGen64: runs the Metal workflow for brain gen 64.
metalError_t processMetalBrainGen64()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalBrainGen64();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS * THREAD_STEPS_BRAIN;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;
    for (uint64_t seed_local = isRandom ? random_seed64_inclusive(start_seed64, end_seed64) : start_seed64; seed_local <= end_seed64;) {

        uint64_t remaining = end_seed64 - seed_local;
        uint64_t seed_count = (remaining < outputSizeB_T) ? (remaining + 1ull) : outputSizeB_T;

        current_seed = seed_local;
        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";


                ofs << std::hex << std::setw(16) << std::setfill('0') << seed_local << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];
            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev64", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];
                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(true, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        for (size_t suz = 0; suz < Sizes.size(); ++suz)
                        {
                            int custom_size = Sizes[suz];



                            for (size_t num = 0; num < Iterations.size(); ++num)
                            {

                                uint32_t ITERATION_HOST = Iterations[num];
                                std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


                                metal_launch("workerBrain_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, Rounds, brainMode, ITERATION_HOST, seed_local, seed_count, true, PrngBytes[entr_len], mode_h - 1, gen_h - 1);


                                metalStatus = metalGetLastError();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }


                                counterTotal += seed_count;




                                metalStatus = metalDeviceSynchronize();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                                    goto Error;
                                }
                                //show status
                                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                if (tHash > 2500) {
                                    counter = 0;
                                    beginCountHashrate = std::chrono::steady_clock::now();
                                }
                                //check result 2
                                if (read_result_flag_host(buffIsResult)) {
                                    clear_result_flag_host(buffIsResult);
                                    SaveResultBrainGen(OUT_FILE, Founds, save, Derivations_list, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                }

                            }
                        }

                    }
                }

            }
        }

        if (isRandom)
        {
            seed_local = random_seed64_inclusive(start_seed64, end_seed64);
        }
        else
        {
            if (seed_local > (std::numeric_limits<uint64_t>::max() - seed_count)) {
                break;
            }
            seed_local += seed_count;
        }
    }
Error:

    return metalStatus;
}

//Old Electrum modes

//Old mnemonic

metalError_t processMetalOldFile(const vector<string>& mnemonicFiles)
{
    metalError_t lastStatus = metalSuccess;

    for (size_t i = 0; i < mnemonicFiles.size(); ++i) {
        const std::string& fname = mnemonicFiles[i];

        std::ifstream stream(fname.c_str(), std::ios::binary);
        tune_ifstream_buffer(stream);
        if (!stream) {
            std::cout << "Error: Failed to open file '" << fname << "'\n";
            lastStatus = metalErrorInvalidValue;
            continue;
        }
        print_opened_input_file(fname);



        metalError_t st;

        if (use_combos)
        {


            g_pipe.reset();
            g_pipe_in.clear();
            g_pipe_out.clear();

            std::thread generatorThread([&] {
                EmitCombinations(stream, combos, combo_space, combo_rep);
                g_pipe.close();
                });


            st = processMetalOld(g_pipe_in);

            g_pipe.close();

            generatorThread.join();
        }
        else
        {
            st = processMetalOld(stream);
        }


        if (st != metalSuccess) {
            std::cerr << "processMetalOld failed for '" << fname
                << "': " << metalGetErrorString(st) << "\n";
            lastStatus = st;
        }

        stream.close();

        if (deleteFile) {
            delFile(fname.c_str());
        }
    }

    return lastStatus;
}

// processMetalOld: runs the Metal workflow for old.
metalError_t processMetalOld(std::istream& stream)
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_stream_mode_multi_gpu(__func__, stream, [](std::istream& shared_stream) -> metalError_t {
            return processMetalOld(shared_stream);
        });
    }
    metalError_t metalStatus;

    uint32_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::string buffer;
    std::string combined1;
    std::vector<uint32_t> indexes1;
    std::string combined2;
    std::vector<uint32_t> indexes2;
    reserve_batch_buffers(combined1, indexes1, outputSizeB_T, 1024);
    reserve_batch_buffers(combined2, indexes2, outputSizeB_T, 1024);
    const bool input_requires_shared_lock = stream_requires_shared_read_lock(stream);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    bool isData = true;
    bool data1ready = false;
    bool data2ready = false;
    uint32_t nr1 = 0;
    uint32_t nr2 = 0;
    string nr1Last = "";
    string nr2Last = "";

    uint32_t* _devIndexes1;
    uint32_t* _devIndexes2;
    char* _devLines1;
    char* _devLines2;

    _devIndexes1 = nullptr;
    _devIndexes2 = nullptr;
    _devLines1 = nullptr;
    _devLines2 = nullptr;

    string not_valid_buffer;
    string valid_buffer;
    if (!is_multi_gpu_active()) {
        std::ios_base::sync_with_stdio(false);
        std::cin.tie(nullptr);
    }
    while (isData) {
        //read file 1
        combined1.clear();
        indexes1.clear();
        nr1 = 0;
        data1ready = false;
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            uint32_t seed[256 / 4];
            uint16_t seed_count;
            try {
                if (!mnemonic_phrase_to_seed(buffer.data(), (uint32_t*)seed, &seed_count, nullptr)) {
                    counterNotValid++;
                    if (NOT_VALID) {
                        not_valid_buffer += buffer;
                        not_valid_buffer.push_back('\n');
                    }
                    continue;
                }
                else
                {
                    if (NOT_VALID)
                    {
                        valid_buffer += buffer;
                        valid_buffer.push_back('\n');
                    }
                }
            }
            catch (const std::exception& e) {
                counterNotValid++;
                if (NOT_VALID) {
                    buffer += " error: ";
                    buffer += e.what();
                    buffer.push_back('\n');
                    not_valid_buffer += buffer;
                }
                continue;
            }
            for (int i = 0; i < seed_count; i++)
            {
                seed[i] = SWAP256_host(seed[i]);
            }
            buffer.clear();
            buffer.resize(seed_count * 4);
            memcpy(&buffer[0], seed, seed_count * 4);
            combined1.append(buffer.data(), buffer.size());
            counterTotal++;
            indexes1.emplace_back(combined1.size());
            nr1++;
            if (nr1 < outputSizeB_T) {
                continue;
            }
            data1ready = true;
            break;
        }
        if (!data1ready) {
            isData = false;
        }

        //copy data 1 -> device
        if (nr1 > 0) {
            metalStatus = copy_to_device_grow((void**)&_devLines1, combined1.data(), combined1.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes1, indexes1.data(), indexes1.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes1.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();
        }

        ////sync kernel 2
        if (nr2 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 2
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);

                SaveResultOld(OUT_FILE, Founds, save);


            }
        }

        //launch kernel 1
        if (nr1 > 0) {
            metal_launch("workerOld", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _devLines1, _devIndexes1, nr1, _dev_precomp, pitch, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }

        counter += nr2;
        //read file 1
        combined2.clear();
        indexes2.clear();
        nr2 = 0;
        data2ready = false;
        while (read_trimmed_line_known_lock(stream, buffer, 512, input_requires_shared_lock))
        {
            uint32_t seed[256 / 4];
            uint16_t seed_count;
            try {
                if (!mnemonic_phrase_to_seed(buffer.data(), (uint32_t*)seed, &seed_count, nullptr)) {
                    counterNotValid++;
                    if (NOT_VALID) {
                        not_valid_buffer += buffer;
                        not_valid_buffer.push_back('\n');
                    }
                    continue;
                }
                else
                {
                    if (NOT_VALID)
                    {
                        valid_buffer += buffer;
                        valid_buffer.push_back('\n');
                    }
                }
            }
            catch (const std::exception& e) {
                counterNotValid++;
                if (NOT_VALID) {
                    buffer += " error: ";
                    buffer += e.what();
                    buffer.push_back('\n');
                    not_valid_buffer += buffer;
                }
                continue;
            }

            for (int i = 0; i < seed_count; i++)
            {
                seed[i] = SWAP256_host(seed[i]);
            }
            buffer.clear();
            buffer.resize(seed_count * 4);
            memcpy(&buffer[0], seed, seed_count * 4);
            combined2.append(buffer.data(), buffer.size());
            counterTotal++;

            indexes2.emplace_back(combined2.size());
            nr2++;
            if (nr2 < outputSizeB_T) {
                continue;
            }
            data2ready = true;
            break;
        }
        if (!data2ready) {
            isData = false;
        }
        if (nr2 > 0) {
            //copy data 2 -> device
            metalStatus = copy_to_device_grow((void**)&_devLines2, combined2.data(), combined2.size());
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy combined2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            metalStatus = copy_to_device_grow((void**)&_devIndexes2, indexes2.data(), indexes2.size() * sizeof(uint32_t));
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy indexes2.data() failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
        }
        //sync kernel 1
        if (nr1 > 0) {
            metalStatus = metalDeviceSynchronize();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                goto Error;
            }
            //check result 1
            if (read_result_flag_host(buffIsResult)) {
                clear_result_flag_host(buffIsResult);

                SaveResultOld(OUT_FILE, Founds, save);


            }
        }
        //launch kernel 2
        if (nr2 > 0) {
            metal_launch("workerOld", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _devLines2, _devIndexes2, nr2, _dev_precomp, pitch, Rounds);
            metalStatus = metalGetLastError();
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }


        }
        counter += nr1;
        if (NOT_VALID)
        {
            FILE* file = fopen("NotValid.txt", "a");
            if (file) {
                fprintf(file, "%s", not_valid_buffer.c_str());
                fclose(file);
                not_valid_buffer.clear();
            }
            FILE* file1 = fopen("Valid.txt", "a");
            if (file1) {
                fprintf(file1, "%s", valid_buffer.c_str());
                fclose(file1);
                valid_buffer.clear();
            }
        }
    }

    metalDeviceSynchronize();

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);

        SaveResultOld(OUT_FILE, Founds, save);
    }
Error:


    metalFree(_devIndexes1);
    metalFree(_devIndexes2);
    metalFree(_devLines1);
    metalFree(_devLines2);
    return metalStatus;
}

// processMetalOldSeq: runs the Metal workflow for old seq.
metalError_t processMetalOldSeq()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalOldSeq();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* start_pvk_dev;


    metalMalloc((void**)&start_pvk_dev, 512);

    uint64_t plus_size = 0;

    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();

        int result = cmp_host(start_mnemonic_point, end_mnemonic_point, 512);
        if (result > 0)
        {
            break;
        }

        metalStatus = metalMemcpyAsync(start_pvk_dev, start_mnemonic_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy start_pvk failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }

        metal_launch("workerOld_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, start_pvk_dev, min_len, 1, Rounds);
        metalStatus = metalGetLastError();
        counter += outputSizeB_T;
        counterTotal += outputSizeB_T;

        if (metalStatus != metalSuccess) {
            fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }



        metalStatus = metalDeviceSynchronize();
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
            goto Error;
        }
        //show status
        long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
        if (tHash > 2500) {
            counter = 0;
            beginCountHashrate = std::chrono::steady_clock::now();

            {
                FILE* fp = open_runtime_log("OldSeq_log.txt", "wb");
                if (fp)
                {
                    write_hex_last(fp, start_mnemonic_point, 512, (size_t)plus_size);
                }

                if (fp) fclose(fp);
            }

        }
        //check result 2
        if (read_result_flag_host(buffIsResult)) {
            clear_result_flag_host(buffIsResult);
            SaveResultOld(OUT_FILE, Founds, save);

        }


        uint64_t valLE[64];
        uint64_t valBE[64];

        array512_to_64x64_le(start_mnemonic_point, valLE);

        add64to4096_host(valLE, outputSizeB_T * step, valBE);

        array64x64_le_to512(valBE, start_mnemonic_point);
        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultOld(OUT_FILE, Founds, save);
    }
Error:


    metalFree(start_pvk_dev);
    return metalStatus;
}

