    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_mnemonic_point[512] = { 0 };
    uint8_t minus_mnemonic_point[512] = { 0 };

    init_seq_both_points(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    metalMalloc((void**)&plus_pvk_dev, 512);
    metalMalloc((void**)&minus_pvk_dev, 512);


    uint64_t valLE[64];
    uint64_t valBE[64];

    uint64_t plus_size = 0;
    uint64_t minus_size = 0;

    uint64_t local_n = 0;
    bool range_active = seq_both_round_active(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);

    while ((!use_n_count || local_n <= n_number) && range_active) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();

        metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_mnemonic_point, 512, metalMemcpyHostToDevice);
        metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_mnemonic_point, 512, metalMemcpyHostToDevice);
        if (metalStatus != metalSuccess) {
            fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
            goto Error;
        }
        for (size_t suz = 0; suz < Sizes.size(); ++suz)
        {
            int custom_size = Sizes[suz];



            for (size_t num = 0; num < Iterations.size(); ++num)
            {

                uint32_t ITERATION_HOST = Iterations[num];
                //+
                metal_launch("workerOldSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, plus_pvk_dev, min_len, 1, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds);
                metalStatus = metalGetLastError();
                counter += outputSizeB_T;
                counterTotal += outputSizeB_T;

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }

                metalStatus = metalDeviceSynchronize();
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultOldSeed(OUT_FILE, Founds, save);

                }
                metal_launch("workerOldSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, minus_pvk_dev, min_len, -1, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds);
                metalStatus = metalGetLastError();
                counter += outputSizeB_T;
                counterTotal += outputSizeB_T;

                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                    goto Error;
                }

                metalStatus = metalDeviceSynchronize();
                if (metalStatus != metalSuccess) {
                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                    goto Error;
                }


                //show status
                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                if (tHash > 2500) {
                    counter = 0;
                    beginCountHashrate = std::chrono::steady_clock::now();

                    {
                        FILE* fp = open_runtime_log("OldSeedSeqBoth_log.txt", "wb");
                        if (fp)
                        {
                            write_hex_last(fp, plus_mnemonic_point, 512, (size_t)plus_size);
                            write_hex_last(fp, minus_mnemonic_point, 512, (size_t)minus_size, true);
                        }

                        if (fp) fclose(fp);
                    }
                }
                //check result 2
                if (read_result_flag_host(buffIsResult)) {
                    clear_result_flag_host(buffIsResult);
                    SaveResultOldSeed(OUT_FILE, Founds, save);

                }
            }
        }
        array512_to_64x64_le(plus_mnemonic_point, valLE);
        add64to4096_host(valLE, outputSizeB_T * step, valBE);
        array64x64_le_to512(valBE, plus_mnemonic_point);

        plus_size = sizeBE_64(valBE, 64);
        if (plus_size < min_len)
        {
            plus_size = min_len;
        }

        array512_to_64x64_le(minus_mnemonic_point, valLE);
        sub64from4096_host(valLE, outputSizeB_T * step, valBE);
        array64x64_le_to512(valBE, minus_mnemonic_point);

        minus_size = sizeBE_64(valBE, 64);

        if (minus_size < min_len)
        {
            minus_size = min_len;
        }

        local_n += outputSizeB_T;
        range_active = seq_both_round_active(plus_mnemonic_point, minus_mnemonic_point, start_mnemonic_point, end_mnemonic_point, 512);
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultOldSeed(OUT_FILE, Founds, save);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

