    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);

    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;

    uint8_t start_pvk_point_local[512] = { 0 };

    if (seqMode)
    {
        random_bytes_seq(start_mnemonic_point, start_mnemonic_point, start_pvk_point_local, 512);
    }
    else
    {
        random_bytes(start_pvk_point_local, 512, entropy_len);
    }

    uint8_t* plus_pvk_dev;
    uint8_t* minus_pvk_dev;


    uint8_t plus_mnemonic_point[512] = { 0 };
    uint8_t minus_mnemonic_point[512] = { 0 };

    memcpy(&plus_mnemonic_point[0], &start_pvk_point_local[0], 512);
    memcpy(&minus_mnemonic_point[0], &start_pvk_point_local[0], 512);

    metalMalloc((void**)&plus_pvk_dev, 512);
    metalMalloc((void**)&minus_pvk_dev, 512);


    uint64_t valLE[64];
    uint64_t valBE[64];


    while (true) {
        std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();


        for (uint64_t local_n = 0; local_n <= n_number; local_n += outputSizeB_T)
        {
            metalStatus = metalMemcpyAsync(plus_pvk_dev, plus_mnemonic_point, 512, metalMemcpyHostToDevice);
            metalStatus = metalMemcpyAsync(minus_pvk_dev, minus_mnemonic_point, 512, metalMemcpyHostToDevice);
            if (metalStatus != metalSuccess) {
                fprintf(stderr, "metalMemcpy plus & minus points failed: %s\n", metalGetErrorString(metalStatus));
                goto Error;
            }
            for (size_t suz = 0; suz < Sizes.size(); ++suz)
            {
                int custom_size = Sizes[suz];

                for (size_t num = 0; num < Iterations.size(); ++num)
                {

                    uint32_t ITERATION_HOST = Iterations[num];
                    //+
                    metal_launch("workerOldSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, plus_pvk_dev, min_len, 1, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds);
                    metalStatus = metalGetLastError();
                    counter += outputSizeB_T;
                    counterTotal += outputSizeB_T;

                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel + launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    metalStatus = metalDeviceSynchronize();

                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResultOldSeed(OUT_FILE, Founds, save);

                    }
                    metal_launch("workerOldSeed_seq", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, minus_pvk_dev, min_len, -1, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds);
                    metalStatus = metalGetLastError();
                    counter += outputSizeB_T;
                    counterTotal += outputSizeB_T;

                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "kernel - launch failed: %s\n", metalGetErrorString(metalStatus));
                        goto Error;
                    }

                    metalStatus = metalDeviceSynchronize();
                    if (metalStatus != metalSuccess) {
                        fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                        goto Error;
                    }


                    //show status
                    long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                    if (tHash > 2500) {
                        counter = 0;
                        beginCountHashrate = std::chrono::steady_clock::now();

                    }
                    //check result 2
                    if (read_result_flag_host(buffIsResult)) {
                        clear_result_flag_host(buffIsResult);
                        SaveResultOldSeed(OUT_FILE, Founds, save);

                    }
                }
            }
            array512_to_64x64_le(plus_mnemonic_point, valLE);
            add64to4096_host(valLE, outputSizeB_T * step, valBE);
            array64x64_le_to512(valBE, plus_mnemonic_point);


            array512_to_64x64_le(minus_mnemonic_point, valLE);
            sub64from4096_host(valLE, outputSizeB_T * step, valBE);
            array64x64_le_to512(valBE, minus_mnemonic_point);

        }

        if (seqMode)
        {
            random_bytes_seq(start_mnemonic_point, end_mnemonic_point, start_pvk_point_local, 512);
        }
        else
        {
            random_bytes(start_pvk_point_local, 512, entropy_len);
        }
        memcpy(&plus_mnemonic_point[0], &start_pvk_point_local[0], 512);
        memcpy(&minus_mnemonic_point[0], &start_pvk_point_local[0], 512);
    }

    if (read_result_flag_host(buffIsResult)) {
        clear_result_flag_host(buffIsResult);
        SaveResultOldSeed(OUT_FILE, Founds, save);
    }
Error:


    metalFree(plus_pvk_dev);
    metalFree(minus_pvk_dev);
    return metalStatus;
}

// processMetalOldSeedGen: runs the Metal workflow for old seed gen.
metalError_t processMetalOldSeedGen()
{
    if (is_multi_gpu_active() && !g_disable_multi_gpu_dispatch) {
        return dispatch_generated_mode_multi_gpu(__func__, []() -> metalError_t {
            return processMetalOldSeedGen();
        });
    }
    metalError_t metalStatus;

    uint64_t outputSizeB_T = BLOCK_NUMBER * BLOCK_THREADS;

    bool* buffIsResult = nullptr;
    bool* buffDeviceResult = nullptr;
    metalStatus = acquire_shared_result_buffers(outputSizeB_T, &buffIsResult, &buffDeviceResult);


    std::chrono::steady_clock::time_point beginCountHashrate = std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point beginCountStatus = std::chrono::steady_clock::now();
    uint64_t counter = 0;
    for (uint64_t seed_local = isRandom ? random_seed32_inclusive(start_seed, end_seed) : start_seed; seed_local <= end_seed;) {


        uint64_t remaining = end_seed - seed_local + 1;
        uint64_t seed_count = (remaining < outputSizeB_T) ? remaining : outputSizeB_T;

        current_seed = seed_local;

        if (isLog)
        {
            std::ofstream ofs(effective_progress_log_path(), std::ios::app);
            if (!ofs.is_open()) {
                std::cerr << "Failed to open log file: " << log_file << "\n";
            }
            else {
                auto now = std::chrono::system_clock::now();
                std::time_t now_c = std::chrono::system_clock::to_time_t(now);

                std::tm tm_buf;
                localtime_r(&now_c, &tm_buf);

                ofs << std::put_time(&tm_buf, "%Y-%m-%d %H:%M:%S") << " SEED:" << " ";

                uint32_t lower32 = static_cast<uint32_t>(seed_local & 0xFFFFFFFFULL);

                ofs << std::hex << std::setw(8) << std::setfill('0') << lower32 << "\n";
            }
        }
        for (size_t entr_len = 0; entr_len < PrngBytes.size(); ++entr_len)
        {
            current_byte = PrngBytes[entr_len];

            for (size_t skip = 0; skip < PrngSkip.size(); ++skip) {
                metal_launch("SetSkipDev", 1, 1, PrngSkip[skip]);
                current_skip = PrngSkip[skip];

                for (size_t n = 0; n < Gens.size(); ++n)
                {
                    int gen_h = Gens[n];
                    current_gen = gen_h;
                    for (size_t i = 0; i < PrngModes.size(); ++i)
                    {
                        int mode_h = PrngModes[i];
                        if (!should_run_prng_combo(false, gen_h, mode_h)) continue;
                        current_mode = mode_h;


                        for (size_t suz = 0; suz < Sizes.size(); ++suz)
                        {
                            int custom_size = Sizes[suz];



                            for (size_t num = 0; num < Iterations.size(); ++num)
                            {

                                uint32_t ITERATION_HOST = Iterations[num];
                                std::chrono::steady_clock::time_point beginCountRead = std::chrono::steady_clock::now();

                                metal_launch("workerOldSeed_gen", BLOCK_NUMBER, BLOCK_THREADS, buffIsResult, buffDeviceResult, _dev_precomp, pitch, seed_local, seed_count, false, PrngBytes[entr_len], mode_h - 1, gen_h - 1, use_custom_size, custom_size, ENTROPY_MODE, ITERATION_HOST, Rounds);
                                metalStatus = metalGetLastError();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "kernel launch failed: %s\n", metalGetErrorString(metalStatus));
                                    goto Error;
                                }


                                counterTotal += seed_count;




                                metalStatus = metalDeviceSynchronize();
                                if (metalStatus != metalSuccess) {
                                    fprintf(stderr, "metalDeviceSynchronize returned error code %d after launching kernel!\n", metalStatus);
                                    goto Error;
                                }
                                //show status
                                long long tHash = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - beginCountHashrate).count();
                                if (tHash > 2500) {
                                    counter = 0;
                                    beginCountHashrate = std::chrono::steady_clock::now();
                                }
                                //check result 2
                                if (read_result_flag_host(buffIsResult)) {
                                    clear_result_flag_host(buffIsResult);
                                    SaveResultOldSeedGen(OUT_FILE, Founds, save, PrngBytes[entr_len], mode_h, gen_h, PrngSkip[skip]);
                                }
                            }
                        }

                    }
                }

            }
        }
        if (isRandom)
        {
            seed_local = random_seed32_inclusive(start_seed, end_seed);
        }
        else
        {
            seed_local += seed_count;
        }

    }
Error:

    return metalStatus;
}

