#include <deque>

void SpeedThreadFunc()
{
    using namespace std::chrono;

    uint64_t lastSeenKeys = counterTotal.load();
    uint64_t lastSeenMiniValid = counterMiniValid.load();
    uint64_t lastSeenWalletDatKdfIterations = counterWalletDatKdfIterations.load();

    bool baseInit = false;
    uint64_t baseKeys = 0;
    uint64_t baseMiniValid = 0;
    uint64_t baseWalletDatKdfIterations = 0;
    uint64_t baseWalletPasswordCandidates = 0;
    uint64_t basePausedNs = 0;
    steady_clock::time_point baseTime{};
    uint64_t kangarooEpoch =
        g_kangaroo_speed_epoch.load(std::memory_order_acquire);
    uint64_t kangarooBaseOperations = counterTotal.load();
    uint64_t kangarooLastPrintedOperations = kangarooBaseOperations;
    steady_clock::time_point kangarooBaseTime = steady_clock::now();
    steady_clock::time_point kangarooLastPrintTime = kangarooBaseTime;
    uint64_t bsgsEpoch =
        g_bsgs_speed_epoch.load(std::memory_order_acquire);
    uint64_t bsgsBaseOperations = counterTotal.load();
    uint64_t bsgsLastPrintedOperations = bsgsBaseOperations;
    steady_clock::time_point bsgsBaseTime = steady_clock::now();
    steady_clock::time_point bsgsLastPrintTime = bsgsBaseTime;
    modeinfra::ProgressSnapshot modeProgressBase =
        modeinfra::global_mode_progress().snapshot();
    uint64_t modeProgressEpoch = modeProgressBase.epoch;
    steady_clock::time_point modeProgressBaseTime = steady_clock::now();
    steady_clock::time_point modeProgressLastPrintTime =
        modeProgressBaseTime;
    uint64_t modeProgressLastCompleted =
        modeProgressBase.completed_candidates;

    while (isRun)
    {
        if (BSGS_MODE)
        {
            const auto nowTime = steady_clock::now();
            const uint64_t epoch =
                g_bsgs_speed_epoch.load(std::memory_order_acquire);
            const uint64_t totalOperations = counterTotal.load();
            if (epoch != bsgsEpoch)
            {
                bsgsEpoch = epoch;
                bsgsBaseOperations = totalOperations;
                bsgsLastPrintedOperations = totalOperations;
                bsgsBaseTime = nowTime;
                bsgsLastPrintTime = nowTime;
            }
            const double elapsed =
                duration_cast<duration<double>>(
                    nowTime - bsgsBaseTime).count();
            const double printElapsed =
                duration_cast<duration<double>>(
                    nowTime - bsgsLastPrintTime).count();
            if (printElapsed >= 1.0 &&
                totalOperations != bsgsLastPrintedOperations)
            {
                const uint64_t completed =
                    totalOperations >= bsgsBaseOperations
                    ? totalOperations - bsgsBaseOperations
                    : 0ull;
                if (completed > 0)
                {
                    const double operationSpeed =
                        static_cast<double>(completed) / elapsed;
                    const double coveredSpeed = operationSpeed *
                        g_bsgs_covered_scalars_per_operation.load(
                            std::memory_order_acquire);
                    printBsgsSpeed(operationSpeed, coveredSpeed);
                    bsgsLastPrintedOperations = totalOperations;
                    bsgsLastPrintTime = nowTime;
                }
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            continue;
        }
        if (KANGAROO_MODE)
        {
            const auto nowTime = steady_clock::now();
            const uint64_t epoch =
                g_kangaroo_speed_epoch.load(std::memory_order_acquire);
            const uint64_t totalOperations = counterTotal.load();
            if (epoch != kangarooEpoch)
            {
                kangarooEpoch = epoch;
                kangarooBaseOperations = totalOperations;
                kangarooLastPrintedOperations = totalOperations;
                kangarooBaseTime = nowTime;
                kangarooLastPrintTime = nowTime;
            }
            const double elapsed =
                duration_cast<duration<double>>(nowTime - kangarooBaseTime).count();
            const double printElapsed =
                duration_cast<duration<double>>(
                    nowTime - kangarooLastPrintTime).count();
            if (printElapsed >= 1.0 &&
                totalOperations != kangarooLastPrintedOperations)
            {
                const uint64_t completed =
                    totalOperations >= kangarooBaseOperations
                    ? totalOperations - kangarooBaseOperations
                    : 0ull;
                if (completed > 0)
                {
                    const double jumpSpeed =
                        static_cast<double>(completed) / elapsed;
                    const double equivalentSpeed = jumpSpeed *
                        g_kangaroo_equivalent_keys_per_jump.load(
                            std::memory_order_acquire);
                    printKangarooSpeed(jumpSpeed, equivalentSpeed);
                    kangarooLastPrintedOperations = totalOperations;
                    kangarooLastPrintTime = nowTime;
                }
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            continue;
        }
        const modeinfra::ProgressSnapshot modeProgress =
            modeinfra::global_mode_progress().snapshot();
        if (modeProgress.active)
        {
            const auto nowTime = steady_clock::now();
            if (modeProgress.epoch != modeProgressEpoch)
            {
                modeProgressEpoch = modeProgress.epoch;
                modeProgressBase = modeProgress;
                modeProgressBaseTime = nowTime;
                modeProgressLastPrintTime = nowTime;
                modeProgressLastCompleted =
                    modeProgress.completed_candidates;
            }
            const double printElapsed =
                duration_cast<duration<double>>(
                    nowTime - modeProgressLastPrintTime).count();
            if (printElapsed >= 1.0 &&
                modeProgress.completed_candidates !=
                    modeProgressLastCompleted)
            {
                const double elapsed =
                    duration_cast<duration<double>>(
                        nowTime - modeProgressBaseTime).count();
                const std::string line = modeinfra::format_progress_line(
                    modeProgressBase, modeProgress, elapsed);
                std::printf("%s           \r", line.c_str());
                std::fflush(stdout);
                modeProgressLastCompleted =
                    modeProgress.completed_candidates;
                modeProgressLastPrintTime = nowTime;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            continue;
        }

        const uint64_t totalKeys = counterTotal.load();
        const uint64_t totalMiniValid = counterMiniValid.load();
        const uint64_t totalWalletDatKdfIterations = counterWalletDatKdfIterations.load();
        const bool changed =
            (totalKeys != lastSeenKeys) ||
            (IS_MINIKEYS && totalMiniValid != lastSeenMiniValid) ||
            (WALLETDAT_MODE && totalWalletDatKdfIterations != lastSeenWalletDatKdfIterations);

        if (changed)
        {
            const auto nowTime = steady_clock::now();
            lastSeenKeys = totalKeys;
            lastSeenMiniValid = totalMiniValid;
            lastSeenWalletDatKdfIterations = totalWalletDatKdfIterations;

            if (!baseInit)
            {
                baseInit = true;
                baseKeys = totalKeys;
                baseMiniValid = totalMiniValid;
                baseWalletDatKdfIterations = counterWalletDatKdfIterations.load();
                baseWalletPasswordCandidates = counterWalletPasswordCandidates.load();
                basePausedNs = counterSpeedPausedNs.load();
                baseTime = nowTime;
            }
            else
            {
                const uint64_t doneKeys = totalKeys - baseKeys;
                const uint64_t doneMiniValid = totalMiniValid - baseMiniValid;
                const uint64_t pausedNs = counterSpeedPausedNs.load();
                const uint64_t pausedSinceBase = (pausedNs >= basePausedNs) ? (pausedNs - basePausedNs) : 0ull;

                double elapsed = duration_cast<duration<double>>(nowTime - baseTime).count();
                elapsed -= static_cast<double>(pausedSinceBase) / 1000000000.0;
                if (elapsed < 0.1)
                    elapsed = 0.1;

                const bool dualMinikeyStats = IS_MINIKEYS && !IS_MINIKEYS_SEED;
                const uint64_t doneWalletDatKdfIterations =
                    (totalWalletDatKdfIterations >= baseWalletDatKdfIterations)
                    ? (totalWalletDatKdfIterations - baseWalletDatKdfIterations)
                    : 0ull;
                if (doneKeys > 0 || (dualMinikeyStats && doneMiniValid > 0) ||
                    (WALLETDAT_MODE && doneWalletDatKdfIterations > 0))
                {
                    const double keys_per_sec = static_cast<double>(doneKeys) / elapsed;
                    if (dualMinikeyStats) {
                        const double valid_keys_per_sec = static_cast<double>(doneMiniValid) / elapsed;
                        printSpeed(keys_per_sec, 0, 0, 0, valid_keys_per_sec);
                    }
                    else {
                        double seed_resolve_speed = -1.0;
                        if (PROFANITY_MODE && RECOVERY_MODE) {
                            const uint64_t seedResolveCount = counterProfanitySeedResolve.load();
                            const uint64_t seedResolveNs = counterProfanitySeedResolveNs.load();
                            if (seedResolveCount > 0ull && seedResolveNs > 0ull) {
                                seed_resolve_speed = static_cast<double>(seedResolveCount) /
                                    (static_cast<double>(seedResolveNs) / 1000000000.0);
                            }
                        }
                        if (WALLETDAT_MODE) {
                            double kdf_iter_speed = -1.0;
                            if (doneWalletDatKdfIterations > 0ull) {
                                kdf_iter_speed = static_cast<double>(doneWalletDatKdfIterations) / elapsed;
                            }
                            const uint64_t walletPasswordCandidates = counterWalletPasswordCandidates.load();
                            double password_speed = -1.0;
                            if (walletPasswordCandidates >= baseWalletPasswordCandidates) {
                                password_speed = static_cast<double>(walletPasswordCandidates - baseWalletPasswordCandidates) / elapsed;
                            }
                            const uint64_t kdfWorkPerPassword = std::max<uint64_t>(1ull, counterWalletDatKdfWorkPerPassword.load());
                            if (doneWalletDatKdfIterations > 0ull) {
                                const double kdf_equivalent_password_speed =
                                    (static_cast<double>(doneWalletDatKdfIterations) / static_cast<double>(kdfWorkPerPassword)) / elapsed;
                                password_speed = std::max(password_speed, kdf_equivalent_password_speed);
                            }
                            printSpeed(keys_per_sec, 0, 0, 0, kdf_iter_speed, password_speed);
                        }
                        else if (ELECTRUMWALLET_MODE) {
                            const uint64_t walletPasswordCandidates = counterWalletPasswordCandidates.load();
                            double password_speed = -1.0;
                            if (walletPasswordCandidates >= baseWalletPasswordCandidates) {
                                password_speed = static_cast<double>(walletPasswordCandidates - baseWalletPasswordCandidates) / elapsed;
                            }
                            printSpeed(keys_per_sec, 0, 0, 0, seed_resolve_speed, password_speed);
                        }
                        else if (KEYSTORE_MODE || is_browserlike_wallet_mode() || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE) {
                            const uint64_t activeTargets = std::max<uint64_t>(1ull, counterWalletActiveTargets.load());
                            const double password_speed = keys_per_sec / static_cast<double>(activeTargets);
                            printSpeed(keys_per_sec, 0, 0, 0, seed_resolve_speed, password_speed);
                        }
                        else {
                            printSpeed(keys_per_sec, 0, 0, 0, seed_resolve_speed);
                        }
                    }
                }
            }
        }
        else
        {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }
}

static void printKangarooSpeed(double jump_speed,
                               double equivalent_key_speed)
{
    const unsigned long long total =
        static_cast<unsigned long long>(counterTotal.load());
    const std::string jumpSpeed =
        formatDouble("%.2f", jump_speed) + " Jump/s";
    const std::string equivalentSpeed =
        formatDouble("%.2f", equivalent_key_speed) + " EqKey/s";
    printf("[!] T:[%llu] | S:[%s] [%s] | F:[%i] [!]           \r",
           total,
           jumpSpeed.c_str(),
           equivalentSpeed.c_str(),
           static_cast<unsigned int>(
               g_kangaroo_founds.load(std::memory_order_acquire)));
    fflush(stdout);
}

static void printBsgsSpeed(double operation_speed,
                           double covered_scalar_speed)
{
    const uint32_t phase =
        g_bsgs_speed_phase.load(std::memory_order_acquire);
    const bool searchPhase = phase ==
        static_cast<uint32_t>(bsgs::SpeedPhase::Search);
    const char* phaseName = phase ==
        static_cast<uint32_t>(bsgs::SpeedPhase::TableBuild)
        ? "TABLE"
        : (phase == static_cast<uint32_t>(bsgs::SpeedPhase::CacheLoad)
            ? "CACHE" : "SEARCH");
    const char* operationUnit = searchPhase ? " GStep/s" : " Point/s";
    const char* equivalentUnit = searchPhase ? " EqKey/s" : " Scalar/s";
    const std::string operationSpeed =
        formatDouble("%.2f", operation_speed) + operationUnit;
    const std::string coveredSpeed =
        formatDouble("%.2f", covered_scalar_speed) + equivalentUnit;
    const uint64_t absoluteTotal = counterTotal.load();
    const uint64_t phaseStart =
        g_bsgs_phase_start_operations.load(std::memory_order_acquire);
    const unsigned long long total = static_cast<unsigned long long>(
        absoluteTotal >= phaseStart ? absoluteTotal - phaseStart : 0ull);
    const unsigned long long phaseTotal =
        static_cast<unsigned long long>(
            g_bsgs_phase_total.load(std::memory_order_acquire));
    if (searchPhase) {
        printf("[!] BSGS:%s T:[%llu/%llu] | S:[%s] [%s] | F:[%u/%u] [!]     \r",
               phaseName,
               total,
               phaseTotal,
               operationSpeed.c_str(),
               coveredSpeed.c_str(),
               g_bsgs_founds.load(std::memory_order_acquire),
               g_bsgs_total_targets.load(std::memory_order_acquire));
        fflush(stdout);
        return;
    }
    printf("[!] BSGS:%s T:[%llu/%llu] | S:[%s] [%s] | A:[%u] F:[%u] [!]     \r",
           phaseName,
           total,
           phaseTotal,
           operationSpeed.c_str(),
           coveredSpeed.c_str(),
           g_bsgs_active_targets.load(std::memory_order_acquire),
           g_bsgs_founds.load(std::memory_order_acquire));
    fflush(stdout);
}

// old_speed_hash_multiplier: calculates Hash/s multiplier for old Electrum modes.
static inline double old_speed_hash_multiplier() {
    const uint32_t old_deep = (deep == 0u) ? 20u : deep;
    return static_cast<double>(c_counter) * static_cast<double>(old_deep * 2u);
}

static inline uint32_t active_derivation_type_count_for_stats() {
    if (!g_bip_derivations_loaded || !has_generic_derivation_targets()) {
        return 1u;
    }
    uint32_t count = 0;
    if ((derivation_type_mask_host & DERIVATION_TYPE_MASK_BIP32) != 0u) ++count;
    if ((derivation_type_mask_host & DERIVATION_TYPE_MASK_SLIP0010) != 0u) ++count;
    if ((derivation_type_mask_host & DERIVATION_TYPE_MASK_BIP32_ED25519) != 0u) ++count;
    return count == 0u ? 1u : count;
}

static inline uint32_t substrate_suri_output_count_for_stats() {
    if (!Dot || g_substrate_paths_host.empty()) {
        return 0u;
    }
    uint32_t count = 0;
    for (const SubstratePathDevice& path : g_substrate_paths_host) {
        ++count; // sr25519 supports hard and soft junctions.
        bool ed25519_supported = true;
        for (uint32_t i = 0; i < path.junction_count; ++i) {
            if (path.junctions[i].is_hard == 0u) {
                ed25519_supported = false;
                break;
            }
        }
        if (ed25519_supported) {
            ++count;
        }
    }
    return count;
}

static inline bool direct_key_material_mode_for_stats() {
    return IS_PRIV || IS_MINIKEYS || POETRY_MODE || BRAIN;
}

static inline double current_hash_speed_multiplier() {
    const double target_count = static_cast<double>(c_counter + ((Ada && g_ada_pointer_set) ? 1 : 0));
    if (POETRY_MODE) {
        return target_count > 0.0 ? target_count : 1.0;
    }
    if (!g_bip_derivations_loaded && !direct_key_material_mode_for_stats() && !OLD && !ARMORY) {
        const uint32_t substrate_count = substrate_suri_output_count_for_stats();
        return substrate_count == 0u ? target_count : static_cast<double>(substrate_count);
    }

    double multiplier = target_count *
        static_cast<double>(derIndex_size) *
        static_cast<double>(active_derivation_type_count_for_stats());

    if (Dot && !g_substrate_paths_host.empty()) {
        multiplier += static_cast<double>(substrate_suri_output_count_for_stats());
    }
    return multiplier;
}

// printSpeed: prints speed.
void printSpeed(double speed, int byte_p, uint32_t seed_p, int skip, double valid_speed, double wallet_password_speed) {
    std::string speedStr;
    const unsigned long long totalCounter = static_cast<unsigned long long>(counterTotal.load());
    const unsigned long long falsePositiveCount = static_cast<unsigned long long>(false_positive.load(std::memory_order_relaxed));
    const int currentByte = current_byte.load(std::memory_order_relaxed);
    const int currentSkip = current_skip.load(std::memory_order_relaxed);
    const int currentGen = current_gen.load(std::memory_order_relaxed);
    const int currentMode = current_mode.load(std::memory_order_relaxed);
    const unsigned long long currentSeed = static_cast<unsigned long long>(current_seed.load(std::memory_order_relaxed));
    if (IS_MINIKEYS && !IS_MINIKEYS_SEED)
    {
        const unsigned long long validCounter = static_cast<unsigned long long>(counterMiniValid.load());
        const double valid_keys_per_sec = (valid_speed >= 0.0) ? valid_speed : 0.0;
        const double hash_mul = static_cast<double>((Rounds * 2ull) + 1ull) *
            current_hash_speed_multiplier();
        const std::string totalKeySpeed = formatDouble("%.2f", speed);
        const std::string validKeySpeed = formatDouble("%.2f", valid_keys_per_sec) + " Key/s";
        const std::string totalHashSpeed = formatDouble("%.2f", speed * hash_mul);
        const std::string validHashSpeed = formatDouble("%.2f", valid_keys_per_sec * hash_mul) + " Hash/s";

        printf("[!] T:[%llu|%llu] | S:[%s|%s] [%s|%s] | F:[%i] | F/P:[%llu] [!]           \r",
            totalCounter,
            validCounter,
            totalKeySpeed.c_str(),
            validKeySpeed.c_str(),
            totalHashSpeed.c_str(),
            validHashSpeed.c_str(),
            Founds,
            falsePositiveCount);
    }
    else if (IS_MINIKEYS)
    {
        const double hash_mul = static_cast<double>((Rounds * 2ull) + 1ull) *
            current_hash_speed_multiplier();
        const std::string keySpeed = formatDouble("%.2f", speed) + " Key/s";
        const std::string hashSpeed = formatDouble("%.2f", speed * hash_mul) + " Hash/s";
        printf("[!] T:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
            totalCounter,
            keySpeed.c_str(),
            hashSpeed.c_str(),
            Founds,
            falsePositiveCount);
    }
    else if (PROFANITY_MODE)
    {
        const int target_count = profanity_target_count();
        int recovery_filter_count = 0;
        if (RECOVERY_MODE) {
            if (useXor) recovery_filter_count += static_cast<int>(xorFiles.size());
            if (useXorUn) recovery_filter_count += static_cast<int>(xorFilesUn.size());
            if (useXorUc) recovery_filter_count += static_cast<int>(xorFilesUc.size());
            if (useXorHc) recovery_filter_count += static_cast<int>(xorFilesHc.size());
        }
        const double target_mul = RECOVERY_MODE
            ? 1.0
            : ((target_count > 0) ? static_cast<double>(target_count) : 1.0);
        const std::string pointSpeed = formatDouble("%.2f", speed) +
            (RECOVERY_MODE ? " Points/s" : " PointCheck/s");
        const std::string targetSpeed = formatDouble("%.2f", speed * target_mul) +
            (RECOVERY_MODE ? " Points/s" : " TargetCheck/s");
        if (RECOVERY_MODE) {
            const unsigned long long seedResolveCounter = static_cast<unsigned long long>(counterProfanitySeedResolve.load());
            const double seed_resolve_speed = (valid_speed >= 0.0) ? valid_speed : 0.0;
            const std::string seedResolveSpeed = formatDouble("%.2f", seed_resolve_speed) + " SeedResolve/s";
            printf("[!] T:[%llu] | SR:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                totalCounter,
                seedResolveCounter,
                pointSpeed.c_str(),
                seedResolveSpeed.c_str(),
                Founds,
                falsePositiveCount);
        }
        else {
            printf("[!] T:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                totalCounter,
                pointSpeed.c_str(),
                targetSpeed.c_str(),
                Founds,
                falsePositiveCount);
        }
    }
    else if (XP_MODE)
    {
        int target_count = 0;
        if (Compressed) ++target_count;
        if (Uncompressed) ++target_count;
        if (Segwit) ++target_count;
        if (P2wsh) ++target_count;
        if (Taproot) ++target_count;
        if (Xpoint) ++target_count;
        if (Ethereum) ++target_count;
        if (target_count <= 0) target_count = 1;
        const std::string keySpeed = formatDouble("%.2f", speed) + " Key/s";
        const std::string targetSpeed = formatDouble("%.2f", speed * static_cast<double>(target_count)) + " TargetCheck/s";
        printf("[!] T:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
            totalCounter,
            keySpeed.c_str(),
            targetSpeed.c_str(),
            Founds,
            falsePositiveCount);
    }
    else if (KEYSTORE_MODE || WALLETDAT_MODE || is_browserlike_wallet_mode() || ELECTRUMWALLET_MODE || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE)
    {
        const std::string checkSpeed = formatDouble("%.2f", speed) + " TargetCheck/s";
        if (WALLETDAT_MODE && valid_speed >= 0.0) {
            const std::string kdfSpeed = formatDouble("%.2f", valid_speed) + " KDFIter/s";
            const unsigned long long kdfCounter = static_cast<unsigned long long>(counterWalletDatKdfIterations.load());
            if (wallet_password_speed >= 0.0) {
                const unsigned long long passwordCounter = static_cast<unsigned long long>(counterWalletPasswordCandidates.load());
                const std::string passSpeed = formatDouble("%.2f", wallet_password_speed) + " Passwords/s";
                printf("[!] T:[%llu] | P:[%llu] | KDF:[%llu] | S:[%s] [%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                    totalCounter,
                    passwordCounter,
                    kdfCounter,
                    checkSpeed.c_str(),
                    passSpeed.c_str(),
                    kdfSpeed.c_str(),
                    Founds,
                    falsePositiveCount);
            }
            else {
                printf("[!] T:[%llu] | KDF:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                    totalCounter,
                    kdfCounter,
                    checkSpeed.c_str(),
                    kdfSpeed.c_str(),
                    Founds,
                    falsePositiveCount);
            }
        }
        else if (ELECTRUMWALLET_MODE && wallet_password_speed >= 0.0) {
            const unsigned long long passwordCounter = static_cast<unsigned long long>(counterWalletPasswordCandidates.load());
            const std::string passSpeed = formatDouble("%.2f", wallet_password_speed) + " Passwords/s";
            printf("[!] T:[%llu] | P:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                totalCounter,
                passwordCounter,
                checkSpeed.c_str(),
                passSpeed.c_str(),
                Founds,
                falsePositiveCount);
        }
        else if ((KEYSTORE_MODE || is_browserlike_wallet_mode() || EXODUSSECO_MODE || BITCOINJWALLET_MODE || ANDROIDWALLET_MODE || ARMORYWALLET_MODE) && wallet_password_speed >= 0.0) {
            const unsigned long long activeTargets = std::max<unsigned long long>(1ull,
                static_cast<unsigned long long>(counterWalletActiveTargets.load()));
            const unsigned long long passwordCounter = totalCounter / activeTargets;
            const std::string passSpeed = formatDouble("%.2f", wallet_password_speed) + " Passwords/s";
            printf("[!] T:[%llu] | P:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                totalCounter,
                passwordCounter,
                checkSpeed.c_str(),
                passSpeed.c_str(),
                Founds,
                falsePositiveCount);
        }
        else {
            printf("[!] T:[%llu] | S:[%s] | F:[%i] | F/P:[%llu] [!]           \r",
                totalCounter,
                checkSpeed.c_str(),
                Founds,
                falsePositiveCount);
        }
    }
    else if (WALLETJS_MODE)
    {
        const std::string candidateSpeed = formatDouble("%.2f", speed) + " Candidate/s";
        printf("[!] T:[%llu] | S:[%s] | F:[%i] | F/P:[%llu] [!]           \r",
            totalCounter,
            candidateSpeed.c_str(),
            Founds,
            falsePositiveCount);
    }
    else if (IS_PRIV || POETRY_MODE)
    {
        std::string speed_count = formatDouble("%.2f", speed * current_hash_speed_multiplier()) + " Hash/s";
        speedStr = formatDouble("%.2f", speed) + " Key/s";
        if (seqMode && seq_priv_use_step_schedule && !prng_gen && !prng64_gen)
        {
            const unsigned long long cur_step = static_cast<unsigned long long>(seq_priv_status_step.load(std::memory_order_relaxed));
            const unsigned long long cur_plus = static_cast<unsigned long long>(seq_priv_status_plus_step.load(std::memory_order_relaxed));
            printf("[!] T:[%llu] | Current Step:[%llx]|Plusstep:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r",
                totalCounter, cur_step, cur_plus, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
        else if (prng_gen)
        {
            printf("[!] T:[%llu] | Byte:[%i]|Gen:[%i]|mode:[%i]|shift:[%i]|seed:[%llx] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r", totalCounter, currentByte, currentGen, currentMode, currentSkip, currentSeed, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
        else if (prng64_gen)
        {
            printf("[!] T:[%llu] | Byte:[%i]|Gen:[%i]|mode:[%i]|shift:[%i]|seed:[%016llx] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r", totalCounter, currentByte, currentGen, currentMode, currentSkip, currentSeed, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
        else
        {
            printf("[!] T:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r", totalCounter, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
    }
    else
    {
        const double hash_mul = OLD
            ? old_speed_hash_multiplier()
            : current_hash_speed_multiplier();
        std::string speed_count = formatDouble("%.2f", speed * hash_mul) + " Hash/s";
        speedStr = formatDouble("%.2f", speed) + " Line/s";
        if (prng_gen)
        {
            printf("[!] T:[%llu] | Byte:[%i]|Gen:[%i]|mode:[%i]|shift:[%i]|seed:[%llx] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r", totalCounter, currentByte, currentGen, currentMode, currentSkip, currentSeed, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
        else if (prng64_gen)
        {
            printf("[!] T:[%llu] | Byte:[%i]|Gen:[%i]|mode:[%i]|shift:[%i]|seed:[%016llx] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r", totalCounter, currentByte, currentGen, currentMode, currentSkip, currentSeed, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
        else
        {
            printf("[!] T:[%llu] | S:[%s] [%s] | F:[%i] | F/P:[%llu] [!]           \r", totalCounter, speedStr.c_str(), speed_count.c_str(), Founds, falsePositiveCount);
        }
    }


    fflush(stdout);
}

// Loads bloom filter files into CPU RAM (called once, shared across all GPUs).
metalError_t MetalHashLookup::loadBloomFromFiles(const std::vector<string>& targets)
{
    if (targets.size() > 100) {
        std::cerr << "Too many bloom filters: " << targets.size() << " (max 100)" << std::endl;
        return metalErrorInvalidValue;
    }
    _bloomCount = 0;
    for (size_t i = 0; i < targets.size(); ++i) {
        init_log_fprintf(stderr, "[!] Initializing BF [size=%lu] [file=%s]\n",
            (unsigned long)BLOOM_SIZE, targets[i].c_str());

        if (strcmp(targets[i].c_str(), "full.blf") == 0) {
            _bloomHostData[i] = nullptr;  // nullptr signals "full.blf" to uploadBloomToGPU
            _bloomHostSize[i] = 0;
            _bloomCount++;
            continue;
        }

        try {
            _bloomHostData[i] = new uint8_t[BLOOM_SIZE];
        }
        catch (std::bad_alloc&) {
            return metalErrorMemoryAllocation;
        }
        _bloomHostSize[i] = BLOOM_SIZE;

        memset(_bloomHostData[i], 0, BLOOM_SIZE);
        FILE* file = fopen(targets[i].c_str(), "rb");
        if (file == nullptr) {
            delete[] _bloomHostData[i];
            _bloomHostData[i] = nullptr;
            _bloomHostSize[i] = 0;
            std::cerr << "Failed to open bloom file: " << targets[i] << std::endl;
            return metalErrorInvalidValue;
        }
        size_t bytesRead = fread(_bloomHostData[i], 1, BLOOM_SIZE, file);
        fclose(file);
        if (bytesRead != BLOOM_SIZE) {
            std::cerr << "Warning: bloom file '" << targets[i]
                << "' read " << bytesRead << " of " << BLOOM_SIZE << " bytes" << std::endl;
        }
        _bloomCount++;
    }
    return metalSuccess;
}

// Uploads CPU-cached bloom data to the currently active GPU.
metalError_t MetalHashLookup::uploadBloomToGPU()
{
    for (int i = 0; i < _bloomCount; ++i) {
        if (_bloomHostData[i] == nullptr) {
            // "full.blf" slot: activate FULL mode on this GPU
            metal_launch("setFULL", 1, 1);
            continue;
        }

        uint8_t* devPtr = nullptr;
        metalError_t err = metalMalloc(&devPtr, _bloomHostSize[i]);
        if (err) return err;

        err = metalMemcpy(devPtr, _bloomHostData[i], _bloomHostSize[i], metalMemcpyHostToDevice);
        if (err) { metalFree(devPtr); return err; }

        err = metalLoadBloomFilter(devPtr, i);
        if (err) { metalFree(devPtr); return err; }
        // devPtr is now referenced by this GPU's _BLOOM_FILTER constant; freed at GPU context teardown
    }
    return metalSuccess;
}

// Cache structures for XOR filter data (CPU-side, loaded once and reused per GPU).
struct XorFilterCache32 {
    std::string path;
    std::vector<uint32_t> fp;
    size_t size, arrayLength, segmentCount, segmentCountLength, segmentLength, segmentLengthMask;
};
struct XorFilterCache16 {
    std::string path;
    std::vector<uint16_t> fp;
    size_t size, arrayLength, segmentCount, segmentCountLength, segmentLength, segmentLengthMask;
};
struct XorFilterCache8 {
    std::string path;
    std::vector<uint8_t> fp;
    size_t size, arrayLength, segmentCount, segmentCountLength, segmentLength, segmentLengthMask;
};

enum class XorLoadFailureKind {
    none,
    open_failed,
    header_read_failed,
    invalid_header,
    alloc_failed,
    body_read_failed
};

struct XorLoadDiagnostics {
    const char* filter_kind = nullptr;
    std::string path;
    XorLoadFailureKind failure = XorLoadFailureKind::none;
    size_t fingerprint_bytes = 0;
    size_t size = 0;
    size_t arrayLength = 0;
    size_t segmentCount = 0;
    size_t segmentCountLength = 0;
    size_t segmentLength = 0;
    size_t segmentLengthMask = 0;
    size_t expected_body_bytes = 0;
    int error_code = 0;
};

static const char* xor_load_failure_kind_to_string(const XorLoadFailureKind kind) {
    switch (kind) {
    case XorLoadFailureKind::open_failed: return "open_failed";
    case XorLoadFailureKind::header_read_failed: return "header_read_failed";
    case XorLoadFailureKind::invalid_header: return "invalid_header";
    case XorLoadFailureKind::alloc_failed: return "alloc_failed";
    case XorLoadFailureKind::body_read_failed: return "body_read_failed";
    default: return "none";
    }
}


static FILE* open_binary_file_utf8_for_read(const std::string& path, XorLoadDiagnostics& diag) {
    return mac_open_binary_read(path, diag.error_code);
}

static void log_xor_load_failure(const XorLoadDiagnostics& diag) {
    std::ostringstream oss;
    oss << "[!] " << (diag.filter_kind ? diag.filter_kind : "Unknown")
        << " XOR filter load failed"
        << " [file=" << diag.path << "]"
        << " [failure=" << xor_load_failure_kind_to_string(diag.failure) << "]"
        << " [fingerprint=" << diag.fingerprint_bytes << "B]";

    if (diag.arrayLength != 0) {
        oss << " [arrayLength=" << diag.arrayLength << "]";
    }
    if (diag.expected_body_bytes != 0) {
        oss << " [body_bytes=" << diag.expected_body_bytes << "]";
    }
    if (diag.segmentCount != 0 || diag.segmentLength != 0) {
        oss << " [segmentCount=" << diag.segmentCount
            << "] [segmentLength=" << diag.segmentLength
            << "] [segmentMask=" << diag.segmentLengthMask << "]";
    }
    if (diag.error_code != 0) {
        oss << " [errno=" << diag.error_code << "]";
        const char* text = std::strerror(diag.error_code);
        if (text != nullptr) {
            oss << " [" << text << "]";
        }
    }
    std::cerr << oss.str() << std::endl;
}

template <typename FingerprintType, typename CacheEntry>
static bool load_xor_filter_cache_entry(const std::string& path, const char* filter_kind, CacheEntry& entry) {
    XorLoadDiagnostics diag;
    diag.filter_kind = filter_kind;
    diag.path = path;
    diag.fingerprint_bytes = sizeof(FingerprintType);

    FILE* file = open_binary_file_utf8_for_read(path, diag);
    if (file == nullptr) {
        diag.failure = XorLoadFailureKind::open_failed;
        log_xor_load_failure(diag);
        return false;
    }

    size_t size = 0;
    size_t arrayLength = 0;
    size_t segmentCount = 0;
    size_t segmentCountLength = 0;
    size_t segmentLength = 0;
    size_t segmentLengthMask = 0;

    const bool header_ok =
        std::fread(&size, sizeof(size), 1, file) == 1 &&
        std::fread(&arrayLength, sizeof(arrayLength), 1, file) == 1 &&
        std::fread(&segmentCount, sizeof(segmentCount), 1, file) == 1 &&
        std::fread(&segmentCountLength, sizeof(segmentCountLength), 1, file) == 1 &&
        std::fread(&segmentLength, sizeof(segmentLength), 1, file) == 1 &&
        std::fread(&segmentLengthMask, sizeof(segmentLengthMask), 1, file) == 1;

    diag.size = size;
    diag.arrayLength = arrayLength;
    diag.segmentCount = segmentCount;
    diag.segmentCountLength = segmentCountLength;
    diag.segmentLength = segmentLength;
    diag.segmentLengthMask = segmentLengthMask;

    if (!header_ok) {
        diag.failure = XorLoadFailureKind::header_read_failed;
        std::fclose(file);
        log_xor_load_failure(diag);
        return false;
    }

    if (arrayLength == 0 ||
        arrayLength > XOR_MAX_SIZE ||
        arrayLength > (std::numeric_limits<size_t>::max() / sizeof(FingerprintType))) {
        diag.failure = XorLoadFailureKind::invalid_header;
        std::fclose(file);
        log_xor_load_failure(diag);
        return false;
    }

    diag.expected_body_bytes = arrayLength * sizeof(FingerprintType);

    try {
        entry.fp.assign(arrayLength, FingerprintType{});
    }
    catch (const std::bad_alloc&) {
        diag.failure = XorLoadFailureKind::alloc_failed;
        std::fclose(file);
        log_xor_load_failure(diag);
        return false;
    }

    if (arrayLength > 0 &&
        std::fread(entry.fp.data(), sizeof(FingerprintType), arrayLength, file) != arrayLength) {
        diag.failure = XorLoadFailureKind::body_read_failed;
        entry.fp.clear();
        std::fclose(file);
        log_xor_load_failure(diag);
        return false;
    }

    std::fclose(file);

    entry.path = path;
    entry.size = size;
    entry.arrayLength = arrayLength;
    entry.segmentCount = segmentCount;
    entry.segmentCountLength = segmentCountLength;
    entry.segmentLength = segmentLength;
    entry.segmentLengthMask = segmentLengthMask;

    init_log_fprintf(stderr,
        "[!] Initializing %s XOR Filter [size=%zu] [host=%zu] [device=%zu] [fp=%zuB] [file=%s]\n",
        filter_kind,
        diag.expected_body_bytes,
        diag.expected_body_bytes,
        diag.expected_body_bytes,
        sizeof(FingerprintType),
        path.c_str());
    return true;
}

template <typename FingerprintType, typename CacheEntry, typename SymbolWriter>
static metalError_t upload_xor_cache_to_gpu(
    const std::vector<CacheEntry>& cache,
    const char* filter_kind,
    SymbolWriter&& write_symbol) {

    for (size_t i = 0; i < cache.size(); ++i) {
        const size_t device_bytes = sizeof(FingerprintType) * cache[i].arrayLength;
        FingerprintType* devPtr = nullptr;
        metalError_t err = metalMalloc(&devPtr, device_bytes);
        if (err != metalSuccess) {
            init_log_fprintf(stderr,
                "[!] %s XOR filter GPU upload failed [file=%s] [stage=metalMalloc] [device=%zu] [%s]\n",
                filter_kind, cache[i].path.c_str(), device_bytes, metalGetErrorString(err));
            return err;
        }
        err = metalMemcpy(devPtr, cache[i].fp.data(), device_bytes, metalMemcpyHostToDevice);
        if (err != metalSuccess) {
            init_log_fprintf(stderr,
                "[!] %s XOR filter GPU upload failed [file=%s] [stage=metalMemcpy] [device=%zu] [%s]\n",
                filter_kind, cache[i].path.c_str(), device_bytes, metalGetErrorString(err));
            metalFree(devPtr);
            return err;
        }
        err = write_symbol(devPtr, static_cast<int>(i), cache[i]);
        if (err != metalSuccess) {
            init_log_fprintf(stderr,
                "[!] %s XOR filter GPU upload failed [file=%s] [stage=metalLoadXorFilter] [device=%zu] [%s]\n",
                filter_kind, cache[i].path.c_str(), device_bytes, metalGetErrorString(err));
            metalFree(devPtr);
            return err;
        }
    }
    return metalSuccess;
}

// setTargetXorFilter: loads compressed XOR filter files once, uploads to each GPU.
metalError_t setTargetXorFilter(std::vector<std::string>& targets) {
    static std::mutex s_mutex;
    static std::vector<XorFilterCache32> s_cache;
    static bool s_loaded = false;

    {
        std::lock_guard<std::mutex> lock(s_mutex);
        if (!s_loaded) {
            s_cache.clear();
            for (size_t i = 0; i < targets.size(); ++i) {
                XorFilterCache32 entry;
                if (!load_xor_filter_cache_entry<uint32_t>(targets[i], "Compressed", entry)) {
                    s_cache.clear();
                    return metalErrorUnknown;
                }
                s_cache.push_back(std::move(entry));
            }
            s_loaded = true;
        }
    }

    return upload_xor_cache_to_gpu<uint32_t>(s_cache, "Compressed",
        [](uint32_t* devPtr, int index, const XorFilterCache32& entry) {
            return metalLoadCompressedXorFilter(devPtr, index, entry.size, entry.arrayLength, entry.segmentCount, entry.segmentCountLength, entry.segmentLength, entry.segmentLengthMask);
        });
}

