// MetalHashLookup::setTargets: loads bloom data once from files, then uploads to current GPU.
metalError_t MetalHashLookup::setTargets(const vector<string>& targets)
{
    {
        std::lock_guard<std::mutex> lock(_mutex);
        if (!_bloomFilesLoaded) {
            metalError_t err = loadBloomFromFiles(targets);
            if (err != metalSuccess) return err;
            _bloomFilesLoaded = true;
        }
    }
    return uploadBloomToGPU();
}

// MetalHashLookup::cleanup: releases CPU-side bloom filter buffers.
void MetalHashLookup::cleanup()
{
    for (int i = 0; i < 100; ++i) {
        delete[] _bloomHostData[i];
        _bloomHostData[i] = nullptr;
        _bloomHostSize[i] = 0;
    }
    _bloomCount = 0;
    _bloomFilesLoaded = false;
}
